node_version_meets_minimum() {
  command -v node &>/dev/null || return 1
  local version major minor patch
  version="$(node -v 2>/dev/null | sed 's/^v//' || true)"
  major="${version%%.*}"
  minor="${version#*.}"
  minor="${minor%%.*}"
  patch="${version#*.*.}"
  [[ "${major}" =~ ^[0-9]+$ && "${minor}" =~ ^[0-9]+$ && "${patch}" =~ ^[0-9]+$ ]] || return 1

  # Match the exact engine range published by the tested OpenClaw package.
  # Node 23 is intentionally unsupported; Node 22/24 also have patch floors.
  if (( major == 22 )); then
    (( minor > 22 || (minor == 22 && patch >= 3) ))
  elif (( major == 23 )); then
    return 1
  elif (( major == 24 )); then
    (( minor > 15 || (minor == 15 && patch >= 0) ))
  elif (( major >= 25 )); then
    (( major > 25 || minor > 9 || (minor == 9 && patch >= 0) ))
  else
    return 1
  fi
}

ensure_supported_node_runtime() {
  if node_version_meets_minimum; then
    ok "Node.js $(node --version 2>/dev/null || echo compatible) (OpenClaw-compatible; unchanged)"
    return 0
  fi

  info "Node.js $(node --version 2>/dev/null || echo missing) is outside ${OPENCLAW_NODE_ENGINE_RANGE}; converging the supported Node 22 lane first..."
  spin "Setting up Node.js ${PIN_NODE_MAJOR} repository" "curl -fsSL https://deb.nodesource.com/setup_${PIN_NODE_MAJOR}.x | bash -"
  spin "Installing compatible Node.js runtime" "apt-get update -qq && apt-get install -y -qq --allow-downgrades nodejs"
  node_version_meets_minimum \
    || fail "Node.js must satisfy ${OPENCLAW_NODE_ENGINE_RANGE} before Portal or OpenClaw package operations can run."
  ok "Node.js $(node --version 2>/dev/null || echo compatible) (OpenClaw-compatible)"
}

# ═══════════════════════════════════════════════════════════════
# Terminal styling
# ═══════════════════════════════════════════════════════════════

readonly RED='\033[0;31m'
readonly GREEN='\033[0;32m'
readonly YELLOW='\033[0;33m'
readonly BLUE='\033[0;34m'
readonly MAGENTA='\033[0;35m'
readonly CYAN='\033[0;36m'
readonly WHITE='\033[1;37m'
readonly BOLD='\033[1m'
readonly DIM='\033[2m'
readonly ITALIC='\033[3m'
readonly NC='\033[0m'

readonly BULLET='•'

ok()       { echo -e "  ${GREEN}✓${NC} $*"; }
warn()     { echo -e "  ${YELLOW}⚠${NC} $*"; }
info()     { echo -e "  ${DIM}→${NC} $*"; }
progress() { echo -e "  ${BLUE}${BULLET}${NC} $*"; }

# The Dashboard updater redirects this installer's stdout into a durable,
# root-only outer log that survives the Portal restart. Emit a small,
# allowlisted tab-separated protocol only when the fixed systemd wrapper has
# supplied a valid operation identity. These records are observability only;
# the signed transaction journal remains the recovery authority.
dashboard_update_progress() {
  local status="$1" percent="$2" phase="$3" label="$4" detail="${5:-}"
  local operation_id="${BRIDGESLLM_DASHBOARD_UPDATE_ID:-}"
  local helper="${DASHBOARD_UPDATE_PROGRESS_HELPER}"
  [[ "${UPDATE_MODE:-false}" == "true" \
    && "${operation_id}" =~ ^[a-f0-9]{32}$ ]] || return 0
  [[ "${status}" =~ ^(running|recovering|rolled_back|updated_with_errors|recovery_required)$ \
    && "${percent}" =~ ^[0-9]+$ \
    && "${phase}" =~ ^[a-z0-9][a-z0-9-]{0,47}$ ]] || return 0
  (( percent <= 99 )) || percent=99
  if (( percent < DASHBOARD_UPDATE_PROGRESS_PERCENT )); then
    percent="${DASHBOARD_UPDATE_PROGRESS_PERCENT}"
  fi
  label="${label//$'\t'/ }"
  label="${label//$'\r'/ }"
  label="${label//$'\n'/ }"
  detail="${detail//$'\t'/ }"
  detail="${detail//$'\r'/ }"
  detail="${detail//$'\n'/ }"
  label="${label:0:160}"
  detail="${detail:0:800}"
  [[ -n "${label}" ]] || label="Update in progress"
  DASHBOARD_UPDATE_PROGRESS_PERCENT="${percent}"
  DASHBOARD_UPDATE_PROGRESS_PHASE="${phase}"
  if [[ ! -f "${helper}" || -L "${helper}" ]] \
    || ! /usr/bin/python3 "${helper}" update \
      --operation-id "${operation_id}" \
      --status "${status}" \
      --percent "${percent}" \
      --phase "${phase}" \
      --label "${label}" \
      --detail "${detail}"; then
    # Progress is an observer, never recovery authority. A write failure is
    # visible through the outer unit reconciliation but must not perturb the
    # signed transaction or trigger rollback by itself.
    echo "  Progress observer could not persist phase ${phase}." >&2
  fi
}

fail() {
  # A failure inside failure handling must terminate immediately with one
  # line: no second banner, no second recovery attempt, and never the
  # unrelated OpenClaw pair rollback that a re-entered fail() used to reach.
  if [[ "${FAIL_TERMINAL_IN_PROGRESS:-false}" == "true" ]]; then
    echo -e "  ${RED}FATAL during failure handling: $1${NC}" >&2
    exit 1
  fi
  FAIL_TERMINAL_IN_PROGRESS=true
  DASHBOARD_UPDATE_FAILURE_MESSAGE="$1"
  DASHBOARD_UPDATE_FAILURE_PHASE="${DASHBOARD_UPDATE_PROGRESS_PHASE:-failure}"
  # fail() never returns; from here on nothing may re-trigger ERR handling.
  trap - ERR
  trap '' SIGINT TERM HUP
  set +e
  if [[ "${REPAIR_PROJECT_RUNTIME_IMAGE:-false}" == "true" ]]; then
    echo "" >&2
    echo -e "  ${RED}${BOLD}Project runtime image repair failed:${NC} $1" >&2
    [[ -f "${LOG_FILE}" ]] \
      && echo -e "  ${DIM}Log: ${LOG_FILE}${NC}" >&2
    exit 1
  fi
  if [[ "${DASHBOARD_UPDATE_PORTAL_COMMITTED:-false}" == "true" ]]; then
    dashboard_update_progress updated_with_errors \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${DASHBOARD_UPDATE_FAILURE_PHASE}" \
      "Portal updated; follow-up work failed" "$1"
  elif [[ "${UPDATE_RECOVERY_ARMED:-false}" == "true" ]]; then
    dashboard_update_progress recovering \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
      "Update stopped — checking recovery" "$1"
  else
    dashboard_update_progress running \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" failure \
      "Update stopped before completion" "$1"
  fi
  echo ""
  echo -e "  ${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
  echo -e "  ${RED}${BOLD}  ERROR${NC}  ${CYAN}${CURRENT_STEP}${NC}"
  echo ""
  echo -e "  ${WHITE}  $1${NC}"
  echo ""
  echo -e "  ${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
  echo ""
  if [[ -f "$LOG_FILE" ]]; then
    echo -e "  ${DIM}Log: ${LOG_FILE}${NC}"
    echo -e "  ${DIM}Last 5 lines:${NC}"
    tail -5 "$LOG_FILE" 2>/dev/null | sed 's/^/    /'
  fi
  echo ""
  if declare -F settle_openclaw_compatibility_hotfix_process >/dev/null 2>&1; then
    settle_openclaw_compatibility_hotfix_process \
      || warn "The OpenClaw compatibility patch process could not be proven stopped before recovery."
  fi
  local database_operation_settled=true
  if declare -F settle_active_update_database_operation >/dev/null 2>&1; then
    settle_active_update_database_operation || database_operation_settled=false
  fi
  if [[ "${database_operation_settled}" != "true" ]]; then
    warn "The active database operation could not be proven stopped. Recovery was not started; the Portal remains boot-fenced."
    dashboard_update_progress recovery_required \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${DASHBOARD_UPDATE_FAILURE_PHASE}" \
      "Automatic recovery needs attention" \
      "The active database operation could not be proven stopped. Do not start another update."
    exit 1
  fi
  local update_recovery_attempted=false
  local update_recovery_succeeded=false
  if [[ "${UPDATE_RECOVERY_ARMED:-false}" == "true" ]] && declare -F recover_interrupted_update >/dev/null 2>&1; then
    update_recovery_attempted=true
    UPDATE_RECOVERY_ARMED=false
    if ! recover_interrupted_update; then
      warn "Update recovery did not complete. Portal remains boot-fenced and recovery artifacts were preserved for the next installer run."
    else
      update_recovery_succeeded=true
    fi
  elif declare -F rollback_openclaw_tested_pair >/dev/null 2>&1; then
    rollback_openclaw_tested_pair || warn "The OpenClaw core/plugin pair needs manual recovery; see ${LOG_FILE}."
  fi
  local preserve_transaction_stage=false
  if declare -F update_transaction_state_path >/dev/null 2>&1; then
    local active_receipt="" cutover_receipt=""
    active_receipt="$(
      update_transaction_state_path "${UPDATE_ACTIVE_JOURNAL}" 2>/dev/null || true
    )"
    cutover_receipt="$(
      update_transaction_state_path "${UPDATE_CUTOVER_JOURNAL}" 2>/dev/null || true
    )"
    if [[ -n "${active_receipt}" \
      && ( -e "${active_receipt}" || -L "${active_receipt}" ) ]] \
      || [[ -n "${cutover_receipt}" \
        && ( -e "${cutover_receipt}" || -L "${cutover_receipt}" ) ]]; then
      preserve_transaction_stage=true
    fi
  fi
  if [[ "${preserve_transaction_stage}" == "false" \
    && "${UPDATE_TRANSACTION_ID:-}" =~ ^[a-f0-9]{32}$ ]] \
    && declare -F cleanup_prepared_update_project_runtime_tags \
      >/dev/null 2>&1; then
    local cleanup_policy=""
    if [[ "${SKIP_PROJECT_RUNTIMES:-false}" == "true" ]]; then
      cleanup_policy="${PROJECT_RUNTIME_DISABLED_POLICY}"
    elif [[ -n "${UPDATE_RELEASE_STAGE_DIR:-}" ]] \
      && declare -F prepared_update_project_runtime_cleanup_policy_from_stage \
        >/dev/null 2>&1; then
      cleanup_policy="$(
        prepared_update_project_runtime_cleanup_policy_from_stage \
          "${UPDATE_RELEASE_STAGE_DIR}" "${UPDATE_TRANSACTION_ID}" \
          2>/dev/null || true
      )"
    fi
    if ! cleanup_prepared_update_project_runtime_tags \
      "${UPDATE_TRANSACTION_ID}" "${cleanup_policy}" >/dev/null 2>&1; then
      preserve_transaction_stage=true
      warn "Prepared Project runtime tags could not be proven removed. The private update stage was preserved for exact cleanup on the next installer run."
    fi
  fi
  if [[ -n "${UPDATE_RELEASE_STAGE_DIR:-}" ]] \
    && "${preserve_transaction_stage}" == "false" \
    && declare -F cleanup_release_stage_dir >/dev/null 2>&1; then
    cleanup_release_stage_dir "${UPDATE_RELEASE_STAGE_DIR}" >/dev/null 2>&1 || true
    UPDATE_RELEASE_STAGE_DIR=""
  fi
  if [[ "${preserve_transaction_stage}" == "false" ]] \
    && declare -F release_update_disk_reserves >/dev/null 2>&1; then
    release_update_disk_reserves >/dev/null 2>&1 || true
  fi
  if [[ "${DASHBOARD_UPDATE_PORTAL_COMMITTED:-false}" == "true" ]]; then
    dashboard_update_progress updated_with_errors \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${DASHBOARD_UPDATE_FAILURE_PHASE}" \
      "Portal updated; follow-up work failed" \
      "${DASHBOARD_UPDATE_FAILURE_MESSAGE}"
  elif [[ "${update_recovery_attempted}" == "true" \
    && "${update_recovery_succeeded}" == "true" ]]; then
    dashboard_update_progress rolled_back \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" rolled-back \
      "Previous Portal restored" \
      "The update failed, and the previous Portal was restored and verified. ${DASHBOARD_UPDATE_FAILURE_MESSAGE}"
  elif [[ "${update_recovery_attempted}" == "true" ]]; then
    dashboard_update_progress recovery_required \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${DASHBOARD_UPDATE_FAILURE_PHASE}" \
      "Automatic recovery needs attention" \
      "Recovery did not complete. Do not start another update; review the root-only transaction journal and installer log."
  fi
  exit 1
}

draw_progress_bar() {
  local current=$1
  local total=$2
  local label="${3:-}"
  local bar_width=24
  local filled=$(( (current * bar_width) / total ))
  local empty=$(( bar_width - filled ))
  local pct=$(( (current * 100) / total ))

  local bar=""
  local i
  for ((i = 0; i < filled; i++)); do bar+="█"; done
  for ((i = 0; i < empty; i++)); do bar+="░"; done

  echo -e "  ${CYAN}│${NC} ${CYAN}[${bar}]${NC} ${DIM}${pct}%${NC}  ${DIM}·${NC} ${WHITE}${BOLD}${label}${NC} ${DIM}(${current}/${total})${NC}"
}

step_header() {
  CURRENT_STEP_NUM=$((CURRENT_STEP_NUM + 1))
  local label="$1"

  echo ""
  echo -e "  ${CYAN}┌────────────────────────────────────────────────────${NC}"
  draw_progress_bar "$CURRENT_STEP_NUM" "$TOTAL_STEPS" "$label"
  echo -e "  ${CYAN}└────────────────────────────────────────────────────${NC}"
}

banner() {
  clear 2>/dev/null || true
  echo ""
  echo -e "  ${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
  echo -e "  ${WHITE}${BOLD}  B R I D G E S  L L M   Portal${NC}"
  echo -e "  ${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
  echo -e "  ${DIM}Installer v${VERSION}${NC}"
}

print_kv() {
  # Print a key-value pair aligned nicely
  local key="$1" val="$2" color="${3:-$NC}"
  printf "  ${DIM}%-16s${NC} ${color}%s${NC}\n" "${key}" "${val}"
}

elapsed_since_start() {
  if [[ -n "$INSTALL_START_TIME" ]]; then
    local now
    now=$(date +%s)
    local diff=$((now - INSTALL_START_TIME))
    local mins=$((diff / 60))
    local secs=$((diff % 60))
    if ((mins > 0)); then
      echo "${mins}m ${secs}s"
    else
      echo "${secs}s"
    fi
  fi
}

# ═══════════════════════════════════════════════════════════════
# Utilities
# ═══════════════════════════════════════════════════════════════

command_needs_package_manager() {
  local cmd="$*"
  [[ "$cmd" =~ (^|[[:space:]])(apt-get|apt|dpkg)([[:space:]]|$) ]]
}

package_manager_lock_paths() {
  cat <<'EOF'
/var/lib/dpkg/lock-frontend
/var/lib/dpkg/lock
/var/lib/apt/lists/lock
/var/cache/apt/archives/lock
EOF
}

# Active package-manager processes — only ones that actually hold locks.
# Excludes passive daemons like unattended-upgrade-shutdown (--wait-for-signal)
# and packagekitd (idle), and our own detection processes.
package_manager_active_procs() {
  ps -eo pid=,comm=,args= 2>/dev/null | awk '
    # Skip our own detection processes (awk/grep/ps show the pattern text in args)
    $2 == "awk" || $2 == "grep" || $2 == "ps" || $2 == "bash" || $2 == "sh" { next }
    # Only match processes actively doing package work
    /apt-get|aptitude/ { print $2; next }
    /\/usr\/bin\/dpkg/ { print $2; next }
    /\/usr\/bin\/unattended-upgrade($| )/ { print "unattended-upgr"; next }
    /cloud-init.*apt/ { print "cloud-init"; next }
  ' | sort -u
}

package_manager_holder_name() {
  # First: check who actually holds the locks (most accurate)
  if command -v fuser &>/dev/null; then
    local lock holders_found=""
    while IFS= read -r lock; do
      [[ -e "$lock" ]] || continue
      local pids
      pids="$(fuser "$lock" 2>/dev/null | xargs 2>/dev/null || true)"
      if [[ -n "$pids" ]]; then
        for pid in $pids; do
          local name
          name="$(ps -p "$pid" -o comm= 2>/dev/null || echo "pid:$pid")"
          holders_found="${holders_found:+$holders_found, }${name}"
        done
      fi
    done < <(package_manager_lock_paths)
    if [[ -n "$holders_found" ]]; then
      echo "$holders_found"
      return
    fi
  fi

  # Fallback: active process names
  local procs
  procs="$(package_manager_active_procs | head -3)"
  if [[ -n "$procs" ]]; then
    echo "$procs" | paste -sd ', ' -
    return
  fi
  echo "system packages"
}

cloud_init_pending() {
  if command -v cloud-init &>/dev/null; then
    local status
    status="$(cloud-init status 2>/dev/null || true)"
    [[ "$status" != *"status: done"* ]]
  else
    pgrep -af 'cloud-init' >/dev/null 2>&1
  fi
}

package_manager_is_busy() {
  # Primary check: are any lock files actually held?
  if command -v fuser &>/dev/null; then
    local lock
    while IFS= read -r lock; do
      [[ -e "$lock" ]] || continue
      if fuser "$lock" >/dev/null 2>&1; then
        return 0
      fi
    done < <(package_manager_lock_paths)
  fi

  # Secondary check: are active package processes running?
  if package_manager_active_procs | grep -q .; then
    return 0
  fi

  return 1
}

safe_package_manager_repair() {
  $PACKAGE_MANAGER_REPAIR_ACTIVE && return 1
  PACKAGE_MANAGER_REPAIR_ACTIVE=true
  local rc=0
  {
    echo "[$(date -Is)] attempting safe package-manager recovery" >> "$LOG_FILE"
    DEBIAN_FRONTEND=noninteractive dpkg --configure -a >> "$LOG_FILE" 2>&1 || rc=$?
    if [[ $rc -eq 0 ]]; then
      DEBIAN_FRONTEND=noninteractive apt-get -f install -y >> "$LOG_FILE" 2>&1 || rc=$?
    fi
  }
  PACKAGE_MANAGER_REPAIR_ACTIVE=false
  return $rc
}

wait_for_package_manager_ready() {
  local reason="${1:-package manager work}"
  local timeout_seconds="${2:-$PACKAGE_MANAGER_LONG_WAIT_SECONDS}"
  local start_ts now elapsed holder last_notice=-1 tick=0
  start_ts=$(date +%s)

  if ! package_manager_is_busy; then
    return 0
  fi

  echo ""
  echo -e "  ${CYAN}┌────────────────────────────────────────────────────${NC}"
  if cloud_init_pending; then
    echo -e "  ${CYAN}│${NC}  ${YELLOW}⚠${NC}  ${WHITE}${BOLD}Fresh VPS — waiting for system updates${NC}"
    echo -e "  ${CYAN}│${NC}"
    echo -e "  ${CYAN}│${NC}  ${DIM}Your server is installing security patches. This is${NC}"
    echo -e "  ${CYAN}│${NC}  ${DIM}normal on a new VPS and usually takes 2–5 minutes.${NC}"
    echo -e "  ${CYAN}│${NC}  ${DIM}The installer will continue automatically.${NC}"
  else
    echo -e "  ${CYAN}│${NC}  ${YELLOW}⚠${NC}  ${WHITE}${BOLD}Waiting for package manager${NC}"
    echo -e "  ${CYAN}│${NC}"
    echo -e "  ${CYAN}│${NC}  ${DIM}Another package task is running.${NC}"
    echo -e "  ${CYAN}│${NC}  ${DIM}The installer will continue automatically.${NC}"
  fi
  echo -e "  ${CYAN}│${NC}"

  while package_manager_is_busy; do
    now=$(date +%s)
    elapsed=$(( now - start_ts ))
    holder="$(package_manager_holder_name)"

    if [[ -t 1 ]]; then
      # draw_pulse_bar does \r itself, prefix with box line
      local _pw=24 _pframes=('⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏')
      local _pf="${_pframes[$(( tick % ${#_pframes[@]} ))]}"
      local _pc=$(( _pw * 2 )) _pp=$(( tick % (_pw * 2) ))
      (( _pp >= _pw )) && _pp=$(( _pc - _pp ))
      local _pb="" _pi
      for ((_pi = 0; _pi < _pw; _pi++)); do
        local _pd=$(( _pi - _pp )); (( _pd < 0 )) && _pd=$(( -_pd ))
        if (( _pd == 0 )); then _pb+="█"; elif (( _pd == 1 )); then _pb+="▓"
        elif (( _pd == 2 )); then _pb+="▒"; else _pb+="░"; fi
      done
      printf "\r  ${CYAN}│${NC}  ${CYAN}${_pf}${NC} ${CYAN}[${_pb}]${NC} ${DIM}$(format_elapsed $elapsed) · ${holder}${NC}                    "
    elif (( elapsed / 30 != last_notice )); then
      echo -e "  ${CYAN}│${NC}  ${DIM}Still waiting ($(format_elapsed $elapsed)) — ${holder}${NC}"
      last_notice=$(( elapsed / 30 ))
    fi
    tick=$(( tick + 1 ))

    if (( elapsed >= timeout_seconds )); then
      if [[ -t 1 ]]; then printf "\r%-120s\r" ""; fi
      echo -e "  ${CYAN}│${NC}"
      echo -e "  ${CYAN}└────────────────────────────────────────────────────${NC}"
      warn "Package manager wait exceeded $((timeout_seconds / 60)) minutes. Checking for a safe recovery..."
      if package_manager_is_busy; then
        fail "Package manager is still actively busy (${holder}). First-boot updates may still be running. Wait a few more minutes and rerun: curl -fsSL https://bridgesllm.ai/install.sh | sudo bash"
      fi
      if safe_package_manager_repair; then
        ok "Recovered interrupted package manager state"
        return 0
      fi
      fail "Package manager appears stuck. Check ${LOG_FILE}, then run: dpkg --configure -a && apt-get -f install"
    fi

    sleep 0.2
  done

  if [[ -t 1 ]]; then printf "\r%-120s\r" ""; fi
  echo -e "  ${CYAN}│${NC}"
  echo -e "  ${CYAN}│${NC}  ${GREEN}✓${NC}  ${WHITE}Package manager ready${NC}"
  echo -e "  ${CYAN}└────────────────────────────────────────────────────${NC}"
  echo ""
}

run() {
  if $DRY_RUN; then
    echo "  [dry-run] $*" >> "$LOG_FILE" 2>&1
  else
    if ! $PACKAGE_MANAGER_REPAIR_ACTIVE && command_needs_package_manager "$*"; then
      wait_for_package_manager_ready "$CURRENT_STEP"
    fi
    bash -c "$*" >> "$LOG_FILE" 2>&1
  fi
}

telemetry_event() {
  local event="$1"
  case "${event}" in
    install_start|install_complete|deps_updated|update_complete) ;;
    *) return 0 ;;
  esac
  local os_name; os_name="$(lsb_release -si 2>/dev/null || echo unknown)"
  local os_ver; os_ver="$(lsb_release -sr 2>/dev/null || echo unknown)"
  os_name="$(printf '%s' "${os_name}" | LC_ALL=C tr -cd 'A-Za-z0-9._+ -' | cut -c1-64)"
  os_ver="$(printf '%s' "${os_ver}" | LC_ALL=C tr -cd 'A-Za-z0-9._+ -' | cut -c1-64)"
  [[ -n "${os_name}" ]] || os_name="unknown"
  [[ -n "${os_ver}" ]] || os_ver="unknown"
  local payload="{\"event\":\"${event}\",\"version\":\"${VERSION}\",\"os\":\"${os_name}\",\"osVersion\":\"${os_ver}\",\"installId\":\"${TELEMETRY_INSTALL_ID}\"}"
  curl -sf -X POST "https://bridgesllm.ai/api/telemetry/event" \
    -H 'Content-Type: application/json' \
    -d "${payload}" \
    >/dev/null 2>&1 &
}

load_existing_telemetry_install_id() {
  TELEMETRY_INSTALL_ID="$(read_env_value "${PORTAL_DIR}/backend/.env.production" "TELEMETRY_INSTALL_ID" 2>/dev/null || echo "")"
}

ensure_telemetry_install_id() {
  if [[ ! "${TELEMETRY_INSTALL_ID}" =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ ]]; then
    TELEMETRY_INSTALL_ID="$(cat /proc/sys/kernel/random/uuid 2>/dev/null || uuidgen 2>/dev/null || echo "")"
  fi
  [[ "${TELEMETRY_INSTALL_ID}" =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ ]] \
    || fail "Portal could not create its local telemetry install identifier."
}

ensure_build_tools() {
  if ! command -v make &>/dev/null || ! command -v g++ &>/dev/null; then
    spin "Installing build tools"       "apt-get install -y -qq build-essential python3 || { apt-get update -qq && apt-get install -y -qq build-essential python3; }"
  fi
}

verify_prisma_client_runtime() {
  local backend_dir="$1" check_label="${2:-prisma-runtime-check}"
  [[ -d "${backend_dir}" && ! -L "${backend_dir}" ]] || return 1
  (
    cd "${backend_dir}"
    node - "${check_label}" <<'NODE'
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const label = process.argv[2] || 'prisma-runtime-check';
const fail = (message) => {
  console.error(`[${label}] ${message}`);
  process.exit(1);
};
for (const name of [
  'PRISMA_CLIENT_ENGINE_TYPE',
  'PRISMA_QUERY_ENGINE_BINARY',
  'PRISMA_QUERY_ENGINE_LIBRARY',
  'PRISMA_CLIENT_GET_TIME',
  'NODE_PG_FORCE_NATIVE',
  'NODE_TLS_REJECT_UNAUTHORIZED',
  'PGUSER',
  'PGDATABASE',
  'PGPORT',
  'PGHOST',
  'PGPASSWORD',
  'PGBINARY',
  'PGOPTIONS',
  'PGSSLMODE',
  'PGSSLNEGOTIATION',
  'PGCLIENT_ENCODING',
  'PGREPLICATION',
  'PGAPPNAME',
  'PGCONNECT_TIMEOUT',
]) {
  if (Object.prototype.hasOwnProperty.call(process.env, name)) {
    fail(`installer environment contains forbidden Prisma engine override ${name}`);
  }
}
const readPackage = (name) => {
  const packagePath = path.join(
    process.cwd(),
    'node_modules',
    ...name.split('/'),
    'package.json',
  );
  const stat = fs.lstatSync(packagePath);
  if (
    !stat.isFile()
    || stat.isSymbolicLink()
    || stat.uid !== process.geteuid()
    || (stat.mode & 0o022) !== 0
  ) {
    fail(`unsafe installed package metadata for ${name}`);
  }
  const value = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
  if (value.name !== name) {
    fail(`installed package identity differs for ${name}`);
  }
  return { path: packagePath, value };
};
const assertSecureRegularFile = (filePath, minimumSize, maximumSize) => {
  const stat = fs.lstatSync(filePath);
  if (
    !stat.isFile()
    || stat.isSymbolicLink()
    || stat.uid !== process.geteuid()
    || (stat.mode & 0o022) !== 0
    || stat.size < minimumSize
    || stat.size > maximumSize
  ) {
    fail(`unsafe generated runtime file: ${path.basename(filePath)}`);
  }
  return stat;
};

const rootPackage = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const declared = rootPackage.dependencies || {};
const nodeModulesPath = path.join(process.cwd(), 'node_modules');
const nodeModulesStat = fs.lstatSync(nodeModulesPath);
if (
  !nodeModulesStat.isDirectory()
  || nodeModulesStat.isSymbolicLink()
  || nodeModulesStat.uid !== process.geteuid()
  || (nodeModulesStat.mode & 0o022) !== 0
) {
  fail('node_modules directory is unsafe');
}
const client = readPackage('@prisma/client');
const adapter = readPackage('@prisma/adapter-pg');
const prisma = readPackage('prisma');
const pg = readPackage('pg');
for (const [name, installed] of [
  ['@prisma/client', client.value.version],
  ['@prisma/adapter-pg', adapter.value.version],
  ['prisma', prisma.value.version],
  ['pg', pg.value.version],
]) {
  if (!/^\d+\.\d+\.\d+$/.test(declared[name] || '')) {
    fail(`${name} must have an exact declared version`);
  }
  if (declared[name] !== installed) {
    fail(`${name} declared and installed versions differ`);
  }
}
if (
  client.value.version !== adapter.value.version
  || client.value.version !== prisma.value.version
) {
  fail('Prisma client, adapter, and CLI versions must match exactly');
}

const generatedRoot = path.join(process.cwd(), 'node_modules', '.prisma', 'client');
const generatedRootStat = fs.lstatSync(generatedRoot);
if (
  !generatedRootStat.isDirectory()
  || generatedRootStat.isSymbolicLink()
  || generatedRootStat.uid !== process.geteuid()
  || (generatedRootStat.mode & 0o022) !== 0
) {
  fail('generated Prisma client directory is unsafe');
}

const generatedSchemaPath = path.join(generatedRoot, 'schema.prisma');
const generatedIndexPath = path.join(generatedRoot, 'index.js');
const generatedWasmPath = path.join(generatedRoot, 'query_compiler_bg.wasm');
const generatedCompilerWrapperPath = path.join(
  generatedRoot,
  'query_compiler_bg.js',
);
assertSecureRegularFile(generatedSchemaPath, 100, 8 * 1024 * 1024);
assertSecureRegularFile(generatedIndexPath, 1_000, 32 * 1024 * 1024);
assertSecureRegularFile(generatedWasmPath, 100_000, 64 * 1024 * 1024);
assertSecureRegularFile(generatedCompilerWrapperPath, 1_000, 4 * 1024 * 1024);

const generatedSchema = fs.readFileSync(generatedSchemaPath, 'utf8');
const clientGenerator = generatedSchema.match(/generator\s+client\s*\{([\s\S]*?)\}/);
if (
  !clientGenerator
  || !/provider\s*=\s*["']prisma-client-js["']/.test(clientGenerator[1])
  || !/engineType\s*=\s*["']client["']/.test(clientGenerator[1])
) {
  fail('generated Prisma schema is not the Rust-free client engine');
}

const generatedIndex = fs.readFileSync(generatedIndexPath, 'utf8');
if (!/["']engineType["']\s*:\s*["']client["']/.test(generatedIndex)) {
  fail('generated Prisma metadata does not attest engineType=client');
}

const forbiddenRuntime = /^(?:libquery_engine-|query-engine-)/;
const pendingGeneratedDirectories = [generatedRoot];
let generatedEntryCount = 0;
while (pendingGeneratedDirectories.length > 0) {
  const directory = pendingGeneratedDirectories.pop();
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    generatedEntryCount += 1;
    if (generatedEntryCount > 512) {
      fail('generated Prisma client contains too many runtime entries');
    }
    const entryPath = path.join(directory, entry.name);
    const entryStat = fs.lstatSync(entryPath);
    if (
      entryStat.isSymbolicLink()
      || entryStat.uid !== process.geteuid()
      || (entryStat.mode & 0o022) !== 0
    ) {
      fail(`generated Prisma client contains unsafe entry ${entry.name}`);
    }
    if (forbiddenRuntime.test(entry.name)) {
      fail(`generated Prisma client contains forbidden native runtime ${entry.name}`);
    }
    if (entry.isDirectory()) {
      pendingGeneratedDirectories.push(entryPath);
    } else if (!entry.isFile()) {
      fail(`generated Prisma client contains unsupported entry ${entry.name}`);
    }
  }
}

const wasmBytes = fs.readFileSync(generatedWasmPath);
if (!wasmBytes.subarray(0, 4).equals(Buffer.from([0x00, 0x61, 0x73, 0x6d]))) {
  fail('generated Prisma query compiler is not a WebAssembly module');
}
const clientRoot = path.dirname(client.path);
const compilerSourcePath = path.join(
  clientRoot,
  'runtime',
  'query_compiler_bg.postgresql.wasm-base64.js',
);
const compilerWrapperSourcePath = path.join(
  clientRoot,
  'runtime',
  'query_compiler_bg.postgresql.js',
);
assertSecureRegularFile(compilerSourcePath, 100_000, 64 * 1024 * 1024);
assertSecureRegularFile(compilerWrapperSourcePath, 1_000, 4 * 1024 * 1024);
if (
  !fs.readFileSync(generatedCompilerWrapperPath).equals(
    fs.readFileSync(compilerWrapperSourcePath),
  )
) {
  fail('generated Prisma compiler wrapper differs from the installed client package');
}
const compilerSource = require(compilerSourcePath);
if (typeof compilerSource.wasm !== 'string') {
  fail('installed Prisma client is missing the PostgreSQL compiler source');
}
const trustedWasmBytes = Buffer.from(compilerSource.wasm, 'base64');
if (!wasmBytes.equals(trustedWasmBytes)) {
  fail('generated Prisma compiler bytes differ from the installed client package');
}

for (const name of ['@prisma/client', '@prisma/adapter-pg', 'pg']) {
  require(name);
}
console.log(
  `[${label}] ok engine=client prisma=${client.value.version} pg=${pg.value.version} wasm_sha256=${crypto.createHash('sha256').update(wasmBytes).digest('hex')}`,
);
NODE
  )
}

install_backend_runtime_dependencies() {
  local backend_dir="${PORTAL_DIR}/backend"
  [[ -d "${backend_dir}" ]] || fail "Backend directory not found at ${backend_dir}"

  spin "Installing runtime dependencies" "cd '${backend_dir}' && npm ci --omit=dev --ignore-scripts 2>/dev/null || npm install --omit=dev --ignore-scripts"

  local repaired_native_modules=()

  if [[ -d "${backend_dir}/prebuilts/node-pty/prebuilds/linux-x64" ]]; then
    mkdir -p "${backend_dir}/node_modules/node-pty/prebuilds/linux-x64"
    cp -f "${backend_dir}/prebuilts/node-pty/prebuilds/linux-x64/pty.node" \
          "${backend_dir}/node_modules/node-pty/prebuilds/linux-x64/pty.node"
    ok "Using prebuilt node-pty binary"
  else
    ensure_build_tools
    spin "Building node-pty from source" "cd '${backend_dir}' && npm rebuild node-pty"
  fi

  local runtime_modules=(bcrypt sharp)
  local module
  for module in "${runtime_modules[@]}"; do
    if [[ -d "${backend_dir}/node_modules/${module}" ]]; then
      repaired_native_modules+=("${module}")
    fi
  done

  if (( ${#repaired_native_modules[@]} > 0 )); then
    spin "Repairing native runtime modules" "cd '${backend_dir}' && npm rebuild ${repaired_native_modules[*]}"
  fi

  progress "Generating database client..."
  if ! run_without_database_authority \
      bash -c 'cd "$1" && exec npx prisma generate' \
      bridgesllm-prisma-generate "${backend_dir}" \
      >> "${LOG_FILE}" 2>&1; then
    fail "Database client generation failed — check ${LOG_FILE}."
  fi

  if ! (cd "${backend_dir}" && node <<'NODE' >> "$LOG_FILE" 2>&1
const checks = [
  ['@prisma/client', () => require('@prisma/client')],
  ['@prisma/adapter-pg', () => require('@prisma/adapter-pg')],
  ['pg', () => require('pg')],
  ['bcrypt', () => require('bcrypt')],
  ['sharp', () => require('sharp')],
  ['node-pty', () => require('node-pty')],
];
for (const [name, load] of checks) {
  try {
    load();
    console.log(`[runtime-check] ok ${name}`);
  } catch (error) {
    console.error(`[runtime-check] failed ${name}: ${error && error.stack ? error.stack : error}`);
    process.exit(1);
  }
}
NODE
  ); then
    fail "Runtime dependency verification failed — check ${LOG_FILE}"
  fi
  if ! verify_prisma_client_runtime "${backend_dir}" runtime-prisma-check \
      >> "${LOG_FILE}" 2>&1; then
    fail "Rust-free database runtime verification failed — check ${LOG_FILE}"
  fi

  ok "Runtime dependencies verified"
}

prepare_staged_backend_runtime_dependencies() {
  local staged_portal="$1"
  local backend_dir="${staged_portal}/backend"
  [[ -d "${backend_dir}" && -f "${backend_dir}/package-lock.json" \
    && -f "${backend_dir}/package.json" ]] || return 1
  local required_tool
  for required_tool in npm make g++ python3; do
    command -v "${required_tool}" >/dev/null 2>&1 || {
      echo "staged dependency preparation missing required tool: ${required_tool}" \
        >> "${LOG_FILE}"
      return 1
    }
  done

  info "Preparing candidate dependencies before Portal downtime..."
  (
    cd "${backend_dir}"
    npm ci --omit=dev --ignore-scripts
  ) >> "${LOG_FILE}" 2>&1 || return 1

  if [[ -f "${backend_dir}/prebuilts/node-pty/prebuilds/linux-x64/pty.node" ]]; then
    install -D -m 0755 \
      "${backend_dir}/prebuilts/node-pty/prebuilds/linux-x64/pty.node" \
      "${backend_dir}/node_modules/node-pty/prebuilds/linux-x64/pty.node" \
      >> "${LOG_FILE}" 2>&1 || return 1
  else
    return 1
  fi

  (
    cd "${backend_dir}"
    npm rebuild bcrypt sharp
    run_without_database_authority npx prisma generate
    node <<'NODE'
const checks = [
  ['@prisma/client', () => require('@prisma/client')],
  ['@prisma/adapter-pg', () => require('@prisma/adapter-pg')],
  ['pg', () => require('pg')],
  ['bcrypt', () => require('bcrypt')],
  ['sharp', () => require('sharp')],
  ['node-pty', () => require('node-pty')],
];
for (const [name, load] of checks) {
  try {
    load();
  } catch (error) {
    console.error(`[candidate-runtime-check] failed ${name}: ${error && error.stack ? error.stack : error}`);
    process.exit(1);
  }
}
NODE
  ) >> "${LOG_FILE}" 2>&1 || return 1
  verify_prisma_client_runtime "${backend_dir}" candidate-prisma-check \
    >> "${LOG_FILE}" 2>&1 || return 1

  ok "Candidate dependencies prepared and verified"
}

pg_url_component() {
  local db_url="$1" component="$2"
  pg_url_uses_supported_prisma_adapter_options "${db_url}" || return 1
  printf '%s' "${db_url}" | python3 /dev/fd/3 "${component}" 3<<'PY2'
import re
import sys
from urllib.parse import unquote, urlsplit

raw = sys.stdin.read()
if (not raw or len(raw.encode("utf-8")) > 128000 or "#" in raw
        or re.search(r"%(?![0-9A-Fa-f]{2})", raw)
        or any(ord(char) < 32 or ord(char) == 127 for char in raw)):
    raise SystemExit(1)
try:
    parsed = urlsplit(raw)
    _, separator, host_part = parsed.netloc.rpartition("@")
    host = unquote(parsed.hostname or "", errors="strict")
    port_number = 5432 if parsed.port is None else parsed.port
    database = unquote((parsed.path or "").lstrip("/"), errors="strict")
    user = unquote(parsed.username or "", errors="strict")
    password = unquote(parsed.password or "", errors="strict")
    decoded_host_part = unquote(host_part, errors="strict")
    raw_port_suffix = (
        host_part[host_part.find("]") + 1:]
        if host_part.startswith("[")
        else f":{host_part.rsplit(':', 1)[1]}" if ":" in host_part else ""
    )
except (UnicodeDecodeError, ValueError):
    raise SystemExit(1)
identity_or_secret = {
    "password", "sslpassword", "passfile", "service", "servicefile",
    "host", "hostaddr", "port", "user", "dbname", "database",
}
for raw_pair in parsed.query.split("&") if parsed.query else ():
    if "+" in raw_pair:
        raise SystemExit(1)
    raw_key, pair_separator, raw_value = raw_pair.partition("=")
    if "=" in raw_value:
        raise SystemExit(1)
    try:
        key = unquote(raw_key, errors="strict").lower()
        value = unquote(raw_value, errors="strict")
    except UnicodeDecodeError:
        raise SystemExit(1)
    if (not pair_separator or not key or key in identity_or_secret
            or any(ord(char) < 32 or ord(char) == 127
                   for value_part in (key, value) for char in value_part)):
        raise SystemExit(1)
if (parsed.scheme not in {"postgres", "postgresql"} or parsed.fragment
        or re.search(r"%(?:23|24|26|2b|2c|2f|3a|3b|3d|3f|40)", parsed.path, re.I)
        or not parsed.path.startswith("/") or parsed.path.count("/") != 1
        or database in {".", ".."} or "/" in database
        or not separator or parsed.netloc.count("@") != 1
        or host_part.startswith("[") or not 1 <= port_number <= 65535
        or "," in decoded_host_part or "%" in host
        or "%" in (parsed.hostname or "")
        or (raw_port_suffix
            and not re.fullmatch(r":[1-9][0-9]*", raw_port_suffix))
        or re.search(r"[<>\\^|]", host)
        or host_part != host_part.lower() or not host.isascii()
        or any(char.isspace() for char in host)):
    raise SystemExit(1)
component = sys.argv[1]
values = {"host": host, "port": str(port_number), "database": database, "user": user, "password": password}
value = values.get(component, "")
if not value or any(ord(char) < 32 or ord(char) == 127 for char in value):
    raise SystemExit(1)
print(value)
PY2
}

pg_url_uses_public_schema() {
  local db_url="$1"
  printf '%s' "${db_url}" | python3 /dev/fd/3 3<<'PY2'
import re
import sys
from urllib.parse import unquote, urlsplit

raw = sys.stdin.read()
if (not raw or len(raw.encode("utf-8")) > 128000 or "#" in raw
        or re.search(r"%(?![0-9A-Fa-f]{2})", raw)
        or any(ord(char) < 32 or ord(char) == 127 for char in raw)):
    raise SystemExit(1)
try:
    parsed = urlsplit(raw)
except ValueError:
    raise SystemExit(1)
if re.search(r"%(?:23|24|26|2b|2c|2f|3a|3b|3d|3f|40)", parsed.path, re.I):
    raise SystemExit(1)
schemas = []
for raw_pair in parsed.query.split("&") if parsed.query else ():
    if "+" in raw_pair:
        raise SystemExit(1)
    raw_key, separator, raw_value = raw_pair.partition("=")
    if "=" in raw_value:
        raise SystemExit(1)
    try:
        key = unquote(raw_key, errors="strict").lower()
        value = unquote(raw_value, errors="strict")
    except UnicodeDecodeError:
        raise SystemExit(1)
    if (not separator or any(ord(char) < 32 or ord(char) == 127
            for char in value)):
        raise SystemExit(1)
    if key == "schema":
        schemas.append(value)
if len(schemas) > 1 or (schemas and schemas[0] != "public"):
    raise SystemExit(1)
PY2
}

pg_url_uses_supported_prisma_adapter_options() {
  local db_url="$1"
  printf '%s' "${db_url}" | python3 /dev/fd/3 3<<'PY2'
import os
import re
import sys
from urllib.parse import unquote, urlsplit

raw = sys.stdin.read()
if (not raw or len(raw.encode("utf-8")) > 128000 or "#" in raw
        or re.search(r"%(?![0-9A-Fa-f]{2})", raw)
        or any(ord(char) < 32 or ord(char) == 127 for char in raw)):
    raise SystemExit(1)
try:
    parsed = urlsplit(raw)
except ValueError:
    raise SystemExit(1)
if re.search(r"%(?:23|24|26|2b|2c|2f|3a|3b|3d|3f|40)", parsed.path, re.I):
    raise SystemExit(1)

security_relevant = {
    "schema", "connection_limit", "connect_timeout", "pool_timeout",
    "socket_timeout", "pgbouncer", "statement_cache_size",
    "max_idle_connection_lifetime", "max_connection_lifetime", "sslmode",
    "sslcert", "sslkey", "sslrootcert", "sslidentity", "sslpassword",
    "sslaccept", "channel_binding", "uselibpqcompat",
}
preserved = {
    "application_name", "fallback_application_name", "options",
    "client_encoding", "replication",
}
allowed = security_relevant | preserved
unsupported = {
    "sslcert", "sslkey", "sslidentity", "sslpassword", "sslaccept",
    "channel_binding", "uselibpqcompat"
}
seen = set()
values = {}
for raw_pair in parsed.query.split("&") if parsed.query else ():
    if "+" in raw_pair:
        raise SystemExit(1)
    raw_key, separator, raw_value = raw_pair.partition("=")
    if "=" in raw_value:
        raise SystemExit(1)
    try:
        key = unquote(raw_key, errors="strict")
        value = unquote(raw_value, errors="strict")
    except UnicodeDecodeError:
        raise SystemExit(1)
    if (not separator or any(ord(char) < 32 or ord(char) == 127
            for char in value)):
        raise SystemExit(1)
    normalized = key.lower()
    if normalized not in allowed:
        raise SystemExit(1)
    if key != normalized or normalized in seen:
        raise SystemExit(1)
    seen.add(normalized)
    if normalized in security_relevant:
        if normalized in unsupported:
            raise SystemExit(1)
        values[normalized] = value
if values.get("sslmode") == "prefer":
    raise SystemExit(1)
if "sslmode" in values and values["sslmode"] not in {
    "disable", "require", "verify-ca", "verify-full"
}:
    raise SystemExit(1)
if "sslmode" not in values and (parsed.hostname or "") not in {
    "localhost", "127.0.0.1", "::1"
}:
    raise SystemExit(1)
ssl_root_cert = values.get("sslrootcert")
if ssl_root_cert is not None and not os.path.isabs(ssl_root_cert):
    raise SystemExit(1)
if ssl_root_cert is not None and values.get("sslmode") not in {
    "require", "verify-ca", "verify-full"
}:
    raise SystemExit(1)
if values.get("sslmode") in {"verify-ca", "verify-full"} \
        and ssl_root_cert is None:
    raise SystemExit(1)

def bounded_integer(name, minimum, maximum, default):
    value = values.get(name)
    if value is None:
        return default
    if not re.fullmatch(r"[0-9]+", value):
        raise SystemExit(1)
    parsed_value = int(value)
    if not minimum <= parsed_value <= maximum:
        raise SystemExit(1)
    return parsed_value

bounded_integer("connection_limit", 1, 1000, None)
connect_timeout = bounded_integer("connect_timeout", 0, 86400, 5)
pool_timeout = bounded_integer("pool_timeout", 0, 86400, 10)
bounded_integer("socket_timeout", 0, 86400, None)
bounded_integer("max_idle_connection_lifetime", 0, 86400, None)
bounded_integer("max_connection_lifetime", 0, 86400, None)
bounded_integer("statement_cache_size", 0, 1000000, None)
if (("connect_timeout" in values or "pool_timeout" in values)
        and connect_timeout != pool_timeout):
    raise SystemExit(1)
if values.get("pgbouncer") not in {None, "true", "false"}:
    raise SystemExit(1)
schema = values.get("schema")
if schema is not None and (not schema or len(schema.encode("utf-8")) > 63
        or any(ord(char) < 32 or ord(char) == 127 for char in schema)):
    raise SystemExit(1)
for tls_path_name in ("sslrootcert",):
    tls_path = values.get(tls_path_name)
    if tls_path is not None and (not tls_path
            or any(ord(char) < 32 or ord(char) == 127 for char in tls_path)):
        raise SystemExit(1)
PY2
}

libpq_database_url() {
  local db_url="$1"
  pg_url_uses_supported_prisma_adapter_options "${db_url}" || return 1
  printf '%s' "${db_url}" | python3 /dev/fd/3 3<<'PY2'
import os
import re
import sys
from urllib.parse import unquote, urlsplit, urlunsplit

raw = sys.stdin.read()
if (not raw or len(raw.encode("utf-8")) > 128000 or "#" in raw
        or re.search(r"%(?![0-9A-Fa-f]{2})", raw)
        or any(ord(char) < 32 or ord(char) == 127 for char in raw)):
    raise SystemExit(1)
try:
    parsed = urlsplit(raw)
    credentials, separator, host_part = parsed.netloc.rpartition("@")
    username_raw = credentials.split(":", 1)[0] if separator else ""
    host = unquote(parsed.hostname or "", errors="strict")
    user = unquote(parsed.username or "", errors="strict")
    password = unquote(parsed.password or "", errors="strict")
    database = unquote((parsed.path or "").lstrip("/"), errors="strict")
    port = 5432 if parsed.port is None else parsed.port
    decoded_host_part = unquote(host_part, errors="strict")
    raw_port_suffix = (
        host_part[host_part.find("]") + 1:]
        if host_part.startswith("[")
        else f":{host_part.rsplit(':', 1)[1]}" if ":" in host_part else ""
    )
except (UnicodeDecodeError, ValueError):
    raise SystemExit(1)
if (parsed.scheme not in {"postgres", "postgresql"} or parsed.fragment
        or re.search(r"%(?:23|24|26|2b|2c|2f|3a|3b|3d|3f|40)", parsed.path, re.I)
        or not parsed.path.startswith("/") or parsed.path.count("/") != 1
        or database in {".", ".."} or "/" in database
        or not all((separator, username_raw, host, user, password, database))
        or parsed.netloc.count("@") != 1 or host_part.startswith("[")
        or not 1 <= port <= 65535 or "," in decoded_host_part
        or (raw_port_suffix
            and not re.fullmatch(r":[1-9][0-9]*", raw_port_suffix))
        or "%" in host or "%" in (parsed.hostname or "")
        or re.search(r"[<>\\^|]", host)
        or host_part != host_part.lower() or not host.isascii()
        or any(char.isspace() for char in host)
        or any(ord(char) < 32 or ord(char) == 127
               for value in (host, user, password, database) for char in value)):
    raise SystemExit(1)

# Prisma accepts ORM/pool options that libpq rejects as unknown URI
# parameters. Preserve every other query option (notably TLS/connectivity) and
# remove only the documented Prisma-only controls for psql/pg_dump postflight.
prisma_only = {
    "schema",
    "connection_limit",
    "pool_timeout",
    "pgbouncer",
    "statement_cache_size",
    "socket_timeout",
    "max_idle_connection_lifetime",
    "max_connection_lifetime",
}
preserved = {
    "connect_timeout", "sslmode", "sslrootcert", "application_name",
    "fallback_application_name", "options", "client_encoding", "replication",
}
allowed = prisma_only | preserved
identity_or_secret = {
    "password",
    "sslpassword",
    "passfile",
    "service",
    "servicefile",
    "host",
    "hostaddr",
    "port",
    "user",
    "dbname",
    "database",
}
query = []
security = {}
seen = set()
if parsed.query:
    for raw_pair in parsed.query.split("&"):
        if "+" in raw_pair:
            raise SystemExit(1)
        raw_key, pair_separator, raw_value = raw_pair.partition("=")
        if "=" in raw_value:
            raise SystemExit(1)
        try:
            decoded_key = unquote(raw_key, errors="strict")
            key = decoded_key.lower()
            decoded_value = unquote(raw_value, errors="strict")
        except UnicodeDecodeError:
            raise SystemExit(1)
        if (not pair_separator or not key
                or any(ord(char) < 32 or ord(char) == 127
                       for value_part in (key, decoded_value)
                       for char in value_part)):
            raise SystemExit(1)
        if key in identity_or_secret:
            raise SystemExit(1)
        if decoded_key != key or key not in allowed or key in seen:
            raise SystemExit(1)
        seen.add(key)
        if key in {"sslmode", "sslrootcert"}:
            security[key] = decoded_value
        if key not in prisma_only:
            query.append(raw_pair)

ssl_mode = security.get("sslmode")
ssl_root_cert = security.get("sslrootcert")
if ssl_mode is not None and ssl_mode not in {
    "disable", "require", "verify-ca", "verify-full"
}:
    raise SystemExit(1)
if ssl_root_cert is not None and (
    not ssl_root_cert
    or not os.path.isabs(ssl_root_cert)
    or any(ord(char) < 32 or ord(char) == 127 for char in ssl_root_cert)
):
    raise SystemExit(1)
if ssl_root_cert is not None and ssl_mode not in {
    "require", "verify-ca", "verify-full"
}:
    raise SystemExit(1)
if ssl_mode in {"verify-ca", "verify-full"} and ssl_root_cert is None:
    raise SystemExit(1)

# The postflight URI is passed to psql as an explicit --dbname argument, so it
# must never carry the password; credentials travel through a 0600 pgpass file
# instead. Keep the username (pgpass matching needs it) and the host/port.
netloc = f"{username_raw}@{host_part}"
print(urlunsplit((parsed.scheme, netloc, parsed.path, "&".join(query), "")))
PY2
}

update_pgpass_runner_python() {
  cat <<'PY2'
import os
import select
import ctypes
import re
import signal
import sys

try:
    parent_pid = int(sys.argv[1])
except (IndexError, ValueError):
    raise SystemExit(1)
libc = ctypes.CDLL(None, use_errno=True)
if libc.prctl(1, signal.SIGKILL, 0, 0, 0) != 0:
    raise SystemExit(1)
if os.getppid() != parent_pid:
    os.kill(os.getpid(), signal.SIGKILL)
from urllib.parse import unquote, urlsplit

raw_parts = []
raw_size = 0
while True:
    part = os.read(3, min(65536, 128001 - raw_size))
    if not part:
        break
    raw_parts.append(part)
    raw_size += len(part)
    if raw_size > 128000:
        raise SystemExit(1)
os.close(3)
raw_bytes = b"".join(raw_parts)
try:
    raw = raw_bytes.decode("utf-8")
except UnicodeDecodeError:
    raise SystemExit(1)
if raw.endswith("\n"):
    raw = raw[:-1]
if (not raw or len(raw.encode("utf-8")) > 128000 or "#" in raw
        or re.search(r"%(?![0-9A-Fa-f]{2})", raw)
        or any(ord(char) < 32 or ord(char) == 127 for char in raw)):
    raise SystemExit(1)
try:
    parsed = urlsplit(raw)
    _, separator, host_part = parsed.netloc.rpartition("@")
    host = unquote(parsed.hostname or "", errors="strict")
    port_number = 5432 if parsed.port is None else parsed.port
    database = unquote((parsed.path or "").lstrip("/"), errors="strict")
    user = unquote(parsed.username or "", errors="strict")
    password = unquote(parsed.password or "", errors="strict")
    decoded_host_part = unquote(host_part, errors="strict")
    raw_port_suffix = (
        host_part[host_part.find("]") + 1:]
        if host_part.startswith("[")
        else f":{host_part.rsplit(':', 1)[1]}" if ":" in host_part else ""
    )
except (UnicodeDecodeError, ValueError):
    raise SystemExit(1)
identity_or_secret = {
    "password", "sslpassword", "passfile", "service", "servicefile",
    "host", "hostaddr", "port", "user", "dbname", "database",
}
for raw_pair in parsed.query.split("&") if parsed.query else ():
    if "+" in raw_pair:
        raise SystemExit(1)
    raw_key, pair_separator, raw_value = raw_pair.partition("=")
    if "=" in raw_value:
        raise SystemExit(1)
    try:
        key = unquote(raw_key, errors="strict").lower()
        value = unquote(raw_value, errors="strict")
    except UnicodeDecodeError:
        raise SystemExit(1)
    if (not pair_separator or not key or key in identity_or_secret
            or any(ord(char) < 32 or ord(char) == 127
                   for value_part in (key, value) for char in value_part)):
        raise SystemExit(1)
if (parsed.scheme not in {"postgres", "postgresql"} or parsed.fragment
        or re.search(r"%(?:23|24|26|2b|2c|2f|3a|3b|3d|3f|40)", parsed.path, re.I)
        or not parsed.path.startswith("/") or parsed.path.count("/") != 1
        or database in {".", ".."} or "/" in database
        or not separator or parsed.netloc.count("@") != 1
        or host_part.startswith("[") or not 1 <= port_number <= 65535
        or "," in decoded_host_part or "%" in host
        or "%" in (parsed.hostname or "")
        or (raw_port_suffix
            and not re.fullmatch(r":[1-9][0-9]*", raw_port_suffix))
        or re.search(r"[<>\\^|]", host)
        or host_part != host_part.lower() or not host.isascii()
        or any(char.isspace() for char in host)):
    raise SystemExit(1)
port = str(port_number)
values = (host, port, database, user, password)
if not all(values) or any(ord(char) < 32 or ord(char) == 127 for value in values for char in value):
    raise SystemExit(1)
escape = lambda value: value.replace("\\", "\\\\").replace(":", "\\:")
try:
    fd = os.memfd_create("bridgesllm-pgpass", 0)
    os.fchmod(fd, 0o600)
    payload = (":".join(escape(value) for value in values) + "\n").encode()
    if os.write(fd, payload) != len(payload):
        raise OSError("short pgpass write")
    os.lseek(fd, 0, os.SEEK_SET)
    os.set_inheritable(fd, True)
except (AttributeError, OSError):
    raise SystemExit(1)
environment = os.environ.copy()
environment.pop("DATABASE_URL", None)
for key in tuple(environment):
    if key.startswith("PG") and key != "PGAPPNAME":
        environment.pop(key, None)
environment.pop("BRIDGESLLM_UPDATE_PGPASS_EXEC", None)
minimal = environment.pop("BRIDGESLLM_UPDATE_PGPASS_MINIMAL_ENV", "") == "1"
if minimal:
    environment = {
        "PATH": "/usr/bin:/bin",
        "LANG": "C",
        "LC_ALL": "C",
        **({"PGAPPNAME": os.environ["PGAPPNAME"]} if "PGAPPNAME" in os.environ else {}),
    }
environment["PGPASSFILE"] = f"/proc/self/fd/{fd}"
os.execvpe(sys.argv[2], sys.argv[2:], environment)
PY2
}

run_with_update_pgpass() {
  # Give one libpq operation an anonymous, inherited pgpass inode. There is
  # never a credential-bearing directory entry to survive SIGKILL: the memfd
  # exists only while this process tree has it open.
  local db_url="$1"
  shift
  [[ "$#" -gt 0 ]] || return 1
  pg_url_uses_supported_prisma_adapter_options "${db_url}" || return 1
  local runner_source
  runner_source="$(update_pgpass_runner_python)" || return 1
  local -a clean_environment=(
    env -u DATABASE_URL -u PGHOST -u PGHOSTADDR -u PGPORT
    -u PGDATABASE -u PGUSER -u PGPASSWORD -u PGPASSFILE
    -u PGSERVICE -u PGSERVICEFILE -u PGOPTIONS
    -u PGSSLMODE -u PGREQUIRESSL -u PGSSLCOMPRESSION
    -u PGSSLCERT -u PGSSLKEY -u PGSSLROOTCERT -u PGSSLCRL
    -u PGREQUIREPEER -u PGCHANNELBINDING -u PGTARGETSESSIONATTRS
    -u PGCONNECT_TIMEOUT -u PGCLIENTENCODING -u PGKRBSRVNAME
    -u PGGSSLIB -u PGSYSCONFDIR -u PGLOCALEDIR
  )
  if [[ "${BRIDGESLLM_UPDATE_PGPASS_EXEC:-0}" == "1" ]]; then
    local expected_parent="" current_runner_pid="${BASHPID}"
    expected_parent="$(
      awk '/^PPid:[[:space:]]/ { print $2; exit }' \
        "/proc/${current_runner_pid}/status" 2>/dev/null
    )"
    [[ "${expected_parent}" =~ ^[1-9][0-9]*$ ]] || return 1
    exec "${clean_environment[@]}" \
      python3 -c "${runner_source}" "${expected_parent}" "$@" \
        3< <(printf '%s' "${db_url}")
  else
    "${clean_environment[@]}" \
      python3 -c "${runner_source}" "${BASHPID}" "$@" \
        3< <(printf '%s' "${db_url}")
  fi
}

run_without_database_authority() {
  env -u DATABASE_URL -u PGHOST -u PGHOSTADDR -u PGPORT \
    -u PGDATABASE -u PGUSER -u PGPASSWORD -u PGPASSFILE \
    -u PGSERVICE -u PGSERVICEFILE -u PGOPTIONS -u PGAPPNAME \
    -u PGSSLMODE -u PGREQUIRESSL -u PGSSLCOMPRESSION \
    -u PGSSLCERT -u PGSSLKEY -u PGSSLROOTCERT -u PGSSLCRL \
    -u PGREQUIREPEER -u PGCHANNELBINDING -u PGTARGETSESSIONATTRS \
    -u PGCONNECT_TIMEOUT -u PGCLIENTENCODING -u PGKRBSRVNAME \
    -u PGGSSLIB -u PGSYSCONFDIR -u PGLOCALEDIR \
    "$@"
}

fsync_update_payload() {
  # Rollback payloads must survive a crash of the host, not just of the
  # installer: fsync the file itself and its parent directory entry.
  local target="$1"
  python3 - "${target}" <<'PY2'
import os
import sys

path = sys.argv[1]
fd = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
try:
    os.fsync(fd)
finally:
    os.close(fd)
parent = os.path.dirname(path) or "."
dfd = os.open(parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
try:
    os.fsync(dfd)
finally:
    os.close(dfd)
PY2
}

update_database_unsupported_globals_select_sql() {
  cat <<'SQL'
SELECT
  (SELECT count(*) FROM pg_publication) AS publication_count,
  (
    SELECT count(*)
    FROM pg_subscription
    WHERE subdbid = (
      SELECT oid FROM pg_database WHERE datname = current_database()
    )
  ) AS subscription_count,
  (SELECT count(*) FROM pg_cast WHERE oid >= 16384) AS user_cast_count,
  (SELECT count(*) FROM pg_transform WHERE oid >= 16384) AS user_transform_count,
  (SELECT count(*) FROM pg_am WHERE oid >= 16384) AS user_access_method_count,
  (SELECT count(*) FROM pg_event_trigger) AS event_trigger_count,
  (SELECT count(*) FROM pg_foreign_data_wrapper) AS fdw_count,
  (SELECT count(*) FROM pg_foreign_server) AS foreign_server_count,
  (
    SELECT count(*)
    FROM pg_language language
    WHERE language.lanispl
      AND NOT (
        language.oid < 16384
        AND language.lanname = 'plpgsql'
        AND language.lanpltrusted
        AND language.laninline <> 0
        AND language.lanvalidator <> 0
        AND EXISTS (
          SELECT 1
          FROM pg_depend dependency
          JOIN pg_extension extension
            ON extension.oid = dependency.refobjid
          WHERE dependency.classid = 'pg_language'::regclass
            AND dependency.objid = language.oid
            AND dependency.objsubid = 0
            AND dependency.refclassid = 'pg_extension'::regclass
            AND dependency.deptype = 'e'
            AND extension.extname = 'plpgsql'
        )
      )
  ) AS procedural_language_count
SQL
}

update_database_ownership_violations_sql() {
  cat <<'SQL'
SET search_path TO pg_catalog;
WITH public_schema AS (
  SELECT n.oid, n.nspacl, r.rolname AS owner_name
  FROM pg_namespace n
  JOIN pg_roles r ON r.oid = n.nspowner
  WHERE n.nspname = 'public'
),
public_acl AS (
  SELECT
    COALESCE(grantee.rolname, 'PUBLIC') AS grantee_name,
    grantor.rolname AS grantor_name,
    acl.privilege_type,
    acl.is_grantable
  FROM public_schema schema
  CROSS JOIN LATERAL aclexplode(schema.nspacl) acl
  LEFT JOIN pg_roles grantee ON grantee.oid = acl.grantee
  JOIN pg_roles grantor ON grantor.oid = acl.grantor
),
schema_contract AS (
  SELECT CASE
    WHEN (SELECT count(*) FROM public_schema) = 1
      AND (SELECT owner_name FROM public_schema) = current_user
      AND (SELECT nspacl FROM public_schema) IS NULL
    THEN 'owner-null'
    WHEN (SELECT count(*) FROM public_schema) = 1
      AND (SELECT owner_name FROM public_schema) = 'pg_database_owner'
      AND COALESCE((
        SELECT array_agg(
          concat_ws(
            '|',
            grantee_name,
            grantor_name,
            privilege_type,
            is_grantable::text
          )
          ORDER BY grantee_name, grantor_name, privilege_type, is_grantable
        )
        FROM public_acl
      ), ARRAY[]::text[]) = ARRAY[
        'PUBLIC|pg_database_owner|USAGE|false',
        'pg_database_owner|pg_database_owner|CREATE|false',
        'pg_database_owner|pg_database_owner|USAGE|false'
      ]::text[]
    THEN 'pg-database-owner-default'
    ELSE 'invalid'
  END AS variant
),
unsupported_globals AS (
SQL
  update_database_unsupported_globals_select_sql
  cat <<'SQL'
)
SELECT (
  (SELECT count(*) FROM pg_database d JOIN pg_roles r ON r.oid = d.datdba
     WHERE d.datname = current_database() AND r.rolname <> current_user)
+ (SELECT CASE WHEN variant = 'invalid' THEN 1 ELSE 0 END FROM schema_contract)
+ (SELECT count(*) FROM pg_namespace n
     WHERE n.nspname <> 'public'
       AND n.nspname <> 'information_schema'
       AND n.nspname !~ '^pg_')
+ (SELECT count(*) FROM pg_class c
     JOIN pg_namespace n ON n.oid = c.relnamespace
     JOIN pg_roles r ON r.oid = c.relowner
     WHERE n.nspname = 'public'
       AND (r.rolname <> current_user OR c.relacl IS NOT NULL))
+ (SELECT count(*) FROM pg_attribute a
     JOIN pg_class c ON c.oid = a.attrelid
     JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'public'
       AND a.attnum > 0 AND NOT a.attisdropped AND a.attacl IS NOT NULL)
+ (SELECT count(*) FROM pg_proc p
     JOIN pg_namespace n ON n.oid = p.pronamespace
     JOIN pg_roles r ON r.oid = p.proowner
     WHERE n.nspname = 'public'
       AND (r.rolname <> current_user OR p.proacl IS NOT NULL))
+ (SELECT count(*) FROM pg_type t
     JOIN pg_namespace n ON n.oid = t.typnamespace
     JOIN pg_roles r ON r.oid = t.typowner
     WHERE n.nspname = 'public'
       AND (r.rolname <> current_user OR t.typacl IS NOT NULL))
+ (SELECT count(*) FROM pg_collation c
     JOIN pg_namespace n ON n.oid = c.collnamespace
     JOIN pg_roles r ON r.oid = c.collowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_conversion c
     JOIN pg_namespace n ON n.oid = c.connamespace
     JOIN pg_roles r ON r.oid = c.conowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_operator o
     JOIN pg_namespace n ON n.oid = o.oprnamespace
     JOIN pg_roles r ON r.oid = o.oprowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_opclass o
     JOIN pg_namespace n ON n.oid = o.opcnamespace
     JOIN pg_roles r ON r.oid = o.opcowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_opfamily o
     JOIN pg_namespace n ON n.oid = o.opfnamespace
     JOIN pg_roles r ON r.oid = o.opfowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_ts_dict d
     JOIN pg_namespace n ON n.oid = d.dictnamespace
     JOIN pg_roles r ON r.oid = d.dictowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_ts_config c
     JOIN pg_namespace n ON n.oid = c.cfgnamespace
     JOIN pg_roles r ON r.oid = c.cfgowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_statistic_ext s
     JOIN pg_namespace n ON n.oid = s.stxnamespace
     JOIN pg_roles r ON r.oid = s.stxowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_extension e
     JOIN pg_namespace n ON n.oid = e.extnamespace
     JOIN pg_roles r ON r.oid = e.extowner
     WHERE n.nspname = 'public' AND r.rolname <> current_user)
+ (SELECT count(*) FROM pg_default_acl d
     LEFT JOIN pg_namespace n ON n.oid = d.defaclnamespace
     WHERE d.defaclnamespace = 0 OR n.nspname = 'public')
+ (SELECT count(*) FROM pg_largeobject_metadata)
+ (SELECT
   publication_count
     + subscription_count
     + user_cast_count
     + user_transform_count
     + user_access_method_count
     + event_trigger_count
     + fdw_count
     + foreign_server_count
     + procedural_language_count
   FROM unsupported_globals)
)::text || '|' || (SELECT variant FROM schema_contract);
SQL
}

update_database_size_bytes() {
  local db_url="$1"
  local connection_url size status=0
  connection_url="$(libpq_database_url "${db_url}")" || return 1
  size="$(run_with_update_pgpass "${db_url}" \
    psql --dbname="${connection_url}" --no-psqlrc \
    -v ON_ERROR_STOP=1 -qAt \
    -c "SET search_path TO pg_catalog; SELECT pg_catalog.pg_database_size(pg_catalog.current_database())" \
    2>> "${LOG_FILE}")" || status=$?
  [[ "${status}" -eq 0 ]] || return 1
  size="$(tr -d '[:space:]' <<<"${size}")"
  [[ "${size}" =~ ^[0-9]+$ ]] || return 1
  printf '%s\n' "${size}"
}

update_database_storage_sql() {
  # Only storage selected by this database is relevant. Cluster-wide
  # tablespaces can belong to unrelated databases and must not make a Portal
  # update reserve hundreds of gigabytes on unrelated filesystems.
  cat <<'SQL'
SET search_path TO pg_catalog;
WITH current_database_row AS (
  SELECT oid, dattablespace
  FROM pg_database
  WHERE datname = current_database()
),
used_tablespace_oids AS (
  SELECT dattablespace AS oid FROM current_database_row
  UNION
  SELECT reltablespace
  FROM pg_class
  WHERE reltablespace <> 0
  UNION
  SELECT oid
  FROM pg_tablespace
  WHERE spcname = NULLIF(current_setting('default_tablespace'), '')
)
SELECT json_build_object(
  'serverAddress', COALESCE(host(inet_server_addr()), ''),
  'serverPort', inet_server_port(),
  'backendPid', pg_backend_pid(),
  -- Settlement identity must come from inside the held session itself.
  -- application_name is spoofable through URI parameters (application_name=
  -- or options=-c...), so the settlement probe binds to pid + backend_start.
  'backendStart', (
    SELECT extract(epoch FROM backend_start)::text
    FROM pg_stat_activity
    WHERE pid = pg_backend_pid()
  ),
  'databaseName', current_database(),
  'databaseOid', (SELECT oid::bigint FROM current_database_row),
  -- Storage paths are host authority, not database-role authority. Ordinary
  -- database owners cannot read data_directory or arbitrary tablespace
  -- locations on PostgreSQL 16. The canonical proof derives those paths from
  -- the /proc-attested local postmaster and its pg_tblspc symlinks instead.
  'dataDirectory', '',
  'walDirectory', '',
  'defaultTablespace', current_setting('default_tablespace'),
  'defaultTablespaceOid', COALESCE(
    (
      SELECT oid::bigint
      FROM pg_tablespace
      WHERE spcname = NULLIF(current_setting('default_tablespace'), '')
    ),
    0
  ),
  'tempTablespaces', current_setting('temp_tablespaces'),
  'tablespaces', '[]'::json,
  'tablespaceOids', COALESCE(
    (SELECT json_agg(oid::bigint ORDER BY oid) FROM used_tablespace_oids),
    '[]'::json
  )
)::text;
SQL
}

update_database_storage_json() {
  # This low-level query is also exercised against real PostgreSQL in CI. The
  # canonical topology function below keeps the same backend alive long enough
  # to prove that the SQL session is a child of the observed local postmaster.
  local db_url="$1"
  local connection_url result status=0 operation_log="${LOG_FILE}"
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && -n "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT:-}" ]]; then
    operation_log="${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT}/database-topology.log"
  fi
  connection_url="$(libpq_database_url "${db_url}")" || return 1
  result="$(
    update_database_storage_sql \
      | run_with_update_pgpass "${db_url}" \
        psql --dbname="${connection_url}" --no-psqlrc \
        -v ON_ERROR_STOP=1 -qAt 2>> "${operation_log}"
  )" || status=$?
  [[ "${status}" -eq 0 && -n "${result}" && "${#result}" -le 65536 ]] \
    || return 1
  printf '%s\n' "${result}"
}

canonical_update_database_topology() {
  # Return one canonical JSON record that binds the exact PostgreSQL system,
  # database, listening endpoint, and every filesystem this database can use.
  # In production an interactive psql session remains open while /proc is
  # inspected, proving that the reported session belongs to the attested local
  # postmaster rather than trusting a loopback address alone. The client is
  # then released explicitly and its exact backend must disappear.
  local db_url="$1"
  local host port database user connection_url work_dir fifo output_file
  local proof_file app_name remaining=""
  local psql_pid="" psql_input_fd="" backend_pid="" raw="" proof_output=""
  local backend_identity="" backend_start=""
  local status=0 proof_status=0 settlement_status=0 source_only=false
  host="$(pg_url_component "${db_url}" host)" || return 1
  port="$(pg_url_component "${db_url}" port)" || return 1
  database="$(pg_url_component "${db_url}" database)" || return 1
  user="$(pg_url_component "${db_url}" user)" || return 1
  connection_url="$(libpq_database_url "${db_url}")" || return 1
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && -n "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT:-}" ]]; then
    source_only=true
  fi
  work_dir="$(mktemp -d "${TMPDIR:-/tmp}/blp-update-dbtopology.XXXXXX")" \
    || return 1
  chmod 0700 "${work_dir}"
  fifo="${work_dir}/topology.input"
  output_file="${work_dir}/topology.out"
  proof_file="${work_dir}/topology.proof"
  app_name="bridgesllm_a009_topology_${BASHPID}_${RANDOM}"

  if ${source_only}; then
    raw="$(update_database_storage_json "${db_url}")" || status=$?
  else
    mkfifo -m 0600 "${fifo}" || status=$?
    if [[ "${status}" -eq 0 ]]; then
      BRIDGESLLM_UPDATE_PGPASS_EXEC=1 \
        PGAPPNAME="${app_name}" \
        run_with_update_pgpass "${db_url}" stdbuf -oL psql \
          --dbname="${connection_url}" --no-psqlrc -q \
          -v ON_ERROR_STOP=1 -tA \
          < "${fifo}" \
          > "${output_file}" 2>> "${LOG_FILE}" &
      psql_pid=$!
      exec {psql_input_fd}>"${fifo}" || status=$?
    fi
    if [[ "${status}" -eq 0 ]]; then
      update_database_storage_sql >&"${psql_input_fd}" || status=$?
    fi
    if [[ "${status}" -eq 0 ]]; then
      local attempt
      for attempt in {1..100}; do
        raw="$(sed -n '1p' "${output_file}" 2>/dev/null || true)"
        [[ -n "${raw}" ]] && break
        kill -0 "${psql_pid}" 2>/dev/null || break
        sleep 0.05
      done
      [[ -n "${raw}" && "${#raw}" -le 65536 \
        && -n "${psql_pid}" && -d "/proc/${psql_pid}" ]] || status=1
      if [[ "${status}" -eq 0 ]]; then
        backend_identity="$(
          python3 - "${raw}" <<'PY2'
import json
import re
import sys

value = json.loads(sys.argv[1])
pid = value.get("backendPid")
start = value.get("backendStart")
if (
    isinstance(pid, bool)
    or not isinstance(pid, int)
    or pid <= 1
    or not isinstance(start, str)
    or re.fullmatch(r"[0-9]{1,20}(\.[0-9]{1,9})?", start) is None
):
    raise SystemExit(1)
print(pid)
print(start)
PY2
        )" || status=$?
        if [[ "${status}" -eq 0 ]]; then
          backend_pid="${backend_identity%%$'\n'*}"
          backend_start="${backend_identity#*$'\n'}"
          [[ -n "${backend_pid}" && -n "${backend_start}" \
            && "${backend_pid}" != "${backend_start}" ]] || status=1
        fi
      fi
    fi
  fi

  if [[ "${status}" -eq 0 ]]; then
    python3 - "${raw}" "${host}" "${port}" "${database}" \
      "${source_only}" "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT:-}" \
      > "${proof_file}" <<'PY2' \
      || proof_status=$?
import hashlib
import ipaddress
import json
import os
import posixpath
import re
import stat
import subprocess
import sys
import tempfile
import ctypes

raw, expected_host, expected_port, expected_database, source_only_text, test_root = (
    sys.argv[1:7]
)
source_only = source_only_text == "true"
try:
    observed = json.loads(raw)
except ValueError:
    raise SystemExit(1)
required = {
    "serverAddress",
    "serverPort",
    "backendPid",
    "backendStart",
    "databaseName",
    "databaseOid",
    "dataDirectory",
    "walDirectory",
    "defaultTablespace",
    "defaultTablespaceOid",
    "tempTablespaces",
    "tablespaces",
    "tablespaceOids",
}
if (
    not isinstance(observed, dict)
    or set(observed) != required
    or not isinstance(observed["serverAddress"], str)
    or isinstance(observed["serverPort"], bool)
    or not isinstance(observed["serverPort"], int)
    or isinstance(observed["backendPid"], bool)
    or not isinstance(observed["backendPid"], int)
    or not isinstance(observed["backendStart"], str)
    or re.fullmatch(
        r"[0-9]{1,20}(\.[0-9]{1,9})?", observed["backendStart"]
    ) is None
    or not isinstance(observed["databaseName"], str)
    or isinstance(observed["databaseOid"], bool)
    or not isinstance(observed["databaseOid"], int)
    or not isinstance(observed["dataDirectory"], str)
    or not isinstance(observed["walDirectory"], str)
    or not isinstance(observed["defaultTablespace"], str)
    or isinstance(observed["defaultTablespaceOid"], bool)
    or not isinstance(observed["defaultTablespaceOid"], int)
    or not isinstance(observed["tempTablespaces"], str)
    or not isinstance(observed["tablespaces"], list)
    or len(observed["tablespaces"]) > 32
    or not all(isinstance(path, str) for path in observed["tablespaces"])
    or not isinstance(observed["tablespaceOids"], list)
    or len(observed["tablespaceOids"]) > 32
    or not all(
        not isinstance(oid, bool) and isinstance(oid, int)
        for oid in observed["tablespaceOids"]
    )
):
    raise SystemExit(1)
try:
    address = ipaddress.ip_address(observed["serverAddress"])
except ValueError:
    raise SystemExit(1)
if (
    "/" in observed["serverAddress"]
    or not 1 <= observed["serverPort"] <= 65535
    or observed["databaseName"] != expected_database
    or not 1 <= observed["databaseOid"] <= 4_294_967_295
    or observed["backendPid"] <= 1
    or observed["tempTablespaces"].strip()
):
    raise SystemExit(1)
if source_only:
    host_address = address
    if (
        not address.is_loopback
        or observed["serverPort"] != int(expected_port)
    ):
        raise SystemExit(1)
else:
    try:
        host_address = ipaddress.ip_address(expected_host)
    except ValueError:
        raise SystemExit(1)
    if not host_address.is_loopback:
        raise SystemExit(1)
    if (
        observed["dataDirectory"]
        or observed["walDirectory"]
        or observed["tablespaces"]
    ):
        raise SystemExit(1)

tablespace_oids = []
for oid in observed["tablespaceOids"]:
    if not 1 <= oid <= 4_294_967_295:
        raise SystemExit(1)
    tablespace_oids.append(oid)
if (
    len(tablespace_oids) != len(set(tablespace_oids))
    or tablespace_oids != sorted(tablespace_oids)
    or (not source_only and not tablespace_oids)
):
    raise SystemExit(1)
default_tablespace = observed["defaultTablespace"].strip()
default_tablespace_oid = observed["defaultTablespaceOid"]
if (
    not 0 <= default_tablespace_oid <= 4_294_967_295
    or (
        not default_tablespace
        and default_tablespace_oid != 0
    )
    or (
        default_tablespace
        and (
            default_tablespace_oid == 0
            or default_tablespace_oid not in tablespace_oids
        )
    )
):
    raise SystemExit(1)


def safe_directory(path: str) -> str:
    if (
        not path
        or len(os.fsencode(path)) > 4096
        or not os.path.isabs(path)
        or any(ord(character) < 32 or ord(character) == 127 for character in path)
    ):
        raise SystemExit(1)
    resolved = os.path.realpath(path)
    if not os.path.isabs(resolved) or not os.path.isdir(resolved):
        raise SystemExit(1)
    details = os.stat(resolved)
    if not stat.S_ISDIR(details.st_mode) or details.st_mode & 0o022:
        raise SystemExit(1)
    if source_only:
        root = os.path.realpath(test_root)
        if not root or os.path.commonpath((root, resolved)) != root:
            raise SystemExit(1)
    elif details.st_uid == 0:
        raise SystemExit(1)
    return resolved


if source_only:
    data_directory = safe_directory(observed["dataDirectory"])
    wal_directory = safe_directory(observed["walDirectory"])
    tablespaces = sorted(
        {safe_directory(path) for path in observed["tablespaces"]}
    )
    data_details = os.stat(data_directory)
    system_identifier = os.environ.get(
        "BRIDGESLLM_UPDATE_TRANSACTION_TEST_DATABASE_SYSTEM_IDENTIFIER",
        "7612345678901234567",
    )
else:
    def process_identity(pid: int) -> dict:
        process_root = f"/proc/{pid}"
        details = os.stat(process_root)
        executable_path = os.path.join(process_root, "exe")
        executable = os.readlink(executable_path)
        executable_details = os.stat(executable_path)
        process_stat = open(
            os.path.join(process_root, "stat"), "r", encoding="ascii"
        ).read()
        suffix = process_stat.rsplit(")", 1)
        if len(suffix) != 2:
            raise SystemExit(1)
        fields = suffix[1].strip().split()
        if (
            len(fields) < 20
            or fields[0] in {"Z", "X", "x"}
            or not fields[1].isdigit()
            or not fields[19].isdigit()
            or not os.path.isabs(executable)
            or executable.endswith(" (deleted)")
            or any(ord(character) < 32 for character in executable)
        ):
            raise SystemExit(1)
        status = open(
            os.path.join(process_root, "status"), "r", encoding="ascii"
        ).read().splitlines()
        nspid_lines = [line for line in status if line.startswith("NSpid:")]
        if len(nspid_lines) != 1:
            raise SystemExit(1)
        nspids = nspid_lines[0].split()[1:]
        if not nspids or not all(value.isdigit() for value in nspids):
            raise SystemExit(1)
        namespaces = tuple(
            os.stat(os.path.join(process_root, "ns", name)).st_ino
            for name in ("pid", "mnt", "net")
        )
        return {
            "pid": pid,
            "details": details,
            "parentPid": int(fields[1]),
            "startTime": int(fields[19]),
            "executable": executable,
            "executableDevice": executable_details.st_dev,
            "executableInode": executable_details.st_ino,
            "namespacePids": tuple(int(value) for value in nspids),
            "namespaces": namespaces,
        }

    def same_postgres_process_pair(backend: dict, postmaster: dict) -> bool:
        return (
            backend["parentPid"] == postmaster["pid"]
            and backend["details"].st_uid == postmaster["details"].st_uid
            and backend["details"].st_gid == postmaster["details"].st_gid
            and postmaster["details"].st_uid != 0
            and backend["startTime"] > 0
            and postmaster["startTime"] > 0
            and backend["namespaces"] == postmaster["namespaces"]
            and os.path.basename(backend["executable"])
                in {"postgres", "postmaster"}
            and os.path.basename(postmaster["executable"])
                in {"postgres", "postmaster"}
            and (
                backend["executableDevice"],
                backend["executableInode"],
            ) == (
                postmaster["executableDevice"],
                postmaster["executableInode"],
            )
        )

    docker_records_cache = {"loaded": False, "records": []}

    def running_docker_records() -> list:
        if docker_records_cache["loaded"]:
            return docker_records_cache["records"]
        docker = "/usr/bin/docker"
        details = os.lstat(docker)
        if (
            not stat.S_ISREG(details.st_mode)
            or stat.S_ISLNK(details.st_mode)
            or details.st_uid != 0
            or details.st_mode & 0o022
            or not details.st_mode & 0o111
        ):
            raise SystemExit(1)
        listed = subprocess.run(
            [docker, "ps", "--quiet", "--no-trunc"],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            env={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
            text=True,
            timeout=10,
            check=False,
        )
        if listed.returncode != 0 or len(listed.stdout) > 16 * 1024:
            raise SystemExit(1)
        identifiers = [line.strip() for line in listed.stdout.splitlines()]
        if (
            len(identifiers) > 128
            or any(re.fullmatch(r"[a-f0-9]{64}", value) is None
                   for value in identifiers)
        ):
            raise SystemExit(1)
        if not identifiers:
            docker_records_cache["loaded"] = True
            return []
        inspected = subprocess.run(
            [docker, "inspect", *identifiers],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            env={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
            text=True,
            timeout=20,
            check=False,
        )
        if inspected.returncode != 0 or len(inspected.stdout) > 8 * 1024 * 1024:
            raise SystemExit(1)
        try:
            records = json.loads(inspected.stdout)
        except ValueError:
            raise SystemExit(1)
        if not isinstance(records, list) or len(records) != len(identifiers):
            raise SystemExit(1)
        docker_records_cache["loaded"] = True
        docker_records_cache["records"] = records
        return records

    def container_for_namespaces(namespaces: tuple) -> list:
        matches = []
        for record in running_docker_records():
            if not isinstance(record, dict):
                raise SystemExit(1)
            state = record.get("State")
            if not isinstance(state, dict):
                continue
            init_pid = state.get("Pid")
            if (
                state.get("Running") is not True
                or isinstance(init_pid, bool)
                or not isinstance(init_pid, int)
                or init_pid <= 1
            ):
                continue
            try:
                init_namespaces = tuple(
                    os.stat(f"/proc/{init_pid}/ns/{name}").st_ino
                    for name in ("pid", "mnt", "net")
                )
            except OSError:
                continue
            if init_namespaces == namespaces:
                matches.append(record)
        return matches

    self_namespaces = tuple(
        os.stat(f"/proc/self/ns/{name}").st_ino
        for name in ("pid", "mnt", "net")
    )
    candidates = []
    for entry in os.listdir("/proc"):
        if not entry.isdigit():
            continue
        try:
            backend = process_identity(int(entry))
        except (OSError, ValueError, SystemExit):
            continue
        if backend["namespacePids"][-1] != observed["backendPid"]:
            continue
        try:
            postmaster = process_identity(backend["parentPid"])
        except (OSError, ValueError, SystemExit):
            continue
        if not same_postgres_process_pair(backend, postmaster):
            continue

        container = None
        if backend["namespaces"] == self_namespaces:
            if (
                not address.is_loopback
                or address != host_address
                or observed["serverPort"] != int(expected_port)
            ):
                continue
        else:
            containers = container_for_namespaces(backend["namespaces"])
            if len(containers) != 1:
                continue
            container = containers[0]
            network = container.get("NetworkSettings")
            ports = network.get("Ports") if isinstance(network, dict) else None
            bindings = (
                ports.get(f'{observed["serverPort"]}/tcp')
                if isinstance(ports, dict)
                else None
            )
            if not isinstance(bindings, list) or len(bindings) != 1:
                continue
            exact_bindings = []
            for binding in bindings:
                if not isinstance(binding, dict):
                    continue
                try:
                    binding_address = ipaddress.ip_address(
                        binding.get("HostIp", "")
                    )
                    binding_port = int(binding.get("HostPort", ""))
                except (ValueError, TypeError):
                    continue
                if (
                    binding_address == host_address
                    and binding_address.is_loopback
                    and binding_port == int(expected_port)
                ):
                    exact_bindings.append(binding)
            networks = network.get("Networks")
            container_addresses = set()
            if isinstance(networks, dict):
                for value in networks.values():
                    if not isinstance(value, dict):
                        continue
                    for field in ("IPAddress", "GlobalIPv6Address"):
                        candidate_address = value.get(field)
                        if not candidate_address:
                            continue
                        try:
                            container_addresses.add(
                                ipaddress.ip_address(candidate_address)
                            )
                        except ValueError:
                            raise SystemExit(1)
            if len(exact_bindings) != 1 or address not in container_addresses:
                continue
        candidates.append((backend, postmaster, container))

    if len(candidates) != 1:
        raise SystemExit(1)
    backend, postmaster, container_record = candidates[0]
    backend_pid = backend["pid"]
    postmaster_pid = postmaster["pid"]
    backend_details = backend["details"]
    postmaster_details = postmaster["details"]
    backend_binary = backend["executable"]
    postmaster_binary = postmaster["executable"]
    backend_start_time = backend["startTime"]
    postmaster_start_time = postmaster["startTime"]

    def unsafe_writable_directory(mode: int) -> bool:
        # Group/other-writable ancestors let a local user replace a path
        # component, except when the sticky bit forbids renaming or deleting
        # entries owned by someone else (the official PostgreSQL images ship
        # /var/lib/postgresql as 1777, exactly like /tmp).
        return bool(mode & 0o022) and not mode & 0o1000

    def clean_namespace_path(path: str) -> str:
        if (
            not isinstance(path, str)
            or not path
            or len(os.fsencode(path)) > 4096
            or not posixpath.isabs(path)
            or any(ord(character) < 32 or ord(character) == 127
                   for character in path)
        ):
            raise SystemExit(1)
        normalized = posixpath.normpath(path)
        if normalized == "/" or not normalized.startswith("/"):
            raise SystemExit(1)
        return normalized

    namespace_root = f"/proc/{postmaster_pid}/root"

    def namespace_access_path(path: str) -> str:
        return namespace_root + clean_namespace_path(path)

    def resolve_namespace_directory(path: str):
        requested = clean_namespace_path(path)
        pending = requested.lstrip("/").split("/")
        current = "/"
        # The container root itself is an ancestor: if it is writable by an
        # unprivileged container user, root-owned top-level entries such as
        # /var can be replaced after proof. The trailing slash makes lstat
        # traverse the /proc/<pid>/root magic link to the directory.
        root_access_path = namespace_root + "/"
        root_details = os.lstat(root_access_path)
        if (
            not stat.S_ISDIR(root_details.st_mode)
            or unsafe_writable_directory(root_details.st_mode)
            or root_details.st_uid not in {0, postmaster_details.st_uid}
        ):
            raise SystemExit(1)
        chain = [
            (
                "directory",
                root_access_path,
                root_details.st_dev,
                root_details.st_ino,
                "",
                root_details.st_uid,
                root_details.st_gid,
                stat.S_IMODE(root_details.st_mode),
            )
        ]
        followed_links = 0
        while pending:
            component = pending.pop(0)
            candidate = posixpath.join(current, component)
            access_path = namespace_access_path(candidate)
            details = os.lstat(access_path)
            if stat.S_ISLNK(details.st_mode):
                if (
                    details.st_nlink != 1
                    or details.st_uid not in {0, postmaster_details.st_uid}
                ):
                    raise SystemExit(1)
                target = os.readlink(access_path)
                chain.append(
                    (
                        "symlink",
                        access_path,
                        details.st_dev,
                        details.st_ino,
                        target,
                        details.st_uid,
                        details.st_gid,
                        stat.S_IMODE(details.st_mode),
                    )
                )
                followed_links += 1
                if followed_links > 8:
                    raise SystemExit(1)
                unresolved = (
                    target
                    if posixpath.isabs(target)
                    else posixpath.join(posixpath.dirname(candidate), target)
                )
                if pending:
                    unresolved = posixpath.join(unresolved, *pending)
                resolved = clean_namespace_path(unresolved)
                pending = resolved.lstrip("/").split("/")
                current = "/"
                continue
            if (
                not stat.S_ISDIR(details.st_mode)
                or unsafe_writable_directory(details.st_mode)
                or details.st_uid not in {0, postmaster_details.st_uid}
            ):
                raise SystemExit(1)
            chain.append(
                (
                    "directory",
                    access_path,
                    details.st_dev,
                    details.st_ino,
                    "",
                    details.st_uid,
                    details.st_gid,
                    stat.S_IMODE(details.st_mode),
                )
            )
            current = candidate
        if current == "/":
            raise SystemExit(1)
        final_details = os.lstat(namespace_access_path(current))
        if not stat.S_ISDIR(final_details.st_mode):
            raise SystemExit(1)
        return current, final_details, tuple(chain)

    def recheck_namespace_chain(chain):
        for kind, access_path, device, inode, target, uid, gid, mode in chain:
            details = os.lstat(access_path)
            if (
                (
                    details.st_dev,
                    details.st_ino,
                    details.st_uid,
                    details.st_gid,
                    stat.S_IMODE(details.st_mode),
                ) != (device, inode, uid, gid, mode)
            ):
                raise SystemExit(1)
            if kind == "symlink":
                if (
                    not stat.S_ISLNK(details.st_mode)
                    or details.st_nlink != 1
                    or os.readlink(access_path) != target
                ):
                    raise SystemExit(1)
            elif kind == "directory":
                if (
                    not stat.S_ISDIR(details.st_mode)
                    or unsafe_writable_directory(details.st_mode)
                    or details.st_uid not in {0, postmaster_details.st_uid}
                ):
                    raise SystemExit(1)
            else:
                raise SystemExit(1)

    def capture_host_directory_chain(path: str, anchor: str = ""):
        if (
            not path
            or len(os.fsencode(path)) > 4096
            or not os.path.isabs(path)
            or any(ord(character) < 32 or ord(character) == 127
                   for character in path)
        ):
            raise SystemExit(1)
        resolved = os.path.realpath(path)
        if not os.path.isabs(resolved) or not os.path.isdir(resolved):
            raise SystemExit(1)
        if anchor:
            resolved_anchor = os.path.realpath(anchor)
            if (
                not os.path.isabs(resolved_anchor)
                or os.path.commonpath((resolved_anchor, resolved))
                    != resolved_anchor
            ):
                raise SystemExit(1)
        # The anchor only constrains containment. Ancestors are attested
        # from the filesystem root either way: a writable ancestor of a
        # Docker mount source lets a local user rename the source directory
        # out from under the recorded chain after proof.
        current = os.path.sep
        paths = [current]
        for component in resolved.split(os.sep)[1:]:
            if component in {"", ".", ".."}:
                raise SystemExit(1)
            current = os.path.join(current, component)
            paths.append(current)
        chain = []
        for component_path in paths:
            details = os.lstat(component_path)
            if (
                not stat.S_ISDIR(details.st_mode)
                or stat.S_ISLNK(details.st_mode)
                or unsafe_writable_directory(details.st_mode)
                or details.st_uid not in {0, postmaster_details.st_uid}
            ):
                raise SystemExit(1)
            chain.append(
                (
                    component_path,
                    details.st_dev,
                    details.st_ino,
                    details.st_uid,
                    details.st_gid,
                    stat.S_IMODE(details.st_mode),
                )
            )
        if chain[-1][3] != postmaster_details.st_uid:
            raise SystemExit(1)
        return resolved, tuple(chain)

    def recheck_host_chain(chain):
        for path, device, inode, uid, gid, mode in chain:
            details = os.lstat(path)
            if (
                not stat.S_ISDIR(details.st_mode)
                or stat.S_ISLNK(details.st_mode)
                or unsafe_writable_directory(details.st_mode)
                or (
                    details.st_dev,
                    details.st_ino,
                    details.st_uid,
                    details.st_gid,
                    stat.S_IMODE(details.st_mode),
                ) != (device, inode, uid, gid, mode)
            ):
                raise SystemExit(1)

    def safe_mount_source(path: str) -> str:
        if (
            not path
            or len(os.fsencode(path)) > 4096
            or not os.path.isabs(path)
            or any(ord(character) < 32 or ord(character) == 127
                   for character in path)
        ):
            raise SystemExit(1)
        resolved = os.path.realpath(path)
        if not os.path.isabs(resolved) or not os.path.isdir(resolved):
            raise SystemExit(1)
        details = os.stat(resolved)
        if (
            not stat.S_ISDIR(details.st_mode)
            or unsafe_writable_directory(details.st_mode)
            or details.st_uid not in {0, postmaster_details.st_uid}
        ):
            raise SystemExit(1)
        return resolved

    container_mounts = []
    if container_record is not None:
        raw_mounts = container_record.get("Mounts")
        if not isinstance(raw_mounts, list) or len(raw_mounts) > 128:
            raise SystemExit(1)
        for mount in raw_mounts:
            if not isinstance(mount, dict):
                raise SystemExit(1)
            if (
                mount.get("Type") not in {"bind", "volume"}
                or mount.get("RW") is not True
            ):
                continue
            source = mount.get("Source")
            destination = mount.get("Destination")
            if (
                not isinstance(source, str)
                or not os.path.isabs(source)
                or any(ord(character) < 32 or ord(character) == 127
                       for character in source)
            ):
                raise SystemExit(1)
            container_mounts.append(
                (clean_namespace_path(destination), source)
            )

    def persistent_directory(path: str):
        namespace_path, namespace_details, namespace_chain = (
            resolve_namespace_directory(path)
        )
        if container_record is None:
            host_path, host_chain = capture_host_directory_chain(
                namespace_path
            )
        else:
            matches = []
            for destination, source in container_mounts:
                if (
                    namespace_path == destination
                    or namespace_path.startswith(destination + "/")
                ):
                    relative = posixpath.relpath(namespace_path, destination)
                    matches.append(
                        (
                            len(destination),
                            source,
                            relative,
                        )
                    )
            if not matches:
                raise SystemExit(1)
            matches.sort(key=lambda value: value[0], reverse=True)
            if len(matches) > 1 and matches[0][0] == matches[1][0]:
                raise SystemExit(1)
            _, selected_source, selected_relative = matches[0]
            mount_root = safe_mount_source(selected_source)
            selected_path = (
                mount_root
                if selected_relative == "."
                else os.path.join(
                    mount_root, *selected_relative.split("/")
                )
            )
            host_path, host_chain = capture_host_directory_chain(
                selected_path, mount_root
            )
        host_details = os.lstat(host_path)
        if (
            host_details.st_dev != namespace_details.st_dev
            or host_details.st_ino != namespace_details.st_ino
        ):
            raise SystemExit(1)
        return namespace_path, host_path, namespace_chain, host_chain

    # The backend is held by the open interactive client while this proof
    # runs. Its exact host
    # parent is the live local postmaster. The cwd is interpreted inside that
    # process's mount namespace and, for Docker, mapped only through the exact
    # inspected persistent bind/volume mount.
    namespace_data_directory = clean_namespace_path(
        os.readlink(f"/proc/{postmaster_pid}/cwd")
    )
    data_requested_path = namespace_data_directory
    (
        namespace_data_directory,
        data_directory,
        data_chain,
        data_host_chain,
    ) = (
        persistent_directory(data_requested_path)
    )
    wal_requested_path = posixpath.join(
        namespace_data_directory, "pg_wal"
    )
    (
        namespace_wal_directory,
        wal_directory,
        wal_chain,
        wal_host_chain,
    ) = (
        persistent_directory(wal_requested_path)
    )
    tablespace_root_requested_path = posixpath.join(
        namespace_data_directory, "pg_tblspc"
    )
    (
        namespace_tablespace_root,
        tablespace_root_details,
        tablespace_root_chain,
    ) = (
        resolve_namespace_directory(
            tablespace_root_requested_path
        )
    )
    data_details = os.stat(data_directory)
    if (
        data_details.st_uid != postmaster_details.st_uid
        or os.stat(wal_directory).st_uid != data_details.st_uid
        or tablespace_root_details.st_uid != data_details.st_uid
    ):
        raise SystemExit(1)

    tablespaces = []
    tablespace_links = []
    for oid in tablespace_oids:
        if oid in {1663, 1664}:  # pg_default and pg_global
            continue
        link_namespace_path = posixpath.join(
            namespace_tablespace_root, str(oid)
        )
        link_path = namespace_access_path(link_namespace_path)
        link_details = os.lstat(link_path)
        if (
            not stat.S_ISLNK(link_details.st_mode)
            or link_details.st_uid != data_details.st_uid
            or link_details.st_nlink != 1
        ):
            raise SystemExit(1)
        target = os.readlink(link_path)
        target_namespace_path = clean_namespace_path(
            target
            if posixpath.isabs(target)
            else posixpath.join(
                posixpath.dirname(link_namespace_path), target
            )
        )
        (
            resolved_namespace_path,
            tablespace,
            target_chain,
            target_host_chain,
        ) = persistent_directory(target_namespace_path)
        if os.stat(tablespace).st_uid != data_details.st_uid:
            raise SystemExit(1)
        tablespaces.append(tablespace)
        tablespace_links.append(
            (
                link_path,
                link_details.st_dev,
                link_details.st_ino,
                target,
                target_namespace_path,
                resolved_namespace_path,
                tablespace,
                target_chain,
                target_host_chain,
            )
        )
    tablespaces = sorted(set(tablespaces))

    version_path = os.path.join(data_directory, "PG_VERSION")
    postmaster_path = os.path.join(data_directory, "postmaster.pid")
    postmaster_pidfile_details = os.lstat(postmaster_path)
    for required_path in (version_path, postmaster_path):
        details = os.lstat(required_path)
        if (
            not stat.S_ISREG(details.st_mode)
            or stat.S_ISLNK(details.st_mode)
            or details.st_uid != data_details.st_uid
            or details.st_nlink != 1
        ):
            raise SystemExit(1)
    lines = open(postmaster_path, "r", encoding="ascii").read().splitlines()
    if (
        len(lines) < 4
        or not lines[0].isdigit()
        or int(lines[0]) != postmaster["namespacePids"][-1]
        or clean_namespace_path(lines[1]) != namespace_data_directory
        or not lines[3].isdigit()
        or int(lines[3]) != observed["serverPort"]
    ):
        raise SystemExit(1)

    # Re-read both /proc identities after path resolution. A PID reuse or
    # process replacement during the proof must fail closed.
    backend_after = process_identity(backend_pid)
    postmaster_after = process_identity(postmaster_pid)
    if (
        not same_postgres_process_pair(backend_after, postmaster_after)
        or backend_after["startTime"] != backend_start_time
        or postmaster_after["startTime"] != postmaster_start_time
        or (
            backend_after["details"].st_dev,
            backend_after["details"].st_ino,
        )
            != (backend_details.st_dev, backend_details.st_ino)
        or (
            postmaster_after["details"].st_dev,
            postmaster_after["details"].st_ino,
        )
            != (postmaster_details.st_dev, postmaster_details.st_ino)
        or (
            backend_after["executableDevice"],
            backend_after["executableInode"],
        ) != (
            backend["executableDevice"],
            backend["executableInode"],
        )
        or (
            postmaster_after["executableDevice"],
            postmaster_after["executableInode"],
        ) != (
            postmaster["executableDevice"],
            postmaster["executableInode"],
        )
    ):
        raise SystemExit(1)

    if not os.path.isabs(postmaster_binary):
        raise SystemExit(1)
    postgres_bindir = clean_namespace_path(
        posixpath.dirname(postmaster_binary)
    )
    bindir_access_path = namespace_access_path(postgres_bindir)
    bindir_details = os.stat(bindir_access_path)
    if (
        not stat.S_ISDIR(bindir_details.st_mode)
        or bindir_details.st_mode & 0o022
    ):
        raise SystemExit(1)
    pg_controldata = posixpath.join(
        postgres_bindir, "pg_controldata"
    )
    tool_access_path = namespace_access_path(pg_controldata)
    tool_details = os.lstat(tool_access_path)
    if (
        not stat.S_ISREG(tool_details.st_mode)
        or stat.S_ISLNK(tool_details.st_mode)
        or tool_details.st_nlink != 1
        or tool_details.st_mode & (stat.S_ISUID | stat.S_ISGID)
        or tool_details.st_mode & 0o022
        or not tool_details.st_mode & 0o111
    ):
        raise SystemExit(1)
    tool_fd = os.open(
        tool_access_path,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0),
    )
    mount_namespace_fd = -1
    container_root_fd = -1
    try:
        opened_tool = os.fstat(tool_fd)
        if (
            opened_tool.st_dev != tool_details.st_dev
            or opened_tool.st_ino != tool_details.st_ino
            or not stat.S_ISREG(opened_tool.st_mode)
            or opened_tool.st_nlink != 1
            or opened_tool.st_mode & (stat.S_ISUID | stat.S_ISGID)
            or opened_tool.st_mode & 0o022
        ):
            raise SystemExit(1)

        if container_record is not None:
            mount_namespace_fd = os.open(
                f"/proc/{postmaster_pid}/ns/mnt",
                os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
            )
            container_root_fd = os.open(
                namespace_root,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_CLOEXEC", 0),
            )

        # pg_controldata is discovered from the exact /proc-attested
        # postmaster binary, but it is still PostgreSQL-controlled input. For
        # Docker, enter only the already-pinned mount namespace and chroot to
        # its exact root so the matching dynamic loader/libraries are visible.
        # Drop to the postmaster identity before exec in both modes.
        def exec_verified_tool_as_postmaster():
            libc = ctypes.CDLL(None, use_errno=True)
            if container_record is not None:
                if libc.setns(mount_namespace_fd, 0) != 0:
                    raise OSError(
                        ctypes.get_errno(), "PostgreSQL mount setns failed"
                    )
                os.fchdir(container_root_fd)
                os.chroot(".")
                os.chdir("/")
            if libc.prctl(38, 1, 0, 0, 0) != 0:  # PR_SET_NO_NEW_PRIVS
                raise OSError(ctypes.get_errno(), "PR_SET_NO_NEW_PRIVS failed")
            os.setgroups([])
            os.setgid(postmaster_details.st_gid)
            os.setuid(postmaster_details.st_uid)
            os.umask(0o077)
            if (
                os.getuid() != postmaster_details.st_uid
                or os.geteuid() != postmaster_details.st_uid
                or os.getgid() != postmaster_details.st_gid
                or os.getegid() != postmaster_details.st_gid
                or os.getgroups()
            ):
                raise OSError("could not drop to PostgreSQL process identity")
            argv_values = [
                os.fsencode(pg_controldata),
                os.fsencode(command_data_directory),
            ]
            environment_values = [
                b"PATH=/usr/bin:/bin",
                b"LANG=C",
                b"LC_ALL=C",
            ]
            argv = (ctypes.c_char_p * (len(argv_values) + 1))(
                *argv_values, None
            )
            environment = (
                ctypes.c_char_p * (len(environment_values) + 1)
            )(*environment_values, None)
            try:
                execveat = libc.execveat
            except AttributeError:
                # musl omits the execveat wrapper but provides fexecve. This
                # branch is used only when already running in the postmaster's
                # own PID/mount namespace, where its procfs can resolve the
                # opened fd without crossing a descendant PID namespace.
                if container_record is not None:
                    raise OSError("execveat is unavailable for Docker proof")
                libc.fexecve.argtypes = [
                    ctypes.c_int,
                    ctypes.POINTER(ctypes.c_char_p),
                    ctypes.POINTER(ctypes.c_char_p),
                ]
                libc.fexecve.restype = ctypes.c_int
                result = libc.fexecve(tool_fd, argv, environment)
            else:
                execveat.argtypes = [
                    ctypes.c_int,
                    ctypes.c_char_p,
                    ctypes.POINTER(ctypes.c_char_p),
                    ctypes.POINTER(ctypes.c_char_p),
                    ctypes.c_int,
                ]
                execveat.restype = ctypes.c_int
                result = execveat(
                    tool_fd,
                    b"",
                    argv,
                    environment,
                    0x1000,  # AT_EMPTY_PATH: execute the verified fd.
                )
            if result != 0:
                raise OSError(
                    ctypes.get_errno(), "verified pg_controldata exec failed"
                )

        command_data_directory = (
            namespace_data_directory
            if container_record is not None
            else data_directory
        )
        passed_fds = [tool_fd]
        if container_record is not None:
            passed_fds.extend((mount_namespace_fd, container_root_fd))
        completed = subprocess.run(
            [pg_controldata, command_data_directory],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            env={
                "PATH": "/usr/bin:/bin",
                "LANG": "C",
                "LC_ALL": "C",
            },
            text=True,
            timeout=10,
            check=False,
            close_fds=True,
            pass_fds=tuple(passed_fds),
            preexec_fn=exec_verified_tool_as_postmaster,
        )
    finally:
        if mount_namespace_fd >= 0:
            os.close(mount_namespace_fd)
        if container_root_fd >= 0:
            os.close(container_root_fd)
        os.close(tool_fd)
    if completed.returncode != 0 or len(completed.stdout) > 256 * 1024:
        raise SystemExit(1)
    match = re.search(
        r"^Database system identifier:\s*([0-9]+)\s*$",
        completed.stdout,
        flags=re.MULTILINE,
    )
    if match is None:
        raise SystemExit(1)
    system_identifier = match.group(1)

    # Recheck every mutable namespace link and the exact process/pidfile
    # identities after pg_controldata. Mid-proof storage swaps fail closed.
    postmaster_final = process_identity(postmaster_pid)
    backend_final = process_identity(backend_pid)
    pidfile_final = os.lstat(postmaster_path)
    if (
        not same_postgres_process_pair(backend_final, postmaster_final)
        or backend_final["startTime"] != backend_start_time
        or postmaster_final["startTime"] != postmaster_start_time
        or (pidfile_final.st_dev, pidfile_final.st_ino)
            != (
                postmaster_pidfile_details.st_dev,
                postmaster_pidfile_details.st_ino,
            )
    ):
        raise SystemExit(1)
    (
        current_data_namespace,
        current_data_host,
        current_data_chain,
        current_data_host_chain,
    ) = (
        persistent_directory(data_requested_path)
    )
    (
        current_wal_namespace,
        current_wal_host,
        current_wal_chain,
        current_wal_host_chain,
    ) = (
        persistent_directory(wal_requested_path)
    )
    (
        current_tablespace_root,
        _current_tablespace_root_details,
        current_tablespace_root_chain,
    ) = resolve_namespace_directory(tablespace_root_requested_path)
    if (
        current_data_namespace != namespace_data_directory
        or current_data_host != data_directory
        or current_data_chain != data_chain
        or current_data_host_chain != data_host_chain
        or current_wal_namespace != namespace_wal_directory
        or current_wal_host != wal_directory
        or current_wal_chain != wal_chain
        or current_wal_host_chain != wal_host_chain
        or current_tablespace_root != namespace_tablespace_root
        or current_tablespace_root_chain != tablespace_root_chain
    ):
        raise SystemExit(1)
    recheck_namespace_chain(data_chain)
    recheck_namespace_chain(wal_chain)
    recheck_namespace_chain(tablespace_root_chain)
    recheck_host_chain(data_host_chain)
    recheck_host_chain(wal_host_chain)

    for (
        link_path,
        link_device,
        link_inode,
        link_target,
        target_requested_path,
        namespace_target,
        host_target,
        target_chain,
        target_host_chain,
    ) in tablespace_links:
        current_link = os.lstat(link_path)
        if (
            not stat.S_ISLNK(current_link.st_mode)
            or current_link.st_dev != link_device
            or current_link.st_ino != link_inode
            or os.readlink(link_path) != link_target
        ):
            raise SystemExit(1)
        (
            current_namespace_target,
            current_host_target,
            current_target_chain,
            current_target_host_chain,
        ) = persistent_directory(target_requested_path)
        if (
            current_namespace_target != namespace_target
            or current_host_target != host_target
            or current_target_chain != target_chain
            or current_target_host_chain != target_host_chain
        ):
            raise SystemExit(1)
        recheck_namespace_chain(target_chain)
        recheck_host_chain(target_host_chain)

paths = [data_directory, wal_directory, *tablespaces]
if any(os.stat(path).st_uid != data_details.st_uid for path in paths):
    raise SystemExit(1)

if re.fullmatch(r"[1-9][0-9]{0,31}", system_identifier) is None:
    raise SystemExit(1)
topology = {
    "schema": "bridgesllm-update-database-topology-v1",
    "systemIdentifier": system_identifier,
    "serverAddress": str(host_address),
    "serverPort": int(expected_port),
    "databaseName": observed["databaseName"],
    "databaseOid": observed["databaseOid"],
    "dataDirectory": data_directory,
    "walDirectory": wal_directory,
    "tablespaces": [
        {"path": path, "stDev": os.stat(path).st_dev} for path in tablespaces
    ],
    "dataDevice": data_details.st_dev,
    "walDevice": os.stat(wal_directory).st_dev,
}
payload = json.dumps(
    topology, sort_keys=True, separators=(",", ":"), ensure_ascii=True
).encode("ascii")
if len(payload) > 64 * 1024:
    raise SystemExit(1)
print(payload.decode("ascii"))
PY2
  fi

  if [[ -n "${psql_input_fd}" ]]; then
    printf '%s\n' '\q' >&"${psql_input_fd}" 2>/dev/null || true
    eval "exec ${psql_input_fd}>&-" || true
  fi
  if [[ -n "${psql_pid}" ]]; then
    for _ in {1..20}; do
      kill -0 "${psql_pid}" 2>/dev/null || break
      sleep 0.05
    done
    kill -TERM "${psql_pid}" 2>/dev/null || true
    wait "${psql_pid}" 2>/dev/null || true
  fi
  if [[ -n "${backend_pid}" ]]; then
    [[ -n "${backend_start}" ]] || settlement_status=1
    for _ in {1..200}; do
      [[ "${settlement_status}" -eq 0 ]] || break
      remaining="$(
        printf "SELECT count(*) FROM pg_catalog.pg_stat_activity WHERE pid = %s AND extract(epoch FROM backend_start)::text = '%s';\n" \
          "${backend_pid}" "${backend_start}" \
          | run_with_update_pgpass "${db_url}" \
              psql --dbname="${connection_url}" --no-psqlrc \
                -v ON_ERROR_STOP=1 -qAt 2>>"${LOG_FILE}"
      )" || {
        settlement_status=1
        break
      }
      remaining="$(tr -d '[:space:]' <<<"${remaining}")"
      [[ "${remaining}" == "0" ]] && break
      [[ "${remaining}" == "1" ]] || {
        settlement_status=1
        break
      }
      sleep 0.05
    done
    [[ "${remaining}" == "0" ]] || settlement_status=1
  fi
  if [[ "${status}" -eq 0 && "${proof_status}" -eq 0 \
    && "${settlement_status}" -eq 0 ]]; then
    proof_output="$(cat "${proof_file}")" || status=$?
  fi
  rm -rf -- "${work_dir}"
  [[ "${status}" -eq 0 && "${proof_status}" -eq 0 \
    && "${settlement_status}" -eq 0 && -n "${proof_output}" ]] || return 1
  printf '%s\n' "${proof_output}"
}

release_update_disk_reserves() {
  # Terminal cleanup is itself journaled. A hard kill after any unlink can
  # resume from the manifest without guessing at files or touching another
  # transaction's reserve.
  local state_root manifest
  state_root="$(update_transaction_state_path "${UPDATE_STATE_ROOT}")" \
    || return 1
  manifest="${state_root}/update-disk-reserves.json"
  UPDATE_DISK_RESERVE_MANIFEST="${manifest}"
  [[ -e "${manifest}" || -L "${manifest}" ]] || return 0
  python3 - "${manifest}" <<'PY2' || return $?
import json
import os
import re
import stat
import sys
import tempfile

manifest = sys.argv[1]


def fsync_directory(path):
    descriptor = os.open(
        path,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def write_manifest(record):
    directory = os.path.dirname(manifest)
    payload = (
        json.dumps(
            record, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        )
        + "\n"
    ).encode("ascii")
    if len(payload) > 64 * 1024:
        raise SystemExit(1)
    descriptor, temporary = tempfile.mkstemp(
        prefix=".update-disk-reserves.", dir=directory
    )
    try:
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, manifest)
        temporary = ""
        fsync_directory(directory)
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass


source_only = (
    os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
    and bool(os.environ.get("BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT"))
)
crash_after = 0
if source_only and os.environ.get(
    "BRIDGESLLM_UPDATE_TRANSACTION_TEST_RESERVE_CRASH_AFTER"
):
    crash_after = int(
        os.environ["BRIDGESLLM_UPDATE_TRANSACTION_TEST_RESERVE_CRASH_AFTER"]
    )
    if crash_after < 1:
        raise SystemExit(1)
crash_step = 0


def maybe_crash():
    global crash_step
    crash_step += 1
    if crash_after == crash_step:
        os._exit(97)


try:
    details = os.lstat(manifest)
except OSError:
    raise SystemExit(1)
if (
    not stat.S_ISREG(details.st_mode)
    or stat.S_ISLNK(details.st_mode)
    or details.st_uid != os.geteuid()
    or details.st_gid != os.getegid()
    or details.st_nlink != 1
    or stat.S_IMODE(details.st_mode) != 0o600
    or not 1 <= details.st_size <= 64 * 1024
):
    raise SystemExit(1)
try:
    record = json.loads(open(manifest, "rb").read())
except (OSError, ValueError):
    raise SystemExit(1)
if (
    not isinstance(record, dict)
    or record.get("schema") != "bridgesllm-update-disk-reserve-v2"
    or record.get("state") not in {
        "allocating",
        "held",
        "rearming",
        "recovery-preparing",
        "recovery",
        "emergency-ready",
        "emergency-releasing",
        "emergency-consumed",
        "releasing",
    }
    or not isinstance(record.get("transactionId"), str)
    or not re.fullmatch(r"[a-f0-9]{32}", record["transactionId"])
    or not isinstance(record.get("tierBytes"), int)
    or not 1 <= record["tierBytes"] <= 256 * 1024 * 1024
    or not isinstance(record.get("entries"), list)
    or not 2 <= len(record["entries"]) <= 128
    or len(record["entries"]) % 2
):
    raise SystemExit(1)

if record["state"] != "releasing":
    record["state"] = "releasing"
    for entry in record["entries"]:
        if isinstance(entry, dict):
            entry["removed"] = False
    write_manifest(record)

seen = set()
for entry in record["entries"]:
    tier = entry.get("tier") if isinstance(entry, dict) else None
    expected_name = (
        f".bridgesllm-update-reserve-{tier}-{record['transactionId']}"
    )
    if (
        not isinstance(entry, dict)
        or tier not in {"work", "emergency"}
        or not isinstance(entry.get("device"), str)
        or not entry["device"]
        or not isinstance(entry.get("path"), str)
        or os.path.basename(entry["path"]) != expected_name
        or not os.path.isabs(entry["path"])
        or os.path.normpath(entry["path"]) != entry["path"]
        or not isinstance(entry.get("removed"), bool)
        or (entry["device"], tier) in seen
    ):
        raise SystemExit(1)
    seen.add((entry["device"], tier))
    path = entry["path"]
    parent = os.path.dirname(path)
    try:
        parent_details = os.lstat(parent)
    except OSError:
        raise SystemExit(1)
    if (
        not stat.S_ISDIR(parent_details.st_mode)
        or stat.S_ISLNK(parent_details.st_mode)
        or parent_details.st_mode & 0o022
    ):
        raise SystemExit(1)
    try:
        held = os.lstat(path)
    except FileNotFoundError:
        if record["state"] != "releasing":
            raise SystemExit(1)
        if not entry["removed"]:
            entry["removed"] = True
            write_manifest(record)
        continue
    except OSError:
        raise SystemExit(1)
    if (
        not stat.S_ISREG(held.st_mode)
        or stat.S_ISLNK(held.st_mode)
        or held.st_uid != os.geteuid()
        or held.st_gid != os.getegid()
        or held.st_nlink != 1
        or stat.S_IMODE(held.st_mode) != 0o600
        or not 0 <= held.st_size <= record["tierBytes"]
        or (
            entry.get("stDev") is not None
            and held.st_dev != entry.get("stDev")
        )
        or (
            entry.get("stIno") is not None
            and held.st_ino != entry.get("stIno")
        )
    ):
        raise SystemExit(1)
    os.unlink(path)
    fsync_directory(parent)
    maybe_crash()
    entry["removed"] = True
    write_manifest(record)
    maybe_crash()

os.unlink(manifest)
parent = os.path.dirname(manifest)
fsync_directory(parent)
maybe_crash()
PY2
  UPDATE_DISK_RESERVE_MANIFEST=""
}

prepare_update_disk_reserves_for_recovery() {
  # Recovery consumes only the work tier. The emergency tier remains fully
  # allocated on every filesystem until the transaction reaches a terminal
  # receipt. A restarted recovery first tries to re-arm every work tier. If
  # recovery already consumed that space, it records emergency-ready but this
  # function never consumes the final tier. The caller must first prove the
  # sole receipt, rollback artifacts, protected paths, and database topology,
  # then invoke the explicit emergency consumer immediately before recovery
  # writes.
  local state_root manifest
  state_root="$(update_transaction_state_path "${UPDATE_STATE_ROOT}")" \
    || return 1
  manifest="${state_root}/update-disk-reserves.json"
  [[ -f "${manifest}" && ! -L "${manifest}" ]] || return 1
  python3 - "${manifest}" <<'PY2' || return $?
import errno
import json
import os
import re
import stat
import sys
import tempfile

manifest = sys.argv[1]
state_root = os.path.dirname(manifest)


def fsync_directory(path):
    descriptor = os.open(
        path,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def write_manifest(record):
    payload = (
        json.dumps(
            record, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        )
        + "\n"
    ).encode("ascii")
    if len(payload) > 64 * 1024:
        raise SystemExit(1)
    descriptor, temporary = tempfile.mkstemp(
        prefix=".update-disk-reserves.", dir=state_root
    )
    try:
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, manifest)
        temporary = ""
        fsync_directory(state_root)
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass


details = os.lstat(manifest)
if (
    not stat.S_ISREG(details.st_mode)
    or stat.S_ISLNK(details.st_mode)
    or details.st_uid != os.geteuid()
    or details.st_gid != os.getegid()
    or details.st_nlink != 1
    or stat.S_IMODE(details.st_mode) != 0o600
    or not 1 <= details.st_size <= 64 * 1024
):
    raise SystemExit(1)
try:
    record = json.loads(open(manifest, "rb").read())
except (OSError, ValueError):
    raise SystemExit(1)
if (
    not isinstance(record, dict)
    or record.get("schema") != "bridgesllm-update-disk-reserve-v2"
    or record.get("state") not in {
        "held",
        "rearming",
        "recovery-preparing",
        "recovery",
        "emergency-ready",
        "emergency-releasing",
        "emergency-consumed",
    }
    or not isinstance(record.get("transactionId"), str)
    or not re.fullmatch(r"[a-f0-9]{32}", record["transactionId"])
    or not isinstance(record.get("tierBytes"), int)
    or not 1 <= record["tierBytes"] <= 256 * 1024 * 1024
    or not isinstance(record.get("entries"), list)
    or not 2 <= len(record["entries"]) <= 128
    or len(record["entries"]) % 2
):
    raise SystemExit(1)
tier_bytes = record["tierBytes"]
source_only = (
    os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
    and bool(os.environ.get("BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT"))
)
crash_after = 0
if source_only and os.environ.get(
    "BRIDGESLLM_UPDATE_TRANSACTION_TEST_RESERVE_RECOVERY_CRASH_AFTER"
):
    crash_after = int(
        os.environ[
            "BRIDGESLLM_UPDATE_TRANSACTION_TEST_RESERVE_RECOVERY_CRASH_AFTER"
        ]
    )
    if crash_after < 1:
        raise SystemExit(1)
crash_step = 0


def maybe_crash():
    global crash_step
    crash_step += 1
    if crash_after == crash_step:
        os._exit(98)


entries_by_device = {}
for entry in record["entries"]:
    if not isinstance(entry, dict):
        raise SystemExit(1)
    tier = entry.get("tier")
    device = entry.get("device")
    path = entry.get("path")
    expected_name = (
        f".bridgesllm-update-reserve-{tier}-{record['transactionId']}"
    )
    if (
        tier not in {"work", "emergency"}
        or not isinstance(device, str)
        or not device
        or not isinstance(path, str)
        or not os.path.isabs(path)
        or os.path.normpath(path) != path
        or os.path.basename(path) != expected_name
        or (device, tier) in entries_by_device
    ):
        raise SystemExit(1)
    parent = os.path.dirname(path)
    parent_details = os.lstat(parent)
    if (
        not stat.S_ISDIR(parent_details.st_mode)
        or stat.S_ISLNK(parent_details.st_mode)
        or parent_details.st_mode & 0o022
    ):
        raise SystemExit(1)
    entries_by_device[(device, tier)] = entry
devices = {device for device, _ in entries_by_device}
if any(
    (device, "work") not in entries_by_device
    or (device, "emergency") not in entries_by_device
    for device in devices
):
    raise SystemExit(1)


def validate_file(entry, *, require_full):
    details = os.lstat(entry["path"])
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_gid != os.getegid()
        or details.st_nlink != 1
        or stat.S_IMODE(details.st_mode) != 0o600
        or details.st_dev != entry.get("stDev")
        or details.st_ino != entry.get("stIno")
        or not 0 <= details.st_size <= tier_bytes
    ):
        raise SystemExit(1)
    if require_full and (
        details.st_size != tier_bytes
        or details.st_blocks * 512 < tier_bytes
    ):
        raise SystemExit(1)
    return details


initial_state = record["state"]


def truncate_tier(entry):
    details = validate_file(entry, require_full=False)
    descriptor = os.open(
        entry["path"],
        os.O_RDWR | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        opened = os.fstat(descriptor)
        if opened.st_dev != details.st_dev or opened.st_ino != details.st_ino:
            raise SystemExit(1)
        os.ftruncate(descriptor, 0)
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    fsync_directory(os.path.dirname(entry["path"]))


# Emergency states are only validated here. Consumption is a separate,
# explicitly ordered operation after the read-only recovery preflight. A
# partially releasing state is accepted so SIGKILL can re-run the preflight
# before converging its write-ahead truncations.
if initial_state in {
    "emergency-ready", "emergency-releasing", "emergency-consumed"
}:
    for device in sorted(devices):
        work = entries_by_device[(device, "work")]
        work_details = validate_file(work, require_full=False)
        if work_details.st_size != 0 or work.get("released") is not True:
            raise SystemExit(1)
    if initial_state == "emergency-consumed":
        for device in sorted(devices):
            emergency = entries_by_device[(device, "emergency")]
            emergency_details = validate_file(emergency, require_full=False)
            if (
                emergency_details.st_size != 0
                or emergency.get("released") is not True
            ):
                raise SystemExit(1)
        raise SystemExit(0)
    for device in sorted(devices):
        emergency = entries_by_device[(device, "emergency")]
        details = validate_file(emergency, require_full=False)
        if initial_state == "emergency-ready":
            if (
                details.st_size != tier_bytes
                or details.st_blocks * 512 < tier_bytes
                or emergency.get("released") is not False
            ):
                raise SystemExit(1)
        elif (
            details.st_size not in {0, tier_bytes}
            or (
                details.st_size == tier_bytes
                and details.st_blocks * 512 < tier_bytes
            )
            or emergency.get("released") not in {False, True}
            or (
                emergency.get("released") is True
                and details.st_size != 0
            )
        ):
            raise SystemExit(1)
    raise SystemExit(0)

# Before escalation the emergency tier is immutable and fully allocated.
for device in sorted(devices):
    emergency = entries_by_device[(device, "emergency")]
    validate_file(emergency, require_full=True)
    if emergency.get("released") is not False:
        raise SystemExit(1)

forced_rearm_available = None
if source_only and os.environ.get(
    "BRIDGESLLM_UPDATE_TRANSACTION_TEST_RECOVERY_AVAILABLE_BYTES"
) is not None:
    forced_rearm_available = int(
        os.environ[
            "BRIDGESLLM_UPDATE_TRANSACTION_TEST_RECOVERY_AVAILABLE_BYTES"
        ]
    )
    if forced_rearm_available < 0:
        raise SystemExit(1)

record["state"] = "rearming"
write_manifest(record)
maybe_crash()
rearm_failed = False
for device in sorted(devices):
    entry = entries_by_device[(device, "work")]
    path = entry["path"]
    descriptor = -1
    try:
        try:
            validate_file(entry, require_full=False)
            descriptor = os.open(
                path,
                os.O_RDWR | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0),
            )
        except FileNotFoundError:
            descriptor = os.open(
                path,
                os.O_RDWR | os.O_CREAT | os.O_EXCL
                | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
                0o600,
            )
            created = os.fstat(descriptor)
            entry["stDev"] = created.st_dev
            entry["stIno"] = created.st_ino
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_uid != os.geteuid()
            or opened.st_gid != os.getegid()
            or opened.st_nlink != 1
            or stat.S_IMODE(opened.st_mode) != 0o600
            or opened.st_dev != entry["stDev"]
            or opened.st_ino != entry["stIno"]
        ):
            raise SystemExit(1)
        if (
            forced_rearm_available is not None
            and forced_rearm_available < tier_bytes
        ):
            raise OSError(errno.ENOSPC, "simulated recovery reserve exhaustion")
        os.ftruncate(descriptor, 0)
        if hasattr(os, "posix_fallocate"):
            os.posix_fallocate(descriptor, 0, tier_bytes)
        else:
            remaining = tier_bytes
            block = b"\0" * min(1024 * 1024, tier_bytes)
            while remaining:
                written = os.write(descriptor, block[:remaining])
                if written <= 0:
                    raise OSError("reserve allocation made no progress")
                remaining -= written
        os.fsync(descriptor)
        held = os.fstat(descriptor)
        if (
            held.st_size != tier_bytes
            or held.st_blocks * 512 < tier_bytes
        ):
            raise OSError("work reserve is sparse or incomplete")
    except OSError as error:
        if error.errno not in {errno.ENOSPC, errno.EDQUOT}:
            raise
        rearm_failed = True
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    if rearm_failed:
        break
    fsync_directory(os.path.dirname(path))
    entry["released"] = False
    write_manifest(record)
    maybe_crash()

# Whether rearm succeeded or capacity was consumed, return every work inode to
# a journaled released state. In the latter case emergency remains untouched
# for this recovery attempt and is consumed only on a later invocation.
record["state"] = "recovery-preparing"
write_manifest(record)
maybe_crash()
for device in sorted(devices):
    entry = entries_by_device[(device, "work")]
    details = validate_file(entry, require_full=False)
    if details.st_size:
        truncate_tier(entry)
        maybe_crash()
    entry["released"] = True
    write_manifest(record)
    maybe_crash()

record["state"] = "emergency-ready" if rearm_failed else "recovery"
write_manifest(record)
maybe_crash()
PY2
  UPDATE_DISK_RESERVE_MANIFEST="${manifest}"
}

consume_update_emergency_disk_reserves_for_recovery() {
  # This is the only non-terminal path allowed to consume the final reserve.
  # Its caller orders it after the read-only recovery preflight and
  # immediately before journal/restore writes. Every truncation is protected
  # by a durable emergency-releasing state and converges after SIGKILL.
  local state_root manifest
  state_root="$(update_transaction_state_path "${UPDATE_STATE_ROOT}")" \
    || return 1
  manifest="${state_root}/update-disk-reserves.json"
  [[ -f "${manifest}" && ! -L "${manifest}" ]] || return 1
  python3 - "${manifest}" <<'PY2' || return $?
import json
import os
import re
import stat
import sys
import tempfile

manifest = sys.argv[1]
state_root = os.path.dirname(manifest)


def fsync_directory(path):
    descriptor = os.open(
        path,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def write_manifest(record):
    payload = (
        json.dumps(
            record, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        )
        + "\n"
    ).encode("ascii")
    if len(payload) > 64 * 1024:
        raise SystemExit(1)
    descriptor, temporary = tempfile.mkstemp(
        prefix=".update-disk-reserves.", dir=state_root
    )
    try:
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, manifest)
        temporary = ""
        fsync_directory(state_root)
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass


details = os.lstat(manifest)
if (
    not stat.S_ISREG(details.st_mode)
    or stat.S_ISLNK(details.st_mode)
    or details.st_uid != os.geteuid()
    or details.st_gid != os.getegid()
    or details.st_nlink != 1
    or stat.S_IMODE(details.st_mode) != 0o600
    or not 1 <= details.st_size <= 64 * 1024
):
    raise SystemExit(1)
try:
    record = json.loads(open(manifest, "rb").read())
except (OSError, ValueError):
    raise SystemExit(1)
if (
    not isinstance(record, dict)
    or record.get("schema") != "bridgesllm-update-disk-reserve-v2"
    or record.get("state") not in {
        "held",
        "rearming",
        "recovery-preparing",
        "recovery",
        "emergency-ready",
        "emergency-releasing",
        "emergency-consumed",
    }
    or not isinstance(record.get("transactionId"), str)
    or not re.fullmatch(r"[a-f0-9]{32}", record["transactionId"])
    or not isinstance(record.get("tierBytes"), int)
    or not 1 <= record["tierBytes"] <= 256 * 1024 * 1024
    or not isinstance(record.get("entries"), list)
    or not 2 <= len(record["entries"]) <= 128
    or len(record["entries"]) % 2
):
    raise SystemExit(1)
if record["state"] in {
    "held", "rearming", "recovery-preparing", "recovery"
}:
    raise SystemExit(0)

tier_bytes = record["tierBytes"]
source_only = (
    os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
    and bool(os.environ.get("BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT"))
)
crash_after = 0
if source_only and os.environ.get(
    "BRIDGESLLM_UPDATE_TRANSACTION_TEST_RESERVE_RECOVERY_CRASH_AFTER"
):
    crash_after = int(
        os.environ[
            "BRIDGESLLM_UPDATE_TRANSACTION_TEST_RESERVE_RECOVERY_CRASH_AFTER"
        ]
    )
    if crash_after < 1:
        raise SystemExit(1)
crash_step = 0


def maybe_crash():
    global crash_step
    crash_step += 1
    if crash_after == crash_step:
        os._exit(98)


entries_by_device = {}
for entry in record["entries"]:
    if not isinstance(entry, dict):
        raise SystemExit(1)
    tier = entry.get("tier")
    device = entry.get("device")
    path = entry.get("path")
    expected_name = (
        f".bridgesllm-update-reserve-{tier}-{record['transactionId']}"
    )
    if (
        tier not in {"work", "emergency"}
        or not isinstance(device, str)
        or not device
        or not isinstance(path, str)
        or not os.path.isabs(path)
        or os.path.normpath(path) != path
        or os.path.basename(path) != expected_name
        or (device, tier) in entries_by_device
    ):
        raise SystemExit(1)
    parent = os.path.dirname(path)
    parent_details = os.lstat(parent)
    if (
        not stat.S_ISDIR(parent_details.st_mode)
        or stat.S_ISLNK(parent_details.st_mode)
        or parent_details.st_mode & 0o022
    ):
        raise SystemExit(1)
    entries_by_device[(device, tier)] = entry
devices = {device for device, _ in entries_by_device}
if any(
    (device, "work") not in entries_by_device
    or (device, "emergency") not in entries_by_device
    for device in devices
):
    raise SystemExit(1)


def validate_file(entry):
    details = os.lstat(entry["path"])
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_gid != os.getegid()
        or details.st_nlink != 1
        or stat.S_IMODE(details.st_mode) != 0o600
        or details.st_dev != entry.get("stDev")
        or details.st_ino != entry.get("stIno")
        or details.st_size not in {0, tier_bytes}
        or (
            details.st_size == tier_bytes
            and details.st_blocks * 512 < tier_bytes
        )
    ):
        raise SystemExit(1)
    return details


for device in sorted(devices):
    work = entries_by_device[(device, "work")]
    if (
        validate_file(work).st_size != 0
        or work.get("released") is not True
    ):
        raise SystemExit(1)

if record["state"] == "emergency-consumed":
    for device in sorted(devices):
        emergency = entries_by_device[(device, "emergency")]
        if (
            validate_file(emergency).st_size != 0
            or emergency.get("released") is not True
        ):
            raise SystemExit(1)
    raise SystemExit(0)

if record["state"] == "emergency-ready":
    for device in sorted(devices):
        emergency = entries_by_device[(device, "emergency")]
        if (
            validate_file(emergency).st_size != tier_bytes
            or emergency.get("released") is not False
        ):
            raise SystemExit(1)
    record["state"] = "emergency-releasing"
    write_manifest(record)
    maybe_crash()

for device in sorted(devices):
    emergency = entries_by_device[(device, "emergency")]
    details = validate_file(emergency)
    if emergency.get("released") is True:
        if details.st_size != 0:
            raise SystemExit(1)
        continue
    if emergency.get("released") is not False:
        raise SystemExit(1)
    if details.st_size == tier_bytes:
        descriptor = os.open(
            emergency["path"],
            os.O_RDWR | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
        )
        try:
            opened = os.fstat(descriptor)
            if (
                opened.st_dev != details.st_dev
                or opened.st_ino != details.st_ino
            ):
                raise SystemExit(1)
            os.ftruncate(descriptor, 0)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        fsync_directory(os.path.dirname(emergency["path"]))
        maybe_crash()
    emergency["released"] = True
    write_manifest(record)
    maybe_crash()

record["state"] = "emergency-consumed"
write_manifest(record)
maybe_crash()
PY2
}

update_disk_admission_denied() {
  # Every admission refusal names itself in the log. The caller can then say
  # what actually happened instead of blaming free space for all of them.
  printf 'update transaction disk admission denied: %s\n' "$1" \
    >> "${LOG_FILE}" 2>/dev/null || true
  return 1
}

update_disk_admission_last_detail() {
  # Read back the reason this run recorded, for the operator-facing message.
  # This must never fail: it is expanded inside the operator-facing message of
  # a refusal, and a non-zero status there would trip the ERR trap and replace
  # a precise explanation with "Unexpected error" -- the exact substitution
  # this whole change exists to stop.
  local detail=""
  if [[ -r "${LOG_FILE}" ]]; then
    detail="$(
      tail -n 200 "${LOG_FILE}" 2>/dev/null \
        | grep -E '^update transaction disk admission (denied|failed): ' \
        | tail -n 1 \
        | sed -E 's/^update transaction disk admission (denied|failed): //'
    )" || detail=""
  fi
  [[ -n "${detail}" ]] || detail="no reason was recorded; see the installer log"
  printf '%s\n' "${detail}"
  return 0
}

assert_update_transaction_disk_admission() {
  # The transaction must never begin work it cannot finish or roll back for
  # want of disk. Before staging, the current Portal is a conservative
  # candidate estimate. After staging and dependency preparation, the exact
  # candidate footprint is required and admission runs again before a receipt
  # or downtime. The journal filesystem gets its own reserve because its
  # bounded manifests can live on a separately mounted /var.
  #
  # Exit codes are load-bearing: 2 means the host genuinely lacks the space,
  # and anything else non-zero means admission refused for a different,
  # separately logged reason. Collapsing them into one message hides real
  # upgrade blockers behind a disk-space claim that is not true.
  local portal_dir="$1" db_url="$2" staged_portal="${3:-}"
  local portal_size candidate_size db_size db_topology
  local backup_root stage_root state_root
  [[ "${UPDATE_TRANSACTION_ID:-}" =~ ^[a-f0-9]{32}$ ]] \
    || update_disk_admission_denied \
      "the update transaction identifier is malformed" \
    || return 1
  portal_size="$(du -sb "${portal_dir}" 2>/dev/null | cut -f1)" \
    || update_disk_admission_denied \
      "the live Portal tree size could not be measured" \
    || return 1
  [[ "${portal_size}" =~ ^[0-9]+$ && "${portal_size}" -gt 0 ]] \
    || update_disk_admission_denied \
      "the live Portal tree reported a non-positive size" \
    || return 1
  candidate_size="${portal_size}"
  if [[ -n "${staged_portal}" ]]; then
    [[ -d "${staged_portal}" && ! -L "${staged_portal}" ]] \
      || update_disk_admission_denied \
        "the staged candidate tree is missing, is not a directory, or is a symlink" \
      || return 1
    candidate_size="$(du -sb "${staged_portal}" 2>/dev/null | cut -f1)" \
      || update_disk_admission_denied \
        "the staged candidate tree size could not be measured" \
      || return 1
    [[ "${candidate_size}" =~ ^[0-9]+$ && "${candidate_size}" -gt 0 ]] \
      || update_disk_admission_denied \
        "the staged candidate tree reported a non-positive size" \
      || return 1
  fi
  db_size="$(update_database_size_bytes "${db_url}")" \
    || update_disk_admission_denied \
      "the Portal database size could not be measured" \
    || return 1
  db_topology="$(canonical_update_database_topology "${db_url}")" \
    || update_disk_admission_denied \
      "the Portal database storage topology could not be attested" \
    || return 1
  backup_root="$(update_transaction_state_path "${UPDATE_BACKUP_ROOT}")" \
    || update_disk_admission_denied \
      "the rollback snapshot root is not a safe update transaction path" \
    || return 1
  stage_root="$(update_transaction_state_path "${UPDATE_STAGE_ROOT}")" \
    || update_disk_admission_denied \
      "the staging root is not a safe update transaction path" \
    || return 1
  state_root="$(update_transaction_state_path "${UPDATE_STATE_ROOT}")" \
    || update_disk_admission_denied \
      "the installer journal root is not a safe update transaction path" \
    || return 1
  python3 - "${portal_size}" "${candidate_size}" "${db_size}" \
    "${stage_root}" "${backup_root}" "${portal_dir}" "${state_root}" \
    "${staged_portal}" "${db_topology}" \
    "${UPDATE_TRANSACTION_ID}" <<'PY2' >> "${LOG_FILE}" 2>&1 \
    || return $?
import hashlib
import ipaddress
import json
import os
import re
import stat
import sys
import tempfile

RECOVERY_RESERVE_BYTES = 512 * 1024 * 1024
STATE_RESERVE_BYTES = 1024 * 1024 * 1024

# Exit 3 marks a policy refusal that has nothing to do with free space. The
# reason is printed into the installer log so the operator is told what the
# admission actually objected to.
POLICY_DENIED_EXIT = 3


def deny(reason: str) -> SystemExit:
    print(f"update transaction disk admission denied: {reason}")
    return SystemExit(POLICY_DENIED_EXIT)


portal_size = int(sys.argv[1])
candidate_size = int(sys.argv[2])
db_size = int(sys.argv[3])
stage_root, backup_root, portal_dir, state_root, staged_portal = sys.argv[4:9]
topology_raw, transaction_id = sys.argv[9:11]
if not re.fullmatch(r"[a-f0-9]{32}", transaction_id):
    raise deny("the transaction identifier passed to the policy check is malformed")

source_only = (
    os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
    and bool(os.environ.get("BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT"))
)
test_root = os.path.realpath(
    os.environ.get("BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT", "")
) if source_only else ""

try:
    topology = json.loads(topology_raw)
except ValueError:
    raise deny("the database storage topology record is not valid JSON")
if (
    not isinstance(topology, dict)
    or set(topology) != {
        "schema",
        "systemIdentifier",
        "serverAddress",
        "serverPort",
        "databaseName",
        "databaseOid",
        "dataDirectory",
        "walDirectory",
        "tablespaces",
        "dataDevice",
        "walDevice",
    }
    or topology.get("schema")
        != "bridgesllm-update-database-topology-v1"
    or not isinstance(topology["systemIdentifier"], str)
    or not re.fullmatch(r"[1-9][0-9]{0,31}", topology["systemIdentifier"])
    or not isinstance(topology["serverAddress"], str)
    or isinstance(topology["serverPort"], bool)
    or not isinstance(topology["serverPort"], int)
    or not 1 <= topology["serverPort"] <= 65535
    or not isinstance(topology["databaseName"], str)
    or isinstance(topology["databaseOid"], bool)
    or not isinstance(topology["databaseOid"], int)
    or not isinstance(topology["dataDirectory"], str)
    or not isinstance(topology["walDirectory"], str)
    or not isinstance(topology["tablespaces"], list)
    or len(topology["tablespaces"]) > 32
    or not all(
        isinstance(item, dict)
        and set(item) == {"path", "stDev"}
        and isinstance(item["path"], str)
        and isinstance(item["stDev"], int)
        and not isinstance(item["stDev"], bool)
        for item in topology["tablespaces"]
    )
    or isinstance(topology["dataDevice"], bool)
    or not isinstance(topology["dataDevice"], int)
    or isinstance(topology["walDevice"], bool)
    or not isinstance(topology["walDevice"], int)
):
    raise deny("the database storage topology record failed its schema contract")
try:
    if not ipaddress.ip_address(topology["serverAddress"]).is_loopback:
        raise deny("the database server address is not a loopback address")
except ValueError:
    raise deny("the database server address is not a valid IP address")

def existing_ancestor(path: str) -> str:
    current = os.path.abspath(path)
    while not os.path.exists(current):
        parent = os.path.dirname(current)
        if parent == current:
            break
        current = parent
    return os.path.realpath(current)


def safe_storage_directory(path: str) -> str:
    if (
        not path
        or len(os.fsencode(path)) > 4096
        or not os.path.isabs(path)
        or any(ord(char) < 32 or ord(char) == 127 for char in path)
    ):
        raise deny("a database storage path is empty, relative, over-long, or contains control characters")
    resolved = os.path.realpath(path)
    if not os.path.isabs(resolved) or not os.path.isdir(resolved):
        raise deny("a database storage path does not resolve to an absolute directory")
    if source_only:
        if os.path.commonpath((test_root, resolved)) != test_root:
            raise deny("a database storage path resolves outside the test fixture root")
        return resolved
    details = os.stat(resolved)
    if (
        not stat.S_ISDIR(details.st_mode)
        or details.st_uid == 0
        or details.st_mode & 0o022
    ):
        raise deny("a database storage directory is root-owned or group/world writable")
    return resolved


data_directory = safe_storage_directory(topology["dataDirectory"])
wal_directory = safe_storage_directory(topology["walDirectory"])
tablespaces = [
    safe_storage_directory(item["path"]) for item in topology["tablespaces"]
]
database_paths = list(dict.fromkeys(
    [data_directory, wal_directory, *tablespaces]
))
if (
    os.stat(data_directory).st_dev != topology["dataDevice"]
    or os.stat(wal_directory).st_dev != topology["walDevice"]
    or any(
        os.stat(item["path"]).st_dev != item["stDev"]
        for item in topology["tablespaces"]
    )
):
    raise deny("a database storage directory changed filesystem device during admission")


device_map: dict[str, str] = {}
if source_only and os.environ.get(
    "BRIDGESLLM_UPDATE_TRANSACTION_TEST_DEVICE_MAP"
):
    try:
        parsed_map = json.loads(
            os.environ["BRIDGESLLM_UPDATE_TRANSACTION_TEST_DEVICE_MAP"]
        )
    except ValueError:
        raise deny("the test device map is not valid JSON")
    if (
        not isinstance(parsed_map, dict)
        or not parsed_map
        or not all(
            isinstance(path, str) and isinstance(device, str) and device
            for path, device in parsed_map.items()
        )
    ):
        raise deny("the test device map is malformed")
    device_map = {
        os.path.realpath(path): device for path, device in parsed_map.items()
    }


def device_for(path: str) -> str:
    resolved = os.path.realpath(path)
    matches = [
        (len(prefix), device)
        for prefix, device in device_map.items()
        if os.path.commonpath((prefix, resolved)) == prefix
    ]
    if matches:
        return max(matches)[1]
    return f"dev:{os.stat(existing_ancestor(path)).st_dev}"


def safe_anchor(path: str) -> str:
    anchor = existing_ancestor(path)
    details = os.lstat(anchor)
    if (
        not stat.S_ISDIR(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_mode & 0o022
    ):
        raise deny("a reserve anchor is not a safe directory (missing, a symlink, or group/world writable)")
    return anchor


def database_reserve_anchor(path: str) -> str:
    # Keep the large reserve outside PGDATA/pg_wal/tablespace contents when a
    # safe parent is on the same filesystem. A mount rooted at the PostgreSQL
    # directory necessarily falls back to a hidden root-owned file there.
    if source_only:
        return path
    parent = os.path.realpath(os.path.dirname(path))
    parent_details = os.lstat(parent)
    path_details = os.stat(path)
    if (
        stat.S_ISDIR(parent_details.st_mode)
        and not stat.S_ISLNK(parent_details.st_mode)
        and not parent_details.st_mode & 0o022
        and parent_details.st_dev == path_details.st_dev
    ):
        return parent
    return path


state_parent = os.path.dirname(state_root)
state_parent_details = os.lstat(existing_ancestor(state_parent))
if (
    not stat.S_ISDIR(state_parent_details.st_mode)
    or stat.S_ISLNK(state_parent_details.st_mode)
    or state_parent_details.st_uid != os.geteuid()
    or state_parent_details.st_mode & 0o022
):
    raise deny("the installer journal parent directory is unsafe (wrong owner, a symlink, or group/world writable)")
try:
    os.mkdir(state_root, 0o700)
except FileExistsError:
    pass
state_details = os.lstat(state_root)
if (
    not stat.S_ISDIR(state_details.st_mode)
    or stat.S_ISLNK(state_details.st_mode)
    or state_details.st_uid != os.geteuid()
    or state_details.st_gid != os.getegid()
):
    raise deny("the installer journal directory is unsafe (wrong owner/group, or a symlink)")
if stat.S_IMODE(state_details.st_mode) != 0o700:
    # Older uninstall runs left this root at 0755 because `install -d` only
    # applies its mode to the last component. Refusing on that would strand
    # the host on a permanent, and untrue, disk-space error. A root-owned
    # directory that was never writable by anyone else can be narrowed to
    # 0700 safely; one that was group- or world-writable cannot, because its
    # contents are no longer trustworthy.
    if state_details.st_mode & 0o022:
        raise deny("the installer journal directory is group- or world-writable")
    state_fd = os.open(
        state_root,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        opened = os.fstat(state_fd)
        if (
            opened.st_dev != state_details.st_dev
            or opened.st_ino != state_details.st_ino
        ):
            raise deny("the installer journal directory was replaced during admission")
        os.fchmod(state_fd, 0o700)
        state_details = os.fstat(state_fd)
    finally:
        os.close(state_fd)
    if stat.S_IMODE(state_details.st_mode) != 0o700:
        raise deny("the installer journal directory could not be narrowed to 0700")
    print(
        "update transaction disk admission repaired: "
        f"narrowed {state_root} to 0700"
    )

requirements: dict[str, int] = {}
for path, needed in (
    (backup_root, portal_size + db_size),
    (portal_dir, candidate_size),
    (state_root, STATE_RESERVE_BYTES),
    (stage_root, 0 if staged_portal else candidate_size),
):
    anchor = existing_ancestor(path)
    device = device_for(anchor)
    requirements[device] = requirements.get(device, 0) + needed
for path in database_paths:
    device = device_for(path)
    requirements[device] = requirements.get(device, 0) + db_size

paths = [state_root, backup_root, stage_root, os.path.dirname(portal_dir)]
if staged_portal:
    paths.append(staged_portal)
paths.extend(database_reserve_anchor(path) for path in database_paths)
anchors: dict[str, str] = {}
for path in paths:
    anchor = safe_anchor(path)
    anchors.setdefault(device_for(anchor), anchor)
if set(anchors) != set(requirements):
    raise deny("the reserve anchors do not cover exactly the devices that carry requirements")

reserve_bytes = RECOVERY_RESERVE_BYTES
if source_only and os.environ.get(
    "BRIDGESLLM_UPDATE_TRANSACTION_TEST_RESERVE_BYTES"
):
    reserve_bytes = int(
        os.environ["BRIDGESLLM_UPDATE_TRANSACTION_TEST_RESERVE_BYTES"]
    )
    if (
        not 2 <= reserve_bytes <= RECOVERY_RESERVE_BYTES
        or reserve_bytes % 2
    ):
        raise deny("the test reserve size override is out of range")
tier_bytes = reserve_bytes // 2

test_available: dict[str, int] = {}
if source_only:
    raw_map = os.environ.get(
        "BRIDGESLLM_UPDATE_TRANSACTION_TEST_AVAILABLE_BY_DEVICE"
    )
    raw_single = os.environ.get(
        "BRIDGESLLM_UPDATE_TRANSACTION_TEST_AVAILABLE_BYTES"
    )
    if raw_map:
        try:
            parsed_available = json.loads(raw_map)
        except ValueError:
            raise deny("the test available-space map is not valid JSON")
        if (
            not isinstance(parsed_available, dict)
            or not all(
                isinstance(device, str)
                and isinstance(value, int)
                and value >= 0
                for device, value in parsed_available.items()
            )
        ):
            raise deny("the test available-space map is malformed")
        test_available = parsed_available
    elif raw_single is not None:
        value = int(raw_single)
        if value < 0:
            raise deny("the test available-space value is negative")
        test_available = {device: value for device in requirements}

manifest_path = os.path.join(state_root, "update-disk-reserves.json")


def read_manifest() -> dict[str, object] | None:
    try:
        details = os.lstat(manifest_path)
    except FileNotFoundError:
        return None
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_gid != os.getegid()
        or details.st_nlink != 1
        or stat.S_IMODE(details.st_mode) != 0o600
        or not 1 <= details.st_size <= 64 * 1024
    ):
        raise deny("the existing disk reserve manifest failed its ownership, mode, link-count, or size contract")
    try:
        record = json.loads(open(manifest_path, "rb").read())
    except (OSError, ValueError, SystemExit):
        raise deny("the existing disk reserve manifest is not readable JSON")
    return record


def write_manifest(record: dict[str, object]) -> None:
    payload = (
        json.dumps(
            record, sort_keys=True, separators=(",", ":"), ensure_ascii=True
        )
        + "\n"
    ).encode("ascii")
    if len(payload) > 64 * 1024:
        raise deny("the disk reserve manifest payload exceeds its bounded size")
    descriptor, temporary = tempfile.mkstemp(
        prefix=".update-disk-reserves.", dir=state_root
    )
    try:
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, manifest_path)
        temporary = ""
        directory_fd = os.open(
            state_root,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        )
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass


expected_entries = [
    {
        "device": device,
        "tier": tier,
        "path": os.path.join(
            anchor,
            f".bridgesllm-update-reserve-{tier}-{transaction_id}",
        ),
        "released": False,
    }
    for device, anchor in sorted(anchors.items())
    for tier in ("work", "emergency")
]
topology_payload = json.dumps(
    topology, sort_keys=True, separators=(",", ":"), ensure_ascii=True
).encode("ascii")
topology_sha256 = hashlib.sha256(topology_payload).hexdigest()
record = read_manifest()
reserve_already_held = record is not None
if record is not None:
    if (
        record.get("schema") != "bridgesllm-update-disk-reserve-v2"
        or record.get("state") != "held"
        or record.get("transactionId") != transaction_id
        or record.get("tierBytes") != tier_bytes
        or record.get("databaseSystemIdentifier")
            != topology["systemIdentifier"]
        or record.get("databaseTopologySha256") != topology_sha256
        or record.get("databaseTopology") != topology
        or not isinstance(record.get("entries"), list)
        or [
            {
                "device": entry.get("device"),
                "tier": entry.get("tier"),
                "path": entry.get("path"),
                "released": entry.get("released"),
            }
            for entry in record["entries"]
        ] != expected_entries
    ):
        raise deny("the existing disk reserve manifest does not match this transaction, tier size, database identity, or planned entries")
    for entry in record["entries"]:
        held = os.lstat(entry["path"])
        if (
            not stat.S_ISREG(held.st_mode)
            or stat.S_ISLNK(held.st_mode)
            or held.st_uid != os.geteuid()
            or held.st_gid != os.getegid()
            or held.st_nlink != 1
            or stat.S_IMODE(held.st_mode) != 0o600
            or held.st_size != tier_bytes
            or held.st_dev != entry.get("stDev")
            or held.st_ino != entry.get("stIno")
            or held.st_blocks * 512 < tier_bytes
        ):
            raise deny("a held reserve file no longer matches its manifest entry (owner, mode, size, inode, or allocated blocks)")

for device, anchor in anchors.items():
    details = os.statvfs(anchor)
    available = (
        test_available[device]
        if device in test_available
        else details.f_bavail * details.f_frsize
    )
    required = requirements[device]
    if not reserve_already_held:
        required += reserve_bytes
    if available < required:
        print(
            "update transaction disk admission failed: "
            f"device {device} at {anchor} has {available} bytes available, "
            f"requires {required} "
            f"(short by {required - available} bytes)"
        )
        raise SystemExit(2)

if not reserve_already_held:
    record = {
        "schema": "bridgesllm-update-disk-reserve-v2",
        "state": "allocating",
        "transactionId": transaction_id,
        "tierBytes": tier_bytes,
        "databaseSystemIdentifier": topology["systemIdentifier"],
        "databaseTopologySha256": topology_sha256,
        "databaseTopology": topology,
        "entries": expected_entries,
    }
    write_manifest(record)
    held_entries: list[dict[str, object]] = []
    for planned in expected_entries:
        flags = (
            os.O_WRONLY | os.O_CREAT | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        descriptor = os.open(planned["path"], flags, 0o600)
        try:
            os.fchmod(descriptor, 0o600)
            if hasattr(os, "posix_fallocate"):
                os.posix_fallocate(descriptor, 0, tier_bytes)
            else:
                remaining = tier_bytes
                block = b"\0" * min(1024 * 1024, tier_bytes)
                while remaining:
                    written = os.write(descriptor, block[:remaining])
                    if written <= 0:
                        raise OSError("reserve allocation made no progress")
                    remaining -= written
            os.fsync(descriptor)
            held = os.fstat(descriptor)
            if (
                held.st_size != tier_bytes
                or held.st_blocks * 512 < tier_bytes
            ):
                raise OSError("reserve file is sparse or incomplete")
            held_entries.append({
                **planned,
                "stDev": held.st_dev,
                "stIno": held.st_ino,
            })
        finally:
            os.close(descriptor)
        parent_fd = os.open(
            os.path.dirname(planned["path"]),
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        )
        try:
            os.fsync(parent_fd)
        finally:
            os.close(parent_fd)
    record["state"] = "held"
    record["entries"] = held_entries
    write_manifest(record)

print(
    "update transaction disk admission passed: "
    f"portal={portal_size} candidate={candidate_size} database={db_size} "
    f"devices={len(requirements)} reserve_per_device={reserve_bytes} "
    f"reserve_tier={tier_bytes}"
)
PY2
  UPDATE_DISK_RESERVE_MANIFEST="${state_root}/update-disk-reserves.json"
}

read_update_disk_reserve_database_topology() {
  local expected_transaction_id="$1" state_root manifest
  state_root="$(update_transaction_state_path "${UPDATE_STATE_ROOT}")" \
    || return 1
  manifest="${state_root}/update-disk-reserves.json"
  python3 - "${manifest}" "${expected_transaction_id}" <<'PY2'
import hashlib
import json
import os
import re
import stat
import sys

manifest, expected_transaction_id = sys.argv[1:3]
if re.fullmatch(r"[a-f0-9]{32}", expected_transaction_id) is None:
    raise SystemExit(1)
details = os.lstat(manifest)
if (
    not stat.S_ISREG(details.st_mode)
    or stat.S_ISLNK(details.st_mode)
    or details.st_uid != os.geteuid()
    or details.st_gid != os.getegid()
    or details.st_nlink != 1
    or stat.S_IMODE(details.st_mode) != 0o600
    or not 1 <= details.st_size <= 64 * 1024
):
    raise SystemExit(1)
try:
    record = json.loads(open(manifest, "rb").read())
except (OSError, ValueError):
    raise SystemExit(1)
if (
    not isinstance(record, dict)
    or record.get("schema") != "bridgesllm-update-disk-reserve-v2"
    or record.get("state") not in {
        "held",
        "rearming",
        "recovery-preparing",
        "recovery",
        "emergency-ready",
        "emergency-releasing",
        "emergency-consumed",
    }
    or record.get("transactionId") != expected_transaction_id
    or not isinstance(record.get("databaseTopology"), dict)
    or not isinstance(record.get("databaseSystemIdentifier"), str)
    or re.fullmatch(
        r"[1-9][0-9]{0,31}", record["databaseSystemIdentifier"]
    ) is None
    or not isinstance(record.get("databaseTopologySha256"), str)
    or re.fullmatch(
        r"[a-f0-9]{64}", record["databaseTopologySha256"]
    ) is None
):
    raise SystemExit(1)
payload = json.dumps(
    record["databaseTopology"],
    sort_keys=True,
    separators=(",", ":"),
    ensure_ascii=True,
).encode("ascii")
digest = hashlib.sha256(payload).hexdigest()
if (
    digest != record["databaseTopologySha256"]
    or record["databaseTopology"].get("systemIdentifier")
        != record["databaseSystemIdentifier"]
):
    raise SystemExit(1)
print(record["databaseSystemIdentifier"])
print(digest)
print(payload.decode("ascii"))
PY2
}

assert_update_database_topology_unchanged() {
  local db_url="$1" context="${2:-database-operation}"
  local target transaction_id receipt_system_identifier receipt_digest
  local current_topology
  local -a pinned=()
  target="$(current_update_receipt_target)" || return 1
  transaction_id="$(
    read_update_transaction_field "${target}" transaction_id
  )" || return 1
  receipt_system_identifier="$(
    read_update_transaction_field "${target}" database_system_identifier
  )" || return 1
  receipt_digest="$(
    read_update_transaction_field "${target}" database_topology_sha256
  )" || return 1
  mapfile -t pinned < <(
    read_update_disk_reserve_database_topology "${transaction_id}"
  ) || return 1
  [[ "${#pinned[@]}" -eq 3 \
    && "${pinned[0]}" == "${receipt_system_identifier}" \
    && "${pinned[1]}" == "${receipt_digest}" ]] || return 1
  current_topology="$(canonical_update_database_topology "${db_url}")" \
    || return 1
  python3 - "${pinned[2]}" "${current_topology}" \
    "${receipt_system_identifier}" "${receipt_digest}" "${context}" <<'PY2'
import hashlib
import json
import sys

pinned_raw, current_raw, expected_system_identifier, expected_digest, context = (
    sys.argv[1:6]
)
try:
    pinned = json.loads(pinned_raw)
    current = json.loads(current_raw)
except ValueError:
    raise SystemExit(1)
if not isinstance(pinned, dict) or not isinstance(current, dict):
    raise SystemExit(1)
pinned_payload = json.dumps(
    pinned, sort_keys=True, separators=(",", ":"), ensure_ascii=True
).encode("ascii")
current_payload = json.dumps(
    current, sort_keys=True, separators=(",", ":"), ensure_ascii=True
).encode("ascii")
if (
    hashlib.sha256(pinned_payload).hexdigest() != expected_digest
    or pinned.get("systemIdentifier") != expected_system_identifier
    or current.get("systemIdentifier") != expected_system_identifier
    or current_payload != pinned_payload
):
    print(
        f"database topology changed before {context}; refusing operation",
        file=sys.stderr,
    )
    raise SystemExit(1)
PY2
}

attest_update_database_guard_identity() {
  local observed_json="$1" pinned_json="$2" db_url="$3"
  local current_topology
  current_topology="$(canonical_update_database_topology "${db_url}")" \
    || return 1
  python3 - "${observed_json}" "${pinned_json}" \
    "${current_topology}" <<'PY2'
import hashlib
import ipaddress
import json
import os
import ctypes
import posixpath
import re
import stat
import subprocess
import sys

try:
    observed = json.loads(sys.argv[1])
    pinned = json.loads(sys.argv[2])
    current = json.loads(sys.argv[3])
except ValueError:
    raise SystemExit(1)
if (
    not isinstance(observed, dict)
    or not isinstance(pinned, dict)
    or not isinstance(current, dict)
):
    raise SystemExit(1)
current_payload = json.dumps(
    current, sort_keys=True, separators=(",", ":"), ensure_ascii=True
).encode("ascii")
pinned_payload = json.dumps(
    pinned, sort_keys=True, separators=(",", ":"), ensure_ascii=True
).encode("ascii")
if (
    current_payload != pinned_payload
    or current.get("systemIdentifier") != pinned.get("systemIdentifier")
):
    raise SystemExit(1)
expected_observed = {
    "serverAddress",
    "serverPort",
    "backendPid",
    "backendStart",
    "databaseName",
    "databaseOid",
    "dataDirectory",
    "walDirectory",
    "defaultTablespace",
    "defaultTablespaceOid",
    "tempTablespaces",
    "tablespaces",
    "tablespaceOids",
}
if (
    set(observed) != expected_observed
    or observed.get("tempTablespaces", "").strip()
    or observed.get("dataDirectory") != ""
    or observed.get("walDirectory") != ""
    or observed.get("tablespaces") != []
    or observed.get("databaseName") != pinned.get("databaseName")
    or observed.get("databaseOid") != pinned.get("databaseOid")
    or not isinstance(observed.get("tablespaceOids"), list)
    or not isinstance(observed.get("backendStart"), str)
    or isinstance(observed.get("defaultTablespaceOid"), bool)
    or not isinstance(observed.get("defaultTablespaceOid"), int)
):
    raise SystemExit(1)
default_tablespace = observed.get("defaultTablespace", "").strip()
default_tablespace_oid = observed["defaultTablespaceOid"]
tablespace_oids = observed["tablespaceOids"]
if (
    not all(
        not isinstance(oid, bool)
        and isinstance(oid, int)
        and 1 <= oid <= 4_294_967_295
        for oid in tablespace_oids
    )
    or tablespace_oids != sorted(set(tablespace_oids))
    or not 0 <= default_tablespace_oid <= 4_294_967_295
    or (not default_tablespace and default_tablespace_oid != 0)
    or (
        default_tablespace
        and (
            default_tablespace_oid == 0
            or default_tablespace_oid not in tablespace_oids
        )
    )
):
    raise SystemExit(1)
database_backend_pid = observed.get("backendPid")
server_port = observed.get("serverPort")
try:
    observed_address = ipaddress.ip_address(observed.get("serverAddress", ""))
    expected_address = ipaddress.ip_address(pinned.get("serverAddress", ""))
except ValueError:
    raise SystemExit(1)
if (
    isinstance(database_backend_pid, bool)
    or not isinstance(database_backend_pid, int)
    or database_backend_pid <= 1
    or isinstance(server_port, bool)
    or not isinstance(server_port, int)
    or not 1 <= server_port <= 65535
    or not expected_address.is_loopback
    or isinstance(pinned.get("serverPort"), bool)
    or not isinstance(pinned.get("serverPort"), int)
):
    raise SystemExit(1)


def process_identity(pid):
    root = f"/proc/{pid}"
    details = os.stat(root)
    executable_path = os.path.join(root, "exe")
    executable = os.readlink(executable_path)
    executable_details = os.stat(executable_path)
    process_stat = open(
        os.path.join(root, "stat"), "r", encoding="ascii"
    ).read()
    split = process_stat.rsplit(")", 1)
    if len(split) != 2:
        raise SystemExit(1)
    fields = split[1].strip().split()
    if (
        len(fields) < 20
        or fields[0] in {"Z", "X", "x"}
        or not fields[1].isdigit()
        or not fields[19].isdigit()
        or not os.path.isabs(executable)
        or executable.endswith(" (deleted)")
    ):
        raise SystemExit(1)
    status = open(
        os.path.join(root, "status"), "r", encoding="ascii"
    ).read().splitlines()
    nspid = [line for line in status if line.startswith("NSpid:")]
    if len(nspid) != 1:
        raise SystemExit(1)
    namespace_pids = nspid[0].split()[1:]
    if not namespace_pids or not all(value.isdigit() for value in namespace_pids):
        raise SystemExit(1)
    return {
        "pid": pid,
        "uid": details.st_uid,
        "gid": details.st_gid,
        "procDevice": details.st_dev,
        "procInode": details.st_ino,
        "parentPid": int(fields[1]),
        "startTime": int(fields[19]),
        "executable": executable,
        "executableDevice": executable_details.st_dev,
        "executableInode": executable_details.st_ino,
        "namespacePids": tuple(int(value) for value in namespace_pids),
        "namespaces": tuple(
            os.stat(os.path.join(root, "ns", name)).st_ino
            for name in ("pid", "mnt", "net")
        ),
    }


def postgres_pair(backend, postmaster):
    return (
        backend["parentPid"] == postmaster["pid"]
        and backend["uid"] == postmaster["uid"]
        and backend["gid"] == postmaster["gid"]
        and backend["uid"] != 0
        and backend["namespaces"] == postmaster["namespaces"]
        and os.path.basename(backend["executable"]) in {"postgres", "postmaster"}
        and os.path.basename(postmaster["executable"]) in {"postgres", "postmaster"}
        and (
            backend["executableDevice"], backend["executableInode"]
        ) == (
            postmaster["executableDevice"], postmaster["executableInode"]
        )
    )


def docker_records():
    docker = "/usr/bin/docker"
    details = os.lstat(docker)
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != 0
        or details.st_mode & 0o022
    ):
        raise SystemExit(1)
    listed = subprocess.run(
        [docker, "ps", "--quiet", "--no-trunc"],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        env={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
        text=True,
        timeout=10,
        check=False,
    )
    identifiers = [line.strip() for line in listed.stdout.splitlines()]
    if (
        listed.returncode != 0
        or len(listed.stdout) > 16 * 1024
        or len(identifiers) > 128
        or any(re.fullmatch(r"[a-f0-9]{64}", value) is None
               for value in identifiers)
    ):
        raise SystemExit(1)
    if not identifiers:
        return []
    inspected = subprocess.run(
        [docker, "inspect", *identifiers],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        env={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
        text=True,
        timeout=20,
        check=False,
    )
    if inspected.returncode != 0 or len(inspected.stdout) > 8 * 1024 * 1024:
        raise SystemExit(1)
    try:
        records = json.loads(inspected.stdout)
    except ValueError:
        raise SystemExit(1)
    if not isinstance(records, list):
        raise SystemExit(1)
    return records


records = None
self_namespaces = tuple(
    os.stat(f"/proc/self/ns/{name}").st_ino for name in ("pid", "mnt", "net")
)
candidates = []
for entry in os.listdir("/proc"):
    if not entry.isdigit():
        continue
    try:
        backend_candidate = process_identity(int(entry))
    except (OSError, ValueError, SystemExit):
        continue
    if backend_candidate["namespacePids"][-1] != database_backend_pid:
        continue
    try:
        postmaster_candidate = process_identity(
            backend_candidate["parentPid"]
        )
    except (OSError, ValueError, SystemExit):
        continue
    if not postgres_pair(backend_candidate, postmaster_candidate):
        continue

    container = None
    if backend_candidate["namespaces"] == self_namespaces:
        if (
            not observed_address.is_loopback
            or observed_address != expected_address
            or server_port != pinned["serverPort"]
        ):
            continue
    else:
        if records is None:
            records = docker_records()
        namespace_matches = []
        for record in records:
            if not isinstance(record, dict):
                raise SystemExit(1)
            state = record.get("State")
            init_pid = state.get("Pid") if isinstance(state, dict) else None
            if (
                not isinstance(state, dict)
                or state.get("Running") is not True
                or isinstance(init_pid, bool)
                or not isinstance(init_pid, int)
                or init_pid <= 1
            ):
                continue
            try:
                namespaces = tuple(
                    os.stat(f"/proc/{init_pid}/ns/{name}").st_ino
                    for name in ("pid", "mnt", "net")
                )
            except OSError:
                continue
            if namespaces == backend_candidate["namespaces"]:
                namespace_matches.append(record)
        if len(namespace_matches) != 1:
            continue
        container = namespace_matches[0]
        network = container.get("NetworkSettings")
        ports = network.get("Ports") if isinstance(network, dict) else None
        bindings = (
            ports.get(f"{server_port}/tcp")
            if isinstance(ports, dict)
            else None
        )
        exact_bindings = []
        if isinstance(bindings, list) and len(bindings) == 1:
            for binding in bindings:
                if not isinstance(binding, dict):
                    continue
                try:
                    bind_address = ipaddress.ip_address(
                        binding.get("HostIp", "")
                    )
                    bind_port = int(binding.get("HostPort", ""))
                except (ValueError, TypeError):
                    continue
                if (
                    bind_address == expected_address
                    and bind_address.is_loopback
                    and bind_port == pinned["serverPort"]
                ):
                    exact_bindings.append(binding)
        container_addresses = set()
        networks = network.get("Networks") if isinstance(network, dict) else None
        if isinstance(networks, dict):
            for value in networks.values():
                if not isinstance(value, dict):
                    continue
                for field in ("IPAddress", "GlobalIPv6Address"):
                    raw_address = value.get(field)
                    if raw_address:
                        container_addresses.add(
                            ipaddress.ip_address(raw_address)
                        )
        if (
            len(exact_bindings) != 1
            or observed_address not in container_addresses
        ):
            continue
    candidates.append((backend_candidate, postmaster_candidate, container))

if len(candidates) != 1:
    raise SystemExit(1)
backend, postmaster, container = candidates[0]
backend_pid = backend["pid"]
postmaster_pid = postmaster["pid"]

namespace_data_directory = posixpath.normpath(
    os.readlink(f"/proc/{postmaster_pid}/cwd")
)
if (
    not posixpath.isabs(namespace_data_directory)
    or namespace_data_directory == "/"
):
    raise SystemExit(1)
data_directory = os.path.realpath(pinned["dataDirectory"])
if container is None:
    candidate_data_directory = os.path.realpath(namespace_data_directory)
else:
    mounts = container.get("Mounts")
    if not isinstance(mounts, list):
        raise SystemExit(1)
    mapped = []
    for mount in mounts:
        if (
            not isinstance(mount, dict)
            or mount.get("Type") not in {"bind", "volume"}
            or mount.get("RW") is not True
        ):
            continue
        source = mount.get("Source")
        destination = mount.get("Destination")
        if not isinstance(source, str) or not isinstance(destination, str):
            raise SystemExit(1)
        destination = posixpath.normpath(destination)
        if (
            namespace_data_directory == destination
            or namespace_data_directory.startswith(destination + "/")
        ):
            relative = posixpath.relpath(
                namespace_data_directory, destination
            )
            mapped.append(
                (
                    len(destination),
                    source if relative == "." else os.path.join(
                        source, *relative.split("/")
                    ),
                )
            )
    if not mapped:
        raise SystemExit(1)
    mapped.sort(reverse=True)
    candidate_data_directory = os.path.realpath(mapped[0][1])
    namespace_details = os.stat(
        f"/proc/{postmaster_pid}/root{namespace_data_directory}"
    )
    host_details = os.stat(candidate_data_directory)
    if (
        namespace_details.st_dev != host_details.st_dev
        or namespace_details.st_ino != host_details.st_ino
    ):
        raise SystemExit(1)
if candidate_data_directory != data_directory:
    raise SystemExit(1)

postmaster_path = os.path.join(data_directory, "postmaster.pid")
postmaster_details = os.lstat(postmaster_path)
if (
    not stat.S_ISREG(postmaster_details.st_mode)
    or stat.S_ISLNK(postmaster_details.st_mode)
    or postmaster_details.st_nlink != 1
    or postmaster_details.st_uid != postmaster["uid"]
    or postmaster_details.st_gid != postmaster["gid"]
    or postmaster_details.st_mode & 0o022
    or postmaster["uid"] != os.stat(data_directory).st_uid
):
    raise SystemExit(1)
lines = open(postmaster_path, "r", encoding="ascii").read().splitlines()
if (
    len(lines) < 4
    or not lines[0].isdigit()
    or int(lines[0]) != postmaster["namespacePids"][-1]
    or posixpath.normpath(lines[1]) != namespace_data_directory
    or not lines[3].isdigit()
    or int(lines[3]) != server_port
):
    raise SystemExit(1)

# A separate full canonical proof above has already re-read pg_controldata
# from this exact persistent data directory. The held guard backend is bound
# here to the same postmaster, namespace, endpoint, database OID, and mapped
# data inode; its host PID can now be watched with pidfd for the operation.
boot_id = open(
    "/proc/sys/kernel/random/boot_id", "r", encoding="ascii"
).read().strip()
token = {
    "bootId": boot_id,
    "dataDirectory": data_directory,
    "postmasterPid": postmaster_pid,
    "postmasterStartTime": postmaster["startTime"],
    "postmasterExecutableDevice": postmaster["executableDevice"],
    "postmasterExecutableInode": postmaster["executableInode"],
    "postmasterPidFileDevice": postmaster_details.st_dev,
    "postmasterPidFileInode": postmaster_details.st_ino,
    "postmasterPidFileUid": postmaster_details.st_uid,
    "postmasterPidFileGid": postmaster_details.st_gid,
    "postmasterPidFileMode": stat.S_IMODE(postmaster_details.st_mode),
    "databaseBackendPid": database_backend_pid,
    "backendPid": backend_pid,
    "backendStartTime": backend["startTime"],
    "backendExecutableDevice": backend["executableDevice"],
    "backendExecutableInode": backend["executableInode"],
}
print(json.dumps(token, sort_keys=True, separators=(",", ":")))
PY2
}

verify_update_database_guard_identity() {
  local expected_token="$1"
  python3 - "${expected_token}" <<'PY2'
import json
import os
import re
import secrets
import stat
import sys
import time

try:
    expected = json.loads(sys.argv[1])
except ValueError:
    raise SystemExit(1)
required = {
    "bootId",
    "dataDirectory",
    "postmasterPid",
    "postmasterStartTime",
    "postmasterExecutableDevice",
    "postmasterExecutableInode",
    "postmasterPidFileDevice",
    "postmasterPidFileInode",
    "postmasterPidFileUid",
    "postmasterPidFileGid",
    "postmasterPidFileMode",
    "databaseBackendPid",
    "backendPid",
    "backendStartTime",
    "backendExecutableDevice",
    "backendExecutableInode",
}
if not isinstance(expected, dict) or set(expected) != required:
    raise SystemExit(1)
if (
    isinstance(expected["databaseBackendPid"], bool)
    or not isinstance(expected["databaseBackendPid"], int)
    or not 1 < expected["databaseBackendPid"] <= 2_147_483_647
):
    raise SystemExit(1)
if (
    open("/proc/sys/kernel/random/boot_id", "r", encoding="ascii").read().strip()
    != expected["bootId"]
):
    raise SystemExit(1)


def current_process(pid):
    root = f"/proc/{pid}"
    executable_details = os.stat(os.path.join(root, "exe"))
    process_stat = open(
        os.path.join(root, "stat"), "r", encoding="ascii"
    ).read()
    split = process_stat.rsplit(")", 1)
    if len(split) != 2:
        raise SystemExit(1)
    fields = split[1].strip().split()
    if (
        len(fields) < 20
        or fields[0] in {"Z", "X", "x"}
        or not fields[1].isdigit()
        or not fields[19].isdigit()
    ):
        raise SystemExit(1)
    return (
        int(fields[1]),
        int(fields[19]),
        executable_details.st_dev,
        executable_details.st_ino,
    )


postmaster = current_process(expected["postmasterPid"])
backend = current_process(expected["backendPid"])
if (
    postmaster[1:] != (
        expected["postmasterStartTime"],
        expected["postmasterExecutableDevice"],
        expected["postmasterExecutableInode"],
    )
    or backend != (
        expected["postmasterPid"],
        expected["backendStartTime"],
        expected["backendExecutableDevice"],
        expected["backendExecutableInode"],
    )
):
    raise SystemExit(1)
postmaster_path = os.path.join(expected["dataDirectory"], "postmaster.pid")
details = os.lstat(postmaster_path)
if (
    not stat.S_ISREG(details.st_mode)
    or stat.S_ISLNK(details.st_mode)
    or details.st_nlink != 1
    or details.st_uid != expected["postmasterPidFileUid"]
    or details.st_gid != expected["postmasterPidFileGid"]
    or stat.S_IMODE(details.st_mode) != expected["postmasterPidFileMode"]
    or details.st_mode & 0o022
    or details.st_dev != expected["postmasterPidFileDevice"]
    or details.st_ino != expected["postmasterPidFileInode"]
):
    raise SystemExit(1)
PY2
}

start_update_database_guard_pidfd_watchdog() {
  local expected_token="$1"
  local ready_path="${UPDATE_DATABASE_OPERATION_GUARD_DIR}/watchdog.ready"
  local watchdog_expected_parent="${BASHPID}"
  rm -f -- "${ready_path}"
  python3 - "${watchdog_expected_parent}" \
    "${expected_token}" "${ready_path}" <<'PY2' &
import json
import ctypes
import os
import select
import signal
import sys
import time

try:
    parent_pid = int(sys.argv[1])
except ValueError:
    raise SystemExit(92)
expected = json.loads(sys.argv[2])
ready_path = sys.argv[3]
libc = ctypes.CDLL(None, use_errno=True)
if libc.prctl(1, signal.SIGKILL, 0, 0, 0) != 0:
    raise SystemExit(92)
if os.getppid() != parent_pid:
    os.kill(os.getpid(), signal.SIGKILL)
postmaster_fd = os.pidfd_open(expected["postmasterPid"], 0)
backend_fd = os.pidfd_open(expected["backendPid"], 0)
poller = select.poll()
poller.register(postmaster_fd, select.POLLIN | select.POLLERR | select.POLLHUP)
poller.register(backend_fd, select.POLLIN | select.POLLERR | select.POLLHUP)
ready_fd = os.open(
    ready_path,
    os.O_WRONLY | os.O_CREAT | os.O_EXCL
    | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    0o600,
)
os.write(ready_fd, b"BRIDGESLLM_A009_WATCHDOG_READY\n")
os.close(ready_fd)
signal.signal(signal.SIGTERM, lambda _signal, _frame: raise_exit())


def raise_exit():
    raise SystemExit(0)


try:
    while True:
        if poller.poll(100):
            raise SystemExit(92)
        time.sleep(0.05)
finally:
    os.close(postmaster_fd)
    os.close(backend_fd)
PY2
  UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID=$!
  local attempt marker=""
  for attempt in {1..100}; do
    marker="$(cat "${ready_path}" 2>/dev/null || true)"
    [[ "${marker}" == "BRIDGESLLM_A009_WATCHDOG_READY" ]] && break
    update_database_guard_process_is_live \
      "${UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID}" 2>/dev/null || break
    sleep 0.05
  done
  rm -f -- "${ready_path}"
  [[ "${marker}" == "BRIDGESLLM_A009_WATCHDOG_READY" ]] \
    && update_database_guard_process_is_live \
      "${UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID}"
}

cleanup_update_database_operation_guard() {
  if [[ -n "${UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD:-}" ]]; then
    printf '%s\n' '\q' >&"${UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD}" \
      2>/dev/null || true
    eval "exec ${UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD}>&-" || true
  fi
  if [[ -n "${UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID:-}" ]]; then
    kill -TERM "${UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID}" 2>/dev/null \
      || true
    wait "${UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID}" 2>/dev/null || true
  fi
  if [[ -n "${UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID:-}" ]]; then
    kill -TERM "${UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID}" 2>/dev/null \
      || true
    wait "${UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID}" 2>/dev/null || true
  fi
  if [[ -n "${UPDATE_DATABASE_OPERATION_GUARD_DIR:-}" \
    && "${UPDATE_DATABASE_OPERATION_GUARD_DIR}" == \
      "${TMPDIR:-/tmp}"/blp-update-dbguard.* ]]; then
    rm -rf -- "${UPDATE_DATABASE_OPERATION_GUARD_DIR}"
  fi
  UPDATE_DATABASE_OPERATION_GUARD_DIR=""
  UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID=""
  UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID=""
  UPDATE_DATABASE_OPERATION_GUARD_BACKEND_PID=""
  UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD=""
  UPDATE_DATABASE_OPERATION_GUARD_IDENTITY=""
  UPDATE_DATABASE_OPERATION_GUARD_INITIAL_TOPOLOGY=""
}

start_update_database_operation_guard() {
  local db_url="$1" context="$2" connection_url fifo output
  local target transaction_id marker="" observed="" identity=""
  local -a pinned=()
  assert_update_database_topology_unchanged \
    "${db_url}" "${context}-guard-start" || return 1
  target="$(current_update_receipt_target)" || return 1
  transaction_id="$(
    read_update_transaction_field "${target}" transaction_id
  )" || return 1
  mapfile -t pinned < <(
    read_update_disk_reserve_database_topology "${transaction_id}"
  ) || return 1
  [[ "${#pinned[@]}" -eq 3 ]] || return 1
  connection_url="$(libpq_database_url "${db_url}")" || return 1
  UPDATE_DATABASE_OPERATION_GUARD_DIR="$(
    mktemp -d "${TMPDIR:-/tmp}/blp-update-dbguard.XXXXXX"
  )" || return 1
  chmod 0700 "${UPDATE_DATABASE_OPERATION_GUARD_DIR}"
  fifo="${UPDATE_DATABASE_OPERATION_GUARD_DIR}/input"
  output="${UPDATE_DATABASE_OPERATION_GUARD_DIR}/output"
  mkfifo -m 0600 "${fifo}" \
    || { cleanup_update_database_operation_guard; return 1; }
  : >"${output}"
  chmod 0600 "${output}"
  BRIDGESLLM_UPDATE_PGPASS_EXEC=1 \
    BRIDGESLLM_UPDATE_PGPASS_MINIMAL_ENV=1 \
    PGAPPNAME=bridgesllm-update-guard \
    run_with_update_pgpass "${db_url}" \
      stdbuf -oL psql --dbname="${connection_url}" --no-psqlrc -qAt \
      -v ON_ERROR_STOP=1 <"${fifo}" >"${output}" 2>>"${LOG_FILE}" &
  UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID=$!
  exec {UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD}>"${fifo}" \
    || { cleanup_update_database_operation_guard; return 1; }
  printf '%s\n' \
    "SELECT 'BRIDGESLLM_A009_GUARD_READY';" \
    >&"${UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD}"
  update_database_storage_sql >&"${UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD}"
  local attempt
  for attempt in {1..100}; do
    marker="$(sed -n '1p' "${output}" 2>/dev/null || true)"
    observed="$(sed -n '2p' "${output}" 2>/dev/null || true)"
    [[ "${marker}" == "BRIDGESLLM_A009_GUARD_READY" && -n "${observed}" ]] \
      && break
    update_database_guard_process_is_live \
      "${UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID}" 2>/dev/null \
      || break
    sleep 0.05
  done
  [[ "${marker}" == "BRIDGESLLM_A009_GUARD_READY" \
    && -n "${observed}" && "${#observed}" -le 65536 ]] \
    || { cleanup_update_database_operation_guard; return 1; }
  identity="$(attest_update_database_guard_identity \
    "${observed}" "${pinned[2]}" "${db_url}")" \
    || { cleanup_update_database_operation_guard; return 1; }
  UPDATE_DATABASE_OPERATION_GUARD_IDENTITY="${identity}"
  UPDATE_DATABASE_OPERATION_GUARD_INITIAL_TOPOLOGY="${observed}"
  UPDATE_DATABASE_OPERATION_GUARD_BACKEND_PID="$(
    python3 - "${identity}" <<'PY2'
import json
import sys
print(json.loads(sys.argv[1])["databaseBackendPid"])
PY2
  )" || { cleanup_update_database_operation_guard; return 1; }
  start_update_database_guard_pidfd_watchdog "${identity}" \
    || { cleanup_update_database_operation_guard; return 1; }
}

finish_update_database_operation_guard() {
  local db_url="$1" context="$2" output marker="" observed="" identity=""
  output="${UPDATE_DATABASE_OPERATION_GUARD_DIR}/output"
  verify_update_database_guard_identity \
    "${UPDATE_DATABASE_OPERATION_GUARD_IDENTITY}" || return 1
  printf '%s\n' \
    "SELECT 'BRIDGESLLM_A009_GUARD_FINAL';" \
    >&"${UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD}" || return 1
  update_database_storage_sql >&"${UPDATE_DATABASE_OPERATION_GUARD_INPUT_FD}" \
    || return 1
  local attempt
  for attempt in {1..100}; do
    marker="$(sed -n '3p' "${output}" 2>/dev/null || true)"
    observed="$(sed -n '4p' "${output}" 2>/dev/null || true)"
    [[ "${marker}" == "BRIDGESLLM_A009_GUARD_FINAL" && -n "${observed}" ]] \
      && break
    kill -0 "${UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID}" 2>/dev/null \
      || break
    sleep 0.05
  done
  [[ "${marker}" == "BRIDGESLLM_A009_GUARD_FINAL" \
    && -n "${observed}" \
    && "${observed}" == "${UPDATE_DATABASE_OPERATION_GUARD_INITIAL_TOPOLOGY}" ]] \
    || return 1
  local target transaction_id
  local -a pinned=()
  target="$(current_update_receipt_target)" || return 1
  transaction_id="$(
    read_update_transaction_field "${target}" transaction_id
  )" || return 1
  mapfile -t pinned < <(
    read_update_disk_reserve_database_topology "${transaction_id}"
  ) || return 1
  [[ "${#pinned[@]}" -eq 3 ]] || return 1
  identity="$(attest_update_database_guard_identity \
    "${observed}" "${pinned[2]}" "${db_url}")" || return 1
  [[ "${identity}" == "${UPDATE_DATABASE_OPERATION_GUARD_IDENTITY}" ]] \
    || return 1
  assert_update_database_topology_unchanged \
    "${db_url}" "${context}-guard-complete"
}

update_database_operation_supervisor_python() {
  cat <<'PY2'
import ctypes
import os
import re
import signal
import sys

try:
    original_parent = int(sys.argv[1])
except (IndexError, ValueError):
    raise SystemExit(92)
libc = ctypes.CDLL(None, use_errno=True)
if libc.prctl(1, signal.SIGTERM, 0, 0, 0) != 0:
    raise SystemExit(92)
if os.getppid() != original_parent:
    os.kill(os.getpid(), signal.SIGKILL)

context, ready_fifo, start_fifo, completion_path = sys.argv[2:6]
command = sys.argv[6:]
if not command:
    raise SystemExit(92)


def host_process_start_time(pid):
    text = open(f"/proc/{pid}/stat", "r", encoding="ascii").read()
    split = text.rsplit(")", 1)
    if len(split) != 2:
        raise SystemExit(92)
    fields = split[1].strip().split()
    if len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
        raise SystemExit(92)
    return int(fields[19])


def write_completion(supervisor_pid, supervisor_start, status):
    payload = (
        "BRIDGESLLM_A009_OPERATION_COMPLETE_V1 "
        f"{supervisor_pid} {supervisor_start} {status}\n"
    ).encode("ascii")
    flags = (
        os.O_WRONLY
        | os.O_CREAT
        | os.O_EXCL
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor = os.open(completion_path, flags, 0o600)
    try:
        os.fchmod(descriptor, 0o600)
        if os.write(descriptor, payload) != len(payload):
            raise OSError("short completion write")
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
    directory = os.open(
        os.path.dirname(completion_path),
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        os.fsync(directory)
    finally:
        os.close(directory)


# Put the destructive command in a private PID namespace whose init process is
# the descendant supervisor below. Linux kills every remaining process in a
# PID namespace if its init dies, including setsid()/double-fork escape
# attempts. The small outer monitor is the exact process tracked by the shell;
# its death also SIGKILLs the namespace init through PDEATHSIG.
outer_supervisor_pid = os.getpid()
outer_supervisor_start = host_process_start_time(outer_supervisor_pid)
CLONE_NEWPID = 0x20000000
if libc.unshare(CLONE_NEWPID) != 0:
    raise SystemExit(92)
namespace_init_host_pid = os.fork()
if namespace_init_host_pid != 0:
    os.close(3)
    while True:
        try:
            _waited, namespace_status = os.waitpid(namespace_init_host_pid, 0)
            break
        except InterruptedError:
            continue
    if os.WIFEXITED(namespace_status):
        outer_status = os.WEXITSTATUS(namespace_status)
    elif os.WIFSIGNALED(namespace_status):
        outer_status = 128 + os.WTERMSIG(namespace_status)
    else:
        outer_status = 92
    # waitpid above reaped PID-namespace init. The kernel guarantees every
    # other member was killed before namespace init could disappear.
    write_completion(
        outer_supervisor_pid, outer_supervisor_start, outer_status
    )
    raise SystemExit(outer_status)

if libc.prctl(1, signal.SIGKILL, 0, 0, 0) != 0:
    raise SystemExit(92)
host_stat = open("/proc/self/stat", "r", encoding="ascii").read()
host_fields = host_stat.rsplit(")", 1)[1].strip().split()
if (
    len(host_fields) < 20
    or host_fields[0] in {"Z", "X", "x"}
    or int(host_fields[1]) != outer_supervisor_pid
):
    os.kill(os.getpid(), signal.SIGKILL)
operation_root_pid = int(host_stat.split("(", 1)[0].strip())
if libc.prctl(36, 1, 0, 0, 0) != 0:  # PR_SET_CHILD_SUBREAPER
    raise SystemExit(92)

import json
import time
from urllib.parse import unquote, urlsplit

raw_parts = []
raw_size = 0
while True:
    part = os.read(3, min(65536, 128001 - raw_size))
    if not part:
        break
    raw_parts.append(part)
    raw_size += len(part)
    if raw_size > 128000:
        raise SystemExit(92)
os.close(3)
raw_bytes = b"".join(raw_parts)
try:
    database_url = raw_bytes.decode("utf-8")
except UnicodeDecodeError:
    raise SystemExit(92)
if database_url.endswith("\n"):
    database_url = database_url[:-1]
if not database_url or "#" in database_url or re.search(
    r"%(?![0-9A-Fa-f]{2})", database_url
) or any(
    ord(character) < 32 or ord(character) == 127
    for character in database_url
):
    raise SystemExit(92)


def pgpass_payload(raw):
    try:
        parsed = urlsplit(raw)
        _, separator, host_part = parsed.netloc.rpartition("@")
        host = unquote(parsed.hostname or "", errors="strict")
        port_number = 5432 if parsed.port is None else parsed.port
        database = unquote((parsed.path or "").lstrip("/"), errors="strict")
        user = unquote(parsed.username or "", errors="strict")
        password = unquote(parsed.password or "", errors="strict")
        decoded_host_part = unquote(host_part, errors="strict")
        raw_port_suffix = (
            host_part[host_part.find("]") + 1:]
            if host_part.startswith("[")
            else f":{host_part.rsplit(':', 1)[1]}" if ":" in host_part else ""
        )
    except (UnicodeDecodeError, ValueError):
        raise SystemExit(92)
    forbidden = {
        "password", "sslpassword", "passfile", "service", "servicefile",
        "host", "hostaddr", "port", "user", "dbname", "database",
    }
    for raw_pair in parsed.query.split("&") if parsed.query else ():
        if "+" in raw_pair:
            raise SystemExit(92)
        raw_key, pair_separator, raw_value = raw_pair.partition("=")
        if "=" in raw_value:
            raise SystemExit(92)
        try:
            key = unquote(raw_key, errors="strict").lower()
            value = unquote(raw_value, errors="strict")
        except UnicodeDecodeError:
            raise SystemExit(92)
        if (
            not pair_separator
            or not key
            or key in forbidden
            or any(
                ord(character) < 32 or ord(character) == 127
                for value_part in (key, value)
                for character in value_part
            )
        ):
            raise SystemExit(92)
    if (
        parsed.scheme not in {"postgres", "postgresql"}
        or parsed.fragment
        or re.search(
            r"%(?:23|24|26|2b|2c|2f|3a|3b|3d|3f|40)",
            parsed.path,
            re.I,
        )
        or not parsed.path.startswith("/")
        or parsed.path.count("/") != 1
        or database in {".", ".."}
        or "/" in database
        or not separator
        or parsed.netloc.count("@") != 1
        or host_part.startswith("[")
        or not 1 <= port_number <= 65535
        or "," in decoded_host_part
        or (raw_port_suffix
            and not re.fullmatch(r":[1-9][0-9]*", raw_port_suffix))
        or "%" in host
        or "%" in (parsed.hostname or "")
        or re.search(r"[<>\\^|]", host)
        or host_part != host_part.lower()
        or not host.isascii()
        or any(character.isspace() for character in host)
    ):
        raise SystemExit(92)
    values = (host, str(port_number), database, user, password)
    if not all(values) or any(
        ord(character) < 32 or ord(character) == 127
        for value in values
        for character in value
    ):
        raise SystemExit(92)
    escape = lambda value: value.replace("\\", "\\\\").replace(":", "\\:")
    return (":".join(escape(value) for value in values) + "\n").encode()


def process_start_time(pid):
    text = open(f"/proc/{pid}/stat", "r", encoding="ascii").read()
    split = text.rsplit(")", 1)
    if len(split) != 2:
        raise SystemExit(92)
    fields = split[1].strip().split()
    if len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
        raise SystemExit(92)
    return int(fields[19])


os.setsid()
supervisor_pid = outer_supervisor_pid
supervisor_start = process_start_time(supervisor_pid)
stop_requested = 0


def request_stop(signal_number, _frame):
    global stop_requested
    stop_requested = signal_number


for handled_signal in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP):
    signal.signal(handled_signal, request_stop)

child_pid = os.fork()
if child_pid == 0:
    os.setpgid(0, 0)
    if libc.prctl(1, signal.SIGKILL, 0, 0, 0) != 0:
        os._exit(92)
    child_stat = open("/proc/self/stat", "r", encoding="ascii").read()
    child_fields = child_stat.rsplit(")", 1)[1].strip().split()
    if (
        len(child_fields) < 20
        or child_fields[0] in {"Z", "X", "x"}
        or int(child_fields[1]) != operation_root_pid
    ):
        os.kill(os.getpid(), signal.SIGKILL)
    child_pid = int(child_stat.split("(", 1)[0].strip())
    metadata = {
        "schema": "bridgesllm-update-operation-ready-v1",
        "supervisorPid": supervisor_pid,
        "supervisorStartTime": supervisor_start,
        "childPid": child_pid,
        "childStartTime": int(child_fields[19]),
        "childPgid": int(child_fields[2]),
    }
    try:
        descriptor = os.open(
            ready_fifo, os.O_WRONLY | getattr(os, "O_CLOEXEC", 0)
        )
        os.write(
            descriptor,
            (
                json.dumps(metadata, sort_keys=True, separators=(",", ":"))
                + "\n"
            ).encode("ascii"),
        )
        os.close(descriptor)
        descriptor = os.open(
            start_fifo, os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        )
        token = b""
        while not token.endswith(b"\n") and len(token) <= 16:
            part = os.read(descriptor, 16)
            if not part:
                break
            token += part
        os.close(descriptor)
        if token != b"START\n":
            os._exit(92)
        environment = os.environ.copy()
        environment.pop("DATABASE_URL", None)
        for key in tuple(environment):
            if key.startswith("PG") and key != "PGAPPNAME":
                environment.pop(key, None)
        if context in {"prisma-migrate", "prisma-schema-diff"}:
            environment["DATABASE_URL"] = database_url
        else:
            payload = pgpass_payload(database_url)
            credential_fd = os.memfd_create("bridgesllm-pgpass", 0)
            os.fchmod(credential_fd, 0o600)
            if os.write(credential_fd, payload) != len(payload):
                os._exit(92)
            os.lseek(credential_fd, 0, os.SEEK_SET)
            os.set_inheritable(credential_fd, True)
            environment["PGPASSFILE"] = f"/proc/self/fd/{credential_fd}"
        os.execvpe(command[0], command, environment)
    except BaseException:
        os._exit(92)


def process_identity(pid):
    text = open(f"/proc/{pid}/stat", "r", encoding="ascii").read()
    split = text.rsplit(")", 1)
    if len(split) != 2:
        raise ProcessLookupError
    fields = split[1].strip().split()
    if len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
        raise ProcessLookupError
    return (
        int(fields[1]),
        int(fields[2]),
        int(fields[3]),
        int(fields[19]),
    )


def owned_members():
    identities = {}
    for entry in os.scandir("/proc"):
        if not entry.name.isdigit():
            continue
        try:
            pid = int(entry.name)
            if pid == operation_root_pid:
                continue
            identities[pid] = process_identity(pid)
        except (
            FileNotFoundError,
            PermissionError,
            ProcessLookupError,
            ValueError,
        ):
            continue
    # The supervisor is a child subreaper. A recursive PPID closure covers
    # ordinary children, setsid()/setpgid() escape attempts, and double-forked
    # descendants once they are reparented to this exact supervisor.
    parents = {operation_root_pid}
    members = {}
    changed = True
    while changed:
        changed = False
        for pid, (ppid, _pgid, _sid, start_time) in identities.items():
            if pid not in members and ppid in parents:
                members[pid] = start_time
                parents.add(pid)
                changed = True
    return sorted(members.items())


def group_exists():
    return bool(owned_members())


def reap_nonblocking():
    result = None
    while True:
        try:
            waited_pid, status = os.waitpid(-1, os.WNOHANG)
        except ChildProcessError:
            return result
        if waited_pid == 0:
            return result
        if waited_pid == child_pid:
            result = status


def settle_descendants(force):
    signal_number = signal.SIGKILL if force else signal.SIGTERM
    members = dict(owned_members())
    for pid, expected_start in sorted(members.items(), reverse=True):
        descriptor = None
        try:
            descriptor = os.pidfd_open(pid, 0)
            if dict(owned_members()).get(pid) != expected_start:
                continue
            signal.pidfd_send_signal(descriptor, signal_number)
        except (FileNotFoundError, PermissionError, ProcessLookupError, OSError):
            continue
        finally:
            if descriptor is not None:
                os.close(descriptor)


def drain_descendants():
    settle_descendants(False)
    deadline = time.monotonic() + 3.0
    while time.monotonic() < deadline:
        reap_nonblocking()
        if not group_exists():
            return True
        settle_descendants(False)
        time.sleep(0.05)
    settle_descendants(True)
    deadline = time.monotonic() + 3.0
    while time.monotonic() < deadline:
        reap_nonblocking()
        if not group_exists():
            return True
        settle_descendants(True)
        time.sleep(0.05)
    reap_nonblocking()
    return not group_exists()


child_status = None
while child_status is None and not stop_requested:
    try:
        waited_pid, status = os.waitpid(child_pid, os.WNOHANG)
    except ChildProcessError:
        break
    if waited_pid == child_pid:
        child_status = status
        break
    time.sleep(0.05)

unexpected_tree = group_exists()
daemonized = child_status is not None and unexpected_tree
if (stop_requested or unexpected_tree) and not drain_descendants():
    raise SystemExit(92)
reap_nonblocking()
if group_exists():
    raise SystemExit(92)
if stop_requested:
    final_status = 128 + stop_requested
elif daemonized:
    final_status = 92
elif child_status is None:
    final_status = 92
elif os.WIFEXITED(child_status):
    final_status = os.WEXITSTATUS(child_status)
elif os.WIFSIGNALED(child_status):
    final_status = 128 + os.WTERMSIG(child_status)
else:
    final_status = 92
raise SystemExit(final_status)
PY2
}

update_database_process_matches() {
  local pid="$1" start_time="$2" expected_pgid="${3:-}" expected_sid="${4:-}"
  python3 - "${pid}" "${start_time}" "${expected_pgid}" "${expected_sid}" <<'PY2'
import os
import sys

pid_text, expected_start, expected_pgid, expected_sid = sys.argv[1:]
if not pid_text.isdigit() or not expected_start.isdigit():
    raise SystemExit(1)
pid = int(pid_text)
if pid <= 1:
    raise SystemExit(1)
text = open(f"/proc/{pid}/stat", "r", encoding="ascii").read()
split = text.rsplit(")", 1)
if len(split) != 2:
    raise SystemExit(1)
fields = split[1].strip().split()
if (
    len(fields) < 20
    or fields[0] in {"Z", "X", "x"}
    or fields[19] != expected_start
):
    raise SystemExit(1)
if expected_pgid and os.getpgid(pid) != int(expected_pgid):
    raise SystemExit(1)
if expected_sid and os.getsid(pid) != int(expected_sid):
    raise SystemExit(1)
PY2
}

signal_update_database_operation_descendants() {
  local supervisor_pid="$1" supervisor_start="$2" signal_number="$3"
  python3 - "${supervisor_pid}" "${supervisor_start}" \
    "${signal_number}" <<'PY2'
import os
import signal
import sys

if (
    not all(value.isdigit() and int(value) > 1 for value in sys.argv[1:3])
    or sys.argv[3] not in {"9", "15"}
    or not hasattr(os, "pidfd_open")
    or not hasattr(signal, "pidfd_send_signal")
):
    raise SystemExit(1)
supervisor_pid, supervisor_start, signal_number = map(int, sys.argv[1:])


def identity(pid):
    text = open(f"/proc/{pid}/stat", "r", encoding="ascii").read()
    split = text.rsplit(")", 1)
    if len(split) != 2:
        raise ProcessLookupError
    fields = split[1].strip().split()
    if len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
        raise ProcessLookupError
    return int(fields[1]), int(fields[19])


supervisor_descriptor = None
try:
    supervisor_descriptor = os.pidfd_open(supervisor_pid, 0)
    _supervisor_parent, observed_start = identity(supervisor_pid)
    if observed_start != supervisor_start:
        raise SystemExit(2)
except (FileNotFoundError, PermissionError, ProcessLookupError, OSError):
    raise SystemExit(2)

identities = {}
for entry in os.scandir("/proc"):
    if not entry.name.isdigit():
        continue
    pid = int(entry.name)
    if pid == supervisor_pid:
        continue
    try:
        identities[pid] = identity(pid)
    except (FileNotFoundError, PermissionError, ProcessLookupError, ValueError):
        continue

parents = {supervisor_pid}
members = {}
changed = True
while changed:
    changed = False
    for pid, (ppid, start_time) in identities.items():
        if pid not in members and ppid in parents:
            members[pid] = start_time
            parents.add(pid)
            changed = True

for pid, expected_start in sorted(members.items(), reverse=True):
    descriptor = None
    try:
        descriptor = os.pidfd_open(pid, 0)
        _ppid, start_time = identity(pid)
        _supervisor_parent, live_supervisor_start = identity(supervisor_pid)
        if (
            start_time != expected_start
            or live_supervisor_start != supervisor_start
        ):
            continue
        signal.pidfd_send_signal(descriptor, signal_number)
    except (FileNotFoundError, PermissionError, ProcessLookupError, OSError):
        continue
    finally:
        if descriptor is not None:
            os.close(descriptor)
if supervisor_descriptor is not None:
    os.close(supervisor_descriptor)
print(len(members))
PY2
}

signal_update_database_operation_process_exact() {
  local pid="$1" start_time="$2" signal_number="$3"
  python3 - "${pid}" "${start_time}" "${signal_number}" <<'PY2'
import os
import signal
import sys

pid_text, start_text, signal_text = sys.argv[1:]
if (
    not pid_text.isdigit()
    or int(pid_text) <= 1
    or not start_text.isdigit()
    or signal_text not in {"9", "15"}
    or not hasattr(os, "pidfd_open")
    or not hasattr(signal, "pidfd_send_signal")
):
    raise SystemExit(1)
pid = int(pid_text)
descriptor = os.pidfd_open(pid, 0)
try:
    text = open(f"/proc/{pid}/stat", "r", encoding="ascii").read()
    fields = text.rsplit(")", 1)[1].strip().split()
    if (
        len(fields) < 20
        or fields[0] in {"Z", "X", "x"}
        or fields[19] != start_text
    ):
        raise SystemExit(2)
    signal.pidfd_send_signal(descriptor, int(signal_text))
finally:
    os.close(descriptor)
PY2
}

read_update_database_operation_completion() {
  local supervisor_pid="$1" supervisor_start="$2"
  local completion_path="${UPDATE_DATABASE_OPERATION_GUARD_DIR}/operation.complete"
  python3 - "${completion_path}" "${supervisor_pid}" \
    "${supervisor_start}" <<'PY2'
import os
import stat
import sys

path, expected_pid, expected_start = sys.argv[1:]
flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
descriptor = os.open(path, flags)
try:
    metadata = os.fstat(descriptor)
    if (
        not stat.S_ISREG(metadata.st_mode)
        or metadata.st_nlink != 1
        or stat.S_IMODE(metadata.st_mode) != 0o600
        or metadata.st_uid != os.geteuid()
        or metadata.st_gid != os.getegid()
        or metadata.st_size > 128
    ):
        raise SystemExit(1)
    raw = os.read(descriptor, 129)
finally:
    os.close(descriptor)
parts = raw.decode("ascii", errors="strict").rstrip("\n").split(" ")
if (
    len(parts) != 4
    or parts[0] != "BRIDGESLLM_A009_OPERATION_COMPLETE_V1"
    or parts[1] != expected_pid
    or parts[2] != expected_start
    or not parts[3].isdigit()
    or not 0 <= int(parts[3]) <= 255
):
    raise SystemExit(1)
print(parts[3])
PY2
}

launch_update_database_operation() {
  local db_url="$1" context="$2"
  shift 2
  local ready_fifo="${UPDATE_DATABASE_OPERATION_GUARD_DIR}/operation.ready"
  local start_fifo="${UPDATE_DATABASE_OPERATION_GUARD_DIR}/operation.start"
  local completion_path="${UPDATE_DATABASE_OPERATION_GUARD_DIR}/operation.complete"
  local ready_fd start_fd supervisor_pid supervisor_start=""
  local metadata="" parsed="" child_pid="" child_start="" child_pgid=""
  local runner_source supervisor_expected_parent="${BASHPID}"
  runner_source="$(update_database_operation_supervisor_python)" || return 1
  [[ ! -e "${completion_path}" && ! -L "${completion_path}" ]] || return 1
  mkfifo -m 0600 "${ready_fifo}" "${start_fifo}" || return 1
  exec {ready_fd}<>"${ready_fifo}" || return 1
  exec {start_fd}<>"${start_fifo}" || {
    eval "exec ${ready_fd}>&-"
    return 1
  }
  env -u DATABASE_URL -u PGHOST -u PGHOSTADDR -u PGPORT \
    -u PGDATABASE -u PGUSER -u PGPASSWORD -u PGPASSFILE \
    -u PGSERVICE -u PGSERVICEFILE -u PGOPTIONS -u PGAPPNAME \
    -u PGSSLMODE -u PGREQUIRESSL -u PGSSLCOMPRESSION \
    -u PGSSLCERT -u PGSSLKEY -u PGSSLROOTCERT -u PGSSLCRL \
    -u PGREQUIREPEER -u PGCHANNELBINDING -u PGTARGETSESSIONATTRS \
    -u PGCONNECT_TIMEOUT -u PGCLIENTENCODING -u PGKRBSRVNAME \
    -u PGGSSLIB -u PGSYSCONFDIR -u PGLOCALEDIR \
    BRIDGESLLM_DATABASE_GUARD_BACKEND_PID="$(
      printf '%s' "${UPDATE_DATABASE_OPERATION_GUARD_BACKEND_PID:-4242}"
    )" \
    python3 -c "${runner_source}" "${supervisor_expected_parent}" \
      "${context}" "${ready_fifo}" "${start_fifo}" "${completion_path}" "$@" \
      3< <(printf '%s' "${db_url}") &
  supervisor_pid=$!
  supervisor_start="$(
    python3 - "${supervisor_pid}" <<'PY2'
import sys
text = open(f"/proc/{sys.argv[1]}/stat", "r", encoding="ascii").read()
fields = text.rsplit(")", 1)[1].strip().split()
if len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
    raise SystemExit(1)
print(fields[19])
PY2
  )" || supervisor_start=""
  [[ "${supervisor_start}" =~ ^[1-9][0-9]*$ ]] || {
    kill -TERM "${supervisor_pid}" 2>/dev/null || true
    wait "${supervisor_pid}" 2>/dev/null || true
    eval "exec ${ready_fd}>&-"
    eval "exec ${start_fd}>&-"
    rm -f -- "${ready_fifo}" "${start_fifo}"
    return 1
  }
  UPDATE_DATABASE_OPERATION_SUPERVISOR_PID="${supervisor_pid}"
  UPDATE_DATABASE_OPERATION_LATCH="${supervisor_pid}:${supervisor_start}:0:0:0"
  IFS= read -r -t 10 -u "${ready_fd}" metadata || metadata=""
  parsed="$(
    python3 - "${metadata}" "${supervisor_pid}" "${supervisor_start}" <<'PY2'
import json
import os
import sys

try:
    value = json.loads(sys.argv[1])
except ValueError:
    raise SystemExit(1)
required = {
    "schema", "supervisorPid", "supervisorStartTime",
    "childPid", "childStartTime", "childPgid",
}
if (
    not isinstance(value, dict)
    or set(value) != required
    or value["schema"] != "bridgesllm-update-operation-ready-v1"
    or value["supervisorPid"] != int(sys.argv[2])
    or value["supervisorStartTime"] != int(sys.argv[3])
    or value["childPid"] <= 1
    or value["childPgid"] != value["childPid"]
    or value["childStartTime"] <= 0
):
    raise SystemExit(1)
pid = value["childPid"]
text = open(f"/proc/{pid}/stat", "r", encoding="ascii").read()
fields = text.rsplit(")", 1)[1].strip().split()
if (
    len(fields) < 20
    or fields[0] in {"Z", "X", "x"}
    or int(fields[19]) != value["childStartTime"]
    or os.getpgid(pid) != value["childPgid"]
):
    raise SystemExit(1)
print(value["childPid"], value["childStartTime"], value["childPgid"])
PY2
  )" || parsed=""
  read -r child_pid child_start child_pgid <<<"${parsed}"
  if [[ ! "${child_pid}" =~ ^[1-9][0-9]*$ \
    || ! "${child_start}" =~ ^[1-9][0-9]*$ \
    || "${child_pgid}" != "${child_pid}" ]]; then
    kill -TERM "${supervisor_pid}" 2>/dev/null || true
    wait "${supervisor_pid}" 2>/dev/null || true
    UPDATE_DATABASE_OPERATION_LATCH=""
    UPDATE_DATABASE_OPERATION_SUPERVISOR_PID=""
    eval "exec ${ready_fd}>&-"
    eval "exec ${start_fd}>&-"
    rm -f -- "${ready_fifo}" "${start_fifo}"
    return 1
  fi
  # Publish the complete identity before releasing the child to exec.
  UPDATE_DATABASE_OPERATION_LATCH="${supervisor_pid}:${supervisor_start}:${child_pid}:${child_start}:${child_pgid}"
  local test_pre_go_guard_failure=false
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_PRE_GO_GUARD_FAIL:-0}" \
      == "1" ]]; then
    test_pre_go_guard_failure=true
  fi
  if ${test_pre_go_guard_failure} \
    || { [[ -n "${UPDATE_DATABASE_OPERATION_GUARD_IDENTITY:-}" ]] \
      && { ! update_database_guard_process_is_live \
           "${UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID}" \
         || ! update_database_guard_process_is_live \
           "${UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID}" \
         || ! verify_update_database_guard_identity \
           "${UPDATE_DATABASE_OPERATION_GUARD_IDENTITY}"; }; }; then
    eval "exec ${ready_fd}>&-" || true
    eval "exec ${start_fd}>&-" || true
    rm -f -- "${ready_fifo}" "${start_fifo}"
    settle_active_update_database_operation >/dev/null 2>&1 || return 93
    return 1
  fi
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_START_WRITE_FAIL:-0}" \
      == "1" ]]; then
    eval "exec ${start_fd}>&-" || true
  fi
  printf '%s\n' START >&"${start_fd}" || {
    eval "exec ${ready_fd}>&-" || true
    eval "exec ${start_fd}>&-" || true
    rm -f -- "${ready_fifo}" "${start_fifo}"
    settle_active_update_database_operation >/dev/null 2>&1 || return 93
    return 1
  }
  eval "exec ${ready_fd}>&-"
  eval "exec ${start_fd}>&-"
  rm -f -- "${ready_fifo}" "${start_fifo}"
}

settle_active_update_database_operation() {
  if [[ "${UPDATE_DATABASE_OPERATION_SETTLEMENT_IN_PROGRESS:-false}" \
    == "true" ]]; then
    return 1
  fi
  UPDATE_DATABASE_OPERATION_SETTLEMENT_IN_PROGRESS=true
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_SETTLEMENT_FAIL:-0}" \
      == "1" ]]; then
    UPDATE_DATABASE_OPERATION_SETTLEMENT_IN_PROGRESS=false
    return 1
  fi
  local latch="${UPDATE_DATABASE_OPERATION_LATCH:-}"
  local supervisor_pid="" supervisor_start="" child_pid="" child_start="" child_pgid=""
  local status=0 attempt descendant_count="" completion_status=""
  IFS=: read -r supervisor_pid supervisor_start child_pid child_start child_pgid \
    <<<"${latch}"
  if [[ -z "${latch}" ]]; then
    cleanup_update_database_operation_guard
    UPDATE_DATABASE_OPERATION_SETTLEMENT_IN_PROGRESS=false
    return 0
  fi
  if [[ ! "${supervisor_pid}" =~ ^[1-9][0-9]*$ \
    || ! "${supervisor_start}" =~ ^[1-9][0-9]*$ ]]; then
    status=1
  elif update_database_process_matches \
      "${supervisor_pid}" "${supervisor_start}" 2>/dev/null; then
    # Signal only descendants proven to belong to the exact live supervisor.
    # TERM gets three seconds, then KILL gets three seconds. The supervisor is
    # never SIGKILLed: it alone may publish the completion proof, and recovery
    # must fail closed if that proof cannot be produced.
    for attempt in {1..60}; do
      descendant_count="$(
        signal_update_database_operation_descendants \
          "${supervisor_pid}" "${supervisor_start}" 15 2>/dev/null
      )" || descendant_count=""
      if [[ "${descendant_count}" == "0" ]]; then
        signal_update_database_operation_process_exact \
          "${supervisor_pid}" "${supervisor_start}" 15 2>/dev/null || true
        break
      fi
      update_database_process_matches \
        "${supervisor_pid}" "${supervisor_start}" 2>/dev/null || break
      if (( attempt >= 30 )); then
        descendant_count="$(
          signal_update_database_operation_descendants \
            "${supervisor_pid}" "${supervisor_start}" 9 2>/dev/null
        )" || descendant_count=""
      fi
      sleep 0.1
    done
    for attempt in {1..60}; do
      update_database_process_matches \
        "${supervisor_pid}" "${supervisor_start}" 2>/dev/null || break
      sleep 0.1
    done
    if update_database_process_matches \
      "${supervisor_pid}" "${supervisor_start}" 2>/dev/null; then
      status=1
    fi
  fi
  if [[ "${supervisor_pid}" =~ ^[1-9][0-9]*$ ]]; then
    wait "${supervisor_pid}" 2>/dev/null || true
  fi
  completion_status="$(
    read_update_database_operation_completion \
      "${supervisor_pid}" "${supervisor_start}" 2>/dev/null
  )" || completion_status=""
  [[ "${completion_status}" =~ ^[0-9]+$ ]] || status=1
  if [[ "${status}" -eq 0 ]]; then
    cleanup_update_database_operation_guard
    UPDATE_DATABASE_OPERATION_LATCH=""
    UPDATE_DATABASE_OPERATION_SUPERVISOR_PID=""
  fi
  UPDATE_DATABASE_OPERATION_SETTLEMENT_IN_PROGRESS=false
  return "${status}"
}

update_database_guard_process_is_live() {
  local pid="$1"
  python3 - "${pid}" <<'PY2'
import sys
pid = sys.argv[1]
if not pid.isdigit() or int(pid) <= 1:
    raise SystemExit(1)
text = open(f"/proc/{pid}/stat", "r", encoding="ascii").read()
fields = text.rsplit(")", 1)[1].strip().split()
if len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
    raise SystemExit(1)
PY2
}

run_contained_database_operation() {
  local db_url="$1" context="$2"
  shift 2
  [[ "$#" -gt 0 ]] || return 1
  UPDATE_DATABASE_OPERATION_GUARD_DIR="$(
    mktemp -d "${TMPDIR:-/tmp}/blp-update-dbguard.XXXXXX"
  )" || return 92
  chmod 0700 "${UPDATE_DATABASE_OPERATION_GUARD_DIR}" || {
    cleanup_update_database_operation_guard
    return 92
  }
  local launch_status=0 operation_status=0 completion_status=""
  launch_update_database_operation "${db_url}" "${context}" "$@" \
    || launch_status=$?
  if [[ "${launch_status}" -ne 0 ]]; then
    [[ "${launch_status}" -ne 93 ]] || return 93
    if [[ -n "${UPDATE_DATABASE_OPERATION_LATCH:-}" ]]; then
      settle_active_update_database_operation || return 93
    else
      cleanup_update_database_operation_guard
    fi
    return 92
  fi
  local supervisor_pid="${UPDATE_DATABASE_OPERATION_SUPERVISOR_PID}"
  local supervisor_start="${UPDATE_DATABASE_OPERATION_LATCH#*:}"
  supervisor_start="${supervisor_start%%:*}"
  while update_database_process_matches \
      "${supervisor_pid}" "${supervisor_start}" 2>/dev/null; do
    sleep 0.1
  done
  wait "${supervisor_pid}" || operation_status=$?
  completion_status="$(
    read_update_database_operation_completion \
      "${supervisor_pid}" "${supervisor_start}" 2>/dev/null
  )" || completion_status=""
  if [[ ! "${completion_status}" =~ ^[0-9]+$ \
    || "${completion_status}" -ne "${operation_status}" ]]; then
    return 93
  fi
  cleanup_update_database_operation_guard
  UPDATE_DATABASE_OPERATION_LATCH=""
  UPDATE_DATABASE_OPERATION_SUPERVISOR_PID=""
  return "${operation_status}"
}

run_attested_database_operation() {
  local db_url="$1" context="$2"
  shift 2
  [[ "$#" -gt 0 ]] || return 1
  local source_only=false operation_status=0 guard_status=0 guard_started=false
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && -n "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT:-}" ]]; then
    source_only=true
  fi
  if ${source_only}; then
    assert_update_database_topology_unchanged \
      "${db_url}" "${context}-guard-start" || return 92
    if [[ "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_GUARD_FAIL_AFTER_READY:-0}" \
      == "1" ]]; then
      return 92
    fi
    UPDATE_DATABASE_OPERATION_GUARD_DIR="$(
      mktemp -d "${TMPDIR:-/tmp}/blp-update-dbguard.XXXXXX"
    )" || return 92
    chmod 0700 "${UPDATE_DATABASE_OPERATION_GUARD_DIR}"
  else
    start_update_database_operation_guard "${db_url}" "${context}" || return 92
    guard_started=true
  fi
  local launch_status=0
  launch_update_database_operation "${db_url}" "${context}" "$@" \
    || launch_status=$?
  if [[ "${launch_status}" -ne 0 ]]; then
    [[ "${launch_status}" -ne 93 ]] || return 93
    if [[ -n "${UPDATE_DATABASE_OPERATION_LATCH:-}" ]]; then
      settle_active_update_database_operation || return 93
    else
      cleanup_update_database_operation_guard
    fi
    return 92
  fi
  local supervisor_pid="${UPDATE_DATABASE_OPERATION_SUPERVISOR_PID}"
  local supervisor_start="${UPDATE_DATABASE_OPERATION_LATCH#*:}"
  supervisor_start="${supervisor_start%%:*}"
  while update_database_process_matches \
      "${supervisor_pid}" \
      "${supervisor_start}" 2>/dev/null; do
    if ${guard_started} \
      && { ! update_database_guard_process_is_live \
             "${UPDATE_DATABASE_OPERATION_GUARD_CLIENT_PID}" \
           || ! update_database_guard_process_is_live \
             "${UPDATE_DATABASE_OPERATION_GUARD_WATCHDOG_PID}" \
           || ! verify_update_database_guard_identity \
             "${UPDATE_DATABASE_OPERATION_GUARD_IDENTITY}"; }; then
      guard_status=92
      settle_active_update_database_operation || return 93
      break
    fi
    sleep 0.1
  done
  if [[ "${guard_status}" -eq 0 ]]; then
    wait "${supervisor_pid}" || operation_status=$?
    local completion_status=""
    completion_status="$(
      read_update_database_operation_completion \
        "${supervisor_pid}" "${supervisor_start}" 2>/dev/null
    )" || completion_status=""
    if [[ ! "${completion_status}" =~ ^[0-9]+$ \
      || "${completion_status}" -ne "${operation_status}" ]]; then
      # The exact supervisor is the only process authorized to prove its
      # recursive descendant tree empty. Never recover or clear the boot fence
      # after an unexpected supervisor death or a forged/mismatched receipt.
      return 93
    fi
    if [[ "${guard_status}" -eq 0 ]]; then
      if ${guard_started}; then
        finish_update_database_operation_guard "${db_url}" "${context}" \
          || guard_status=92
      else
        assert_update_database_topology_unchanged \
          "${db_url}" "${context}-guard-complete" || guard_status=92
      fi
      cleanup_update_database_operation_guard
      UPDATE_DATABASE_OPERATION_LATCH=""
      UPDATE_DATABASE_OPERATION_SUPERVISOR_PID=""
    fi
  fi
  [[ "${guard_status}" -eq 0 ]] || return "${guard_status}"
  return "${operation_status}"
}

attest_update_database_ownership() {
  # Rollback recreates the public schema and its objects as the connecting
  # role with no explicit grants. That is only lossless when the database
  # already follows the installer contract: the DATABASE_URL role owns the
  # database, the public schema, and every dumpable public-schema object in it,
  # and no schema/object/column/default ACL or large-object state would be
  # flattened by --no-owner --no-privileges. This includes relations, routines,
  # types, collations, conversions, operators, operator classes/families, and
  # text-search dictionaries/configurations, extended statistics, and
  # extensions assigned to public. Extra user schemas are outside
  # the product contract and are rejected instead of silently surviving with
  # split database authority.
  local db_url="$1" context="${2:-admission}"
  local expected_variant="${3:-}"
  local connection_url result violations variant extra
  local status=0
  connection_url="$(libpq_database_url "${db_url}")" || return 1
  result="$(update_database_ownership_violations_sql \
    | run_with_update_pgpass "${db_url}" \
      psql --dbname="${connection_url}" --no-psqlrc \
      -v ON_ERROR_STOP=1 -qAt \
      2>> "${LOG_FILE}")" || status=$?
  [[ "${status}" -eq 0 ]] || return 1
  result="$(tr -d '[:space:]' <<<"${result}")"
  IFS='|' read -r violations variant extra <<<"${result}"
  [[ "${violations}" =~ ^[0-9]+$ \
    && "${variant}" =~ ^(owner-null|pg-database-owner-default)$ \
    && -z "${extra}" ]] || return 1
  if [[ "${violations}" != "0" ]]; then
    echo "database ownership contract violations (${context}): ${violations}" \
      >> "${LOG_FILE}"
    return 1
  fi
  if [[ -n "${expected_variant}" && "${variant}" != "${expected_variant}" ]]; then
    echo "database ownership contract variant changed (${context}): expected ${expected_variant}, got ${variant}" \
      >> "${LOG_FILE}"
    return 1
  fi
  UPDATE_RECOVERY_DATABASE_CONTRACT_VARIANT="${variant}"
}

backup_database_for_update() {
  local db_url="$1" backup_dir="$2"
  local connection_url dump
  [[ -n "${db_url}" ]] || return 1
  assert_update_database_topology_unchanged "${db_url}" backup \
    || return 1
  connection_url="$(libpq_database_url "${db_url}")" || return 1
  dump="${backup_dir}/database-before-update.dump"
  if ! run_attested_database_operation \
    "${db_url}" backup \
    pg_dump --format=custom --no-owner --no-privileges \
    --dbname="${connection_url}" --file="${dump}" \
    >> "${LOG_FILE}" 2>&1; then
    rm -f -- "${dump}"
    return 1
  fi
  if ! assert_update_database_topology_unchanged \
      "${db_url}" backup-complete; then
    rm -f -- "${dump}"
    return 1
  fi
  [[ -s "${dump}" ]] || return 1
  chmod 0600 "${dump}"
  pg_restore --list "${dump}" >> "${LOG_FILE}" 2>&1 || return 1
  fsync_update_payload "${dump}" || return 1
  UPDATE_RECOVERY_DATABASE_DUMP="${dump}"
  UPDATE_RECOVERY_DATABASE_URL="${db_url}"
  ok "Database rollback snapshot created"
}

snapshot_update_database_contract() {
  local backup_dir="$1"
  local destination="${backup_dir}/database-contract.variant"
  local variant="${UPDATE_RECOVERY_DATABASE_CONTRACT_VARIANT:-}"
  [[ "${variant}" =~ ^(owner-null|pg-database-owner-default)$ \
    && -d "${backup_dir}" && ! -L "${backup_dir}" \
    && ! -e "${destination}" && ! -L "${destination}" ]] || return 1
  (umask 077; printf '%s\n' "${variant}" > "${destination}") || return 1
  chmod 0600 "${destination}" || return 1
  fsync_update_payload "${destination}"
}

read_update_database_contract_snapshot() {
  local target="$1" backup_dir="$2"
  local manifest path="${backup_dir}/database-contract.variant"
  manifest="$(update_transaction_manifest_path "${target}" database-contract)" \
    || return 1
  update_artifact_manifest verify "${path}" "${manifest}" false || return 1
  python3 - "${path}" <<'PY2'
import os
import stat
import sys

path = sys.argv[1]
details = os.lstat(path)
if (
    not stat.S_ISREG(details.st_mode)
    or stat.S_ISLNK(details.st_mode)
    or details.st_uid != os.geteuid()
    or details.st_gid != os.getegid()
    or details.st_nlink != 1
    or stat.S_IMODE(details.st_mode) != 0o600
    or not 1 <= details.st_size <= 64
):
    raise SystemExit(1)
value = open(path, "r", encoding="ascii").read()
if value not in {"owner-null\n", "pg-database-owner-default\n"}:
    raise SystemExit(1)
print(value.rstrip("\n"))
PY2
}

restore_database_after_failed_update() {
  local db_url="${UPDATE_RECOVERY_DATABASE_URL:-}" dump="${UPDATE_RECOVERY_DATABASE_DUMP:-}"
  local status=0
  [[ -n "${db_url}" && -s "${dump}" ]] || return 1
  [[ "${UPDATE_RECOVERY_DATABASE_CONTRACT_VARIANT:-}" \
    =~ ^(owner-null|pg-database-owner-default)$ ]] || status=1
  if [[ "${status}" -eq 0 ]]; then
    restore_database_with_pgpass "${dump}" \
      "${UPDATE_RECOVERY_DATABASE_CONTRACT_VARIANT}" "${db_url}" \
      || status=1
  fi
  if [[ "${status}" -eq 0 ]]; then
    # The restored database must land back on the attested ownership
    # contract; a mismatch means the rollback is NOT byte-faithful.
    attest_update_database_ownership \
      "${db_url}" restore "${UPDATE_RECOVERY_DATABASE_CONTRACT_VARIANT}" \
      || status=1
  fi
  return "${status}"
}

update_database_competing_session_settlement_sql() {
  cat <<'SQL'
SET search_path TO pg_catalog;
DO $bridgesllm$
DECLARE
  deadline timestamptz := pg_catalog.clock_timestamp() + interval '10 seconds';
BEGIN
  PERFORM pg_catalog.pg_terminate_backend(pid)
  FROM pg_catalog.pg_stat_activity
  WHERE datname = pg_catalog.current_database()
    AND backend_type = 'client backend'
    AND pid <> pg_catalog.pg_backend_pid()
    AND pid <> __BRIDGESLLM_GUARD_BACKEND_PID__;
  LOOP
    PERFORM pg_catalog.pg_stat_clear_snapshot();
    EXIT WHEN NOT EXISTS (
      SELECT 1
      FROM pg_catalog.pg_stat_activity
      WHERE datname = pg_catalog.current_database()
        AND backend_type = 'client backend'
        AND pid <> pg_catalog.pg_backend_pid()
        AND pid <> __BRIDGESLLM_GUARD_BACKEND_PID__
    );
    IF pg_catalog.clock_timestamp() >= deadline THEN
      RAISE EXCEPTION 'database backends did not terminate before schema reset';
    END IF;
    PERFORM pg_catalog.pg_sleep(0.05);
  END LOOP;
END
$bridgesllm$;
SQL
}

restore_database_with_pgpass() {
  local dump="$1" contract_variant="$2" db_url="$3"
  local connection_url schema_restore_sql session_settlement_sql
  connection_url="$(libpq_database_url "${db_url}")" || return 1
  # A forward-migrated schema can hold objects the snapshot does not know
  # about, so pg_restore --clean cannot order its drops past them. Reset the
  # schema wholesale, then restore the snapshot into the empty schema (the
  # custom-format dump carries no CREATE SCHEMA public entry of its own).
  case "${contract_variant}" in
    owner-null)
      schema_restore_sql='DROP SCHEMA IF EXISTS public CASCADE; CREATE SCHEMA public;'
      ;;
    pg-database-owner-default)
      schema_restore_sql='DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
ALTER SCHEMA public OWNER TO pg_database_owner;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO PUBLIC;
GRANT CREATE, USAGE ON SCHEMA public TO pg_database_owner;'
      ;;
    *) return 1 ;;
  esac
  session_settlement_sql="$(
    update_database_competing_session_settlement_sql
  )" || return 1
  # One live, PID-bound guard spans session termination, schema reset, and
  # pg_restore; there is no
  # unguarded empty-schema gap. Only that exact guard backend is exempted from
  # termination.
  assert_update_database_topology_unchanged "${db_url}" recovery-schema-reset \
    || return 1
  run_attested_database_operation \
    "${db_url}" recovery-database-restore \
    bash -c '
      set -Eeuo pipefail
      connection_url="$1"
      dump="$2"
      schema_restore_sql="$3"
      termination_sql="$4"
      guard_backend_pid="${BRIDGESLLM_DATABASE_GUARD_BACKEND_PID:-}"
      [[ "${guard_backend_pid}" =~ ^[1-9][0-9]*$ ]] || exit 91
      termination_sql="${termination_sql//__BRIDGESLLM_GUARD_BACKEND_PID__/${guard_backend_pid}}"
      # One exact psql session delivers termination, waits until every
      # non-guard backend has disappeared, and only then resets the schema.
      # Signal delivery alone is not settlement: a PostgreSQL backend can
      # continue abort/commit work after pg_terminate_backend() returns true.
      psql --dbname="${connection_url}" --no-psqlrc -v ON_ERROR_STOP=1 \
        -c "${termination_sql}" \
        -c "${schema_restore_sql}"
      pg_restore --no-owner --no-privileges --exit-on-error \
        --dbname="${connection_url}" "${dump}"
    ' bridgesllm-database-restore \
    "${connection_url}" "${dump}" "${schema_restore_sql}" \
    "${session_settlement_sql}" \
    >> "${LOG_FILE}" 2>&1
}

run_migrations_safe() {
  local db_url="$1"
  local postflight_db_url=""
  local guarded_update=false
  local backend_dir="${PORTAL_DIR}/backend"
  local migration_dir="${backend_dir}/prisma/migrations"

  # Validate the connection string with a real URI parser before handing it to
  # Prisma/libpq.  Reinstalls may retain encoded credentials, non-default
  # ports, and connection options; shell/sed reconstruction corrupts all three.
  pg_url_component "${db_url}" host >/dev/null \
    && pg_url_component "${db_url}" port >/dev/null \
    && pg_url_component "${db_url}" database >/dev/null \
    && pg_url_component "${db_url}" user >/dev/null \
    || fail "Configured DATABASE_URL is invalid or incomplete."
  postflight_db_url="$(libpq_database_url "${db_url}")" \
    || fail "Configured DATABASE_URL cannot be used for database postflight verification."
  if $UPDATE_MODE; then
    current_update_receipt_target >/dev/null 2>&1 \
      || fail "Update migration requires exactly one valid durable update receipt; refusing an unguarded database migration."
    guarded_update=true
  fi

  # ── Pre-flight: ensure migration files exist ──
  local migration_count=0
  if [[ -d "${migration_dir}" ]]; then
    migration_count=$(find "${migration_dir}" -maxdepth 1 -mindepth 1 -type d 2>/dev/null | wc -l)
  fi

  if (( migration_count == 0 )); then
    echo ""
    echo -e "  ${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "  ${RED}${BOLD}  DATABASE SETUP ERROR${NC}"
    echo ""
    echo -e "  ${WHITE}  No migration files found in:${NC}"
    echo -e "  ${DIM}  ${migration_dir}${NC}"
    echo ""
    echo -e "  ${WHITE}  This usually means the release tarball is incomplete.${NC}"
    echo -e "  ${WHITE}  The portal cannot start without database tables.${NC}"
    echo ""
    echo -e "  ${CYAN}  How to fix:${NC}"
    echo -e "  ${WHITE}  1. Re-download the installer and run again:${NC}"
    echo -e "  ${DIM}     curl -fsSL https://bridgesllm.ai/install.sh | sudo bash${NC}"
    echo ""
    echo -e "  ${WHITE}  2. Or manually re-download the portal tarball:${NC}"
    echo -e "  ${DIM}     curl -fsSL https://bridgesllm.ai/releases/${VERSION}/portal.tar.gz -o /tmp/portal.tar.gz${NC}"
    echo -e "  ${DIM}     tar xzf /tmp/portal.tar.gz -C /tmp${NC}"
    echo -e "  ${DIM}     cp -r /tmp/portal/backend/prisma/migrations ${migration_dir}${NC}"
    echo -e "  ${DIM}     cd ${backend_dir} && npx prisma migrate deploy${NC}"
    echo -e "  ${DIM}     systemctl restart bridgesllm-product${NC}"
    echo ""
    echo -e "  ${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo ""
    fail "No database migrations found — release package may be corrupt"
  fi

  info "Found ${migration_count} migration(s)"

  # Any partially applied forward migration must restore with the previous
  # runtime. The updater keeps this armed until exact-version readiness passes.
  if $UPDATE_MODE && [[ -s "${UPDATE_RECOVERY_DATABASE_DUMP:-}" ]]; then
    UPDATE_RECOVERY_DATABASE_RESTORE_REQUIRED=true
  fi

  if $DRY_RUN; then
    info "[dry-run] Would migrate, verify, and generate the configured database"
    return 0
  fi

  # ── Run migrations ──
  # Keep credentials out of argv/log output. The subshell receives the URL in
  # its environment and invokes Prisma directly, so URI query parameters and
  # percent-encoded credentials are preserved byte-for-byte.
  info "Running database migrations..."
  if ${guarded_update}; then
    assert_update_database_topology_unchanged "${db_url}" prisma-migrate \
      || fail "The local PostgreSQL system or storage topology changed before migration; rollback remains armed."
    if ! run_attested_database_operation \
      "${db_url}" prisma-migrate \
      bash -c 'cd "$1"; exec npx prisma migrate deploy' \
      bridgesllm-prisma-migrate "${backend_dir}" \
      >> "${LOG_FILE}" 2>&1; then
      fail "Database migrations failed against the configured database — check ${LOG_FILE}."
    fi
    assert_update_database_topology_unchanged \
      "${db_url}" prisma-migrate-complete \
      || fail "The local PostgreSQL system or storage topology changed while migrations were running; rollback remains armed."
  elif ! run_contained_database_operation \
      "${db_url}" prisma-migrate \
      bash -c 'cd "$1"; exec npx prisma migrate deploy' \
      bridgesllm-prisma-migrate "${backend_dir}" \
      >> "${LOG_FILE}" 2>&1; then
    fail "Database migrations failed against the configured database — check ${LOG_FILE}."
  fi
  ok "Database migrations applied"

  # ── Post-flight: verify tables were actually created ──
  # libpq only expands connection URIs passed as the dbname parameter, never
  # via PGDATABASE, so the URI goes to --dbname explicitly. The password is
  # stripped from that URI (no secret in argv) and supplied through an
  # anonymous memfd; TLS/connectivity query options survive in the URI itself.
  local table_count=0
  table_count=$(run_with_update_pgpass "${db_url}" \
    psql --dbname="${postflight_db_url}" --no-psqlrc -qAtc \
    "SET search_path TO pg_catalog; SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE'" \
    2>> "${LOG_FILE}" | tr -d '[:space:]' || echo "0")
  table_count="${table_count:-0}"

  # _prisma_migrations table always exists; we need at least a few more
  if (( table_count < 3 )); then
    echo ""
    echo -e "  ${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "  ${RED}${BOLD}  DATABASE MIGRATION FAILED${NC}"
    echo ""
    echo -e "  ${WHITE}  Migrations ran but only ${table_count} table(s) were created.${NC}"
    echo -e "  ${WHITE}  Expected 10+. The database is incomplete.${NC}"
    echo ""
    echo -e "  ${CYAN}  How to fix:${NC}"
    echo -e "  ${WHITE}  1. Check the install log for errors:${NC}"
    echo -e "  ${DIM}     tail -50 ${LOG_FILE}${NC}"
    echo ""
    echo -e "  ${WHITE}  2. Retry migrations using DATABASE_URL from:${NC}"
    echo -e "  ${DIM}     cd ${backend_dir}${NC}"
    echo -e "  ${DIM}     ${backend_dir}/.env.production${NC}"
    echo ""
    echo -e "  ${WHITE}  3. If that fails, verify the configured database is reachable.${NC}"
    echo -e "  ${DIM}     Then restart: systemctl restart bridgesllm-product${NC}"
    echo ""
    echo -e "  ${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo ""
    fail "Database migration incomplete — only ${table_count} tables created (expected 10+)"
  fi

  if ! (
    cd "${backend_dir}"
    run_without_database_authority npx prisma generate
  ) >> "${LOG_FILE}" 2>&1; then
    fail "Database client generation failed — check ${LOG_FILE}."
  fi
  if ! verify_prisma_client_runtime "${backend_dir}" migration-prisma-check \
      >> "${LOG_FILE}" 2>&1; then
    fail "Rust-free database runtime verification failed after migrations — check ${LOG_FILE}."
  fi
  ok "Database ready ${DIM}(${table_count} tables, ${migration_count} migrations)${NC}"
}

verify_portal_service_health() {
  local service_name="${1:-bridgesllm-product}"
  local health_url="${2:-http://127.0.0.1:4001/health}"
  local timeout_secs="${3:-60}"
  local waited=0 tick=0

  while (( waited < timeout_secs )); do
    if systemctl is-active --quiet "${service_name}" && curl -fsS --max-time 2 "${health_url}" >> "$LOG_FILE" 2>&1; then
      if [[ -t 1 ]]; then printf "\r%-120s\r" ""; fi
      ok "Portal is healthy"
      return 0
    fi

    if [[ -t 1 ]]; then
      draw_pulse_bar "$tick" "Waiting for portal" "$(format_elapsed $waited)"
    fi
    tick=$(( tick + 3 ))
    sleep 2
    waited=$((waited + 2))
  done

  if [[ -t 1 ]]; then printf "\r%-120s\r" ""; fi
  journalctl -u "${service_name}" -n 50 --no-pager >> "$LOG_FILE" 2>&1 || true
  return 1
}

portal_service_restart_count() {
  local service_name="${1:-bridgesllm-product}"
  systemctl show "${service_name}" -p NRestarts --value 2>/dev/null | tr -cd '0-9'
}

verify_portal_update_readiness() {
  # Startup migrations (for example legacy-project-retirement) can hold the
  # service in a bootstrap "starting" state for many minutes on a populated
  # install. The budget must cover that, while a crashed or
  # crash-looping service must still fail fast instead of burning the budget.
  local expected_version="$1" probe_token="$2" timeout_secs="${3:-900}"
  local service_name="${4:-bridgesllm-product}"
  local readiness_url="${5:-http://127.0.0.1:4001/health/update-ready}"
  local expected_validation_mode="${6:-canonical}"
  local response_file baseline_restarts current_restarts
  # Budget in real elapsed seconds: probe latency inside each iteration must
  # consume the budget, or a 900s budget silently stretches toward an hour.
  local start_seconds="${SECONDS}"
  [[ -n "${expected_version}" && -n "${probe_token}" ]] || return 1
  baseline_restarts="$(portal_service_restart_count "${service_name}")"
  response_file="$(mktemp /tmp/bridgesllm-readiness.XXXXXX)"
  chmod 0600 "${response_file}"

  while (( SECONDS - start_seconds < timeout_secs )); do
    if ! systemctl is-active --quiet "${service_name}"; then
      rm -f "${response_file}"
      warn "Portal service is no longer active while waiting for readiness"
      return 1
    fi
    current_restarts="$(portal_service_restart_count "${service_name}")"
    if [[ -n "${baseline_restarts}" && -n "${current_restarts}" ]] \
      && (( current_restarts > baseline_restarts )); then
      rm -f "${response_file}"
      warn "Portal service restarted while waiting for readiness (crash loop)"
      return 1
    fi
    if systemctl is-active --quiet "${service_name}" \
      && curl -fsS --max-time 3 -H "x-portal-update-probe: ${probe_token}" \
        -o "${response_file}" "${readiness_url}" 2>> "${LOG_FILE}" \
      && python3 - "${response_file}" "${expected_version}" "${expected_validation_mode}" <<'PY2'
import json
import sys

try:
    payload = json.load(open(sys.argv[1], encoding="utf-8"))
except Exception:
    raise SystemExit(1)
# Require the readiness contract fields; tolerate additive diagnostic fields
# (4.0 attaches mailboxReconciliation) so honest extra detail cannot fail a
# ready deploy.
if not isinstance(payload, dict):
    raise SystemExit(1)
expected_version = sys.argv[2]
mode = sys.argv[3]
validation_value = payload.get("updateValidation")
if mode == "candidate" and validation_value is not True:
    raise SystemExit(1)
if mode == "canonical" and validation_value is not False:
    raise SystemExit(1)
if mode == "legacy-canonical" and (
    "updateValidation" in payload or "updateValidationContract" in payload
):
    raise SystemExit(1)
if mode in {"candidate", "canonical"} and (
    payload.get("updateValidationContract")
    != "BRIDGESLLM_UPDATE_VALIDATION_CONTRACT_V1"
):
    raise SystemExit(1)
if mode not in {"candidate", "canonical", "legacy-canonical"}:
    raise SystemExit(1)
if (
    payload.get("status") != "ready"
    or payload.get("version") != expected_version
    or payload.get("database") != "ready"
):
    raise SystemExit(1)
PY2
    then
      rm -f "${response_file}"
      ok "Portal ${expected_version} authenticated readiness verified"
      return 0
    fi
    sleep 2
  done
  rm -f "${response_file}"
  return 1
}

UPDATE_RECOVERY_BACKUP_DIR=""
UPDATE_RECOVERY_ROLLBACK_RUNTIME=false

openclaw_standard_state_static_is_confirmed() {
  local allow_dynamic_unit="${1:-false}"
  [[ -z "${OPENCLAW_STATE_DIR:-}" \
    && -z "${OPENCLAW_HOME:-}" \
    && -z "${OPENCLAW_PROFILE:-}" \
    && -z "${OPENCLAW_CONFIG_PATH:-}" \
    && -z "${CLAWDBOT_STATE_DIR:-}" \
    && -z "${CLAWDBOT_HOME:-}" \
    && -z "${CLAWDBOT_PROFILE:-}" \
    && -z "${CLAWDBOT_CONFIG_PATH:-}" ]] || return 1
  [[ "${HOME:-/root}" == "/root" && -d "/root/.openclaw" && ! -L "/root/.openclaw" ]] || return 1

  local unit_user unit_env unit_text exec_start exec_path
  unit_user="$(systemctl show openclaw-gateway -p User --value 2>/dev/null || true)"
  [[ -z "${unit_user}" || "${unit_user}" == "root" ]] || return 1
  unit_env="$(systemctl show openclaw-gateway -p Environment --value 2>/dev/null || true)"
  if printf '%s\n' "${unit_env}" | grep -Eq '(^|[[:space:]])(OPENCLAW|CLAWDBOT)_(STATE_DIR|HOME|PROFILE|CONFIG_PATH)='; then
    return 1
  fi
  if printf '%s\n' "${unit_env}" | grep -Eq '(^|[[:space:]])HOME=' \
    && ! printf '%s\n' "${unit_env}" | grep -Eq '(^|[[:space:]])HOME=/root($|[[:space:]])'; then
    return 1
  fi
  unit_text="$(systemctl cat openclaw-gateway --no-pager 2>/dev/null || true)"
  # EnvironmentFile contents and named profiles can redirect state invisibly.
  # Custom units are supported, but their OpenClaw package must be upgraded by
  # an operator who knows that layout rather than by this default-path repair.
  if ! $allow_dynamic_unit \
    && printf '%s\n' "${unit_text}" | grep -Eq '^[[:space:]]*EnvironmentFile='; then
    return 1
  fi
  if printf '%s\n' "${unit_text}" | grep -Eq -- '^[[:space:]]*ExecStart=.*(^|[[:space:]])--(profile|dev|config|state-dir|home)($|=|[[:space:]])'; then
    return 1
  fi

  exec_start="$(systemctl show openclaw-gateway -p ExecStart --value 2>/dev/null || true)"
  if printf '%s\n' "${exec_start}" | grep -Eq -- '(^|[[:space:]])--(profile|dev|config|state-dir|home)($|=|[[:space:]])'; then
    return 1
  fi
  exec_path="$(printf '%s\n' "${exec_start}" | sed -n 's/.*path=\([^ ;]*\).*/\1/p' | head -1)"
  if [[ -n "${exec_path}" && -f "${exec_path}" ]]; then
    if grep -Eq -- '(OPENCLAW|CLAWDBOT)_(STATE_DIR|HOME|PROFILE|CONFIG_PATH)=|(^|[[:space:]])--(profile|dev|config|state-dir|home)($|=|[[:space:]])' "${exec_path}"; then
      return 1
    fi
    local wrapper_home_assignments
    wrapper_home_assignments="$(grep -E '^[[:space:]]*(export[[:space:]]+)?HOME=' "${exec_path}" || true)"
    if [[ -n "${wrapper_home_assignments}" ]] \
      && printf '%s\n' "${wrapper_home_assignments}" \
        | grep -Evq "^[[:space:]]*(export[[:space:]]+)?HOME=(/root|\"/root\"|'/root')[[:space:]]*(#.*)?$"; then
      return 1
    fi
    # A healthy process can prove the result of sourced files via /proc. An
    # inactive gateway cannot, so rescue mode refuses dynamic wrapper state.
    if ! $allow_dynamic_unit \
      && grep -Eq '^[[:space:]]*(source|\.)[[:space:]]+' "${exec_path}"; then
      return 1
    fi
  fi

  return 0
}

openclaw_standard_state_is_confirmed() {
  openclaw_standard_state_static_is_confirmed true || return 1
  systemctl is-active --quiet openclaw-gateway || return 1
  openclaw_gateway_http_ready || return 1

  local main_pid gateway_home

  main_pid="$(systemctl show openclaw-gateway -p MainPID --value 2>/dev/null || true)"
  [[ "${main_pid}" =~ ^[1-9][0-9]*$ && -r "/proc/${main_pid}/environ" && -r "/proc/${main_pid}/cmdline" ]] || return 1

  # /proc is the authority here. It includes EnvironmentFile and wrapper-script
  # exports that cannot be inferred safely from the unit text while inactive.
  gateway_home="$(tr '\0' '\n' < "/proc/${main_pid}/environ" | sed -n 's/^HOME=//p' | head -1)"
  [[ "${gateway_home}" == "/root" ]] || return 1
  if tr '\0' '\n' < "/proc/${main_pid}/environ" | grep -Eq '^(OPENCLAW|CLAWDBOT)_(STATE_DIR|HOME|PROFILE|CONFIG_PATH)='; then
    return 1
  fi
  if tr '\0' ' ' < "/proc/${main_pid}/cmdline" | grep -Eq -- '(^|[[:space:]])--(profile|dev|config|state-dir|home)($|=|[[:space:]])'; then
    return 1
  fi

  return 0
}

prepare_openclaw_upgrade_state() {
  if $SKIP_OPENCLAW || ! command -v node >/dev/null 2>&1; then
    return 0
  fi

  local needs_preparation=false
  if $OPENCLAW_PACKAGE_UPDATED && $OPENCLAW_STATE_EXISTED_BEFORE_UPDATE; then
    needs_preparation=true
  elif ! openclaw_gateway_http_ready \
    && { [[ -e "/root/.clawdbot" ]] || [[ -f "/root/.openclaw/plugins/installs.json" ]]; }; then
    needs_preparation=true
  fi
  if ! $needs_preparation; then
    ok "OpenClaw legacy-state preparation not needed"
    return 0
  fi

  local layout_confirmed=false
  if $OPENCLAW_PACKAGE_UPDATED && $OPENCLAW_STATE_EXISTED_BEFORE_UPDATE; then
    if $OPENCLAW_GATEWAY_WAS_ACTIVE; then
      openclaw_standard_state_is_confirmed && layout_confirmed=true
    else
      # A fresh Portal install may inherit a CLI/state directory but no gateway
      # unit. By this point configure_services has created the standard unit;
      # prove that static layout before the first new-runtime boot.
      openclaw_standard_state_static_is_confirmed && layout_confirmed=true
    fi
  else
    # Rescue an already-failed 2026.7.1 first start using static unit proof. A
    # healthy package upgrade requires the stronger live /proc baseline above.
    openclaw_standard_state_static_is_confirmed && layout_confirmed=true
  fi
  if ! $layout_confirmed; then
    warn "OpenClaw uses a custom or unverified state layout; refusing to alter default-path migration artifacts automatically."
    if ! openclaw_gateway_http_ready; then
      systemctl stop openclaw-gateway >> "$LOG_FILE" 2>&1 || true
      warn "Stopped the unready gateway to prevent a continuing restart loop; custom-state recovery requires an operator."
    fi
    return 1
  fi

  if ! $OPENCLAW_PACKAGE_UPDATED && ! openclaw_gateway_http_ready; then
    # A failed first 2026.7 start may still be cycling under Restart=always.
    # Stop it before touching warning sources so no new migration owner can
    # race the repair or extend the upstream startup-migration lease.
    systemctl stop openclaw-gateway >> "$LOG_FILE" 2>&1 || true
    local stop_waited=0
    while systemctl is-active --quiet openclaw-gateway && (( stop_waited < 30 )); do
      sleep 2
      stop_waited=$((stop_waited + 2))
    done
    if systemctl is-active --quiet openclaw-gateway; then
      warn "Could not stop the unready OpenClaw gateway before migration recovery."
      return 1
    fi
    OPENCLAW_RESCUE_MODE=true
  fi

  local helper="${PORTAL_DIR}/backend/dist/services/openclawConfigManager.js"
  if [[ ! -f "${helper}" ]]; then
    warn "OpenClaw upgrade-state helper is missing."
    return 1
  fi

  local manifest_dir="${UPDATE_RECOVERY_BACKUP_DIR:-/tmp}"
  mkdir -p "${manifest_dir}"
  OPENCLAW_UPGRADE_STATE_MANIFEST="${manifest_dir}/openclaw-upgrade-state-${TIMESTAMP}.json"
  if ! PORTAL_OPENCLAW_STANDARD_STATE_CONFIRMED=1 \
    NODE_PATH="${PORTAL_DIR}/backend/node_modules" \
    node -e '
const fs = require("fs");
const helper = require(process.argv[1]);
const output = process.argv[2];
const result = helper.prepareOpenClawUpgradeState();
try {
  fs.writeFileSync(output, JSON.stringify(result, null, 2) + "\n", { mode: 0o600 });
  fs.chmodSync(output, 0o600);
} catch (error) {
  const restored = helper.restoreOpenClawUpgradeState(result);
  console.error(JSON.stringify({ manifestWriteFailed: String(error), restored }));
  process.exit(44);
}
console.log(JSON.stringify(result));
if (!result.readyForGatewayStart) process.exit(42);
' "${helper}" "${OPENCLAW_UPGRADE_STATE_MANIFEST}" >> "$LOG_FILE" 2>&1; then
    warn "OpenClaw legacy state could not be reconciled safely; the old runtime will be restored."
    return 1
  fi

  ok "OpenClaw legacy state checked and recoverably preserved"

  if $OPENCLAW_RESCUE_MODE && ! wait_for_openclaw_startup_migration_lease; then
    warn "OpenClaw's orphaned startup-migration lease did not expire safely within the recovery window."
    return 1
  fi
}

restore_prepared_openclaw_state() {
  [[ -n "${OPENCLAW_UPGRADE_STATE_MANIFEST:-}" && -f "${OPENCLAW_UPGRADE_STATE_MANIFEST}" ]] || return 0
  local helper="${PORTAL_DIR}/backend/dist/services/openclawConfigManager.js"
  [[ -f "${helper}" ]] || return 1

  NODE_PATH="${PORTAL_DIR}/backend/node_modules" node -e '
const fs = require("fs");
const helper = require(process.argv[1]);
const preparation = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
const result = helper.restoreOpenClawUpgradeState(preparation);
console.log(JSON.stringify(result));
if (!result.restored) process.exit(43);
' "${helper}" "${OPENCLAW_UPGRADE_STATE_MANIFEST}" >> "$LOG_FILE" 2>&1
}

openclaw_gateway_http_ready() {
  curl -fsS --max-time 5 http://127.0.0.1:18789/readyz >/dev/null 2>&1
}

wait_for_openclaw_gateway_http_ready() {
  local timeout_secs="${1:-60}"
  local waited=0
  while (( waited < timeout_secs )); do
    openclaw_gateway_http_ready && return 0
    sleep 3
    waited=$((waited + 3))
  done
  return 1
}

# The Portal restarts the OpenClaw gateway from its own boot path (visible
# browser agent reconciliation, Remote Desktop recovery), so in the seconds
# after the Portal runtime is replaced the gateway can legitimately be
# stopping, starting, or up but not yet answering /readyz. Sampling that
# instant as if it were steady state reported a perfectly healthy host as
# "not stably ready" and aborted the update. Let the unit settle first; the
# real baseline gates still judge whatever we settle on.
settle_openclaw_gateway_before_converge() {
  local timeout_secs="${1:-180}"
  local waited=0 state=""
  systemctl list-unit-files openclaw-gateway.service >/dev/null 2>&1 || return 0
  systemctl is-enabled openclaw-gateway >/dev/null 2>&1 \
    || systemctl is-active --quiet openclaw-gateway \
    || return 0
  while (( waited < timeout_secs )); do
    state="$(systemctl show openclaw-gateway -p ActiveState --value 2>/dev/null || true)"
    if [[ "${state}" == "active" ]] && openclaw_gateway_http_ready; then
      return 0
    fi
    # A unit that has given up is a real fault, not a transient restart, and
    # waiting the full window would only delay an accurate diagnosis.
    [[ "${state}" == "failed" ]] && return 1
    sleep 3
    waited=$((waited + 3))
  done
  return 1
}

openclaw_startup_migration_lease_remaining_seconds() {
  NODE_NO_WARNINGS=1 node - <<'NODE' 2>> "$LOG_FILE"
const { DatabaseSync } = require('node:sqlite');
let db;
try {
  db = new DatabaseSync('/root/.openclaw/state/openclaw.sqlite', { readOnly: true });
  const table = db.prepare("select 1 from sqlite_master where type='table' and name='state_leases'").get();
  if (!table) {
    console.log('0');
    process.exit(0);
  }
  const row = db.prepare("select expires_at from state_leases where scope='startup-migrations' and lease_key='global'").get();
  const expiresAt = Number(row?.expires_at || 0);
  console.log(String(Math.max(0, Math.ceil((expiresAt - Date.now()) / 1000))));
} catch (error) {
  console.error(`Could not inspect the OpenClaw startup-migration lease: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
} finally {
  try { db?.close(); } catch {}
}
NODE
}

wait_for_openclaw_startup_migration_lease() {
  local remaining waited=0 max_wait
  remaining="$(openclaw_startup_migration_lease_remaining_seconds)" || return 1
  [[ "${remaining}" =~ ^[0-9]+$ ]] || return 1
  (( remaining == 0 )) && return 0
  if (( remaining > 315 )); then
    warn "OpenClaw reported an unexpectedly long startup-migration lease (${remaining}s); refusing to delete or bypass it."
    return 1
  fi

  max_wait=$((remaining + 15))
  info "Waiting up to ${max_wait}s for OpenClaw's orphaned startup-migration lease to expire (the lease is not deleted or bypassed)"
  while (( waited < max_wait )); do
    remaining="$(openclaw_startup_migration_lease_remaining_seconds)" || return 1
    [[ "${remaining}" =~ ^[0-9]+$ ]] || return 1
    (( remaining == 0 )) && return 0
    sleep 3
    waited=$((waited + 3))
    if (( waited % 30 == 0 )); then
      progress "OpenClaw migration lease: ${remaining}s remaining"
    fi
  done
  return 1
}

openclaw_gateway_pid() {
  systemctl show openclaw-gateway -p MainPID --value 2>/dev/null || true
}

openclaw_gateway_restart_count() {
  systemctl show openclaw-gateway -p NRestarts --value 2>/dev/null || true
}

capture_openclaw_gateway_baseline() {
  local expected_version="$1"
  systemctl is-active --quiet openclaw-gateway || return 1
  openclaw_gateway_http_ready || return 1
  OPENCLAW_ALLOW_ROOT=1 openclaw gateway status --require-rpc --timeout 10000 >> "$LOG_FILE" 2>&1 || return 1
  [[ "$(openclaw_gateway_version)" == "${expected_version}" ]] || return 1

  OPENCLAW_BASELINE_PID="$(openclaw_gateway_pid)"
  OPENCLAW_BASELINE_RESTARTS="$(openclaw_gateway_restart_count)"
  [[ "${OPENCLAW_BASELINE_PID}" =~ ^[1-9][0-9]*$ && "${OPENCLAW_BASELINE_RESTARTS}" =~ ^[0-9]+$ ]] || return 1
  return 0
}

openclaw_startup_checkpoint_matches() {
  local expected_version="$1"
  OPENCLAW_EXPECTED_CHECKPOINT_VERSION="${expected_version}" node - <<'NODE' >> "$LOG_FILE" 2>&1
const { DatabaseSync } = require('node:sqlite');
const expected = process.env.OPENCLAW_EXPECTED_CHECKPOINT_VERSION;
const normalizeStableRuntime = (value) => String(value || '').replace(/-\d+$/, '');
let db;
try {
  db = new DatabaseSync('/root/.openclaw/state/openclaw.sqlite', { readOnly: true });
  const row = db.prepare("select app_version from schema_meta where meta_key='startup-migrations'").get();
  if (normalizeStableRuntime(row?.app_version) !== normalizeStableRuntime(expected)) process.exit(1);
} catch (error) {
  console.error(`OpenClaw startup checkpoint check failed: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
} finally {
  try { db?.close(); } catch {}
}
NODE
}

openclaw_gateway_log_is_clean_since_start() {
  local started_at
  started_at="$(systemctl show openclaw-gateway -p ExecMainStartTimestamp --value 2>/dev/null || true)"
  [[ -n "${started_at}" && "${started_at}" != "n/a" ]] || return 1
  ! journalctl -u openclaw-gateway --since "${started_at}" --no-pager 2>/dev/null \
    | grep -Eqi 'refusing to report the gateway ready|startup migrations did not complete cleanly|state lease.*(contention|held|failed)|Main process exited|Failed with result'
}

verify_openclaw_gateway_stable() {
  local expected_version="$1"
  local stability_seconds="${2:-18}"
  local cli_version gateway_version initial_pid initial_restarts waited=0

  wait_for_openclaw_gateway_http_ready 60 || return 1
  cli_version="$(openclaw_cli_version)"
  gateway_version="$(openclaw_gateway_version)"
  [[ -n "${expected_version}" && "${cli_version}" == "${expected_version}" && "${gateway_version}" == "${expected_version}" ]] || return 1
  OPENCLAW_ALLOW_ROOT=1 openclaw gateway status --require-rpc --timeout 10000 >> "$LOG_FILE" 2>&1 || return 1

  initial_pid="$(openclaw_gateway_pid)"
  initial_restarts="$(openclaw_gateway_restart_count)"
  [[ "${initial_pid}" =~ ^[1-9][0-9]*$ && "${initial_restarts}" =~ ^[0-9]+$ ]] || return 1

  while (( waited < stability_seconds )); do
    sleep 3
    waited=$((waited + 3))
    systemctl is-active --quiet openclaw-gateway || return 1
    openclaw_gateway_http_ready || return 1
    [[ "$(openclaw_gateway_pid)" == "${initial_pid}" ]] || return 1
    [[ "$(openclaw_gateway_restart_count)" == "${initial_restarts}" ]] || return 1
  done

  OPENCLAW_ALLOW_ROOT=1 openclaw gateway status --require-rpc --timeout 10000 >> "$LOG_FILE" 2>&1 || return 1
  openclaw_gateway_log_is_clean_since_start || return 1
  if [[ "${expected_version}" == "${PIN_OPENCLAW_RUNTIME_VERSION}" ]]; then
    openclaw_startup_checkpoint_matches "${expected_version}" || return 1
  fi
  return 0
}

node_package_name_from_dir() {
  local package_dir="$1"
  [[ -f "${package_dir}/package.json" ]] || return 1
  node -e '
const fs = require("fs");
try {
  const data = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
  process.stdout.write(String(data.name || ""));
} catch (_) {
  process.exit(1);
}
' "${package_dir}/package.json" 2>/dev/null
}

node_package_version_from_dir() {
  local package_dir="$1"
  [[ -f "${package_dir}/package.json" ]] || return 1
  node -e '
const fs = require("fs");
try {
  const data = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
  process.stdout.write(String(data.version || ""));
} catch (_) {
  process.exit(1);
}
' "${package_dir}/package.json" 2>/dev/null
}

openclaw_core_package_dir() {
  local global_root candidate binary resolved package_name depth
  global_root="$(npm root -g 2>/dev/null || true)"
  candidate="${global_root}/openclaw"
  if [[ -n "${global_root}" && -d "${candidate}" ]] \
    && [[ "$(node_package_name_from_dir "${candidate}" || true)" == "openclaw" ]]; then
    printf '%s\n' "${candidate}"
    return 0
  fi

  binary="$(command -v openclaw 2>/dev/null || true)"
  [[ -n "${binary}" ]] || return 1
  resolved="$(readlink -f "${binary}" 2>/dev/null || true)"
  [[ -n "${resolved}" ]] || return 1
  candidate="$(dirname "${resolved}")"
  for depth in 1 2 3 4 5 6; do
    package_name="$(node_package_name_from_dir "${candidate}" || true)"
    if [[ "${package_name}" == "openclaw" ]]; then
      printf '%s\n' "${candidate}"
      return 0
    fi
    [[ "${candidate}" != "/" ]] || break
    candidate="$(dirname "${candidate}")"
  done
  return 1
}

openclaw_core_package_version() {
  local package_dir
  package_dir="$(openclaw_core_package_dir || true)"
  [[ -n "${package_dir}" ]] || return 1
  node_package_version_from_dir "${package_dir}"
}

verify_openclaw_core_package_pin() {
  [[ "$(openclaw_core_package_version || true)" == "${PIN_OPENCLAW_CORE_PACKAGE_VERSION}" ]] \
    && [[ "$(openclaw_cli_version || true)" == "${PIN_OPENCLAW_RUNTIME_VERSION}" ]]
}

stage_openclaw_rollback_package() {
  local expected_version="$1"
  local package_dir backup_dir packed_name packed_path packed_version
  package_dir="$(openclaw_core_package_dir || true)"
  backup_dir="${UPDATE_RECOVERY_BACKUP_DIR:-/tmp}/openclaw-package"
  [[ -d "${package_dir}" && -f "${package_dir}/package.json" ]] || return 1
  mkdir -p "${backup_dir}"

  packed_name="$(cd "${backup_dir}" && npm pack --ignore-scripts --silent "${package_dir}" 2>> "$LOG_FILE" | tail -1)"
  packed_path="${backup_dir}/${packed_name}"
  [[ -n "${packed_name}" && -f "${packed_path}" ]] || return 1
  packed_version="$(tar -xOf "${packed_path}" package/package.json 2>/dev/null \
    | node -e 'let s=""; process.stdin.on("data", c => s += c); process.stdin.on("end", () => { try { console.log(JSON.parse(s).version || ""); } catch {} });' \
    | head -1)"
  if [[ "${packed_version}" != "${expected_version}" ]]; then
    rm -f "${packed_path}"
    return 1
  fi
  chmod 600 "${packed_path}" 2>/dev/null || true
  OPENCLAW_ROLLBACK_PACKAGE_TARBALL="${packed_path}"
  return 0
}

openclaw_installation_state_present() {
  # The Portal's media pipeline creates /root/.openclaw/media on boot even
  # when OpenClaw itself was never installed, so a media cache alone is not
  # installation state that needs repair. Anything else under the state dir
  # is treated as a real OpenClaw installation footprint.
  local state_dir="${1:-/root/.openclaw}" entry
  [[ -d "${state_dir}" ]] || return 1
  for entry in "${state_dir}"/* "${state_dir}"/.[!.]* "${state_dir}"/..?*; do
    [[ -e "${entry}" || -L "${entry}" ]] || continue
    [[ "$(basename -- "${entry}")" == "media" ]] && continue
    return 0
  done
  return 1
}

converge_openclaw_core_package() {
  $SKIP_OPENCLAW && return 0
  command -v npm >/dev/null 2>&1 || fail "npm is required to install the tested OpenClaw runtime."

  local current_package_version="" current_runtime_version=""
  OPENCLAW_STATE_EXISTED_BEFORE_UPDATE=false
  openclaw_installation_state_present /root/.openclaw \
    && OPENCLAW_STATE_EXISTED_BEFORE_UPDATE=true
  OPENCLAW_GATEWAY_WAS_ENABLED=false
  OPENCLAW_GATEWAY_WAS_ACTIVE=false
  settle_openclaw_gateway_before_converge 180 || true
  systemctl is-enabled openclaw-gateway >/dev/null 2>&1 && OPENCLAW_GATEWAY_WAS_ENABLED=true
  systemctl is-active --quiet openclaw-gateway && OPENCLAW_GATEWAY_WAS_ACTIVE=true

  if command -v openclaw >/dev/null 2>&1; then
    OPENCLAW_PACKAGE_PREEXISTED=true
    current_package_version="$(openclaw_core_package_version || true)"
    current_runtime_version="$(openclaw_cli_version || true)"
    if [[ "${current_package_version}" == "${PIN_OPENCLAW_CORE_PACKAGE_VERSION}" \
      && "${current_runtime_version}" == "${PIN_OPENCLAW_RUNTIME_VERSION}" ]]; then
      ok "OpenClaw ${current_package_version} (tested core revision)"
      return 0
    fi
    if [[ -z "${current_package_version}" || -z "${current_runtime_version}" ]]; then
      fail "The existing OpenClaw installation could not be identified precisely; refusing to overwrite it without a verifiable rollback package."
    fi
    if $OPENCLAW_GATEWAY_WAS_ACTIVE; then
      local baseline_attempt=0 baseline_confirmed=false
      # The Portal can restart the gateway again between settling and probing,
      # so a single miss is retried rather than treated as an unsafe host.
      while (( baseline_attempt < 3 )); do
        baseline_attempt=$((baseline_attempt + 1))
        if capture_openclaw_gateway_baseline "${current_runtime_version}" \
          && openclaw_standard_state_is_confirmed; then
          baseline_confirmed=true
          break
        fi
        (( baseline_attempt < 3 )) || break
        settle_openclaw_gateway_before_converge 60 || true
      done
      if ! $baseline_confirmed; then
        fail "The existing OpenClaw gateway is not stably ready in the standard state layout; refusing to replace ${current_package_version} without a safe live rollback baseline."
      fi
    elif $OPENCLAW_GATEWAY_WAS_ENABLED; then
      fail "The existing OpenClaw gateway is enabled but not running; refusing to replace ${current_package_version} without a safe live rollback baseline."
    fi
    if ! stage_openclaw_rollback_package "${current_package_version}"; then
      fail "Could not preserve an exact local rollback package for OpenClaw ${current_package_version}."
    fi
    if ! capture_openclaw_codex_plugin_baseline; then
      fail "Could not prove and preserve the existing OpenClaw Codex plugin baseline before replacing the core package."
    fi
    OPENCLAW_PREUPDATE_PACKAGE_VERSION="${current_package_version}"
    OPENCLAW_PREUPDATE_RUNTIME_VERSION="${current_runtime_version}"
  else
    OPENCLAW_PACKAGE_PREEXISTED=false
    if $OPENCLAW_STATE_EXISTED_BEFORE_UPDATE; then
      fail "OpenClaw state exists but its runtime is missing; repair that installation explicitly before Portal convergence."
    fi
    # This is a genuinely fresh host: capture the pre-install plugin state as
    # absent before installing a core package that bundles the Codex plugin.
    # Inspecting only after core installation would misclassify that newly
    # bundled copy as the rollback baseline.
    OPENCLAW_CODEX_PLUGIN_PREEXISTED=false
    OPENCLAW_CODEX_PLUGIN_PREUPDATE_VERSION=""
    OPENCLAW_CODEX_PLUGIN_BASELINE_CAPTURED=true
  fi

  OPENCLAW_PACKAGE_UPDATE_ATTEMPTED=true
  info "Converging OpenClaw core to ${PIN_OPENCLAW_CORE_PACKAGE_VERSION}..."
  if ! npm install -g "openclaw@${PIN_OPENCLAW_CORE_PACKAGE_VERSION}" >> "$LOG_FILE" 2>&1; then
    fail "OpenClaw core package installation failed or ended in a partial state; automatic rollback is starting."
  fi
  OPENCLAW_PACKAGE_UPDATED=true
  if ! verify_openclaw_core_package_pin; then
    fail "OpenClaw core did not converge to package ${PIN_OPENCLAW_CORE_PACKAGE_VERSION} / runtime ${PIN_OPENCLAW_RUNTIME_VERSION}; automatic rollback is starting."
  fi
  ok "OpenClaw ${PIN_OPENCLAW_CORE_PACKAGE_VERSION} package staged (gateway restart deferred)"
}

rollback_openclaw_package_update() {
  $OPENCLAW_ROLLBACK_IN_PROGRESS && return 1
  OPENCLAW_ROLLBACK_IN_PROGRESS=true
  local defer_gateway_restart="${1:-false}"
  local rollback_ok=true
  local restart_gateway=false
  if $OPENCLAW_PACKAGE_UPDATE_ATTEMPTED || $OPENCLAW_PACKAGE_UPDATED || [[ -n "${OPENCLAW_UPGRADE_STATE_MANIFEST:-}" ]]; then
    $OPENCLAW_GATEWAY_WAS_ACTIVE && restart_gateway=true
    systemctl stop openclaw-gateway >> "$LOG_FILE" 2>&1 || true
  fi

  if $OPENCLAW_PACKAGE_UPDATE_ATTEMPTED || $OPENCLAW_PACKAGE_UPDATED; then
    if $OPENCLAW_PACKAGE_PREEXISTED; then
      warn "Rolling OpenClaw back to package ${OPENCLAW_PREUPDATE_PACKAGE_VERSION:-unknown}"
      local rollback_source="openclaw@${OPENCLAW_PREUPDATE_PACKAGE_VERSION}"
      if [[ -n "${OPENCLAW_ROLLBACK_PACKAGE_TARBALL:-}" && -f "${OPENCLAW_ROLLBACK_PACKAGE_TARBALL}" ]]; then
        rollback_source="${OPENCLAW_ROLLBACK_PACKAGE_TARBALL}"
      fi
      if [[ -z "${OPENCLAW_PREUPDATE_PACKAGE_VERSION:-}" ]] \
        || ! npm install -g "${rollback_source}" >> "$LOG_FILE" 2>&1 \
        || [[ "$(openclaw_core_package_version || true)" != "${OPENCLAW_PREUPDATE_PACKAGE_VERSION}" ]] \
        || [[ "$(openclaw_cli_version || true)" != "${OPENCLAW_PREUPDATE_RUNTIME_VERSION}" ]]; then
        warn "Could not restore the exact OpenClaw package/runtime pair during automatic rollback."
        rollback_ok=false
      fi
    else
      warn "Removing the newly installed OpenClaw package"
      if ! npm uninstall -g openclaw >> "$LOG_FILE" 2>&1; then
        warn "Could not remove the newly installed OpenClaw package during automatic rollback."
        rollback_ok=false
      fi
    fi
  fi

  if ! restore_prepared_openclaw_state; then
    warn "Could not restore one or more preserved OpenClaw legacy artifacts automatically."
    rollback_ok=false
  fi

  if $restart_gateway && [[ "${defer_gateway_restart}" != "true" ]]; then
    systemctl start openclaw-gateway >> "$LOG_FILE" 2>&1 || true
    if [[ -z "${OPENCLAW_PREUPDATE_RUNTIME_VERSION:-}" ]] \
      || ! verify_openclaw_gateway_stable "${OPENCLAW_PREUPDATE_RUNTIME_VERSION}" 18; then
      local restored_version
      restored_version="$(openclaw_cli_version || true)"
      warn "OpenClaw rollback health verification failed (expected ${OPENCLAW_PREUPDATE_RUNTIME_VERSION:-unknown}, found ${restored_version:-unknown})."
      systemctl stop openclaw-gateway >> "$LOG_FILE" 2>&1 || true
      rollback_ok=false
    fi
  fi

  if $rollback_ok; then
    OPENCLAW_PACKAGE_UPDATED=false
    OPENCLAW_PACKAGE_UPDATE_ATTEMPTED=false
    ok "Previous OpenClaw runtime restored"
  fi
  OPENCLAW_ROLLBACK_IN_PROGRESS=false
  $rollback_ok
}

recover_interrupted_update() {
  echo ""
  warn "Update interrupted before commit; resuming the durable recovery transaction."
  if recover_pending_update_transaction; then
    ok "Previous Portal runtime restored and verified"
    return 0
  fi
  warn "Automatic recovery did not complete. Portal remains boot-fenced and stopped; the root-only transaction journal and rollback artifacts were preserved."
  return 1
}

ollama_client_version() {
  command -v ollama >/dev/null 2>&1 || return 1
  # `ollama --version` can block while querying a stale daemon. Point it at a
  # closed loopback port and discard inherited endpoints/proxies so it reports
  # the embedded client version without consulting operator-controlled routing.
  /usr/bin/env -i \
    PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin \
    HOME="${HOME:-/root}" \
    LANG=C \
    LC_ALL=C \
    OLLAMA_HOST=http://127.0.0.1:1 \
    timeout 10s ollama --version 2>&1 \
    | sed -nE 's/.*(client version is|ollama version is) ([0-9]+\.[0-9]+\.[0-9]+).*/\2/p' \
    | head -1 || true
}

ollama_server_version() {
  curl --noproxy '*' -fsS --max-time 3 http://127.0.0.1:11434/api/version 2>/dev/null \
    | python3 -c 'import json,sys; print(json.load(sys.stdin).get("version", ""))' 2>/dev/null || true
}

verify_ollama_client_server_parity() {
  local timeout_secs="${1:-60}" waited=0 client_version server_version
  while (( waited < timeout_secs )); do
    client_version="$(ollama_client_version || true)"
    server_version="$(ollama_server_version || true)"
    if systemctl is-active --quiet ollama \
      && [[ -n "${client_version}" && "${client_version}" == "${server_version}" ]]; then
      ok "Ollama ${client_version} client/server parity verified"
      return 0
    fi
    sleep 2
    waited=$((waited + 2))
  done
  warn "Ollama client/server mismatch after restart (client: ${client_version:-unknown}, server: ${server_version:-unavailable})."
  return 1
}

install_or_update_ollama() {
  $SKIP_OLLAMA && return 0
  if ! command -v zstd >/dev/null 2>&1; then
    spin "Installing zstd (required by Ollama installer)" "DEBIAN_FRONTEND=noninteractive apt-get install -y -qq zstd"
  fi

  local previous_version
  previous_version="$(ollama_client_version || true)"
  if ! spin "Installing/updating Ollama (${previous_version:-not installed})" \
    "curl -fsSL '${OLLAMA_INSTALLER_URL}' | sh >/dev/null 2>&1"; then
    fail "The official Ollama installer failed."
  fi
  command -v ollama >/dev/null 2>&1 || fail "Ollama installer exited successfully but no ollama executable was found."

  systemctl daemon-reload >> "$LOG_FILE" 2>&1 || true
  systemctl enable ollama >> "$LOG_FILE" 2>&1 || true
  if ! systemctl restart ollama >> "$LOG_FILE" 2>&1; then
    fail "Ollama was installed but its service could not be restarted."
  fi
  if ! verify_ollama_client_server_parity 60; then
    fail "Ollama did not reach client/server version parity after its upgrade restart."
  fi
}

converge_grok_build() {
  local helper="${PORTAL_DIR}/installer/grok-build-runtime.sh"
  [[ -f "${helper}" ]] || {
    warn "Grok Build runtime helper is missing from the installed Portal artifact."
    return 1
  }

  GROK_BIN_DIR=/usr/local/bin bash "${helper}" converge >> "${LOG_FILE}" 2>&1 || return 1
  GROK_BIN_DIR=/usr/local/bin bash "${helper}" verify >> "${LOG_FILE}" 2>&1
}

converge_antigravity() {
  local helper="${PORTAL_DIR}/installer/antigravity-runtime.sh"
  [[ -f "${helper}" ]] || {
    warn "Antigravity runtime helper is missing from the installed Portal artifact."
    return 1
  }

  ANTIGRAVITY_BIN_DIR=/usr/local/bin bash "${helper}" converge >> "${LOG_FILE}" 2>&1 || return 1
  ANTIGRAVITY_BIN_DIR=/usr/local/bin bash "${helper}" verify >> "${LOG_FILE}" 2>&1
}

npm_global_package_version() {
  local package_name="$1" global_root package_json
  global_root="$(npm root -g 2>/dev/null)" || return 1
  package_json="${global_root}/${package_name}/package.json"
  [[ -f "${package_json}" ]] || return 1
  node - "${package_json}" <<'NODE'
const fs = require('fs');
try {
  const parsed = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  if (typeof parsed.version !== 'string' || !parsed.version) process.exit(1);
  process.stdout.write(parsed.version);
} catch {
  process.exit(1);
}
NODE
}

verify_pinned_npm_cli() {
  local package_name="$1" expected_version="$2" command_name="$3" version_arg="$4"
  local package_version cli_output
  package_version="$(npm_global_package_version "${package_name}" 2>/dev/null || true)"
  [[ "${package_version}" == "${expected_version}" ]] || return 1
  command -v "${command_name}" >/dev/null 2>&1 || return 1
  cli_output="$(timeout 15 "${command_name}" "${version_arg}" 2>/dev/null || true)"
  grep -Fq "${expected_version}" <<<"${cli_output}"
}

converge_pinned_npm_cli() {
  local label="$1" package_name="$2" expected_version="$3" command_name="$4" version_arg="$5"
  local baseline_version="" had_package=false

  if verify_pinned_npm_cli "${package_name}" "${expected_version}" "${command_name}" "${version_arg}"; then
    ok "${label} ${expected_version} (verified)"
    return 0
  fi

  baseline_version="$(npm_global_package_version "${package_name}" 2>/dev/null || true)"
  [[ -z "${baseline_version}" ]] || had_package=true
  if ! ${had_package} && command -v "${command_name}" >/dev/null 2>&1; then
    warn "${label} is present but is not owned by the expected global npm package; refusing to overwrite it."
    return 1
  fi

  info "Converging ${label} to Portal-tested version ${expected_version}..."
  if npm install -g --no-audit --no-fund "${package_name}@${expected_version}" >> "${LOG_FILE}" 2>&1 \
    && verify_pinned_npm_cli "${package_name}" "${expected_version}" "${command_name}" "${version_arg}"; then
    ok "${label} ${expected_version} (verified)"
    return 0
  fi

  warn "${label} ${expected_version} failed verification; restoring its previous global package state."
  if ${had_package}; then
    npm install -g --no-audit --no-fund "${package_name}@${baseline_version}" >> "${LOG_FILE}" 2>&1 || true
  else
    npm uninstall -g "${package_name}" >> "${LOG_FILE}" 2>&1 || true
  fi
  return 1
}

update_dependencies() {
  info "Checking Portal runtime compatibility..."

  # This must be the first package-runtime action in the updater. OpenClaw's
  # npm package cannot even be inspected safely on unsupported Node lanes.
  ensure_supported_node_runtime
  if $MAINTAIN_TOOLS; then
    spin "Updating Node.js within the supported lane" "apt-get update -qq && apt-get install -y -qq --only-upgrade nodejs 2>/dev/null" || true
    ensure_supported_node_runtime
  fi

  # The Portal updater owns only the Portal and its tested OpenClaw runtime
  # pair. Ollama and coding CLIs are independent operator tools: changing them
  # during an ordinary Portal update makes rollback non-atomic and previously
  # caused unrelated provider drift. They move only on fresh install, an
  # explicit --maintain-tools run, or a deliberate Admin maintenance action.

  # OpenClaw core uses the same exact tested package revision on fresh installs
  # and updates. Its gateway restart remains deferred until state preparation.
  converge_openclaw_core_package

  if $MAINTAIN_TOOLS; then
    # ClawHub powers Skills marketplace search/install.
    if ! $SKIP_OPENCLAW; then
      converge_pinned_npm_cli "ClawHub" "clawhub" "${PIN_CLAWHUB_VERSION}" "clawhub" "--cli-version" \
        || warn "ClawHub could not be converged; Skills marketplace actions will remain unavailable."
    fi

    # Ollama's installer updates the client before the daemon. Restart and prove
    # the API-reported server version matches before continuing.
    if $SKIP_OLLAMA; then
      info "Skipping Ollama (--skip-ollama)"
    else
      install_or_update_ollama
    fi

    converge_pinned_npm_cli "Codex CLI" "@openai/codex" "${PIN_CODEX_CLI_VERSION}" "codex" "--version" \
      || warn "Codex CLI could not be converged to ${PIN_CODEX_CLI_VERSION}; its provider will remain unavailable."
    converge_pinned_npm_cli "Claude Code" "@anthropic-ai/claude-code" "${PIN_CLAUDE_CODE_VERSION}" "claude" "--version" \
      || warn "Claude Code could not be converged to ${PIN_CLAUDE_CODE_VERSION}; its provider will remain unavailable."

    if ! converge_antigravity; then
      warn "Antigravity could not be converged to ${PIN_ANTIGRAVITY_VERSION}; its provider will remain unavailable."
    else
      ok "Antigravity ${PIN_ANTIGRAVITY_VERSION} (verified)"
    fi

    # Grok Build remains exact-pinned when the operator explicitly chooses tool
    # maintenance. Normal Portal updates only report drift and fail the provider
    # closed; they do not replace a working CLI behind the operator's back.
    if ! converge_grok_build; then
      warn "Grok Build could not be converged to ${PIN_GROK_BUILD_VERSION}; its Portal provider will remain unavailable."
    else
      ok "Grok Build ${PIN_GROK_BUILD_VERSION} (verified)"
    fi

  else
    info "Optional tool maintenance skipped (use --maintain-tools to update Ollama and coding CLIs)"
  fi

  # Caddy terminates HTTPS and may carry local/beta site config. Do not mutate it
  # from a Portal app update; the admin maintenance UI treats Caddy as protected
  # infrastructure and installer updates must follow that same boundary.
  if command -v caddy &>/dev/null; then
    local current_caddy
    current_caddy="$(caddy version 2>/dev/null | awk '{print $1}' || echo 'installed')"
    ok "Caddy ${current_caddy:-installed} (manual review)"
  fi

  # ── Tier 3: Notify only ──
  # PostgreSQL — never auto-update major. Minor via apt is safe but requires restart.
  # Docker — user-managed. Don't touch.

  ok "Portal runtime compatibility checked"
}

# ── Progress display helpers ──────────────────────────────────

format_elapsed() {
  local secs="$1"
  if (( secs >= 60 )); then
    printf '%dm %ds' $((secs / 60)) $((secs % 60))
  else
    printf '%ds' "$secs"
  fi
}

format_bytes() {
  # Pure bash integer arithmetic: minimal hosts do not ship `bc`, and a failed
  # substitution here must never feed printf a non-number under `set -e`.
  local bytes="${1:-0}" tenths
  [[ "$bytes" =~ ^[0-9]+$ ]] || bytes=0
  if (( bytes >= 1073741824 )); then
    tenths=$(( (bytes * 10) / 1073741824 ))
    printf '%d.%d GB' $(( tenths / 10 )) $(( tenths % 10 ))
  elif (( bytes >= 1048576 )); then
    tenths=$(( (bytes * 10) / 1048576 ))
    printf '%d.%d MB' $(( tenths / 10 )) $(( tenths % 10 ))
  elif (( bytes >= 1024 )); then
    printf '%d KB' $(( bytes / 1024 ))
  else
    printf '%d B' "$bytes"
  fi
}

# Render a determinate progress bar (0–100%)
draw_pct_bar() {
  local pct="$1" msg="$2" detail="${3:-}"
  local bar_width=24
  local filled=$(( (pct * bar_width) / 100 ))
  (( filled > bar_width )) && filled=$bar_width
  local empty=$(( bar_width - filled ))

  local bar="" i
  for ((i = 0; i < filled; i++)); do bar+="█"; done
  for ((i = 0; i < empty; i++)); do bar+="░"; done

  if [[ -n "$detail" ]]; then
    printf "\r  ${CYAN}[${bar}]${NC} ${DIM}%3d%%${NC}  ${msg} ${DIM}${detail}${NC}          " "$pct"
  else
    printf "\r  ${CYAN}[${bar}]${NC} ${DIM}%3d%%${NC}  ${msg}          " "$pct"
  fi
}

# Render an indeterminate progress bar (pulsing glow)
draw_pulse_bar() {
  local tick="$1" msg="$2" detail="${3:-}"
  local bar_width=24
  local frames=('⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏')
  local frame="${frames[$(( tick % ${#frames[@]} ))]}"

  # Pulse: a bright segment that sweeps back and forth
  local cycle=$(( bar_width * 2 ))
  local pos=$(( tick % cycle ))
  if (( pos >= bar_width )); then
    pos=$(( cycle - pos ))
  fi

  local bar="" i
  for ((i = 0; i < bar_width; i++)); do
    local dist=$(( i - pos ))
    (( dist < 0 )) && dist=$(( -dist ))
    if (( dist == 0 )); then
      bar+="█"
    elif (( dist == 1 )); then
      bar+="▓"
    elif (( dist == 2 )); then
      bar+="▒"
    else
      bar+="░"
    fi
  done

  if [[ -n "$detail" ]]; then
    printf "\r  ${CYAN}${frame}${NC} ${CYAN}[${bar}]${NC} ${msg} ${DIM}${detail}${NC}          "
  else
    printf "\r  ${CYAN}${frame}${NC} ${CYAN}[${bar}]${NC} ${msg}          "
  fi
}

# ── Core spin: indeterminate progress with elapsed time ──────

spin() {
  local msg="$1"; shift
  if $DRY_RUN; then
    echo "  [dry-run] $*" >> "$LOG_FILE" 2>&1
    return
  fi
  if ! $PACKAGE_MANAGER_REPAIR_ACTIVE && command_needs_package_manager "$*"; then
    wait_for_package_manager_ready "$msg"
  fi
  bash -c "$*" >> "$LOG_FILE" 2>&1 &
  local pid=$!
  local start_ts tick=0
  start_ts=$(date +%s)

  if [[ -t 1 ]]; then
    while kill -0 "$pid" 2>/dev/null; do
      local now elapsed
      now=$(date +%s)
      elapsed=$(( now - start_ts ))
      draw_pulse_bar "$tick" "$msg" "$(format_elapsed $elapsed)"
      tick=$(( tick + 1 ))
      sleep 0.15
    done
  else
    echo -e "  ${CYAN}⠿${NC} ${msg}..."
  fi

  wait "$pid"
  local rc=$?
  if [[ -t 1 ]]; then
    printf "\r%-120s\r" ""
  fi
  if [[ $rc -eq 0 ]]; then
    local end_ts total
    end_ts=$(date +%s)
    total=$(( end_ts - start_ts ))
    if (( total > 2 )); then
      ok "${msg} ${DIM}($(format_elapsed $total))${NC}"
    else
      ok "${msg}"
    fi
  fi
  return $rc
}

# ── Download with real progress (curl + actual bytes) ────────

spin_download() {
  local msg="$1" url="$2" dest="$3"
  if $DRY_RUN; then
    echo "  [dry-run] curl $url → $dest" >> "$LOG_FILE" 2>&1
    return
  fi

  # Get total size via HEAD request for real percentage
  local total_bytes=0
  total_bytes=$(curl -fsSLI "$url" 2>/dev/null | grep -i '^content-length:' | awk '{print $2}' | tr -d '\r' || echo 0)

  # Download in background, track file size for real progress
  curl -fSL "$url" -o "$dest" >> "$LOG_FILE" 2>&1 &
  local pid=$!
  local start_ts tick=0
  start_ts=$(date +%s)

  if [[ -t 1 ]]; then
    while kill -0 "$pid" 2>/dev/null; do
      local now elapsed current_bytes=0 pct=0 speed_str=""
      now=$(date +%s)
      elapsed=$(( now - start_ts ))

      if [[ -f "$dest" ]]; then
        current_bytes=$(stat -c%s "$dest" 2>/dev/null || echo 0)
      fi

      if (( total_bytes > 0 && current_bytes > 0 )); then
        pct=$(( (current_bytes * 100) / total_bytes ))
        (( pct > 100 )) && pct=100
        if (( elapsed > 0 )); then
          local speed=$(( current_bytes / elapsed ))
          speed_str="$(format_bytes $current_bytes)/$(format_bytes $total_bytes)  $(format_bytes $speed)/s"
        else
          speed_str="$(format_bytes $current_bytes)/$(format_bytes $total_bytes)"
        fi
        draw_pct_bar "$pct" "$msg" "$speed_str"
      else
        # Indeterminate (no content-length)
        if (( current_bytes > 0 )); then
          draw_pulse_bar "$tick" "$msg" "$(format_bytes $current_bytes)  $(format_elapsed $elapsed)"
        else
          draw_pulse_bar "$tick" "$msg" "$(format_elapsed $elapsed)"
        fi
      fi
      tick=$(( tick + 1 ))
      sleep 0.3
    done
  else
    echo -e "  ${CYAN}⠿${NC} ${msg}..."
  fi

  wait "$pid"
  local rc=$?

  if [[ -t 1 ]]; then
    printf "\r%-120s\r" ""
  fi
  if [[ $rc -eq 0 ]]; then
    local final_size=0
    [[ -f "$dest" ]] && final_size=$(stat -c%s "$dest" 2>/dev/null || echo 0)
    local end_ts total
    end_ts=$(date +%s)
    total=$(( end_ts - start_ts ))
    if (( total > 2 )); then
      ok "${msg} ${DIM}($(format_bytes $final_size), $(format_elapsed $total))${NC}"
    else
      ok "${msg} ${DIM}($(format_bytes $final_size))${NC}"
    fi
  fi
  return $rc
}

# ── Apt install with package counting ────────────────────────

spin_apt() {
  local msg="$1"; shift
  # $@ = list of expected package names
  local expected_pkgs=("$@")
  local total=${#expected_pkgs[@]}

  if $DRY_RUN; then
    echo "  [dry-run] apt install ${expected_pkgs[*]}" >> "$LOG_FILE" 2>&1
    return
  fi
  if ! $PACKAGE_MANAGER_REPAIR_ACTIVE; then
    wait_for_package_manager_ready "$msg"
  fi

  DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends "${expected_pkgs[@]}" >> "$LOG_FILE" 2>&1 &
  local pid=$!
  local start_ts tick=0
  start_ts=$(date +%s)

  if [[ -t 1 ]]; then
    while kill -0 "$pid" 2>/dev/null; do
      local now elapsed installed=0 current_pkg=""
      now=$(date +%s)
      elapsed=$(( now - start_ts ))

      # Count how many of our target packages are now installed
      for pkg in "${expected_pkgs[@]}"; do
        if dpkg -s "$pkg" &>/dev/null 2>&1; then
          installed=$(( installed + 1 ))
        fi
      done

      # Try to identify what's being worked on from the log tail
      current_pkg="$(tail -3 "$LOG_FILE" 2>/dev/null | grep -oP '(?:Setting up|Unpacking|Preparing to unpack) \K[^ ]+' | tail -1 || true)"
      current_pkg="${current_pkg%%:*}"  # strip arch suffix

      if (( total > 0 && installed > 0 )); then
        local pct=$(( (installed * 100) / total ))
        local detail="${installed}/${total}"
        [[ -n "$current_pkg" ]] && detail="${detail} · ${current_pkg}"
        draw_pct_bar "$pct" "$msg" "$detail"
      else
        local detail="$(format_elapsed $elapsed)"
        [[ -n "$current_pkg" ]] && detail="${detail} · ${current_pkg}"
        draw_pulse_bar "$tick" "$msg" "$detail"
      fi
      tick=$(( tick + 1 ))
      sleep 0.5
    done
  else
    echo -e "  ${CYAN}⠿${NC} ${msg}..."
  fi

  wait "$pid"
  local rc=$?
  if [[ -t 1 ]]; then
    printf "\r%-120s\r" ""
  fi
  if [[ $rc -eq 0 ]]; then
    local end_ts total_t
    end_ts=$(date +%s)
    total_t=$(( end_ts - start_ts ))
    if (( total_t > 2 )); then
      ok "${msg} ${DIM}(${total} packages, $(format_elapsed $total_t))${NC}"
    else
      ok "${msg}"
    fi
  fi
  return $rc
}

rand_hex()  { openssl rand -hex "${1:-32}"; }
rand_pass() { openssl rand -base64 48 | tr -dc 'a-zA-Z0-9' | head -c "${1:-24}"; }

settle_openclaw_compatibility_hotfix_process() {
  local pid="${OPENCLAW_COMPAT_HOTFIX_PID:-}" state="" attempt
  [[ -n "${pid}" ]] || return 0
  if [[ ! "${pid}" =~ ^[1-9][0-9]*$ ]]; then
    OPENCLAW_COMPAT_HOTFIX_PID=""
    return 1
  fi
  if kill -0 "${pid}" 2>/dev/null; then
    kill -TERM -- "-${pid}" 2>/dev/null \
      || kill -TERM "${pid}" 2>/dev/null \
      || true
    for attempt in {1..50}; do
      if ! kill -0 "${pid}" 2>/dev/null; then
        break
      fi
      state="$(awk '{print $3}' "/proc/${pid}/stat" 2>/dev/null || true)"
      [[ "${state}" == "Z" ]] && break
      sleep 0.1
    done
    if kill -0 "${pid}" 2>/dev/null \
      && [[ "$(awk '{print $3}' "/proc/${pid}/stat" 2>/dev/null || true)" != "Z" ]]; then
      kill -KILL -- "-${pid}" 2>/dev/null \
        || kill -KILL "${pid}" 2>/dev/null \
        || true
    fi
  fi
  wait "${pid}" 2>/dev/null || true
  OPENCLAW_COMPAT_HOTFIX_PID=""
  ! kill -0 "${pid}" 2>/dev/null
}

run_openclaw_compatibility_hotfix() {
  local hotfix_script="$1" openclaw_dist="$2"
  local hotfix_log="${3:-${LOG_FILE}}" status=0 observed_pgid=""
  local pgid_attempt
  command -v setsid >/dev/null 2>&1 || return 1
  setsid env \
    PORTAL_OPENCLAW_HOTFIX_STRICT=1 \
    PORTAL_REQUIRED_OPENCLAW_PACKAGE_VERSION="${PIN_OPENCLAW_CORE_PACKAGE_VERSION}" \
    bash "${hotfix_script}" "${openclaw_dist}" \
      >> "${hotfix_log}" 2>&1 &
  OPENCLAW_COMPAT_HOTFIX_PID=$!
  for pgid_attempt in {1..20}; do
    observed_pgid="$(ps -o pgid= -p "${OPENCLAW_COMPAT_HOTFIX_PID}" 2>/dev/null \
      | tr -d '[:space:]')"
    [[ -z "${observed_pgid}" \
      || "${observed_pgid}" == "${OPENCLAW_COMPAT_HOTFIX_PID}" ]] && break
    sleep 0.05
  done
  if [[ -z "${observed_pgid}" ]]; then
    if wait "${OPENCLAW_COMPAT_HOTFIX_PID}"; then
      status=0
    else
      status=$?
    fi
    OPENCLAW_COMPAT_HOTFIX_PID=""
    return "${status}"
  fi
  if [[ "${observed_pgid}" != "${OPENCLAW_COMPAT_HOTFIX_PID}" ]]; then
    settle_openclaw_compatibility_hotfix_process || true
    return 1
  fi
  if wait "${OPENCLAW_COMPAT_HOTFIX_PID}"; then
    status=0
  else
    status=$?
  fi
  OPENCLAW_COMPAT_HOTFIX_PID=""
  return "${status}"
}

recover_uncommitted_openclaw_after_signal() {
  settle_openclaw_compatibility_hotfix_process || return 1
  if [[ "${UPDATE_RECOVERY_ARMED:-false}" != "true" \
    && "${OPENCLAW_UPGRADE_COMMITTED:-false}" != "true" ]] \
    && declare -F rollback_openclaw_tested_pair >/dev/null 2>&1; then
    rollback_openclaw_tested_pair || warn "The OpenClaw core/plugin pair needs manual recovery; see ${LOG_FILE}."
  fi
}

update_transaction_test_root() {
  local root="${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT:-}"
  [[ -n "${root}" ]] || return 1
  [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" ]] || return 1
  python3 - "${root}" <<'PY2'
import os
import sys

root = sys.argv[1]
if (
    not os.path.isabs(root)
    or root != os.path.normpath(root)
    or root == os.path.sep
    or any(ord(char) < 32 or ord(char) == 127 for char in root)
):
    raise SystemExit(1)
print(root)
PY2
}

update_transaction_state_path() {
  local production_path="$1"
  local test_root=""
  test_root="$(update_transaction_test_root 2>/dev/null || true)"
  if [[ -n "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT:-}" && -z "${test_root}" ]]; then
    return 1
  fi
  if [[ -n "${test_root}" ]]; then
    printf '%s%s\n' "${test_root}" "${production_path}"
  else
    printf '%s\n' "${production_path}"
  fi
}

recover_update_after_signal() {
  local active_journal cutover_journal
  active_journal="$(update_transaction_state_path "${UPDATE_ACTIVE_JOURNAL}")" || return 1
  cutover_journal="$(update_transaction_state_path "${UPDATE_CUTOVER_JOURNAL}")" || return 1
  if [[ -e "${active_journal}" || -L "${active_journal}" \
    || -e "${cutover_journal}" || -L "${cutover_journal}" ]]; then
    declare -F recover_pending_update_transaction >/dev/null 2>&1 \
      && recover_pending_update_transaction
    return
  fi
  recover_uncommitted_openclaw_after_signal
}

handle_installer_signal() {
  local exit_code="$1" message="$2"
  local interrupted_phase="${DASHBOARD_UPDATE_PROGRESS_PHASE:-failure}"
  trap '' SIGINT TERM HUP
  trap - ERR
  set +e
  if [[ "${DASHBOARD_UPDATE_PORTAL_COMMITTED:-false}" == "true" ]]; then
    dashboard_update_progress updated_with_errors \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${interrupted_phase}" \
      "Portal updated; follow-up work was interrupted" "${message}"
  elif [[ "${UPDATE_RECOVERY_ARMED:-false}" == "true" ]]; then
    dashboard_update_progress recovering \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
      "Installer interrupted — checking recovery" "${message}"
  else
    dashboard_update_progress running \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" failure \
      "Installer interrupted" "${message}"
  fi
  echo ""
  echo -e "\n  ${YELLOW}⚠  ${message}${NC}"
  echo ""
  if ! settle_openclaw_compatibility_hotfix_process; then
    warn "The OpenClaw compatibility patch process could not be proven stopped. Recovery was not started."
    [[ "${UPDATE_RECOVERY_ARMED:-false}" != "true" ]] \
      || dashboard_update_progress recovery_required \
        "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${interrupted_phase}" \
        "Automatic recovery needs attention" \
        "A compatibility process could not be proven stopped. Do not start another update."
    exit "${exit_code}"
  fi
  if declare -F settle_active_update_database_operation >/dev/null 2>&1 \
    && ! settle_active_update_database_operation; then
    warn "The active database operation could not be proven stopped. Recovery was not started; the Portal remains boot-fenced."
    dashboard_update_progress recovery_required \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${interrupted_phase}" \
      "Automatic recovery needs attention" \
      "The database operation could not be proven stopped. Do not start another update."
    exit "${exit_code}"
  fi
  if ! recover_update_after_signal; then
    warn "Update recovery did not complete. Portal remains boot-fenced and recovery artifacts were preserved."
    dashboard_update_progress recovery_required \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${interrupted_phase}" \
      "Automatic recovery needs attention" \
      "Recovery after interruption did not complete. Do not start another update."
  elif [[ "${DASHBOARD_UPDATE_PORTAL_COMMITTED:-false}" == "true" ]]; then
    # A cutover receipt recovers forward, not backward. Recovery may have
    # committed the target Portal after the signal arrived, so preserve that
    # exact outcome instead of letting the outer nonzero exit look like an
    # ordinary pre-commit failure.
    dashboard_update_progress updated_with_errors \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${interrupted_phase}" \
      "Portal updated; follow-up work was interrupted" "${message}"
  fi
  exit "${exit_code}"
}

handle_sigint() {
  handle_installer_signal 130 "Installation cancelled by user"
}

handle_sigterm() {
  handle_installer_signal 143 "Installation terminated"
}

handle_sighup() {
  handle_installer_signal 129 "Installer session disconnected"
}

handle_err() {
  local exit_code=$?
  local line_no=${1:-unknown}
  fail "Unexpected error (exit ${exit_code}) at line ${line_no}"
}

handle_update_transaction_err() {
  local exit_code="${1:-1}"
  local failed_phase="${DASHBOARD_UPDATE_PROGRESS_PHASE:-failure}"
  [[ "${exit_code}" =~ ^[1-9][0-9]*$ ]] || exit_code=1
  trap - ERR
  trap '' SIGINT TERM HUP
  set +e
  dashboard_update_progress recovering \
    "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
    "Unexpected installer error — recovering" \
    "The durable transaction is restoring or completing a verified Portal state."
  if ! settle_openclaw_compatibility_hotfix_process; then
    warn "The OpenClaw compatibility patch process could not be proven stopped. Recovery was not started."
    dashboard_update_progress recovery_required \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${failed_phase}" \
      "Automatic recovery needs attention" \
      "A compatibility process could not be proven stopped. Do not start another update."
    exit "${exit_code}"
  fi
  if declare -F settle_active_update_database_operation >/dev/null 2>&1 \
    && ! settle_active_update_database_operation; then
    warn "The active database operation could not be proven stopped. Recovery was not started; the Portal remains boot-fenced."
    dashboard_update_progress recovery_required \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${failed_phase}" \
      "Automatic recovery needs attention" \
      "The database operation could not be proven stopped. Do not start another update."
    exit "${exit_code}"
  fi
  if ! recover_pending_update_transaction; then
    warn "Update recovery did not complete. Portal remains boot-fenced and recovery artifacts were preserved."
    dashboard_update_progress recovery_required \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${failed_phase}" \
      "Automatic recovery needs attention" \
      "The transaction stopped without a verified terminal state. Do not start another update."
  elif [[ "${DASHBOARD_UPDATE_PORTAL_COMMITTED:-false}" == "true" ]]; then
    dashboard_update_progress updated_with_errors \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" "${failed_phase}" \
      "Portal updated; follow-up work failed" \
      "The cutover recovered forward, but the installer exited before completing host integration."
  fi
  exit "${exit_code}"
}

trap 'handle_err $LINENO' ERR
trap handle_sigint SIGINT
trap handle_sigterm TERM
trap handle_sighup HUP

ensure_keyring_from_url() {
  local url="$1"
  local keyring="$2"
  local tmp
  tmp="$(mktemp)"

  if $DRY_RUN; then
    echo "  [dry-run] refresh keyring ${keyring} from ${url}" >> "$LOG_FILE" 2>&1
    rm -f "$tmp"
    return
  fi

  curl -fsSL "${url}" | gpg --dearmor > "${tmp}"
  install -D -m 0644 "${tmp}" "${keyring}"
  rm -f "${tmp}"
}

parse_strict_systemd_environment_file() {
  local file="$1"
  local key="${2:-}"
  [[ -f "${file}" && ! -L "${file}" ]] || return 1
  [[ -z "${key}" || "${key}" =~ ^[A-Z][A-Z0-9_]*$ ]] || return 1
  python3 - "${file}" "${key}" <<'PY2'
import re
import sys
from pathlib import Path
file_path, key = sys.argv[1], sys.argv[2]
try:
    payload = Path(file_path).read_bytes()
    text = payload.decode("utf-8")
except (OSError, UnicodeError):
    raise SystemExit(1)
if b"\x00" in payload or "\r" in text:
    raise SystemExit(1)

# Accept one deliberately small, systemd-equivalent EnvironmentFile subset.
# Backslashes are forbidden rather than reimplemented: in systemd they can
# escape characters or continue a physical line, which was the source of the
# installer/service split-authority bug. Assignments must be KEY=value with
# optional whole-value single/double quoting and no shell-only `export`.
assignment = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)=(.*)$")
values = {}
for line_number, raw in enumerate(text.split("\n"), start=1):
    if not raw or raw.lstrip().startswith(("#", ";")):
        continue
    match = assignment.fullmatch(raw)
    if match is None:
        print(f"unsupported environment syntax on line {line_number}", file=sys.stderr)
        raise SystemExit(1)
    name, value = match.groups()
    if name in values:
        print(f"duplicate assignment of {name}", file=sys.stderr)
        raise SystemExit(1)
    if "\\" in value:
        print(f"backslash syntax is not accepted on line {line_number}", file=sys.stderr)
        raise SystemExit(1)
    if any(ord(char) < 32 or ord(char) == 127 for char in value):
        print(f"control character in value on line {line_number}", file=sys.stderr)
        raise SystemExit(1)
    if value[:1] in {"'", '"'}:
        quote = value[0]
        if len(value) < 2 or value[-1] != quote or quote in value[1:-1]:
            print(f"unsupported quoted value on line {line_number}", file=sys.stderr)
            raise SystemExit(1)
        value = value[1:-1]
    elif any(char in value for char in "\"'") or value != value.strip(" \t"):
        print(f"unsupported unquoted value on line {line_number}", file=sys.stderr)
        raise SystemExit(1)
    values[name] = value
if key and key in values:
    print(values[key])
PY2
}

read_env_value() {
  local file="$1"
  local key="$2"
  parse_strict_systemd_environment_file "${file}" "${key}"
}

assert_env_file_no_duplicate_keys() {
  # This is intentionally the same parser used for every installer read.
  # Besides duplicates, it rejects systemd quoting/escape/continuation forms
  # outside the generated strict subset before any snapshot or mutation.
  parse_strict_systemd_environment_file "$1"
}

env_file_has_assignment() {
  local file="$1"
  local key="$2"
  [[ -f "${file}" && ! -L "${file}" ]] || return 2
  [[ "${key}" =~ ^[A-Z][A-Z0-9_]*$ ]] || return 2
  parse_strict_systemd_environment_file "${file}" || return 2
  python3 - "${file}" "${key}" <<'PY2'
import re
import sys
from pathlib import Path

path = Path(sys.argv[1])
key = sys.argv[2]
assignment = re.compile(rf"^{re.escape(key)}=")
try:
    found = any(assignment.match(line) for line in path.read_text().splitlines())
except (OSError, UnicodeError):
    raise SystemExit(2)
raise SystemExit(0 if found else 1)
PY2
}

assert_database_process_environment_safe() {
  local key
  for key in \
    PRISMA_CLIENT_ENGINE_TYPE \
    PRISMA_QUERY_ENGINE_BINARY \
    PRISMA_QUERY_ENGINE_LIBRARY \
    PRISMA_CLIENT_GET_TIME \
    NODE_PG_FORCE_NATIVE \
    NODE_TLS_REJECT_UNAUTHORIZED \
    PGUSER \
    PGDATABASE \
    PGPORT \
    PGHOST \
    PGPASSWORD \
    PGBINARY \
    PGOPTIONS \
    PGSSLMODE \
    PGSSLNEGOTIATION \
    PGCLIENT_ENCODING \
    PGREPLICATION \
    PGAPPNAME \
    PGCONNECT_TIMEOUT; do
    [[ ! -v "${key}" ]] || return 1
  done
}

assert_prisma_runtime_environment_safe() {
  local env_file="$1" key status
  assert_database_process_environment_safe || return 1
  assert_env_file_no_duplicate_keys "${env_file}" || return 1
  for key in \
    PRISMA_CLIENT_ENGINE_TYPE \
    PRISMA_QUERY_ENGINE_BINARY \
    PRISMA_QUERY_ENGINE_LIBRARY \
    PRISMA_CLIENT_GET_TIME \
    NODE_PG_FORCE_NATIVE \
    NODE_TLS_REJECT_UNAUTHORIZED \
    PGUSER \
    PGDATABASE \
    PGPORT \
    PGHOST \
    PGPASSWORD \
    PGBINARY \
    PGOPTIONS \
    PGSSLMODE \
    PGSSLNEGOTIATION \
    PGCLIENT_ENCODING \
    PGREPLICATION \
    PGAPPNAME \
    PGCONNECT_TIMEOUT; do
    status=0
    env_file_has_assignment "${env_file}" "${key}" || status=$?
    case "${status}" in
      1) ;;
      *) return 1 ;;
    esac
  done
}

remove_env_assignment_atomic() {
  local file="$1"
  local key="$2"
  [[ -f "${file}" && ! -L "${file}" ]] || return 1
  [[ "${key}" =~ ^[A-Z][A-Z0-9_]*$ ]] || return 1
  parse_strict_systemd_environment_file "${file}" || return 1
  python3 - "${file}" "${key}" <<'PY2'
import os
import re
import stat
import sys
import tempfile
from pathlib import Path

path = Path(sys.argv[1])
key = sys.argv[2]
current = path.lstat()
if (
    not stat.S_ISREG(current.st_mode)
    or stat.S_ISLNK(current.st_mode)
    or current.st_nlink != 1
):
    raise SystemExit(1)
assignment = re.compile(rf"^{re.escape(key)}=")
lines = path.read_text().splitlines()
payload = ("\n".join(line for line in lines if not assignment.match(line)) + "\n").encode()
fd, temporary = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
try:
    os.fchmod(fd, stat.S_IMODE(current.st_mode))
    os.fchown(fd, current.st_uid, current.st_gid)
    with os.fdopen(fd, "wb", closefd=True) as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, path)
    temporary = ""
    directory_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if temporary:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
PY2
}

set_env_value_atomic() {
  local file="$1"
  local key="$2"
  local value="$3"
  [[ -f "${file}" && ! -L "${file}" ]] || return 1
  [[ "${key}" =~ ^[A-Z][A-Z0-9_]*$ ]] || return 1
  [[ "${value}" != *$'\n'* && "${value}" != *$'\r'* \
    && "${value}" != *'\'* && "${value}" != *'"'* \
    && "${value}" != *"'"* \
    && "${value}" == "${value#"${value%%[![:space:]]*}"}" \
    && "${value}" == "${value%"${value##*[![:space:]]}"}" ]] || return 1
  parse_strict_systemd_environment_file "${file}" || return 1

  # Send the value over stdin rather than argv so secrets never appear in the
  # process list. The replace+directory fsync keeps a killed installer from
  # leaving a partially written production environment.
  printf '%s' "${value}" | python3 /dev/fd/3 "${file}" "${key}" 3<<'PY2'
import os
import re
import sys
import tempfile
from pathlib import Path

path = Path(sys.argv[1])
key = sys.argv[2]
value = sys.stdin.read()
if path.is_symlink() or not path.is_file() or any(char in value for char in "\r\n\x00"):
    raise SystemExit(1)

lines = path.read_text().splitlines()
output = []
replaced = False
assignment = re.compile(rf"^{re.escape(key)}=")
for line in lines:
    if assignment.match(line):
        if not replaced:
            output.append(f"{key}={value}")
            replaced = True
        continue
    output.append(line)
if not replaced:
    output.append(f"{key}={value}")
payload = ("\n".join(output) + "\n").encode()

fd, temporary = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
try:
    os.fchmod(fd, 0o600)
    with os.fdopen(fd, "wb", closefd=True) as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, path)
    directory_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
except BaseException:
    try:
        os.close(fd)
    except OSError:
        pass
    try:
        os.unlink(temporary)
    except FileNotFoundError:
        pass
    raise
PY2
}

valid_project_egress_token_secret() {
  local value="${1:-}"
  [[ "${value}" =~ ^[A-Za-z0-9_-]{43,256}$ ]]
}

ensure_project_egress_token_secret() {
  local env_file="${1:-${PORTAL_DIR}/backend/.env.production}"
  local existing=""
  existing="$(read_env_value "${env_file}" "PROJECT_EGRESS_TOKEN_SECRET" 2>/dev/null || true)"
  if [[ -n "${existing}" ]]; then
    valid_project_egress_token_secret "${existing}" \
      || fail "PROJECT_EGRESS_TOKEN_SECRET is malformed; refusing to rotate an active Project credential root automatically."
    PROJECT_EGRESS_TOKEN_SECRET="${existing}"
  else
    PROJECT_EGRESS_TOKEN_SECRET="$(rand_hex 32)"
    valid_project_egress_token_secret "${PROJECT_EGRESS_TOKEN_SECRET}" \
      || fail "Could not generate the Project egress credential secret."
  fi
  set_env_value_atomic "${env_file}" "PROJECT_EGRESS_TOKEN_SECRET" "${PROJECT_EGRESS_TOKEN_SECRET}" \
    || fail "Could not persist the Project egress credential secret safely."
  [[ "$(read_env_value "${env_file}" "PROJECT_EGRESS_TOKEN_SECRET" 2>/dev/null || true)" == "${PROJECT_EGRESS_TOKEN_SECRET}" ]] \
    || fail "Project egress credential secret verification failed."
  ok "Project egress credential secret (verified)"
}

release_base_url_is_trusted() {
  python3 - "${RELEASE_BASE_URL}" <<'PY2'
import sys
from urllib.parse import urlparse

parsed = urlparse(sys.argv[1])
if parsed.username or parsed.password or parsed.query or parsed.fragment:
    raise SystemExit(1)
if parsed.scheme == "https" and parsed.hostname:
    raise SystemExit(0)
if parsed.scheme == "http" and parsed.hostname in {"127.0.0.1", "::1", "localhost"}:
    raise SystemExit(0)
raise SystemExit(1)
PY2
}

write_release_verification_key() {
  local destination="$1"
  cat > "${destination}" <<'KEY'
-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEAF0Mqi+e9entO6AacPZbQ4lBQ+hModVr2tqb/P3tkQD4=
-----END PUBLIC KEY-----
KEY
  chmod 0600 "${destination}"
}

verify_release_bundle() {
  local bundle_dir="$1"
  local artifact="${bundle_dir}/portal.tar.gz"
  local manifest="${bundle_dir}/portal-release.manifest"
  local signature="${bundle_dir}/portal-release.sig"
  local public_key=""
  local verify_log="/dev/null"

  [[ -s "${artifact}" && -s "${manifest}" && -s "${signature}" ]] || return 1
  (( $(stat -c '%s' "${manifest}") <= 16384 )) || return 1
  (( $(stat -c '%s' "${signature}") <= 4096 )) || return 1

  [[ -d "$(dirname "${LOG_FILE}")" && -w "$(dirname "${LOG_FILE}")" ]] && verify_log="${LOG_FILE}"
  public_key="$(mktemp "${bundle_dir}/.release-key.XXXXXX")" || return 1
  if ! write_release_verification_key "${public_key}" \
    || [[ "$(openssl pkey -pubin -in "${public_key}" -outform DER 2>/dev/null | sha256sum | awk '{print $1}')" != "${RELEASE_PUBLIC_KEY_SHA256}" ]] \
    || ! openssl pkeyutl -verify -pubin -inkey "${public_key}" -rawin \
      -in "${manifest}" -sigfile "${signature}" >> "${verify_log}" 2>&1; then
    rm -f -- "${public_key}"
    return 1
  fi

  if ! python3 - "${manifest}" "${artifact}" "${VERSION}" "${public_key}" <<'PY2'
import base64
import datetime
import hashlib
import json
import os
import re
import stat
import subprocess
import sys
import tarfile
