manifest_path, artifact_path, expected_version, public_key_path = sys.argv[1:5]
raw = open(manifest_path, "rb").read()
if b"\x00" in raw or b"\r" in raw:
    raise SystemExit("invalid manifest encoding")
values = {}
for line in raw.decode("utf-8").splitlines():
    if not line or "=" not in line:
        raise SystemExit("invalid manifest line")
    key, value = line.split("=", 1)
    if key in values:
        raise SystemExit("duplicate manifest key")
    values[key] = value

base_required = {"schema", "version", "artifact", "sha256", "size"}
metadata_required = {"released", "release_class", "highlights"}
if values.get("schema") == "1":
    if set(values) != base_required:
        raise SystemExit("unsupported manifest schema")
elif values.get("schema") == "2":
    if set(values) != base_required | metadata_required:
        raise SystemExit("unsupported manifest schema")
else:
    raise SystemExit("unsupported manifest schema")
if values["version"] != expected_version or not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", values["version"]):
    raise SystemExit("release version mismatch")
if values["artifact"] != "portal.tar.gz":
    raise SystemExit("unexpected artifact name")
if not re.fullmatch(r"[0-9a-f]{64}", values["sha256"]):
    raise SystemExit("invalid artifact digest")
size = os.path.getsize(artifact_path)
if size <= 0 or size > 536_870_912 or str(size) != values["size"]:
    raise SystemExit("artifact size mismatch")
hasher = hashlib.sha256()
with open(artifact_path, "rb") as artifact:
    for chunk in iter(lambda: artifact.read(1024 * 1024), b""):
        hasher.update(chunk)
digest = hasher.hexdigest()
if digest != values["sha256"]:
    raise SystemExit("artifact digest mismatch")

manifest_highlights = None
if values["schema"] == "2":
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", values["released"]):
        raise SystemExit("invalid release date")
    try:
        if datetime.date.fromisoformat(values["released"]).isoformat() != values["released"]:
            raise ValueError
    except ValueError:
        raise SystemExit("invalid release date")
    if values["release_class"] not in {"hotfix", "security", "feature", "maintenance"}:
        raise SystemExit("invalid release class")
    encoded_highlights = values["highlights"]
    if not encoded_highlights or len(encoded_highlights) > 8192 or not re.fullmatch(r"[A-Za-z0-9_-]+", encoded_highlights):
        raise SystemExit("invalid release highlights")
    try:
        padding = "=" * (-len(encoded_highlights) % 4)
        highlight_bytes = base64.urlsafe_b64decode(encoded_highlights + padding)
        if base64.urlsafe_b64encode(highlight_bytes).rstrip(b"=").decode("ascii") != encoded_highlights:
            raise ValueError
        manifest_highlights = json.loads(highlight_bytes.decode("utf-8"))
    except (ValueError, UnicodeDecodeError, json.JSONDecodeError):
        raise SystemExit("invalid release highlights")
    if not isinstance(manifest_highlights, list) or not (1 <= len(manifest_highlights) <= 5):
        raise SystemExit("invalid release highlights")
    for highlight in manifest_highlights:
        if (not isinstance(highlight, str) or highlight != highlight.strip()
                or not (1 <= len(highlight) <= 200)
                or any(ord(character) < 32 or ord(character) == 127 for character in highlight)):
            raise SystemExit("invalid release highlight")
    if len(set(manifest_highlights)) != len(manifest_highlights):
        raise SystemExit("duplicate release highlight")

