            raise SystemExit("archive contains links or special files")
        relative_parts = tuple(part.lower() for part in path.parts[1:])
        if any(part in {
            ".data", ".git", ".ssh", "app-zips", "apps", "coverage",
            "node_modules", "projects", "reports", "src", "uploads",
