    inventory = inventory_raw.decode("utf-8").splitlines()
    if not inventory or len(inventory) > 4096 or len(inventory) != len(set(inventory)):
        raise SystemExit("invalid release inventory")
    for required_name in inventory:
        required_path = PurePosixPath(required_name)
        if (not required_name or required_name != required_name.strip()
                or required_path.is_absolute() or ".." in required_path.parts
                or not required_path.parts or required_path.parts[0] != "portal"):
            raise SystemExit("unsafe release inventory path")
    inventory_set = set(inventory)
    if not required_baseline_members.issubset(inventory_set) or not inventory_set.issubset(seen):
