    }
    inventory_skill = {
        name for name in inventory_set if name.startswith("portal/skills/bridgesllm-portal/")
    }
    if archive_skill != required_current_skill or inventory_skill != required_current_skill:
        raise SystemExit("bundled Portal skill does not match its required inventory")

    contents_raw = read_member("portal/RELEASE-CONTENTS.sha256", 16 * 1024 * 1024)
