        hasher = hashlib.sha256()
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            hasher.update(chunk)
        if hasher.hexdigest() != expected_hash:
            raise SystemExit(f"release content digest mismatch: {name}")

