# Retire the one known Portal-created all-images prune job and fail closed on
# literal unsafe prune commands in effective installed root scheduler
# definitions and their bounded, strict absolute helper-script chain. Opaque
# executables, arbitrary shell variables, relative helpers, and external
# program construction remain outside a static installer inspection.
# The optional root argument is only for isolated installer fixtures.
converge_unsafe_docker_prune_automation() {
  local host_root="${1:-/}"
  command -v python3 >/dev/null 2>&1 \
    || { warn "Python 3 is required to inspect scheduled Docker cleanup jobs safely."; return 1; }

  python3 - \
    "${host_root}" \
    "${LEGACY_DOCKER_PRUNE_CRON_PATH}" \
    "${LEGACY_DOCKER_PRUNE_QUARANTINE_PATH}" <<'PY2'
import ctypes
import errno
import hashlib
import os
import re
import shlex
import stat
import sys

LIMIT = 1024 * 1024
HELPER_FILE_LIMIT = 128 * 1024
HELPER_TOTAL_LIMIT = 1024 * 1024
HELPER_FILE_COUNT_LIMIT = 96
HELPER_LINE_LIMIT = 16384
HELPER_DEPTH_LIMIT = 4
WRAPPER_DEPTH_LIMIT = 16
SCHEDULER_ENTRY_LIMIT = 16384
HELPER_CANDIDATE_FILE_LIMIT = 256
HELPER_CANDIDATE_TOTAL_LIMIT = 4 * 1024 * 1024
HELPER_CANDIDATE_LINE_LIMIT = 65536
PORTAL_AUDITED_HELPER_LIMIT = 512 * 1024
# Exact backup-full.sh payloads retained from installable Portal 4.0 releases.
# installer/backup-helper-identities.tsv is the append-only, version-labelled
# source ledger; the release gate validates every historical Git blob and
# requires this set to match that ledger exactly. The backup service
# legitimately schedules this larger audited entrypoint. Keep arbitrary
# operator helpers on the generic 128 KiB per-file, 96-file, 1 MiB aggregate,
# and 16,384 executable-line work bounds.
PORTAL_BACKUP_HELPER_RELEASES = {
    (223518, "4988ba5be75e7e78e9c0f0981684c0a9203c7175f353eb07f890d337df8e1b1b"),
    (224956, "fc6751d6844589e081911e425c551afb317a3ded4b9d465b754dc7113c3c9454"),
    (227908, "a25a3d3562dfc2b51798916b893070f811e91074ef9c40430f296f22afd5a736"),
    (229463, "cba9826305c93de11f99699437937d6f7f89e1ae9869f415df903b047c5f2816"),
    (248156, "5b42a047fa07e3b5af2752b85f6d3e22e5944778c660799cf2eaade18f868143"),
    (263283, "337d15eb7289a63f77429aee7677ebb8c1aa4a037698111c591565a3496a1a85"),
    (268494, "384e21ade857380bdced2855671184f0a624338dcc20da3f21bea09cdc6178c9"),
    # 4.0.15 shipped a rewritten helper (degraded-backup preservation) without
    # adding it here, so 4.0.15's own guard rejected the helper 4.0.15 installs
    # and every host that reached 4.0.15 was blocked from updating again.
    # scripts/validation/backup-helper-allowlist-static.py now fails the build
    # when this set does not cover the helper the release actually ships.
    (271864, "c68881be5af61d0ba778b37fbea65068f650b74ab96703f15cafe73420b34f6c"),
    (288193, "04309ddec3ab7f2ae5c18d68a6e07b09809924f94a3f77b9694da90aa8c48305"),
}
PORTAL_RUNTIME_REPAIR_LAUNCHER = (
    "/opt/bridgesllm/portal/installer/"
    "project-runtime-image-repair-launcher.py"
)
PORTAL_RUNTIME_REPAIR_UNIT = (
    "/run/systemd/transient/"
    "bridgesllm-project-runtime-image-repair.service"
)
PORTAL_RUNTIME_REPAIR_LAUNCHER_CURRENT = (8641, "9bb962ad51725c2025d4813bb84c1887c115f47ca891134a5f3e70abfa8bc9ee")
PORTAL_RUNTIME_REPAIR_LAUNCHER_RELEASES = {
    PORTAL_RUNTIME_REPAIR_LAUNCHER_CURRENT,
}
LEGACY = b'13 0 * * * root docker image prune -af --filter "until=24h"\n'
SEPARATORS = {";", "&", "&&", "|", "||"}
EXEC_KEYS = {
    "ExecCondition", "ExecReload", "ExecStart", "ExecStartPost",
    "ExecStartPre", "ExecStop", "ExecStopPost",
}
UNIT_SUFFIXES = {
    ".automount", ".path", ".scope", ".service", ".slice",
    ".socket", ".swap", ".target", ".timer",
}
SHELL_NAMES = {"bash", "dash", "ksh", "sh", "zsh"}
PERL_NAMES = {"perl"}
RUBY_NAMES = {"ruby"}
NODE_NAMES = {"node", "nodejs"}
BUILTIN_WRAPPERS = {"command", "exec"}
SHELL_CONTROL_PREFIXES = {"!", "{", "coproc", "do", "elif", "else", "if", "then", "until", "while"}
DOCKER_TRUE_VALUES = {"1", "t", "true"}
DOCKER_FALSE_VALUES = {"0", "f", "false"}


def fail(message):
    print(f"Unsafe Docker prune guard: {message}", file=sys.stderr)
    raise SystemExit(1)


root = os.path.abspath(sys.argv[1])
source_logical, quarantine_logical = sys.argv[2:4]


def host_path(logical):
    value = os.path.normpath(os.path.join(root, logical.lstrip("/")))
    if root != "/" and value != root and not value.startswith(root + os.sep):
        fail(f"mapped path escapes the fixture root: {logical}")
    return value


def display(path):
    if root == "/":
        return path
    relative = os.path.relpath(path, root)
    return "/" if relative == "." else "/" + relative


def lstat_or_none(path):
    try:
        return os.lstat(path)
    except FileNotFoundError:
        return None
    except OSError as exc:
        fail(f"could not inspect {display(path)}: {exc}")


def read_root_file(path, modes=None, single_link=False, require_root_group=False):
    before = lstat_or_none(path)
    if before is None:
        return None, None
    mode = stat.S_IMODE(before.st_mode)
    if not stat.S_ISREG(before.st_mode) or stat.S_ISLNK(before.st_mode):
        fail(f"{display(path)} is not a regular file; inspect it manually")
    if before.st_uid != 0 or (require_root_group and before.st_gid != 0):
        expected_owner = "root:root" if require_root_group else "root"
        fail(f"{display(path)} is not owned by {expected_owner}; inspect it manually")
    if single_link and before.st_nlink != 1:
        fail(f"{display(path)} has unexpected hard links; inspect it manually")
    if modes is not None and mode not in modes:
        expected = ", ".join(f"{item:04o}" for item in sorted(modes))
        fail(f"{display(path)} has mode {mode:04o}, expected {expected}")
    if before.st_size > LIMIT:
        fail(f"{display(path)} exceeds the 1 MiB job inspection limit")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        fail(f"could not open {display(path)} without following links: {exc}")
    try:
        opened = os.fstat(descriptor)
        before_id = (
            before.st_dev, before.st_ino, before.st_mode, before.st_uid,
            before.st_gid, before.st_nlink, before.st_size,
            before.st_mtime_ns, before.st_ctime_ns,
        )
        opened_id = (
            opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid,
            opened.st_gid, opened.st_nlink, opened.st_size,
            opened.st_mtime_ns, opened.st_ctime_ns,
        )
        if opened_id != before_id:
            fail(f"{display(path)} changed during inspection")
        payload = b""
        while len(payload) <= LIMIT:
            chunk = os.read(descriptor, min(65536, LIMIT + 1 - len(payload)))
            if not chunk:
                break
            payload += chunk
        if len(payload) > LIMIT:
            fail(f"{display(path)} exceeds the 1 MiB job inspection limit")
        after = os.fstat(descriptor)
        after_id = (
            after.st_dev, after.st_ino, after.st_mode, after.st_uid,
            after.st_gid, after.st_nlink, after.st_size,
            after.st_mtime_ns, after.st_ctime_ns,
        )
        if after_id != opened_id:
            fail(f"{display(path)} changed while it was read")
        return payload, before
    finally:
        os.close(descriptor)


def require_secure_directory(
    path,
    metadata,
    context,
    *,
    allow_standard_crontab_spool=False,
    require_root_group=True,
):
    mode = stat.S_IMODE(metadata.st_mode)
    if (
        allow_standard_crontab_spool
        and display(path) == "/var/spool/cron/crontabs"
        and stat.S_ISDIR(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_uid == 0
        and mode == 0o1730
    ):
        # Debian/Ubuntu deliberately use root:crontab 1730 here so the
        # setgid crontab helper can install per-user spools. Its sticky bit,
        # lack of world access, and root ownership are the supported secure
        # exception to the otherwise root:root/non-writable chain.
        return
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or metadata.st_uid != 0
        or (require_root_group and metadata.st_gid != 0)
        or mode & 0o022
    ):
        fail(
            f"{context} directory {display(path)} is linked, non-root-owned, "
            "or writable by another account"
        )


def resolve_secure_path(
    path,
    *,
    allow_missing=False,
    allow_mask=False,
    final_kind,
    require_root_group=True,
    require_root_group_directories=True,
    require_owner_readable=False,
    allow_standard_crontab_spool=False,
):
    normalized = os.path.normpath(path)
    if root != "/" and normalized != root and not normalized.startswith(root + os.sep):
        fail(f"secure path escapes the host root: {path}")
    relative = os.path.relpath(normalized, root)
    pending = [] if relative == "." else relative.split(os.sep)
    current = root
    root_stat = lstat_or_none(root)
    if root_stat is None:
        fail("host root disappeared during scheduler inspection")
    require_secure_directory(
        root,
        root_stat,
        "scheduler",
        allow_standard_crontab_spool=allow_standard_crontab_spool,
    )
    symlink_count = 0
    visited_links = set()
    required_link_target_components = 0

    while pending:
        component = pending.pop(0)
        if component in {"", "."}:
            continue
        if component == "..":
            fail(f"secure path escapes the host root: {path}")
        candidate = os.path.join(current, component)
        metadata = lstat_or_none(candidate)
        if metadata is None:
            if allow_missing and required_link_target_components == 0:
                return None, False
            fail(f"scheduled path {display(candidate)} is missing or a link target is broken")
        if stat.S_ISLNK(metadata.st_mode):
            if metadata.st_uid != 0 or metadata.st_gid != 0:
                fail(f"scheduled path link {display(candidate)} is not owned by root:root")
            symlink_count += 1
            if symlink_count > 32:
                fail(f"scheduled path {display(path)} has too many link indirections")
            link_identity = (metadata.st_dev, metadata.st_ino)
            if link_identity in visited_links:
                fail(f"scheduled path {display(path)} contains a link cycle")
            visited_links.add(link_identity)
            try:
                link_target = os.readlink(candidate)
            except OSError as exc:
                fail(f"could not read scheduled path link {display(candidate)}: {exc}")
            target = (
                host_path(link_target)
                if os.path.isabs(link_target)
                else os.path.normpath(os.path.join(os.path.dirname(candidate), link_target))
            )
            if root != "/" and target != root and not target.startswith(root + os.sep):
                fail(f"scheduled path link {display(candidate)} escapes the host root")
            if allow_mask and not pending and target == host_path("/dev/null"):
                return None, True
            target_relative = os.path.relpath(target, root)
            target_parts = [] if target_relative == "." else target_relative.split(os.sep)
            required_link_target_components = (
                len(target_parts)
                + max(required_link_target_components - 1, 0)
            )
            pending = target_parts + pending
            current = root
            continue
        if required_link_target_components > 0:
            required_link_target_components -= 1
        if pending:
            require_secure_directory(
                candidate,
                metadata,
                "scheduler",
                allow_standard_crontab_spool=allow_standard_crontab_spool,
                require_root_group=require_root_group_directories,
            )
        current = candidate

    metadata = lstat_or_none(current)
    if metadata is None:
        if allow_missing and symlink_count == 0:
            return None, False
        fail(f"scheduled path {display(current)} disappeared during inspection")
    if final_kind == "directory":
        require_secure_directory(
            current,
            metadata,
            "scheduler",
            allow_standard_crontab_spool=allow_standard_crontab_spool,
            require_root_group=require_root_group_directories,
        )
    elif final_kind == "file":
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != 0
            or (require_root_group and metadata.st_gid != 0)
            or stat.S_IMODE(metadata.st_mode) & 0o022
            or (require_owner_readable and not metadata.st_mode & stat.S_IRUSR)
        ):
            if not require_owner_readable:
                fail(
                    f"scheduled definition or helper {display(current)} is non-regular, "
                    "non-root-owned, or writable by another account"
                )
            fail(
                f"scheduled definition or helper {display(current)} is non-regular, "
                "unreadable, non-root-owned, or writable by another account"
            )
    elif final_kind == "either":
        if stat.S_ISDIR(metadata.st_mode):
            require_secure_directory(
                current,
                metadata,
                "scheduler",
                allow_standard_crontab_spool=allow_standard_crontab_spool,
                require_root_group=require_root_group_directories,
            )
        elif (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != 0
            or (require_root_group and metadata.st_gid != 0)
            or stat.S_IMODE(metadata.st_mode) & 0o022
            or (require_owner_readable and not metadata.st_mode & stat.S_IRUSR)
        ):
            if not require_owner_readable:
                fail(
                    f"scheduled definition or helper {display(current)} is non-regular, "
                    "non-root-owned, or writable by another account"
                )
            fail(
                f"scheduled definition or helper {display(current)} is non-regular, "
                "unreadable, non-root-owned, or writable by another account"
            )
    else:
        fail(f"unsupported secure-path kind: {final_kind}")
    return current, False


def tokens(value):
    try:
        lexer = shlex.shlex(value, posix=True, punctuation_chars=";&|")
        lexer.whitespace_split = True
        lexer.commenters = "#"
        return list(lexer)
    except ValueError:
        return re.findall(r"&&|\|\||[;&|]|[^\s;&|]+", value)


def word(value):
    cleaned = value.strip("$(){}[]<>,\"'")
    prefix_match = re.match(r"^[-+!:@]+", cleaned)
    if prefix_match:
        prefix = prefix_match.group(0)
        return prefix + os.path.basename(cleaned[len(prefix):])
    return os.path.basename(cleaned)


def is_known_legacy_payload(payload):
    """Recognize the retired Portal cron job plus inert output redirects."""
    if b"\0" in payload:
        return False
    try:
        text = payload.decode("utf-8")
    except UnicodeDecodeError:
        return False
    stripped = text.strip()
    if not stripped or len(stripped.splitlines()) != 1:
        return False
    fields = stripped.split(None, 6)
    if len(fields) != 7 or fields[:6] != ["13", "0", "*", "*", "*", "root"]:
        return False
    try:
        lexer = shlex.shlex(fields[6], posix=True, punctuation_chars="><;&|")
        lexer.whitespace_split = True
        lexer.commenters = ""
        command = list(lexer)
    except ValueError:
        return False
    base = [
        "docker", "image", "prune", "-af", "--filter", "until=24h",
    ]
    if command[:len(base)] != base:
        return False
    suffix = command[len(base):]
    seen_stdout, seen_stderr = False, False
    while suffix:
        if suffix[:2] == [">", "/dev/null"]:
            if seen_stdout:
                return False
            seen_stdout = True
            suffix = suffix[2:]
            continue
        if suffix[:3] == ["1", ">", "/dev/null"]:
            if seen_stdout:
                return False
            seen_stdout = True
            suffix = suffix[3:]
            continue
        if suffix[:3] == ["2", ">&", "1"]:
            if seen_stderr:
                return False
            seen_stderr = True
            suffix = suffix[3:]
            continue
        return False
    return True


def systemd_effective_argv(arguments):
    argv = list(arguments)
    if not argv:
        return argv
    prefix_match = re.match(r"^[-+!:@]+", argv[0])
    prefix = prefix_match.group(0) if prefix_match else ""
    executable = argv[0][len(prefix):] if prefix else argv[0]
    if not executable:
        return []
    if "@" not in prefix:
        return [executable, *argv[1:]]
    # systemd's @ executable prefix consumes the next word as the overridden
    # argv[0]. It is not part of the called program's argument vector. The
    # prefix has no such meaning in cron's ordinary shell grammar.
    if len(argv) < 2:
        return []
    return [executable, *argv[2:]]


def command_segments(value):
    result = []
    start = 0
    index = 0
    quote = None
    end = len(value)
    while index < len(value):
        character = value[index]
        if quote == "'":
            if character == "'":
                quote = None
            index += 1
            continue
        if quote == '"':
            if character == "\\":
                index += 2
                continue
            if character == '"':
                quote = None
            index += 1
            continue
        if character == "\\":
            index += 2
            continue
        if character in {"'", '"'}:
            quote = character
            index += 1
            continue
        if quote is None and character == "#" and (
            index == 0
            or value[index - 1].isspace()
            or value[index - 1] in ";&|()"
        ):
            end = index
            break
        separator_length = 0
        if quote is None and character in {"(", ")"} and not (
            character == "(" and index > 0 and value[index - 1] == "$"
        ):
            separator_length = 1
        elif quote is None and character in {";", "\n"}:
            separator_length = 1
        elif quote is None and character in {"&", "|"}:
            if (
                (index > 0 and value[index - 1] in {">", "<"})
                or (
                    character == "&"
                    and index + 1 < len(value)
                    and value[index + 1] == ">"
                )
            ):
                index += 1
                continue
            separator_length = (
                2
                if index + 1 < len(value)
                and value[index + 1] in {character, "&"}
                else 1
            )
        if separator_length:
            segment = value[start:index].strip()
            if segment:
                result.append(tokens(segment))
            index += separator_length
            start = index
            continue
        index += 1
    segment = value[start:end].strip()
    if segment:
        result.append(tokens(segment))
    return result


def systemd_command_segments(value):
    # systemd supports multiple Exec*= commands only when a semicolon appears
    # as its own unquoted, unescaped word. Pipes, ampersands, substitutions,
    # and escaped/quoted semicolons are ordinary argv data, not shell syntax.
    result = []
    start = 0
    index = 0
    quote = None
    while index < len(value):
        character = value[index]
        if character == "\\":
            index += 2
            continue
        if quote is not None:
            if character == quote:
                quote = None
            index += 1
            continue
        if character in {"'", '"'}:
            quote = character
            index += 1
            continue
        if character == ";" and (
            index == 0 or value[index - 1].isspace()
        ) and (
            index + 1 == len(value) or value[index + 1].isspace()
        ):
            segment = value[start:index].strip()
            if segment:
                result.append(tokens(segment))
            start = index + 1
        index += 1
    segment = value[start:].strip()
    if segment:
        result.append(tokens(segment))
    return result


def shell_segment_plan(arguments):
    argv = []
    stdin_source = None
    raw = list(arguments)
    index = 0
    redirection = re.compile(
        r"^(?:(?P<descriptor>[0-9]+))?"
        r"(?P<operator><<<|<<|<>|>>|>|<)(?P<suffix>.*)$"
    )
    while index < len(raw):
        item = raw[index]
        # shlex separates the `&` in &> and descriptor duplication. Keep
        # shell redirections out of the executed argv without treating the
        # duplication ampersand as a command-list separator.
        if item == "&" and index + 1 < len(raw):
            following = redirection.fullmatch(raw[index + 1])
            if following and following.group("operator").startswith(">"):
                item = raw[index + 1]
                index += 1
            else:
                argv.append(item)
                index += 1
                continue
        match = redirection.fullmatch(item)
        if match:
            descriptor = match.group("descriptor")
            operator = match.group("operator")
            suffix = match.group("suffix")
            target = suffix
            descriptor_duplication = target.startswith("&")
            if descriptor_duplication:
                target = target[1:]
            index += 1
            if not suffix and index < len(raw):
                if raw[index] in {"&", "|"}:
                    descriptor_duplication = raw[index] == "&"
                    index += 1
                    if index < len(raw):
                        target = raw[index]
                        index += 1
                else:
                    target = raw[index]
                    index += 1
            effective_descriptor = (
                int(descriptor)
                if descriptor is not None
                else (0 if operator.startswith("<") else 1)
            )
            if effective_descriptor == 0 and operator.startswith("<"):
                if operator == "<<<":
                    stdin_source = (
                        ("here-string", target)
                        if target != ""
                        else ("here-string", "")
                    )
                elif operator == "<<":
                    # The body of a here-document is outside this bounded
                    # single-command tokenizer. A stdin-driven shell must not
                    # be admitted on an unknowable command source.
                    stdin_source = ("opaque", "here-document")
                elif descriptor_duplication:
                    stdin_source = (
                        ("closed", None)
                        if target == "-"
                        else ("opaque", "descriptor duplication")
                    )
                elif target:
                    stdin_source = ("file", target)
                else:
                    stdin_source = ("opaque", "missing redirection target")
            continue
        argv.append(item)
        index += 1
    while argv and argv[0] in SHELL_CONTROL_PREFIXES:
        argv.pop(0)
    return argv, stdin_source


def shell_segment_argv(arguments):
    return shell_segment_plan(arguments)[0]


def shell_invocation_plan(arguments, stdin_source):
    """Resolve whether a shell reads -c, a script, or its effective stdin."""
    index = 0
    noexec = False
    stdin_mode = False
    command = None
    terminal = False
    while index < len(arguments):
        item = arguments[index]
        if item == "--":
            index += 1
            break
        if item in {"--help", "--version"}:
            terminal = True
            break
        if item == "--noexec":
            noexec = True
            index += 1
            continue
        if item in {"-O", "+O", "-o", "+o", "--init-file", "--rcfile"}:
            if index + 1 >= len(arguments):
                terminal = True
                break
            option_value = arguments[index + 1]
            if item in {"-o", "+o"} and option_value == "noexec":
                noexec = item == "-o"
            index += 2
            continue
        if item.startswith(("-", "+")) and item not in {"-", "+"}:
            sign = item[0]
            cluster = item[1:]
            if not cluster.isalpha():
                # An unmodelled shell option can change how the remaining
                # argv is interpreted. Reject an stdin-driven invocation
                # later rather than guessing that it is harmless.
                return {
                    "kind": "opaque", "value": "unsupported shell option",
                    "noexec": noexec,
                }
            if "n" in cluster:
                noexec = sign == "-"
            if "s" in cluster:
                stdin_mode = sign == "-"
            if "c" in cluster:
                if index + 1 >= len(arguments):
                    terminal = True
                else:
                    command = arguments[index + 1]
                index = len(arguments)
                break
            index += 1
            continue
        break
    if noexec or terminal:
        return {"kind": "nonexecuting", "value": None, "noexec": noexec}
    if command is not None:
        return {"kind": "command", "value": command, "noexec": False}
    if not stdin_mode and index < len(arguments) and arguments[index] != "-":
        return {"kind": "script", "value": arguments[index], "noexec": False}
    if stdin_source is None or stdin_source[0] == "closed":
        return {"kind": "empty-stdin", "value": None, "noexec": False}
    return {"kind": stdin_source[0], "value": stdin_source[1], "noexec": False}


def env_command_argv(arguments):
    index = 0
    while index < len(arguments):
        item = arguments[index]
        if item == "--":
            index += 1
            break
        if item in {"-u", "--unset", "-C", "--chdir"}:
            if index + 1 >= len(arguments):
                return []
            index += 2
            continue
        split_value = None
        split_tail = []
        if item in {"-S", "--split-string"}:
            if index + 1 >= len(arguments):
                return []
            split_value = arguments[index + 1]
            split_tail = arguments[index + 2:]
        elif item.startswith("-S") and item != "-S":
            split_value = item[2:]
            split_tail = arguments[index + 1:]
        elif item.startswith("--split-string="):
            split_value = item.split("=", 1)[1]
            split_tail = arguments[index + 1:]
        if split_value is not None:
            try:
                split_arguments = shlex.split(
                    split_value, comments=False, posix=True
                )
            except ValueError:
                # GNU env rejects an unterminated split string before it can
                # execute a command. Treat that invocation as non-executing.
                return []
            return split_arguments + list(split_tail)
        if item.startswith("-") or re.fullmatch(
            r"[A-Za-z_][A-Za-z0-9_]*=.*", item
        ):
            index += 1
            continue
        break
    return list(arguments[index:])


def docker_all_value(argument):
    if argument == "--all":
        return True
    if argument.startswith("--all="):
        explicit = argument.split("=", 1)[1].strip().lower()
        if explicit in DOCKER_TRUE_VALUES:
            return True
        if explicit in DOCKER_FALSE_VALUES:
            return False
        return None
    if not argument.startswith("-") or argument.startswith("--"):
        return None
    shorthand = argument[1:]
    flags, separator, explicit = shorthand.partition("=")
    if "a" not in flags:
        return None
    # pflag evaluates a compact Boolean shorthand from left to right. An
    # explicit value belongs to the final shorthand; preceding `a` flags have
    # already taken their no-option default of true.
    if not separator or flags.index("a") < len(flags) - 1:
        return True
    explicit = explicit.strip().lower()
    if explicit in DOCKER_TRUE_VALUES:
        return True
    if explicit in DOCKER_FALSE_VALUES:
        return False
    return None


def docker_prune_kind(arguments):
    index = 0
    global_value_options = {
        "-H", "--config", "--context", "--host", "-l", "--log-level",
        "--tlscacert", "--tlscert", "--tlskey",
    }
    global_boolean_options = {"-D", "--debug", "--tls", "--tlsverify"}
    global_nonexecuting_options = {"-h", "--help", "-v", "--version"}
    while index < len(arguments):
        argument = arguments[index]
        if argument == "--":
            index += 1
            break
        if argument in global_nonexecuting_options:
            return None
        if argument in global_value_options:
            if index + 1 >= len(arguments):
                return None
            index += 2
            continue
        if any(argument.startswith(option + "=") for option in global_value_options):
            index += 1
            continue
        if (
            (argument.startswith("-H") and argument != "-H")
            or (argument.startswith("-l") and argument != "-l")
        ):
            index += 1
            continue
        if argument in global_boolean_options:
            index += 1
            continue
        if any(argument.startswith(option + "=") for option in global_boolean_options):
            explicit = argument.split("=", 1)[1].strip().lower()
            if explicit not in (DOCKER_TRUE_VALUES | DOCKER_FALSE_VALUES):
                return None
            index += 1
            continue
        if argument.startswith("-"):
            return None
        break
    if index + 1 >= len(arguments):
        return None
    kind = word(arguments[index])
    if kind not in {"image", "system"} or word(arguments[index + 1]) != "prune":
        return None
    index += 2
    all_enabled = False
    while index < len(arguments):
        argument = arguments[index]
        if argument == "--":
            if index + 1 < len(arguments):
                return None
            break
        if argument == "--filter":
            if index + 1 >= len(arguments):
                return None
            index += 2
            continue
        if argument.startswith("--filter="):
            index += 1
            continue
        if argument == "--all" or argument.startswith("--all="):
            all_value = docker_all_value(argument)
            if all_value is None:
                return None
            all_enabled = all_value
            index += 1
            continue
        if argument in {"--force", "-f"}:
            index += 1
            continue
        if argument.startswith("--force="):
            if argument.split("=", 1)[1].strip().lower() not in (
                DOCKER_TRUE_VALUES | DOCKER_FALSE_VALUES
            ):
                return None
            index += 1
            continue
        if kind == "system" and argument == "--volumes":
            index += 1
            continue
        if kind == "system" and argument.startswith("--volumes="):
            if argument.split("=", 1)[1].strip().lower() not in (
                DOCKER_TRUE_VALUES | DOCKER_FALSE_VALUES
            ):
                return None
            index += 1
            continue
        if argument.startswith("-") and not argument.startswith("--"):
            shorthand, separator, explicit = argument[1:].partition("=")
            if not shorthand or any(flag not in {"a", "f"} for flag in shorthand):
                return None
            if separator and explicit.strip().lower() not in (
                DOCKER_TRUE_VALUES | DOCKER_FALSE_VALUES
            ):
                return None
            if "a" in shorthand:
                all_value = docker_all_value(argument)
                if all_value is None:
                    return None
                all_enabled = all_value
            index += 1
            continue
        return None
    return kind if all_enabled else None


def shell_command_substitutions(value):
    """Return statically delimited substitutions that a shell will execute."""
    substitutions = []
    index = 0
    quote = None
    while index < len(value):
        character = value[index]
        if quote == "'":
            if character == "'":
                quote = None
            index += 1
            continue
        if character == "\\":
            if (
                quote == '"'
                and index + 1 < len(value)
                and value[index + 1] not in {'$', '`', '"', "\\", "\n"}
            ):
                index += 1
            else:
                index += 2
            continue
        if quote is None and character == "'":
            quote = "'"
            index += 1
            continue
        if character == '"':
            quote = None if quote == '"' else '"'
            index += 1
            continue
        if quote is None and character == "#" and (
            index == 0
            or value[index - 1].isspace()
            or value[index - 1] in ";&|()"
        ):
            break
        if character == "`":
            end = index + 1
            while end < len(value):
                if value[end] == "\\":
                    end += 2
                    continue
                if value[end] == "`":
                    substitutions.append(value[index + 1:end])
                    index = end + 1
                    break
                end += 1
            else:
                return substitutions
            continue
        if character == "$" and index + 1 < len(value) and value[index + 1] == "(":
            start = index + 2
            end = start
            depth = 1
            inner_quote = None
            while end < len(value):
                inner = value[end]
                if inner_quote == "'":
                    if inner == "'":
                        inner_quote = None
                    end += 1
                    continue
                if inner == "\\":
                    if (
                        inner_quote == '"'
                        and end + 1 < len(value)
                        and value[end + 1] not in {'$', '`', '"', "\\", "\n"}
                    ):
                        end += 1
                    else:
                        end += 2
                    continue
                if inner_quote is None and inner == "'":
                    inner_quote = "'"
                    end += 1
                    continue
                if inner == '"':
                    inner_quote = None if inner_quote == '"' else '"'
                    end += 1
                    continue
                if inner_quote is None and inner == "(":
                    depth += 1
                elif inner_quote is None and inner == ")":
                    depth -= 1
                    if depth == 0:
                        substitutions.append(value[start:end])
                        index = end + 1
                        break
                end += 1
            else:
                return substitutions
            continue
        index += 1
    return substitutions


def language_execution_command_records(value, kind):
    # These APIs execute one literal string through a command shell. Arbitrary
    # strings, assignments, logging calls, and dynamically constructed values
    # are intentionally not interpreted as executable commands. Scan the
    # complete bounded source rather than one physical line: each supported
    # language permits whitespace (including newlines) between the call,
    # opening parenthesis, and literal argument.
    call_names = {
        "python": (("os.system",), False, "#"),
        "perl": (("system", "exec"), True, "#"),
        "ruby": (("system", "exec"), True, "#"),
        "node": (("execSync", "exec"), False, "//"),
    }
    configuration = call_names.get(kind)
    if configuration is None:
        return []
    names, optional_parenthesis, comment = configuration
    commands = []
    index = 0
    quote = None
    while index < len(value):
        character = value[index]
        if quote is not None:
            if character == "\\":
                index += 2
                continue
            if character == quote:
                quote = None
            index += 1
            continue
        if character in ({"'", '"', "`"} if kind == "node" else {"'", '"'}):
            quote = character
            index += 1
            continue
        if value.startswith(comment, index):
            newline = value.find("\n", index + len(comment))
            if newline < 0:
                break
            index = newline + 1
            continue
        matched = next(
            (
                name for name in sorted(names, key=len, reverse=True)
                if value.startswith(name, index)
                and (index == 0 or not (value[index - 1].isalnum() or value[index - 1] == "_"))
                and (
                    index + len(name) == len(value)
                    or not (
                        value[index + len(name)].isalnum()
                        or value[index + len(name)] == "_"
                    )
                )
            ),
            None,
        )
        if matched is None:
            index += 1
            continue
        call_line = value.count("\n", 0, index) + 1
        cursor = index + len(matched)
        while cursor < len(value) and value[cursor].isspace():
            cursor += 1
        if cursor < len(value) and value[cursor] == "(":
            cursor += 1
            while cursor < len(value) and value[cursor].isspace():
                cursor += 1
        elif not optional_parenthesis:
            index += len(matched)
            continue
        argument_quotes = (
            {"'", '"', "`"} if kind == "node" else {"'", '"'}
        )
        if cursor >= len(value) or value[cursor] not in argument_quotes:
            index += len(matched)
            continue
        argument_quote = value[cursor]
        cursor += 1
        argument = []
        template_interpolation = False
        while cursor < len(value):
            if value[cursor] == "\\" and cursor + 1 < len(value):
                argument.extend(value[cursor:cursor + 2])
                cursor += 2
                continue
            if argument_quote == "`" and value.startswith("${", cursor):
                template_interpolation = True
            if value[cursor] == argument_quote:
                command = "".join(argument)
                lowered_command = command.lower()
                if (
                    template_interpolation
                    and "docker" in lowered_command
                    and "prune" in lowered_command
                ):
                    fail(
                        "scheduled Node execution template contains "
                        "interpolation and a Docker prune candidate that "
                        "cannot be inspected safely"
                    )
                if not template_interpolation:
                    commands.append((command, call_line))
                cursor += 1
                break
            argument.append(value[cursor])
            cursor += 1
        index = max(cursor, index + len(matched))
    return commands


def language_execution_commands(value, kind):
    return [
        command
        for command, _ in language_execution_command_records(value, kind)
    ]


def dangerous_argv(arguments, depth, stdin_source=None):
    if depth > WRAPPER_DEPTH_LIMIT:
        fail(
            f"scheduled command wrapper inspection exceeded depth "
            f"{WRAPPER_DEPTH_LIMIT}"
        )
    argv = list(arguments)
    while argv and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", argv[0]):
        argv.pop(0)
    if not argv:
        return None
    name = word(argv[0])
    rest = argv[1:]

    if name == "docker":
        return docker_prune_kind(rest)

    if name in BUILTIN_WRAPPERS:
        if name == "command" and any(item in {"-v", "-V"} for item in rest):
            return None
        index = 0
        while index < len(rest) and rest[index].startswith("-"):
            if rest[index] == "--":
                index += 1
                break
            if name == "exec" and rest[index] == "-a" and index + 1 < len(rest):
                index += 2
            else:
                index += 1
        return dangerous_argv(rest[index:], depth + 1, stdin_source)

    if name == "eval":
        return dangerous(" ".join(rest), shell_syntax=True, depth=depth + 1)

    if name == "env":
        return dangerous_argv(env_command_argv(rest), depth + 1, stdin_source)

    if name == "timeout":
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-k", "--kill-after", "-s", "--signal"}:
                index += 2
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        return (
            dangerous_argv(rest[index + 1:], depth + 1, stdin_source)
            if index < len(rest) else None
        )

    if name == "flock":
        for index, item in enumerate(rest):
            if item in {"-c", "--command"} and index + 1 < len(rest):
                return dangerous(rest[index + 1], shell_syntax=True, depth=depth + 1)
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-w", "--wait", "-E", "--conflict-exit-code"}:
                index += 2
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        return (
            dangerous_argv(rest[index + 1:], depth + 1, stdin_source)
            if index < len(rest) else None
        )

    if name == "nice":
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-n", "--adjustment"}:
                index += 2
                continue
            if re.fullmatch(r"-\d+", item) or item.startswith("--adjustment="):
                index += 1
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        return dangerous_argv(rest[index:], depth + 1, stdin_source)

    if name == "time":
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-f", "--format", "-o", "--output"}:
                index += 2
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        return dangerous_argv(rest[index:], depth + 1, stdin_source)

    if name == "nohup":
        return dangerous_argv(
            rest[1:] if rest[:1] == ["--"] else rest,
            depth + 1,
            stdin_source,
        )

    if name == "sudo":
        index = 0
        value_options = {
            "-C", "--close-from", "-D", "--chdir", "-g", "--group",
            "-h", "--host", "-p", "--prompt", "-R", "--chroot",
            "-T", "--command-timeout", "-u", "--user",
        }
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in value_options:
                index += 2
                continue
            if item.startswith("-") or re.fullmatch(
                r"[A-Za-z_][A-Za-z0-9_]*=.*", item
            ):
                index += 1
                continue
            break
        return dangerous_argv(rest[index:], depth + 1, stdin_source)

    kind = interpreter_kind(name)
    if kind == "shell":
        plan = shell_invocation_plan(rest, stdin_source)
        if plan["kind"] == "command":
            return dangerous(plan["value"], shell_syntax=True, depth=depth + 1)
        if plan["kind"] == "here-string":
            return dangerous(plan["value"], shell_syntax=True, depth=depth + 1)
        if plan["kind"] == "opaque":
            if plan["value"] == "here-document":
                # A containing shell helper supplies and inspects this body
                # with its literal delimiter below.
                return None
            fail(
                "scheduled stdin-driven shell uses a command source that "
                f"cannot be inspected safely ({plan['value']})"
            )
        return None
    if kind in {"python", "perl", "ruby", "node"}:
        plan = interpreter_invocation(kind, rest)
        for source in plan["inline"]:
            for command in language_execution_commands(source, kind):
                finding = dangerous(command, shell_syntax=True, depth=depth + 1)
                if finding:
                    return finding
        return None
    return None


def dangerous(value, *, shell_syntax=False, systemd_syntax=False, depth=0):
    parts = tokens(value) if isinstance(value, str) else list(value)
    if isinstance(value, str) and shell_syntax:
        segments = command_segments(value)
    elif isinstance(value, str) and systemd_syntax:
        segments = systemd_command_segments(value)
    else:
        segments = [parts]
    for segment in segments:
        stdin_source = None
        if shell_syntax:
            segment, stdin_source = shell_segment_plan(segment)
        elif systemd_syntax:
            segment = systemd_effective_argv(segment)
        finding = dangerous_argv(segment, depth, stdin_source)
        if finding:
            return finding
    if shell_syntax and isinstance(value, str):
        for substitution in shell_command_substitutions(value):
            finding = dangerous(
                substitution, shell_syntax=True, depth=depth + 1
            )
            if finding:
                return finding
    return None


def cron_commands(payload, kind):
    text = payload.decode("utf-8", errors="replace").replace("\\\n", " ")
    for number, raw in enumerate(text.splitlines(), 1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if kind == "run-parts":
            yield number, raw
            continue
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*\s*=", stripped):
            continue
        if kind == "anacron":
            fields = stripped.split(None, 3)
            if len(fields) == 4:
                yield number, fields[3]
            continue
        if kind == "root-spool":
            if stripped.startswith("@"):
                fields = stripped.split(None, 1)
                if len(fields) == 2:
                    yield number, fields[1]
            else:
                fields = stripped.split(None, 5)
                if len(fields) == 6:
                    yield number, fields[5]
            continue
        if stripped.startswith("@"):
            fields = stripped.split(None, 2)
            if len(fields) == 3 and fields[1] == "root":
                yield number, fields[2]
        else:
            fields = stripped.split(None, 6)
            if len(fields) == 7 and fields[5] == "root":
                yield number, fields[6]


def systemd_service_directives(payload):
    text = payload.decode("utf-8", errors="replace").replace("\\\n", " ")
    section = None
    for number, raw in enumerate(text.splitlines(), 1):
        stripped = raw.strip()
        if not stripped or stripped.startswith(("#", ";")):
            continue
        if stripped.startswith("[") and stripped.endswith("]"):
            section = stripped[1:-1].strip()
            continue
        if section != "Service" or "=" not in stripped:
            continue
        key, command = stripped.split("=", 1)
        yield number, key.strip(), command


def systemd_directives(payload):
    for number, key, command in systemd_service_directives(payload):
        if key in EXEC_KEYS:
            yield number, key, command


def systemd_unescaped_reference(value):
    simple = {
        "a": "\a", "b": "\b", "f": "\f", "n": "\n", "r": "\r",
        "s": " ", "t": "\t", "v": "\v", "\\": "\\", '"': '"', "'": "'",
    }
    result = []
    index = 0
    while index < len(value):
        if value[index] != "\\" or index + 1 >= len(value):
            result.append(value[index])
            index += 1
            continue
        marker = value[index + 1]
        if marker in simple:
            result.append(simple[marker])
            index += 2
            continue
        widths = {"x": 2, "u": 4, "U": 8}
        width = widths.get(marker)
        if width is not None:
            encoded = value[index + 2:index + 2 + width]
            if len(encoded) == width and re.fullmatch(r"[0-9A-Fa-f]+", encoded):
                try:
                    result.append(chr(int(encoded, 16)))
                    index += 2 + width
                    continue
                except ValueError:
                    pass
        octal = re.match(r"[0-7]{1,3}", value[index + 1:])
        if octal is not None:
            result.append(chr(int(octal.group(0), 8)))
            index += 1 + len(octal.group(0))
            continue
        result.extend(("\\", marker))
        index += 2
    return "".join(result)


def secure_cron_file(path, *, allow_missing, periodic, allow_crontab_spool):
    resolved, masked = resolve_secure_path(
        path,
        allow_missing=allow_missing,
        allow_mask=False,
        final_kind="file",
        require_root_group=False,
        require_owner_readable=True,
        allow_standard_crontab_spool=allow_crontab_spool,
    )
    if masked or resolved is None:
        return None
    metadata = lstat_or_none(resolved)
    if metadata is None:
        fail(f"cron scheduler target {display(resolved)} disappeared")
    if periodic and not stat.S_IMODE(metadata.st_mode) & 0o111:
        return None
    return resolved


def bounded_directory_entries(directory, entry_budget, context):
    entries = []
    try:
        with os.scandir(directory) as iterator:
            for entry in iterator:
                entry_budget[0] += 1
                if entry_budget[0] > SCHEDULER_ENTRY_LIMIT:
                    fail(
                        f"scheduler inspection exceeded its "
                        f"{SCHEDULER_ENTRY_LIMIT}-entry aggregate budget"
                    )
                entries.append(entry)
    except OSError as exc:
        fail(f"could not enumerate {context} {display(directory)}: {exc}")
    entries.sort(key=lambda entry: entry.name)
    return entries


def is_unit_name_activation_link(relative, path, metadata):
    parts = relative.split(os.sep)
    if (
        len(parts) != 2
        or not parts[0].endswith((".wants", ".requires"))
        or os.path.splitext(parts[1])[1] not in UNIT_SUFFIXES
        or not stat.S_ISLNK(metadata.st_mode)
    ):
        return False
    if metadata.st_uid != 0 or metadata.st_gid != 0:
        fail(f"scheduled path link {display(path)} is not owned by root:root")
    try:
        target = os.readlink(path)
    except OSError as exc:
        fail(f"could not read scheduled path link {display(path)}: {exc}")
    current = lstat_or_none(path)
    if current is None:
        fail(f"systemd scheduler entry {display(path)} disappeared")
    before_identity = (
        metadata.st_dev, metadata.st_ino, metadata.st_mode,
        metadata.st_uid, metadata.st_gid, metadata.st_nlink,
        metadata.st_size, metadata.st_mtime_ns, metadata.st_ctime_ns,
    )
    current_identity = (
        current.st_dev, current.st_ino, current.st_mode,
        current.st_uid, current.st_gid, current.st_nlink,
        current.st_size, current.st_mtime_ns, current.st_ctime_ns,
    )
    if current_identity != before_identity:
        fail(f"systemd scheduler entry {display(path)} changed during inspection")
    # systemd permits .wants/.requires dependency links to name a unit in the
    # global load path even when the relative filesystem target is dangling.
    # Defer only the canonical same-name form; a concrete definition elsewhere
    # in the load path must still win, and a missing definition remains fatal.
    return target == f"../{parts[1]}"


def is_systemd_loadable_directory(relative):
    parts = relative.split(os.sep)
    return len(parts) == 1 and parts[0].endswith(
        (".d", ".wants", ".requires")
    )


def is_systemd_loadable_leaf(relative):
    parts = relative.split(os.sep)
    basename = parts[-1]
    suffix = os.path.splitext(basename)[1]
    if len(parts) == 1:
        return suffix in UNIT_SUFFIXES
    if len(parts) != 2:
        return False
    if parts[0].endswith((".wants", ".requires")):
        return suffix in UNIT_SUFFIXES
    return parts[0].endswith(".d") and basename.endswith(".conf")


def secure_cron_directory(logical, kind, entry_budget, seen_directories=None):
    lexical_root = host_path(logical)
    resolved_root, masked = resolve_secure_path(
        lexical_root,
        allow_missing=True,
        allow_mask=False,
        final_kind="directory",
    )
    if masked or resolved_root is None:
        return
    root_metadata = lstat_or_none(resolved_root)
    if root_metadata is None:
        fail(f"cron scheduler root {display(resolved_root)} disappeared")
    root_identity = (root_metadata.st_dev, root_metadata.st_ino)
    if seen_directories is not None:
        if root_identity in seen_directories:
            return
        seen_directories.add(root_identity)
    entries = bounded_directory_entries(
        resolved_root, entry_budget, "cron scheduler root"
    )
    for entry in entries:
        lexical = os.path.join(lexical_root, entry.name)
        resolved, entry_masked = resolve_secure_path(
            lexical,
            allow_missing=False,
            allow_mask=False,
            final_kind="either",
            require_root_group=False,
            require_owner_readable=True,
        )
        if entry_masked or resolved is None:
            continue
        metadata = lstat_or_none(resolved)
        if metadata is None:
            fail(f"cron scheduler entry {display(resolved)} disappeared")
        if stat.S_ISDIR(metadata.st_mode):
            # cron.d and run-parts do not recurse into subdirectories. The
            # directory was still securely resolved and attested above.
            continue
        if kind == "run-parts" and not stat.S_IMODE(metadata.st_mode) & 0o111:
            continue
        yield lexical, kind, resolved


def collect_systemd_root(logical, resolved_root, entry_budget):
    records = []
    pending = [(resolved_root, "")]
    visited = set()
    while pending:
        directory, relative_prefix = pending.pop()
        metadata = lstat_or_none(directory)
        if metadata is None:
            fail(f"systemd scheduler directory {display(directory)} disappeared")
        require_secure_directory(directory, metadata, "systemd scheduler")
        visit_key = (metadata.st_dev, metadata.st_ino, relative_prefix)
        if visit_key in visited:
            continue
        visited.add(visit_key)
        entries = bounded_directory_entries(
            directory, entry_budget, "systemd scheduler directory"
        )
        for entry in entries:
            path = entry.path
            relative = os.path.join(relative_prefix, entry.name) if relative_prefix else entry.name
            try:
                entry_metadata = os.lstat(path)
            except OSError as exc:
                fail(f"could not inspect systemd scheduler entry {display(path)}: {exc}")
            if stat.S_ISDIR(entry_metadata.st_mode):
                if not is_systemd_loadable_directory(relative):
                    continue
                require_secure_directory(path, entry_metadata, "systemd scheduler")
                pending.append((path, relative))
                continue
            if not (
                is_systemd_loadable_leaf(relative)
                or is_systemd_loadable_directory(relative)
            ):
                # systemd ignores backups, editor temporaries, and arbitrary
                # nested files in a unit load path. Do not attest content that
                # the scheduler itself cannot load.
                continue
            if is_unit_name_activation_link(relative, path, entry_metadata):
                records.append((relative, path, None, False))
                continue
            resolved, entry_masked = resolve_secure_path(
                path,
                allow_missing=False,
                allow_mask=True,
                final_kind="either",
            )
            if entry_masked:
                records.append((relative, path, None, True))
                continue
            if resolved is None:
                fail(f"systemd scheduler entry {display(path)} disappeared")
            resolved_metadata = lstat_or_none(resolved)
            if resolved_metadata is None:
                fail(f"systemd scheduler target {display(resolved)} disappeared")
            if stat.S_ISDIR(resolved_metadata.st_mode):
                if not is_systemd_loadable_directory(relative):
                    continue
                pending.append((resolved, relative))
                continue
            records.append((relative, path, resolved, False))
    return records


def systemd_dropin_owners(unit_name):
    stem, suffix = os.path.splitext(unit_name)
    owners = [unit_name]
    if "@" in stem:
        owners.append(stem.split("@", 1)[0] + "@" + suffix)
    prefix = stem
    while "-" in prefix:
        prefix = prefix.rsplit("-", 1)[0]
        owners.append(prefix + "-" + suffix)
    owners.append(suffix.lstrip("."))
    return list(dict.fromkeys(owners))


def locally_managed_scheduler_path(path):
    return path.startswith(("/etc/", "/run/", "/root/", "/usr/local/"))


def effective_systemd_definitions(logical_roots, entry_budget):
    selected_main = {}
    activation_fallback = {}
    selected_dropins = {}
    seen_roots = set()
    for logical in logical_roots:
        lexical_root = host_path(logical)
        resolved_root, masked = resolve_secure_path(
            lexical_root,
            allow_missing=True,
            allow_mask=True,
            final_kind="directory",
        )
        if masked:
            fail(f"systemd scheduler root {logical} cannot be masked")
        if resolved_root is None:
            continue
        root_metadata = lstat_or_none(resolved_root)
        if root_metadata is None:
            fail(f"systemd scheduler root {logical} disappeared")
        root_identity = (root_metadata.st_dev, root_metadata.st_ino)
        if root_identity in seen_roots:
            continue
        seen_roots.add(root_identity)
        for relative, definition, target, entry_masked in collect_systemd_root(
            logical, resolved_root, entry_budget
        ):
            parts = relative.split(os.sep)
            basename = parts[-1]
            suffix = os.path.splitext(basename)[1]
            if len(parts) == 1 and suffix in UNIT_SUFFIXES:
                selected_main.setdefault(
                    basename, (definition, target, entry_masked)
                )
                continue
            if (
                len(parts) == 2
                and parts[0].endswith((".wants", ".requires"))
                and suffix in UNIT_SUFFIXES
            ):
                activation_fallback.setdefault(
                    basename, (definition, target, entry_masked)
                )
                continue
            if (
                len(parts) == 2
                and parts[0].endswith(".d")
                and basename.endswith(".conf")
            ):
                owner = parts[0][:-2]
                selected_dropins.setdefault(
                    (owner, basename), (definition, target, entry_masked)
                )

    for unit_name, fallback in activation_fallback.items():
        selected_main.setdefault(unit_name, fallback)

    def definition_priority(item):
        unit_name, (definition, _, _) = item
        origin = display(definition)
        locally_managed = locally_managed_scheduler_path(origin)
        return (0 if locally_managed else 1, unit_name)

    # Inspect administrator/runtime definitions before vendor definitions so
    # ordinary distro units cannot consume generic helper work ahead of the
    # scheduler surface most likely to contain local policy.
    for unit_name, selected_record in sorted(
        selected_main.items(), key=definition_priority
    ):
        definition, target, masked = selected_record
        if masked:
            continue
        if target is None:
            fail(f"effective systemd definition {display(definition)} has no target")
        definitions = [(definition, target)]
        owner_rank = {
            owner: rank
            for rank, owner in enumerate(systemd_dropin_owners(unit_name))
        }
        effective_dropins = {}
        for (owner, basename), record in selected_dropins.items():
            if owner not in owner_rank:
                continue
            previous = effective_dropins.get(basename)
            if previous is None or owner_rank[owner] < previous[0]:
                effective_dropins[basename] = (owner_rank[owner], record)
        for basename in sorted(effective_dropins):
            _, (dropin, dropin_target, dropin_masked) = effective_dropins[basename]
            if dropin_masked:
                continue
            if dropin_target is None:
                fail(f"effective systemd drop-in {display(dropin)} has no target")
            definitions.append((dropin, dropin_target))
        yield unit_name, definitions


def jobs(scheduler_entry_budget, scheduler_directories):
    for logical, kind in (
        ("/etc/crontab", "system-cron"),
        ("/etc/anacrontab", "anacron"),
        ("/var/spool/cron/crontabs/root", "root-spool"),
        ("/var/spool/cron/root", "root-spool"),
    ):
        lexical = host_path(logical)
        target = secure_cron_file(
            lexical,
            allow_missing=True,
            periodic=False,
            allow_crontab_spool=kind == "root-spool",
        )
        if target is not None:
            yield lexical, kind, target
    for logical, kind in (
        ("/etc/cron.d", "system-cron"),
        ("/etc/cron.hourly", "run-parts"),
        ("/etc/cron.daily", "run-parts"),
        ("/etc/cron.weekly", "run-parts"),
        ("/etc/cron.monthly", "run-parts"),
        ("/etc/cron.yearly", "run-parts"),
    ):
        yield from secure_cron_directory(
            logical, kind, scheduler_entry_budget, scheduler_directories
        )

    system_roots = (
        "/etc/systemd/system.control",
        "/run/systemd/system.control",
        "/run/systemd/transient",
        "/run/systemd/generator.early",
        "/etc/systemd/system",
        "/etc/systemd/system.attached",
        "/run/systemd/system",
        "/run/systemd/system.attached",
        "/run/systemd/generator",
        "/usr/local/lib/systemd/system",
        "/usr/lib/systemd/system",
        "/lib/systemd/system",
        "/run/systemd/generator.late",
    )
    root_user_roots = (
        "/root/.config/systemd/user.control",
        "/run/user/0/systemd/user.control",
        "/run/user/0/systemd/transient",
        "/run/user/0/systemd/generator.early",
        "/root/.config/systemd/user",
        "/etc/xdg/systemd/user",
        "/etc/systemd/user",
        "/run/user/0/systemd/user",
        "/run/systemd/user",
        "/root/.local/share/systemd/user",
        "/usr/local/share/systemd/user",
        "/usr/share/systemd/user",
        "/usr/local/lib/systemd/user",
        "/usr/lib/systemd/user",
        "/run/user/0/systemd/generator",
        "/run/user/0/systemd/generator.late",
    )
    for roots in (system_roots, root_user_roots):
        for unit_name, definitions in effective_systemd_definitions(
            roots, scheduler_entry_budget
        ):
            yield unit_name, "systemd", definitions


def is_audited_portal_backup_helper(logical_path, path, metadata):
    expected_path = "/opt/bridgesllm/portal/backup-full.sh"
    if (
        os.path.normpath(logical_path) != expected_path
        or display(path) != expected_path
    ):
        return False
    if metadata.st_size > PORTAL_AUDITED_HELPER_LIMIT:
        fail(
            "scheduled Portal backup helper exceeds its 512 KiB audited "
            "release limit"
        )
    if metadata.st_size not in {
        release_size for release_size, _ in PORTAL_BACKUP_HELPER_RELEASES
    }:
        fail(
            "scheduled Portal backup helper does not match a known shipped "
            "BridgesLLM release; restore it through a signed update before "
            "retrying"
        )
    payload, current = read_root_file(
        path,
        single_link=True,
        require_root_group=True,
    )
    expected_identity = (
        metadata.st_dev, metadata.st_ino, metadata.st_mode,
        metadata.st_uid, metadata.st_gid, metadata.st_nlink,
        metadata.st_size, metadata.st_mtime_ns, metadata.st_ctime_ns,
    )
    current_identity = (
        current.st_dev, current.st_ino, current.st_mode,
        current.st_uid, current.st_gid, current.st_nlink,
        current.st_size, current.st_mtime_ns, current.st_ctime_ns,
    )
    if current_identity != expected_identity:
        fail(
            "scheduled Portal backup helper changed before release "
            "attestation"
        )
    digest = hashlib.sha256(payload).hexdigest()
    if (
        os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
        and root != "/"
        and os.environ.get("BRIDGESLLM_DOCKER_PRUNE_TEST_HOOK", "")
        == "portal-helper-post-read-replacement"
    ):
        replacement = path + ".test-replacement"
        displaced = path + ".test-old"
        if os.path.lexists(displaced) or not os.path.isfile(replacement):
            fail("Portal helper replacement fixture is incomplete")
        os.rename(path, displaced)
        os.rename(replacement, path)
    final = lstat_or_none(path)
    if final is None:
        fail("scheduled Portal backup helper disappeared after attestation")
    final_identity = (
        final.st_dev, final.st_ino, final.st_mode,
        final.st_uid, final.st_gid, final.st_nlink,
        final.st_size, final.st_mtime_ns, final.st_ctime_ns,
    )
    if final_identity != expected_identity:
        fail(
            "scheduled Portal backup helper changed during release "
            "attestation"
        )
    if (metadata.st_size, digest) not in PORTAL_BACKUP_HELPER_RELEASES:
        fail(
            "scheduled Portal backup helper does not match a known shipped "
            "BridgesLLM release; restore it through a signed update before "
            "retrying"
        )
    return True


def is_audited_portal_runtime_repair_launcher(logical_path, path, metadata):
    if (
        os.path.normpath(logical_path) != PORTAL_RUNTIME_REPAIR_LAUNCHER
        or display(path) != PORTAL_RUNTIME_REPAIR_LAUNCHER
    ):
        return False
    strict_path, strict_masked = resolve_secure_path(
        host_path(PORTAL_RUNTIME_REPAIR_LAUNCHER),
        allow_missing=False,
        allow_mask=False,
        final_kind="file",
        require_root_group=True,
        require_root_group_directories=True,
    )
    if strict_masked or strict_path != path:
        fail("scheduled Project runtime repair launcher path is unsafe")
    if metadata.st_size not in {
        release_size
        for release_size, _ in PORTAL_RUNTIME_REPAIR_LAUNCHER_RELEASES
    }:
        fail(
            "scheduled Project runtime repair launcher does not match a "
            "known shipped BridgesLLM release"
        )
    payload, current = read_root_file(
        path,
        modes={0o600, 0o644},
        single_link=True,
        require_root_group=True,
    )
    expected_identity = (
        metadata.st_dev, metadata.st_ino, metadata.st_mode,
        metadata.st_uid, metadata.st_gid, metadata.st_nlink,
        metadata.st_size, metadata.st_mtime_ns, metadata.st_ctime_ns,
    )
    current_identity = (
        current.st_dev, current.st_ino, current.st_mode,
        current.st_uid, current.st_gid, current.st_nlink,
        current.st_size, current.st_mtime_ns, current.st_ctime_ns,
    )
    if current_identity != expected_identity:
        fail("scheduled Project runtime repair launcher changed before attestation")
    digest = hashlib.sha256(payload).hexdigest()
    final = lstat_or_none(path)
    if final is None:
        fail("scheduled Project runtime repair launcher disappeared after attestation")
    final_identity = (
        final.st_dev, final.st_ino, final.st_mode,
        final.st_uid, final.st_gid, final.st_nlink,
        final.st_size, final.st_mtime_ns, final.st_ctime_ns,
    )
    if final_identity != expected_identity:
        fail("scheduled Project runtime repair launcher changed during attestation")
    if (metadata.st_size, digest) not in PORTAL_RUNTIME_REPAIR_LAUNCHER_RELEASES:
        fail(
            "scheduled Project runtime repair launcher does not match a "
            "known shipped BridgesLLM release"
        )
    return True


class HelperBudget:
    def __init__(self, scheduler_entries, scheduler_directories):
        self.files = 0
        self.bytes = 0
        self.lines = 0
        self.candidate_files = 0
        self.candidate_bytes = 0
        self.candidate_lines = 0
        self.inspected = set()
        self.warnings = set()
        self.scheduler_entries = scheduler_entries
        self.scheduler_directories = scheduler_directories

    def warn_skip(self, key, message):
        if key not in self.warnings:
            print(f"Unsafe Docker prune guard warning: {message}", file=sys.stderr)
            self.warnings.add(key)

    def admit(self, logical_path, path, metadata, candidate=False):
        identity = (metadata.st_dev, metadata.st_ino)
        is_runtime_repair_launcher = (
            os.path.normpath(logical_path) == PORTAL_RUNTIME_REPAIR_LAUNCHER
        )
        if is_runtime_repair_launcher:
            is_audited_portal_runtime_repair_launcher(
                logical_path, path, metadata
            )
        if identity in self.inspected:
            return False
        if (
            metadata.st_size > HELPER_FILE_LIMIT
            and is_audited_portal_backup_helper(
                logical_path, path, metadata
            )
        ):
            # This exact release helper is always attested, even after generic
            # helper work has reached a soft ceiling. Its exact bytes are
            # reviewed and shipped by BridgesLLM, so no line parsing follows.
            self.inspected.add(identity)
            self.files += 1
            self.bytes += metadata.st_size
            return False
        if metadata.st_size > HELPER_FILE_LIMIT:
            fail(f"scheduled helper {display(path)} exceeds 128 KiB")
        generic_exhausted = (
            self.files + 1 > HELPER_FILE_COUNT_LIMIT
            or self.bytes + metadata.st_size > HELPER_TOTAL_LIMIT
        )
        if candidate and generic_exhausted:
            if self.files + 1 > HELPER_FILE_COUNT_LIMIT:
                self.warn_skip(
                    "files",
                    "scheduled helper inspection reached its 96-file work "
                    "budget; prioritized helper candidates continue in the "
                    "bounded reserve",
                )
            else:
                self.warn_skip(
                    "bytes",
                    "scheduled helper inspection reached its 1 MiB aggregate "
                    "budget; prioritized helper candidates continue in the "
                    "bounded reserve",
                )
            if self.candidate_files + 1 > HELPER_CANDIDATE_FILE_LIMIT:
                fail(
                    "scheduled helper candidate inspection exceeded its "
                    "256-file reserve"
                )
            if (
                self.candidate_bytes + metadata.st_size
                > HELPER_CANDIDATE_TOTAL_LIMIT
            ):
                fail(
                    "scheduled helper candidate inspection exceeded its "
                    "4 MiB reserve"
                )
            self.inspected.add(identity)
            self.candidate_files += 1
            self.candidate_bytes += metadata.st_size
            return True
        if self.files + 1 > HELPER_FILE_COUNT_LIMIT:
            self.warn_skip(
                "files",
                "scheduled helper inspection reached its 96-file work budget; "
                "remaining helper bodies are skipped while literal scheduler "
                "commands remain inspected",
            )
            return False
        if self.bytes + metadata.st_size > HELPER_TOTAL_LIMIT:
            self.warn_skip(
                "bytes",
                "scheduled helper inspection reached its 1 MiB aggregate "
                "budget; remaining helper bodies are skipped while literal "
                "scheduler commands remain inspected",
            )
            return False
        if is_runtime_repair_launcher:
            self.inspected.add(identity)
            self.files += 1
            self.bytes += metadata.st_size
            return False
        self.inspected.add(identity)
        self.files += 1
        self.bytes += metadata.st_size
        return True

    def admit_line(self, candidate=False):
        if self.lines >= HELPER_LINE_LIMIT:
            if candidate:
                self.warn_skip(
                    "lines",
                    "scheduled helper inspection reached its 16384-line work "
                    "budget; prioritized helper candidates continue in the "
                    "bounded reserve",
                )
                self.candidate_lines += 1
                if self.candidate_lines > HELPER_CANDIDATE_LINE_LIMIT:
                    fail(
                        "scheduled helper candidate inspection exceeded its "
                        "65536-line reserve"
                    )
                return True
            self.warn_skip(
                "lines",
                "scheduled helper inspection reached its 16384-line work "
                "budget; remaining helper bodies are skipped while literal "
                "scheduler commands remain inspected",
            )
            return False
        self.lines += 1
        return True


def absolute_token(value):
    cleaned = value.strip("$(){}[]<>,\"'")
    return cleaned if cleaned.startswith("/") else None


def helper_prune_candidate(payload):
    # This is only a priority signal, never a finding: false positives spend a
    # small reserve and are parsed normally. Keeping the scan byte-oriented
    # also surfaces ASCII shell commands inside otherwise non-UTF-8 scripts.
    lowered = payload.lower()
    return b"docker" in lowered and b"prune" in lowered


def shell_text(payload):
    try:
        text = payload.decode("utf-8")
    except UnicodeDecodeError:
        text = "".join(
            chr(value) if value in {9, 10, 13} or 32 <= value <= 126 else " "
            for value in payload
        )
    return "".join(
        character if character in "\t\r\n" or character.isprintable() else " "
        for character in text
    )


def interpreter_kind(name):
    if name in SHELL_NAMES:
        return "shell"
    if re.fullmatch(r"python(?:\d+(?:\.\d+)*)?", name):
        return "python"
    if name in PERL_NAMES:
        return "perl"
    if name in RUBY_NAMES:
        return "ruby"
    if name in NODE_NAMES:
        return "node"
    return None


def interpreter_inline_argument(kind, arguments, index):
    argument = arguments[index]
    following = arguments[index + 1] if index + 1 < len(arguments) else None
    match = None
    if kind == "python":
        # Python permits no-value short switches to be clustered before -c,
        # including the common `-BcCODE` form.
        match = re.fullmatch(r"-[bBdEiIOPqRsSuvx]*c(.*)", argument)
    elif kind == "perl":
        # Perl accepts attached -e/-E code and clusters such as -weCODE.
        # Its -0 and -l switches can also carry an attached octal value before
        # a later execution switch (for example `-0777eCODE`). Parse that
        # cluster deterministically: a nested-regex spelling permits
        # catastrophic backtracking on a long, safe nonmatch.
        if argument.startswith("-") and not argument.startswith("--"):
            body = argument[1:]
            cursor = 0
            simple = set("wWTtnpsSUdD")
            while cursor < len(body):
                option = body[cursor]
                if option in {"e", "E"}:
                    source = body[cursor + 1:]
                    if source:
                        return source, 1
                    return (following, 2) if following is not None else (None, 1)
                if option in simple:
                    cursor += 1
                    continue
                if option == "0":
                    cursor += 1
                    octal_digits = 0
                    while (
                        cursor < len(body)
                        and octal_digits < 3
                        and body[cursor] in "01234567"
                    ):
                        cursor += 1
                        octal_digits += 1
                    continue
                if option == "l":
                    cursor += 1
                    octal_digits = 0
                    while (
                        cursor < len(body)
                        and octal_digits < 4
                        and body[cursor] in "01234567"
                    ):
                        cursor += 1
                        octal_digits += 1
                    continue
                break
        return None
    elif kind == "ruby":
        # Ruby accepts attached -e code and no-value clusters such as -weCODE.
        match = re.fullmatch(r"-[wWvdlnpsa]*e(.*)", argument)
    elif kind == "node":
        if argument.startswith("--eval="):
            return argument.split("=", 1)[1], 1
        if argument in {"-e", "-p", "--eval", "--print"}:
            return (following, 2) if following is not None else (None, 1)
        if re.fullmatch(r"-[ep].+", argument):
            # Shipped Node rejects attached short-form source (`-eCODE` and
            # `-pCODE`) before it can execute a main script.
            return None, 1
    if match is None:
        return None
    attached = match.group(1)
    if attached:
        return attached, 1
    return (following, 2) if following is not None else (None, 1)


def interpreter_invocation(kind, arguments):
    inline = []
    preloads = []
    node_print_mode = False
    index = 0
    while index < len(arguments):
        argument = arguments[index]
        if argument == "--":
            index += 1
            break
        if kind == "node" and argument.startswith("--print="):
            # Node treats the equals suffix as an ignored value for the print
            # switch. The first later non-option is the expression, if any;
            # with no such argument this invocation prints `undefined` and
            # does not execute the suffix.
            node_print_mode = True
            index += 1
            continue
        if kind == "node" and (
            re.fullmatch(r"-r.+", argument)
            or (
                argument.startswith("--require")
                and argument != "--require"
                and not argument.startswith("--require=")
            )
            or (
                argument.startswith("--import")
                and argument != "--import"
                and not argument.startswith("--import=")
            )
        ):
            # These attached spellings are rejected by shipped Node before a
            # main script can run. Only -r VALUE, --require[=]VALUE, and
            # --import[=]VALUE are executable preload contracts.
            return {
                "inline": inline, "preloads": preloads,
                "script": None, "terminal": True,
            }
        parsed_inline = interpreter_inline_argument(kind, arguments, index)
        if parsed_inline is not None:
            source, consumed = parsed_inline
            if source is None:
                return {
                    "inline": inline, "preloads": preloads,
                    "script": None, "terminal": True,
                }
            inline.append(source)
            index += consumed
            if kind in {"python", "node"}:
                return {
                    "inline": inline, "preloads": preloads,
                    "script": None, "terminal": True,
                }
            continue
        if kind == "python" and (
            argument == "-m" or (argument.startswith("-m") and argument != "-m")
        ):
            return {
                "inline": inline, "preloads": preloads,
                "script": None, "terminal": True,
            }
        if argument.startswith("-"):
            preload_value = None
            preload_consumed = 1
            if kind in {"node", "ruby"}:
                preload_options = (
                    {"-r", "--require", "--import"}
                    if kind == "node" else {"-r", "--require"}
                )
                if argument in preload_options:
                    if index + 1 >= len(arguments):
                        return {
                            "inline": inline, "preloads": preloads,
                            "script": None, "terminal": True,
                        }
                    preload_value = arguments[index + 1]
                    preload_consumed = 2
                elif (
                    argument.startswith("--require=")
                    or (kind == "node" and argument.startswith("--import="))
                ):
                    preload_value = argument.split("=", 1)[1]
                elif (
                    kind == "ruby"
                    and argument.startswith("-r")
                    and argument != "-r"
                ):
                    preload_value = argument[2:]
            if preload_value is not None:
                preload = absolute_token(preload_value)
                if preload is not None:
                    preloads.append(preload)
                index += preload_consumed
                continue
            value_options = {
                "python": {"-W", "-X", "--check-hash-based-pycs"},
                "perl": {"-I", "-M", "-m"},
                "ruby": {"-I", "-r"},
                "node": {"-r", "--require", "--import"},
            }.get(kind, set())
            if argument in value_options:
                if index + 1 >= len(arguments):
                    return {
                        "inline": inline, "preloads": preloads,
                        "script": None, "terminal": True,
                    }
                index += 2
                continue
            if any(
                argument.startswith(option + "=")
                for option in value_options
                if option.startswith("--")
            ):
                index += 1
                continue
            if any(
                argument.startswith(option) and argument != option
                for option in value_options
                if option.startswith("-") and not option.startswith("--")
            ):
                index += 1
                continue
            index += 1
            continue
        break
    if kind == "node" and node_print_mode:
        if index < len(arguments):
            inline.append(arguments[index])
        return {
            "inline": inline,
            "preloads": preloads,
            "script": None,
            "terminal": True,
        }
    script = absolute_token(arguments[index]) if index < len(arguments) else None
    return {
        "inline": inline,
        "preloads": preloads,
        "script": script,
        "terminal": bool(inline),
    }


def recurse_argv(arguments, depth, direct_invocation, stdin_source=None):
    if depth > WRAPPER_DEPTH_LIMIT:
        fail(
            f"scheduled command wrapper inspection exceeded depth "
            f"{WRAPPER_DEPTH_LIMIT}"
        )
    return helper_candidates_from_argv(
        arguments, depth, direct_invocation, stdin_source
    )


def interpreter_candidates(
    kind, arguments, depth, direct_invocation, stdin_source=None
):
    if kind == "shell":
        plan = shell_invocation_plan(arguments, stdin_source)
        if plan["kind"] in {"command", "here-string"}:
            return helper_candidates(
                plan["value"], depth + 1, "shell-fallback"
            )
        if plan["kind"] == "script":
            script = absolute_token(plan["value"])
            if script is None:
                fail(
                    "scheduled shell script path is not a literal absolute path"
                )
            return [(script, "interpreter:shell")]
        if plan["kind"] == "file":
            script = absolute_token(plan["value"])
            if script is None:
                fail(
                    "scheduled shell stdin path is not a literal absolute path"
                )
            return [(script, "shell-source")]
        if plan["kind"] == "opaque":
            if plan["value"] == "here-document":
                return []
            fail(
                "scheduled stdin-driven shell uses a command source that "
                f"cannot be inspected safely ({plan['value']})"
            )
        return []

    plan = interpreter_invocation(kind, arguments)
    candidates = [
        (preload, f"interpreter:{kind}") for preload in plan["preloads"]
    ]
    for source in plan["inline"]:
        for command in language_execution_commands(source, kind):
            candidates.extend(
                helper_candidates(command, depth + 1, "shell-fallback")
            )
    if plan["terminal"]:
        return candidates
    if plan["script"]:
        candidates.append((plan["script"], f"interpreter:{kind}"))
    return candidates


def run_parts_directory(arguments):
    index = 0
    value_options = {"--arg", "--regex", "--umask"}
    nonexecuting_options = {"--help", "--list", "--test", "--version"}
    options_end = (
        arguments.index("--") if "--" in arguments else len(arguments)
    )
    if any(argument in nonexecuting_options for argument in arguments[:options_end]):
        return None
    while index < len(arguments):
        argument = arguments[index]
        if argument == "--":
            index += 1
            break
        if argument in value_options:
            index += 2
            continue
        if any(argument.startswith(option + "=") for option in value_options):
            index += 1
            continue
        if argument.startswith("-"):
            index += 1
            continue
        break
    if index >= len(arguments):
        return None
    return absolute_token(arguments[index])


def helper_candidates_from_argv(
    arguments, depth, direct_invocation, stdin_source=None
):
    if depth > WRAPPER_DEPTH_LIMIT:
        fail(
            f"scheduled command wrapper inspection exceeded depth "
            f"{WRAPPER_DEPTH_LIMIT}"
        )
    argv = list(arguments)
    while argv and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", argv[0]):
        argv.pop(0)
    if not argv:
        return []
    if any(PORTAL_RUNTIME_REPAIR_LAUNCHER in item for item in argv):
        if (
            direct_invocation != "systemd"
            or len(argv) != 6
            or argv[:4] != [
                "/usr/bin/python3",
                "-I",
                "-S",
                PORTAL_RUNTIME_REPAIR_LAUNCHER,
            ]
            or re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", argv[4]) is None
            or re.fullmatch(
                r"/opt/bridgesllm/logs/"
                r"project-runtime-image-repair-[A-Za-z0-9_.:-]+\.log",
                argv[5],
            ) is None
        ):
            fail("scheduled Project runtime repair launcher command is malformed")
        return [
            (PORTAL_RUNTIME_REPAIR_LAUNCHER, "portal-runtime-repair-launcher")
        ]
    name = word(argv[0])
    rest = argv[1:]

    if direct_invocation == "shell-fallback" and argv[0] in {".", "source"}:
        # Shell source builtins execute only their first positional operand;
        # later values become the sourced file's positional arguments. Limit
        # recursion to a literal absolute file so dynamic PATH lookup remains
        # outside this bounded static inspection.
        sourced = absolute_token(rest[0]) if rest else None
        return [(sourced, "shell-source")] if sourced is not None else []

    if name in BUILTIN_WRAPPERS:
        if name == "command" and any(item in {"-v", "-V"} for item in rest):
            return []
        index = 0
        while index < len(rest) and rest[index].startswith("-"):
            if rest[index] == "--":
                index += 1
                break
            if name == "exec" and rest[index] == "-a" and index + 1 < len(rest):
                index += 2
            else:
                index += 1
        return recurse_argv(
            rest[index:], depth + 1, direct_invocation, stdin_source
        )

    if name == "env":
        return recurse_argv(
            env_command_argv(rest), depth + 1, "shell-fallback", stdin_source
        )

    if name == "time":
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-f", "--format", "-o", "--output"}:
                index += 2
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        return recurse_argv(
            rest[index:], depth + 1, "shell-fallback", stdin_source
        )

    if name == "timeout":
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-k", "--kill-after", "-s", "--signal"}:
                index += 2
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        if index >= len(rest):
            return []
        return recurse_argv(
            rest[index + 1:], depth + 1, "shell-fallback", stdin_source
        )

    if name == "flock":
        for index, item in enumerate(rest):
            if item in {"-c", "--command"} and index + 1 < len(rest):
                return helper_candidates(
                    rest[index + 1], depth + 1, "shell-fallback"
                )
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-w", "--wait", "-E", "--conflict-exit-code"}:
                index += 2
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        if index >= len(rest):
            return []
        return recurse_argv(
            rest[index + 1:], depth + 1, "shell-fallback", stdin_source
        )

    if name == "nice":
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-n", "--adjustment"}:
                index += 2
                continue
            if re.fullmatch(r"-\d+", item) or item.startswith("--adjustment="):
                index += 1
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        return recurse_argv(
            rest[index:], depth + 1, "shell-fallback", stdin_source
        )

    if name == "nohup":
        return recurse_argv(
            rest[1:] if rest[:1] == ["--"] else rest,
            depth + 1,
            "shell-fallback",
            stdin_source,
        )

    if name == "sudo":
        index = 0
        value_options = {
            "-C", "--close-from", "-D", "--chdir", "-g", "--group",
            "-h", "--host", "-p", "--prompt", "-R", "--chroot",
            "-T", "--command-timeout", "-u", "--user",
        }
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in value_options:
                index += 2
                continue
            if item.startswith("-") or re.fullmatch(
                r"[A-Za-z_][A-Za-z0-9_]*=.*", item
            ):
                index += 1
                continue
            break
        return recurse_argv(
            rest[index:], depth + 1, "shell-fallback", stdin_source
        )

    kind = interpreter_kind(name)
    if kind:
        return interpreter_candidates(
            kind, rest, depth, direct_invocation, stdin_source
        )

    if name == "run-parts":
        directory = run_parts_directory(rest)
        candidates = []
        executable = absolute_token(argv[0])
        if executable is not None:
            candidates.append((executable, direct_invocation))
        if directory is not None:
            candidates.append((directory, "run-parts"))
        return candidates

    executable = absolute_token(argv[0])
    if executable is None:
        return []
    return [(executable, direct_invocation)]


def helper_candidates(command, depth=0, direct_invocation="direct"):
    candidates = []
    if direct_invocation == "shell-fallback":
        segments = command_segments(command)
    elif direct_invocation == "systemd":
        segments = systemd_command_segments(command)
    else:
        segments = [tokens(command)]
    for segment in segments:
        stdin_source = None
        if direct_invocation == "shell-fallback":
            segment, stdin_source = shell_segment_plan(segment)
        elif direct_invocation == "systemd":
            segment = systemd_effective_argv(segment)
        candidates.extend(
            helper_candidates_from_argv(
                segment, depth, direct_invocation, stdin_source
            )
        )
    return candidates


def read_root_prefix(path, expected, maximum=4096):
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        fail(f"could not open scheduled helper {display(path)} safely: {exc}")
    try:
        opened = os.fstat(descriptor)
        if (
            opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid,
            opened.st_gid, opened.st_size, opened.st_mtime_ns, opened.st_ctime_ns,
        ) != (
            expected.st_dev, expected.st_ino, expected.st_mode, expected.st_uid,
            expected.st_gid, expected.st_size,
            expected.st_mtime_ns, expected.st_ctime_ns,
        ):
            fail(f"scheduled helper {display(path)} changed before type inspection")
        payload = os.read(descriptor, maximum)
        after = os.fstat(descriptor)
        if (
            after.st_dev, after.st_ino, after.st_mode, after.st_uid,
            after.st_gid, after.st_size, after.st_mtime_ns, after.st_ctime_ns,
        ) != (
            opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid,
            opened.st_gid, opened.st_size,
            opened.st_mtime_ns, opened.st_ctime_ns,
        ):
            fail(f"scheduled helper {display(path)} changed during type inspection")
        return payload
    finally:
        os.close(descriptor)


def supported_shebang_invocation(payload):
    first_line = payload.splitlines()[0] if payload.splitlines() else b""
    if not first_line.startswith(b"#!"):
        return None
    try:
        declaration = first_line[2:].decode("utf-8").strip()
    except UnicodeDecodeError:
        return None
    if not declaration:
        return None
    # Linux passes everything after the interpreter pathname as one optional
    # argv item. Quotes and spaces in that tail are not shell syntax. GNU env
    # is the deliberate exception: -S/--split-string parses its tail into the
    # final interpreter argv.
    shebang_match = re.fullmatch(r"(\S+)(?:[ \t]+(.*))?", declaration)
    if shebang_match is None:
        return None
    interpreter = shebang_match.group(1)
    optional_tail = shebang_match.group(2)
    arguments = [optional_tail] if optional_tail else []
    name = word(interpreter)
    if name == "env":
        remaining = env_command_argv(arguments)
        if not remaining:
            return None
        name = word(remaining[0])
        arguments = remaining
    else:
        arguments = [interpreter, *arguments]
    kind = interpreter_kind(name)
    return (kind, arguments[1:]) if kind is not None else None


def shell_heredoc_lex(command):
    """Mask arithmetic shifts and describe each real unquoted heredoc operator."""
    result = []
    masked = list(command)
    mask_marker = "\ue000"
    while mask_marker in command:
        mask_marker += "\ue001"
    quote = None
    escaped = False
    arithmetic_kind = None
    arithmetic_depth = 0
    index = 0
    while index < len(command):
        character = command[index]
        if escaped:
            if character == "<":
                # The shell treats this byte as literal. Mask it in the shlex
                # input too; otherwise `\\<<` or `\\<\\<` can be reassembled
                # into a false heredoc token even though the operator counter
                # correctly ignored the escaped byte.
                masked[index] = mask_marker
            escaped = False
            index += 1
            continue
        if quote == "'":
            if character == "<":
                masked[index] = mask_marker
            if character == "'":
                quote = None
            index += 1
            continue
        if quote == '"':
            if character == "<":
                masked[index] = mask_marker
            if character == "\\":
                escaped = True
            elif character == '"':
                quote = None
            index += 1
            continue
        if character == "\\":
            escaped = True
            index += 1
            continue
        if character in "'\"":
            quote = character
            index += 1
            continue
        if arithmetic_kind is not None:
            if command[index:index + 2] == "<<":
                # shlex otherwise exposes a Bash arithmetic left shift as the
                # same punctuation token used by a here-document. Preserve
                # token width while keeping it out of the heredoc stream.
                masked[index:index + 2] = [mask_marker, mask_marker]
                index += 2
                continue
            if arithmetic_kind == "paren":
                if character == "(":
                    arithmetic_depth += 1
                elif character == ")":
                    arithmetic_depth -= 1
                    if arithmetic_depth == 0:
                        arithmetic_kind = None
            elif character == "[":
                arithmetic_depth += 1
            elif character == "]":
                arithmetic_depth -= 1
                if arithmetic_depth == 0:
                    arithmetic_kind = None
            index += 1
            continue
        if character == "#" and (
            index == 0 or command[index - 1].isspace()
            or command[index - 1] in ";|&"
        ):
            break
        if command[index:index + 3] == "$((":
            arithmetic_kind = "paren"
            arithmetic_depth = 2
            index += 3
            continue
        if command[index:index + 2] == "((":
            arithmetic_kind = "paren"
            arithmetic_depth = 2
            index += 2
            continue
        if command[index:index + 2] == "$[":
            arithmetic_kind = "bracket"
            arithmetic_depth = 1
            index += 2
            continue
        if (
            command[index:index + 2] == "<<"
            and (index == 0 or command[index - 1] != "<")
            and command[index:index + 3] != "<<<"
        ):
            result.append(command[index + 2:index + 3] == "-")
            index += 2
            continue
        index += 1
    return "".join(masked), result, mask_marker


def shell_heredoc_tab_operators(command):
    """Record whether each real heredoc operator has a tab-strip dash."""
    return shell_heredoc_lex(command)[1]


def shell_heredoc_specs(command):
    """Return ordered delimiters with the command that receives each body."""
    masked_command, tab_operators, mask_marker = shell_heredoc_lex(command)
    try:
        # Non-POSIX mode retains quoting long enough to distinguish a quoted
        # delimiter (literal body) from an unquoted one (shell substitutions
        # still execute before the receiving interpreter reads the body).
        lexer = shlex.shlex(masked_command, posix=False, punctuation_chars="<;&|")
        lexer.whitespace_split = True
        lexer.commenters = "#"
        parts = list(lexer)
    except ValueError:
        return []
    heredoc_index = 0
    result = []
    segment = []
    index = 0
    while index < len(parts):
        if parts[index] in SEPARATORS:
            segment = []
            index += 1
            continue
        if parts[index] != "<<" or index + 1 >= len(parts):
            segment.append(parts[index])
            index += 1
            continue
        if heredoc_index >= len(tab_operators):
            return []
        strip_tabs = tab_operators[heredoc_index]
        heredoc_index += 1
        delimiter_index = index + 1
        delimiter = parts[delimiter_index]
        if strip_tabs and delimiter == "-":
            # shlex separates the valid spaced form `<<- 'EOF'` into
            # `<<`, `-`, and the delimiter word. Consume the operator dash;
            # it is never itself the terminator.
            delimiter_index += 1
            if delimiter_index >= len(parts):
                segment.append(parts[index])
                index += 1
                continue
            delimiter = parts[delimiter_index]
            strip_tabs = True
        elif strip_tabs and delimiter.startswith("-"):
            delimiter = delimiter[1:]
        # Non-operator less-than bytes remain masked in every ordinary token,
        # but a delimiter is a shell word whose exact quoted/escaped bytes are
        # semantically significant. Restore only this proven delimiter token;
        # restoring other tokens could recreate a false `<<` punctuation item.
        delimiter = delimiter.replace(mask_marker, "<")
        quoted = any(character in delimiter for character in "'\"\\")
        try:
            unquoted = shlex.split(delimiter, comments=False, posix=True)
        except ValueError:
            unquoted = []
        if len(unquoted) == 1 and unquoted[0]:
            try:
                receiver_argv = shlex.split(
                    " ".join(segment), comments=False, posix=True
                )
            except ValueError:
                receiver_argv = []
            result.append(
                (
                    unquoted[0], strip_tabs, not quoted,
                    wrapped_interpreter_kind(receiver_argv),
                )
            )
        index = delimiter_index + 1
    return result


def wrapped_interpreter_kind(arguments, depth=0):
    if depth > WRAPPER_DEPTH_LIMIT:
        return None
    argv, _ = shell_segment_plan(arguments)
    while argv and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", argv[0]):
        argv.pop(0)
    if not argv:
        return None
    name = word(argv[0])
    rest = argv[1:]
    kind = interpreter_kind(name)
    if kind is not None:
        return kind
    if name == "env":
        return wrapped_interpreter_kind(env_command_argv(rest), depth + 1)
    if name in BUILTIN_WRAPPERS:
        index = 0
        while index < len(rest) and rest[index].startswith("-"):
            if rest[index] == "--":
                index += 1
                break
            if name == "exec" and rest[index] == "-a" and index + 1 < len(rest):
                index += 2
            else:
                index += 1
        return wrapped_interpreter_kind(rest[index:], depth + 1)
    if name == "timeout":
        index = 0
        while index < len(rest):
            item = rest[index]
            if item == "--":
                index += 1
                break
            if item in {"-k", "--kill-after", "-s", "--signal"}:
                index += 2
                continue
            if item.startswith("-"):
                index += 1
                continue
            break
        return (
            wrapped_interpreter_kind(rest[index + 1:], depth + 1)
            if index < len(rest) else None
        )
    return None


def inspect_helper(path_logical, invocation, budget, depth, priority=False):
    if depth > HELPER_DEPTH_LIMIT:
        fail(f"scheduled helper recursion exceeded depth {HELPER_DEPTH_LIMIT}")
    lexical = host_path(path_logical)
    resolved, masked = resolve_secure_path(
        lexical,
        allow_missing=True,
        allow_mask=False,
        final_kind="either",
        # A dedicated service may need read/traverse access to its immutable
        # root-owned helper. Group identity is not mutation authority when no
        # traversed directory or final file grants group/world write. Keep
        # scheduler roots and definitions on the stricter root:root path.
        require_root_group=False,
        require_root_group_directories=False,
    )
    if masked or resolved is None:
        # A missing command cannot execute. If it appears later, a subsequent
        # installer run will inspect it like every other absolute helper.
        return None
    metadata = lstat_or_none(resolved)
    if metadata is None:
        fail(f"scheduled helper {path_logical} disappeared")
    if stat.S_ISDIR(metadata.st_mode):
        # A directory-shaped command token (including a bare `/`) cannot be
        # executed as a helper and is not evidence of unsafe cleanup.
        return None
    prefix = read_root_prefix(
        resolved,
        metadata,
        min(metadata.st_size, HELPER_FILE_LIMIT) + 1,
    )
    prune_candidate = priority or helper_prune_candidate(prefix)
    has_shebang = prefix.startswith(b"#!")
    shebang = supported_shebang_invocation(prefix)
    shebang_kind = shebang[0] if shebang is not None else None
    if invocation in {"direct", "systemd"} and shebang_kind is None:
        # A directly executed custom program is a statically inspectable
        # script only when its kernel interpreter contract is explicit. ELF,
        # other binaries, and non-shebang text executables remain opaque.
        return None
    if invocation == "shell-fallback" and shebang_kind is None:
        # Cron invokes its command through a shell, while the supported process
        # wrappers use execvp-style ENOEXEC fallback. In both cases an
        # executable non-ELF file without a shebang is interpreted by /bin/sh.
        # Shell source bytes need not be UTF-8, so preserve ASCII commands and
        # sanitize other bytes later instead of treating encoding as fatal.
        if (
            has_shebang
            or not metadata.st_mode & 0o111
            or prefix.startswith(b"\x7fELF")
        ):
            return None
    if not budget.admit(
        path_logical, resolved, metadata, candidate=prune_candidate
    ):
        return None
    payload, _ = read_root_file(resolved, require_root_group=False)
    if invocation == "shell-source":
        # The current shell interprets sourced content. A leading shebang is
        # merely a comment and cannot change the source language.
        language = "shell"
    elif invocation.startswith("interpreter:"):
        language = invocation.split(":", 1)[1]
    elif shebang_kind is not None:
        language = shebang_kind
    else:
        language = "shell"
    if b"\0" in payload:
        if language == "shell":
            # Bash ignores embedded NUL bytes with a warning. Remove them for
            # static inspection so the remaining executed shell text is still
            # checked for a literal unsafe prune.
            payload = payload.replace(b"\0", b"")
        elif not prune_candidate:
            return None
    if language == "shell":
        text = shell_text(payload)
    else:
        try:
            text = payload.decode("utf-8")
        except UnicodeDecodeError:
            if not prune_candidate:
                return None
            # Known interpreter source containing the byte-level Docker/prune
            # candidate cannot become opaque because of one irrelevant byte.
            # Preserve its ASCII source and line layout while replacing bytes
            # whose language semantics cannot be reduced safely.
            text = "".join(
                chr(value)
                if value in {9, 10, 13} or 32 <= value <= 126 else " "
                for value in payload
            )
        if not all(
            character in "\t\r\n" or character.isprintable()
            for character in text
        ):
            if not prune_candidate:
                return None
            text = "".join(
                chr(value)
                if value in {9, 10, 13} or 32 <= value <= 126 else " "
                for value in payload
            )

    def inspect_literal_commands(commands, line_number):
        for command in commands:
            prune_kind = dangerous(command, shell_syntax=True)
            if prune_kind:
                return prune_kind, display(resolved), line_number
            for nested, nested_invocation in helper_candidates(
                command, direct_invocation="shell-fallback"
            ):
                if nested_invocation == "run-parts":
                    finding = inspect_run_parts_directory(
                        nested, budget, depth + 1, priority=prune_candidate
                    )
                else:
                    finding = inspect_helper(
                        nested, nested_invocation, budget, depth + 1,
                        priority=prune_candidate,
                    )
                if finding:
                    return finding
        return None

    if shebang is not None and shebang_kind in {"python", "perl", "ruby", "node"}:
        shebang_plan = interpreter_invocation(
            shebang_kind, [*shebang[1], display(resolved)]
        )
        for preload in shebang_plan["preloads"]:
            finding = inspect_helper(
                preload, f"interpreter:{shebang_kind}", budget, depth + 1,
                priority=prune_candidate,
            )
            if finding:
                return finding
        for source in shebang_plan["inline"]:
            if not budget.admit_line(candidate=prune_candidate):
                return None
            finding = inspect_literal_commands(
                language_execution_commands(source, shebang_kind), 1
            )
            if finding:
                return finding
        if shebang_plan["terminal"]:
            return None

    logical_text = text.replace("\\\n", " ")
    if language != "shell":
        for raw in logical_text.splitlines():
            stripped = raw.strip()
            if (
                not stripped
                or stripped.startswith("#")
                or (language == "node" and stripped.startswith("//"))
            ):
                continue
            if not budget.admit_line(candidate=prune_candidate):
                return None
        for command, line_number in language_execution_command_records(
            logical_text, language
        ):
            finding = inspect_literal_commands([command], line_number)
            if finding:
                return finding
        return None

    heredocs = []
    heredoc_body = []
    heredoc_body_start = None
    for line_number, raw in enumerate(logical_text.splitlines(), 1):
        if heredocs:
            delimiter, strip_tabs, expand_body, receiver = heredocs[0]
            comparison = raw.lstrip("\t") if strip_tabs else raw
            if comparison == delimiter:
                if receiver not in {None, "shell"} and heredoc_body:
                    body_text = "\n".join(heredoc_body)
                    for command, relative_line in language_execution_command_records(
                        body_text, receiver
                    ):
                        finding = inspect_literal_commands(
                            [command], heredoc_body_start + relative_line - 1
                        )
                        if finding:
                            return finding
                heredocs.pop(0)
                heredoc_body = []
                heredoc_body_start = None
                continue
            if receiver is not None:
                if not budget.admit_line(candidate=prune_candidate):
                    return None
                if receiver == "shell":
                    commands = [raw]
                else:
                    if heredoc_body_start is None:
                        heredoc_body_start = line_number
                    heredoc_body.append(raw)
                    commands = language_execution_commands(raw, receiver)
                finding = inspect_literal_commands(commands, line_number)
                if finding:
                    return finding
            if expand_body:
                finding = inspect_literal_commands(
                    shell_command_substitutions(raw), line_number
                )
                if finding:
                    return finding
            continue
        stripped = raw.strip()
        if (
            not stripped
            or stripped.startswith("#")
            or (language == "node" and stripped.startswith("//"))
        ):
            continue
        if not budget.admit_line(candidate=prune_candidate):
            return None
        commands = (
            [raw] if language == "shell"
            else language_execution_commands(raw, language)
        )
        finding = inspect_literal_commands(commands, line_number)
        if finding:
            return finding
        if language == "shell":
            heredocs.extend(shell_heredoc_specs(raw))
    return None


def inspect_run_parts_directory(path_logical, budget, depth, priority=False):
    if depth > HELPER_DEPTH_LIMIT:
        fail(f"scheduled helper recursion exceeded depth {HELPER_DEPTH_LIMIT}")
    for definition, _, target in secure_cron_directory(
        path_logical,
        "run-parts",
        budget.scheduler_entries,
        budget.scheduler_directories,
    ):
        finding = inspect_helper(
            display(definition), "direct", budget, depth, priority=priority
        )
        if finding:
            prune_kind, helper_path, helper_line = finding
            return (
                prune_kind,
                display(definition) if helper_path == display(target) else helper_path,
                helper_line,
            )
    return None


def inspect_scheduled_command(
    command, budget, direct_invocation, prioritize_helpers=False
):
    prune_kind = dangerous(
        command,
        shell_syntax=direct_invocation == "shell-fallback",
        systemd_syntax=direct_invocation == "systemd",
    )
    if prune_kind:
        return prune_kind, None, None
    for helper, invocation in helper_candidates(
        command, direct_invocation=direct_invocation
    ):
        if invocation == "run-parts":
            finding = inspect_run_parts_directory(
                helper, budget, 1, priority=prioritize_helpers
            )
        else:
            finding = inspect_helper(
                helper, invocation, budget, 1, priority=prioritize_helpers
            )
        if finding:
            return finding
    return None


def unsafe_jobs(excluded):
    findings, inspected = [], set()
    scheduler_entry_budget = [0]
    scheduler_directories = set()
    helper_budget = HelperBudget(scheduler_entry_budget, scheduler_directories)
    systemd_cache = {}
    for definition, kind, resolved_target in jobs(
        scheduler_entry_budget, scheduler_directories
    ):
        if excluded is not None and (
            os.path.normpath(definition) == os.path.normpath(excluded)
        ):
            continue
        if kind == "systemd":
            effective = {key: [] for key in sorted(EXEC_KEYS)}
            service_assignments = []
            for origin, target in resolved_target:
                metadata = lstat_or_none(target)
                if metadata is None:
                    fail(f"systemd definition {display(target)} disappeared")
                if (
                    not stat.S_ISREG(metadata.st_mode)
                    or metadata.st_uid != 0
                    or metadata.st_gid != 0
                    or stat.S_IMODE(metadata.st_mode) & 0o022
                ):
                    fail(
                        f"systemd definition {display(target)} is non-regular, "
                        "non-root-owned, or writable by another account"
                    )
                identity = (
                    metadata.st_dev,
                    metadata.st_ino,
                    metadata.st_size,
                    metadata.st_mtime_ns,
                    metadata.st_ctime_ns,
                )
                cached = systemd_cache.get(identity)
                if cached is None:
                    payload, _ = read_root_file(
                        target, require_root_group=True
                    )
                    assignments = list(systemd_service_directives(payload))
                    directives = [
                        item for item in assignments if item[1] in EXEC_KEYS
                    ]
                    cached = (directives, assignments)
                    systemd_cache[identity] = cached
                directives, assignments = cached
                service_assignments.extend(
                    (origin, number, key, value)
                    for number, key, value in assignments
                )
                for number, key, command in directives:
                    if not command.strip():
                        effective[key] = []
                    else:
                        effective[key].append((origin, number, command))
            is_runtime_repair_unit = (
                definition == os.path.basename(PORTAL_RUNTIME_REPAIR_UNIT)
            )
            references_runtime_repair = any(
                PORTAL_RUNTIME_REPAIR_LAUNCHER
                in systemd_unescaped_reference(value)
                for _, _, _, value in service_assignments
            )
            if is_runtime_repair_unit or references_runtime_repair:
                expected_origin = PORTAL_RUNTIME_REPAIR_UNIT
                if (
                    not is_runtime_repair_unit
                    or len(resolved_target) != 1
                    or any(
                        display(origin) != expected_origin
                        or display(target) != expected_origin
                        for origin, target in resolved_target
                    )
                ):
                    fail(
                        "scheduled Project runtime repair launcher is outside "
                        "its exact transient unit"
                    )
                service_shape = [
                    (key, value.strip())
                    for _, _, key, value in service_assignments
                ]
                environment_values = [
                    value for key, value in service_shape
                    if key == "Environment"
                ]
                exec_start_values = [
                    value for key, value in service_shape
                    if key == "ExecStart"
                ]
                other_service_keys = [
                    key for key, _ in service_shape
                    if key not in {"Environment", "ExecStart"}
                ]
                nonempty_exec_start = [
                    value for value in exec_start_values if value
                ]
                if (
                    other_service_keys
                    or len(environment_values) != 1
                    or tokens(environment_values[0]) != ["HOME=/root"]
                    or len(exec_start_values) != 2
                    or exec_start_values.count("") != 1
                    or len(nonempty_exec_start) != 1
                ):
                    fail(
                        "scheduled Project runtime repair unit properties "
                        "are malformed"
                    )
                repair_candidates = helper_candidates(
                    nonempty_exec_start[0], direct_invocation="systemd"
                )
                if repair_candidates != [
                    (
                        PORTAL_RUNTIME_REPAIR_LAUNCHER,
                        "portal-runtime-repair-launcher",
                    )
                ]:
                    fail(
                        "scheduled Project runtime repair launcher command "
                        "is malformed"
                    )
            unit_found = False
            for key in sorted(effective):
                for origin, number, command in effective[key]:
                    finding = inspect_scheduled_command(
                        command,
                        helper_budget,
                        "systemd",
                        prioritize_helpers=locally_managed_scheduler_path(
                            display(origin)
                        ),
                    )
                    if finding:
                        prune_kind, helper_path, helper_line = finding
                        findings.append(
                            (
                                helper_path or display(origin),
                                helper_line or number,
                                prune_kind,
                            )
                        )
                        unit_found = True
                        break
                if unit_found:
                    break
            continue
        target = resolved_target
        if target is None:
            continue
        metadata = lstat_or_none(target)
        if metadata is None:
            continue
        if (
            not stat.S_ISREG(metadata.st_mode)
            or metadata.st_uid != 0
            or stat.S_IMODE(metadata.st_mode) & 0o022
            or not metadata.st_mode & stat.S_IRUSR
        ):
            fail(
                f"cron definition {display(target)} is non-regular, unreadable, "
                "non-root-owned, or writable by another account"
            )
        identity = (metadata.st_dev, metadata.st_ino, kind)
        if identity in inspected:
            continue
        inspected.add(identity)
        if kind == "run-parts":
            finding = inspect_helper(
                display(definition), "direct", helper_budget, 1, priority=True
            )
            if finding:
                prune_kind, helper_path, helper_line = finding
                finding_path = (
                    display(definition)
                    if helper_path == display(target)
                    else helper_path or display(definition)
                )
                findings.append(
                    (finding_path, helper_line or 1, prune_kind)
                )
            continue
        payload, _ = read_root_file(target)
        commands = cron_commands(payload, kind)
        for number, command in commands:
            finding = inspect_scheduled_command(
                command,
                helper_budget,
                "shell-fallback",
                prioritize_helpers=True,
            )
            if finding:
                prune_kind, helper_path, helper_line = finding
                findings.append(
                    (helper_path or display(definition), helper_line or number, prune_kind)
                )
                break
    return findings


def ensure_quarantine_parent(path):
    relative = os.path.relpath(os.path.dirname(path), root)
    if relative.startswith(".."):
        fail("quarantine path escapes the host root")
    current = root
    components = [] if relative == "." else relative.split(os.sep)
    for index, component in enumerate(components):
        current = os.path.join(current, component)
        metadata = lstat_or_none(current)
        if metadata is None:
            os.mkdir(current, 0o700 if index == len(components) - 1 else 0o755)
            metadata = lstat_or_none(current)
        if (
            metadata is None
            or not stat.S_ISDIR(metadata.st_mode)
            or stat.S_ISLNK(metadata.st_mode)
            or metadata.st_uid != 0
            or metadata.st_gid != 0
            or stat.S_IMODE(metadata.st_mode) & 0o022
        ):
            fail(f"quarantine parent {display(current)} is linked or has unsafe metadata")
        if index == len(components) - 1 and stat.S_IMODE(metadata.st_mode) != 0o700:
            fail(f"quarantine directory {display(current)} must have mode 0700")


def fsync_dir(path):
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def open_secure_directory_fd(path, context):
    normalized = os.path.normpath(path)
    relative = os.path.relpath(normalized, root)
    if relative == ".." or relative.startswith(".." + os.sep):
        fail(f"{context} directory escapes the host root")
    flags = (
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    )
    try:
        descriptor = os.open(root, flags)
    except OSError as exc:
        fail(f"could not bind the host root for {context}: {exc}")
    current = root
    try:
        require_secure_directory(current, os.fstat(descriptor), context)
        components = [] if relative == "." else relative.split(os.sep)
        for component in components:
            try:
                child = os.open(component, flags, dir_fd=descriptor)
            except OSError as exc:
                fail(
                    f"could not bind {context} directory "
                    f"{display(os.path.join(current, component))}: {exc}"
                )
            os.close(descriptor)
            descriptor = child
            current = os.path.join(current, component)
            require_secure_directory(current, os.fstat(descriptor), context)
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise


def open_attested_legacy(parent_fd, name, expected, expected_payload):
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(name, flags, dir_fd=parent_fd)
    except OSError as exc:
        fail(f"could not open {source_logical} for inode-bound quarantine: {exc}")
    try:
        metadata = os.fstat(descriptor)
        identity = (
            metadata.st_dev, metadata.st_ino, metadata.st_mode, metadata.st_uid,
            metadata.st_gid, metadata.st_nlink, metadata.st_size, metadata.st_mtime_ns,
        )
        expected_identity = (
            expected.st_dev, expected.st_ino, expected.st_mode, expected.st_uid,
            expected.st_gid, expected.st_nlink, expected.st_size, expected.st_mtime_ns,
        )
        if identity != expected_identity:
            fail(f"{source_logical} changed before inode-bound quarantine")
        payload = b""
        while len(payload) <= LIMIT:
            chunk = os.read(descriptor, min(65536, LIMIT + 1 - len(payload)))
            if not chunk:
                break
            payload += chunk
        if payload != expected_payload or not is_known_legacy_payload(payload):
            fail(f"{source_logical} content changed before inode-bound quarantine")
        os.lseek(descriptor, 0, os.SEEK_SET)
        return descriptor, metadata
    except BaseException:
        os.close(descriptor)
        raise


def fixture_race_hook(
    stage,
    source,
    source_parent_fd,
    source_name,
    quarantine_name,
    quarantine_dir_fd,
):
    hook = ""
    if os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1" and root != "/":
        hook = os.environ.get("BRIDGESLLM_DOCKER_PRUNE_TEST_HOOK", "")
    if not hook:
        return
    if hook == "destination-collision" and stage == "before-link":
        descriptor = os.open(
            quarantine_name,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0),
            0o600,
            dir_fd=quarantine_dir_fd,
        )
        try:
            os.write(descriptor, b"operator collision\n")
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        os.fsync(quarantine_dir_fd)
        return
    if hook in {"source-replacement", "post-check-source-replacement"}:
        expected_stage = (
            "before-link" if hook == "source-replacement" else "post-source-check"
        )
        if stage != expected_stage:
            return
        replacement = source + ".test-replacement"
        displaced = source + ".test-old"
        if os.path.lexists(displaced):
            fail("source-replacement test hook found an existing displaced path")
        replacement_payload, _ = read_root_file(
            replacement, {0o644}, True, True
        )
        if replacement_payload is None:
            fail("source-replacement test hook has no replacement fixture")
        os.rename(
            source_name,
            source_name + ".test-old",
            src_dir_fd=source_parent_fd,
            dst_dir_fd=source_parent_fd,
        )
        os.rename(
            source_name + ".test-replacement",
            source_name,
            src_dir_fd=source_parent_fd,
            dst_dir_fd=source_parent_fd,
        )
        os.fsync(source_parent_fd)
        return
    if hook == "final-source-reappearance":
        return
    if hook and stage != "before-link":
        return
    fail(f"unknown Docker prune fixture hook: {hook}")


def unlink_destination_if_held_inode(directory_fd, name, held):
    try:
        current = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
    except FileNotFoundError:
        return
    if (current.st_dev, current.st_ino) != (held.st_dev, held.st_ino):
        fail("quarantine destination changed identity during rollback")
    os.unlink(name, dir_fd=directory_fd)
    os.fsync(directory_fd)


def rename_noreplace(source_dir_fd, source_name, target_dir_fd, target_name):
    libc = ctypes.CDLL(None, use_errno=True)
    renameat2 = getattr(libc, "renameat2", None)
    if renameat2 is None:
        fail("this Linux libc does not expose renameat2 for no-replace quarantine")
    renameat2.argtypes = [
        ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p,
        ctypes.c_uint,
    ]
    renameat2.restype = ctypes.c_int
    if renameat2(
        source_dir_fd,
        os.fsencode(source_name),
        target_dir_fd,
        os.fsencode(target_name),
        1,  # RENAME_NOREPLACE
    ) != 0:
        error_number = ctypes.get_errno()
        raise OSError(error_number, os.strerror(error_number))


def restore_tombstone(source_parent_fd, tombstone_name, source_name):
    try:
        rename_noreplace(
            source_parent_fd,
            tombstone_name,
            source_parent_fd,
            source_name,
        )
    except OSError as exc:
        fail(
            f"source replacement was preserved as {tombstone_name}, but could "
            f"not be restored to {source_logical}: {exc}"
        )
    os.fsync(source_parent_fd)


def quarantine_legacy_inode(source, quarantine, expected, expected_payload):
    source_directory = os.path.dirname(source)
    source_name = os.path.basename(source)
    quarantine_directory = os.path.dirname(quarantine)
    quarantine_name = os.path.basename(quarantine)
    source_parent_fd = open_secure_directory_fd(
        source_directory, "legacy source-parent"
    )
    try:
        source_fd, held = open_attested_legacy(
            source_parent_fd, source_name, expected, expected_payload
        )
    except BaseException:
        os.close(source_parent_fd)
        raise
    try:
        quarantine_dir_fd = open_secure_directory_fd(
            quarantine_directory, "quarantine"
        )
    except BaseException:
        os.close(source_fd)
        os.close(source_parent_fd)
        raise
    linked = False
    tombstone_name = None
    try:
        fixture_race_hook(
            "before-link",
            source,
            source_parent_fd,
            source_name,
            quarantine_name,
            quarantine_dir_fd,
        )
        libc = ctypes.CDLL(None, use_errno=True)
        linkat = getattr(libc, "linkat", None)
        if linkat is None:
            fail("this Linux libc does not expose linkat for inode-bound quarantine")
        linkat.argtypes = [
            ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
        ]
        linkat.restype = ctypes.c_int
        if linkat(source_fd, b"", quarantine_dir_fd, os.fsencode(quarantine_name), 0x1000) != 0:
            error_number = ctypes.get_errno()
            if error_number == errno.EEXIST:
                fail(
                    f"{quarantine_logical} appeared during quarantine; "
                    "the active legacy job was left untouched"
                )
            fail(
                "inode-bound no-replace quarantine was unavailable; "
                f"the active legacy job was left untouched ({os.strerror(error_number)})"
            )
        linked = True
        os.fsync(quarantine_dir_fd)

        source_now = os.stat(
            source_name, dir_fd=source_parent_fd, follow_symlinks=False
        )
        destination_now = os.stat(
            quarantine_name, dir_fd=quarantine_dir_fd, follow_symlinks=False
        )
        held_now = os.fstat(source_fd)
        held_identity = (held.st_dev, held.st_ino)
        if (
            (source_now.st_dev, source_now.st_ino) != held_identity
            or (destination_now.st_dev, destination_now.st_ino) != held_identity
            or (held_now.st_dev, held_now.st_ino) != held_identity
            or held_now.st_nlink != 2
        ):
            unlink_destination_if_held_inode(
                quarantine_dir_fd, quarantine_name, held
            )
            linked = False
            fail(
                f"{source_logical} changed at the final quarantine boundary; "
                "no recovery copy was installed"
            )

        fixture_race_hook(
            "post-source-check",
            source,
            source_parent_fd,
            source_name,
            quarantine_name,
            quarantine_dir_fd,
        )
        tombstone_name = (
            f".{source_name}.bridgesllm-tombstone-{os.getpid()}-"
            f"{os.urandom(16).hex()}"
        )
        try:
            rename_noreplace(
                source_parent_fd,
                source_name,
                source_parent_fd,
                tombstone_name,
            )
        except OSError as exc:
            unlink_destination_if_held_inode(
                quarantine_dir_fd, quarantine_name, held
            )
            linked = False
            fail(f"could not tombstone the attested legacy source: {exc}")
        tombstone = os.stat(
            tombstone_name, dir_fd=source_parent_fd, follow_symlinks=False
        )
        if (tombstone.st_dev, tombstone.st_ino) != held_identity:
            restore_tombstone(source_parent_fd, tombstone_name, source_name)
            tombstone_name = None
            unlink_destination_if_held_inode(
                quarantine_dir_fd, quarantine_name, held
            )
            linked = False
            fail(
                f"{source_logical} changed after its final identity check; "
                "the replacement survived and no recovery copy was installed"
            )
        os.unlink(tombstone_name, dir_fd=source_parent_fd)
        tombstone_name = None
        os.fchmod(source_fd, 0o600)
        os.fsync(source_fd)
        os.fsync(source_parent_fd)
        os.fsync(quarantine_dir_fd)
        final = os.fstat(source_fd)
        if final.st_nlink != 1 or stat.S_IMODE(final.st_mode) != 0o600:
            fail("inode-bound quarantine did not settle to one sealed recovery link")
    except BaseException:
        if tombstone_name is not None:
            try:
                tombstone = os.stat(
                    tombstone_name,
                    dir_fd=source_parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                tombstone = None
            if tombstone is not None and (
                tombstone.st_dev, tombstone.st_ino
            ) == (held.st_dev, held.st_ino):
                restore_tombstone(source_parent_fd, tombstone_name, source_name)
                tombstone_name = None
        if linked:
            try:
                current = os.stat(
                    source_name,
                    dir_fd=source_parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                current = None
            if current is not None:
                unlink_destination_if_held_inode(
                    quarantine_dir_fd, quarantine_name, held
                )
        raise
    finally:
        os.close(quarantine_dir_fd)
        os.close(source_fd)
        os.close(source_parent_fd)


def attest_secure_directory_chain(path):
    relative = os.path.relpath(path, root)
    if relative == ".." or relative.startswith(".." + os.sep):
        fail(f"scheduler directory {display(path)} escapes the host root")
    current = root
    components = [] if relative == "." else relative.split(os.sep)
    for component in [None, *components]:
        if component is not None:
            current = os.path.join(current, component)
        metadata = lstat_or_none(current)
        if metadata is None:
            return False
        if (
            not stat.S_ISDIR(metadata.st_mode)
            or stat.S_ISLNK(metadata.st_mode)
            or metadata.st_uid != 0
            or metadata.st_gid != 0
            or stat.S_IMODE(metadata.st_mode) & 0o022
        ):
            fail(
                f"scheduler directory chain component {display(current)} is "
                "linked, non-root-owned, or writable by another account"
            )
    return True


def fixture_final_scan_hook(source):
    if not (
        os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
        and root != "/"
        and os.environ.get("BRIDGESLLM_DOCKER_PRUNE_TEST_HOOK", "")
        == "final-source-reappearance"
    ):
        return
    parent = os.path.dirname(source)
    parent_fd = open_secure_directory_fd(parent, "legacy final-scan source-parent")
    try:
        descriptor = os.open(
            os.path.basename(source),
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0),
            0o644,
            dir_fd=parent_fd,
        )
        try:
            os.write(descriptor, LEGACY)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
        os.fsync(parent_fd)
    finally:
        os.close(parent_fd)


root_metadata = lstat_or_none(root)
if (
    root_metadata is None
    or not stat.S_ISDIR(root_metadata.st_mode)
    or stat.S_ISLNK(root_metadata.st_mode)
    or root_metadata.st_uid != 0
    or root != os.path.realpath(root)
):
    fail("host root must be an existing canonical root-owned directory")

source = host_path(source_logical)
quarantine = host_path(quarantine_logical)
source_parent_exists = attest_secure_directory_chain(os.path.dirname(source))
source_exists = source_parent_exists and os.path.lexists(source)
quarantine_exists = os.path.lexists(quarantine)
source_metadata = None

if source_exists:
    payload, source_metadata = read_root_file(source, {0o644}, True, True)
    if not is_known_legacy_payload(payload):
        fail(
            f"{source_logical} differs from the one known legacy job; "
            "disable or replace it manually, then retry"
        )
if quarantine_exists:
    ensure_quarantine_parent(quarantine)
    payload, _ = read_root_file(quarantine, {0o600}, True, True)
    if not is_known_legacy_payload(payload):
        fail(f"{quarantine_logical} is not the known recovery copy; resolve it manually")

findings = unsafe_jobs(source)
if findings:
    print(
        "Unsafe Docker prune guard: refusing install/update because another "
        "effective installed root scheduler definition contains a literal "
        "command that can delete retained Docker images:",
        file=sys.stderr,
    )
    for path, number, kind in findings[:32]:
        print(f"  - {path}:{number} (docker {kind} prune with --all/-a)", file=sys.stderr)
    if len(findings) > 32:
        print(f"  - and {len(findings) - 32} more", file=sys.stderr)
    print(
        "Disable the definition or change it to dangling-only cleanup, such as "
        "docker image prune --force, then rerun. No unknown job was changed.",
        file=sys.stderr,
    )
    raise SystemExit(1)

if source_exists and quarantine_exists:
    fail(
        f"both {source_logical} and {quarantine_logical} exist; "
        "verify the recovery copy before removing the active file"
    )
if source_exists:
    ensure_quarantine_parent(quarantine)
    payload, current = read_root_file(source, {0o644}, True, True)
    if not is_known_legacy_payload(payload) or (
        current.st_dev, current.st_ino, current.st_mtime_ns
    ) != (
        source_metadata.st_dev, source_metadata.st_ino, source_metadata.st_mtime_ns
    ):
        fail(f"{source_logical} changed before quarantine")
    quarantine_legacy_inode(source, quarantine, current, payload)
    print(f"Quarantined the retired all-images Docker prune job at {quarantine_logical}.")

if os.path.lexists(source):
    fail(f"{source_logical} still exists after convergence")
fixture_final_scan_hook(source)
if os.path.lexists(quarantine):
    payload, _ = read_root_file(quarantine, {0o600}, True, True)
    if not is_known_legacy_payload(payload):
        fail(f"{quarantine_logical} failed final attestation")
if unsafe_jobs(None):
    fail(
        "an unsafe Docker prune definition appeared during convergence; "
        "inspect installed scheduler definitions and retry"
    )
if os.path.lexists(source):
    fail(f"{source_logical} reappeared during final convergence")
PY2
}

ensure_media_toolchain() {
  if command -v ffmpeg >/dev/null 2>&1 \
    && command -v ffprobe >/dev/null 2>&1; then
    ok "Animated GIF media tools"
    return 0
  fi

  command -v apt-get >/dev/null 2>&1 || return 1
  info "Installing the FFmpeg media tools required for animated GIF uploads..."
  run "apt-get update -qq" || return 1
  spin_apt "Installing animated GIF media tools" ffmpeg || return 1
  command -v ffmpeg >/dev/null 2>&1 \
    && command -v ffprobe >/dev/null 2>&1
}

preflight() {
  step_header "Checking system requirements"
  CURRENT_STEP="preflight"

  # Root
  [[ "${EUID:-$(id -u)}" -eq 0 ]] || fail "Must run as root. Use: sudo bash ${SCRIPT_NAME}"

  # OS
  if [[ -f /etc/os-release ]]; then
    OS_ID="$(grep -oP '^ID=\K.*' /etc/os-release | tr -d '"' || echo unknown)"
    OS_VERSION="$(grep -oP '^VERSION_ID=\K.*' /etc/os-release | tr -d '"' || echo unknown)"
  fi
  command -v apt-get &>/dev/null && APT_AVAILABLE=true

  case "${OS_ID}" in
    ubuntu|debian) ;;
    *) warn "Detected ${OS_ID} ${OS_VERSION} — tested on Ubuntu/Debian only" ;;
  esac

  # RAM
  local mem_mb
  mem_mb=$(awk '/MemTotal/ {printf "%d", $2/1024}' /proc/meminfo)
  (( mem_mb >= MIN_RAM_MB )) || fail "Need ${MIN_RAM_MB}MB+ RAM (found: ${mem_mb}MB)"

  # Disk
  local disk_gb
  disk_gb=$(df -BG / | awk 'NR==2 {gsub("G",""); print $4}')
  (( disk_gb >= MIN_DISK_GB )) || fail "Need ${MIN_DISK_GB}GB+ disk (found: ${disk_gb}GB)"

  # CPUs
  local cpus
  cpus=$(nproc 2>/dev/null || echo 1)
  (( cpus >= 2 )) || warn "Only ${cpus} CPU — 2+ CPUs recommended for best performance"

  local uptime_min
  uptime_min=$(awk '{print int($1/60)}' /proc/uptime 2>/dev/null || echo 9999)

  echo ""
  print_kv "OS" "${OS_ID^} ${OS_VERSION}" "$WHITE"
  print_kv "CPUs" "${cpus}" "$WHITE"
  print_kv "RAM" "${mem_mb} MB" "$WHITE"
  print_kv "Disk free" "${disk_gb} GB" "$WHITE"
  if use_local_profile; then
    print_kv "Profile" "Local beta (WSL / localhost, experimental)" "$GREEN"
  else
    print_kv "Profile" "Server / VPS" "$WHITE"
  fi
  print_kv "Uptime" "${uptime_min} min" "$WHITE"
  echo ""

  if use_local_profile && ! systemd_ready; then
    fail "WSL detected but systemd is not running. Enable systemd for your Ubuntu WSL distro, restart WSL, then rerun the installer. See docs/WINDOWS_WSL_BETA.md"
  fi

  if ! use_local_profile && (( uptime_min < 20 )); then
    warn "Fresh VPS detected. First-boot package tasks may still be running in the background."
    info "If package setup pauses later, the installer will now show what it is waiting on and continue automatically."
  fi

  # Ports
  local blocked=""
  if use_local_profile || use_tailnet_profile; then
    if ss -tlnp "sport = :4001" 2>/dev/null | grep -q ":4001"; then
      blocked=" 4001"
    fi
    [[ -z "$blocked" ]] && ok "Port 4001 available" || warn "Port${blocked} in use — another local portal or web app may already be running"
  else
    for port in 80 443; do
      if ss -tlnp "sport = :${port}" 2>/dev/null | grep -q ":${port}"; then
        blocked+=" $port"
      fi
    done
    [[ -z "$blocked" ]] && ok "Ports 80, 443 available" || warn "Ports${blocked} in use — Caddy will take them over"
  fi

  # Internet
  curl -fsSL --max-time 10 https://www.google.com &>/dev/null || fail "No internet connectivity"

  # Public IP / local access
  if use_local_profile; then
    PUBLIC_IP="127.0.0.1"
    print_kv "Access URL" "http://localhost:4001" "$GREEN"
    info "WSL local mode serves the portal directly on localhost so Windows users can test before moving to a VPS. This path is experimental, still untested in the field, and under active development."
  elif use_tailnet_profile; then
    # A public IP is not required: the portal is reachable only over the
    # operator's tailnet, and no public port is ever opened.
    PUBLIC_IP="$(curl -fsSL --max-time 5 https://api.ipify.org 2>/dev/null || echo "0.0.0.0")"
    print_kv "Origin mode" "Private Tailscale network (no public ports)" "$GREEN"
    warn "Tailnet origin mode is EXPERIMENTAL — new and still under field validation. Use --domain for the recommended production install."
  else
    PUBLIC_IP=$(curl -fsSL --max-time 5 https://api.ipify.org 2>/dev/null || \
                curl -fsSL --max-time 5 https://ifconfig.me 2>/dev/null || \
                echo "")
    if [[ -n "$PUBLIC_IP" ]]; then
      print_kv "Public IP" "${PUBLIC_IP}" "$GREEN"
    else
      warn "Could not detect public IP"
      PUBLIC_IP="0.0.0.0"
    fi
  fi

  if $APT_AVAILABLE; then
    wait_for_package_manager_ready "system preflight"
  fi

  # Core tools — always ensure lsb-release is present (needed by PostgreSQL repo setup)
  local missing=""
  for cmd in curl git openssl rsync lsb_release zstd python3; do
    command -v "$cmd" &>/dev/null || missing+=" $cmd"
  done
  if [[ -n "$missing" ]]; then
    $APT_AVAILABLE || fail "Missing:${missing} — and apt is not available"
    info "Installing core tools..."
    run "apt-get update -qq && apt-get install -y -qq curl git openssl rsync ca-certificates gnupg lsb-release ffmpeg python3 python3-venv zstd"
  fi
  ensure_media_toolchain \
    || fail "Animated GIF uploads require ffmpeg and ffprobe, but the FFmpeg package could not be installed. Check ${LOG_FILE}, repair apt, and rerun the installer."

  ok "System checks passed"
}

# ═══════════════════════════════════════════════════════════════
# Step 2: System packages
# ═══════════════════════════════════════════════════════════════

ensure_remote_desktop_packages() {
  # Remote Desktop packages (VNC + XFCE desktop + PulseAudio + X11 clipboard bridge).
  # Keep this idempotent: update/recovery paths call Remote Desktop setup directly,
  # so new package requirements must repair existing installs, not just fresh installs.
  local rd_pkgs=(tigervnc-standalone-server novnc websockify xfce4 xfce4-goodies xfce4-terminal dbus-x11 x11-utils xauth xclip xsel xterm firefox pulseaudio pulseaudio-utils librsvg2-common wmctrl xdotool)
  local rd_missing=()
  for pkg in "${rd_pkgs[@]}"; do
    if ! dpkg -s "$pkg" &>/dev/null; then
      rd_missing+=("$pkg")
    fi
  done
  if [[ ${#rd_missing[@]} -eq 0 ]]; then
    ok "Remote Desktop packages"
  else
    run "apt-get update -qq"
    spin_apt "Installing Remote Desktop packages" "${rd_missing[@]}"
    ok "Remote Desktop packages"
  fi
}

install_system_packages() {
  step_header "Installing system packages"
  CURRENT_STEP="system packages"

  # OpenClaw publishes a disjoint engine range with exact patch floors. Node 23
  # is not supported even though it is numerically newer than Node 22.
  ensure_supported_node_runtime

  # PostgreSQL 16
  if command -v psql &>/dev/null; then
    ok "PostgreSQL $(psql --version | grep -oP '\d+' | head -1)"
  else
    run "apt-get install -y -qq wget"
    run "sh -c 'echo \"deb [signed-by=/usr/share/keyrings/postgresql-keyring.gpg] http://apt.postgresql.org/pub/repos/apt \$(lsb_release -cs)-pgdg main\" > /etc/apt/sources.list.d/pgdg.list'"
    progress "Refreshing PostgreSQL signing key..."
    ensure_keyring_from_url "https://www.postgresql.org/media/keys/ACCC4CF8.asc" "/usr/share/keyrings/postgresql-keyring.gpg"
    spin "Installing PostgreSQL 16" "apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq postgresql-16 postgresql-contrib-16"
    run "systemctl enable postgresql && systemctl start postgresql"
    ok "PostgreSQL 16"
  fi

  # Caddy
  if use_local_profile; then
    info "Skipping Caddy in local beta mode — portal will be served directly on http://localhost:4001"
  elif command -v caddy &>/dev/null; then
    ok "Caddy web server"
  else
    run "apt-get install -y -qq debian-keyring debian-archive-keyring apt-transport-https"
    progress "Refreshing Caddy signing key..."
    ensure_keyring_from_url "https://dl.cloudsmith.io/public/caddy/stable/gpg.key" "/usr/share/keyrings/caddy-stable-archive-keyring.gpg"
    run "curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' | tee /etc/apt/sources.list.d/caddy-stable.list"
    spin "Installing Caddy web server" "apt-get update -qq && apt-get install -y -qq caddy"
    ok "Caddy web server"
  fi

  # Docker
  if command -v docker &>/dev/null; then
    ok "Docker"
  else
    spin "Installing Docker" "curl -fsSL https://get.docker.com | sh"
    run "systemctl enable docker && systemctl start docker"
    ok "Docker"
  fi

  # ClamAV
  if command -v clamscan &>/dev/null; then
    ok "ClamAV antivirus"
  else
    spin "Installing ClamAV antivirus" "DEBIAN_FRONTEND=noninteractive apt-get install -y -qq clamav clamav-daemon"
    run "systemctl stop clamav-freshclam 2>/dev/null || true"
    spin "Updating virus definitions" "freshclam || true"
    run "systemctl enable clamav-daemon clamav-freshclam 2>/dev/null || true"
    run "systemctl start clamav-freshclam 2>/dev/null || true"
    run "systemctl start clamav-daemon 2>/dev/null || true"
    ok "ClamAV antivirus"
  fi

  # UFW
  if use_local_profile; then
    info "Skipping UFW in local beta mode — Windows/WSL networking stays local by default"
  else
    command -v ufw &>/dev/null || run "apt-get install -y -qq ufw"
    ok "Firewall (UFW)"
  fi

  ensure_remote_desktop_packages

  # Desktop themes (Greybird + elementary icons)
  local theme_pkgs=(greybird-gtk-theme elementary-xfce-icon-theme numix-gtk-theme gnome-themes-extra)
  local themes_missing=()
  for pkg in "${theme_pkgs[@]}"; do
    if ! dpkg -s "$pkg" &>/dev/null; then
      themes_missing+=("$pkg")
    fi
  done
  if [[ ${#themes_missing[@]} -eq 0 ]]; then
    ok "Desktop themes"
  else
    spin_apt "Installing desktop themes" "${themes_missing[@]}" || true
    ok "Desktop themes"
  fi

  # Google Chrome
  if dpkg -s google-chrome-stable &>/dev/null 2>&1; then
    ok "Google Chrome"
  else
    spin_download "Downloading Google Chrome" "https://dl.google.com/linux/direct/google-chrome-stable_current_amd64.deb" "/tmp/google-chrome.deb"
    spin "Installing Google Chrome" "DEBIAN_FRONTEND=noninteractive apt-get install -y /tmp/google-chrome.deb && rm -f /tmp/google-chrome.deb" || true
    ok "Google Chrome"
  fi
}

# ═══════════════════════════════════════════════════════════════
# Step 3: AI tools
# ═══════════════════════════════════════════════════════════════

install_ai_tools() {
  step_header "Installing AI tools"
  CURRENT_STEP="AI tools"

  # Ollama
  if $SKIP_OLLAMA; then
    info "Skipping Ollama (--skip-ollama)"
  else
    install_or_update_ollama
    ok "Ollama — models will be configured in the setup wizard"
  fi

  # OpenClaw
  if $SKIP_OPENCLAW; then
    info "Skipping OpenClaw (--skip-openclaw)"
  else
    converge_openclaw_core_package
    ok "OpenClaw core ${PIN_OPENCLAW_CORE_PACKAGE_VERSION}"
  fi

  # Portal-native provider CLIs are exact-pinned. A failed replacement restores
  # the previous global npm package rather than leaving a half-updated tool.
  if ! $SKIP_OPENCLAW && command -v npm &>/dev/null; then
    converge_pinned_npm_cli "ClawHub" "clawhub" "${PIN_CLAWHUB_VERSION}" "clawhub" "--cli-version" \
      || warn "ClawHub CLI install failed; Skills marketplace search/install will be unavailable until repaired."
  fi
  converge_pinned_npm_cli "Codex CLI" "@openai/codex" "${PIN_CODEX_CLI_VERSION}" "codex" "--version" \
    || warn "Codex CLI install failed; the native Codex provider will remain unavailable."
  converge_pinned_npm_cli "Claude Code" "@anthropic-ai/claude-code" "${PIN_CLAUDE_CODE_VERSION}" "claude" "--version" \
    || warn "Claude Code install failed; the native Claude provider will remain unavailable."

  # Configure OpenClaw gateway with the portal's operator token
  if ! $SKIP_OPENCLAW && command -v openclaw &>/dev/null; then
    local oc_dir="${HOME}/.openclaw"
    local oc_config="${oc_dir}/openclaw.json"
    mkdir -p "${oc_dir}"

    # Generate a token early if we don't have one yet
    [[ -n "${OPENCLAW_TOKEN}" ]] || OPENCLAW_TOKEN="$(rand_hex 24)"

    if [[ -f "${oc_config}" ]]; then
      # Read existing token if set, otherwise inject ours
      local existing_oc_token
      existing_oc_token="$(python3 -c "
import json
try:
    d = json.load(open('${oc_config}'))
    print(d.get('gateway',{}).get('auth',{}).get('token',''))
except: pass
" 2>/dev/null || true)"
      if [[ -n "${existing_oc_token}" ]]; then
        # Use OpenClaw's existing token for the portal
        OPENCLAW_TOKEN="${existing_oc_token}"
      else
        # Inject our token into OpenClaw's config
        python3 -c "
import json
d = json.load(open('${oc_config}'))
d.setdefault('gateway', {}).setdefault('auth', {})['token'] = '${OPENCLAW_TOKEN}'
d['gateway']['auth']['mode'] = 'token'
d['gateway']['port'] = 18789
json.dump(d, open('${oc_config}', 'w'), indent=2)
" 2>/dev/null || true
      fi
    else
      # Create minimal OpenClaw config with gateway token
      cat > "${oc_config}" << OCEOF
{
  "gateway": {
    "port": 18789,
    "mode": "local",
    "bind": "loopback",
    "auth": {
      "mode": "token",
      "token": "${OPENCLAW_TOKEN}"
    }
  }
}
OCEOF
      chmod 600 "${oc_config}"
    fi
    ok "OpenClaw gateway configured"
  fi
}

install_native_provider_tools() {
  step_header "Installing native provider runtimes"
  CURRENT_STEP="native provider runtimes"

  if converge_antigravity; then
    ok "Antigravity ${PIN_ANTIGRAVITY_VERSION} (verified)"
  else
    warn "Antigravity could not be installed; its Portal provider will remain unavailable."
  fi

  if converge_grok_build; then
    ok "Grok Build ${PIN_GROK_BUILD_VERSION} (verified)"
  else
    warn "Grok Build could not be installed; its Portal provider will remain unavailable."
  fi
}

# ═══════════════════════════════════════════════════════════════
# Step 4: Database
# ═══════════════════════════════════════════════════════════════

setup_database() {
  step_header "Setting up database"
  CURRENT_STEP="database"
  assert_database_process_environment_safe \
    || fail "The installer process environment overrides the attested database runtime. Remove Prisma engine switches, node-postgres PG* fallbacks, NODE_PG_FORCE_NATIVE, and NODE_TLS_REJECT_UNAUTHORIZED before installing."

  # A forced reinstall over an existing Portal must not create/alter the
  # installer's default local database when the Portal is configured for a
  # different PostgreSQL host, port, database, or account. The retained URL is
  # validated and used unchanged later by run_migrations_safe().
  local existing_database_url=""
  if [[ -f "${PORTAL_DIR}/backend/.env.production" ]]; then
    assert_prisma_runtime_environment_safe \
      "${PORTAL_DIR}/backend/.env.production" \
      || fail "The retained backend environment overrides the attested database runtime; repair it before reinstalling."
    existing_database_url="$(read_env_value "${PORTAL_DIR}/backend/.env.production" "DATABASE_URL" || true)"
  fi
  if [[ -n "${existing_database_url}" ]]; then
    pg_url_component "${existing_database_url}" host >/dev/null \
      && pg_url_component "${existing_database_url}" port >/dev/null \
      && pg_url_component "${existing_database_url}" database >/dev/null \
      && pg_url_component "${existing_database_url}" user >/dev/null \
      && pg_url_component "${existing_database_url}" password >/dev/null \
      || fail "Existing DATABASE_URL is invalid; refusing to alter a fallback database during reinstall."
    pg_url_uses_supported_prisma_adapter_options "${existing_database_url}" \
      || fail "Existing DATABASE_URL has an ambiguous or unsupported database-driver option. Remote databases must set sslmode=disable, require, verify-ca, or verify-full. An absolute sslrootcert is required for verify-ca/verify-full; sslcert/client identities/keys, sslaccept, and channel_binding are not supported. Only lowercase application_name, fallback_application_name, options, client_encoding, replication, and documented Prisma pool controls may be supplied; literal plus signs must be percent-encoded. Custom connect_timeout and pool_timeout values must match. Repair the URL before reinstalling."
    info "Preserving the configured PostgreSQL database; local fallback creation is skipped"
    return 0
  fi

  [[ -n "${DB_PASSWORD}" ]] || DB_PASSWORD="$(rand_pass 24)"

  # Create user
  if sudo -u postgres psql -tc "SELECT 1 FROM pg_roles WHERE rolname='blp'" 2>/dev/null | grep -q 1; then
    run "sudo -u postgres psql -c \"ALTER USER blp WITH PASSWORD '${DB_PASSWORD}';\""
  else
    run "sudo -u postgres psql -c \"CREATE USER blp WITH PASSWORD '${DB_PASSWORD}';\""
  fi

  # Create database
  if ! sudo -u postgres psql -tc "SELECT 1 FROM pg_database WHERE datname='bridgesllm_portal'" 2>/dev/null | grep -q 1; then
    run "sudo -u postgres psql -c \"CREATE DATABASE bridgesllm_portal OWNER blp;\""
  fi
  run "sudo -u postgres psql -c \"GRANT ALL PRIVILEGES ON DATABASE bridgesllm_portal TO blp;\""

  ok "Database ready ${DIM}(bridgesllm_portal)${NC}"
}

# ═══════════════════════════════════════════════════════════════
# Step 5: Build portal
# ═══════════════════════════════════════════════════════════════

attest_portal_app_sources_root() {
  local root="$1"
  python3 - "${root}" "${PORTAL_DIR}" "${INSTALL_ROOT}/apps" <<'PY'
import os
import pathlib
import stat
import sys

raw, portal_root_raw, hosted_root_raw = sys.argv[1:]
root = pathlib.Path(raw)
portal_root = pathlib.Path(portal_root_raw)
hosted_root = pathlib.Path(hosted_root_raw)
broad = {
    pathlib.Path(value)
    for value in (
        "/", "/bin", "/boot", "/dev", "/etc", "/home", "/lib",
        "/lib64", "/media", "/mnt", "/opt", "/proc", "/root", "/run",
        "/sbin", "/srv", "/sys", "/tmp", "/usr", "/var",
    )
}
if (
    not raw
    or not root.is_absolute()
    or os.path.normpath(raw) != raw
    or root in broad
    or root == hosted_root
    or hosted_root.is_relative_to(root)
    or len(raw.encode("utf-8")) > 4096
    or any(ord(character) < 32 or ord(character) == 127 for character in raw)
):
    raise SystemExit(1)

current = pathlib.Path("/")
for component in root.parts[1:]:
    current /= component
    try:
        info = os.lstat(current)
    except FileNotFoundError:
        break
    if (
        not stat.S_ISDIR(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or info.st_mode & 0o022
    ):
        raise SystemExit(1)

# A custom explicit root remains supported, but it may not engulf the Portal
# runtime or the hosted deployment root. The two product defaults are exact.
if root != portal_root / "apps" and root != pathlib.Path("/portal/apps"):
    if portal_root == root or portal_root.is_relative_to(root):
        raise SystemExit(1)
print(root)
PY
}

select_portal_app_sources_root() {
  local env_file="$1"
  local previous_version="${2:-}"
  local configured=""
  if [[ -f "${env_file}" && ! -L "${env_file}" ]]; then
    configured="$(read_env_value "${env_file}" PORTAL_APPS_ROOT || true)"
  fi
  if [[ -z "${configured}" ]]; then
    if [[ "${previous_version}" == 3.* ]]; then
      configured="/portal/apps"
    else
      configured="${PORTAL_DIR}/apps"
    fi
  fi
  attest_portal_app_sources_root "${configured}"
}

ensure_portal_app_sources_root() {
  local root="$1"
  if [[ ! -e "${root}" && ! -L "${root}" ]]; then
    install -d -m 0755 -- "${root}" || return 1
  fi
  attest_portal_app_sources_root "${root}" >/dev/null
}

build_portal() {
  step_header "Installing portal"
  CURRENT_STEP="portal build"

  local pre_overlay_portal_version=""
  pre_overlay_portal_version="$(
    attest_existing_portal_for_update "${PORTAL_DIR}" 2>/dev/null || true
  )"

  # Create directories
  mkdir -p "${INSTALL_ROOT}" "${PORTAL_DIR}" "${LOG_DIR}"
  mkdir -p "${INSTALL_ROOT}/apps" "${INSTALL_ROOT}/uploads" "${INSTALL_ROOT}/backups"
  mkdir -p "${INSTALL_ROOT}/assets/avatars" "${INSTALL_ROOT}/assets/branding"
  mkdir -p "${INSTALL_ROOT}/assets/branding"
  mkdir -p "${PORTAL_DIR}/projects" "${PORTAL_DIR}/upload-temp"
  chmod 755 "${PORTAL_DIR}/projects" "${PORTAL_DIR}/upload-temp"

  # Download or copy portal.
  # Only use the local fallback dir as a SOURCE when it is a different path from
  # the install target. RELEASE_FALLBACK_DIR defaults to PORTAL_DIR, so on an
  # existing install this would otherwise rsync the live dir onto itself and
  # silently deploy nothing — prefer the release tarball in that case.
  if [[ "${BRIDGESLLM_ALLOW_UNVERIFIED_LOCAL_SOURCE:-0}" == "1" ]] \
     && [[ -d "${RELEASE_FALLBACK_DIR}" ]] && [[ -f "${RELEASE_FALLBACK_DIR}/backend/package.json" ]] \
     && [[ "$(readlink -f "${RELEASE_FALLBACK_DIR}" 2>/dev/null)" != "$(readlink -f "${PORTAL_DIR}" 2>/dev/null)" ]]; then
    UNVERIFIED_LOCAL_SOURCE_USED=true
    VERIFIED_RELEASE_VERSION=""
    VERIFIED_RELEASE_ARTIFACT_SHA256=""
    VERIFIED_RELEASE_MANIFEST_SHA256=""
    VERIFIED_RELEASE_MANIFEST_SCHEMA=""
    warn "Using explicitly authorized unverified local source; never use this path for a public release."
    spin "Copying portal files from local source" "rsync -a --delete --exclude='node_modules' --exclude='.git' --exclude='.env' --exclude='.env.production' --exclude='/projects' --exclude='/apps' --exclude='/assets' --exclude='/upload-temp' --exclude='/.data' --exclude='/backend/.data' '${RELEASE_FALLBACK_DIR}/' '${PORTAL_DIR}/'"
  else
    local release_stage_dir
    release_stage_dir="$(new_release_stage_dir)"
    if ! stage_verified_release "${release_stage_dir}"; then
      cleanup_release_stage_dir "${release_stage_dir}" || true
      fail "Portal release signature, version, digest, or archive validation failed."
    fi
    # Forced reinstalls converge to the signed payload exactly. Explicit data
    # exclusions retain user state while --delete removes compiled/routes files
    # that no longer exist in the release (a common source of ghost handlers).
    rsync -a --delete \
      --exclude='node_modules' \
      --exclude='.git' \
      --exclude='.env' \
      --exclude='.env.production' \
      --exclude='/projects' \
      --exclude='/apps' \
      --exclude='/assets' \
      --exclude='/upload-temp' \
      --exclude='/.data' \
      --exclude='/backend/.data' \
      "${release_stage_dir}/portal/" "${PORTAL_DIR}/"
    cleanup_release_stage_dir "${release_stage_dir}"
  fi

  install_backend_runtime_dependencies

  ok "Portal files ready"

  local existing_env="${PORTAL_DIR}/backend/.env.production"
  if ${RETAINED_RECONNECT_MODE}; then
    # The signed runtime and exact backend dependency tree now exist, while
    # every retained path is still byte-for-byte identical to the receipt.
    # Retire the receipt at this recoverable boundary: a later interruption is
    # an ordinary attested repair/update, not an ambiguous partial fresh host.
    clear_retained_install_receipt true \
      || fail "The retained Portal data changed while the signed runtime was being reconnected. The reconnect was stopped before configuration or migrations."
    ok "Retained Portal state reconnected to the signed runtime"
  fi
  local existing_database_url=""
  local portal_app_sources_root=""
  if [[ -f "${existing_env}" ]]; then
    info "Preserving existing secrets"
    existing_database_url="$(read_env_value "${existing_env}" "DATABASE_URL" || true)"
    JWT_SECRET="$(read_env_value "${existing_env}" "JWT_SECRET" || true)"
    JWT_REFRESH_SECRET="$(read_env_value "${existing_env}" "JWT_REFRESH_SECRET" || true)"
    PORTAL_UPDATE_PROBE_TOKEN="$(read_env_value "${existing_env}" "PORTAL_UPDATE_PROBE_TOKEN" || true)"
    PROJECT_EGRESS_TOKEN_SECRET="$(read_env_value "${existing_env}" "PROJECT_EGRESS_TOKEN_SECRET" || true)"
    # Only read OPENCLAW_TOKEN from env if not already set by install_ai_tools()
    # (which adopts the token from openclaw.json on fresh installs)
    if [[ -z "${OPENCLAW_TOKEN}" ]]; then
      OPENCLAW_TOKEN="$(read_env_value "${existing_env}" "OPENCLAW_GATEWAY_TOKEN" || true)"
    fi
    SETUP_TOKEN="$(read_env_value "${existing_env}" "SETUP_TOKEN" || true)"
    SETUP_TOKEN_EXPIRES_AT="$(read_env_value "${existing_env}" "SETUP_TOKEN_EXPIRES_AT" || true)"
    SETUP_TOKEN_USED_AT="$(read_env_value "${existing_env}" "SETUP_TOKEN_USED_AT" || true)"
    SETUP_SESSION_TOKEN_HASH="$(read_env_value "${existing_env}" "SETUP_SESSION_TOKEN_HASH" || true)"
    SETUP_SESSION_ORIGIN="$(read_env_value "${existing_env}" "SETUP_SESSION_ORIGIN" || true)"
    SETUP_SESSION_EXPIRES_AT="$(read_env_value "${existing_env}" "SETUP_SESSION_EXPIRES_AT" || true)"
    SETUP_HANDOFF_TOKEN_HASH="$(read_env_value "${existing_env}" "SETUP_HANDOFF_TOKEN_HASH" || true)"
    SETUP_HANDOFF_ORIGIN="$(read_env_value "${existing_env}" "SETUP_HANDOFF_ORIGIN" || true)"
    SETUP_HANDOFF_EXPIRES_AT="$(read_env_value "${existing_env}" "SETUP_HANDOFF_EXPIRES_AT" || true)"
  fi
  portal_app_sources_root="$(
    select_portal_app_sources_root "${existing_env}" "${pre_overlay_portal_version}"
  )" || fail "The standalone uploaded-App source root is unsafe or ambiguous."
  ensure_portal_app_sources_root "${portal_app_sources_root}" \
    || fail "The standalone uploaded-App source root could not be created safely."

  [[ -n "${JWT_SECRET}" ]] || JWT_SECRET="$(rand_hex 32)"
  [[ -n "${JWT_REFRESH_SECRET}" ]] || JWT_REFRESH_SECRET="$(rand_hex 32)"
  [[ -n "${PORTAL_UPDATE_PROBE_TOKEN}" ]] || PORTAL_UPDATE_PROBE_TOKEN="$(rand_hex 32)"
  [[ -n "${OPENCLAW_TOKEN}" ]] || OPENCLAW_TOKEN="$(rand_hex 24)"
  if [[ -n "${PROJECT_EGRESS_TOKEN_SECRET}" ]]; then
    valid_project_egress_token_secret "${PROJECT_EGRESS_TOKEN_SECRET}" \
      || fail "PROJECT_EGRESS_TOKEN_SECRET is malformed; refusing to rotate an active Project credential root automatically."
  else
    PROJECT_EGRESS_TOKEN_SECRET="$(rand_hex 32)"
  fi
  valid_project_egress_token_secret "${PROJECT_EGRESS_TOKEN_SECRET}" \
    || fail "Could not provision a valid independent Project egress credential secret."
  # Mint a bootstrap secret only for genuinely fresh installs. A reinstall over an
  # existing account store (preserved env/DB) must not resurrect the setup
  # wizard: a fresh token there replaces the login page with the
  # password-reset flow for every logged-out visitor.
  local setup_now setup_token_rotated=false
  setup_now="$(date +%s)"
  if [[ -z "${SETUP_TOKEN}" && -z "${existing_database_url}" ]]; then
    SETUP_TOKEN="$(rand_hex 32)"
    SETUP_TOKEN_EXPIRES_AT="$((setup_now + 86400))"
    setup_token_rotated=true
  elif [[ -n "${SETUP_TOKEN}" ]] \
    && { [[ -n "${SETUP_TOKEN_USED_AT}" ]] \
      || [[ ! "${SETUP_TOKEN_EXPIRES_AT}" =~ ^[0-9]+$ ]] \
      || (( SETUP_TOKEN_EXPIRES_AT <= setup_now )); }; then
    # Legacy, expired, or already-consumed bootstrap material is never printed
    # again. An explicit forced installer rerun rotates it and invalidates the
    # prior browser session, yielding one new resumable setup link.
    SETUP_TOKEN="$(rand_hex 32)"
    SETUP_TOKEN_EXPIRES_AT="$((setup_now + 86400))"
    setup_token_rotated=true
  fi
  if ${setup_token_rotated}; then
    SETUP_TOKEN_USED_AT=""
    SETUP_SESSION_TOKEN_HASH=""
    SETUP_SESSION_ORIGIN=""
    SETUP_SESSION_EXPIRES_AT=""
    SETUP_HANDOFF_TOKEN_HASH=""
    SETUP_HANDOFF_ORIGIN=""
    SETUP_HANDOFF_EXPIRES_AT=""
  elif [[ -z "${SETUP_TOKEN}" ]]; then
    SETUP_TOKEN_EXPIRES_AT=""
    SETUP_TOKEN_USED_AT=""
    SETUP_SESSION_TOKEN_HASH=""
    SETUP_SESSION_ORIGIN=""
    SETUP_SESSION_EXPIRES_AT=""
    SETUP_HANDOFF_TOKEN_HASH=""
    SETUP_HANDOFF_ORIGIN=""
    SETUP_HANDOFF_EXPIRES_AT=""
  fi
  ensure_telemetry_install_id

  # Build the DATABASE_URL — PRESERVE existing URL on updates to respect
  # custom port/database name. Only construct a new one for fresh installs.
  local final_database_url=""
  if [[ -n "${existing_database_url}" ]]; then
    final_database_url="${existing_database_url}"
    info "Preserving existing DATABASE_URL ($(echo "${existing_database_url}" | sed 's#://[^:]*:[^@]*@#://***:***@#'))"
  else
    [[ -n "${DB_PASSWORD}" ]] || DB_PASSWORD="$(rand_pass 24)"
    final_database_url="postgresql://blp:${DB_PASSWORD}@127.0.0.1:5432/bridgesllm_portal"
  fi

  # Write .env.production. Recover the served domain first: reinstalls reach
  # this point with an empty $DOMAIN while Caddy still serves the real vhost,
  # and DOMAIN/CORS/PORTAL_URL below must match it.
  recover_domain_from_caddyfile
  configure_app_content_identity
  local cors_origin
  cors_origin="$(portal_cors_origins)"
  local portal_url
  portal_url="$(portal_primary_origin)"
  local portal_public_origin=""
  if use_tailnet_profile && [[ -n "${TAILNET_DNS_NAME}" ]]; then
    portal_public_origin="https://${TAILNET_DNS_NAME}"
  fi

  cat > "${PORTAL_DIR}/backend/.env.production" << ENVEOF
# Generated by BridgesLLM installer v${VERSION} — $(date)
NODE_ENV=production
PORT=4001
# Loopback bind: external access is served by Caddy over HTTPS. Widen only if
# you know you need the portal reachable without the reverse proxy.
HOST=127.0.0.1

DATABASE_URL="${final_database_url}"
JWT_SECRET=${JWT_SECRET}
JWT_REFRESH_SECRET=${JWT_REFRESH_SECRET}
PORTAL_UPDATE_PROBE_TOKEN=${PORTAL_UPDATE_PROBE_TOKEN}

PORTAL_ROOT=${PORTAL_DIR}
PORTAL_APPS_ROOT=${portal_app_sources_root}
PORTAL_APP_ZIPS_ROOT=${PORTAL_DIR}/upload-temp/app-zips
INSTALL_ROOT=${INSTALL_ROOT}
APPS_ROOT=${INSTALL_ROOT}/apps
UPLOAD_DIR=${INSTALL_ROOT}/uploads

CORS_ORIGIN=${cors_origin}
PUBLIC_IP=${PUBLIC_IP}
DOMAIN=${DOMAIN}
PORTAL_URL=${portal_url}
INSTALL_PROFILE=${INSTALL_PROFILE}
ORIGIN_MODE=${ORIGIN_MODE}
TAILNET_DNS_NAME=${TAILNET_DNS_NAME}
PORTAL_PUBLIC_ORIGIN=${portal_public_origin}
APP_CONTENT_DOMAIN=${APP_CONTENT_DOMAIN}
APP_CONTENT_ORIGIN=${APP_CONTENT_ORIGIN}
APP_CONTENT_DNS_MODE=${APP_CONTENT_DNS_MODE}

OPENCLAW_API_URL=http://127.0.0.1:18789
OPENCLAW_GATEWAY_TOKEN=${OPENCLAW_TOKEN}
OPENCLAW_PROJECT_SANDBOX_IMAGE_ID=
CODEX_PROJECT_SANDBOX_IMAGE_ID=
CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID=
ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID=
OLLAMA_PROJECT_SANDBOX_IMAGE_ID=
AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID=
PORTAL_PROJECT_RUNTIME_IMAGE_ID=
PROJECT_RUNTIME_CONFINEMENT_POLICY=

# Installer-attested Project egress plane. The credential root is independent
# from Portal session/JWT secrets; image IDs are populated only after the exact
# runtime recipes and compiled egress artifacts pass verification.
PROJECT_EGRESS_PROXY_IMAGE_ID=
PROJECT_EGRESS_TOKEN_SECRET=${PROJECT_EGRESS_TOKEN_SECRET}

OLLAMA_API_URL=http://127.0.0.1:11434

# One-time setup bootstrap — exchanged only on HTTPS or true loopback and
# cleared after wizard completion. Session/handoff values are hashes, not bearer secrets.
SETUP_TOKEN=${SETUP_TOKEN}
SETUP_TOKEN_EXPIRES_AT=${SETUP_TOKEN_EXPIRES_AT}
SETUP_TOKEN_USED_AT=${SETUP_TOKEN_USED_AT}
SETUP_SESSION_TOKEN_HASH=${SETUP_SESSION_TOKEN_HASH}
SETUP_SESSION_ORIGIN=${SETUP_SESSION_ORIGIN}
SETUP_SESSION_EXPIRES_AT=${SETUP_SESSION_EXPIRES_AT}
SETUP_HANDOFF_TOKEN_HASH=${SETUP_HANDOFF_TOKEN_HASH}
SETUP_HANDOFF_ORIGIN=${SETUP_HANDOFF_ORIGIN}
SETUP_HANDOFF_EXPIRES_AT=${SETUP_HANDOFF_EXPIRES_AT}
TELEMETRY_INSTALL_ID=${TELEMETRY_INSTALL_ID}
ENVEOF
  chmod 600 "${PORTAL_DIR}/backend/.env.production"
  assert_prisma_runtime_environment_safe \
    "${PORTAL_DIR}/backend/.env.production" \
    || fail "The generated backend environment did not preserve the attested database runtime."

  # Create .env symlink so dotenv.config() finds the production env file
  ln -sf .env.production "${PORTAL_DIR}/backend/.env"

  ok "Configuration generated"

  # Frontend env
  printf 'VITE_API_URL=/api\n' > "${PORTAL_DIR}/frontend/.env"

  # Run migrations
  run_migrations_safe "${final_database_url}"

  # Build
  if [[ -f "${PORTAL_DIR}/frontend/dist/index.html" ]] \
    && [[ -f "${PORTAL_DIR}/backend/dist/server.js" ]] \
    && [[ -f "${PORTAL_DIR}/backend/dist/services/projectEgressPolicy.js" ]] \
    && [[ -f "${PORTAL_DIR}/backend/dist/services/projectEgressProxy.js" ]]; then
    ok "Prebuilt artifacts detected — no compilation needed"
  else
    info "Packaged build artifacts missing — building from source"
    spin "Building frontend" "cd '${PORTAL_DIR}/frontend' && npm run build"
    spin "Building backend" "cd '${PORTAL_DIR}/backend' && npm run build"
    ok "Build complete"
  fi
}

# ═══════════════════════════════════════════════════════════════
# Step 6: Configure services
# ═══════════════════════════════════════════════════════════════

configure_services() {
  step_header "Configuring services"
  CURRENT_STEP="service configuration"

  $DRY_RUN && { ok "[dry-run] Would create systemd service + Caddy config"; return; }

  # Systemd service
  cat > /etc/systemd/system/bridgesllm-product.service << SVCEOF
[Unit]
Description=BridgesLLM Portal
After=network.target postgresql.service

[Service]
Type=simple
User=root
WorkingDirectory=${PORTAL_DIR}/backend
EnvironmentFile=${PORTAL_DIR}/backend/.env.production
ExecStart=/usr/bin/node dist/server.js
Restart=always
RestartSec=5
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
SVCEOF

  install_portal_update_boot_fence \
    || fail "Could not install the Portal update boot-safety fence."
  systemctl daemon-reload
  systemctl enable bridgesllm-product >> "$LOG_FILE" 2>&1
  ok "Portal service created"

  # Caddy / direct local access
  if use_local_profile; then
    ok "Direct local access configured ${DIM}(http://localhost:4001)${NC}"
  elif use_tailnet_profile; then
    # Tailscale Serve owns TLS and routing; Caddy stays out of the picture and
    # no public listener exists.
    ok "Tailnet origin configured ${DIM}(https://${TAILNET_DNS_NAME} via Tailscale Serve)${NC}"
  else
    write_caddy_config
    systemctl enable caddy >> "$LOG_FILE" 2>&1
    systemctl is-active --quiet caddy \
      || systemctl start caddy >> "$LOG_FILE" 2>&1 \
      || fail "Caddy could not be started after its configuration was verified."
    ok "Web server configured"
  fi

  # Install both the system-unit fence and the permanent root user-unit
  # inhibitor even when OpenClaw is deliberately skipped. A later package or
  # legacy user unit must never acquire unfenced gateway authority.
  install_openclaw_gateway_authorization_fence_dropin \
    || fail "Could not install the OpenClaw gateway authorization fence."

  # OpenClaw gateway service (if installed)
  if ! $SKIP_OPENCLAW && command -v openclaw &>/dev/null; then
    local oc_bin
    oc_bin="$(which openclaw 2>/dev/null || echo '/usr/bin/openclaw')"
    cat > /etc/systemd/system/openclaw-gateway.service << OCSVCEOF
[Unit]
Description=OpenClaw AI Gateway
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=root
ExecStart=${oc_bin} gateway --port 18789
Restart=always
RestartSec=5
TimeoutStopSec=30
TimeoutStartSec=30
SuccessExitStatus=0 143
KillMode=control-group
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
OCSVCEOF
    systemctl daemon-reload
    systemctl enable openclaw-gateway >> "$LOG_FILE" 2>&1 || true
    ok "OpenClaw gateway service configured"
  fi

  # Firewall
  if use_local_profile; then
    ok "Firewall skipped in local mode"
  elif use_tailnet_profile; then
    # No public web ports at all: Tailscale's WireGuard traffic flows over its
    # own UDP path and the portal is reachable only through the tailnet.
    ufw allow 22/tcp >> "$LOG_FILE" 2>&1
    ufw deny 4001/tcp >> "$LOG_FILE" 2>&1
    ufw --force enable >> "$LOG_FILE" 2>&1 || true
    ok "Firewall configured (no public web ports — tailnet-only access)"
  else
    ufw allow 22/tcp >> "$LOG_FILE" 2>&1
    ufw allow 80/tcp >> "$LOG_FILE" 2>&1
    ufw allow 443/tcp >> "$LOG_FILE" 2>&1
    ufw deny 4001/tcp >> "$LOG_FILE" 2>&1
    ufw --force enable >> "$LOG_FILE" 2>&1 || true
    ok "Firewall configured"
  fi
}

# ═══════════════════════════════════════════════════════════════
# Step 7: Remote Desktop
# ═══════════════════════════════════════════════════════════════

setup_remote_desktop() {
  step_header "Setting up Remote Desktop"
  CURRENT_STEP="remote desktop"

  $DRY_RUN && { ok "[dry-run] Would configure Remote Desktop"; return; }

  ensure_remote_desktop_packages

  local RD_USER="bridgesrd"
  local XDG_DIR="/tmp/bridges-rd-runtime"
  local LOG_RD="/var/log/bridges-rd"

  # Create service user
  if id "$RD_USER" &>/dev/null; then
    ok "User $RD_USER exists"
  else
    useradd -r -m -s /bin/bash "$RD_USER"
    ok "Created user $RD_USER"
  fi

  mkdir -p "$XDG_DIR" "$LOG_RD"
  chown "$RD_USER:$RD_USER" "$XDG_DIR" "$LOG_RD"
  chmod 700 "$XDG_DIR"

  # Deploy the managed XFCE desktop config (Greybird theme, panel layout,
  # keyboard shortcuts, session settings, and related compatibility defaults).
  # Only deploy if this is a fresh install or the config dir doesn't exist yet.
  local xfce_config_dir="/home/$RD_USER/.config/xfce4"
  local xfce_source="${PORTAL_DIR}/installer/xfce4-config"
  if [[ -d "$xfce_source" ]]; then
    mkdir -p "$xfce_config_dir"
    rsync -a "$xfce_source/" "$xfce_config_dir/"
  fi

  chown -R "$RD_USER:$RD_USER" "/home/$RD_USER/.config"
  ok "Desktop environment configured"

  # Web browser launcher (for noVNC URL bar)
  local web_launcher="/usr/local/bin/bridges-rd-web-open.sh"
  cat > "$web_launcher" << 'WEBEOF'
#!/bin/bash
URL="${1:-about:blank}"
if command -v google-chrome-stable &>/dev/null; then
  exec google-chrome-stable --start-maximized "$URL" 2>/dev/null
elif command -v firefox &>/dev/null; then
  exec firefox "$URL" 2>/dev/null
else
  echo "No browser found" >&2
  exit 1
fi
WEBEOF
  chmod 755 "$web_launcher"

  # Branded Remote Desktop launchers/icons. Shared Browser keeps the agent-controlled
  # reset-on-open profile; OpenClaw Web UI gets its own persistent profile so it
  # does not get confused with normal Chrome or the shared browser.
  local shared_browser_launcher="/usr/local/bin/bridges-rd-shared-chrome.sh"
  local openclaw_ui_launcher="/usr/local/bin/bridges-rd-openclaw-ui.sh"
  local ai_provider_launcher="/usr/local/bin/bridges-rd-ai-launchers.sh"
  local shared_browser_src="${PORTAL_DIR}/static/scripts/bridges-rd-shared-chrome.sh"
  local openclaw_ui_src="${PORTAL_DIR}/static/scripts/bridges-rd-openclaw-ui.sh"
  local ai_provider_src="${PORTAL_DIR}/static/scripts/bridges-rd-ai-launchers.sh"
  [[ -f "$shared_browser_src" ]] || fail "Signed Shared Browser launcher is missing"
  [[ -f "$openclaw_ui_src" ]] || fail "Signed OpenClaw UI launcher is missing"
  [[ -f "$ai_provider_src" ]] || fail "Signed AI provider launcher is missing"
  if [[ -f "$shared_browser_src" ]]; then
    install -m 755 "$shared_browser_src" "$shared_browser_launcher"
  fi
  if [[ -f "$openclaw_ui_src" ]]; then
    install -m 755 "$openclaw_ui_src" "$openclaw_ui_launcher"
  fi
  if [[ -f "$ai_provider_src" ]]; then
    install -m 755 "$ai_provider_src" "$ai_provider_launcher"
  fi

  mkdir -p /usr/local/share/pixmaps "/home/$RD_USER/Desktop"
  local shared_browser_icon="/usr/local/share/pixmaps/bridges-shared-browser.svg"
  local openclaw_ui_icon="/usr/local/share/pixmaps/bridges-openclaw-ui.svg"
  [[ -f "${PORTAL_DIR}/static/icons/bridges-shared-browser.svg" ]] && install -m 644 "${PORTAL_DIR}/static/icons/bridges-shared-browser.svg" "$shared_browser_icon"
  [[ -f "${PORTAL_DIR}/static/icons/bridges-openclaw-ui.svg" ]] && install -m 644 "${PORTAL_DIR}/static/icons/bridges-openclaw-ui.svg" "$openclaw_ui_icon"

  local shared_browser_state_dir="/home/$RD_USER/.config/bridges-agent-browser"
  local shared_browser_log_dir="$shared_browser_state_dir/logs"
  local openclaw_ui_profile_dir="/home/$RD_USER/.config/openclaw-control-ui-browser"
  local openclaw_ui_url_file="$openclaw_ui_profile_dir/dashboard-url"
  local openclaw_ui_launch_html="$openclaw_ui_profile_dir/launch.html"
  install -d -o "$RD_USER" -g "$RD_USER" -m 0700 \
    "$shared_browser_state_dir" "$shared_browser_log_dir" "$openclaw_ui_profile_dir"
  OPENCLAW_UI_URL_FILE="$openclaw_ui_url_file" OPENCLAW_UI_LAUNCH_HTML="$openclaw_ui_launch_html" python3 - <<'PY'
import html
import json
import os
from pathlib import Path
from urllib.parse import quote
base = 'http://127.0.0.1:18789/'
token = ''
config = Path('/root/.openclaw/openclaw.json')
try:
    if config.exists():
        token = (json.loads(config.read_text()).get('gateway') or {}).get('auth', {}).get('token') or ''
except Exception:
    token = ''
if not token:
    token_file = Path('/root/.openclaw/gateway.token')
    try:
        if token_file.exists():
            token = token_file.read_text().strip()
    except Exception:
        token = ''
url = base + (('#token=' + quote(token, safe='')) if token else '')
Path(os.environ['OPENCLAW_UI_URL_FILE']).write_text(url + '\n')
Path(os.environ['OPENCLAW_UI_LAUNCH_HTML']).write_text(f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Opening OpenClaw Web UI…</title>
<meta http-equiv="refresh" content="0; url={html.escape(url, quote=True)}" />
<style>:root{{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#070b14;color:#d9f6ff}}body{{min-height:100vh;margin:0;display:grid;place-items:center}}main{{text-align:center;padding:24px}}.mark{{font-size:52px;line-height:1;margin-bottom:14px}}p{{margin:0;opacity:.78}}</style>
</head><body><main><div class="mark">🦞</div><p>Opening OpenClaw Web UI…</p></main>
<script>window.location.replace({json.dumps(url)});</script></body></html>
''')
PY
  chown -R "$RD_USER:$RD_USER" "$openclaw_ui_profile_dir"
  chmod 700 "$shared_browser_state_dir" "$shared_browser_log_dir" "$openclaw_ui_profile_dir"
  chmod 600 "$openclaw_ui_url_file" "$openclaw_ui_launch_html"

  cat > "/home/$RD_USER/Desktop/Shared Chrome.desktop" <<EOF
[Desktop Entry]
Version=1.0
Type=Application
Name=Shared Browser
Comment=Shared browser used by the agent and the user inside Remote Desktop
Exec=$shared_browser_launcher
Icon=$shared_browser_icon
Terminal=false
Categories=Network;WebBrowser;
StartupNotify=true
EOF

  cat > "/home/$RD_USER/Desktop/OpenClaw Web UI.desktop" <<EOF
[Desktop Entry]
Version=1.0
Type=Application
Name=OpenClaw Web UI
Comment=Open native OpenClaw Control UI in a dedicated browser profile
Exec=$openclaw_ui_launcher
Icon=$openclaw_ui_icon
Terminal=false
Categories=Development;Network;WebBrowser;
StartupNotify=true
EOF

  chown -R "$RD_USER:$RD_USER" "/home/$RD_USER/Desktop"
  chmod 755 "/home/$RD_USER/Desktop/Shared Chrome.desktop" "/home/$RD_USER/Desktop/OpenClaw Web UI.desktop"
  runuser -u "$RD_USER" -- bash -lc "command -v gio >/dev/null 2>&1 && gio set '/home/$RD_USER/Desktop/Shared Chrome.desktop' metadata::trusted true || true; command -v gio >/dev/null 2>&1 && gio set '/home/$RD_USER/Desktop/OpenClaw Web UI.desktop' metadata::trusted true || true" || true
  "$ai_provider_launcher" install --assets-dir "${PORTAL_DIR}/static/icons" >> "$LOG_FILE" 2>&1 \
    || fail "AI runtime Remote Desktop launchers could not be provisioned."
  ps -eo pid=,args= | awk '/[O]penClawControlUI/ && /[#]token=/ {print $1}' | xargs -r kill || true
  ok "Remote Desktop browser and AI runtime launchers configured"

  # Install the canonical signed Remote Desktop runtime. A release missing any
  # of these files is invalid; divergent embedded fallbacks are deliberately
  # not maintained.
  local vnc_launcher="/usr/local/bin/bridges-rd-xtigervnc-start.sh"
  local bundled_vnc_launcher="$PORTAL_DIR/installer/scripts/bridges-rd-xtigervnc-start.sh"
  local session_guard="/usr/local/bin/bridges-rd-session-guard.sh"
  local bundled_session_guard="$PORTAL_DIR/installer/scripts/bridges-rd-session-guard.sh"
  local healthcheck="/usr/local/bin/bridges-rd-healthcheck.sh"
  local bundled_healthcheck="$PORTAL_DIR/installer/scripts/bridges-rd-healthcheck.sh"
  local bundled_window_fit="$PORTAL_DIR/installer/scripts/bridges-rd-window-fit.sh"
  if [[ -r "$bundled_window_fit" ]]; then
    install -o root -g root -m 0755 "$bundled_window_fit" /usr/local/bin/bridges-rd-window-fit.sh
  else
    warn "Remote Desktop window-fit helper missing; dynamic desktop resizing will not reposition windows"
  fi
  if [[ -r "$bundled_vnc_launcher" ]]; then
    install -o root -g root -m 0755 "$bundled_vnc_launcher" "$vnc_launcher"
  else
    fail "Canonical Remote Desktop launcher is missing from the signed Portal bundle"
  fi
  if [[ -r "$bundled_session_guard" ]]; then
    install -o root -g root -m 0755 "$bundled_session_guard" "$session_guard"
  else
    fail "Canonical Remote Desktop session guard is missing from the signed Portal bundle"
  fi
  if [[ -r "$bundled_healthcheck" ]]; then
    install -o root -g root -m 0755 "$bundled_healthcheck" "$healthcheck"
  else
    fail "Canonical Remote Desktop healthcheck is missing from the signed Portal bundle"
  fi
  chmod 755 "$vnc_launcher"
  ok "VNC launcher, semantic session guard, and automatic recovery healthcheck written"

  # Systemd units
  cat > /etc/systemd/system/bridges-rd-xtigervnc.service << VNCSVCEOF
[Unit]
Description=Bridges Remote Desktop Xtigervnc :1
After=network.target systemd-tmpfiles-setup.service systemd-user-sessions.service
Before=bridges-rd-websockify.service
Conflicts=tigervncserver@:1.service tigervncserver@1.service vncserver@:1.service vncserver@1.service
RequiresMountsFor=/home/bridgesrd /var/log/bridges-rd
StartLimitIntervalSec=600
StartLimitBurst=3

[Service]
Type=notify
NotifyAccess=main
User=root
ExecStart=${vnc_launcher}
ExecStopPost=-/bin/bash -c 'pkill -f "Xtigervnc :1" 2>/dev/null || true'
Restart=on-failure
RestartSec=3
WatchdogSec=45
TimeoutStartSec=120
TimeoutStopSec=20
KillMode=control-group
Environment=HOME=/root

[Install]
WantedBy=multi-user.target
VNCSVCEOF

  cat > /etc/systemd/system/bridges-rd-websockify.service << WSSVCEOF
[Unit]
Description=Bridges Remote Desktop noVNC Websockify
After=network.target bridges-rd-xtigervnc.service
Requires=bridges-rd-xtigervnc.service

[Service]
Type=simple
User=bridgesrd
Group=bridgesrd
ExecStart=/usr/bin/python3 /usr/bin/websockify 127.0.0.1:6080 127.0.0.1:5901
Restart=always
RestartSec=3
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=full
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
LockPersonality=true
CapabilityBoundingSet=
AmbientCapabilities=
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6

[Install]
WantedBy=multi-user.target
WSSVCEOF

  cat > /etc/systemd/system/bridges-rd-healthcheck.service << HEALTHSVCEOF
[Unit]
Description=Bridges Remote Desktop semantic health recovery
After=bridges-rd-xtigervnc.service bridges-rd-websockify.service

[Service]
Type=oneshot
User=root
ExecStart=${healthcheck}
TimeoutStartSec=150
UMask=0077

HEALTHSVCEOF

  cat > /etc/systemd/system/bridges-rd-healthcheck.timer << 'HEALTHTIMEREOF'
[Unit]
Description=Check and recover Bridges Remote Desktop

[Timer]
OnBootSec=45s
OnUnitActiveSec=30s
AccuracySec=5s
Unit=bridges-rd-healthcheck.service
Persistent=true

[Install]
WantedBy=timers.target
HEALTHTIMEREOF

  systemctl daemon-reload

  # Disable every stock TigerVNC display-1 alias. Ubuntu ships
  # tigervncserver@.service; older images used vncserver@.service. Leaving even
  # one alias enabled creates a cold-boot race for display :1.
  systemctl disable --now \
    tigervncserver@:1.service tigervncserver@1.service \
    vncserver@:1.service vncserver@1.service 2>/dev/null || true
  local stock_vnc_unit stock_vnc_state
  for stock_vnc_unit in \
    tigervncserver@:1.service tigervncserver@1.service \
    vncserver@:1.service vncserver@1.service; do
    if systemctl is-active --quiet "$stock_vnc_unit"; then
      fail "Conflicting stock Remote Desktop unit ${stock_vnc_unit} could not be stopped"
    fi
    systemctl mask "$stock_vnc_unit" >/dev/null 2>&1 \
      || fail "Conflicting stock Remote Desktop unit ${stock_vnc_unit} could not be masked"
    stock_vnc_state="$(systemctl is-enabled "$stock_vnc_unit" 2>/dev/null || true)"
    [[ "$stock_vnc_state" == "masked" ]] \
      || fail "Conflicting stock Remote Desktop unit ${stock_vnc_unit} is not masked"
  done

  # Retire only the complete legacy Bridges rc.local script. Substring edits
  # are unsafe here: they can mutate an administrator-owned boot script and
  # leave the legacy root XFCE/Xvfb cgroup alive. The second exact variant is
  # a Portal-owned variant that commented only its vncserver line; it still
  # launches the obsolete :99 desktop. Unknown or near-match files remain
  # byte-for-byte untouched.
  local rd_legacy_rc_retired
  rd_legacy_rc_retired="$(python3 - <<'PY'
import os
from pathlib import Path

path = Path('/etc/rc.local')
archive = Path('/etc/rc.local.bridgesllm-remote-desktop-legacy')
original = '''#!/bin/bash
# Start XFCE desktop on system boot
export DISPLAY=:99
(/usr/bin/Xvfb :99 -screen 0 1920x1080x24 -ac &)
sleep 3
(DISPLAY=:99 /usr/bin/startxfce4 &)
sleep 3
(DISPLAY=:99 /usr/bin/vncserver :1 -geometry 1920x1080 -depth 24 -fg 2>/dev/null &)
exit 0
'''
interim = '''#!/bin/bash
# Start XFCE desktop on system boot
export DISPLAY=:99
(/usr/bin/Xvfb :99 -screen 0 1920x1080x24 -ac &)
sleep 3
(DISPLAY=:99 /usr/bin/startxfce4 &)
sleep 3
# Display :1 is owned by bridges-rd-xtigervnc.service.  The legacy vncserver
# launch raced the managed Remote Desktop after reboot and could expose an
# unusable greeter instead of the Portal desktop.
# (DISPLAY=:99 /usr/bin/vncserver :1 -geometry 1920x1080 -depth 24 -fg 2>/dev/null &)
exit 0
'''
if not path.exists():
    print('false')
elif path.is_symlink():
    print('false')
else:
    current = path.read_text()
    if current not in {original, interim}:
        print('false')
    else:
        if archive.exists():
            if archive.is_symlink() or archive.read_text() != current:
                raise SystemExit('legacy rc.local archive already exists with different content')
            path.unlink()
        else:
            os.replace(path, archive)
        os.chown(archive, 0, 0)
        os.chmod(archive, 0o600)
        print('true')
PY
)"
  if [[ "$rd_legacy_rc_retired" == "true" ]]; then
    systemctl stop rc-local.service >/dev/null 2>&1 \
      || fail "The retired legacy Remote Desktop rc.local cgroup could not be stopped"
    local rc_local_state
    rc_local_state="$(systemctl show --property=ActiveState --value rc-local.service 2>/dev/null || true)"
    [[ "$rc_local_state" == "inactive" || "$rc_local_state" == "failed" ]] \
      || fail "The retired legacy Remote Desktop rc.local cgroup is still active"
    ok "Retired the exact legacy Remote Desktop rc.local boot stack"
  elif [[ -e /etc/rc.local ]]; then
    warn "Preserved an unrecognized /etc/rc.local; no administrator-owned boot commands were changed"
  fi

  # Disable legacy service name if present
  systemctl disable --now bridges-rd-vnc.service 2>/dev/null || true

  systemctl enable \
    bridges-rd-xtigervnc.service \
    bridges-rd-websockify.service \
    bridges-rd-healthcheck.timer >> "$LOG_FILE" 2>&1 \
    || fail "Remote Desktop services and automatic recovery timer could not be enabled"
  systemctl is-enabled --quiet bridges-rd-healthcheck.timer \
    || fail "Remote Desktop automatic recovery timer is not enabled"
  systemctl restart bridges-rd-xtigervnc.service >> "$LOG_FILE" 2>&1
  sleep 2
  systemctl restart bridges-rd-websockify.service >> "$LOG_FILE" 2>&1
  systemctl restart bridges-rd-healthcheck.timer >> "$LOG_FILE" 2>&1 \
    || fail "Remote Desktop automatic recovery timer could not be started"
  systemctl start bridges-rd-healthcheck.service >> "$LOG_FILE" 2>&1 \
    || fail "Remote Desktop automatic health state could not be initialized"

  local rd_ready=false
  local rd_deadline=$((SECONDS + 20))
  while (( SECONDS < rd_deadline )); do
    if systemctl is-active --quiet bridges-rd-xtigervnc.service \
      && systemctl is-active --quiet bridges-rd-websockify.service \
      && systemctl is-active --quiet bridges-rd-healthcheck.timer \
      && ss -H -ltn 'sport = :5901' | grep -q . \
      && ss -H -ltn 'sport = :6080' | grep -q . \
      && "$session_guard" check >/dev/null 2>&1; then
      rd_ready=true
      break
    fi
    sleep 1
  done
  [[ "$rd_ready" == "true" ]] \
    || fail "Remote Desktop services, semantic session, and automatic recovery timer did not become ready"

  local rd_port
  for rd_port in 5901 6080; do
    if ! ss -H -ltn "sport = :$rd_port" | awk '
      { address=$4; found=1; if (address !~ /^127\.0\.0\.1:/ && address !~ /^\[::1\]:/ && address !~ /^::1:/) bad=1 }
      END { exit (!found || bad) }
    '; then
      fail "Remote Desktop port $rd_port is missing or exposed beyond loopback"
    fi
  done

  local rd_vnc_process
  rd_vnc_process="$(ps -eo args= | grep '[X]tigervnc :1' | head -n 1 || true)"
  if [[ -z "$rd_vnc_process" || "$rd_vnc_process" != *"-localhost=1"* \
    || "$rd_vnc_process" != *"-auth /home/bridgesrd/.Xauthority"* \
    || " $rd_vnc_process " == *" -ac "* ]]; then
    fail "Remote Desktop VNC process failed the loopback/Xauthority policy check"
  fi
  local rd_websockify_process
  rd_websockify_process="$(ps -eo user:64=,args= | awk '$1 == "bridgesrd" && $0 ~ /[w]ebsockify 127.0.0.1:6080 127.0.0.1:5901/ { $1=""; sub(/^ +/, ""); print; exit }' || true)"
  [[ -n "$rd_websockify_process" ]] || fail "Remote Desktop websockify process failed the exact loopback bridge policy check"

  local rd_private_state
  for rd_private_state in \
    "/home/$RD_USER/.config/bridges-agent-browser" \
    "/home/$RD_USER/.config/bridges-agent-browser/logs"; do
    [[ -d "$rd_private_state" && ! -L "$rd_private_state" ]] \
      || fail "Remote Desktop private browser state is missing or linked: $rd_private_state"
    [[ "$(stat -c '%U:%G:%a' "$rd_private_state")" == "$RD_USER:$RD_USER:700" ]] \
      || fail "Remote Desktop private browser state has unsafe ownership or mode: $rd_private_state"
  done

  local rd_managed_marker="/home/$RD_USER/.bridgesllm-portal-managed"
  RD_MANAGED_MARKER="${rd_managed_marker}" python3 - <<'PY'
import os

path = os.environ["RD_MANAGED_MARKER"]
flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
if hasattr(os, "O_NOFOLLOW"):
    flags |= os.O_NOFOLLOW
fd = os.open(path, flags, 0o600)
try:
    os.write(fd, b"managed-by=bridgesllm-portal-remote-desktop-v1\n")
    os.fchmod(fd, 0o600)
    # This marker authorizes clean-slate account deletion. Keep it outside the
    # control of the desktop account it attests.
    os.fchown(fd, 0, 0)
finally:
    os.close(fd)
PY

  ok "Remote Desktop services started and security policy verified"
}

# ═══════════════════════════════════════════════════════════════
# Step 8: Start
# ═══════════════════════════════════════════════════════════════

ensure_openclaw_gateway_boots_cleanly() {
  if ! systemctl is-enabled openclaw-gateway &>/dev/null 2>&1; then
    return 0
  fi

  systemctl start openclaw-gateway >> "$LOG_FILE" 2>&1 || true
  if wait_for_openclaw_gateway_http_ready 60; then
    return 0
  fi

  warn "OpenClaw gateway did not come up cleanly. Clearing stale gateway processes and retrying once."
  systemctl stop openclaw-gateway >> "$LOG_FILE" 2>&1 || true
  pkill -f 'openclaw-gateway|/usr/bin/openclaw gateway|/usr/local/bin/openclaw gateway|openclaw$' >> "$LOG_FILE" 2>&1 || true
  sleep 2
  systemctl start openclaw-gateway >> "$LOG_FILE" 2>&1 || true
  if wait_for_openclaw_gateway_http_ready 60; then
    return 0
  fi

  warn "OpenClaw gateway still did not answer on 127.0.0.1:18789 after retry."
  return 1
}

openclaw_cli_version() {
  command -v openclaw >/dev/null 2>&1 || return 1
  OPENCLAW_ALLOW_ROOT=1 openclaw --version 2>/dev/null | head -1 | grep -oP '\d{4}\.\d+\.\d+' || true
}

openclaw_gateway_version() {
  command -v openclaw >/dev/null 2>&1 || return 1
  OPENCLAW_ALLOW_ROOT=1 openclaw gateway status --deep --json 2>/dev/null | node -e '
let input = "";
process.stdin.on("data", chunk => input += chunk);
process.stdin.on("end", () => {
  try {
    const data = JSON.parse(input);
    const raw = (data.gateway && data.gateway.version) || data.runningVersion || "";
    const match = String(raw).match(/\d{4}\.\d+\.\d+/);
    console.log(match ? match[0] : "");
  } catch (_) {
    console.log("");
  }
});
' 2>/dev/null || true
}

ensure_openclaw_gateway_matches_cli() {
  if $SKIP_OPENCLAW || ! command -v openclaw >/dev/null 2>&1; then
    return 0
  fi
  if ! systemctl is-enabled openclaw-gateway &>/dev/null 2>&1; then
    return 0
  fi

  local cli_version gateway_version
  cli_version="$(openclaw_cli_version)"
  gateway_version="$(openclaw_gateway_version)"

  if [[ -n "${cli_version}" && -n "${gateway_version}" && "${cli_version}" == "${gateway_version}" ]]; then
    if OPENCLAW_ALLOW_ROOT=1 openclaw gateway status --require-rpc --timeout 10000 >> "$LOG_FILE" 2>&1; then
      ok "OpenClaw gateway ${gateway_version} matches CLI"
      return 0
    fi
    warn "OpenClaw gateway version matches, but RPC readiness failed. Restarting once."
  else
    warn "OpenClaw gateway version mismatch detected (CLI: ${cli_version:-unknown}, gateway: ${gateway_version:-unknown}). Restarting gateway."
  fi

  if ! spin "Restarting OpenClaw gateway for version parity" "systemctl restart openclaw-gateway"; then
    warn "OpenClaw gateway restart failed."
    return 1
  fi

  local waited=0
  while (( waited < 60 )); do
    if openclaw_gateway_http_ready; then
      cli_version="$(openclaw_cli_version)"
      gateway_version="$(openclaw_gateway_version)"
      if [[ -n "${cli_version}" && -n "${gateway_version}" && "${cli_version}" == "${gateway_version}" ]] \
        && OPENCLAW_ALLOW_ROOT=1 openclaw gateway status --require-rpc --timeout 10000 >> "$LOG_FILE" 2>&1; then
        ok "OpenClaw gateway ${gateway_version} matches CLI"
        return 0
      fi
    fi
    sleep 3
    waited=$((waited + 3))
  done

  warn "OpenClaw gateway still mismatched after restart (CLI: ${cli_version:-unknown}, gateway: ${gateway_version:-unknown})."
  return 1
}

valid_local_image_tag() {
  local image="${1:-}"
  [[ "${image}" =~ ^[a-z0-9][a-z0-9._/-]*(:[A-Za-z0-9._-]+)?$ ]]
}

valid_docker_image_id() {
  local image_id="${1:-}"
  [[ "${image_id}" =~ ^sha256:[a-f0-9]{64}$ ]]
}

docker_image_label() {
  local image="$1"
  local label="$2"
  docker image inspect --format "{{ index .Config.Labels \"${label}\" }}" "${image}" 2>/dev/null
}

docker_image_id() {
  local image="$1"
  docker image inspect --format '{{.Id}}' "${image}" 2>/dev/null
}

capture_managed_project_egress_inventory() (
  # Capture both discovery authorities. Reserved deterministic names find
  # partially labelled planes; policy labels find managed claimants whose
  # names drifted. Neither inventory is trusted unless both resolve to the
  # same immutable resources and every full identity has the exact topology
  # the backend will attest during Project-provider qualification.
  local all_containers managed_containers all_networks managed_networks
  local row resource_id resource_name extra found snapshot_root
  local container_format network_format
  local -a reserved_proxy_ids=()
  local -a labelled_proxy_ids=()
  local -a reserved_network_ids=()
  local -a labelled_network_ids=()
  local -A seen_resource_ids=()

  report_project_egress_inventory_failure() {
    local reason="$1"
    local source row diagnostic_id diagnostic_name extra separator=""
    local resources="" container_command="" network_command=""
    local -A reported=()
    for source in "${all_containers:-}" "${managed_containers:-}"; do
      while IFS= read -r row; do
        [[ -n "${row}" ]] || continue
        read -r diagnostic_id diagnostic_name extra <<<"${row}"
        [[ -z "${extra:-}" \
          && "${diagnostic_id}" =~ ^[a-f0-9]{64}$ \
          && "${diagnostic_name}" =~ ^[A-Za-z0-9][A-Za-z0-9_.-]*$ \
          && ( "${diagnostic_name}" =~ ^p4e-proxy-[a-f0-9]{20}$ \
            || "${source}" == "${managed_containers:-}" ) ]] || continue
        [[ -z "${reported["container:${diagnostic_id}"]:-}" ]] || continue
        reported["container:${diagnostic_id}"]=1
        resources+="${separator}proxy ${diagnostic_name} (${diagnostic_id})"
        separator=", "
        container_command+=" ${diagnostic_id}"
      done <<<"${source}"
    done
    for source in "${all_networks:-}" "${managed_networks:-}"; do
      while IFS= read -r row; do
        [[ -n "${row}" ]] || continue
        read -r diagnostic_id diagnostic_name extra <<<"${row}"
        [[ -z "${extra:-}" \
          && "${diagnostic_id}" =~ ^[a-f0-9]{64}$ \
          && "${diagnostic_name}" =~ ^[A-Za-z0-9][A-Za-z0-9_.-]*$ \
          && ( "${diagnostic_name}" =~ ^p4e-(in|out)-[a-f0-9]{20}$ \
            || "${source}" == "${managed_networks:-}" ) ]] || continue
        [[ -z "${reported["network:${diagnostic_id}"]:-}" ]] || continue
        reported["network:${diagnostic_id}"]=1
        resources+="${separator}network ${diagnostic_name} (${diagnostic_id})"
        separator=", "
        network_command+=" ${diagnostic_id}"
      done <<<"${source}"
    done
    printf '%s\n' \
      "Managed Project egress inventory validation failed (${reason}) for ${resources:-unresolved reserved resources}." >&2
    if [[ -n "${container_command}" || -n "${network_command}" ]]; then
      printf 'Remediation:' >&2
      [[ -z "${container_command}" ]] \
        || printf ' docker container inspect%s;' "${container_command}" >&2
      [[ -z "${network_command}" ]] \
        || printf ' docker network inspect%s;' "${network_command}" >&2
      printf '%s\n' \
        ' stop attached Project runtimes, then retry the Portal update. Remove only a fully empty parentless network pair.' >&2
    else
      printf '%s\n' \
        'Remediation: docker container ls --all --no-trunc; docker network ls --no-trunc; stop attached Project runtimes, then retry the Portal update.' >&2
    fi
  }

  all_containers="$(docker container ls --all --no-trunc \
    --format '{{.ID}} {{.Names}}' 2>/dev/null | LC_ALL=C sort)" \
    || return 2
  managed_containers="$(docker container ls --all --no-trunc \
    --filter "label=${PROJECT_EGRESS_POLICY_LABEL}=${PROJECT_EGRESS_POLICY_VERSION}" \
    --format '{{.ID}} {{.Names}}' 2>/dev/null | LC_ALL=C sort)" \
    || return 2
  all_networks="$(docker network ls --no-trunc \
    --format '{{.ID}} {{.Name}}' 2>/dev/null | LC_ALL=C sort)" \
    || return 2
  managed_networks="$(docker network ls --no-trunc \
    --filter "label=${PROJECT_EGRESS_POLICY_LABEL}=${PROJECT_EGRESS_POLICY_VERSION}" \
    --format '{{.ID}} {{.Name}}' 2>/dev/null | LC_ALL=C sort)" \
    || return 2

  while IFS= read -r row; do
    [[ -n "${row}" ]] || continue
    read -r resource_id resource_name extra <<<"${row}"
    [[ -z "${extra:-}" && "${resource_id}" =~ ^[a-f0-9]{64}$ ]] || {
      report_project_egress_inventory_failure "invalid container inventory"
      return 3
    }
    [[ -z "${seen_resource_ids["container:${resource_id}"]:-}" ]] \
      || {
        report_project_egress_inventory_failure "duplicate container identity"
        return 3
      }
    seen_resource_ids["container:${resource_id}"]=1
    if [[ "${resource_name}" =~ ^p4e-proxy-[a-f0-9]{20}$ ]]; then
      reserved_proxy_ids+=("${resource_id}")
    fi
  done <<<"${all_containers}"

  while IFS= read -r row; do
    [[ -n "${row}" ]] || continue
    read -r resource_id resource_name extra <<<"${row}"
    [[ -z "${extra:-}" \
      && "${resource_id}" =~ ^[a-f0-9]{64}$ \
      && "${resource_name}" =~ ^p4e-proxy-[a-f0-9]{20}$ ]] \
      || {
        report_project_egress_inventory_failure "managed proxy name or identity drift"
        return 3
      }
    labelled_proxy_ids+=("${resource_id}")
  done <<<"${managed_containers}"

  while IFS= read -r row; do
    [[ -n "${row}" ]] || continue
    read -r resource_id resource_name extra <<<"${row}"
    [[ -z "${extra:-}" && "${resource_id}" =~ ^[a-f0-9]{64}$ ]] || {
      report_project_egress_inventory_failure "invalid network inventory"
      return 3
    }
    [[ -z "${seen_resource_ids["network:${resource_id}"]:-}" ]] \
      || {
        report_project_egress_inventory_failure "duplicate network identity"
        return 3
      }
    seen_resource_ids["network:${resource_id}"]=1
    if [[ "${resource_name}" =~ ^p4e-(in|out)-[a-f0-9]{20}$ ]]; then
      reserved_network_ids+=("${resource_id}")
    fi
  done <<<"${all_networks}"

  while IFS= read -r row; do
    [[ -n "${row}" ]] || continue
    read -r resource_id resource_name extra <<<"${row}"
    [[ -z "${extra:-}" \
      && "${resource_id}" =~ ^[a-f0-9]{64}$ \
      && "${resource_name}" =~ ^p4e-(in|out)-[a-f0-9]{20}$ ]] \
      || {
        report_project_egress_inventory_failure "managed network name or identity drift"
        return 3
      }
    labelled_network_ids+=("${resource_id}")
  done <<<"${managed_networks}"

  [[ "${#reserved_proxy_ids[@]}" -eq "${#labelled_proxy_ids[@]}" \
    && "${#reserved_network_ids[@]}" -eq "${#labelled_network_ids[@]}" ]] \
    || {
      report_project_egress_inventory_failure "reserved names and managed labels disagree"
      return 3
    }
  for resource_id in "${reserved_proxy_ids[@]}"; do
    found=false
    for actual_id in "${labelled_proxy_ids[@]}"; do
      if [[ "${actual_id}" == "${resource_id}" ]]; then
        found=true
        break
      fi
    done
    ${found} || {
      report_project_egress_inventory_failure "reserved proxy lacks exact managed ownership"
      return 3
    }
  done
  for resource_id in "${reserved_network_ids[@]}"; do
    found=false
    for actual_id in "${labelled_network_ids[@]}"; do
      if [[ "${actual_id}" == "${resource_id}" ]]; then
        found=true
        break
      fi
    done
    ${found} || {
      report_project_egress_inventory_failure "reserved network lacks exact managed ownership"
      return 3
    }
  done

  if ((${#reserved_proxy_ids[@]} == 0 \
    && ${#reserved_network_ids[@]} == 0)); then
    return 1
  fi

  snapshot_root="$(mktemp -d)" || return 2
  [[ -n "${snapshot_root}" && -d "${snapshot_root}" ]] || return 2
  chmod 0700 "${snapshot_root}" || return 2
  trap 'rm -rf -- "${snapshot_root}"' EXIT
  mkdir -m 0700 "${snapshot_root}/containers" "${snapshot_root}/networks" \
    || return 2
  printf '%s\n' "${all_containers}" > "${snapshot_root}/container-list"
  printf '%s\n' "${all_networks}" > "${snapshot_root}/network-list"

  # Selected JSON lines deliberately omit environment and mount contents. They
  # capture every identity/topology field needed for a stable comparison
  # without copying Project credentials into the update transaction.
  container_format='{{json .Id}}
{{json .Name}}
{{json .Image}}
{{json .Config.Image}}
{{json .Config.Labels}}
{{json .HostConfig.NetworkMode}}
{{json .NetworkSettings.Networks}}
{{json .State.Running}}'
  network_format='{{json .Id}}
{{json .Name}}
{{json .Driver}}
{{json .Internal}}
{{json .Attachable}}
{{json .Ingress}}
{{json .EnableIPv6}}
{{json .Labels}}
{{json .Options}}
{{json .IPAM}}
{{json .Containers}}'

  while IFS= read -r row; do
    [[ -n "${row}" ]] || continue
    read -r resource_id resource_name extra <<<"${row}"
    [[ -z "${extra:-}" && "${resource_id}" =~ ^[a-f0-9]{64}$ ]] \
      || return 3
    docker container inspect --format "${container_format}" \
      "${resource_id}" > "${snapshot_root}/containers/${resource_id}" 2>/dev/null \
      || return 2
  done <<<"${all_containers}"

  for resource_id in "${reserved_network_ids[@]}"; do
    docker network inspect --format "${network_format}" \
      "${resource_id}" > "${snapshot_root}/networks/${resource_id}" 2>/dev/null \
      || return 2
  done

  node - "${snapshot_root}" \
    "${PROJECT_EGRESS_POLICY_VERSION}" \
    "${PROJECT_EGRESS_POLICY_LABEL}" \
    "${PROJECT_EGRESS_ROLE_LABEL}" \
    "${PROJECT_EGRESS_IDENTITY_LABEL}" \
    "${PROJECT_EGRESS_ACTOR_LABEL}" \
    "${PROJECT_EGRESS_PROJECT_LABEL}" \
    "${PROJECT_EGRESS_PROVIDER_LABEL}" \
    "${PROJECT_EGRESS_CONSUMER_KIND_LABEL}" \
    "${PROJECT_EGRESS_WORKLOAD_LABEL}" \
    "${PROJECT_EGRESS_FINGERPRINT_LABEL}" \
    "${PROJECT_EGRESS_TOKEN_HASH_LABEL}" \
    "${PROJECT_EGRESS_RUNTIME_FINGERPRINT_LABEL}" <<'NODE'
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const inputArgs = process.argv.slice(2);
const diagnosticSnapshotRoot = inputArgs[0];

try {
  const [
    snapshotRoot,
    policyVersion,
    policyLabel,
    roleLabel,
    identityLabel,
    actorLabel,
    projectLabel,
    providerLabel,
    consumerKindLabel,
    workloadLabel,
    fingerprintLabel,
    tokenHashLabel,
    runtimeFingerprintLabel,
  ] = inputArgs;
  const immutableId = /^[a-f0-9]{64}$/;
  const digest = /^[a-f0-9]{64}$/;
  const imageId = /^sha256:[a-f0-9]{64}$/;
  const providers = new Set([
    'OPENCLAW',
    'CLAUDE_CODE',
    'CODEX',
    'AGENT_ZERO',
    'GEMINI',
    'OLLAMA',
    'GROK_BUILD',
    'PORTAL_WORKLOAD',
  ]);
  const workloadKinds = new Set([
    'PORTAL_GIT',
    'PORTAL_LIFECYCLE',
    'PORTAL_APP',
  ]);

  const fail = () => {
    throw new Error('invalid Project egress topology');
  };
  const object = (value) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) fail();
    return value;
  };
  const exactBoolean = (value) => {
    if (typeof value !== 'boolean') fail();
    return value;
  };
  const opaque = (value) => {
    if (typeof value !== 'string'
      || Buffer.byteLength(value, 'utf8') < 1
      || Buffer.byteLength(value, 'utf8') > 512
      || /[\u0000-\u001f\u007f]/.test(value)) fail();
    return value;
  };
  const sha256 = (value) => crypto.createHash('sha256').update(value).digest('hex');
  const jsonStringHash = (value) => sha256(JSON.stringify(value));
  const readJsonLines = (file, count) => {
    const raw = fs.readFileSync(file, 'utf8');
    const lines = raw.endsWith('\n') ? raw.slice(0, -1).split('\n') : raw.split('\n');
    if (lines.length !== count) fail();
    return lines.map((line) => JSON.parse(line));
  };
  const readList = (file) => {
    const raw = fs.readFileSync(file, 'utf8').trim();
    if (!raw) return [];
    return raw.split('\n').map((line) => {
      const fields = line.split(/\s+/);
      if (fields.length !== 2 || !immutableId.test(fields[0]) || !fields[1]) fail();
      return { id: fields[0], name: fields[1] };
    });
  };
  const sameKeys = (value, expected) => {
    const actual = Object.keys(value).sort();
    const wanted = [...expected].sort();
    return JSON.stringify(actual) === JSON.stringify(wanted);
  };
  const canonical = (value) => {
    if (Array.isArray(value)) return value.map(canonical);
    if (value && typeof value === 'object') {
      return Object.fromEntries(
        Object.keys(value).sort().map((key) => [key, canonical(value[key])]),
      );
    }
    return value;
  };

  const containerList = readList(path.join(snapshotRoot, 'container-list'));
  const networkList = readList(path.join(snapshotRoot, 'network-list'));
  if (new Set(containerList.map(({ id }) => id)).size !== containerList.length
    || new Set(networkList.map(({ id }) => id)).size !== networkList.length) fail();

  const containers = new Map();
  for (const listed of containerList) {
    const [
      id,
      inspectedName,
      image,
      configuredImage,
      labelsInput,
      networkMode,
      networksInput,
      running,
    ] = readJsonLines(path.join(snapshotRoot, 'containers', listed.id), 8);
    const name = String(inspectedName || '').replace(/^\//, '');
    if (id !== listed.id || name !== listed.name || typeof networkMode !== 'string') fail();
    containers.set(id, {
      id,
      name,
      image,
      configuredImage,
      labels: object(labelsInput),
      networkMode,
      networks: object(networksInput),
      running: exactBoolean(running),
    });
  }

  const networks = new Map();
  for (const listed of networkList) {
    if (!/^p4e-(?:in|out)-[a-f0-9]{20}$/.test(listed.name)) continue;
    const [
      id,
      name,
      driver,
      internal,
      attachable,
      ingress,
      enableIPv6,
      labelsInput,
      optionsInput,
      ipamInput,
      membersInput,
    ] = readJsonLines(path.join(snapshotRoot, 'networks', listed.id), 11);
    if (id !== listed.id || name !== listed.name || driver !== 'bridge'
      || attachable !== false || ingress !== false
      || typeof enableIPv6 !== 'boolean') fail();
    const options = optionsInput === null ? null : object(optionsInput);
    const ipam = object(ipamInput);
    if (typeof ipam.Driver !== 'string'
      || (ipam.Options !== null && ipam.Options !== undefined
        && (typeof ipam.Options !== 'object' || Array.isArray(ipam.Options)))
      || !Array.isArray(ipam.Config)
      || ipam.Config.length < 1) fail();
    const ipamConfig = ipam.Config.find(
      (entry) => entry
        && typeof entry === 'object'
        && !Array.isArray(entry)
        && String(entry.Subnet || '').includes('.'),
    );
    if (!ipamConfig) fail();
    const subnetMatch = String(ipamConfig.Subnet || '').match(
      /^((?:\d{1,3}\.){3}\d{1,3})\/(\d{1,2})$/,
    );
    const gatewayValue = String(ipamConfig.Gateway || '');
    const baseValue = gatewayValue || (subnetMatch ? subnetMatch[1] : '');
    const gatewayMatch = gatewayValue
      ? gatewayValue.match(/^((?:\d{1,3}\.){3}\d{1,3})$/)
      : null;
    if (!subnetMatch || Number.parseInt(subnetMatch[2], 10) < 1
      || Number.parseInt(subnetMatch[2], 10) > 32) fail();
    const octets = (value) => value.split('.').map((part) => Number.parseInt(part, 10));
    const subnetOctets = octets(subnetMatch[1]);
    const baseOctets = octets(baseValue);
    if ((gatewayValue && !gatewayMatch)
      || [...subnetOctets, ...baseOctets].some(
        (part) => !Number.isInteger(part) || part < 0 || part > 255,
      )
      || baseOctets.length !== 4
      || baseOctets[3] + (gatewayValue ? 1 : 2) > 255) fail();
    const staticProxyOctets = [...baseOctets];
    staticProxyOctets[3] += gatewayValue ? 1 : 2;
    networks.set(id, {
      id,
      name,
      driver,
      internal: exactBoolean(internal),
      attachable,
      ingress,
      enableIPv6,
      labels: object(labelsInput),
      options,
      ipam,
      subnet: subnetMatch[0],
      staticProxyIpv4: staticProxyOctets.join('.'),
      members: membersInput === null ? {} : object(membersInput),
    });
  }

  const identityFromLabels = (labels, expectedRole) => {
    if (labels[policyLabel] !== policyVersion || labels[roleLabel] !== expectedRole) fail();
    const actorId = opaque(labels[actorLabel]);
    const projectId = opaque(labels[projectLabel]);
    const provider = opaque(labels[providerLabel]);
    if (!providers.has(provider)) fail();
    const identity = { actorId, projectId, provider };
    if (provider === 'PORTAL_WORKLOAD') {
      const consumerKind = opaque(labels[consumerKindLabel]);
      const workloadId = opaque(labels[workloadLabel]);
      if (!workloadKinds.has(consumerKind)) fail();
      identity.consumerKind = consumerKind;
      identity.workloadId = workloadId;
    } else if (labels[consumerKindLabel] !== undefined
      || labels[workloadLabel] !== undefined) fail();
    const identityFingerprint = jsonStringHash(identity);
    if (labels[identityLabel] !== identityFingerprint
      || !digest.test(String(labels[fingerprintLabel] || ''))) fail();
    return {
      ...identity,
      identityFingerprint,
      policyFingerprint: labels[fingerprintLabel],
    };
  };

  const planes = new Map();
  const addPlaneResource = (identity, key, resource) => {
    let plane = planes.get(identity.identityFingerprint);
    if (!plane) {
      plane = { identity, proxy: null, internal: null, publicNetwork: null };
      planes.set(identity.identityFingerprint, plane);
    } else if (JSON.stringify(plane.identity) !== JSON.stringify(identity)) fail();
    if (plane[key]) fail();
    plane[key] = resource;
  };

  for (const container of containers.values()) {
    if (!/^p4e-proxy-[a-f0-9]{20}$/.test(container.name)) continue;
    const identity = identityFromLabels(container.labels, 'proxy');
    const expectedName = `p4e-proxy-${identity.identityFingerprint.slice(0, 20)}`;
    if (container.name !== expectedName
      || !imageId.test(String(container.image || ''))
      || container.configuredImage !== container.image
      || !digest.test(String(container.labels[tokenHashLabel] || ''))) fail();
    addPlaneResource(identity, 'proxy', container);
  }
  for (const network of networks.values()) {
    const role = network.name.startsWith('p4e-in-') ? 'internal' : 'proxy-public';
    const identity = identityFromLabels(network.labels, role);
    const expectedName = `p4e-${role === 'internal' ? 'in' : 'out'}-${identity.identityFingerprint.slice(0, 20)}`;
    if (network.name !== expectedName || network.internal !== (role === 'internal')) fail();
    addPlaneResource(
      identity,
      role === 'internal' ? 'internal' : 'publicNetwork',
      network,
    );
  }

  const runtimeIdentityMatches = (runtime, plane) => {
    const labels = runtime.labels;
    const fingerprint = String(labels[runtimeFingerprintLabel] || '');
    if (!digest.test(fingerprint)) return false;
    const actor = plane.identity.actorId;
    const project = plane.identity.projectId;
    switch (plane.identity.provider) {
      case 'OPENCLAW':
        return runtime.name.startsWith('p4oc-')
          && labels['openclaw.sandbox'] === '1'
          && labels['com.bridgesllm.openclaw-project.actor'] === sha256(actor)
          && labels['com.bridgesllm.openclaw-project.identity'] === sha256(project);
      case 'CODEX':
        return runtime.name === `p4cx-${fingerprint.slice(0, 24)}`
          && ['portal-project-sandbox-v3', 'portal-project-sandbox-v2'].includes(
            labels['com.bridgesllm.codex-project.policy'],
          )
          && labels['com.bridgesllm.codex-project.actor'] === jsonStringHash(actor)
          && labels['com.bridgesllm.codex-project.project'] === jsonStringHash(project)
          && labels['com.bridgesllm.codex-project.egress'] === plane.identity.policyFingerprint;
      case 'CLAUDE_CODE':
      case 'GEMINI': {
        const prefix = plane.identity.provider === 'CLAUDE_CODE' ? 'p4cc' : 'p4ag';
        return runtime.name === `${prefix}-${fingerprint.slice(0, 24)}`
          && labels['com.bridgesllm.native-cli-project.policy']
            === (plane.identity.provider === 'CLAUDE_CODE'
              ? 'portal-claude-code-project-sandbox-v1'
              : 'portal-antigravity-project-sandbox-v1')
          && labels['com.bridgesllm.native-cli-project.provider'] === plane.identity.provider
          && labels['com.bridgesllm.native-cli-project.actor'] === jsonStringHash(actor)
          && labels['com.bridgesllm.native-cli-project.project'] === jsonStringHash(project)
          && labels['com.bridgesllm.native-cli-project.egress'] === plane.identity.policyFingerprint;
      }
      case 'AGENT_ZERO': {
        const key = String(labels['io.bridgesllm.project-key'] || '');
        return digest.test(key)
          && runtime.name === `bridgesllm-a0p-${key.slice(0, 24)}`
          && labels['io.bridgesllm.managed'] === 'agent-zero-project'
          && labels['io.bridgesllm.runtime'] === 'agent-zero-project-sandbox-v4'
          && labels['io.bridgesllm.policy'] === 'agent-zero-project-isolation-v4'
          && labels['io.bridgesllm.project-id'] === project
          && labels['io.bridgesllm.actor-id'] === actor;
      }
      case 'PORTAL_WORKLOAD': {
        const kind = plane.identity.consumerKind;
        const workload = plane.identity.workloadId;
        const prefix = kind === 'PORTAL_GIT'
          ? 'bridgesllm-project-git'
          : kind === 'PORTAL_APP'
            ? 'bridgesllm-project-app'
            : 'bridgesllm-project-job';
        const discriminator = kind === 'PORTAL_GIT'
          ? `${actor}\0${project}\0${workload}`
          : `${actor}\0${project}\0${kind === 'PORTAL_APP' ? 'app' : 'job'}\0${workload}`;
        return runtime.name === `${prefix}-${sha256(discriminator).slice(0, 20)}`
          && labels['com.bridgesllm.project-workload.policy']
            === 'portal-project-workload-v1'
          && labels['com.bridgesllm.project-workload.actor-id'] === actor
          && labels['com.bridgesllm.project-workload.project-id'] === project
          && labels['com.bridgesllm.project-workload.kind'] === kind
          && labels['com.bridgesllm.project-workload.workload-id'] === workload;
      }
      // Ollama's Project tool container is intentionally --network none, and
      // GROK_BUILD has no current managed Project container runtime. Either
      // provider may own a proxy plane, but neither may contribute an internal
      // network member.
      case 'OLLAMA':
      case 'GROK_BUILD':
        return false;
      default:
        return false;
    }
  };

  const topologyRecords = [];
  for (const plane of planes.values()) {
    const { identity, proxy, internal, publicNetwork } = plane;
    if (!proxy) {
      if (!internal || !publicNetwork
        || identity.policyFingerprint !== internal.labels[fingerprintLabel]
        || identity.policyFingerprint !== publicNetwork.labels[fingerprintLabel]) fail();
      const referenced = (network) => [...containers.values()].some((container) => (
        Object.prototype.hasOwnProperty.call(container.networks, network.name)
        || [network.id, network.name].includes(container.networkMode.toLowerCase())
      ));
      if (Object.keys(internal.members).length !== 0
        || Object.keys(publicNetwork.members).length !== 0
        || referenced(internal)
        || referenced(publicNetwork)) fail();
      const orphanTopology = canonical({ identity, internal, publicNetwork });
      topologyRecords.push(
        `orphan-network|${internal.id}|${internal.name}|internal`,
        `orphan-network|${publicNetwork.id}|${publicNetwork.name}|proxy-public`,
        `orphan-plane|${identity.identityFingerprint}|${sha256(JSON.stringify(orphanTopology))}|`,
      );
      continue;
    }
    if (!internal || !publicNetwork
      || identity.policyFingerprint !== internal.labels[fingerprintLabel]
      || identity.policyFingerprint !== publicNetwork.labels[fingerprintLabel]) fail();

    const expectedNetworkNames = [internal.name, publicNetwork.name].sort();
    if (!sameKeys(proxy.networks, expectedNetworkNames)
      || ![publicNetwork.id, publicNetwork.name].includes(
        proxy.networkMode.toLowerCase(),
      )) fail();
    const internalAttachment = object(proxy.networks[internal.name]);
    const publicAttachment = object(proxy.networks[publicNetwork.name]);
    const reportedInternalId = String(internalAttachment.NetworkID || '').toLowerCase();
    const reportedPublicId = String(publicAttachment.NetworkID || '').toLowerCase();
    const stoppedUnmaterialized = proxy.running === false
      && proxy.networkMode.toLowerCase() === publicNetwork.id;
    if ((reportedInternalId !== internal.id
        && !(stoppedUnmaterialized && reportedInternalId === ''))
      || (reportedPublicId !== publicNetwork.id
        && !(stoppedUnmaterialized && reportedPublicId === ''))
      || !Array.isArray(internalAttachment.Aliases)
      || !internalAttachment.Aliases.includes('portal-project-egress')) fail();
    const staticPublicIpv4 = String(publicAttachment.IPAMConfig?.IPv4Address || '');
    if (staticPublicIpv4 !== publicNetwork.staticProxyIpv4) fail();

    const reversePublic = [];
    const reverseInternal = [];
    for (const container of containers.values()) {
      if (Object.prototype.hasOwnProperty.call(container.networks, publicNetwork.name)) {
        reversePublic.push(container);
      }
      if (Object.prototype.hasOwnProperty.call(container.networks, internal.name)) {
        reverseInternal.push(container);
      }
    }
    if (reversePublic.length !== 1 || reversePublic[0].id !== proxy.id) fail();
    const runtimeCandidates = reverseInternal.filter(({ id }) => id !== proxy.id);
    if (!reverseInternal.some(({ id }) => id === proxy.id)
      || runtimeCandidates.length > 1) fail();
    const runtime = runtimeCandidates[0] || null;
    if (runtime) {
      if (!runtimeIdentityMatches(runtime, plane)
        || !sameKeys(runtime.networks, [internal.name])
        || runtime.networkMode === 'host') fail();
      const attachmentId = String(runtime.networks[internal.name]?.NetworkID || '').toLowerCase();
      if (attachmentId !== internal.id
        && !(attachmentId === ''
          && runtime.running === false
          && ['none', internal.id].includes(runtime.networkMode.toLowerCase()))) fail();
    }

    const attestMembership = (network, expectedRunning) => {
      const entries = Object.entries(network.members);
      if (entries.some(([id, member]) => !immutableId.test(id)
        || !containers.has(id)
        || containers.get(id).name !== member?.Name)) fail();
      const actual = entries.map(([id]) => id).sort();
      const expected = expectedRunning.map(({ id }) => id).sort();
      if (JSON.stringify(actual) !== JSON.stringify(expected)) fail();
    };
    attestMembership(
      publicNetwork,
      proxy.running ? [proxy] : [],
    );
    attestMembership(
      internal,
      [proxy, runtime].filter((candidate) => candidate?.running),
    );

    // A proxy that never started (or exited before Docker materialized its
    // endpoints) can leave the exact managed container and its empty network
    // pair behind. Treat only that fully detached, stopped shape as reclaimable
    // debris. A running proxy, any runtime peer, or any network-side member
    // remains an authoritative topology failure.
    const exitedDetachedProxy = proxy.running === false
      && runtime === null
      && Object.keys(internal.members).length === 0
      && Object.keys(publicNetwork.members).length === 0;
    const exitedDetachedProxyDebris = exitedDetachedProxy
      && reportedInternalId === ''
      && reportedPublicId === ''
      && String(internalAttachment.EndpointID || '') === ''
      && String(publicAttachment.EndpointID || '') === ''
      && String(internalAttachment.IPAddress || '') === ''
      && String(publicAttachment.IPAddress || '') === ''
      && String(internalAttachment.GlobalIPv6Address || '') === ''
      && String(publicAttachment.GlobalIPv6Address || '') === ''
      && String(internalAttachment.IPAMConfig?.IPv6Address || '') === ''
      && String(publicAttachment.IPAMConfig?.IPv6Address || '') === '';
    if (exitedDetachedProxyDebris) {
      const orphanTopology = canonical({
        identity,
        proxy: {
          id: proxy.id,
          name: proxy.name,
          image: proxy.image,
          configuredImage: proxy.configuredImage,
          labels: proxy.labels,
          networkMode: proxy.networkMode,
          networks: proxy.networks,
          running: proxy.running,
        },
        internal,
        publicNetwork,
        runtime: null,
      });
      topologyRecords.push(
        `orphan-container|${proxy.id}|/${proxy.name}|${proxy.image}`,
        `orphan-network|${internal.id}|${internal.name}|internal`,
        `orphan-network|${publicNetwork.id}|${publicNetwork.name}|proxy-public`,
        `orphan-plane|${identity.identityFingerprint}|${sha256(JSON.stringify(orphanTopology))}|`,
      );
      continue;
    }
    if (exitedDetachedProxy) fail();

    const topology = canonical({
      identity,
      proxy: {
        id: proxy.id,
        name: proxy.name,
        image: proxy.image,
        configuredImage: proxy.configuredImage,
        labels: proxy.labels,
        networkMode: proxy.networkMode,
        networks: proxy.networks,
        running: proxy.running,
      },
      internal,
      publicNetwork,
      runtime: runtime ? {
        id: runtime.id,
        name: runtime.name,
        labels: runtime.labels,
        networkMode: runtime.networkMode,
        networks: runtime.networks,
        running: runtime.running,
      } : null,
    });
    topologyRecords.push(
      `container|${proxy.id}|/${proxy.name}|${proxy.image}`,
      `network|${internal.id}|${internal.name}|internal`,
      `network|${publicNetwork.id}|${publicNetwork.name}|proxy-public`,
      `topology|${identity.identityFingerprint}|${sha256(JSON.stringify(topology))}`,
    );
  }
  if (planes.size === 0) fail();
  process.stdout.write(`${topologyRecords.sort().join('\n')}\n`);
} catch {
  const resources = [];
  const containerIds = [];
  const networkIds = [];
  try {
    for (const [kind, file, namePattern] of [
      ['proxy', 'container-list', /^p4e-proxy-[a-f0-9]{20}$/],
      ['network', 'network-list', /^p4e-(?:in|out)-[a-f0-9]{20}$/],
    ]) {
      const raw = fs.readFileSync(path.join(diagnosticSnapshotRoot, file), 'utf8').trim();
      if (!raw) continue;
      for (const line of raw.split('\n')) {
        const fields = line.split(/\s+/);
        if (fields.length === 2
          && /^[a-f0-9]{64}$/.test(fields[0])
          && namePattern.test(fields[1])) {
          resources.push(`${kind} ${fields[1]} (${fields[0]})`);
          (kind === 'proxy' ? containerIds : networkIds).push(fields[0]);
        }
      }
    }
  } catch {
    // Keep the primary validation failure authoritative when diagnostics race.
  }
  console.error(
    `Managed Project egress inventory validation failed for ${resources.join(', ') || 'unresolved reserved resources'}. `
      + `Remediation: ${containerIds.length ? `docker container inspect ${containerIds.join(' ')}; ` : ''}`
      + `${networkIds.length ? `docker network inspect ${networkIds.join(' ')}; ` : ''}`
      + 'stop attached Project runtimes, then retry the Portal update. Remove only a fully empty parentless network pair.',
  );
  process.exit(3);
}
NODE
)

discover_unique_managed_project_egress_proxy_image_id() {
  # Two complete immutable snapshots make image selection a CAS boundary.
  # Any create/remove/relabel between them is a race, not a generation the
  # updater may guess through.
  local first_inventory="" second_inventory="" barrier_inventory="" removal_inventory=""
  local first_status=0 second_status=0 barrier_status=0 removal_status=0
  local row kind resource_id name detail selected_image_id="" index
  local cleanup_attempted=false resource_summary="" separator=""
  local -a orphan_container_ids=()
  local -a orphan_container_names=()
  local -a orphan_network_ids=()
  local -a orphan_network_names=()

  while true; do
    first_inventory=""
    second_inventory=""
    selected_image_id=""
    orphan_container_ids=()
    orphan_container_names=()
    orphan_network_ids=()
    orphan_network_names=()
    if first_inventory="$(capture_managed_project_egress_inventory)"; then
      first_status=0
    else
      first_status=$?
    fi
    if second_inventory="$(capture_managed_project_egress_inventory)"; then
      second_status=0
    else
      second_status=$?
    fi
    if [[ "${first_status}" != "${second_status}" \
      || "${first_inventory}" != "${second_inventory}" ]]; then
      return 5
    fi
    case "${first_status}" in
      0) ;;
      1|2|3) return "${first_status}" ;;
      *) return 5 ;;
    esac

    while IFS='|' read -r kind resource_id name detail; do
      case "${kind}" in
        container)
          [[ "${resource_id}" =~ ^[a-f0-9]{64}$ \
            && "${name}" =~ ^/p4e-proxy-[a-f0-9]{20}$ ]] \
            || return 3
          valid_docker_image_id "${detail}" || return 3
          if [[ -n "${selected_image_id}" \
            && "${selected_image_id}" != "${detail}" ]]; then
            return 4
          fi
          selected_image_id="${detail}"
          ;;
        network)
          [[ "${resource_id}" =~ ^[a-f0-9]{64}$ \
            && "${name}" =~ ^p4e-(in|out)-[a-f0-9]{20}$ \
            && ( "${detail}" == "internal" || "${detail}" == "proxy-public" ) ]] \
            || return 3
          ;;
        topology|orphan-plane)
          [[ "${resource_id}" =~ ^[a-f0-9]{64}$ \
            && "${name}" =~ ^[a-f0-9]{64}$ \
            && -z "${detail}" ]] \
            || return 3
          ;;
        orphan-network)
          [[ "${resource_id}" =~ ^[a-f0-9]{64}$ \
            && "${name}" =~ ^p4e-(in|out)-[a-f0-9]{20}$ \
            && ( "${detail}" == "internal" || "${detail}" == "proxy-public" ) ]] \
            || return 3
          orphan_network_ids+=("${resource_id}")
          orphan_network_names+=("${name}")
          ;;
        orphan-container)
          [[ "${resource_id}" =~ ^[a-f0-9]{64}$ \
            && "${name}" =~ ^/p4e-proxy-[a-f0-9]{20}$ ]] \
            || return 3
          valid_docker_image_id "${detail}" || return 3
          orphan_container_ids+=("${resource_id}")
          orphan_container_names+=("${name#/}")
          ;;
        *) return 3 ;;
      esac
    done <<<"${first_inventory}"

    if ((${#orphan_network_ids[@]} > 0)); then
      if ${cleanup_attempted} || ((${#orphan_network_ids[@]} % 2 != 0)); then
        return 5
      fi
      barrier_inventory=""
      if barrier_inventory="$(capture_managed_project_egress_inventory)"; then
        barrier_status=0
      else
        barrier_status=$?
      fi
      if [[ "${barrier_status}" != "0" \
        || "${barrier_inventory}" != "${first_inventory}" ]]; then
        return 5
      fi
      # One final complete discovery immediately before the first exact-ID
      # removal closes the gap between the cleanup barrier and mutation. A
      # stopped proxy that is reattached or otherwise changes remains intact.
      removal_inventory=""
      if removal_inventory="$(capture_managed_project_egress_inventory)"; then
        removal_status=0
      else
        removal_status=$?
      fi
      if [[ "${removal_status}" != "0" \
        || "${removal_inventory}" != "${first_inventory}" ]]; then
        return 5
      fi
      resource_summary=""
      separator=""
      for ((index = 0; index < ${#orphan_container_ids[@]}; index++)); do
        resource_summary+="${separator}${orphan_container_names[index]} (${orphan_container_ids[index]})"
        separator=", "
      done
      for ((index = 0; index < ${#orphan_network_ids[@]}; index++)); do
        resource_summary+="${separator}${orphan_network_names[index]} (${orphan_network_ids[index]})"
        separator=", "
      done
      printf '%s\n' \
        "Reclaiming exact stopped, detached Project egress debris: ${resource_summary}." >&2
      for ((index = 0; index < ${#orphan_container_ids[@]}; index++)); do
        if ! docker container rm "${orphan_container_ids[index]}" \
          >> "${LOG_FILE}" 2>&1; then
          printf '%s\n' \
            "Could not reclaim Project egress debris ${resource_summary}. Remediation: docker container inspect ${orphan_container_ids[*]}; docker network inspect ${orphan_network_ids[*]}; verify the proxy is stopped and every network endpoint is gone, then retry the Portal update." >&2
          return 3
        fi
        if docker container inspect "${orphan_container_ids[index]}" \
          >/dev/null 2>&1; then
          printf '%s\n' \
            "Project egress proxy ${orphan_container_names[index]} (${orphan_container_ids[index]}) remained after exact removal. Remediation: docker container inspect ${orphan_container_ids[index]}; retry only after the proxy is stopped and detached." >&2
          return 3
        fi
      done
      for ((index = 0; index < ${#orphan_network_ids[@]}; index++)); do
        if ! docker network rm "${orphan_network_ids[index]}" \
          >> "${LOG_FILE}" 2>&1; then
          printf '%s\n' \
            "Could not reclaim Project egress debris ${resource_summary}. Remediation: docker network inspect ${orphan_network_ids[*]}; stop attached Project runtimes, then retry the Portal update. Do not remove a network that still has endpoints." >&2
          return 3
        fi
        if docker network inspect "${orphan_network_ids[index]}" \
          >/dev/null 2>&1; then
          printf '%s\n' \
            "Project egress network ${orphan_network_names[index]} (${orphan_network_ids[index]}) remained after exact removal. Remediation: docker network inspect ${orphan_network_ids[index]}; retry the Portal update after all endpoints are gone." >&2
          return 3
        fi
      done
      cleanup_attempted=true
      continue
    fi

    valid_docker_image_id "${selected_image_id}" || return 3
    printf '%s\n' "${selected_image_id}"
    return 0
  done
}

install_project_runtime_confinement_file() {
  local source_file="$1"
  local target_file="$2"
  local expected_sha256="$3"
  local install_mode="${4:-replace}"
  local target_dir temporary
  [[ "${install_mode}" == "replace" || "${install_mode}" == "additive" ]] \
    || fail "Project runtime confinement install mode is invalid."
  [[ -f "${source_file}" && ! -L "${source_file}" ]] \
    || fail "Project runtime confinement source ${source_file} is missing or unsafe."
  [[ "$(stat -c '%u:%g' "${source_file}")" == "0:0" ]] \
    || fail "Project runtime confinement source ${source_file} is not root-owned."
  (( (8#$(stat -c '%a' "${source_file}") & 0022) == 0 )) \
    || fail "Project runtime confinement source ${source_file} is writable by an unsafe principal."
  [[ "$(sha256sum "${source_file}" | awk '{print $1}')" == "${expected_sha256}" ]] \
    || fail "Project runtime confinement source ${source_file} failed its release digest."

  target_dir="$(dirname "${target_file}")"
  if [[ ! -e "${target_dir}" ]]; then
    install -d -o root -g root -m 0755 "${target_dir}" \
      || fail "Could not create the Project runtime confinement directory ${target_dir}."
  fi
  [[ -d "${target_dir}" && ! -L "${target_dir}" \
    && "$(stat -c '%u:%g' "${target_dir}")" == "0:0" \
    && $((8#$(stat -c '%a' "${target_dir}") & 0022)) -eq 0 ]] \
    || fail "Project runtime confinement directory ${target_dir} has unsafe metadata."
  if [[ "${install_mode}" == "additive" \
    && ( -e "${target_file}" || -L "${target_file}" ) ]]; then
    [[ -f "${target_file}" && ! -L "${target_file}" \
      && "$(stat -c '%u:%g:%a:%h' "${target_file}")" == "0:0:644:1" \
      && "$(sha256sum "${target_file}" | awk '{print $1}')" == "${expected_sha256}" ]] \
      || fail "An update cannot replace confinement policy ${target_file} before cutover. Publish changed policy under a new versioned path and profile name."
    return 0
  fi
  temporary="$(mktemp "${target_dir}/.bridgesllm-project-runtime.XXXXXX")"
  install -o root -g root -m 0644 "${source_file}" "${temporary}" || {
    rm -f -- "${temporary}"
    fail "Could not stage Project runtime confinement profile ${target_file}."
  }
  [[ "$(sha256sum "${temporary}" | awk '{print $1}')" == "${expected_sha256}" ]] || {
    rm -f -- "${temporary}"
    fail "Staged Project runtime confinement profile ${target_file} changed unexpectedly."
  }
  mv -f -- "${temporary}" "${target_file}" \
    || fail "Could not atomically install Project runtime confinement profile ${target_file}."
  chown root:root "${target_file}"
  chmod 0644 "${target_file}"
  [[ -f "${target_file}" && ! -L "${target_file}" \
    && "$(stat -c '%u:%g:%a:%h' "${target_file}")" == "0:0:644:1" \
    && "$(sha256sum "${target_file}" | awk '{print $1}')" == "${expected_sha256}" ]] \
    || fail "Installed Project runtime confinement profile ${target_file} failed metadata or digest attestation."
}

project_runtime_confinement_docker_args() {
  local -n output_args="$1"
  local policy="${PROJECT_RUNTIME_CONFINEMENT_POLICY:-${PROJECT_RUNTIME_APPARMOR_SECCOMP_POLICY}}"
  output_args=(
    --security-opt no-new-privileges
    --security-opt "seccomp=${PROJECT_RUNTIME_SECCOMP_PROFILE_PATH}"
  )
  case "${policy}" in
    "${PROJECT_RUNTIME_APPARMOR_SECCOMP_POLICY}")
      output_args+=(--security-opt "apparmor=${PROJECT_RUNTIME_APPARMOR_PROFILE_NAME}")
      ;;
    "${PROJECT_RUNTIME_SECCOMP_ONLY_POLICY}")
      ;;
    *)
      fail "Project runtime confinement policy is invalid."
      ;;
  esac
}

codex_project_runtime_confinement_docker_args() {
  local -n output_args="$1"
  ${CODEX_PROJECT_RUNTIME_CONFINEMENT_AVAILABLE} || return 1
  output_args=(
    --security-opt no-new-privileges
    --security-opt "seccomp=${CODEX_PROJECT_RUNTIME_SECCOMP_PROFILE_PATH}"
  )
  case "${PROJECT_RUNTIME_CONFINEMENT_POLICY}" in
    "${PROJECT_RUNTIME_APPARMOR_SECCOMP_POLICY}")
      output_args+=(--security-opt "apparmor=${CODEX_PROJECT_RUNTIME_APPARMOR_PROFILE_NAME}")
      ;;
    "${PROJECT_RUNTIME_SECCOMP_ONLY_POLICY}")
      ;;
    *)
      return 1
      ;;
  esac
}

# One provisioning boundary for every Project runtime dependency. With
# --skip-project-runtimes it persists the explicit disabled policy (which the
# backend fails closed on with a truthful reason) and skips confinement and
# image provisioning entirely; the rest of the install proceeds.
provision_project_runtimes() {
  local env_file="${1:-${PORTAL_DIR}/backend/.env.production}"
  if ${SKIP_PROJECT_RUNTIMES}; then
    CODEX_PROJECT_RUNTIME_CONFINEMENT_AVAILABLE=false
    PROJECT_RUNTIME_CONFINEMENT_POLICY="${PROJECT_RUNTIME_DISABLED_POLICY}"
    set_env_value_atomic \
      "${env_file}" \
      "PROJECT_RUNTIME_CONFINEMENT_POLICY" \
      "${PROJECT_RUNTIME_DISABLED_POLICY}" \
      || fail "Could not persist the disabled Project runtime policy."
    [[ "$(read_env_value "${env_file}" PROJECT_RUNTIME_CONFINEMENT_POLICY 2>/dev/null || true)" \
      == "${PROJECT_RUNTIME_DISABLED_POLICY}" ]] \
      || fail "Could not verify the disabled Project runtime policy."
    warn "Project runtimes are disabled (--skip-project-runtimes): Project Chat providers will be unavailable on this host until the installer runs again without the flag on a supported host."
    return 0
  fi
  ensure_project_runtime_confinement_profiles "${env_file}"
  ensure_project_egress_proxy_image "${env_file}"
  ensure_codex_project_sandbox_image "${env_file}"
  ensure_claude_code_project_sandbox_image "${env_file}"
  ensure_antigravity_project_sandbox_image "${env_file}"
  ensure_ollama_project_sandbox_image "${env_file}"
  ensure_agent_zero_project_sandbox_image "${env_file}"
  ensure_openclaw_sandbox_image "${env_file}"
  ensure_portal_project_runtime_image \
    "${PORTAL_PROJECT_RUNTIME_IMAGE_TAG}" "${env_file}"
  prune_project_runtime_build_debris
}

prune_project_runtime_build_debris() {
  # The sandbox image builds above leave tens of GB behind per convergence
  # cycle (observed: 18.2 GB of build cache plus 14 GB of dangling layers a
  # few hours after a clean box, and 17 GB still held as "in-use" BuildKit
  # cache after a default prune). Rebuilds only happen inside updates at pin
  # bumps, so standing cache buys minutes there at tens of GB of permanent
  # cost: prune it all. Tagged images, containers, and volumes are never
  # touched; an untagged digest-pulled base may be reclaimed and simply
  # re-pulls on the next convergence. A prune failure must never fail an
  # install.
  spin "Reclaiming Docker build cache from sandbox image builds" \
    "docker builder prune --all --force" \
    || warn "Docker build cache prune did not complete; disk reclaim will retry on the next update."
  spin "Removing dangling Docker image layers" \
    "docker image prune --force" \
    || warn "Dangling image prune did not complete; disk reclaim will retry on the next update."
}

ensure_project_runtime_confinement_profiles() {
  local env_file="${1:-${PORTAL_DIR}/backend/.env.production}"
  local source_root="${2:-${PORTAL_DIR}}"
  local install_mode="${3:-replace}"
  local docker_security_options apparmor_enabled=false docker_has_apparmor=false
  local shared_seccomp_source="${source_root}/installer/bridgesllm-project-runtime-v1.seccomp.json"
  local codex_seccomp_source="${source_root}/installer/bridgesllm-codex-project-runtime-v1.seccomp.json"
  local shared_apparmor_source="${source_root}/installer/bridgesllm-project-runtime-v1.apparmor"
  local codex_apparmor_source="${source_root}/installer/bridgesllm-codex-project-runtime-v1.apparmor"
  CODEX_PROJECT_RUNTIME_CONFINEMENT_AVAILABLE=false
  [[ -f "${env_file}" && ! -L "${env_file}" ]] \
    || fail "Portal production environment is unavailable for Project runtime confinement."
  command -v docker >/dev/null 2>&1 \
    || fail "Docker is required for Project runtime confinement attestation."

  install_project_runtime_confinement_file \
    "${shared_seccomp_source}" \
    "${PROJECT_RUNTIME_SECCOMP_PROFILE_PATH}" \
    "${PROJECT_RUNTIME_SECCOMP_PROFILE_SHA256}" "${install_mode}"
  install_project_runtime_confinement_file \
    "${codex_seccomp_source}" \
    "${CODEX_PROJECT_RUNTIME_SECCOMP_PROFILE_PATH}" \
    "${CODEX_PROJECT_RUNTIME_SECCOMP_PROFILE_SHA256}" "${install_mode}"
  python3 -m json.tool "${PROJECT_RUNTIME_SECCOMP_PROFILE_PATH}" >/dev/null \
    || fail "Installed Project runtime seccomp profile is not valid JSON."
  python3 -m json.tool "${CODEX_PROJECT_RUNTIME_SECCOMP_PROFILE_PATH}" >/dev/null \
    || fail "Installed Codex Project runtime seccomp profile is not valid JSON."
  install_project_runtime_confinement_file \
    "${shared_apparmor_source}" \
    "${PROJECT_RUNTIME_APPARMOR_PROFILE_PATH}" \
    "${PROJECT_RUNTIME_APPARMOR_PROFILE_SHA256}" "${install_mode}"
  install_project_runtime_confinement_file \
    "${codex_apparmor_source}" \
    "${CODEX_PROJECT_RUNTIME_APPARMOR_PROFILE_PATH}" \
    "${CODEX_PROJECT_RUNTIME_APPARMOR_PROFILE_SHA256}" "${install_mode}"

  docker_security_options="$(docker info --format '{{json .SecurityOptions}}' 2>/dev/null || true)"
  [[ "${docker_security_options}" == *'"name=seccomp'* ]] \
    || fail "Docker does not report seccomp support; Project runtimes remain unavailable."
  [[ "$(cat /sys/module/apparmor/parameters/enabled 2>/dev/null || true)" == "Y" ]] \
    && apparmor_enabled=true
  [[ "${docker_security_options}" == *'"name=apparmor"'* ]] \
    && docker_has_apparmor=true

  if ${apparmor_enabled} && ${docker_has_apparmor}; then
    command -v apparmor_parser >/dev/null 2>&1 \
      || fail "AppArmor is supported but apparmor_parser is unavailable; Project runtimes remain unavailable."
    apparmor_parser -r "${PROJECT_RUNTIME_APPARMOR_PROFILE_PATH}" >> "${LOG_FILE}" 2>&1 \
      || fail "Project runtime AppArmor profile could not be loaded in enforce mode."
    grep -Fx "${PROJECT_RUNTIME_APPARMOR_PROFILE_NAME} (enforce)" \
      /sys/kernel/security/apparmor/profiles >/dev/null 2>&1 \
      || fail "Project runtime AppArmor profile is not loaded in enforce mode."
    if apparmor_parser -Q -T "${CODEX_PROJECT_RUNTIME_APPARMOR_PROFILE_PATH}" \
        >> "${LOG_FILE}" 2>&1 \
      && apparmor_parser -r "${CODEX_PROJECT_RUNTIME_APPARMOR_PROFILE_PATH}" \
        >> "${LOG_FILE}" 2>&1 \
      && grep -Fx "${CODEX_PROJECT_RUNTIME_APPARMOR_PROFILE_NAME} (enforce)" \
        /sys/kernel/security/apparmor/profiles >/dev/null 2>&1; then
      CODEX_PROJECT_RUNTIME_CONFINEMENT_AVAILABLE=true
    else
      warn "This AppArmor parser cannot enforce the Codex Project user-namespace profile; Codex Project is unavailable, while other confined providers remain enabled."
    fi
    PROJECT_RUNTIME_CONFINEMENT_POLICY="${PROJECT_RUNTIME_APPARMOR_SECCOMP_POLICY}"
  elif ! ${apparmor_enabled} && ! ${docker_has_apparmor}; then
    PROJECT_RUNTIME_CONFINEMENT_POLICY="${PROJECT_RUNTIME_SECCOMP_ONLY_POLICY}"
    CODEX_PROJECT_RUNTIME_CONFINEMENT_AVAILABLE=true
    warn "AppArmor is genuinely unsupported on this Docker host; Project runtimes use the explicit seccomp-only policy."
  else
    fail "AppArmor kernel support (enabled: ${apparmor_enabled}) and Docker AppArmor support (available: ${docker_has_apparmor}) disagree on this host, so confined Project runtimes cannot be attested. This is common on LXC/OpenVZ/nested-container hosts where the kernel exposes AppArmor but the container runtime cannot hand it to Docker. Either install on a host/VM where Docker reports AppArmor support, or re-run the installer with --skip-project-runtimes to install the Portal with Project Chat disabled."
  fi

  set_env_value_atomic \
    "${env_file}" \
    "PROJECT_RUNTIME_CONFINEMENT_POLICY" \
    "${PROJECT_RUNTIME_CONFINEMENT_POLICY}" \
    || fail "Could not persist the Project runtime confinement policy."
  [[ "$(read_env_value "${env_file}" PROJECT_RUNTIME_CONFINEMENT_POLICY 2>/dev/null || true)" \
    == "${PROJECT_RUNTIME_CONFINEMENT_POLICY}" ]] \
    || fail "Project runtime confinement policy did not persist exactly."
  ok "Project runtime AppArmor/seccomp confinement (${PROJECT_RUNTIME_CONFINEMENT_POLICY})"
}

record_installer_image_id() {
  local env_file="$1"
  local key="$2"
  local image_id="$3"
  valid_docker_image_id "${image_id}" || return 1
  case "${key}" in
    OPENCLAW_PROJECT_SANDBOX_IMAGE_ID)
      OPENCLAW_PROJECT_SANDBOX_IMAGE_ID="${image_id}"
      ;;
    CODEX_PROJECT_SANDBOX_IMAGE_ID)
      CODEX_PROJECT_SANDBOX_IMAGE_ID="${image_id}"
      ;;
    CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID)
      CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID="${image_id}"
      ;;
    ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID)
      ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID="${image_id}"
      ;;
    OLLAMA_PROJECT_SANDBOX_IMAGE_ID)
      OLLAMA_PROJECT_SANDBOX_IMAGE_ID="${image_id}"
      ;;
    AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID)
      AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID="${image_id}"
      ;;
    PROJECT_EGRESS_PROXY_IMAGE_ID)
      PROJECT_EGRESS_PROXY_IMAGE_ID="${image_id}"
      ;;
    *)
      return 1
      ;;
  esac
  set_env_value_atomic "${env_file}" "${key}" "${image_id}" || return 1
  [[ "$(read_env_value "${env_file}" "${key}" 2>/dev/null || true)" == "${image_id}" ]]
}

clear_installer_image_id() {
  local env_file="$1"
  local key="$2"
  case "${key}" in
    OPENCLAW_PROJECT_SANDBOX_IMAGE_ID)
      OPENCLAW_PROJECT_SANDBOX_IMAGE_ID=""
      ;;
    CODEX_PROJECT_SANDBOX_IMAGE_ID)
      CODEX_PROJECT_SANDBOX_IMAGE_ID=""
      ;;
    CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID)
      CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID=""
      ;;
    ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID)
      ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID=""
      ;;
    OLLAMA_PROJECT_SANDBOX_IMAGE_ID)
      OLLAMA_PROJECT_SANDBOX_IMAGE_ID=""
      ;;
    AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID)
      AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID=""
      ;;
    PROJECT_EGRESS_PROXY_IMAGE_ID)
      PROJECT_EGRESS_PROXY_IMAGE_ID=""
      ;;
    *)
      return 1
      ;;
  esac
  set_env_value_atomic "${env_file}" "${key}" ""
}

start_docker_for_image_build() {
  systemctl start docker >> "${LOG_FILE}" 2>&1 \
    || fail "Docker could not be started for Project runtime image convergence."
  docker info >> "${LOG_FILE}" 2>&1 \
    || fail "Docker is installed but its daemon is not ready for Project runtime image convergence."
}

project_egress_artifact_fingerprint() {
  local artifact_dir="$1"
  node - \
    "${artifact_dir}/projectEgressPolicy.js" \
    "${artifact_dir}/projectEgressProxy.js" <<'NODE'
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const files = process.argv.slice(2);
const hash = crypto.createHash('sha256');
hash.update('bridgesllm-project-egress-artifacts-v1\0');
for (const file of files) {
  hash.update(path.basename(file));
  hash.update('\0');
  hash.update(fs.readFileSync(file));
  hash.update('\0');
}
process.stdout.write(hash.digest('hex'));
NODE
}

image_recipe_fingerprint() {
  local dockerfile="$1"
  local artifact_fingerprint="${2:-}"
  node - "${dockerfile}" "${artifact_fingerprint}" <<'NODE'
const crypto = require('crypto');
const fs = require('fs');
const dockerfile = process.argv[2];
const artifactFingerprint = process.argv[3] || '';
const hash = crypto.createHash('sha256');
hash.update('bridgesllm-installer-image-recipe-v1\0');
hash.update(fs.readFileSync(dockerfile));
hash.update('\0');
hash.update(artifactFingerprint);
process.stdout.write(hash.digest('hex'));
NODE
}

root_protected_regular_file_path() {
  local target="$1"
  [[ "${target}" == /* && -f "${target}" && ! -L "${target}" ]] || return 1
  [[ "$(stat -c '%u' "${target}" 2>/dev/null || true)" == "0" ]] || return 1
  (( (8#$(stat -c '%a' "${target}" 2>/dev/null || printf '777') & 0022) == 0 )) || return 1

  local directory
  directory="$(dirname -- "${target}")"
  while true; do
    [[ -d "${directory}" && ! -L "${directory}" ]] || return 1
    [[ "$(stat -c '%u' "${directory}" 2>/dev/null || true)" == "0" ]] || return 1
    (( (8#$(stat -c '%a' "${directory}" 2>/dev/null || printf '777') & 0022) == 0 )) || return 1
    [[ "${directory}" == "/" ]] && break
    directory="$(dirname -- "${directory}")"
  done
}

copy_root_protected_regular_file() {
  local source="$1" destination="$2"
  python3 - "${source}" "${destination}" <<'PY'
import os
import stat
import sys

source, destination = sys.argv[1:3]
source_flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
destination_flags = (
    os.O_WRONLY
    | os.O_CREAT
    | os.O_EXCL
    | getattr(os, "O_CLOEXEC", 0)
    | getattr(os, "O_NOFOLLOW", 0)
)
source_fd = os.open(source, source_flags)
destination_fd = -1
try:
    source_stat = os.fstat(source_fd)
    if (
        not stat.S_ISREG(source_stat.st_mode)
        or source_stat.st_uid != 0
        or source_stat.st_mode & 0o022
    ):
        raise OSError("source is not a root-protected regular file")
    destination_fd = os.open(destination, destination_flags, 0o644)
    while True:
        chunk = os.read(source_fd, 1024 * 1024)
        if not chunk:
            break
        view = memoryview(chunk)
        while view:
            written = os.write(destination_fd, view)
            if written <= 0:
                raise OSError("short write while copying protected recipe")
            view = view[written:]
    os.fchmod(destination_fd, 0o644)
    os.fsync(destination_fd)
finally:
    if destination_fd >= 0:
        os.close(destination_fd)
    os.close(source_fd)
PY
}

normalize_agent_zero_project_architecture() {
  case "${1:-}" in
    x86_64|amd64|x64)
      printf 'amd64\n'
      ;;
    aarch64|arm64)
      printf 'arm64\n'
      ;;
    *)
      return 1
      ;;
  esac
}

agent_zero_project_upstream_digest() {
  case "${1:-}" in
    amd64)
      printf '%s\n' "${AGENT_ZERO_PROJECT_AMD64_UPSTREAM_DIGEST}"
      ;;
    arm64)
      printf '%s\n' "${AGENT_ZERO_PROJECT_ARM64_UPSTREAM_DIGEST}"
      ;;
    *)
      return 1
      ;;
  esac
}

write_openclaw_sandbox_dockerfile() {
  local destination="$1"
  cat > "${destination}" <<'SANDBOX_DOCKERFILE'
FROM node:22.23.1-bookworm-slim
ARG PORTAL_RECIPE_SHA256
LABEL com.bridgesllm.openclaw-sandbox.recipe-sha256="${PORTAL_RECIPE_SHA256}"
ENV DEBIAN_FRONTEND=noninteractive
RUN apt-get update \
  && apt-get install -y --no-install-recommends \
    bash \
    ca-certificates \
    curl \
    git \
    jq \
    python3 \
    python3-pip \
    python3-venv \
    ripgrep \
  && rm -rf /var/lib/apt/lists/*
RUN mkdir -p /home/openclaw \
  && chown 1000:1000 /home/openclaw
USER 1000:1000
WORKDIR /home/openclaw
ENTRYPOINT []
CMD ["sleep", "infinity"]
SANDBOX_DOCKERFILE
}

write_codex_project_sandbox_dockerfile() {
  local destination="$1"
  cat > "${destination}" <<'CODEX_PROJECT_DOCKERFILE'
FROM node:22.23.1-bookworm-slim
ARG PORTAL_RECIPE_SHA256
ARG CODEX_CLI_VERSION
LABEL com.bridgesllm.codex-project.recipe-sha256="${PORTAL_RECIPE_SHA256}"
LABEL com.bridgesllm.codex-project.cli-version="${CODEX_CLI_VERSION}"
ENV DEBIAN_FRONTEND=noninteractive
RUN apt-get update \
  && apt-get install -y --no-install-recommends \
    bash \
    build-essential \
    ca-certificates \
    curl \
    git \
    jq \
    openssh-client \
    python3 \
    python3-pip \
    python3-venv \
    ripgrep \
    unzip \
  && rm -rf /var/lib/apt/lists/*
RUN npm install --global --omit=dev "@openai/codex@${CODEX_CLI_VERSION}" \
  && ln -sf /usr/local/bin/codex /usr/bin/codex \
  && codex --version | grep -F "${CODEX_CLI_VERSION}"
RUN mkdir -p /home/codex /workspace/project \
  && chown -R 1000:1000 /home/codex /workspace
ENV HOME=/home/codex CODEX_HOME=/home/codex/.codex LANG=C.UTF-8 LC_ALL=C.UTF-8
USER 1000:1000
WORKDIR /workspace/project
ENTRYPOINT []
CMD ["node", "-e", "setInterval(()=>{},2147483647)"]
CODEX_PROJECT_DOCKERFILE
}

write_claude_code_project_sandbox_dockerfile() {
