  [[ "$(docker_image_label "${image}" "${AGENT_ZERO_PROJECT_RECIPE_LABEL}" || true)" == "${recipe_fingerprint}" ]] \
    || return 1
  [[ "$(docker_image_label "${image}" "${AGENT_ZERO_PROJECT_SOURCE_COMMIT_LABEL}" || true)" == "${source_commit}" ]] \
    || return 1
  [[ "$(docker_image_label "${image}" "${AGENT_ZERO_PROJECT_UPSTREAM_DIGEST_LABEL}" || true)" == "${upstream_digest}" ]] \
    || return 1
  [[ "$(docker_image_label "${image}" "${AGENT_ZERO_PROJECT_RUNTIME_USER_LABEL}" || true)" == "${AGENT_ZERO_PROJECT_RUNTIME_USER}" ]] \
    || return 1
  [[ "$(docker image inspect --format '{{.Config.User}}' "${image}" 2>/dev/null || true)" == "${AGENT_ZERO_PROJECT_RUNTIME_USER}" ]] \
    || return 1
  image_command="$(docker image inspect --format '{{json .Config.Cmd}}' "${image}" 2>/dev/null || true)"
  [[ "${image_command}" == '["/opt/venv-a0/bin/python","/a0/run_ui.py","--dockerized=true","--port=80","--host=0.0.0.0"]' ]] \
    || return 1
  image_entrypoint="$(docker image inspect --format '{{json .Config.Entrypoint}}' "${image}" 2>/dev/null || true)"
  [[ -z "${image_entrypoint}" || "${image_entrypoint}" == "null" || "${image_entrypoint}" == "[]" ]] \
    || return 1
  image_workdir="$(docker image inspect --format '{{.Config.WorkingDir}}' "${image}" 2>/dev/null || true)"
  [[ "${image_workdir}" == "/a0" ]] || return 1

  docker run --rm \
    --network none \
    --read-only \
    --cap-drop ALL \
    "${confinement_args[@]}" \
    --pids-limit 64 \
    --memory 512m \
    --tmpfs /tmp:rw,noexec,nosuid,nodev,size=33554432,mode=1777 \
    --tmpfs /a0/tmp:rw,noexec,nosuid,nodev,size=33554432,mode=1777 \
    --mount type=volume,target=/a0/usr \
    --entrypoint sh \
    "${image}" -lc \
    'test "$(id -u):$(id -g)" = "1000:1000" \
      && test -x /opt/venv-a0/bin/python \
      && test -f /a0/run_ui.py \
      && test -f /a0/plugins/_a0_connector/api/v1/capabilities.py \
      && test -f /a0/plugins/_a0_connector/api/ws_connector.py \
      && test ! -e /a0/.git \
      && for runtime_dir in /a0/usr/agents /a0/usr/home /a0/usr/knowledge /a0/usr/plugins /a0/usr/projects /a0/usr/skills /a0/usr/workdir; do \
           test -d "${runtime_dir}" \
             && test ! -L "${runtime_dir}" \
             && test "$(stat -c "%u:%g" "${runtime_dir}")" = "1000:1000"; \
         done \
      && /opt/venv-a0/bin/python -c "import pathlib; assert pathlib.Path(\"/a0/run_ui.py\").is_file()"' \
    >/dev/null 2>&1
}

