  [[ "$(docker_image_label "${image}" "${PROJECT_EGRESS_RECIPE_LABEL}" || true)" == "${recipe_fingerprint}" ]] \
    || return 1
  [[ "$(docker_image_label "${image}" "${PROJECT_EGRESS_ARTIFACTS_LABEL}" || true)" == "${artifact_fingerprint}" ]] \
    || return 1
  [[ "$(docker image inspect --format '{{.Config.User}}' "${image}" 2>/dev/null || true)" == "1000:1000" ]] \
