  docker run --rm \
    --network none \
    --read-only \
    --cap-drop ALL \
    "${confinement_args[@]}" \
    --pids-limit 64 \
    --memory 256m \
    --entrypoint node \
    "${image}" -e "${verify_script}" "${artifact_fingerprint}" \
    >/dev/null 2>&1
}

ensure_openclaw_sandbox_image() {
  local env_file="${1:-${PORTAL_DIR}/backend/.env.production}"
  local image="${2:-${OPENCLAW_PROJECT_SANDBOX_IMAGE_TAG}}"
  [[ -f "${env_file}" && ! -L "${env_file}" ]] \
    || fail "Portal production environment is unavailable for OpenClaw sandbox image attestation."

  if $SKIP_OPENCLAW || ! command -v openclaw &>/dev/null; then
    clear_installer_image_id "${env_file}" "OPENCLAW_PROJECT_SANDBOX_IMAGE_ID" \
      || fail "Could not clear the unavailable OpenClaw sandbox image ID."
    return 0
  fi
  command -v docker &>/dev/null \
    || fail "Docker is required for OpenClaw project sandboxes, but docker is not installed."
  valid_local_image_tag "${image}" || fail "OpenClaw sandbox image tag is invalid."
  start_docker_for_image_build

  local build_dir dockerfile recipe_fingerprint image_id
  build_dir="$(mktemp -d)"
  dockerfile="${build_dir}/Dockerfile"
  write_openclaw_sandbox_dockerfile "${dockerfile}"
  recipe_fingerprint="$(image_recipe_fingerprint "${dockerfile}")"
  [[ "${recipe_fingerprint}" =~ ^[a-f0-9]{64}$ ]] || {
    rm -rf -- "${build_dir}"
    fail "Could not fingerprint the OpenClaw sandbox recipe."
  }

  if verify_openclaw_sandbox_image "${image}" "${recipe_fingerprint}"; then
    ok "OpenClaw sandbox image recipe (verified)"
  else
    if docker image inspect "${image}" >/dev/null 2>&1; then
      warn "Existing OpenClaw sandbox image recipe drifted; rebuilding deterministically."
    fi
    if ! spin "Building OpenClaw project sandbox image" \
      "docker build --pull --tag '${image}' --build-arg 'PORTAL_RECIPE_SHA256=${recipe_fingerprint}' '${build_dir}'"; then
      rm -rf -- "${build_dir}"
      fail "Failed to build ${image}. Project assistants require this exact sandbox recipe."
    fi
    if ! verify_openclaw_sandbox_image "${image}" "${recipe_fingerprint}"; then
      rm -rf -- "${build_dir}"
      fail "Built ${image}, but its recipe label, non-root identity, or required tools failed attestation."
    fi
  fi
  rm -rf -- "${build_dir}"

  image_id="$(docker_image_id "${image}" || true)"
  valid_docker_image_id "${image_id}" \
    || fail "OpenClaw sandbox image did not resolve to an immutable Docker image ID."
  verify_openclaw_sandbox_image "${image_id}" "${recipe_fingerprint}" \
    || fail "The resolved OpenClaw sandbox image ID failed immutable recipe/runtime attestation."
  record_installer_image_id "${env_file}" "OPENCLAW_PROJECT_SANDBOX_IMAGE_ID" "${image_id}" \
    || fail "OpenClaw sandbox image did not resolve and persist an immutable Docker image ID."
  ok "OpenClaw sandbox image ${image_id:0:19}… (pinned)"
}

ensure_codex_project_sandbox_image() {
  local env_file="${1:-${PORTAL_DIR}/backend/.env.production}"
  local image="${2:-${CODEX_PROJECT_SANDBOX_IMAGE_TAG}}"
  [[ -f "${env_file}" && ! -L "${env_file}" ]] \
    || fail "Portal production environment is unavailable for Codex Project runtime image attestation."
  if ! ${CODEX_PROJECT_RUNTIME_CONFINEMENT_AVAILABLE}; then
    degrade_codex_project_runtime \
      "${env_file}" \
      "Codex Project runtime image convergence was skipped because its dedicated confinement profile is unavailable."
    return 0
  fi
  command -v docker &>/dev/null \
    || fail "Docker is required for Codex Project sandboxes, but docker is not installed."
  valid_local_image_tag "${image}" || fail "Codex Project runtime image tag is invalid."
  start_docker_for_image_build

  local build_dir dockerfile recipe_fingerprint image_id
  build_dir="$(mktemp -d)"
  dockerfile="${build_dir}/Dockerfile"
  write_codex_project_sandbox_dockerfile "${dockerfile}"
  recipe_fingerprint="$(image_recipe_fingerprint "${dockerfile}" "codex-cli=${PIN_CODEX_CLI_VERSION}")"
  [[ "${recipe_fingerprint}" =~ ^[a-f0-9]{64}$ ]] || {
    rm -rf -- "${build_dir}"
    fail "Could not fingerprint the Codex Project runtime recipe."
  }

  if verify_codex_project_sandbox_image "${image}" "${recipe_fingerprint}"; then
    ok "Codex Project runtime image recipe/CLI (verified)"
  else
    if docker image inspect "${image}" >/dev/null 2>&1; then
      warn "Existing Codex Project runtime drifted; rebuilding the tested CLI image."
    fi
    if ! spin "Building Codex Project sandbox image" \
      "docker build --pull --tag '${image}' --build-arg 'PORTAL_RECIPE_SHA256=${recipe_fingerprint}' --build-arg 'CODEX_CLI_VERSION=${PIN_CODEX_CLI_VERSION}' '${build_dir}'"; then
      rm -rf -- "${build_dir}"
      degrade_codex_project_runtime \
        "${env_file}" \
        "Codex Project runtime ${image} could not be built with Codex ${PIN_CODEX_CLI_VERSION}."
      return 0
    fi
    if ! verify_codex_project_sandbox_image "${image}" "${recipe_fingerprint}"; then
      rm -rf -- "${build_dir}"
      degrade_codex_project_runtime \
        "${env_file}" \
        "Codex Project runtime ${image} failed its dedicated recipe, CLI, confinement, or sandbox smoke attestation."
      return 0
    fi
  fi
  rm -rf -- "${build_dir}"

  image_id="$(docker_image_id "${image}" || true)"
  if ! valid_docker_image_id "${image_id}"; then
    degrade_codex_project_runtime \
      "${env_file}" \
      "Codex Project runtime image did not resolve to an immutable Docker image ID."
    return 0
  fi
  if ! verify_codex_project_sandbox_image "${image_id}" "${recipe_fingerprint}"; then
    degrade_codex_project_runtime \
      "${env_file}" \
      "The resolved Codex Project runtime image ID failed immutable recipe/runtime attestation."
    return 0
  fi
  if ! record_installer_image_id "${env_file}" "CODEX_PROJECT_SANDBOX_IMAGE_ID" "${image_id}"; then
    degrade_codex_project_runtime \
      "${env_file}" \
      "Codex Project runtime could not persist its immutable Docker image ID."
    return 0
  fi
  ok "Codex Project runtime image ${image_id:0:19}… (pinned)"
}

