      "docker build --pull --tag '${image}' --build-arg 'PORTAL_RECIPE_SHA256=${recipe_fingerprint}' --build-arg 'ANTIGRAVITY_VERSION=${PIN_ANTIGRAVITY_VERSION}' --build-arg 'ANTIGRAVITY_BINARY_SHA256=${binary_fingerprint}' '${build_dir}'"; then
      rm -rf -- "${build_dir}"
      fail "Failed to build ${image} with Antigravity ${PIN_ANTIGRAVITY_VERSION}."
    fi
    if ! verify_antigravity_project_sandbox_image "${image}" "${recipe_fingerprint}" "${binary_fingerprint}"; then
      rm -rf -- "${build_dir}"
      fail "Built ${image}, but its recipe, CLI pin, binary hash, inner-sandbox tools, or non-root identity failed attestation."
    fi
  fi
  rm -rf -- "${build_dir}"

  image_id="$(docker_image_id "${image}" || true)"
  valid_docker_image_id "${image_id}" \
    || fail "Antigravity Project runtime image did not resolve to an immutable Docker image ID."
  verify_antigravity_project_sandbox_image "${image_id}" "${recipe_fingerprint}" "${binary_fingerprint}" \
    || fail "The resolved Antigravity Project runtime image ID failed immutable recipe/runtime attestation."
  record_installer_image_id "${env_file}" "ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID" "${image_id}" \
    || fail "Antigravity Project runtime did not persist an immutable Docker image ID."
