ensure_agent_zero_project_sandbox_image() {
  local env_file="${1:-${PORTAL_DIR}/backend/.env.production}"
  local image="${2:-${AGENT_ZERO_PROJECT_SANDBOX_IMAGE_TAG}}"
  local recipe_source="${3:-${PORTAL_DIR}/installer/agent-zero-project-sandbox.Dockerfile}"
  local requested_architecture="${4:-$(uname -m)}"
  [[ -f "${env_file}" && ! -L "${env_file}" ]] \
    || fail "Portal production environment is unavailable for Agent Zero Project runtime image attestation."
  root_protected_regular_file_path "${recipe_source}" \
    || fail "The Agent Zero Project runtime image recipe or one of its ancestors is not root-protected."
  command -v docker &>/dev/null \
    || fail "Docker is required for Agent Zero Project sandboxes, but docker is not installed."
  valid_local_image_tag "${image}" || fail "Agent Zero Project runtime image tag is invalid."
  start_docker_for_image_build

  local architecture upstream_digest upstream_ref
  architecture="$(normalize_agent_zero_project_architecture "${requested_architecture}" || true)"
  if [[ -z "${architecture}" ]]; then
    clear_installer_image_id "${env_file}" "AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID" \
      || fail "Could not clear the unsupported Agent Zero Project runtime image ID."
    fail "Agent Zero Project sandboxes do not support host architecture ${requested_architecture}."
  fi
  upstream_digest="$(agent_zero_project_upstream_digest "${architecture}" || true)"
  valid_docker_image_id "${upstream_digest}" \
    || fail "Agent Zero Project upstream image digest is invalid for ${architecture}."
  [[ "${AGENT_ZERO_PROJECT_SOURCE_COMMIT}" =~ ^[a-f0-9]{40}$ ]] \
    || fail "Agent Zero Project source commit pin is malformed."
  upstream_ref="agent0ai/agent-zero@${upstream_digest}"

  local build_dir dockerfile recipe_fingerprint image_id
  build_dir="$(mktemp -d)"
  dockerfile="${build_dir}/Dockerfile"
  copy_root_protected_regular_file "${recipe_source}" "${dockerfile}" || {
    rm -rf -- "${build_dir}"
    fail "The Agent Zero Project runtime image recipe changed or became unsafe while it was being opened."
  }
  recipe_fingerprint="$(image_recipe_fingerprint \
    "${dockerfile}" \
    "agent-zero-project-v1;architecture=${architecture};upstream=${upstream_digest};source=${AGENT_ZERO_PROJECT_SOURCE_COMMIT};runtime-user=${AGENT_ZERO_PROJECT_RUNTIME_USER}")"
  [[ "${recipe_fingerprint}" =~ ^[a-f0-9]{64}$ ]] || {
    rm -rf -- "${build_dir}"
    fail "Could not fingerprint the Agent Zero Project runtime recipe."
  }

  if verify_agent_zero_project_sandbox_image \
    "${image}" "${recipe_fingerprint}" "${upstream_digest}" "${AGENT_ZERO_PROJECT_SOURCE_COMMIT}"; then
    ok "Agent Zero Project runtime image recipe/source (verified)"
  else
    if docker image inspect "${image}" >/dev/null 2>&1; then
      warn "Existing Agent Zero Project runtime drifted; rebuilding the audited non-root image."
    fi
    if ! spin "Building Agent Zero Project sandbox image" \
      "docker build --pull --tag '${image}' --network none --build-arg 'PORTAL_RECIPE_SHA256=${recipe_fingerprint}' --build-arg 'A0_BASE_IMAGE=${upstream_ref}' --build-arg 'A0_SOURCE_COMMIT=${AGENT_ZERO_PROJECT_SOURCE_COMMIT}' --build-arg 'A0_UPSTREAM_DIGEST=${upstream_digest}' '${build_dir}'"; then
      rm -rf -- "${build_dir}"
      fail "Failed to build ${image} from the audited Agent Zero v2.5 source."
    fi
    if ! verify_agent_zero_project_sandbox_image \
      "${image}" "${recipe_fingerprint}" "${upstream_digest}" "${AGENT_ZERO_PROJECT_SOURCE_COMMIT}"; then
      rm -rf -- "${build_dir}"
      fail "Built ${image}, but its immutable source, direct-launch command, volume seed, or non-root runtime failed attestation."
    fi
  fi
  rm -rf -- "${build_dir}"

  image_id="$(docker_image_id "${image}" || true)"
  valid_docker_image_id "${image_id}" \
    || fail "Agent Zero Project runtime image did not resolve to an immutable Docker image ID."
  [[ "${image_id}" != "${upstream_digest}" ]] \
    || fail "Agent Zero Project runtime resolved to the raw upstream manifest instead of the derived Portal image."
  verify_agent_zero_project_sandbox_image \
    "${image_id}" "${recipe_fingerprint}" "${upstream_digest}" "${AGENT_ZERO_PROJECT_SOURCE_COMMIT}" \
    || fail "The resolved Agent Zero Project image ID failed immutable source/runtime attestation."
  record_installer_image_id "${env_file}" "AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID" "${image_id}" \
    || fail "Agent Zero Project runtime did not persist an immutable derived image ID."
  ok "Agent Zero Project runtime image ${image_id:0:19}… (pinned)"
}

ensure_docker_address_pools() {
  # Each Project egress plane consumes two bridge networks. Docker's default
  # address pools top out around 31 networks, which a modest number of
  # projects exhausts ("all predefined address pools have been fully
  # subnetted"). Provision a dedicated /16 carved into /28s (4096 networks).
  command -v docker &>/dev/null || return 0
  command -v python3 &>/dev/null || return 0
  local daemon_config="/etc/docker/daemon.json"
  local changed
  changed="$(python3 - "$daemon_config" <<'POOLS_PY'
import json, os, sys
path = sys.argv[1]
config = {}
if os.path.exists(path):
    try:
        with open(path) as handle:
            config = json.load(handle) or {}
    except Exception:
        raise SystemExit("unparseable")
pools = config.get("default-address-pools")
if isinstance(pools, list) and pools:
    print("unchanged")
    raise SystemExit(0)
config["default-address-pools"] = [{"base": "10.201.0.0/16", "size": 28}]
os.makedirs(os.path.dirname(path), exist_ok=True)
tmp = f"{path}.portal-tmp"
with open(tmp, "w") as handle:
    json.dump(config, handle, indent=2)
    handle.write("\n")
os.replace(tmp, path)
print("updated")
POOLS_PY
)" || { warn "Could not evaluate Docker daemon config for address pools; leaving it untouched."; return 0; }
  if [[ "$changed" == "updated" ]]; then
    info "Expanding Docker bridge address pools for Project sandboxes..."
    systemctl restart docker >> "$LOG_FILE" 2>&1 || warn "Docker restart after address-pool expansion failed; existing pools remain in use until the next restart."
  fi
}

ensure_project_egress_proxy_image() {
  local env_file="${1:-${PORTAL_DIR}/backend/.env.production}"
  local artifact_dir="${2:-${PORTAL_DIR}/backend/dist/services}"
  local image="${3:-${PROJECT_EGRESS_PROXY_IMAGE_TAG}}"
  local policy_artifact="${artifact_dir}/projectEgressPolicy.js"
  local proxy_artifact="${artifact_dir}/projectEgressProxy.js"

  [[ -f "${env_file}" && ! -L "${env_file}" ]] \
    || fail "Portal production environment is unavailable for Project egress image attestation."
  [[ -f "${policy_artifact}" && ! -L "${policy_artifact}" \
    && -f "${proxy_artifact}" && ! -L "${proxy_artifact}" ]] \
    || fail "Built Project egress proxy/policy artifacts are missing; refusing to start Portal without its egress sidecar image."
  command -v docker &>/dev/null \
    || fail "Docker is required for the Project egress proxy image, but docker is not installed."
  valid_local_image_tag "${image}" || fail "Project egress proxy image tag is invalid."
  start_docker_for_image_build

  local build_dir artifact_fingerprint recipe_fingerprint image_id
  local in_use_image_id="" discovery_status=0 image_ready=false
  build_dir="$(mktemp -d)"
  install -m 0644 "${policy_artifact}" "${build_dir}/projectEgressPolicy.js"
  install -m 0644 "${proxy_artifact}" "${build_dir}/projectEgressProxy.js"
  write_project_egress_proxy_dockerfile "${build_dir}/Dockerfile"
  artifact_fingerprint="$(project_egress_artifact_fingerprint "${build_dir}")"
  recipe_fingerprint="$(image_recipe_fingerprint "${build_dir}/Dockerfile" "${artifact_fingerprint}")"
  if [[ ! "${artifact_fingerprint}" =~ ^[a-f0-9]{64}$ \
    || ! "${recipe_fingerprint}" =~ ^[a-f0-9]{64}$ ]]; then
    rm -rf -- "${build_dir}"
    fail "Could not fingerprint the built Project egress image inputs."
  fi

  # Preserve a single exact in-use generation before consulting mutable tags.
  # This keeps prepared Project planes valid across an update whose equivalent
  # transaction-scoped build happened to receive another Docker image ID.
  if in_use_image_id="$(
    discover_unique_managed_project_egress_proxy_image_id
  )"; then
    if [[ "$(docker_image_id "${in_use_image_id}" || true)" \
        != "${in_use_image_id}" ]] \
      || ! verify_project_egress_proxy_image \
        "${in_use_image_id}" "${recipe_fingerprint}" "${artifact_fingerprint}"; then
      rm -rf -- "${build_dir}"
      fail "The in-use managed Project egress proxy image does not exactly match this Portal's compiled policy; refusing to strand active Project runtimes."
    fi
    if [[ "$(docker_image_id "${image}" || true)" != "${in_use_image_id}" ]] \
      || ! verify_project_egress_proxy_image \
        "${image}" "${recipe_fingerprint}" "${artifact_fingerprint}"; then
      if ! docker image tag "${in_use_image_id}" "${image}" \
        >> "${LOG_FILE}" 2>&1; then
        rm -rf -- "${build_dir}"
        fail "The verified in-use Project egress proxy image could not be assigned to ${image}."
      fi
    fi
    if [[ "$(docker_image_id "${image}" || true)" != "${in_use_image_id}" ]] \
      || ! verify_project_egress_proxy_image \
        "${image}" "${recipe_fingerprint}" "${artifact_fingerprint}"; then
      rm -rf -- "${build_dir}"
      fail "The reused Project egress proxy image failed immutable candidate attestation."
    fi
    image_ready=true
    ok "Project egress proxy image recipe/artifacts (verified in-use generation)"
  else
    discovery_status=$?
    case "${discovery_status}" in
      1) ;;
      2)
        rm -rf -- "${build_dir}"
        fail "Managed Project egress proxy inventory could not be inspected safely."
        ;;
      3)
        rm -rf -- "${build_dir}"
        fail "Managed Project egress resource ownership, identity, or proxy/network topology is ambiguous; refusing image convergence."
        ;;
      4)
        rm -rf -- "${build_dir}"
        fail "Managed Project egress proxies reference multiple immutable image generations; refusing image convergence."
        ;;
      5)
        rm -rf -- "${build_dir}"
        fail "Managed Project egress resources changed during immutable inventory; retry after Project runtime activity is quiet."
        ;;
      *)
        rm -rf -- "${build_dir}"
        fail "Managed Project egress proxy image discovery returned an invalid state."
        ;;
    esac
  fi

  if ! ${image_ready}; then
    if verify_project_egress_proxy_image \
      "${image}" "${recipe_fingerprint}" "${artifact_fingerprint}"; then
      ok "Project egress proxy image recipe/artifacts (verified)"
    elif [[ "${image}" != "${PROJECT_EGRESS_PROXY_IMAGE_TAG}" ]] \
      && verify_project_egress_proxy_image \
        "${PROJECT_EGRESS_PROXY_IMAGE_TAG}" \
        "${recipe_fingerprint}" "${artifact_fingerprint}"; then
      image_id="$(docker_image_id "${PROJECT_EGRESS_PROXY_IMAGE_TAG}" || true)"
      if ! valid_docker_image_id "${image_id}" \
        || [[ "$(docker_image_id "${image_id}" || true)" != "${image_id}" ]] \
        || ! verify_project_egress_proxy_image \
          "${image_id}" "${recipe_fingerprint}" "${artifact_fingerprint}"; then
        rm -rf -- "${build_dir}"
        fail "The canonical Project egress proxy tag did not resolve to an exact immutable image."
      fi
      if ! docker image tag "${image_id}" "${image}" \
        >> "${LOG_FILE}" 2>&1; then
        rm -rf -- "${build_dir}"
        fail "The verified canonical Project egress proxy image could not be assigned to ${image}."
      fi
      if [[ "$(docker_image_id "${image}" || true)" != "${image_id}" ]] \
        || ! verify_project_egress_proxy_image \
          "${image}" "${recipe_fingerprint}" "${artifact_fingerprint}"; then
        rm -rf -- "${build_dir}"
        fail "The reused canonical Project egress proxy image failed immutable candidate attestation."
      fi
      ok "Project egress proxy image recipe/artifacts (reused canonical generation)"
    else
      if docker image inspect "${image}" >/dev/null 2>&1; then
        warn "Existing Project egress proxy image drifted from its built artifacts; rebuilding."
      fi
      if ! spin "Building Project egress proxy image" \
        "docker build --pull --tag '${image}' --build-arg 'PORTAL_RECIPE_SHA256=${recipe_fingerprint}' --build-arg 'PORTAL_ARTIFACTS_SHA256=${artifact_fingerprint}' '${build_dir}'"; then
        rm -rf -- "${build_dir}"
        fail "Failed to build ${image} from the Portal's compiled egress proxy/policy artifacts."
      fi
      if ! verify_project_egress_proxy_image \
        "${image}" "${recipe_fingerprint}" "${artifact_fingerprint}"; then
        rm -rf -- "${build_dir}"
        fail "Built ${image}, but its labels, compiled artifacts, or non-root runtime failed attestation."
      fi
    fi
  fi
  rm -rf -- "${build_dir}"

  image_id="$(docker_image_id "${image}" || true)"
  valid_docker_image_id "${image_id}" \
    || fail "Project egress proxy image did not resolve to an immutable Docker image ID."
  verify_project_egress_proxy_image \
    "${image_id}" "${recipe_fingerprint}" "${artifact_fingerprint}" \
    || fail "The resolved Project egress proxy image ID failed immutable artifact/runtime attestation."
  record_installer_image_id "${env_file}" "PROJECT_EGRESS_PROXY_IMAGE_ID" "${image_id}" \
    || fail "Project egress proxy image did not resolve and persist an immutable Docker image ID."
  ok "Project egress proxy image ${image_id:0:19}… (pinned)"
}

attest_project_runtime_image_repair_authority() {
  local installed_script="$1" installed_env="$2" executing_script="$3"
  local source_only="${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}"
  python3 - "${installed_script}" "${installed_env}" \
    "${executing_script}" "${source_only}" <<'PY'
import os
import re
import stat
import sys

script_path, env_path, executing_path, source_only = sys.argv[1:]
expected_script = "/opt/bridgesllm/portal/installer/install.sh"
expected_env = "/opt/bridgesllm/portal/backend/.env.production"
if source_only != "1" and (script_path != expected_script or env_path != expected_env):
    raise SystemExit("Project runtime repair authority is not the fixed installed Portal")
if source_only != "1" and not re.fullmatch(r"/proc/(?:self|[0-9]+)/fd/[0-9]+", executing_path):
    raise SystemExit("Project runtime repair was not launched through its attested script descriptor")

def secure_open(path, *, environment=False):
    if not os.path.isabs(path) or os.path.normpath(path) != path:
        raise SystemExit("Project runtime repair authority path is not canonical")
    parts = [part for part in path.split("/") if part]
    directory_fd = os.open("/", os.O_RDONLY | os.O_DIRECTORY)
    opened = [directory_fd]
    try:
        for part in parts[:-1]:
            next_fd = os.open(
                part,
                os.O_RDONLY | os.O_DIRECTORY | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=directory_fd,
            )
            opened.append(next_fd)
            info = os.fstat(next_fd)
            if (
                not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or info.st_gid != 0
                or info.st_mode & 0o022
            ):
                raise SystemExit("Project runtime repair authority directory is unsafe")
            directory_fd = next_fd
        descriptor = os.open(
            parts[-1],
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NOATIME", 0),
            dir_fd=directory_fd,
        )
        info = os.fstat(descriptor)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != 0
            or info.st_gid != 0
            or info.st_nlink != 1
            or info.st_mode & 0o022
            or (environment and stat.S_IMODE(info.st_mode) != 0o600)
        ):
            os.close(descriptor)
            raise SystemExit("Project runtime repair authority file is unsafe")
        return descriptor, info
    finally:
        for opened_fd in reversed(opened):
            os.close(opened_fd)

script_fd, script_info = secure_open(script_path)
env_fd, _ = secure_open(env_path, environment=True)
try:
    current_fd = os.open(
        executing_path,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOATIME", 0),
    )
    try:
        current_info = os.fstat(current_fd)
        if (current_info.st_dev, current_info.st_ino) != (
            script_info.st_dev,
            script_info.st_ino,
        ):
            raise SystemExit("Executing repair script is not the installed Portal script")
    finally:
        os.close(current_fd)
finally:
    os.close(script_fd)
    os.close(env_fd)
PY
}

verify_project_runtime_repair_health() {
  local service_name="${1:-bridgesllm-product.service}"
  local health_url="${2:-http://127.0.0.1:4001/health}"
  local timeout_secs="${3:-60}" waited=0 payload=""
  while (( waited < timeout_secs )); do
    if systemctl is-active --quiet "${service_name}"; then
      payload="$(curl -fsS --max-time 2 "${health_url}" 2>/dev/null || true)"
      if printf '%s' "${payload}" | python3 /dev/fd/3 "${VERSION}" 3<<'PY'
import json
import sys

expected = sys.argv[1]
try:
    payload = json.load(sys.stdin)
except Exception:
    raise SystemExit(1)
if payload.get("status") not in {"ok", "degraded"}:
    raise SystemExit(1)
if payload.get("version") != expected:
    raise SystemExit(1)
PY
      then
        return 0
      fi
    fi
    sleep 2
    waited=$((waited + 2))
  done
  return 1
}

project_runtime_repair_environment_transaction() {
  local action="$1" env_file="$2" transaction_dir="$3"
  local image_id="${4:-}"
  python3 - "${action}" "${env_file}" "${transaction_dir}" \
    "${image_id}" <<'PY'
import base64
import hashlib
import json
import os
import re
import secrets
import stat
import sys
import time

action, env_path, transaction_path, image_id = sys.argv[1:]
key = b"PORTAL_PROJECT_RUNTIME_IMAGE_ID"
maximum_size = 1024 * 1024

def fail(message):
    raise SystemExit(message)

def stat_record(info):
    return {
        "dev": info.st_dev,
        "ino": info.st_ino,
        "mode": stat.S_IMODE(info.st_mode),
        "uid": info.st_uid,
        "gid": info.st_gid,
        "nlink": info.st_nlink,
        "size": info.st_size,
        "atime_ns": info.st_atime_ns,
        "mtime_ns": info.st_mtime_ns,
        "ctime_ns": info.st_ctime_ns,
    }

def identity_matches(info, record):
    current = stat_record(info)
    return all(current[name] == record[name] for name in (
        "dev", "ino", "mode", "uid", "gid", "nlink", "size",
        "mtime_ns", "ctime_ns",
    ))

def open_regular(path):
    descriptor = os.open(
        path,
        os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NOATIME", 0),
    )
    info = os.fstat(descriptor)
    if (
        not stat.S_ISREG(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or info.st_nlink != 1
        or info.st_mode & 0o022
        or info.st_size > maximum_size
    ):
        os.close(descriptor)
        fail("Project runtime repair environment is unsafe")
    return descriptor, info

def read_descriptor(descriptor):
    chunks = []
    total = 0
    while True:
        chunk = os.read(descriptor, min(65536, maximum_size + 1 - total))
        if not chunk:
            break
        chunks.append(chunk)
        total += len(chunk)
        if total > maximum_size:
            fail("Project runtime repair environment exceeds 1 MiB")
    return b"".join(chunks)

def descriptor_xattrs(descriptor):
    values = {}
    for name in os.listxattr(descriptor):
        values[name] = base64.b64encode(os.getxattr(descriptor, name)).decode("ascii")
    return values

def write_private(path, payload):
    descriptor = os.open(
        path,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    try:
        os.fchmod(descriptor, 0o600)
        view = memoryview(payload)
        while view:
            written = os.write(descriptor, view)
            if written <= 0:
                fail("Project runtime repair transaction write stalled")
            view = view[written:]
        os.fsync(descriptor)
    except BaseException:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass
        raise
    finally:
        os.close(descriptor)

def read_private(path, *, limit=maximum_size):
    descriptor = os.open(
        path,
        os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NOATIME", 0),
    )
    try:
        info = os.fstat(descriptor)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != 0
            or info.st_gid != 0
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) != 0o600
            or info.st_size > limit
        ):
            fail("Project runtime repair transaction artifact is unsafe")
        return read_descriptor(descriptor)
    finally:
        os.close(descriptor)

transaction_info = os.lstat(transaction_path)
if (
    not stat.S_ISDIR(transaction_info.st_mode)
    or stat.S_ISLNK(transaction_info.st_mode)
    or transaction_info.st_uid != 0
    or transaction_info.st_gid != 0
    or stat.S_IMODE(transaction_info.st_mode) != 0o700
):
    fail("Project runtime repair transaction directory is unsafe")

original_path = os.path.join(transaction_path, "original.env")
original_meta_path = os.path.join(transaction_path, "original.json")
committed_path = os.path.join(transaction_path, "committed.env")
committed_meta_path = os.path.join(transaction_path, "committed.json")

transaction_artifact_sets = {
    "empty": frozenset(),
    "snapshot": frozenset({"original.env", "original.json"}),
    "staged": frozenset({"original.env", "original.json", "committed.env"}),
    "durable": frozenset({
        "original.env", "original.json", "committed.env", "committed.json"
    }),
}

def fsync_transaction_directory():
    directory_fd = os.open(
        transaction_path,
        os.O_RDONLY | os.O_DIRECTORY | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)

def require_transaction_artifact_set(*allowed_states):
    directory_fd = os.open(
        transaction_path,
        os.O_RDONLY | os.O_DIRECTORY | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        names = os.listdir(directory_fd)
        if len(names) != len(set(names)):
            fail("Project runtime repair transaction artifact inventory is ambiguous")
        observed = frozenset(names)
        state = next(
            (
                candidate
                for candidate in allowed_states
                if observed == transaction_artifact_sets[candidate]
            ),
            None,
        )
        if state is None:
            fail("Project runtime repair transaction has an unexpected artifact set")
        for name in names:
            info = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            if (
                not stat.S_ISREG(info.st_mode)
                or stat.S_ISLNK(info.st_mode)
                or info.st_uid != 0
                or info.st_gid != 0
                or info.st_nlink != 1
                or stat.S_IMODE(info.st_mode) != 0o600
                or info.st_size > maximum_size
            ):
                fail("Project runtime repair transaction artifact is unsafe")
        return state
    finally:
        os.close(directory_fd)

if action not in {
    "snapshot", "commit", "inspect", "reconcile", "recover-commit", "restore"
}:
    fail("Unsupported Project runtime repair transaction action")

if action == "snapshot":
    require_transaction_artifact_set("empty")
    descriptor, before = open_regular(env_path)
    try:
        payload = read_descriptor(descriptor)
        after = os.fstat(descriptor)
        if not identity_matches(after, stat_record(before)):
            fail("Project runtime repair environment changed during snapshot")
        metadata = stat_record(before)
        metadata["sha256"] = hashlib.sha256(payload).hexdigest()
        metadata["xattrs"] = descriptor_xattrs(descriptor)
        metadata["environmentPath"] = env_path
    finally:
        os.close(descriptor)
    write_private(original_path, payload)
    write_private(
        original_meta_path,
        (json.dumps(metadata, sort_keys=True, separators=(",", ":")) + "\n").encode(),
    )
    require_transaction_artifact_set("snapshot")
    fsync_transaction_directory()
    parent_fd = os.open(os.path.dirname(transaction_path), os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(parent_fd)
    finally:
        os.close(parent_fd)
    raise SystemExit(0)

transaction_state = require_transaction_artifact_set(
    "snapshot", "staged", "durable"
)
if action == "commit" and transaction_state != "snapshot":
    fail("Project runtime repair transaction is not ready for commit")
if action == "recover-commit" and transaction_state != "staged":
    fail("Project runtime repair transaction is not a staged commit")
if action == "restore" and transaction_state != "durable":
    fail("Project runtime repair transaction has no durable commit receipt")

try:
    original = read_private(original_path)
    metadata = json.loads(read_private(original_meta_path))
except Exception:
    fail("Project runtime repair snapshot is incomplete")
if hashlib.sha256(original).hexdigest() != metadata.get("sha256"):
    fail("Project runtime repair snapshot checksum is invalid")
if metadata.get("environmentPath") != env_path:
    fail("Project runtime repair snapshot belongs to another environment")

def install_payload(payload, restore_times):
    parent = os.path.dirname(env_path)
    leaf = os.path.basename(env_path)
    parent_fd = os.open(parent, os.O_RDONLY | os.O_DIRECTORY | getattr(os, "O_NOFOLLOW", 0))
    temporary = f".{leaf}.runtime-repair-{secrets.token_hex(12)}"
    descriptor = -1
    try:
        descriptor = os.open(
            temporary,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
            0o600,
            dir_fd=parent_fd,
        )
        os.fchown(descriptor, metadata["uid"], metadata["gid"])
        os.fchmod(descriptor, metadata["mode"])
        for name, encoded in metadata.get("xattrs", {}).items():
            os.setxattr(descriptor, name, base64.b64decode(encoded))
        view = memoryview(payload)
        while view:
            written = os.write(descriptor, view)
            if written <= 0:
                fail("Project runtime repair environment write stalled")
            view = view[written:]
        if restore_times:
            os.utime(
                descriptor,
                ns=(metadata["atime_ns"], metadata["mtime_ns"]),
            )
        os.fsync(descriptor)
        os.close(descriptor)
        descriptor = -1
        os.replace(temporary, leaf, src_dir_fd=parent_fd, dst_dir_fd=parent_fd)
        os.fsync(parent_fd)
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        try:
            os.unlink(temporary, dir_fd=parent_fd)
        except FileNotFoundError:
            pass
        os.close(parent_fd)

if action == "commit":
    if not re.fullmatch(r"sha256:[a-f0-9]{64}", image_id):
        fail("Project runtime repair image identity is invalid")
    descriptor, current_info = open_regular(env_path)
    try:
        current = read_descriptor(descriptor)
    finally:
        os.close(descriptor)
    if not identity_matches(current_info, metadata) or current != original:
        fail("Project runtime repair environment changed before commit")

    lines = original.splitlines(keepends=True)
    matches = []
    for index, line in enumerate(lines):
        body = line.rstrip(b"\r\n")
        if body.startswith(key + b"="):
            matches.append(index)
    if len(matches) > 1:
        fail("Project runtime repair environment contains duplicate image keys")
    replacement = key + b"=" + image_id.encode("ascii")
    if matches:
        index = matches[0]
        ending = lines[index][len(lines[index].rstrip(b"\r\n")):]
        if lines[index].rstrip(b"\r\n") == replacement:
            print("unchanged")
            raise SystemExit(0)
        lines[index] = replacement + ending
        committed = b"".join(lines)
    else:
        separator = b"" if not original or original.endswith((b"\n", b"\r")) else b"\n"
        committed = original + separator + replacement + b"\n"
    write_private(committed_path, committed)
    # The staged payload must be durably discoverable before the installed
    # environment can expose it. A crash after replacement can then always be
    # classified as a recoverable pre-receipt transaction.
    fsync_transaction_directory()
    require_transaction_artifact_set("staged")
    install_payload(committed, False)
    test_hook = os.environ.get("BRIDGESLLM_PROJECT_RUNTIME_REPAIR_TEST_HOOK")
    if (
        os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
        and test_hook == "pause-after-replace-before-receipt"
    ):
        marker = os.environ.get("BRIDGESLLM_PROJECT_RUNTIME_REPAIR_TEST_MARKER", "")
        if not marker or not os.path.isabs(marker):
            fail("Project runtime repair signal-test marker is invalid")
        write_private(marker, b"replaced\n")
        time.sleep(300)
    if (
        os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
        and test_hook == "commit-after-replace"
    ):
        fail("Injected Project runtime repair failure after environment replacement")
    descriptor, committed_info = open_regular(env_path)
    try:
        installed = read_descriptor(descriptor)
    finally:
        os.close(descriptor)
    if installed != committed:
        # Best-effort immediate restoration before reporting a failed commit.
        install_payload(original, True)
        fail("Project runtime repair environment commit did not verify")
    committed_metadata = stat_record(committed_info)
    committed_metadata["sha256"] = hashlib.sha256(committed).hexdigest()
    write_private(
        committed_meta_path,
        (json.dumps(committed_metadata, sort_keys=True, separators=(",", ":")) + "\n").encode(),
    )
    require_transaction_artifact_set("durable")
    fsync_transaction_directory()
    print("changed")
    raise SystemExit(0)

def original_visible(info, payload, xattrs):
    return (
        payload == original
        and stat.S_IMODE(info.st_mode) == metadata["mode"]
        and info.st_uid == metadata["uid"]
        and info.st_gid == metadata["gid"]
        and info.st_nlink == metadata["nlink"]
        and info.st_atime_ns == metadata["atime_ns"]
        and info.st_mtime_ns == metadata["mtime_ns"]
        and xattrs == metadata.get("xattrs", {})
    )

def read_current():
    descriptor, info = open_regular(env_path)
    try:
        payload = read_descriptor(descriptor)
        xattrs = descriptor_xattrs(descriptor)
    finally:
        os.close(descriptor)
    return info, payload, xattrs

def verify_restored_original(message):
    info, payload, xattrs = read_current()
    if not original_visible(info, payload, xattrs):
        fail(message)

if action in {"inspect", "reconcile"}:
    committed_exists = transaction_state in {"staged", "durable"}
    receipt_exists = transaction_state == "durable"

    current_info, current, current_xattrs = read_current()
    if not committed_exists:
        if not original_visible(current_info, current, current_xattrs):
            fail("Project runtime repair snapshot no longer matches the installed environment")
        print("snapshot")
        raise SystemExit(0)

    try:
        committed = read_private(committed_path)
    except Exception:
        fail("Project runtime repair staged commit is incomplete")

    if not receipt_exists:
        if current == committed:
            if action == "reconcile":
                install_payload(original, True)
        elif not original_visible(current_info, current, current_xattrs):
            fail("Project runtime repair environment is neither the original nor staged commit")
        if action == "reconcile":
            verify_restored_original(
                "Project runtime repair pre-receipt recovery did not verify"
            )
        print("staged")
        raise SystemExit(0)

    try:
        committed_metadata = json.loads(read_private(committed_meta_path))
    except Exception:
        fail("Project runtime repair commit receipt is incomplete")
    if hashlib.sha256(committed).hexdigest() != committed_metadata.get("sha256"):
        fail("Project runtime repair committed payload checksum is invalid")
    if current == committed:
        if not identity_matches(current_info, committed_metadata):
            fail("Project runtime repair committed environment changed after receipt")
        if action == "reconcile":
            install_payload(original, True)
    elif not original_visible(current_info, current, current_xattrs):
        fail("Project runtime repair durable commit no longer matches the installed environment")
    if action == "reconcile":
        verify_restored_original(
            "Project runtime repair durable-commit recovery did not verify"
        )
    print("durable")
    raise SystemExit(0)

if action == "recover-commit":
    try:
        committed = read_private(committed_path)
    except Exception:
        fail("Project runtime repair staged commit is incomplete")
    descriptor, current_info = open_regular(env_path)
    try:
        current = read_descriptor(descriptor)
        current_xattrs = descriptor_xattrs(descriptor)
    finally:
        os.close(descriptor)
    if current == committed:
        install_payload(original, True)
    elif current == original:
        if (
            stat.S_IMODE(current_info.st_mode) != metadata["mode"]
            or current_info.st_uid != metadata["uid"]
            or current_info.st_gid != metadata["gid"]
            or current_info.st_atime_ns != metadata["atime_ns"]
            or current_info.st_mtime_ns != metadata["mtime_ns"]
            or current_xattrs != metadata.get("xattrs", {})
        ):
            fail("Project runtime repair original environment metadata changed during failed commit")
    else:
        fail("Project runtime repair environment is neither the original nor staged commit")
    descriptor, restored_info = open_regular(env_path)
    try:
        restored = read_descriptor(descriptor)
        restored_xattrs = descriptor_xattrs(descriptor)
    finally:
        os.close(descriptor)
    if (
        restored != original
        or stat.S_IMODE(restored_info.st_mode) != metadata["mode"]
        or restored_info.st_uid != metadata["uid"]
        or restored_info.st_gid != metadata["gid"]
        or restored_info.st_atime_ns != metadata["atime_ns"]
        or restored_info.st_mtime_ns != metadata["mtime_ns"]
        or restored_xattrs != metadata.get("xattrs", {})
    ):
        fail("Project runtime repair failed-commit recovery did not verify")
    raise SystemExit(0)

if action == "restore":
    try:
        committed = read_private(committed_path)
        committed_metadata = json.loads(read_private(committed_meta_path))
    except Exception:
        fail("Project runtime repair commit receipt is incomplete")
    descriptor, current_info = open_regular(env_path)
    try:
        current = read_descriptor(descriptor)
    finally:
        os.close(descriptor)
    if (
        not identity_matches(current_info, committed_metadata)
        or current != committed
        or hashlib.sha256(current).hexdigest() != committed_metadata.get("sha256")
    ):
        fail("Project runtime repair environment changed after commit; refusing to overwrite it")
    install_payload(original, True)
    descriptor, restored_info = open_regular(env_path)
    try:
        restored = read_descriptor(descriptor)
        restored_xattrs = descriptor_xattrs(descriptor)
    finally:
        os.close(descriptor)
    if (
        restored != original
        or stat.S_IMODE(restored_info.st_mode) != metadata["mode"]
        or restored_info.st_uid != metadata["uid"]
        or restored_info.st_gid != metadata["gid"]
        or restored_info.st_atime_ns != metadata["atime_ns"]
        or restored_info.st_mtime_ns != metadata["mtime_ns"]
        or restored_xattrs != metadata.get("xattrs", {})
    ):
        fail("Project runtime repair environment rollback did not verify")
    raise SystemExit(0)

fail("Unsupported Project runtime repair transaction action")
PY
}

write_portal_project_runtime_dockerfile() {
  local target="$1"
  cat > "${target}" <<'PROJECT_RUNTIME_DOCKERFILE'
FROM node:22.16.0-bookworm-slim
ARG PORTAL_RECIPE_SHA256
LABEL com.bridgesllm.portal-project-runtime.recipe-sha256="${PORTAL_RECIPE_SHA256}"
ENV DEBIAN_FRONTEND=noninteractive
RUN apt-get update \
  && apt-get install -y --no-install-recommends \
    bash \
    build-essential \
    ca-certificates \
    git \
    python3 \
    python3-pip \
    python3-venv \
  && rm -rf /var/lib/apt/lists/*
USER 1000:1000
WORKDIR /workspace/project
# The sandbox attestation requires a bare image: the runtime container's
# command is pinned at create time and the base image's docker-entrypoint.sh
# must not run.
ENTRYPOINT []
CMD ["node", "--version"]
PROJECT_RUNTIME_DOCKERFILE
}

verify_portal_project_runtime_image() {
  local image="$1" expected_recipe="$2" existing_entrypoint=""
  [[ "${expected_recipe}" =~ ^[a-f0-9]{64}$ ]] || return 1
  valid_docker_image_id "$(docker_image_id "${image}" || true)" || return 1
  [[ "$(docker_image_label "${image}" "${PORTAL_PROJECT_RUNTIME_RECIPE_LABEL}" || true)" \
    == "${expected_recipe}" ]] || return 1
  existing_entrypoint="$(
    docker image inspect --format '{{len .Config.Entrypoint}}' \
      "${image}" 2>/dev/null || echo 1
  )"
  [[ "${existing_entrypoint}" == "0" ]] || return 1
  docker run --rm --entrypoint sh "${image}" -lc \
    'test "$(id -u)" = 1000 && test "$(id -g)" = 1000 && node --version >/dev/null 2>&1 && npm --version >/dev/null 2>&1 && python3 --version >/dev/null 2>&1 && python3 -m venv --help >/dev/null 2>&1 && command -v g++ >/dev/null 2>&1 && command -v make >/dev/null 2>&1' \
    >> "${LOG_FILE}" 2>&1
}

ensure_portal_project_runtime_image() {
  local image="${1:-${PORTAL_PROJECT_RUNTIME_IMAGE_TAG}}"
  local prepared_env_file="${2:-}"
  local may_start_docker="${3:-true}"
  if ! command -v docker &>/dev/null; then
    fail "Docker is required for isolated project installs, builds, and full-stack apps."
  fi
  valid_local_image_tag "${image}" \
    || fail "Portal project runtime image tag is invalid."
  if [[ -n "${prepared_env_file}" ]]; then
    [[ -f "${prepared_env_file}" && ! -L "${prepared_env_file}" ]] \
      || fail "Prepared Project runtime environment is unavailable."
  fi

  local build_dir recipe_fingerprint
  build_dir="$(mktemp -d)"
  write_portal_project_runtime_dockerfile "${build_dir}/Dockerfile" \
    || { rm -rf -- "${build_dir}"; fail "Canonical Project runtime recipe could not be staged."; }
  recipe_fingerprint="$(sha256sum "${build_dir}/Dockerfile" | awk '{print $1}')"
  [[ "${recipe_fingerprint}" =~ ^[a-f0-9]{64}$ ]] \
    || { rm -rf -- "${build_dir}"; fail "Canonical Project runtime recipe fingerprint is invalid."; }
  PORTAL_PROJECT_RUNTIME_RECIPE_SHA256="${recipe_fingerprint}"

  if [[ "${may_start_docker}" == "true" ]]; then
    systemctl start docker >> "$LOG_FILE" 2>&1 || true
  elif [[ "${may_start_docker}" == "false" ]]; then
    systemctl is-active --quiet docker \
      || fail "Docker must already be active before Project runtime image repair."
  else
    fail "Project runtime Docker-management mode is invalid."
  fi

  local image_ready=false
  if docker image inspect "$image" >/dev/null 2>&1; then
    if verify_portal_project_runtime_image "${image}" "${recipe_fingerprint}"; then
      ok "Portal project runtime image"
      image_ready=true
    else
      warn "Existing Portal project runtime image is incomplete; rebuilding."
    fi
  fi

  if ! ${image_ready}; then
    if ! spin "Building isolated Portal project runtime" \
      "docker build --tag '${image}' --build-arg 'PORTAL_RECIPE_SHA256=${recipe_fingerprint}' '${build_dir}'"; then
      rm -rf "$build_dir"
      fail "Failed to build ${image}. Project code execution remains disabled."
    fi
  fi

  if ! verify_portal_project_runtime_image "${image}" "${recipe_fingerprint}"; then
    rm -rf -- "${build_dir}"
    fail "Built ${image}, but its required project tools are unavailable."
  fi
  rm -rf -- "${build_dir}"

  local image_id
  image_id="$(docker_image_id "${image}" || true)"
  valid_docker_image_id "${image_id}" \
    || fail "Portal project runtime image did not resolve to an immutable Docker image ID."
  if [[ -n "${prepared_env_file}" ]]; then
    set_env_value_atomic \
      "${prepared_env_file}" "PORTAL_PROJECT_RUNTIME_IMAGE_ID" "${image_id}" \
      || fail "Portal project runtime image ID could not be recorded for update cutover."
  fi
  ok "Portal project runtime image"
}

project_runtime_repair_transaction_root() {
  local root="/run"
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && -n "${BRIDGESLLM_PROJECT_RUNTIME_REPAIR_TEST_ROOT:-}" ]]; then
    root="${BRIDGESLLM_PROJECT_RUNTIME_REPAIR_TEST_ROOT}"
  fi
  python3 - "${root}" <<'PY'
import os
import stat
import sys

root = sys.argv[1]
if not os.path.isabs(root) or os.path.normpath(root) != root:
    raise SystemExit("Project runtime repair transaction root is not canonical")
descriptor = os.open(root, os.O_RDONLY | os.O_DIRECTORY | getattr(os, "O_NOFOLLOW", 0))
try:
    info = os.fstat(descriptor)
    if (
        not stat.S_ISDIR(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or info.st_mode & 0o022
    ):
        raise SystemExit("Project runtime repair transaction root is unsafe")
finally:
    os.close(descriptor)
print(root)
PY
}

cleanup_project_runtime_image_repair_transaction() {
  local directory="${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR:-}"
  local root="${PROJECT_RUNTIME_REPAIR_TRANSACTION_ROOT:-}"
  [[ -n "${directory}" ]] || return 0
  [[ -n "${root}" \
    && "$(dirname -- "${directory}")" == "${root}" \
    && "$(basename -- "${directory}")" \
      =~ ^bridgesllm-project-runtime-image-repair\.[A-Za-z0-9]{8}$ \
    && -d "${directory}" && ! -L "${directory}" ]] || return 1
  rm -rf -- "${directory}" || return 1
  [[ ! -e "${directory}" && ! -L "${directory}" ]] || return 1
  python3 - "${root}" <<'PY' || return 1
import os
import sys
descriptor = os.open(sys.argv[1], os.O_RDONLY | os.O_DIRECTORY | getattr(os, "O_NOFOLLOW", 0))
try:
    os.fsync(descriptor)
finally:
    os.close(descriptor)
PY
  PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR=""
}

settle_project_runtime_image_repair_child() {
  local pid="${PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID:-}"
  local current child index
  local -a pending=() descendants=()
  [[ -n "${pid}" ]] || return 0
  [[ "${pid}" =~ ^[1-9][0-9]*$ ]] || return 1
  pending=("${pid}")
  index=0
  while (( index < ${#pending[@]} )); do
    current="${pending[index]}"
    index=$((index + 1))
    if [[ -r "/proc/${current}/task/${current}/children" ]]; then
      for child in $(<"/proc/${current}/task/${current}/children"); do
        [[ "${child}" =~ ^[1-9][0-9]*$ ]] || continue
        descendants+=("${child}")
        pending+=("${child}")
      done
    fi
  done
  if (( ${#descendants[@]} > 0 )); then
    kill -TERM "${descendants[@]}" >/dev/null 2>&1 || true
  fi
  kill -TERM "${pid}" >/dev/null 2>&1 || true
  for _ in {1..50}; do
    kill -0 "${pid}" >/dev/null 2>&1 || break
    sleep 0.02
  done
  if kill -0 "${pid}" >/dev/null 2>&1; then
    if (( ${#descendants[@]} > 0 )); then
      kill -KILL "${descendants[@]}" >/dev/null 2>&1 || true
    fi
    kill -KILL "${pid}" >/dev/null 2>&1 || true
  fi
  wait "${pid}" >/dev/null 2>&1 || true
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID=""
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_KIND=""
}

run_project_runtime_repair_environment_commit() {
  local env_file="$1" transaction_dir="$2" image_id="$3" status=0
  (
    trap - EXIT ERR SIGINT SIGTERM SIGHUP
    project_runtime_repair_environment_transaction \
      commit "${env_file}" "${transaction_dir}" "${image_id}"
  ) >> "${PROJECT_RUNTIME_REPAIR_ACTIVE_LOG_FILE:-${LOG_FILE}}" 2>&1 &
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID=$!
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_KIND="environment-commit"
  if wait "${PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID}"; then
    status=0
  else
    status=$?
  fi
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID=""
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_KIND=""
  return "${status}"
}

run_project_runtime_repair_portal_restart() {
  local status=0
  (
    trap - EXIT ERR SIGINT SIGTERM SIGHUP
    systemctl restart bridgesllm-product.service
  ) >> "${PROJECT_RUNTIME_REPAIR_ACTIVE_LOG_FILE:-${LOG_FILE}}" 2>&1 &
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID=$!
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_KIND="portal-restart"
  if wait "${PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID}"; then
    status=0
  else
    status=$?
  fi
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID=""
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_KIND=""
  return "${status}"
}

rollback_project_runtime_image_repair() {
  local outcome=""
  [[ -n "${PROJECT_RUNTIME_REPAIR_ENV_FILE:-}" \
    && -n "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR:-}" ]] || return 1
  outcome="$(
    project_runtime_repair_environment_transaction \
      reconcile \
      "${PROJECT_RUNTIME_REPAIR_ENV_FILE}" \
      "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR}"
  )" || return 1
  case "${outcome}" in
    snapshot|staged)
      return 0
      ;;
    durable)
      systemctl restart bridgesllm-product.service \
        >> "${PROJECT_RUNTIME_REPAIR_ACTIVE_LOG_FILE:-${LOG_FILE}}" 2>&1 \
        || return 1
      verify_project_runtime_repair_health \
        bridgesllm-product.service http://127.0.0.1:4001/health 60 \
        || return 1
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

recover_pending_project_runtime_image_repair() {
  local installed_env="$1" root="$2" pending="" outcome=""
  local -a candidates=()
  shopt -s nullglob
  candidates=("${root}"/bridgesllm-project-runtime-image-repair.*)
  shopt -u nullglob
  (( ${#candidates[@]} <= 1 )) \
    || fail "Multiple interrupted Project runtime image repairs exist; refusing to guess recovery order."
  (( ${#candidates[@]} == 1 )) || return 0
  pending="${candidates[0]}"
  [[ -d "${pending}" && ! -L "${pending}" \
    && "$(basename -- "${pending}")" \
      =~ ^bridgesllm-project-runtime-image-repair\.[A-Za-z0-9]{8}$ ]] \
    || fail "An interrupted Project runtime image repair transaction is unsafe."
  PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR="${pending}"
  PROJECT_RUNTIME_REPAIR_TRANSACTION_ROOT="${root}"
  PROJECT_RUNTIME_REPAIR_ENV_FILE="${installed_env}"
  outcome="$(
    project_runtime_repair_environment_transaction \
      inspect "${installed_env}" "${pending}"
  )" || fail "An interrupted Project runtime image repair could not be inspected safely. Its transaction was preserved."
  rollback_project_runtime_image_repair \
    || fail "An interrupted Project runtime image repair could not be reconciled safely. Its transaction was preserved."
  cleanup_project_runtime_image_repair_transaction \
    || fail "A reconciled Project runtime image repair transaction could not be removed."
  info "Recovered interrupted Project runtime image repair (${outcome})."
}

abort_project_runtime_image_repair_after_commit() {
  local message="$1"
  trap '' SIGINT TERM HUP
  trap - ERR
  set +e
  if rollback_project_runtime_image_repair; then
    if cleanup_project_runtime_image_repair_transaction; then
      fail "${message} The exact previous environment was restored and Portal is healthy on it."
    fi
    trap - EXIT
    echo -e "  ${RED}${BOLD}Project runtime image repair rollback verified, but its transaction cleanup did not.${NC}" >&2
    echo -e "  ${RED}The root-only transaction was preserved for the next locked repair.${NC}" >&2
    exit 1
  fi
  trap - EXIT
  echo "" >&2
  echo -e "  ${RED}${BOLD}Project runtime image repair failed after environment commit.${NC}" >&2
  echo -e "  ${RED}${message}${NC}" >&2
  echo -e "  ${RED}Automatic environment/service recovery did not verify. The root-only repair log and transaction state require manual inspection.${NC}" >&2
  exit 1
}

handle_project_runtime_image_repair_exit() {
  local exit_code="${1:-1}"
  trap - EXIT ERR SIGINT SIGTERM SIGHUP
  set +e
  settle_project_runtime_image_repair_child >/dev/null 2>&1 || true
  if [[ -n "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR:-}" ]]; then
    if rollback_project_runtime_image_repair; then
      if ! cleanup_project_runtime_image_repair_transaction >/dev/null 2>&1; then
        echo -e "  ${RED}${BOLD}Project runtime image repair transaction cleanup did not verify; its root-only state was preserved.${NC}" >&2
        exit_code=1
      fi
    else
      echo -e "  ${RED}${BOLD}Project runtime image repair exit recovery did not verify; its root-only transaction was preserved.${NC}" >&2
      exit_code=1
    fi
  fi
  [[ "${exit_code}" =~ ^[0-9]+$ ]] || exit_code=1
  (( exit_code != 0 )) || exit_code=1
  exit "${exit_code}"
}

handle_project_runtime_image_repair_signal() {
  local exit_code="$1" label="$2"
  trap '' SIGINT TERM HUP
  trap - ERR
  set +e
  settle_project_runtime_image_repair_child >/dev/null 2>&1 || true
  if [[ -n "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR:-}" ]] \
    && ! rollback_project_runtime_image_repair; then
    trap - EXIT
    echo -e "  ${RED}${BOLD}${label}; automatic repair rollback did not verify and the root-only transaction was preserved.${NC}" >&2
    exit "${exit_code}"
  fi
  if ! cleanup_project_runtime_image_repair_transaction >/dev/null 2>&1; then
    trap - EXIT
    echo -e "  ${RED}${BOLD}${label}; rollback verified but transaction cleanup did not. Root-only recovery state was preserved.${NC}" >&2
    exit "${exit_code}"
  fi
  echo -e "  ${RED}${label}.${NC}" >&2
  exit "${exit_code}"
}

handle_project_runtime_image_repair_err() {
  local exit_code="${1:-1}" line="${2:-unknown}"
  [[ "${exit_code}" =~ ^[1-9][0-9]*$ ]] || exit_code=1
  handle_project_runtime_image_repair_signal \
    "${exit_code}" "Unexpected Project runtime image repair error at line ${line}"
}

repair_project_runtime_image() {
  local installed_script="${PORTAL_DIR}/installer/install.sh"
  local installed_env="${PORTAL_DIR}/backend/.env.production"
  local source_only="${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}"
  local repair_log_file="${LOG_FILE}" repair_log_dir="${LOG_DIR}"
  local image_id="" commit_state="" transaction_root=""

  if (( $# > 0 )); then
    [[ "${source_only}" == "1" && $# -eq 3 ]] \
      || fail "Project runtime repair authority paths cannot be overridden."
    installed_script="$1"
    installed_env="$2"
    repair_log_file="$3"
    repair_log_dir="$(dirname -- "${repair_log_file}")"
  fi

  CURRENT_STEP="Project runtime image repair"
  attest_project_runtime_image_repair_authority \
    "${installed_script}" "${installed_env}" "${BASH_SOURCE[0]}" \
    || fail "The installed repair script or production environment failed root authority attestation."

  mkdir -p "${repair_log_dir}"
  touch "${repair_log_file}"
  chmod 0600 "${repair_log_file}"
  PROJECT_RUNTIME_REPAIR_ACTIVE_LOG_FILE="${repair_log_file}"

  transaction_root="$(project_runtime_repair_transaction_root)" \
    || fail "The Project runtime repair transaction root failed authority attestation."
  PROJECT_RUNTIME_REPAIR_TRANSACTION_ROOT="${transaction_root}"
  PROJECT_RUNTIME_REPAIR_ENV_FILE="${installed_env}"
  PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR=""
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_PID=""
  PROJECT_RUNTIME_REPAIR_ACTIVE_CHILD_KIND=""
  trap 'handle_project_runtime_image_repair_exit $?' EXIT
  trap 'handle_project_runtime_image_repair_err $? $LINENO' ERR
  trap 'handle_project_runtime_image_repair_signal 130 "Project runtime image repair was interrupted"' SIGINT
  trap 'handle_project_runtime_image_repair_signal 143 "Project runtime image repair was terminated"' SIGTERM
  trap 'handle_project_runtime_image_repair_signal 129 "Project runtime image repair session disconnected"' SIGHUP

  # Holding the shared installer lock makes this the sole repair authority.
  # Reconcile a hard-killed predecessor before image inspection or any
  # idempotent no-restart decision can observe its staged environment.
  recover_pending_project_runtime_image_repair \
    "${installed_env}" "${transaction_root}"

  converge_unsafe_docker_prune_automation \
    || fail "Unsafe scheduled Docker cleanup remains active. Repair it before rebuilding a pinned Project runtime image."
  verify_project_runtime_repair_health \
    bridgesllm-product.service http://127.0.0.1:4001/health 10 \
    || fail "Portal must be healthy before Project runtime image repair begins."

  PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR="$(
    mktemp -d "${transaction_root}/bridgesllm-project-runtime-image-repair.XXXXXXXX"
  )" || fail "A private Project runtime repair transaction directory could not be created."
  chmod 0700 "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR}" \
    || fail "The Project runtime repair transaction could not be made private."

  project_runtime_repair_environment_transaction \
    snapshot "${installed_env}" "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR}" \
    || fail "The exact installed Portal environment could not be snapshotted before repair."
  parse_strict_systemd_environment_file \
    "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR}/original.env" \
    || fail "The installed Portal environment is not a strict systemd environment file."

  # Docker must already be active. This mode never starts or restarts Docker,
  # optional provider tools, Caddy, OpenClaw, or any other managed service.
  ensure_portal_project_runtime_image \
    "${PORTAL_PROJECT_RUNTIME_IMAGE_TAG}" "" false
  image_id="$(docker_image_id "${PORTAL_PROJECT_RUNTIME_IMAGE_TAG}" || true)"
  valid_docker_image_id "${image_id}" \
    || fail "The repaired Project runtime tag did not resolve to an immutable image ID."
  [[ "$(docker_image_id "${image_id}" || true)" == "${image_id}" ]] \
    || fail "The repaired Project runtime image ID did not resolve exactly."
  [[ "${PORTAL_PROJECT_RUNTIME_RECIPE_SHA256}" =~ ^[a-f0-9]{64}$ ]] \
    || fail "The canonical Project runtime recipe fingerprint was not retained."
  verify_portal_project_runtime_image \
    "${image_id}" "${PORTAL_PROJECT_RUNTIME_RECIPE_SHA256}" \
    || fail "The repaired immutable Project runtime image failed runtime attestation."

  if ! run_project_runtime_repair_environment_commit \
      "${installed_env}" "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR}" \
      "${image_id}"; then
    if rollback_project_runtime_image_repair; then
      if cleanup_project_runtime_image_repair_transaction; then
        fail "The Project runtime image ID commit failed; the exact previous environment was restored before any service restart."
      fi
      trap - EXIT
      echo -e "  ${RED}${BOLD}The failed Project runtime image commit was rolled back, but transaction cleanup did not verify.${NC}" >&2
      echo -e "  ${RED}The root-only transaction was preserved for the next locked repair; Portal was not restarted.${NC}" >&2
      exit 1
    fi
    trap - EXIT
    echo -e "  ${RED}${BOLD}Project runtime image environment commit failed and recovery could not be verified.${NC}" >&2
    echo -e "  ${RED}The root-only repair transaction was preserved for automatic recovery by the next locked repair; Portal was not restarted.${NC}" >&2
    exit 1
  fi
  commit_state="$(
    project_runtime_repair_environment_transaction \
      inspect "${installed_env}" "${PROJECT_RUNTIME_REPAIR_TRANSACTION_DIR}"
  )" || abort_project_runtime_image_repair_after_commit \
    "The durable Project runtime image environment state could not be verified."
  case "${commit_state}" in
    snapshot)
      verify_project_runtime_repair_health \
        bridgesllm-product.service http://127.0.0.1:4001/health 10 \
        || fail "Portal became unhealthy during an idempotent Project runtime image repair."
      cleanup_project_runtime_image_repair_transaction \
        || fail "The completed Project runtime repair transaction could not be removed."
      trap - EXIT
      ok "Project runtime image was already repaired ${DIM}(${image_id:0:19}…)${NC}"
      return 0
      ;;
    durable)
      ;;
    *)
      abort_project_runtime_image_repair_after_commit \
        "Project runtime image repair returned an invalid durable environment state."
      ;;
  esac

  if [[ "${source_only}" == "1" \
    && "${BRIDGESLLM_PROJECT_RUNTIME_REPAIR_TEST_HOOK:-}" \
      == "pause-after-receipt-before-restart" ]]; then
    [[ -n "${BRIDGESLLM_PROJECT_RUNTIME_REPAIR_TEST_MARKER:-}" ]] \
      || abort_project_runtime_image_repair_after_commit \
        "The Project runtime repair signal-test marker is invalid."
    printf '%s\n' 'receipt' \
      > "${BRIDGESLLM_PROJECT_RUNTIME_REPAIR_TEST_MARKER}"
    chmod 0600 "${BRIDGESLLM_PROJECT_RUNTIME_REPAIR_TEST_MARKER}"
    while :; do sleep 0.05; done
  fi

  if ! run_project_runtime_repair_portal_restart; then
    abort_project_runtime_image_repair_after_commit \
      "Portal could not restart with the repaired Project runtime image."
  fi
  if ! verify_project_runtime_repair_health \
      bridgesllm-product.service http://127.0.0.1:4001/health 60; then
    abort_project_runtime_image_repair_after_commit \
      "Portal did not become healthy with the repaired Project runtime image."
  fi

  cleanup_project_runtime_image_repair_transaction \
    || fail "The completed Project runtime repair transaction could not be removed."
  trap - EXIT
  ok "Project runtime image repaired ${DIM}(${image_id:0:19}…)${NC}"
}

update_project_runtime_prepared_env_path() {
  local stage_dir="$1"
  [[ -d "${stage_dir}" && ! -L "${stage_dir}" ]] || return 1
  printf '%s/project-runtimes.prepared.env\n' "${stage_dir}"
}

update_project_runtime_preparation_mode_path() {
  local stage_dir="$1"
  [[ -d "${stage_dir}" && ! -L "${stage_dir}" ]] || return 1
  printf '%s/project-runtimes.preparation-mode-v1\n' "${stage_dir}"
}

write_update_project_runtime_preparation_mode() {
  local stage_dir="$1" transaction_id="$2" mode="$3" marker
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ \
    && ( "${mode}" == "disabled" || "${mode}" == "docker" ) ]] \
    || return 1
  marker="$(update_project_runtime_preparation_mode_path "${stage_dir}")" \
    || return 1
  python3 - "${stage_dir}" "${marker}" "${transaction_id}" "${mode}" <<'PY'
import os
import secrets
import stat
import sys

directory, path, transaction_id, mode = sys.argv[1:]
details = os.lstat(directory)
if (
    not stat.S_ISDIR(details.st_mode)
    or stat.S_ISLNK(details.st_mode)
    or details.st_uid != os.geteuid()
    or details.st_gid != os.getegid()
    or stat.S_IMODE(details.st_mode) != 0o700
    or os.path.dirname(path) != directory
):
    raise SystemExit(1)
payload = f"v1:{transaction_id}:{mode}\n".encode("ascii")
if os.path.lexists(path):
    raise SystemExit(1)
temporary = os.path.join(
    directory,
    f".project-runtime-preparation-mode.{os.getpid()}.{secrets.token_hex(8)}",
)
fd = -1
try:
    fd = os.open(
        temporary,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    os.write(fd, payload)
    os.fchmod(fd, 0o600)
    os.fsync(fd)
    info = os.fstat(fd)
    if (
        not stat.S_ISREG(info.st_mode)
        or info.st_uid != os.geteuid()
        or info.st_gid != os.getegid()
        or stat.S_IMODE(info.st_mode) != 0o600
        or info.st_nlink != 1
        or info.st_size != len(payload)
    ):
        raise SystemExit(1)
    os.close(fd)
    fd = -1
    if os.path.lexists(path):
        raise SystemExit(1)
    os.rename(temporary, path)
finally:
    if fd >= 0:
        os.close(fd)
    try:
        os.unlink(temporary)
    except FileNotFoundError:
        pass
directory_fd = os.open(
    directory,
    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
)
try:
    os.fsync(directory_fd)
finally:
    os.close(directory_fd)
PY
}

read_update_project_runtime_preparation_mode() {
  local stage_dir="$1" transaction_id="$2" marker
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ ]] || return 1
  marker="$(update_project_runtime_preparation_mode_path "${stage_dir}")" \
    || return 1
  python3 - "${marker}" "${transaction_id}" <<'PY'
import os
import stat
import sys

path, transaction_id = sys.argv[1:]
flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
fd = os.open(path, flags)
try:
    details = os.fstat(fd)
    if (
        not stat.S_ISREG(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_gid != os.getegid()
        or stat.S_IMODE(details.st_mode) != 0o600
        or details.st_nlink != 1
        or not 1 <= details.st_size <= 96
    ):
        raise SystemExit(1)
    chunks = []
    remaining = 97
    while remaining:
        chunk = os.read(fd, remaining)
        if not chunk:
            break
        chunks.append(chunk)
        remaining -= len(chunk)
    raw = b"".join(chunks)
    after = os.fstat(fd)
    if (
        (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
        != (details.st_dev, details.st_ino, details.st_size, details.st_mtime_ns)
        or len(raw) != details.st_size
    ):
        raise SystemExit(1)
finally:
    os.close(fd)
for mode in ("disabled", "docker"):
    if raw == f"v1:{transaction_id}:{mode}\n".encode("ascii"):
        print(mode)
        raise SystemExit(0)
raise SystemExit(1)
PY
}

update_project_runtime_staging_tag() {
  local transaction_id="$1" component="$2"
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ ]] || return 1
  case "${component}" in
    egress|codex|claude|antigravity|ollama|agent-zero|openclaw|portal)
      ;;
    *)
      return 1
      ;;
  esac
  printf 'bridgesllm-update-%s-%s:candidate\n' \
    "${transaction_id}" "${component}"
}

validate_prepared_update_project_runtime_environment() {
  local prepared_env="$1" expected_transaction_id="$2"
  local expected_owner="$(id -u):$(id -g):600:1"
  [[ "${expected_transaction_id}" =~ ^[a-f0-9]{32}$ \
    && -f "${prepared_env}" && ! -L "${prepared_env}" \
    && "$(stat -c '%u:%g:%a:%h' "${prepared_env}")" == "${expected_owner}" ]] \
    || return 1
  assert_env_file_no_duplicate_keys "${prepared_env}" || return 1
  assert_prisma_runtime_environment_safe "${prepared_env}" || return 1
  [[ "$(read_env_value \
      "${prepared_env}" BRIDGESLLM_UPDATE_PROJECT_RUNTIMES_PREPARED || true)" \
      == "1" \
    && "$(read_env_value \
      "${prepared_env}" BRIDGESLLM_UPDATE_PROJECT_RUNTIME_TRANSACTION_ID || true)" \
      == "${expected_transaction_id}" ]] || return 1

  local policy key value
  policy="$(read_env_value \
    "${prepared_env}" PROJECT_RUNTIME_CONFINEMENT_POLICY || true)"
  case "${policy}" in
    "${PROJECT_RUNTIME_APPARMOR_SECCOMP_POLICY}"|\
    "${PROJECT_RUNTIME_SECCOMP_ONLY_POLICY}")
      for key in \
        PROJECT_EGRESS_PROXY_IMAGE_ID \
        CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID \
        OLLAMA_PROJECT_SANDBOX_IMAGE_ID \
        AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID \
        PORTAL_PROJECT_RUNTIME_IMAGE_ID; do
        value="$(read_env_value "${prepared_env}" "${key}" || true)"
        valid_docker_image_id "${value}" || return 1
      done
      for key in \
        CODEX_PROJECT_SANDBOX_IMAGE_ID \
        ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID \
        OPENCLAW_PROJECT_SANDBOX_IMAGE_ID; do
        value="$(read_env_value "${prepared_env}" "${key}" || true)"
        [[ -z "${value}" ]] || valid_docker_image_id "${value}" || return 1
      done
      ;;
    "${PROJECT_RUNTIME_DISABLED_POLICY}")
      ;;
    *)
      return 1
      ;;
  esac
}

prepare_update_project_runtimes() {
  local staged_portal="$1" source_env="$2" transaction_id="$3"
  local stage_dir prepared_env preparation_mode marker
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ \
    && -d "${staged_portal}" && ! -L "${staged_portal}" \
    && -f "${source_env}" && ! -L "${source_env}" ]] \
    || fail "Update Project runtime preparation received an unsafe input."
  stage_dir="$(dirname "${staged_portal}")"
  prepared_env="$(update_project_runtime_prepared_env_path "${stage_dir}")" \
    || fail "Could not resolve the prepared Project runtime environment."
  marker="$(update_project_runtime_preparation_mode_path "${stage_dir}")" \
    || fail "Could not resolve the Project runtime preparation marker."
  [[ ! -e "${prepared_env}" && ! -L "${prepared_env}" \
    && ! -e "${marker}" && ! -L "${marker}" ]] \
    || fail "Prepared Project runtime environment already exists."
  preparation_mode="docker"
  ${SKIP_PROJECT_RUNTIMES} && preparation_mode="disabled"
  write_update_project_runtime_preparation_mode \
    "${stage_dir}" "${transaction_id}" "${preparation_mode}" \
    || fail "Could not durably record the Project runtime preparation mode."
  install -m 0600 "${source_env}" "${prepared_env}" \
    || fail "Could not create the private prepared Project runtime environment."
  [[ "$(stat -c '%u:%g:%a:%h' "${prepared_env}")" \
    == "$(id -u):$(id -g):600:1" ]] \
    || fail "Prepared Project runtime environment has unsafe metadata."
  # This is the durable "preparation started" boundary. No Docker/tag command
  # may move above it: after a crash, absence of this inode proves that no
  # transaction-scoped image tag could have been created.
  sync -f "${prepared_env}" \
    && sync -f "${stage_dir}" \
    || fail "Could not durably record the Project runtime preparation boundary."

  local key
  if ${SKIP_PROJECT_RUNTIMES}; then
    set_env_value_atomic \
      "${prepared_env}" PROJECT_RUNTIME_CONFINEMENT_POLICY \
      "${PROJECT_RUNTIME_DISABLED_POLICY}" \
      || fail "Could not stage the disabled Project runtime policy."
    for key in \
      PROJECT_EGRESS_PROXY_IMAGE_ID \
      CODEX_PROJECT_SANDBOX_IMAGE_ID \
      CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID \
      ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID \
      OLLAMA_PROJECT_SANDBOX_IMAGE_ID \
      AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID \
      OPENCLAW_PROJECT_SANDBOX_IMAGE_ID \
      PORTAL_PROJECT_RUNTIME_IMAGE_ID; do
      set_env_value_atomic "${prepared_env}" "${key}" "" \
        || fail "Could not clear disabled Project runtime identity ${key}."
    done
  else
    # This boundary is deliberately additive. Candidate images receive
    # transaction-specific tags and no prune runs before cutover, so a failed
    # update can restore its old environment while every prior immutable image
    # ID and canonical tag remain runnable. Changed confinement policy must use
    # a new versioned path/name; an in-place replacement fails before downtime.
    ensure_project_runtime_confinement_profiles \
      "${prepared_env}" "${staged_portal}" additive
    ensure_project_egress_proxy_image \
      "${prepared_env}" "${staged_portal}/backend/dist/services" \
      "$(update_project_runtime_staging_tag "${transaction_id}" egress)"
    ensure_codex_project_sandbox_image \
      "${prepared_env}" \
      "$(update_project_runtime_staging_tag "${transaction_id}" codex)"
    ensure_claude_code_project_sandbox_image \
      "${prepared_env}" \
      "$(update_project_runtime_staging_tag "${transaction_id}" claude)"
    ensure_antigravity_project_sandbox_image \
      "${prepared_env}" \
      "$(update_project_runtime_staging_tag "${transaction_id}" antigravity)"
    ensure_ollama_project_sandbox_image \
      "${prepared_env}" \
      "$(update_project_runtime_staging_tag "${transaction_id}" ollama)"
    ensure_agent_zero_project_sandbox_image \
      "${prepared_env}" \
      "$(update_project_runtime_staging_tag "${transaction_id}" agent-zero)" \
      "${staged_portal}/installer/agent-zero-project-sandbox.Dockerfile"
    ensure_openclaw_sandbox_image \
      "${prepared_env}" \
      "$(update_project_runtime_staging_tag "${transaction_id}" openclaw)"
    ensure_portal_project_runtime_image \
      "$(update_project_runtime_staging_tag "${transaction_id}" portal)" \
      "${prepared_env}"
  fi

  set_env_value_atomic \
    "${prepared_env}" BRIDGESLLM_UPDATE_PROJECT_RUNTIME_TRANSACTION_ID \
    "${transaction_id}" \
    && set_env_value_atomic \
      "${prepared_env}" BRIDGESLLM_UPDATE_PROJECT_RUNTIMES_PREPARED 1 \
    || fail "Could not seal the prepared Project runtime environment."
  sync -f "${prepared_env}" \
    && sync -f "${stage_dir}" \
    || fail "Could not durably seal the prepared Project runtime environment."
  validate_prepared_update_project_runtime_environment \
    "${prepared_env}" "${transaction_id}" \
    || fail "Prepared Project runtime identities failed validation."
}

run_staged_portal_rebootability_preflight() {
  local staged_portal="$1" source_env="$2" plan_file="${3:-}"
  local backend_dir="${staged_portal}/backend"
  local preflight="${backend_dir}/dist/cli/portalRebootabilityPreflight.js"
  local -a arguments=(--env-file "${source_env}")
  if [[ -n "${plan_file}" ]]; then
    [[ "${plan_file}" == /* && ! -e "${plan_file}" && ! -L "${plan_file}" ]] \
      || return 1
    arguments+=(--plan-file "${plan_file}")
  fi
  [[ -d "${backend_dir}" && ! -L "${backend_dir}" \
    && -f "${preflight}" && ! -L "${preflight}" \
    && -f "${source_env}" && ! -L "${source_env}" ]] \
    || return 1
  [[ "$(stat -c '%u:%g:%h' "${preflight}")" == "0:0:1" \
    && "$(stat -c '%u:%g:%h' "${source_env}")" == "0:0:1" \
    && $((8#$(stat -c '%a' "${preflight}") & 0022)) -eq 0 \
    && $((8#$(stat -c '%a' "${source_env}") & 0022)) -eq 0 ]] \
    || return 1
  (
    cd "${backend_dir}"
    /usr/bin/node "${preflight}" "${arguments[@]}"
  ) >> "${LOG_FILE}" 2>&1
}

run_staged_portal_continuity_repair() {
  local staged_portal="$1" source_env="$2" plan_file="$3"
  local backend_dir="${staged_portal}/backend"
  local repair="${backend_dir}/dist/cli/portalContinuityRepair.js"
  [[ -d "${backend_dir}" && ! -L "${backend_dir}" \
    && -f "${repair}" && ! -L "${repair}" \
    && -f "${source_env}" && ! -L "${source_env}" \
    && -f "${plan_file}" && ! -L "${plan_file}" ]] \
    || return 1
  [[ "$(stat -c '%u:%g:%h' "${repair}")" == "0:0:1" \
    && "$(stat -c '%u:%g:%h' "${source_env}")" == "0:0:1" \
    && "$(stat -c '%u:%g:%h' "${plan_file}")" == "0:0:1" \
    && $((8#$(stat -c '%a' "${repair}") & 0022)) -eq 0 \
    && $((8#$(stat -c '%a' "${source_env}") & 0022)) -eq 0 \
    && $((8#$(stat -c '%a' "${plan_file}") & 0077)) -eq 0 ]] \
    || return 1
  (
    cd "${backend_dir}"
    /usr/bin/node "${repair}" \
      --env-file "${source_env}" \
      --plan-file "${plan_file}"
  ) >> "${LOG_FILE}" 2>&1
}

reattest_quiesced_update_project_egress_generation() {
  # Preparation happens while the old Portal is serving requests. After its
  # service is proven stopped, close that admission window by comparing the
  # sealed candidate ID with a fresh double inventory. A plane created during
  # staging may use the old environment; cutover must not strand it.
  local stage_dir="$1" transaction_id="$2"
  local prepared_env policy prepared_image_id live_image_id="" status=0
  prepared_env="$(update_project_runtime_prepared_env_path "${stage_dir}")" \
    || return 1
  validate_prepared_update_project_runtime_environment \
    "${prepared_env}" "${transaction_id}" || return 1
  policy="$(read_env_value \
    "${prepared_env}" PROJECT_RUNTIME_CONFINEMENT_POLICY || true)"
  prepared_image_id="$(read_env_value \
    "${prepared_env}" PROJECT_EGRESS_PROXY_IMAGE_ID || true)"

  if live_image_id="$(discover_unique_managed_project_egress_proxy_image_id)"; then
    status=0
  else
    status=$?
  fi
  case "${status}" in
    0)
      [[ "${policy}" != "${PROJECT_RUNTIME_DISABLED_POLICY}" \
        && "${live_image_id}" == "${prepared_image_id}" ]] || return 1
      ;;
    1)
      # No managed egress plane exists, so there is no live generation for
      # this candidate to preserve.
      ;;
    2|3|4|5)
      return 1
      ;;
    *)
      return 1
      ;;
  esac
}

apply_prepared_update_project_runtime_environment() {
  local destination_env="$1" stage_dir="$2" transaction_id="$3"
  local prepared_env key value
  prepared_env="$(update_project_runtime_prepared_env_path "${stage_dir}")" \
    || return 1
  validate_prepared_update_project_runtime_environment \
    "${prepared_env}" "${transaction_id}" || return 1
  for key in \
    PROJECT_RUNTIME_CONFINEMENT_POLICY \
    PROJECT_EGRESS_PROXY_IMAGE_ID \
    CODEX_PROJECT_SANDBOX_IMAGE_ID \
    CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID \
    ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID \
    OLLAMA_PROJECT_SANDBOX_IMAGE_ID \
    AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID \
    OPENCLAW_PROJECT_SANDBOX_IMAGE_ID \
    PORTAL_PROJECT_RUNTIME_IMAGE_ID; do
    value="$(read_env_value "${prepared_env}" "${key}" || true)"
    set_env_value_atomic "${destination_env}" "${key}" "${value}" || return 1
  done
}

update_project_runtime_promotion_manifest_path() {
  local target="$1" transaction_dir
  transaction_dir="$(read_update_transaction_field \
    "${target}" transaction_dir)" || return 1
  [[ -d "${transaction_dir}" && ! -L "${transaction_dir}" ]] || return 1
  printf '%s/project-runtime-images-v1.json\n' "${transaction_dir}"
}

update_project_runtime_promotion_marker_path() {
  local target="$1" transaction_dir
  transaction_dir="$(read_update_transaction_field \
    "${target}" transaction_dir)" || return 1
  [[ -d "${transaction_dir}" && ! -L "${transaction_dir}" ]] || return 1
  printf '%s/project-runtime-images-v1.promoted\n' "${transaction_dir}"
}

read_update_project_runtime_promotion_manifest() {
  local target="$1" transaction_id manifest
  transaction_id="$(read_update_transaction_field \
    "${target}" transaction_id)" || return 1
  manifest="$(update_project_runtime_promotion_manifest_path "${target}")" \
    || return 1
  python3 - "${manifest}" "${transaction_id}" <<'PY'
import json
import os
import re
import stat
import sys

path, expected_transaction_id = sys.argv[1:]
keys = (
    "PROJECT_EGRESS_PROXY_IMAGE_ID",
    "CODEX_PROJECT_SANDBOX_IMAGE_ID",
    "CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID",
    "ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID",
    "OLLAMA_PROJECT_SANDBOX_IMAGE_ID",
    "AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID",
    "OPENCLAW_PROJECT_SANDBOX_IMAGE_ID",
    "PORTAL_PROJECT_RUNTIME_IMAGE_ID",
)
flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
fd = os.open(path, flags)
try:
    details = os.fstat(fd)
    if (
        not stat.S_ISREG(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_gid != os.getegid()
        or stat.S_IMODE(details.st_mode) != 0o600
        or details.st_nlink != 1
        or not 1 <= details.st_size <= 8192
    ):
        raise SystemExit(1)
    chunks = []
    remaining = 8193
    while remaining:
        chunk = os.read(fd, remaining)
        if not chunk:
            break
        chunks.append(chunk)
        remaining -= len(chunk)
    raw = b"".join(chunks)
    after = os.fstat(fd)
    if (
        (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
        != (details.st_dev, details.st_ino, details.st_size, details.st_mtime_ns)
        or len(raw) != details.st_size
        or len(raw) > 8192
    ):
        raise SystemExit(1)
finally:
    os.close(fd)
record = json.loads(raw.decode("ascii"))
if (
    set(record) != {"schema", "transactionId", "policy", "images"}
    or record["schema"] != "bridgesllm-update-project-runtime-images-v1"
    or record["transactionId"] != expected_transaction_id
    or not isinstance(record["images"], dict)
    or set(record["images"]) != set(keys)
):
    raise SystemExit(1)
policy = record["policy"]
if policy not in {
    "apparmor-seccomp-v1",
    "seccomp-only-apparmor-unsupported-v1",
    "project-runtimes-disabled-v1",
}:
    raise SystemExit(1)
image_pattern = re.compile(r"sha256:[a-f0-9]{64}")
for key in keys:
    value = record["images"][key]
    if not isinstance(value, str) or (value and image_pattern.fullmatch(value) is None):
        raise SystemExit(1)
if policy != "project-runtimes-disabled-v1":
    for key in (
        "PROJECT_EGRESS_PROXY_IMAGE_ID",
        "CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID",
        "OLLAMA_PROJECT_SANDBOX_IMAGE_ID",
        "AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID",
        "PORTAL_PROJECT_RUNTIME_IMAGE_ID",
    ):
        if not record["images"][key]:
            raise SystemExit(1)
canonical = (
    json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n"
).encode("ascii")
if raw != canonical:
    raise SystemExit(1)
print(policy)
for key in keys:
    print(record["images"][key])
PY
}

seal_update_project_runtime_promotion_manifest() {
  local target="$1" stage_dir transaction_id transaction_dir prepared_env
  local backup_dir candidate_env manifest policy key value
  local -a values=()
  stage_dir="$(read_update_transaction_field "${target}" stage_dir)" || return 1
  transaction_id="$(read_update_transaction_field \
    "${target}" transaction_id)" || return 1
  transaction_dir="$(read_update_transaction_field \
    "${target}" transaction_dir)" || return 1
  backup_dir="$(read_update_transaction_field "${target}" backup_dir)" || return 1
  prepared_env="$(update_project_runtime_prepared_env_path "${stage_dir}")" \
    || return 1
  candidate_env="${backup_dir}/environment.updated/backend.env.production"
  manifest="$(update_project_runtime_promotion_manifest_path "${target}")" \
    || return 1
  validate_prepared_update_project_runtime_environment \
    "${prepared_env}" "${transaction_id}" || return 1
  [[ -f "${candidate_env}" && ! -L "${candidate_env}" ]] || return 1
  policy="$(read_env_value \
    "${prepared_env}" PROJECT_RUNTIME_CONFINEMENT_POLICY || true)"
  [[ "$(read_env_value \
      "${candidate_env}" PROJECT_RUNTIME_CONFINEMENT_POLICY || true)" \
      == "${policy}" ]] || return 1
  for key in \
    PROJECT_EGRESS_PROXY_IMAGE_ID \
    CODEX_PROJECT_SANDBOX_IMAGE_ID \
    CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID \
    ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID \
    OLLAMA_PROJECT_SANDBOX_IMAGE_ID \
    AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID \
    OPENCLAW_PROJECT_SANDBOX_IMAGE_ID \
    PORTAL_PROJECT_RUNTIME_IMAGE_ID; do
    value="$(read_env_value "${prepared_env}" "${key}" || true)"
    [[ "$(read_env_value "${candidate_env}" "${key}" || true)" == "${value}" ]] \
      || return 1
    values+=("${value}")
  done

  if [[ ! -e "${manifest}" && ! -L "${manifest}" ]]; then
    python3 - "${transaction_dir}" "${manifest}" "${transaction_id}" \
      "${policy}" "${values[@]}" <<'PY'
import json
import os
import secrets
import stat
import sys

directory, destination, transaction_id, policy, *values = sys.argv[1:]
keys = (
    "PROJECT_EGRESS_PROXY_IMAGE_ID",
    "CODEX_PROJECT_SANDBOX_IMAGE_ID",
    "CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_ID",
    "ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_ID",
    "OLLAMA_PROJECT_SANDBOX_IMAGE_ID",
    "AGENT_ZERO_PROJECT_SANDBOX_IMAGE_ID",
    "OPENCLAW_PROJECT_SANDBOX_IMAGE_ID",
    "PORTAL_PROJECT_RUNTIME_IMAGE_ID",
)
if len(values) != len(keys):
    raise SystemExit(1)
directory_details = os.lstat(directory)
if (
    not stat.S_ISDIR(directory_details.st_mode)
    or stat.S_ISLNK(directory_details.st_mode)
    or directory_details.st_uid != os.geteuid()
    or directory_details.st_gid != os.getegid()
    or directory_details.st_mode & 0o077
    or os.path.dirname(destination) != directory
):
    raise SystemExit(1)
record = {
    "schema": "bridgesllm-update-project-runtime-images-v1",
    "transactionId": transaction_id,
    "policy": policy,
    "images": dict(zip(keys, values, strict=True)),
}
payload = (
    json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n"
).encode("ascii")
temporary = os.path.join(
    directory, f".project-runtime-images.{os.getpid()}.{secrets.token_hex(8)}"
)
fd = -1
try:
    fd = os.open(
        temporary,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    os.write(fd, payload)
    os.fchmod(fd, 0o600)
    os.fsync(fd)
    os.close(fd)
    fd = -1
    if os.path.lexists(destination):
        raise FileExistsError(destination)
    os.rename(temporary, destination)
    directory_fd = os.open(
        directory,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if fd >= 0:
        os.close(fd)
    try:
        os.unlink(temporary)
    except FileNotFoundError:
        pass
PY
  fi
  mapfile -t values < <(
    read_update_project_runtime_promotion_manifest "${target}"
  ) || return 1
  [[ "${#values[@]}" -eq 9 && "${values[0]}" == "${policy}" ]]
}

assert_prepared_update_project_runtime_images_available() {
  local target="$1" policy value
  local -a values=()
  mapfile -t values < <(
    read_update_project_runtime_promotion_manifest "${target}"
  ) || return 1
  [[ "${#values[@]}" -eq 9 ]] || return 1
  policy="${values[0]}"
  [[ "${policy}" == "${PROJECT_RUNTIME_DISABLED_POLICY}" ]] && return 0
  for value in "${values[@]:1}"; do
    [[ -z "${value}" ]] && continue
    [[ "$(docker_image_id "${value}" || true)" == "${value}" ]] || return 1
  done
}

verify_update_project_runtime_promotion_complete() {
  local target="$1" transaction_id manifest marker manifest_sha
  local policy image_id canonical_tag index=0
  local -a values=()
  transaction_id="$(read_update_transaction_field \
    "${target}" transaction_id)" || return 1
  manifest="$(update_project_runtime_promotion_manifest_path "${target}")" \
    || return 1
  marker="$(update_project_runtime_promotion_marker_path "${target}")" \
    || return 1
  [[ -f "${marker}" && ! -L "${marker}" ]] || return 1
  mapfile -t values < <(
    read_update_project_runtime_promotion_manifest "${target}"
  ) || return 1
  [[ "${#values[@]}" -eq 9 ]] || return 1
  manifest_sha="$(sha256sum "${manifest}" | awk '{print $1}')"
  python3 - "${marker}" "${transaction_id}" "${manifest_sha}" <<'PY' \
    || return 1
import json
import os
import stat
import sys

path, transaction_id, manifest_sha = sys.argv[1:]
flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
fd = os.open(path, flags)
try:
    details = os.fstat(fd)
    if (
        not stat.S_ISREG(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_gid != os.getegid()
        or stat.S_IMODE(details.st_mode) != 0o600
        or details.st_nlink != 1
        or not 1 <= details.st_size <= 1024
    ):
        raise SystemExit(1)
    chunks = []
    remaining = 1025
    while remaining:
        chunk = os.read(fd, remaining)
        if not chunk:
            break
        chunks.append(chunk)
        remaining -= len(chunk)
    raw = b"".join(chunks)
    after = os.fstat(fd)
    if (
        (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
        != (details.st_dev, details.st_ino, details.st_size, details.st_mtime_ns)
        or len(raw) != details.st_size
        or len(raw) > 1024
    ):
        raise SystemExit(1)
finally:
    os.close(fd)
record = json.loads(raw.decode("ascii"))
if record != {
    "schema": "bridgesllm-update-project-runtime-promotion-v1",
    "transactionId": transaction_id,
    "manifestSha256": manifest_sha,
}:
    raise SystemExit(1)
canonical = (
    json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n"
).encode("ascii")
if raw != canonical:
    raise SystemExit(1)
PY
  for canonical_tag in \
    "${PROJECT_EGRESS_PROXY_IMAGE_TAG}" \
    "${CODEX_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${OLLAMA_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${AGENT_ZERO_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${OPENCLAW_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${PORTAL_PROJECT_RUNTIME_IMAGE_TAG}"; do
    index=$((index + 1))
    image_id="${values[index]}"
    [[ -z "${image_id}" ]] && continue
    [[ "$(docker_image_id "${canonical_tag}" || true)" == "${image_id}" ]] \
      || return 1
  done
}

promote_prepared_update_project_runtime_images() {
  local target="$1" transaction_id transaction_dir manifest marker manifest_sha
  local image_id canonical_tag index=0
  local -a values=()
  verify_update_project_runtime_promotion_complete "${target}" \
    && return 0
  transaction_id="$(read_update_transaction_field \
    "${target}" transaction_id)" || return 1
  transaction_dir="$(read_update_transaction_field \
    "${target}" transaction_dir)" || return 1
  manifest="$(update_project_runtime_promotion_manifest_path "${target}")" \
    || return 1
  marker="$(update_project_runtime_promotion_marker_path "${target}")" \
    || return 1
  mapfile -t values < <(
    read_update_project_runtime_promotion_manifest "${target}"
  ) || return 1
  [[ "${#values[@]}" -eq 9 ]] || return 1
  for canonical_tag in \
    "${PROJECT_EGRESS_PROXY_IMAGE_TAG}" \
    "${CODEX_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${CLAUDE_CODE_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${ANTIGRAVITY_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${OLLAMA_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${AGENT_ZERO_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${OPENCLAW_PROJECT_SANDBOX_IMAGE_TAG}" \
    "${PORTAL_PROJECT_RUNTIME_IMAGE_TAG}"; do
    index=$((index + 1))
    image_id="${values[index]}"
    [[ -z "${image_id}" ]] && continue
    [[ "$(docker_image_id "${image_id}" || true)" == "${image_id}" ]] \
      || return 1
    docker image tag "${image_id}" "${canonical_tag}" \
      >> "${LOG_FILE}" 2>&1 || return 1
    [[ "$(docker_image_id "${canonical_tag}" || true)" == "${image_id}" ]] \
      || return 1
  done
  manifest_sha="$(sha256sum "${manifest}" | awk '{print $1}')"
  if [[ ! -e "${marker}" && ! -L "${marker}" ]]; then
    python3 - "${transaction_dir}" "${marker}" \
      "${transaction_id}" "${manifest_sha}" <<'PY'
import json
import os
import secrets
import stat
import sys

directory, destination, transaction_id, manifest_sha = sys.argv[1:]
details = os.lstat(directory)
if (
    not stat.S_ISDIR(details.st_mode)
    or stat.S_ISLNK(details.st_mode)
    or details.st_uid != os.geteuid()
    or details.st_gid != os.getegid()
    or details.st_mode & 0o077
    or os.path.dirname(destination) != directory
):
    raise SystemExit(1)
temporary = os.path.join(
    directory,
    f".project-runtime-images-promoted.{os.getpid()}.{secrets.token_hex(8)}",
)
record = {
    "schema": "bridgesllm-update-project-runtime-promotion-v1",
    "transactionId": transaction_id,
    "manifestSha256": manifest_sha,
}
payload = (
    json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n"
).encode("ascii")
fd = -1
try:
    fd = os.open(
        temporary,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    os.write(fd, payload)
    os.fchmod(fd, 0o600)
    os.fsync(fd)
    os.close(fd)
    fd = -1
    if os.path.lexists(destination):
        raise FileExistsError(destination)
    os.rename(temporary, destination)
    directory_fd = os.open(
        directory,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if fd >= 0:
        os.close(fd)
    try:
        os.unlink(temporary)
    except FileNotFoundError:
        pass
PY
  fi
  verify_update_project_runtime_promotion_complete "${target}"
}

cleanup_prepared_update_project_runtime_tags() {
  local transaction_id="$1" cleanup_policy="${2:-}" component tag
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ ]] || return 1
  case "${cleanup_policy}" in
    ""|"${PROJECT_RUNTIME_APPARMOR_SECCOMP_POLICY}"|\
    "${PROJECT_RUNTIME_SECCOMP_ONLY_POLICY}"|\
    "${PROJECT_RUNTIME_DISABLED_POLICY}"|\
    "${PROJECT_RUNTIME_PREPARATION_NOT_STARTED_POLICY}")
      ;;
    *)
      return 1
      ;;
  esac
  # A validated disabled preparation exits before every Docker build/tag
  # operation, so this exact transaction cannot own candidate tags. Do not
  # turn an installed-but-stopped Docker daemon into a permanent cleanup
  # blocker for the explicit --skip-project-runtimes path.
  if [[ "${cleanup_policy}" == "${PROJECT_RUNTIME_DISABLED_POLICY}" \
    || "${cleanup_policy}" \
      == "${PROJECT_RUNTIME_PREPARATION_NOT_STARTED_POLICY}" ]]; then
    return 0
  fi
  if ! command -v docker >/dev/null 2>&1; then
    # For every enabled or indeterminate preparation, absence of the CLI is
    # not proof that old Docker metadata vanished; retain the transaction
    # stage until the exact tags can be inspected and removed.
    return 1
  fi
  docker info >/dev/null 2>&1 || return 1
  for component in \
    egress codex claude antigravity ollama agent-zero openclaw portal; do
    tag="$(update_project_runtime_staging_tag \
      "${transaction_id}" "${component}")" || return 1
    if docker image inspect "${tag}" >/dev/null 2>&1; then
      docker image rm "${tag}" >> "${LOG_FILE}" 2>&1 || return 1
    else
      # `image inspect` uses the same non-zero status for "not found" and a
      # daemon failure. Re-prove daemon reachability before accepting absence.
      docker info >/dev/null 2>&1 || return 1
    fi
    if docker image inspect "${tag}" >/dev/null 2>&1; then
      return 1
    fi
    docker info >/dev/null 2>&1 || return 1
  done
}

prepared_update_project_runtime_cleanup_policy_from_stage() {
  local stage_dir="$1" transaction_id="$2" prepared_env marker
  local preparation_mode="" policy
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ \
    && -d "${stage_dir}" && ! -L "${stage_dir}" \
    && "$(stat -c '%u:%g:%a' "${stage_dir}")" \
      == "$(id -u):$(id -g):700" ]] || return 1
  prepared_env="$(update_project_runtime_prepared_env_path "${stage_dir}")" \
    || return 1
  marker="$(update_project_runtime_preparation_mode_path "${stage_dir}")" \
    || return 1
  if [[ -e "${marker}" || -L "${marker}" ]]; then
    preparation_mode="$(
      read_update_project_runtime_preparation_mode \
        "${stage_dir}" "${transaction_id}"
    )" || return 1
  fi
  if [[ "${preparation_mode}" == "disabled" ]]; then
    printf '%s\n' "${PROJECT_RUNTIME_DISABLED_POLICY}"
    return 0
  fi
  if [[ ! -e "${prepared_env}" && ! -L "${prepared_env}" ]]; then
    printf '%s\n' "${PROJECT_RUNTIME_PREPARATION_NOT_STARTED_POLICY}"
    return 0
  fi
  validate_prepared_update_project_runtime_environment \
    "${prepared_env}" "${transaction_id}" || return 1
  policy="$(read_env_value \
    "${prepared_env}" PROJECT_RUNTIME_CONFINEMENT_POLICY || true)"
  if [[ "${preparation_mode}" == "docker" \
    && "${policy}" == "${PROJECT_RUNTIME_DISABLED_POLICY}" ]]; then
    return 1
  fi
  case "${policy}" in
    "${PROJECT_RUNTIME_APPARMOR_SECCOMP_POLICY}"|\
    "${PROJECT_RUNTIME_SECCOMP_ONLY_POLICY}"|\
    "${PROJECT_RUNTIME_DISABLED_POLICY}")
      printf '%s\n' "${policy}"
      ;;
    *)
      return 1
      ;;
  esac
}

update_project_runtime_cleanup_policy_for_target() {
  local target="$1" manifest_output stage_dir transaction_id
  if manifest_output="$(
    read_update_project_runtime_promotion_manifest "${target}" 2>/dev/null
  )"; then
    printf '%s\n' "${manifest_output%%$'\n'*}"
    return 0
  fi
  stage_dir="$(read_update_transaction_field "${target}" stage_dir)" \
    || return 1
  transaction_id="$(read_update_transaction_field \
    "${target}" transaction_id)" || return 1
  prepared_update_project_runtime_cleanup_policy_from_stage \
    "${stage_dir}" "${transaction_id}"
}

resolve_openclaw_pending_input_hotfix_target() {
  local openclaw_dist="$1"
  python3 - "${openclaw_dist}" <<'PY'
import os
from pathlib import Path
import stat
import sys

dist = Path(sys.argv[1]).resolve()
markers = (
    "function createCodexUserInputBridge(params) {",
    'request.method === "item/tool/requestUserInput"',
    "const activeSteeringQueue = createCodexSteeringQueue({",
    "setActiveEmbeddedRun(params.sessionId, handle, params.sessionKey, params.sessionFile);",
    "clearActiveEmbeddedRun(params.sessionId, handle, params.sessionKey, params.sessionFile);",
)
matches = []
for candidate in sorted(dist.glob("run-attempt-*.js")):
    try:
        metadata = os.lstat(candidate)
        if not stat.S_ISREG(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
            continue
        text = candidate.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
