arm_openclaw_pending_input_hotfix_rollback() {
  local target="$1"
  local backup="${target}.bridgesllm-pending-input-v1.bak"
  python3 - "${target}" "${backup}" <<'PY'
import os
from pathlib import Path
import stat
import subprocess
import sys

target = Path(sys.argv[1])
backup = Path(sys.argv[2])
marker = 'const BRIDGESLLM_PENDING_INPUT_HOTFIX_MARKER = "bridgesllm-openclaw-pending-input-v1";'
if backup != target.with_name(target.name + ".bridgesllm-pending-input-v1.bak"):
    raise SystemExit(1)
for path in (target, backup):
    try:
        metadata = os.lstat(path)
    except OSError:
        raise SystemExit(1)
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or metadata.st_nlink != 1
    ):
        raise SystemExit(1)
try:
    target_text = target.read_text(encoding="utf-8")
    backup_text = backup.read_text(encoding="utf-8")
except (OSError, UnicodeError):
    raise SystemExit(1)
if target_text.count(marker) != 1 or marker in backup_text:
    raise SystemExit(1)
def valid_javascript(text):
    # The OpenClaw bundle is an ES module, but `node --check -` parses stdin as
    # CommonJS no matter what the nearest package.json says, so every ESM bundle
    # fails this check as written. Check the module grammar the bundle actually
    # uses, and still accept CommonJS so an upstream switch to a script bundle
    # cannot turn this into a false negative.
    for module_type in ("module", "commonjs"):
        if subprocess.run(
            ["node", f"--input-type={module_type}", "--check", "-"],
            input=text,
            text=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        ).returncode == 0:
            return True
    return False


for text in (target_text, backup_text):
    if not valid_javascript(text):
        raise SystemExit(1)
PY
  OPENCLAW_PENDING_INPUT_HOTFIX_TARGET="${target}"
  OPENCLAW_PENDING_INPUT_HOTFIX_BACKUP="${backup}"
  OPENCLAW_PENDING_INPUT_HOTFIX_APPLIED=true
  OPENCLAW_PENDING_INPUT_HOTFIX_COMMITTED=false
}

