  $OPENCLAW_PENDING_INPUT_HOTFIX_COMMITTED && return 0
  local target="${OPENCLAW_PENDING_INPUT_HOTFIX_TARGET:-}"
  local backup="${OPENCLAW_PENDING_INPUT_HOTFIX_BACKUP:-}"
  [[ -n "${target}" && -n "${backup}" ]] || return 1
