prepare_openclaw_claude_ask_user_hotfix_rollback() {
  local target="$1"
  local result backup
  if ! result="$(python3 - "${target}" <<'PY'
import os
from pathlib import Path
import shutil
import stat
import subprocess
import sys
import tempfile

target = Path(sys.argv[1])
backup = target.with_name(target.name + ".bridgesllm-claude-ask-user-route-v2.bak")
marker = 'const BRIDGESLLM_CLAUDE_ASK_USER_ROUTE_MARKER = "bridgesllm-openclaw-claude-ask-user-route-v2";'

def regular_single_link(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISREG(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_nlink == 1
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def valid_javascript(text):
    for module_type in ("module", "commonjs"):
        if subprocess.run(
            ["node", f"--input-type={module_type}", "--check", "-"],
            input=text,
            text=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        ).returncode == 0:
            return True
    return False

def pristine_contract(text):
    return (
        marker not in text
        and "function ensureClaudeDisallowedTool(args, toolName) {" not in text
        and text.count("function normalizeClaudeBackendConfig(config, context) {") == 1
        and text.count("args: normalizeClaudePermissionArgs(") == 1
        and text.count("resumeArgs: normalizeClaudePermissionArgs(") == 1
    )

def applied_contract(text):
    return (
        text.count(marker) == 1
        and text.count("function ensureClaudeDisallowedTool(args, toolName) {") == 1
        and text.count(
            "function ensureClaudeDisallowedTool(args, toolName) {\n"
            "\tif (!args) return args;\n"
            "\tconst normalized = [...args];"
        ) == 1
        and text.count("args: ensureClaudeDisallowedTool(") == 1
        and text.count("resumeArgs: ensureClaudeDisallowedTool(") == 1
    )

try:
    if not regular_single_link(target):
        raise SystemExit(1)
except OSError:
    raise SystemExit(1)
try:
    target_text = target.read_text(encoding="utf-8")
except (OSError, UnicodeError):
    target_text = None

backup_exists = os.path.lexists(backup)
if backup_exists:
    try:
        if not regular_single_link(backup):
            raise SystemExit(1)
        backup_text = backup.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        backup_text = None
    if (
        backup_text is not None
        and valid_javascript(backup_text)
        and pristine_contract(backup_text)
    ):
        # A recovery artifact from an interrupted run owns the baseline even
        # when the target stopped between write and marker verification.
        print(backup)
        raise SystemExit(0)
    # Older builds wrote directly to the final backup name. A torn backup is
    # safe to replace only while the live target is still a fully validated,
    # pristine baseline. Never discard the sole recovery copy of a changed or
    # unreadable target.
    if (
        target_text is None
        or not valid_javascript(target_text)
        or not pristine_contract(target_text)
    ):
        raise SystemExit(1)
    backup.unlink()
    directory_fd = os.open(target.parent, os.O_RDONLY)
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)

if target_text is None or not valid_javascript(target_text):
    raise SystemExit(1)
if applied_contract(target_text):
    print("committed")
    raise SystemExit(0)
if not pristine_contract(target_text):
    raise SystemExit(1)

target_mode = target.stat().st_mode & 0o7777
temporary_name = ""
try:
    with tempfile.NamedTemporaryFile(
        mode="wb",
        dir=target.parent,
        prefix=f".{target.name}.bridgesllm-claude-backup-",
        suffix=".tmp",
        delete=False,
    ) as stream:
        temporary_name = stream.name
        stream.write(target.read_bytes())
        stream.flush()
        os.fsync(stream.fileno())
    shutil.copystat(target, temporary_name, follow_symlinks=True)
    os.chmod(temporary_name, target_mode)
    if os.path.lexists(backup):
        raise FileExistsError(backup)
    # The package directory is root-owned and the installer operation lock
    # excludes another writer. Publish only complete, fsynced bytes.
    os.replace(temporary_name, backup)
    temporary_name = ""
    directory_fd = os.open(target.parent, os.O_RDONLY)
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
except BaseException:
    if temporary_name:
        try:
            Path(temporary_name).unlink()
        except FileNotFoundError:
            pass
    raise
print(backup)
PY
)"; then
    return 1
  fi
  if [[ "${result}" == "committed" ]]; then
    OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED=true
    return 0
  fi
  backup="${target}.bridgesllm-claude-ask-user-route-v2.bak"
  [[ "${result}" == "${backup}" && -f "${backup}" ]] || return 1
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_TARGET="${target}"
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_BACKUP="${backup}"
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_APPLIED=true
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED=false
}

rollback_openclaw_claude_ask_user_hotfix() {
  $OPENCLAW_CLAUDE_ASK_USER_HOTFIX_APPLIED || return 0
  $OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED && return 0
  local target="${OPENCLAW_CLAUDE_ASK_USER_HOTFIX_TARGET:-}"
  local backup="${OPENCLAW_CLAUDE_ASK_USER_HOTFIX_BACKUP:-}"
  [[ -n "${target}" && -n "${backup}" ]] || return 1
  if ! python3 - "${target}" "${backup}" <<'PY'
import os
from pathlib import Path
import stat
import subprocess
import sys

target = Path(sys.argv[1])
backup = Path(sys.argv[2])
marker = 'const BRIDGESLLM_CLAUDE_ASK_USER_ROUTE_MARKER = "bridgesllm-openclaw-claude-ask-user-route-v2";'
if backup != target.with_name(target.name + ".bridgesllm-claude-ask-user-route-v2.bak"):
    raise SystemExit(1)

def regular_single_link(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISREG(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_nlink == 1
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

try:
    if not regular_single_link(target) or not regular_single_link(backup):
        raise SystemExit(1)
    backup_text = backup.read_text(encoding="utf-8")
except (OSError, UnicodeError):
    raise SystemExit(1)
if (
    marker in backup_text
    or "function ensureClaudeDisallowedTool(args, toolName) {" in backup_text
    or backup_text.count("function normalizeClaudeBackendConfig(config, context) {") != 1
):
    raise SystemExit(1)
if not any(
    subprocess.run(
        ["node", f"--input-type={module_type}", "--check", "-"],
        input=backup_text,
        text=True,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
    ).returncode == 0
    for module_type in ("module", "commonjs")
):
    raise SystemExit(1)
os.replace(backup, target)
directory_fd = os.open(target.parent, os.O_RDONLY)
try:
    os.fsync(directory_fd)
finally:
    os.close(directory_fd)
PY
  then
    return 1
  fi
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_APPLIED=false
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_TARGET=""
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_BACKUP=""
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED=false
}

commit_openclaw_claude_ask_user_hotfix() {
  if ! $OPENCLAW_CLAUDE_ASK_USER_HOTFIX_APPLIED; then
    OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED=true
    return 0
  fi
  $OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED && return 0
  local target="${OPENCLAW_CLAUDE_ASK_USER_HOTFIX_TARGET:-}"
  local backup="${OPENCLAW_CLAUDE_ASK_USER_HOTFIX_BACKUP:-}"
  [[ -n "${target}" && -n "${backup}" ]] || return 1
  openclaw_claude_ask_user_hotfix_is_applied "${target}" || return 1
  if ! python3 - "${target}" "${backup}" <<'PY'
import os
from pathlib import Path
import stat
import sys

target = Path(sys.argv[1])
backup = Path(sys.argv[2])
marker = 'const BRIDGESLLM_CLAUDE_ASK_USER_ROUTE_MARKER = "bridgesllm-openclaw-claude-ask-user-route-v2";'
if backup != target.with_name(target.name + ".bridgesllm-claude-ask-user-route-v2.bak"):
    raise SystemExit(1)
for path in (target, backup):
    metadata = os.lstat(path)
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or metadata.st_nlink != 1
        or metadata.st_uid != 0
        or metadata.st_gid != 0
    ):
        raise SystemExit(1)
target_text = target.read_text(encoding="utf-8")
backup_text = backup.read_text(encoding="utf-8")
if target_text.count(marker) != 1 or marker in backup_text:
    raise SystemExit(1)
backup.unlink()
directory_fd = os.open(target.parent, os.O_RDONLY)
try:
    os.fsync(directory_fd)
finally:
    os.close(directory_fd)
PY
  then
    return 1
  fi
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_BACKUP=""
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED=true
}

openclaw_tested_pair_commit_record_matches_target() {
  local component="$1" target="$2"
  local record="${OPENCLAW_TESTED_PAIR_COMMIT_RECORD}"
  python3 - "${record}" "${component}" "${target}" <<'PY'
import hashlib
import json
import os
from pathlib import Path
import stat
import sys

record = Path(sys.argv[1])
component = sys.argv[2]
target = Path(sys.argv[3])
if component not in {"claudeAskUser", "pendingInput"}:
    raise SystemExit(1)
backup_suffix = {
    "pendingInput": ".bridgesllm-pending-input-v1.bak",
    "claudeAskUser": ".bridgesllm-claude-ask-user-route-v2.bak",
}[component]
backup = target.with_name(target.name + backup_suffix)

def safe_file(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISREG(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_nlink == 1
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def backup_identity(path):
    metadata = os.lstat(path)
    return {
        "path": str(path.resolve()),
        "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
        "device": metadata.st_dev,
        "inode": metadata.st_ino,
        "ctimeNs": metadata.st_ctime_ns,
        "size": metadata.st_size,
    }

try:
    record_stat = os.lstat(record)
    if (
        not stat.S_ISREG(record_stat.st_mode)
        or stat.S_ISLNK(record_stat.st_mode)
        or record_stat.st_nlink != 1
        or record_stat.st_uid != 0
        or record_stat.st_gid != 0
        or stat.S_IMODE(record_stat.st_mode) != 0o600
        or not safe_file(target)
        or not safe_file(backup)
    ):
        raise SystemExit(1)
    value = json.loads(record.read_text(encoding="utf-8"))
    target_bytes = target.read_bytes()
    observed_backup = backup_identity(backup)
except (OSError, UnicodeError, json.JSONDecodeError):
    raise SystemExit(1)
if not isinstance(value, dict):
    raise SystemExit(1)
entry = value.get(component)
if (
    value.get("schema") != "bridgesllm-openclaw-tested-pair-commit-v3"
    or not isinstance(entry, dict)
    or entry.get("path") != str(target.resolve())
    or entry.get("sha256") != hashlib.sha256(target_bytes).hexdigest()
    or entry.get("backup") != observed_backup
):
    raise SystemExit(1)
PY
}

openclaw_tested_pair_commit_record_matches_ask_user_transaction() {
  local transaction_dir="$1" target_dir="$2" config_path="$3"
  local record="${OPENCLAW_TESTED_PAIR_COMMIT_RECORD}"
  python3 - \
    "${record}" \
    "${transaction_dir}" \
    "${target_dir}" \
    "${config_path}" <<'PY'
import hashlib
import json
import os
from pathlib import Path
import stat
import sys

record = Path(sys.argv[1]).absolute()
transaction = Path(sys.argv[2]).absolute()
target = Path(sys.argv[3]).absolute()
config = Path(sys.argv[4]).absolute()
manifest = transaction / "manifest.json"

def safe_file(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISREG(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_nlink == 1
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def safe_directory(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISDIR(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def tree_digest(root):
    digest = hashlib.sha256()
    for path in [root, *sorted(root.rglob("*"), key=lambda item: str(item.relative_to(root)))]:
        metadata = os.lstat(path)
        relative = "." if path == root else str(path.relative_to(root))
        digest.update(relative.encode("utf-8") + b"\0")
        if stat.S_ISDIR(metadata.st_mode):
            digest.update(b"d\0")
        elif stat.S_ISREG(metadata.st_mode):
            digest.update(b"f\0" + path.read_bytes())
        elif stat.S_ISLNK(metadata.st_mode):
            digest.update(b"l\0" + os.readlink(path).encode("utf-8"))
        else:
            raise OSError(f"unsupported plugin entry: {path}")
    return digest.hexdigest()

try:
    if (
        not safe_file(record)
        or stat.S_IMODE(os.lstat(record).st_mode) != 0o600
        or not safe_directory(transaction)
        or not safe_directory(target)
        or not safe_file(config)
        or stat.S_IMODE(os.lstat(config).st_mode) != 0o600
        or not safe_file(manifest)
    ):
        raise OSError("unsafe ask-user commit artifacts")
    value = json.loads(record.read_text(encoding="utf-8"))
    ask_user = value.get("askUser")
    manifest_value = json.loads(manifest.read_text(encoding="utf-8"))
except (OSError, UnicodeError, json.JSONDecodeError):
    raise SystemExit(1)
if (
    value.get("schema") != "bridgesllm-openclaw-tested-pair-commit-v3"
    or not isinstance(ask_user, dict)
    or manifest_value.get("schema") != "bridgesllm-ask-user-tested-pair-v1"
    or Path(manifest_value.get("targetDir", "")).absolute() != target
    or Path(manifest_value.get("configPath", "")).absolute() != config
    or ask_user.get("transactionPath") != str(transaction)
    or ask_user.get("transactionManifestSha256")
        != hashlib.sha256(manifest.read_bytes()).hexdigest()
    or ask_user.get("pluginPath") != str(target)
    or ask_user.get("pluginTreeSha256") != tree_digest(target)
    or ask_user.get("configPath") != str(config)
    or ask_user.get("configSha256") != hashlib.sha256(config.read_bytes()).hexdigest()
):
    raise SystemExit(1)
PY
}

write_openclaw_tested_pair_commit_record() {
  local pending_target="$1" claude_target="$2"
  local ask_user_transaction="$3" ask_user_target="$4" ask_user_config="$5"
  local record="${OPENCLAW_TESTED_PAIR_COMMIT_RECORD}"
  python3 - \
    "${record}" \
    "${pending_target}" \
    "${claude_target}" \
    "${ask_user_transaction}" \
    "${ask_user_target}" \
    "${ask_user_config}" <<'PY'
import hashlib
import json
import os
from pathlib import Path
import stat
import sys
import tempfile

record = Path(sys.argv[1])
pending_target = Path(sys.argv[2])
claude_target = Path(sys.argv[3])
ask_user_transaction = Path(sys.argv[4]).absolute()
ask_user_target = Path(sys.argv[5]).absolute()
ask_user_config = Path(sys.argv[6]).absolute()
ask_user_manifest = ask_user_transaction / "manifest.json"
parent = record.parent
backup_specs = {
    "pendingInput": (
        pending_target,
        pending_target.with_name(
            pending_target.name + ".bridgesllm-pending-input-v1.bak"
        ),
    ),
    "claudeAskUser": (
        claude_target,
        claude_target.with_name(
            claude_target.name + ".bridgesllm-claude-ask-user-route-v2.bak"
        ),
    ),
}

def safe_file(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISREG(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_nlink == 1
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def safe_directory(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISDIR(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def tree_digest(root):
    digest = hashlib.sha256()
    for path in [root, *sorted(root.rglob("*"), key=lambda item: str(item.relative_to(root)))]:
        metadata = os.lstat(path)
        relative = "." if path == root else str(path.relative_to(root))
        digest.update(relative.encode("utf-8") + b"\0")
        if stat.S_ISDIR(metadata.st_mode):
            digest.update(b"d\0")
        elif stat.S_ISREG(metadata.st_mode):
            digest.update(b"f\0" + path.read_bytes())
        elif stat.S_ISLNK(metadata.st_mode):
            digest.update(b"l\0" + os.readlink(path).encode("utf-8"))
        else:
            raise OSError(f"unsupported plugin entry: {path}")
    return digest.hexdigest()

def component_entry(target, backup):
    entry = {
        "path": str(target.resolve()),
        "sha256": hashlib.sha256(target.read_bytes()).hexdigest(),
        "backup": None,
    }
    if os.path.lexists(backup):
        if not safe_file(backup):
            raise OSError(f"unsafe tested-pair backup: {backup}")
        metadata = os.lstat(backup)
        entry["backup"] = {
            "path": str(backup.resolve()),
            "sha256": hashlib.sha256(backup.read_bytes()).hexdigest(),
            "device": metadata.st_dev,
            "inode": metadata.st_ino,
            "ctimeNs": metadata.st_ctime_ns,
            "size": metadata.st_size,
        }
    return entry

try:
    parent_stat = os.lstat(parent)
    if (
        not stat.S_ISDIR(parent_stat.st_mode)
        or stat.S_ISLNK(parent_stat.st_mode)
        or parent_stat.st_uid != 0
        or parent_stat.st_gid != 0
    ):
        raise SystemExit(1)
    for target in (pending_target, claude_target):
        if not safe_file(target):
            raise SystemExit(1)
    if (
        not safe_directory(ask_user_transaction)
        or not safe_directory(ask_user_target)
        or not safe_file(ask_user_config)
        or stat.S_IMODE(os.lstat(ask_user_config).st_mode) != 0o600
        or not safe_file(ask_user_manifest)
    ):
        raise SystemExit(1)
    ask_user_manifest_value = json.loads(
        ask_user_manifest.read_text(encoding="utf-8")
    )
    if (
        ask_user_manifest_value.get("schema")
            != "bridgesllm-ask-user-tested-pair-v1"
        or Path(ask_user_manifest_value.get("targetDir", "")).absolute()
            != ask_user_target
        or Path(ask_user_manifest_value.get("configPath", "")).absolute()
            != ask_user_config
    ):
        raise SystemExit(1)
    if os.path.lexists(record) and not safe_file(record):
        raise SystemExit(1)
    value = {
        "schema": "bridgesllm-openclaw-tested-pair-commit-v3",
        **{
            component: component_entry(target, backup)
            for component, (target, backup) in backup_specs.items()
        },
        "askUser": {
            "transactionPath": str(ask_user_transaction),
            "transactionManifestSha256": hashlib.sha256(
                ask_user_manifest.read_bytes()
            ).hexdigest(),
            "pluginPath": str(ask_user_target),
            "pluginTreeSha256": tree_digest(ask_user_target),
            "configPath": str(ask_user_config),
            "configSha256": hashlib.sha256(ask_user_config.read_bytes()).hexdigest(),
        },
    }
except (OSError, UnicodeError, json.JSONDecodeError):
    raise SystemExit(1)

temporary_name = ""
try:
    with tempfile.NamedTemporaryFile(
        mode="w",
        encoding="utf-8",
        dir=parent,
        prefix=".bridgesllm-tested-pair-commit-",
        suffix=".tmp",
        delete=False,
    ) as stream:
        temporary_name = stream.name
        json.dump(value, stream, sort_keys=True, separators=(",", ":"))
        stream.write("\n")
        stream.flush()
        os.fsync(stream.fileno())
    os.chmod(temporary_name, 0o600)
    os.replace(temporary_name, record)
    temporary_name = ""
    directory_fd = os.open(parent, os.O_RDONLY)
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if temporary_name:
        try:
            Path(temporary_name).unlink()
        except FileNotFoundError:
            pass
PY
}

retire_openclaw_tested_pair_commit_record_if_clean() {
  local pending_target="$1" claude_target="$2" ask_user_transaction="$3"
  local record="${OPENCLAW_TESTED_PAIR_COMMIT_RECORD}"
  python3 - \
    "${record}" \
    "${pending_target}" \
    "${claude_target}" \
    "${ask_user_transaction}" <<'PY'
import os
from pathlib import Path
import stat
import sys

record = Path(sys.argv[1])
pending_target = Path(sys.argv[2])
claude_target = Path(sys.argv[3])
ask_user_transaction = Path(sys.argv[4])
backups = (
    pending_target.with_name(
        pending_target.name + ".bridgesllm-pending-input-v1.bak"
    ),
    claude_target.with_name(
        claude_target.name + ".bridgesllm-claude-ask-user-route-v2.bak"
    ),
)
if any(os.path.lexists(path) for path in backups) or os.path.lexists(ask_user_transaction):
    raise SystemExit(0)
if not os.path.lexists(record):
    raise SystemExit(0)
try:
    # A cleanup helper can unlink successfully and still fail its directory
    # fsync. Re-prove durable absence in every artifact directory before
    # retiring the only record that authorizes a backup which could reappear
    # after power loss.
    artifact_parents = {
        path.parent.resolve() for path in (*backups, ask_user_transaction)
    }
    for directory in artifact_parents:
        directory_metadata = os.lstat(directory)
        if (
            not stat.S_ISDIR(directory_metadata.st_mode)
            or stat.S_ISLNK(directory_metadata.st_mode)
            or directory_metadata.st_uid != 0
            or directory_metadata.st_gid != 0
        ):
            raise SystemExit(1)
        directory_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    metadata = os.lstat(record)
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or metadata.st_nlink != 1
        or metadata.st_uid != 0
        or metadata.st_gid != 0
        or stat.S_IMODE(metadata.st_mode) != 0o600
    ):
        raise SystemExit(1)
    record.unlink()
    directory_fd = os.open(record.parent, os.O_RDONLY)
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
except OSError:
    raise SystemExit(1)
PY
}

auto_apply_openclaw_compatibility_hotfix() {
  if $SKIP_OPENCLAW || ! command -v openclaw &>/dev/null; then
    return 0
  fi
  if ! $OPENCLAW_ASK_USER_BASE_ATTESTED; then
    fail "Native Claude questions may only be suppressed after the replacement ask-user tool and all settlement methods pass live base probes."
  fi

  local hotfix_script="${PORTAL_DIR}/scripts/patch-openclaw-long-run-relay-hotfix.sh"
  local pending_input_hotfix_script="${PORTAL_DIR}/scripts/patch-openclaw-codex-pending-input-hotfix.sh"
  local openclaw_package_dir openclaw_dist pending_input_target
  local claude_ask_user_target
  local pending_input_backup pending_input_hotfix_status=0
  local pending_input_hotfix_preexisted=false
  openclaw_package_dir="$(openclaw_core_package_dir || true)"
  openclaw_dist="${openclaw_package_dir}/dist"

  if [[ ! -f "${hotfix_script}" ]]; then
    fail "Bundled OpenClaw compatibility hotfix script is missing; refusing to start the tested runtime without its required compatibility markers."
  fi
  if [[ ! -f "${pending_input_hotfix_script}" ]]; then
    fail "Bundled OpenClaw native pending-input hotfix is missing; refusing to start a runtime that cannot attest exact Codex request identity."
  fi

  if [[ -z "${openclaw_package_dir}" \
    || "$(node_package_name_from_dir "${openclaw_package_dir}" || true)" != "openclaw" \
    || "$(node_package_version_from_dir "${openclaw_package_dir}" || true)" != "${PIN_OPENCLAW_CORE_PACKAGE_VERSION}" \
    || ! -d "${openclaw_dist}" ]]; then
    fail "Could not resolve the exact OpenClaw ${PIN_OPENCLAW_CORE_PACKAGE_VERSION} package directory for required compatibility preparation."
  fi

  claude_ask_user_target="$(
    resolve_openclaw_claude_ask_user_hotfix_target "${openclaw_dist}" || true
  )"
  if [[ -z "${claude_ask_user_target}" ]]; then
    fail "Could not resolve exactly one Claude CLI normalization bundle before compatibility preparation."
  fi
  if ! prepare_openclaw_claude_ask_user_hotfix_rollback \
    "${claude_ask_user_target}"; then
    fail "Could not preserve an exact Claude CLI normalization bundle before compatibility preparation."
  fi
  if $OPENCLAW_CLAUDE_ASK_USER_HOTFIX_APPLIED \
    && openclaw_claude_ask_user_hotfix_is_applied \
      "${claude_ask_user_target}" \
    && openclaw_tested_pair_commit_record_matches_target \
      claudeAskUser "${claude_ask_user_target}"; then
    if ! commit_openclaw_claude_ask_user_hotfix; then
      fail "Could not retire a Claude ask-user recovery artifact already covered by the durable tested-pair commit record."
    fi
  fi

  pending_input_target="$(
    resolve_openclaw_pending_input_hotfix_target "${openclaw_dist}" || true
  )"
  if [[ -z "${pending_input_target}" ]]; then
    fail "Could not resolve exactly one native Codex pending-input bundle before compatibility preparation."
  fi
  pending_input_backup="${pending_input_target}.bridgesllm-pending-input-v1.bak"
  if openclaw_pending_input_hotfix_is_applied "${pending_input_target}"; then
    pending_input_hotfix_preexisted=true
    # A patched target plus our exact backup is an interrupted prior
    # transaction, not a committed baseline. Re-arm it so this run either
    # restores the original bytes on failure or retires the backup on commit.
    if [[ -e "${pending_input_backup}" || -L "${pending_input_backup}" ]] \
      && ! arm_openclaw_pending_input_hotfix_rollback \
        "${pending_input_target}"; then
      fail "The existing native pending-input hotfix recovery artifact is unsafe at ${pending_input_backup}; refusing to discard or overwrite it."
    fi
    if $OPENCLAW_PENDING_INPUT_HOTFIX_APPLIED \
      && openclaw_tested_pair_commit_record_matches_target \
        pendingInput "${pending_input_target}"; then
      if ! commit_openclaw_pending_input_hotfix; then
        fail "Could not retire a native pending-input recovery artifact already covered by the durable tested-pair commit record."
      fi
    fi
  elif [[ -e "${pending_input_backup}" || -L "${pending_input_backup}" ]]; then
    fail "A stale native pending-input hotfix backup already exists at ${pending_input_backup}; refusing to overwrite an uncommitted recovery artifact."
  fi

  # The commit record is needed only while at least one exact cleanup artifact
  # survives. Retire it once both are gone. A later same-pin reinstall can
  # therefore never reuse an old decision, and v3 artifact identities make even
  # an interrupted cleanup record fail closed against newly created backups.
  if ! retire_openclaw_tested_pair_commit_record_if_clean \
    "${pending_input_target}" \
    "${claude_ask_user_target}" \
    "/root/.openclaw/.bridgesllm-ask-user-tested-pair-v1"; then
    fail "Could not safely retire the completed OpenClaw tested-pair commit record."
  fi

  chmod 755 "${hotfix_script}" "${pending_input_hotfix_script}" 2>/dev/null || true

  info "Applying OpenClaw compatibility hotfix (if needed)..."
  if ! run_openclaw_compatibility_hotfix \
    "${hotfix_script}" "${openclaw_dist}"; then
    fail "OpenClaw compatibility preparation failed or required markers were not verified; the tested-pair rollback remains armed."
  fi
  if ! openclaw_claude_ask_user_hotfix_is_applied \
    "${claude_ask_user_target}"; then
    fail "OpenClaw compatibility preparation returned without the required post-merge Claude ask-user routing contract."
  fi

  if spin "Applying OpenClaw native pending-input hotfix (if needed)" \
    "PORTAL_OPENCLAW_PENDING_INPUT_STRICT=1 PORTAL_REQUIRED_OPENCLAW_PACKAGE_NAME='openclaw' PORTAL_REQUIRED_OPENCLAW_PACKAGE_VERSION='${PIN_OPENCLAW_CORE_PACKAGE_VERSION}' bash '${pending_input_hotfix_script}' '${openclaw_dist}'"; then
    pending_input_hotfix_status=0
  else
    pending_input_hotfix_status=$?
  fi
  if ! $pending_input_hotfix_preexisted \
    && openclaw_pending_input_hotfix_is_applied "${pending_input_target}"; then
    if ! arm_openclaw_pending_input_hotfix_rollback "${pending_input_target}"; then
      fail "OpenClaw native pending-input preparation changed the runtime, but its exact rollback artifact could not be proven safe. Manual recovery is required from ${pending_input_backup}."
    fi
  fi
  if (( pending_input_hotfix_status != 0 )); then
    fail "OpenClaw native pending-input preparation failed or exact run/request markers were not verified; the tested-pair rollback remains armed."
  fi
  if ! openclaw_pending_input_hotfix_is_applied "${pending_input_target}"; then
    fail "OpenClaw native pending-input preparation returned without the required exact runtime marker."
  fi

  # The replacement ask-user bridge was installed and semantically attested
  # before this function was allowed to patch native Claude routing. Restart
  # now so no running gateway can retain a half-old compatibility generation.
  if systemctl is-enabled openclaw-gateway &>/dev/null 2>&1; then
    if ! spin "Restarting OpenClaw gateway after compatibility hotfix" "systemctl restart openclaw-gateway"; then
      fail "OpenClaw gateway restart after required compatibility preparation failed."
    fi
    sleep 3
  fi

  ok "OpenClaw compatibility hotfix checked"
}

run_openclaw_state_repair_notice() {
  if $SKIP_OPENCLAW || ! command -v openclaw &>/dev/null; then
    return 0
  fi

  ok "OpenClaw state repair skipped (manual/admin action only)"
}

repair_openclaw_portal_model_config() {
  if $SKIP_OPENCLAW || ! command -v node &>/dev/null; then
    return 0
  fi

  local helper="${PORTAL_DIR}/backend/dist/utils/openclawCli.js"
  if [[ ! -f "${helper}" ]]; then
    warn "Portal OpenClaw model repair helper is missing. Skipping model config normalization."
    return 0
  fi

  if ! spin "Normalizing OpenClaw model configuration" "OPENCLAW_ALLOW_ROOT=1 NODE_PATH='${PORTAL_DIR}/backend/node_modules' node -e 'const helper = process.argv[1]; const mod = require(helper); const result = mod.repairClaudeSubscriptionConfig(); console.log(JSON.stringify(result));' '${helper}'"; then
    warn "OpenClaw model configuration normalization failed. Continuing install/update; check ${LOG_FILE}."
    return 0
  fi

  ok "OpenClaw model configuration checked"
}

bridge_openclaw_codex_cli_auth() {
  local portal_root="${1:-${PORTAL_DIR}}"
  if $SKIP_OPENCLAW || ! command -v node &>/dev/null; then
    return 0
  fi

  local helper="${portal_root}/backend/dist/services/openclawConfigManager.js"
  if [[ ! -f "${helper}" ]]; then
    warn "Portal OpenClaw Codex auth bridge helper is missing. Skipping Codex auth bridge."
    return 0
  fi

  local portal_service_codex_home=""
  local portal_env_file="${portal_root}/backend/.env.production"
  if [[ -f "${portal_env_file}" ]]; then
    portal_service_codex_home="$(
      read_env_value "${portal_env_file}" CODEX_HOME 2>/dev/null || true
    )"
  fi
  # The Portal service EnvironmentFile is the runtime authority. Never borrow
  # a transient installer-shell CODEX_HOME: an update launched from an agent
  # can inherit that agent's private Codex home, which the Portal service will
  # not use after restart.
  local portal_codex_home="${portal_service_codex_home:-${HOME}/.codex}"
  if [[ -n "${CODEX_HOME:-}" && "${CODEX_HOME}" != "${portal_codex_home}" ]]; then
    warn "Ignoring transient installer CODEX_HOME; using the Portal service credential path"
  fi
  local -x CODEX_HOME="${portal_codex_home}"
  if [[ ! -f "${portal_codex_home}/auth.json" ]]; then
    ok "OpenClaw Codex auth bridge skipped (no external Codex CLI auth found)"
    return 0
  fi

  if ! spin "Bridging Codex CLI auth into OpenClaw" "OPENCLAW_ALLOW_ROOT=1 NODE_PATH='${PORTAL_DIR}/backend/node_modules' node -e 'const helper = process.argv[1]; const mod = require(helper); const result = mod.pinCodexExternalCliAuthProfile(); console.log(JSON.stringify(result));' '${helper}'"; then
    warn "OpenClaw Codex auth bridge failed. Continuing update; re-run Codex setup in Settings if needed."
    return 0
  fi

  ok "OpenClaw Codex auth bridge checked"
}

openclaw_codex_plugin_package_dir() {
  local source_path="$1" candidate package_name depth
  [[ -n "${source_path}" ]] || return 1
  source_path="${source_path/#\~/${HOME}}"
  if [[ -d "${source_path}" ]]; then
    candidate="${source_path}"
  else
    candidate="$(dirname "${source_path}")"
  fi
  for depth in 1 2 3 4 5 6; do
    package_name="$(node_package_name_from_dir "${candidate}" || true)"
    if [[ "${package_name}" == "@openclaw/codex" ]]; then
      printf '%s\n' "${candidate}"
      return 0
    fi
    [[ "${candidate}" != "/" ]] || break
    candidate="$(dirname "${candidate}")"
  done
  return 1
}

openclaw_codex_plugin_details() {
  local inspect_json list_json presence
  inspect_json="$(OPENCLAW_ALLOW_ROOT=1 openclaw plugins inspect codex --json 2>>"${LOG_FILE}" || true)"
  if [[ -n "${inspect_json}" ]] && printf '%s' "${inspect_json}" | node -e '
let raw = "";
process.stdin.on("data", chunk => raw += chunk);
process.stdin.on("end", () => {
  try {
    const row = JSON.parse(raw);
    const plugin = row && typeof row === "object" ? row.plugin || {} : {};
    const install = row && typeof row === "object" ? row.install || {} : {};
    if (plugin.id !== "codex") process.exit(1);
    for (const value of [
      plugin.version,
      plugin.source,
      plugin.origin,
      install.source,
      install.spec,
      install.installPath,
      install.version,
    ]) console.log(typeof value === "string" ? value : "");
  } catch (_) {
    process.exit(1);
  }
});
'; then
    return 0
  fi

  # `plugins inspect` exits non-zero when codex is absent. Prove absence from
  # the machine-readable registry rather than treating every CLI failure as an
  # empty baseline that is safe to overwrite.
  list_json="$(OPENCLAW_ALLOW_ROOT=1 openclaw plugins list --json 2>>"${LOG_FILE}" || true)"
  presence="$(printf '%s' "${list_json}" | node -e '
let raw = "";
process.stdin.on("data", chunk => raw += chunk);
process.stdin.on("end", () => {
  try {
    const row = JSON.parse(raw);
    const plugins = Array.isArray(row?.plugins) ? row.plugins : null;
    if (!plugins) process.exit(1);
    process.stdout.write(plugins.some(plugin => plugin?.id === "codex") ? "present" : "absent");
  } catch (_) {
    process.exit(1);
  }
});
' 2>/dev/null || true)"
  [[ "${presence}" == "absent" ]] && return 2
  return 1
}

openclaw_codex_plugin_runtime_details() {
  local inspect_json list_json presence
  inspect_json="$(OPENCLAW_ALLOW_ROOT=1 openclaw plugins inspect codex --json --runtime 2>>"${LOG_FILE}" || true)"
  if [[ -n "${inspect_json}" ]] && printf '%s' "${inspect_json}" | node -e '
let raw = "";
process.stdin.on("data", chunk => raw += chunk);
process.stdin.on("end", () => {
  try {
    const row = JSON.parse(raw);
    const plugin = row && typeof row === "object" ? row.plugin || {} : {};
    const install = row && typeof row === "object" ? row.install || {} : {};
    if (
      plugin.id !== "codex"
      || plugin.status !== "loaded"
      || plugin.enabled !== true
      || plugin.activated !== true
      || !Array.isArray(plugin.agentHarnessIds)
      || !plugin.agentHarnessIds.includes("codex")
    ) process.exit(1);
    for (const value of [
      plugin.version,
      plugin.source,
      plugin.origin,
      install.source,
      install.spec,
      install.installPath,
      install.version,
      plugin.rootDir,
    ]) console.log(typeof value === "string" ? value : "");
  } catch (_) {
    process.exit(1);
  }
});
'; then
    return 0
  fi

  list_json="$(OPENCLAW_ALLOW_ROOT=1 openclaw plugins list --json 2>>"${LOG_FILE}" || true)"
  presence="$(printf '%s' "${list_json}" | node -e '
let raw = "";
process.stdin.on("data", chunk => raw += chunk);
process.stdin.on("end", () => {
  try {
    const row = JSON.parse(raw);
    const plugins = Array.isArray(row?.plugins) ? row.plugins : null;
    if (!plugins) process.exit(1);
    process.stdout.write(plugins.some(plugin => plugin?.id === "codex") ? "present" : "absent");
  } catch (_) {
    process.exit(1);
  }
});
' 2>/dev/null || true)"
  [[ "${presence}" == "absent" ]] && return 2
  return 1
}

openclaw_codex_plugin_catalog_package_dir() {
  local details="${1:-}"
  local package_dir package_real source_path
  local -a fields=()
  [[ -n "${details}" ]] || details="$(openclaw_codex_plugin_details)" || return 1
  mapfile -t fields <<< "${details}"
  source_path="${fields[1]:-${fields[5]:-}}"
  package_dir="$(openclaw_codex_plugin_package_dir "${source_path}" || true)"
  package_real="$(readlink -f -- "${package_dir}" 2>/dev/null || true)"
  [[ -n "${package_real}" && -d "${package_real}" ]] || return 1
  printf '%s\n' "${package_real}"
}

openclaw_codex_plugin_active_package_dir() {
  local details="${1:-}"
  local source_package_dir root_package_dir
  local source_real root_real
  local -a fields=()
  [[ -n "${details}" ]] || details="$(openclaw_codex_plugin_runtime_details)" || return 1
  mapfile -t fields <<< "${details}"
  source_package_dir="$(openclaw_codex_plugin_package_dir \
    "${fields[1]:-}" || true)"
  root_package_dir="$(openclaw_codex_plugin_package_dir \
    "${fields[7]:-}" || true)"
  [[ -n "${source_package_dir}" \
    && -n "${root_package_dir}" ]] || return 1
  source_real="$(readlink -f -- "${source_package_dir}" 2>/dev/null || true)"
  root_real="$(readlink -f -- "${root_package_dir}" 2>/dev/null || true)"
  [[ -n "${source_real}" \
    && "${source_real}" == "${root_real}" \
    && -d "${source_real}" ]] || return 1
  printf '%s\n' "${source_real}"
}

openclaw_codex_plugin_attested_package_dir() {
  local details="${1:-}"
  local active_package_dir install_package_dir
  local active_real install_real
  local -a fields=()
  [[ -n "${details}" ]] || details="$(openclaw_codex_plugin_runtime_details)" || return 1
  mapfile -t fields <<< "${details}"
  active_package_dir="$(openclaw_codex_plugin_active_package_dir \
    "${details}" || true)"
  install_package_dir="$(openclaw_codex_plugin_package_dir \
    "${fields[5]:-}" || true)"
  [[ -n "${active_package_dir}" \
    && -n "${install_package_dir}" ]] || return 1
  active_real="$(readlink -f -- "${active_package_dir}" 2>/dev/null || true)"
  install_real="$(readlink -f -- "${install_package_dir}" 2>/dev/null || true)"
  [[ -n "${active_real}" \
    && "${active_real}" == "${install_real}" \
    && -d "${active_real}" ]] || return 1
  printf '%s\n' "${active_real}"
}

verify_openclaw_codex_plugin_pin() {
  local expected_version="${1:-${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}}"
  local details package_dir package_name package_version
  local -a fields=()
  if ! details="$(openclaw_codex_plugin_runtime_details)"; then
    return 1
  fi
  mapfile -t fields <<< "${details}"
  local plugin_version="${fields[0]:-}"
  local plugin_source="${fields[1]:-}"
  local install_source="${fields[3]:-}"
  local install_spec="${fields[4]:-}"
  local recorded_version="${fields[6]:-}"

  package_dir="$(openclaw_codex_plugin_attested_package_dir \
    "${details}" || true)"
  package_name="$(node_package_name_from_dir "${package_dir}" || true)"
  package_version="$(node_package_version_from_dir "${package_dir}" || true)"

  # Registries upgraded from 3.26-era installs keep their legacy bare
  # "@openclaw/codex" spec even after an exact pinned reinstall; the exact
  # version is still enforced through plugin, recorded, and package versions.
  [[ "${plugin_version}" == "${expected_version}" \
    && "${install_source}" == "npm" \
    && ( "${install_spec}" == "@openclaw/codex@${expected_version}" \
      || "${install_spec}" == "@openclaw/codex" ) \
    && "${recorded_version}" == "${expected_version}" \
    && "${package_name}" == "@openclaw/codex" \
    && "${package_version}" == "${expected_version}" \
    && -n "${plugin_source}" \
    && "${plugin_source}" != *"/.openclaw/npm/node_modules/@openclaw/codex/"* \
    && "${plugin_source}" != "~/.openclaw/npm/node_modules/@openclaw/codex/"* ]]
}

resolve_openclaw_codex_plugin_pending_input_hotfix_target() {
  local details package_dir package_name package_version target
  verify_openclaw_codex_plugin_pin "${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}" \
    || return 1
  details="$(openclaw_codex_plugin_runtime_details)" || return 1
  package_dir="$(openclaw_codex_plugin_attested_package_dir \
    "${details}" || true)"
  package_name="$(node_package_name_from_dir "${package_dir}" || true)"
  package_version="$(node_package_version_from_dir "${package_dir}" || true)"
  [[ "${package_name}" == "@openclaw/codex" \
    && "${package_version}" == "${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}" \
    && -d "${package_dir}/dist" ]] || return 1
  target="$(resolve_openclaw_pending_input_hotfix_target \
    "${package_dir}/dist" || true)"
  [[ -n "${target}" ]] || return 1
  printf '%s\n' "${target}"
}

openclaw_codex_plugin_pending_input_hotfix_is_applied() {
  local target="$1"
  python3 - "${target}" <<'PY'
from pathlib import Path
import sys

marker = 'const BRIDGESLLM_PENDING_INPUT_HOTFIX_MARKER = "bridgesllm-openclaw-pending-input-v1";'
symbol = 'Symbol.for("bridgesllm.openclaw.pending-input.codex-plugin.v1")'
try:
    text = Path(sys.argv[1]).read_text(encoding="utf-8")
except (OSError, UnicodeError):
    raise SystemExit(1)
raise SystemExit(0 if text.count(marker) == 1 and text.count(symbol) == 1 else 1)
PY
}

manage_openclaw_codex_plugin_pending_input_backup() {
  local target="$1"
  local hotfix_script="$2"
  local action="$3"
  local backup="${target}.bridgesllm-pending-input-v1.bak"
  python3 - \
    "${target}" \
    "${backup}" \
    "${hotfix_script}" \
    "${action}" \
    "${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}" <<'PY'
import os
from pathlib import Path
import stat
import subprocess
import sys
import tempfile

target = Path(sys.argv[1])
backup = Path(sys.argv[2])
hotfix_script = Path(sys.argv[3])
action = sys.argv[4]
expected_version = sys.argv[5]
marker = 'const BRIDGESLLM_PENDING_INPUT_HOTFIX_MARKER = "bridgesllm-openclaw-pending-input-v1";'
symbol = 'Symbol.for("bridgesllm.openclaw.pending-input.codex-plugin.v1")'
if action not in {"normalize", "retire"}:
    raise SystemExit(1)
if backup != target.with_name(target.name + ".bridgesllm-pending-input-v1.bak"):
    raise SystemExit(1)
for path in (target, backup, hotfix_script):
    try:
        metadata = os.lstat(path)
    except OSError:
        raise SystemExit(1)
    if (
        not stat.S_ISREG(metadata.st_mode)
        or stat.S_ISLNK(metadata.st_mode)
        or metadata.st_nlink != 1
    ):
        raise SystemExit(1)
try:
    package_path = target.parent.parent / "package.json"
    package_metadata = os.lstat(package_path)
    if (
        not stat.S_ISREG(package_metadata.st_mode)
        or stat.S_ISLNK(package_metadata.st_mode)
        or package_metadata.st_nlink != 1
    ):
        raise OSError
    package_bytes = package_path.read_bytes()
    import json
    package = json.loads(package_bytes.decode("utf-8"))
    if (
        package.get("name") != "@openclaw/codex"
        or package.get("version") != expected_version
    ):
        raise OSError
    target_bytes = target.read_bytes()
    backup_bytes = backup.read_bytes()
    target_text = target.read_text(encoding="utf-8")
    backup_text = backup.read_text(encoding="utf-8")
except (OSError, UnicodeError, ValueError):
    raise SystemExit(1)
if (
    marker in backup_text
    or symbol in backup_text
):
    raise SystemExit(1)

# The recovery artifact is trusted only if the exact bundled patcher accepts
# it as the pristine pinned provider source and deterministically reproduces
# the current patched bytes. Syntax alone is not provenance.
with tempfile.TemporaryDirectory(prefix="bridgesllm-codex-pending-proof-") as temporary:
    package_root = Path(temporary) / "package"
    dist = package_root / "dist"
    dist.mkdir(parents=True)
    (package_root / "package.json").write_bytes(package_bytes)
    fixture = dist / target.name
    fixture.write_bytes(backup_bytes)
    environment = os.environ.copy()
    environment.update({
        "PORTAL_OPENCLAW_PENDING_INPUT_STRICT": "1",
        "PORTAL_REQUIRED_OPENCLAW_PACKAGE_NAME": "@openclaw/codex",
        "PORTAL_REQUIRED_OPENCLAW_PACKAGE_VERSION": expected_version,
    })
    proof = subprocess.run(
        ["bash", str(hotfix_script), str(dist)],
        env=environment,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
    )
    if proof.returncode != 0:
        raise SystemExit(1)
    reproduced_bytes = fixture.read_bytes()

target_is_patched = (
    target_text.count(marker) == 1
    and target_text.count(symbol) == 1
    and reproduced_bytes == target_bytes
)
target_is_pristine = (
    marker not in target_text
    and symbol not in target_text
    and target_bytes == backup_bytes
)
if action == "retire":
    if not target_is_patched:
        raise SystemExit(1)
    backup.unlink()
elif target_is_patched:
    # Interrupted after publishing the exact patched bytes: restore the proven
    # original before capturing a fresh package-level rollback baseline.
    os.replace(backup, target)
elif target_is_pristine:
    # Interrupted before publication. The target already is the proven
    # original, so remove only the byte-identical redundant artifact.
    backup.unlink()
else:
    raise SystemExit(1)
directory_fd = os.open(target.parent, os.O_RDONLY)
try:
    os.fsync(directory_fd)
finally:
    os.close(directory_fd)
PY
}

normalize_openclaw_codex_plugin_pending_input_recovery_artifact() {
  manage_openclaw_codex_plugin_pending_input_backup \
    "$1" "$2" normalize
}

retire_openclaw_codex_plugin_pending_input_backup() {
  manage_openclaw_codex_plugin_pending_input_backup \
    "$1" "$2" retire
}

verify_openclaw_codex_plugin_pending_input_hotfix() {
  if $SKIP_OPENCLAW || ! command -v openclaw &>/dev/null; then
    return 0
  fi
  local target backup
  target="$(resolve_openclaw_codex_plugin_pending_input_hotfix_target || true)"
  [[ -n "${target}" ]] || return 1
  backup="${target}.bridgesllm-pending-input-v1.bak"
  openclaw_codex_plugin_pending_input_hotfix_is_applied "${target}" \
    && [[ ! -e "${backup}" && ! -L "${backup}" ]] \
    && node --check "${target}" >/dev/null 2>&1
}

stage_openclaw_codex_plugin_rollback_package() {
  local expected_version="$1" source_path="$2"
  local package_dir backup_dir packed_name packed_path packed_version
  package_dir="$(openclaw_codex_plugin_package_dir "${source_path}" || true)"
  [[ -n "${package_dir}" && -f "${package_dir}/package.json" ]] || return 1
  backup_dir="${UPDATE_RECOVERY_BACKUP_DIR:-/tmp}/openclaw-codex-plugin"
  mkdir -p "${backup_dir}"
  packed_name="$(cd "${backup_dir}" && npm pack --ignore-scripts --silent "${package_dir}" 2>> "$LOG_FILE" | tail -1)"
  packed_path="${backup_dir}/${packed_name}"
  [[ -n "${packed_name}" && -f "${packed_path}" ]] || return 1
  packed_version="$(tar -xOf "${packed_path}" package/package.json 2>/dev/null \
    | node -e 'let s=""; process.stdin.on("data", c => s += c); process.stdin.on("end", () => { try { console.log(JSON.parse(s).version || ""); } catch {} });' \
    | head -1)"
  if [[ "${packed_version}" != "${expected_version}" ]]; then
    rm -f "${packed_path}"
    return 1
  fi
  chmod 600 "${packed_path}" 2>/dev/null || true
  OPENCLAW_CODEX_PLUGIN_ROLLBACK_TARBALL="${packed_path}"
}

capture_openclaw_codex_plugin_baseline() {
  $OPENCLAW_CODEX_PLUGIN_BASELINE_CAPTURED && return 0

  local details status package_source
  local -a fields=()
  if details="$(openclaw_codex_plugin_details)"; then
    mapfile -t fields <<< "${details}"
    local plugin_version="${fields[0]:-}"
    [[ -n "${plugin_version}" ]] || return 1
    # This capture runs before old OpenClaw cores are replaced, so it may not
    # depend on the new runtime-inspection schema. Prefer the catalog's loaded
    # source over a stale installPath and prove the packed package/version.
    package_source="$(openclaw_codex_plugin_catalog_package_dir \
      "${details}" || true)"
    [[ -n "${package_source}" ]] || return 1
    stage_openclaw_codex_plugin_rollback_package "${plugin_version}" "${package_source}" || return 1
    OPENCLAW_CODEX_PLUGIN_PREEXISTED=true
    OPENCLAW_CODEX_PLUGIN_PREUPDATE_VERSION="${plugin_version}"
  else
    status=$?
    [[ ${status} -eq 2 ]] || return 1
    OPENCLAW_CODEX_PLUGIN_PREEXISTED=false
    OPENCLAW_CODEX_PLUGIN_PREUPDATE_VERSION=""
  fi

  OPENCLAW_CODEX_PLUGIN_BASELINE_CAPTURED=true
}

rollback_openclaw_codex_plugin() {
  local defer_gateway_restart="${1:-false}"
  local rollback_ok=true details status package_dir package_version
  local -a fields=()
  if $OPENCLAW_CODEX_PLUGIN_PREEXISTED; then
    if [[ -z "${OPENCLAW_CODEX_PLUGIN_ROLLBACK_TARBALL:-}" \
      || ! -f "${OPENCLAW_CODEX_PLUGIN_ROLLBACK_TARBALL}" ]] \
      || ! OPENCLAW_ALLOW_ROOT=1 openclaw plugins install "${OPENCLAW_CODEX_PLUGIN_ROLLBACK_TARBALL}" --force --pin >> "$LOG_FILE" 2>&1; then
      rollback_ok=false
    else
      if details="$(openclaw_codex_plugin_details)"; then
        mapfile -t fields <<< "${details}"
        package_dir="$(openclaw_codex_plugin_catalog_package_dir \
          "${details}" || true)"
        package_version="$(node_package_version_from_dir "${package_dir}" || true)"
        [[ "${fields[0]:-}" == "${OPENCLAW_CODEX_PLUGIN_PREUPDATE_VERSION}" \
          && "${package_version}" == "${OPENCLAW_CODEX_PLUGIN_PREUPDATE_VERSION}" ]] || rollback_ok=false
      else
        rollback_ok=false
      fi
    fi
  else
    if details="$(openclaw_codex_plugin_details)"; then
      OPENCLAW_ALLOW_ROOT=1 openclaw plugins uninstall codex --force >> "$LOG_FILE" 2>&1 || rollback_ok=false
    else
      status=$?
      [[ ${status} -eq 2 ]] || rollback_ok=false
    fi
  fi

  if [[ "${defer_gateway_restart}" != "true" ]] \
    && systemctl is-enabled openclaw-gateway >/dev/null 2>&1; then
    systemctl restart openclaw-gateway >> "$LOG_FILE" 2>&1 || rollback_ok=false
    verify_openclaw_gateway_stable "${PIN_OPENCLAW_RUNTIME_VERSION}" 18 || rollback_ok=false
  fi
  $rollback_ok && OPENCLAW_CODEX_PLUGIN_UPDATE_ATTEMPTED=false
  $rollback_ok
}

rollback_openclaw_tested_pair() {
  local core_rollback_pending=false
  local hotfix_rollback_pending=false
  local claude_ask_user_rollback_pending=false
  local ask_user_transaction_rollback_pending=false
  local core_rollback_ok=true
  local hotfix_rollback_ok=true
  local claude_ask_user_rollback_ok=true
  local ask_user_transaction_rollback_ok=true
  local plugin_rollback_ok=true
  local defer_plugin_restart=false
  local plugin_retry_restarted=false

  if ! $OPENCLAW_UPGRADE_COMMITTED \
    && { $OPENCLAW_PACKAGE_UPDATE_ATTEMPTED \
      || $OPENCLAW_PACKAGE_UPDATED \
      || [[ -n "${OPENCLAW_UPGRADE_STATE_MANIFEST:-}" ]]; }; then
    core_rollback_pending=true
  fi
  if $OPENCLAW_PENDING_INPUT_HOTFIX_APPLIED \
    && ! $OPENCLAW_PENDING_INPUT_HOTFIX_COMMITTED; then
    hotfix_rollback_pending=true
  fi
  if $OPENCLAW_CLAUDE_ASK_USER_HOTFIX_APPLIED \
    && ! $OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED; then
    claude_ask_user_rollback_pending=true
  fi
  if $OPENCLAW_ASK_USER_TRANSACTION_ARMED \
    && ! $OPENCLAW_ASK_USER_TRANSACTION_COMMITTED; then
    ask_user_transaction_rollback_pending=true
  fi
  if $core_rollback_pending || $hotfix_rollback_pending \
    || $claude_ask_user_rollback_pending \
    || $ask_user_transaction_rollback_pending; then
    defer_plugin_restart=true
  fi

  # Keep the replacement ask-user bridge and its durable rollback journal in
  # place until native Claude prompting is restored. If rollback itself loses
  # power, that ordering guarantees at least one working question path rather
  # than deleting the replacement while native AskUserQuestion is suppressed.
  if $OPENCLAW_CODEX_PLUGIN_UPDATE_ATTEMPTED; then
    rollback_openclaw_codex_plugin "${defer_plugin_restart}" || plugin_rollback_ok=false
  fi

  # The native pending-input patch has its own byte-exact recovery artifact.
  # Restore it before any package-level rollback so every later preparation
  # failure removes the Portal mutation even when the pinned core preexisted.
  if $hotfix_rollback_pending; then
    rollback_openclaw_pending_input_hotfix || hotfix_rollback_ok=false
  fi
  if $claude_ask_user_rollback_pending; then
    rollback_openclaw_claude_ask_user_hotfix \
      || claude_ask_user_rollback_ok=false
  fi

  if $core_rollback_pending; then
    # Do not boot the restored core until the matching plugin/config baseline
    # is back. One final restart below crosses the complete rollback boundary.
    rollback_openclaw_package_update true || core_rollback_ok=false
  fi

  # If the new-core CLI could not restore the old plugin, retry after the old
  # core is back. This makes recovery resilient to cross-revision plugin CLI
  # incompatibility while preserving the original rollback artifacts.
  if $OPENCLAW_CODEX_PLUGIN_UPDATE_ATTEMPTED; then
    if rollback_openclaw_codex_plugin "${ask_user_transaction_rollback_pending}"; then
      plugin_rollback_ok=true
      if ! $ask_user_transaction_rollback_pending; then
        plugin_retry_restarted=true
      fi
    else
      plugin_rollback_ok=false
    fi
  fi

  # Native/core bytes are safe now. Restore the previous bridge/config while
  # preserving the journal until that restoration and the final gateway boot
  # both succeed. The helper itself is idempotent, so a later recovery can
  # repeat this exact step after interruption.
  if $ask_user_transaction_rollback_pending; then
    rollback_bridgesllm_ask_user_transaction true \
      || ask_user_transaction_rollback_ok=false
  fi

  # A package rollback performs its own final restart. When only the exact
  # bundle bytes changed, restart an already-running gateway once after those
  # bytes and any plugin baseline are back. Never start a gateway that was
  # intentionally stopped.
  if { $core_rollback_pending || $hotfix_rollback_pending \
      || $claude_ask_user_rollback_pending \
      || $ask_user_transaction_rollback_pending; } \
    && $hotfix_rollback_ok && $claude_ask_user_rollback_ok \
    && $ask_user_transaction_rollback_ok \
    && ! $plugin_retry_restarted \
    && { $OPENCLAW_GATEWAY_WAS_ACTIVE \
      || systemctl is-active --quiet openclaw-gateway >/dev/null 2>&1; }; then
    local rollback_gateway_version="${PIN_OPENCLAW_RUNTIME_VERSION}"
    $core_rollback_pending \
      && rollback_gateway_version="${OPENCLAW_PREUPDATE_RUNTIME_VERSION:-}"
    if [[ -z "${rollback_gateway_version}" ]] \
      || ! systemctl restart openclaw-gateway >> "$LOG_FILE" 2>&1 \
      || ! verify_openclaw_gateway_stable "${rollback_gateway_version}" 18; then
      hotfix_rollback_ok=false
      claude_ask_user_rollback_ok=false
      ask_user_transaction_rollback_ok=false
    fi
  fi

  $core_rollback_ok && $hotfix_rollback_ok \
    && $claude_ask_user_rollback_ok && $ask_user_transaction_rollback_ok \
    && $plugin_rollback_ok
}

verify_openclaw_tested_pair() {
  # The gateway may still be settling from the plugin-load restart, and the
  # deep status probe has no retry of its own, so a single silent flake here
  # must not unwind an otherwise verified core/plugin migration. Retry the
  # runtime-facing probes over a bounded window and log what was observed.
  local attempt observed_gateway="" openclaw_package_dir=""
  local claude_ask_user_target=""
  verify_openclaw_core_package_pin || return 1
  openclaw_package_dir="$(openclaw_core_package_dir || true)"
  claude_ask_user_target="$(
    resolve_openclaw_claude_ask_user_hotfix_target \
      "${openclaw_package_dir}/dist" || true
  )"
  [[ -n "${claude_ask_user_target}" ]] || return 1
  openclaw_claude_ask_user_hotfix_is_applied \
    "${claude_ask_user_target}" || return 1
  for attempt in 1 2 3 4 5 6; do
    observed_gateway="$(openclaw_gateway_version || true)"
    if [[ "${observed_gateway}" == "${PIN_OPENCLAW_RUNTIME_VERSION}" ]] \
      && OPENCLAW_ALLOW_ROOT=1 openclaw gateway status --require-rpc --timeout 10000 >> "$LOG_FILE" 2>&1 \
      && verify_openclaw_codex_plugin_pin "${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}" \
      && verify_openclaw_codex_plugin_pending_input_hotfix \
      && verify_bridgesllm_ask_user_tested_pair; then
      return 0
    fi
    echo "tested-pair verify attempt ${attempt}: gateway version '${observed_gateway}' (expected '${PIN_OPENCLAW_RUNTIME_VERSION}')" >> "$LOG_FILE"
    sleep 5
  done
  return 1
}

verify_bridgesllm_ask_user_plugin_config() {
  local config_path="$1"
  python3 - "${config_path}" <<'PY'
import json
import os
import pathlib
import stat
import sys

path = pathlib.Path(sys.argv[1])
try:
    metadata = os.lstat(path)
    value = json.loads(path.read_text(encoding="utf-8"))
except (OSError, UnicodeError, json.JSONDecodeError):
    raise SystemExit(1)
if (
    not stat.S_ISREG(metadata.st_mode)
    or stat.S_ISLNK(metadata.st_mode)
    or metadata.st_uid != 0
    or metadata.st_gid != 0
    or metadata.st_nlink != 1
    or stat.S_IMODE(metadata.st_mode) != 0o600
    or not isinstance(value, dict)
):
    raise SystemExit(1)
plugins = value.get("plugins")
entries = plugins.get("entries") if isinstance(plugins, dict) else None
entry = entries.get("bridgesllm-ask-user") if isinstance(entries, dict) else None
if not isinstance(entry, dict) or entry.get("enabled") is not True:
    raise SystemExit(1)
allow = plugins.get("allow")
if allow is not None and (
    not isinstance(allow, list)
    or "bridgesllm-ask-user" not in allow
):
    raise SystemExit(1)
agents = value.get("agents")
defaults = agents.get("defaults") if isinstance(agents, dict) else None
cli_backends = defaults.get("cliBackends") if isinstance(defaults, dict) else None
claude_backend = cli_backends.get("claude-cli") if isinstance(cli_backends, dict) else None
claude_env = claude_backend.get("env") if isinstance(claude_backend, dict) else None
if (
    not isinstance(claude_backend, dict)
    or not isinstance(claude_backend.get("command"), str)
    or not claude_backend["command"].strip()
    or not isinstance(claude_env, dict)
    or claude_env.get("MCP_TOOL_TIMEOUT") != "660000"
    or claude_env.get("CLAUDE_CODE_MCP_TOOL_IDLE_TIMEOUT") != "660000"
):
    raise SystemExit(1)
PY
}

verify_bridgesllm_ask_user_plugin_runtime() {
  local target_dir="$1"
  local output_path="$2"
  if ! OPENCLAW_ALLOW_ROOT=1 openclaw plugins inspect \
      bridgesllm-ask-user --json --runtime > "${output_path}" \
      2>> "${LOG_FILE}"; then
    return 1
  fi
  python3 - \
    "${output_path}" \
    "${target_dir}" \
    "${PIN_BRIDGESLLM_ASK_USER_PLUGIN_VERSION}" <<'PY'
import json
import os
import pathlib
import sys

report_path = pathlib.Path(sys.argv[1])
target = pathlib.Path(sys.argv[2])
expected_version = sys.argv[3]
try:
    report = json.loads(report_path.read_text(encoding="utf-8"))
except (OSError, UnicodeError, json.JSONDecodeError):
    raise SystemExit(1)
plugin = report.get("plugin") if isinstance(report, dict) else None
diagnostics = report.get("diagnostics") if isinstance(report, dict) else None
methods = report.get("gatewayMethods") if isinstance(report, dict) else None
tool_names = plugin.get("toolNames") if isinstance(plugin, dict) else None
typed_hooks = report.get("typedHooks") if isinstance(report, dict) else None
if (
    not isinstance(plugin, dict)
    or plugin.get("id") != "bridgesllm-ask-user"
    or plugin.get("version") != expected_version
    or plugin.get("status") != "loaded"
    or plugin.get("enabled") is not True
    or plugin.get("activated") is not True
    or plugin.get("error")
    or os.path.realpath(plugin.get("rootDir", "")) != os.path.realpath(target)
    or os.path.realpath(plugin.get("source", ""))
        != os.path.realpath(target / "index.js")
    or not isinstance(tool_names, list)
    or "ask_user_question" not in tool_names
    or plugin.get("hookCount") != 1
    or not isinstance(typed_hooks, list)
    or not any(
        isinstance(item, dict) and item.get("name") == "before_tool_call"
        for item in typed_hooks
    )
    or not isinstance(methods, list)
    or not {
        "bridgesllm.ask_user.probe",
        "bridgesllm.ask_user.pending",
        "bridgesllm.ask_user.answer",
        "bridgesllm.ask_user.dismiss",
        "bridgesllm.ask_user.steer",
    }.issubset(set(methods))
    or not isinstance(diagnostics, list)
    or any(
        isinstance(item, dict) and item.get("level") == "error"
        for item in diagnostics
    )
):
    raise SystemExit(1)
PY
}

verify_bridgesllm_ask_user_gateway_method() {
  local output_path="$1"
  local mode="${2:-full}"
  local nonce session_key run_id request_id method params probe_kind
  case "${mode}" in
    full|bootstrap) ;;
    *) return 1 ;;
  esac
  nonce="$(rand_hex 12)" || return 1
  session_key="agent:main:bridgesllm-install-probe-${nonce}"
  run_id="bridgesllm-install-probe-${nonce}"
  request_id="bridgesllm-install-request-${nonce}"
  for probe_kind in probe pending answer dismiss steer; do
    case "${probe_kind}" in
      probe)
        method="bridgesllm.ask_user.probe"
        params="{\"nonce\":\"${nonce}\"}"
        ;;
      pending)
        method="bridgesllm.ask_user.pending"
        params="{\"sessionKey\":\"${session_key}\",\"expectedRunId\":\"${run_id}\"}"
        ;;
      answer)
        method="bridgesllm.ask_user.answer"
        params="{\"sessionKey\":\"${session_key}\",\"expectedRunId\":\"${run_id}\",\"requestId\":\"${request_id}\",\"text\":\"BridgesLLM readiness probe.\"}"
        ;;
      dismiss)
        method="bridgesllm.ask_user.dismiss"
        params="{\"sessionKey\":\"${session_key}\",\"expectedRunId\":\"${run_id}\",\"requestId\":\"${request_id}\"}"
        ;;
      steer)
        method="bridgesllm.ask_user.steer"
        params="{\"sessionKey\":\"${session_key}\",\"expectedRunId\":\"${run_id}\",\"requestId\":\"${request_id}\",\"text\":\"BridgesLLM readiness probe.\"}"
        ;;
    esac
    if ! OPENCLAW_ALLOW_ROOT=1 openclaw gateway call \
        "${method}" \
        --json \
        --timeout 10000 \
        --params "${params}" > "${output_path}" 2>> "${LOG_FILE}"; then
      return 1
    fi
    if ! python3 - \
      "${output_path}" "${probe_kind}" "${request_id}" "${mode}" <<'PY'
import json
import pathlib
import sys

try:
    response = json.loads(pathlib.Path(sys.argv[1]).read_text(encoding="utf-8"))
except (OSError, UnicodeError, json.JSONDecodeError):
    raise SystemExit(1)
kind = sys.argv[2]
request_id = sys.argv[3]
mode = sys.argv[4]
if mode not in {"full", "bootstrap"}:
    raise SystemExit(1)
if not isinstance(response, dict):
    raise SystemExit(1)
if kind == "probe":
    full_valid = (
        response.get("ok") is True
        and response.get("code") == "SEMANTIC_PROBE_OK"
        and response.get("toolName") == "ask_user_question"
        and response.get("answer") is True
        and response.get("dismiss") is True
        and response.get("steer") is True
        and response.get("activeRunSteer") is True
    )
    bootstrap_valid = (
        response.get("ok") is False
        and response.get("code") == "SEMANTIC_PROBE_FAILED"
        and response.get("toolName") == "ask_user_question"
        and response.get("answer") is True
        and response.get("dismiss") is True
        and response.get("steer") is True
        and response.get("activeRunSteer") is False
    )
    valid = full_valid or (mode == "bootstrap" and bootstrap_valid)
elif kind == "pending":
    valid = (
        response.get("pending") is False
        and response.get("code") == "NO_ACTIVE_RUN"
    )
else:
    valid = (
        response.get("accepted") is False
        and response.get("code") == "NO_ACTIVE_RUN"
        and response.get("requestId") == request_id
    )
if not valid:
    raise SystemExit(1)
PY
    then
      return 1
    fi
  done
}

verify_bridgesllm_ask_user_tested_pair() {
  local openclaw_state_dir="${1:-/root/.openclaw}"
  local mode="${2:-full}"
  local target_dir="${openclaw_state_dir}/extensions/bridgesllm-ask-user"
  local config_path="${openclaw_state_dir}/openclaw.json"
  local output_path status=0
  output_path="$(mktemp /tmp/bridgesllm-ask-user-verify.XXXXXX)" \
    || return 1
  chmod 600 "${output_path}" 2>/dev/null || true
  verify_bridgesllm_ask_user_plugin_config "${config_path}" \
    && verify_bridgesllm_ask_user_plugin_runtime \
      "${target_dir}" "${output_path}" \
    && verify_bridgesllm_ask_user_gateway_method "${output_path}" "${mode}" \
    || status=$?
  rm -f -- "${output_path}"
  return "${status}"
}

write_bridgesllm_ask_user_transaction_manifest() {
  local transaction_dir="$1" openclaw_state_dir="$2" target_dir="$3"
  local config_path="$4" target_preexisted="$5" config_preexisted="$6"
  local gateway_was_active="$7"
  python3 - \
    "${transaction_dir}" \
    "${openclaw_state_dir}" \
    "${target_dir}" \
    "${config_path}" \
    "${target_preexisted}" \
    "${config_preexisted}" \
    "${gateway_was_active}" <<'PY'
import hashlib
import json
import os
from pathlib import Path
import stat
import sys
import tempfile

transaction = Path(sys.argv[1]).absolute()
state_root = Path(sys.argv[2]).absolute()
target = Path(sys.argv[3]).absolute()
config = Path(sys.argv[4]).absolute()
target_preexisted = sys.argv[5] == "true"
config_preexisted = sys.argv[6] == "true"
gateway_was_active = sys.argv[7] == "true"
manifest = transaction / "manifest.json"
previous_config = transaction / "previous-openclaw.json"

def safe_directory(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISDIR(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def safe_file(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISREG(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_nlink == 1
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def tree_digest(root):
    digest = hashlib.sha256()
    for path in [root, *sorted(root.rglob("*"), key=lambda item: str(item.relative_to(root)))]:
        metadata = os.lstat(path)
        relative = "." if path == root else str(path.relative_to(root))
        digest.update(relative.encode("utf-8") + b"\0")
        if stat.S_ISDIR(metadata.st_mode):
            digest.update(b"d\0")
        elif stat.S_ISREG(metadata.st_mode):
            digest.update(b"f\0" + path.read_bytes())
        elif stat.S_ISLNK(metadata.st_mode):
            digest.update(b"l\0" + os.readlink(path).encode("utf-8"))
        else:
            raise OSError(f"unsupported plugin entry: {path}")
    return digest.hexdigest()

try:
    if (
        transaction != state_root / ".bridgesllm-ask-user-tested-pair-v1"
        or target != state_root / "extensions" / "bridgesllm-ask-user"
        or config != state_root / "openclaw.json"
        or not safe_directory(state_root)
        or not safe_directory(transaction)
        or not safe_directory(target.parent)
        or os.path.lexists(manifest)
    ):
        raise OSError("unsafe ask-user transaction paths")
    if target_preexisted and not safe_directory(target):
        raise OSError("unsafe previous ask-user plugin")
    if config_preexisted and not safe_file(previous_config):
        raise OSError("unsafe previous OpenClaw config")
    value = {
        "schema": "bridgesllm-ask-user-tested-pair-v1",
        "stateRoot": str(state_root),
        "targetDir": str(target),
        "configPath": str(config),
        "targetPreexisted": target_preexisted,
        "configPreexisted": config_preexisted,
        "gatewayWasActive": gateway_was_active,
        "previousPluginSha256": tree_digest(target) if target_preexisted else None,
        "previousConfigSha256": (
            hashlib.sha256(previous_config.read_bytes()).hexdigest()
            if config_preexisted
            else None
        ),
    }
except OSError:
    raise SystemExit(1)

temporary_name = ""
try:
    with tempfile.NamedTemporaryFile(
        mode="w",
        encoding="utf-8",
        dir=transaction,
        prefix=".manifest-",
        suffix=".tmp",
        delete=False,
    ) as stream:
        temporary_name = stream.name
        json.dump(value, stream, sort_keys=True, separators=(",", ":"))
        stream.write("\n")
        stream.flush()
        os.fsync(stream.fileno())
    os.chmod(temporary_name, 0o600)
    os.replace(temporary_name, manifest)
    temporary_name = ""
    directory_fd = os.open(transaction, os.O_RDONLY)
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if temporary_name:
        try:
            Path(temporary_name).unlink()
        except FileNotFoundError:
            pass
PY
}

rollback_bridgesllm_ask_user_transaction() {
  $OPENCLAW_ASK_USER_TRANSACTION_ARMED || return 0
  $OPENCLAW_ASK_USER_TRANSACTION_COMMITTED && return 0
  local defer_gateway_restart="${1:-false}"
  local transaction_dir="${OPENCLAW_ASK_USER_TRANSACTION_DIR:-}"
  local gateway_was_active=""
  [[ -n "${transaction_dir}" ]] || return 1
  if ! gateway_was_active="$(python3 - "${transaction_dir}" <<'PY'
import hashlib
import json
import os
from pathlib import Path
import shutil
import stat
import sys
import tempfile

transaction = Path(sys.argv[1]).absolute()
manifest_path = transaction / "manifest.json"
previous_plugin = transaction / "previous-plugin"
previous_config = transaction / "previous-openclaw.json"
failed_plugin = transaction / "failed-plugin"
failed_config = transaction / "failed-openclaw.json"

def safe_directory(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISDIR(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def safe_file(path):
    metadata = os.lstat(path)
    return (
        stat.S_ISREG(metadata.st_mode)
        and not stat.S_ISLNK(metadata.st_mode)
        and metadata.st_nlink == 1
        and metadata.st_uid == 0
        and metadata.st_gid == 0
    )

def tree_digest(root):
    digest = hashlib.sha256()
    for path in [root, *sorted(root.rglob("*"), key=lambda item: str(item.relative_to(root)))]:
        metadata = os.lstat(path)
        relative = "." if path == root else str(path.relative_to(root))
        digest.update(relative.encode("utf-8") + b"\0")
        if stat.S_ISDIR(metadata.st_mode):
            digest.update(b"d\0")
        elif stat.S_ISREG(metadata.st_mode):
            digest.update(b"f\0" + path.read_bytes())
        elif stat.S_ISLNK(metadata.st_mode):
            digest.update(b"l\0" + os.readlink(path).encode("utf-8"))
        else:
            raise OSError(f"unsupported plugin entry: {path}")
    return digest.hexdigest()

try:
    if not safe_directory(transaction) or not safe_file(manifest_path):
        raise OSError("unsafe transaction")
    value = json.loads(manifest_path.read_text(encoding="utf-8"))
    state_root = Path(value["stateRoot"]).absolute()
    target = Path(value["targetDir"]).absolute()
    config = Path(value["configPath"]).absolute()
    if (
        value.get("schema") != "bridgesllm-ask-user-tested-pair-v1"
        or transaction != state_root / ".bridgesllm-ask-user-tested-pair-v1"
        or target != state_root / "extensions" / "bridgesllm-ask-user"
        or config != state_root / "openclaw.json"
        or not safe_directory(state_root)
        or not safe_directory(target.parent)
    ):
        raise OSError("invalid transaction manifest")

    if value.get("targetPreexisted") is True:
        expected_plugin_hash = value.get("previousPluginSha256")
        if os.path.lexists(previous_plugin):
            if not safe_directory(previous_plugin) or tree_digest(previous_plugin) != expected_plugin_hash:
                raise OSError("previous plugin does not match transaction manifest")
            if os.path.lexists(target):
                if not safe_directory(target) or os.path.lexists(failed_plugin):
                    raise OSError("unsafe candidate plugin")
                os.replace(target, failed_plugin)
            os.replace(previous_plugin, target)
        elif not safe_directory(target) or tree_digest(target) != expected_plugin_hash:
            raise OSError("previous plugin is unavailable")
    elif os.path.lexists(target):
        if not safe_directory(target) or os.path.lexists(failed_plugin):
            raise OSError("unsafe fresh candidate plugin")
        os.replace(target, failed_plugin)

    if value.get("configPreexisted") is True:
        expected_config_hash = value.get("previousConfigSha256")
        if (
            not safe_file(previous_config)
            or hashlib.sha256(previous_config.read_bytes()).hexdigest() != expected_config_hash
        ):
            raise OSError("previous config does not match transaction manifest")
        temporary_name = ""
        try:
            with tempfile.NamedTemporaryFile(
                mode="wb",
                dir=state_root,
                prefix=".bridgesllm-ask-user-config-restore-",
                suffix=".tmp",
                delete=False,
            ) as stream:
                temporary_name = stream.name
                stream.write(previous_config.read_bytes())
                stream.flush()
                os.fsync(stream.fileno())
            shutil.copystat(previous_config, temporary_name, follow_symlinks=True)
            os.replace(temporary_name, config)
            temporary_name = ""
        finally:
            if temporary_name:
                try:
                    Path(temporary_name).unlink()
                except FileNotFoundError:
                    pass
    elif os.path.lexists(config):
        if not safe_file(config) or os.path.lexists(failed_config):
            raise OSError("unsafe fresh config")
        os.replace(config, failed_config)

    for directory in {state_root, target.parent}:
        directory_fd = os.open(directory, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
except (OSError, KeyError, TypeError, UnicodeError, json.JSONDecodeError):
    raise SystemExit(1)
print("true" if value.get("gatewayWasActive") is True else "false")
PY
  )"; then
    return 1
  fi
  if [[ "${gateway_was_active}" == "true" \
    && "${defer_gateway_restart}" != "true" ]]; then
    systemctl restart openclaw-gateway >> "${LOG_FILE}" 2>&1 || return 1
    verify_openclaw_gateway_stable \
      "${PIN_OPENCLAW_RUNTIME_VERSION}" 18 || return 1
  fi
  rm -rf -- "${transaction_dir}" || return 1
  sync -f "$(dirname "${transaction_dir}")" 2>/dev/null || return 1
  OPENCLAW_ASK_USER_TRANSACTION_ARMED=false
  OPENCLAW_ASK_USER_TRANSACTION_COMMITTED=false
  OPENCLAW_ASK_USER_TRANSACTION_DIR=""
  OPENCLAW_ASK_USER_STATE_DIR=""
  OPENCLAW_ASK_USER_GATEWAY_WAS_ACTIVE=false
  OPENCLAW_ASK_USER_BASE_ATTESTED=false
  OPENCLAW_ASK_USER_LIVE_ATTESTED=false
}

commit_bridgesllm_ask_user_transaction() {
  local transaction_dir="${OPENCLAW_ASK_USER_TRANSACTION_DIR:-}"
  local state_root="${OPENCLAW_ASK_USER_STATE_DIR:-}"
  [[ -n "${transaction_dir}" && -n "${state_root}" ]] || return 1
  $OPENCLAW_ASK_USER_TRANSACTION_COMMITTED || return 1
  openclaw_tested_pair_commit_record_matches_ask_user_transaction \
    "${transaction_dir}" \
    "${state_root}/extensions/bridgesllm-ask-user" \
    "${state_root}/openclaw.json" || return 1
  local legacy_dir="${state_root}/plugins/bridgesllm-ask-user"
  if [[ -d "${state_root}/plugins" && ! -L "${state_root}/plugins" \
    && -d "${legacy_dir}" && ! -L "${legacy_dir}" \
    && -f "${legacy_dir}/index.js" && ! -L "${legacy_dir}/index.js" ]] \
    && ! mountpoint -q -- "${legacy_dir}"; then
    rm -rf -- "${legacy_dir}" || return 1
  fi
  rm -rf -- "${transaction_dir}" || return 1
  sync -f "${state_root}" 2>/dev/null || return 1
  OPENCLAW_ASK_USER_TRANSACTION_ARMED=false
  OPENCLAW_ASK_USER_TRANSACTION_DIR=""
  OPENCLAW_ASK_USER_STATE_DIR=""
  return 0
}

recover_or_retire_bridgesllm_ask_user_transaction() {
  local openclaw_state_dir="$1"
  local transaction_dir="${openclaw_state_dir}/.bridgesllm-ask-user-tested-pair-v1"
  [[ -e "${transaction_dir}" || -L "${transaction_dir}" ]] || return 0
  if [[ ! -d "${transaction_dir}" || -L "${transaction_dir}" \
    || "$(stat -c '%u:%g' -- "${transaction_dir}" 2>/dev/null || true)" != "0:0" ]]; then
    return 1
  fi
  if [[ ! -e "${transaction_dir}/manifest.json" ]]; then
    rm -rf -- "${transaction_dir}" || return 1
    sync -f "${openclaw_state_dir}" 2>/dev/null || return 1
    return 0
  fi
  OPENCLAW_ASK_USER_TRANSACTION_ARMED=true
  OPENCLAW_ASK_USER_TRANSACTION_COMMITTED=false
  OPENCLAW_ASK_USER_TRANSACTION_DIR="${transaction_dir}"
  OPENCLAW_ASK_USER_STATE_DIR="${openclaw_state_dir}"
  if openclaw_tested_pair_commit_record_matches_ask_user_transaction \
      "${transaction_dir}" \
      "${openclaw_state_dir}/extensions/bridgesllm-ask-user" \
      "${openclaw_state_dir}/openclaw.json"; then
    OPENCLAW_ASK_USER_TRANSACTION_COMMITTED=true
    commit_bridgesllm_ask_user_transaction
  else
    rollback_bridgesllm_ask_user_transaction
  fi
}

install_bridgesllm_ask_user_plugin() {
  # The ask-user bridge is a required part of the Portal/OpenClaw runtime. It
  # provides non-Codex providers with a real ask-user tool and registers
  # gateway methods that settle either that tool or native Codex input only on
  # the exact attested run. Treat its directory and the shared OpenClaw config
  # as one local transaction: either the new plugin is loaded and callable, or
  # both are restored before this function fails.
  if $SKIP_OPENCLAW; then
    return 0
  fi
  if ! command -v openclaw &>/dev/null; then
    warn "OpenClaw CLI is missing; the required ask-question plugin cannot be installed."
    return 1
  fi
  local source_dir="${1:-${PORTAL_DIR}/installer/openclaw-ask-user-plugin}"
  local openclaw_state_dir="${2:-/root/.openclaw}"
  # OpenClaw scans `<config dir>/extensions`, NOT `<config dir>/plugins`. The
  # `plugins` directory holds the install registry, not loadable plugin trees,
  # so a plugin dropped there is never discovered and the hook never runs.
  local extensions_dir="${openclaw_state_dir}/extensions"
  local target_dir="${extensions_dir}/bridgesllm-ask-user"
  local legacy_dir="${openclaw_state_dir}/plugins/bridgesllm-ask-user"
  local config_path="${openclaw_state_dir}/openclaw.json"
  local required_file
  for required_file in index.js package.json openclaw.plugin.json register.py; do
    if [[ ! -f "${source_dir}/${required_file}" \
      || -L "${source_dir}/${required_file}" ]]; then
      warn "Ask-question plugin source is missing or unsafe: ${required_file}."
      return 1
    fi
  done

  if [[ ! -d "${openclaw_state_dir}" || -L "${openclaw_state_dir}" ]]; then
    warn "OpenClaw state root is missing or unsafe; refusing plugin mutation."
    return 1
  fi
  if ! recover_or_retire_bridgesllm_ask_user_transaction \
      "${openclaw_state_dir}"; then
    warn "An interrupted ask-question transaction could not be reconciled safely."
    return 1
  fi
  if [[ -e "${extensions_dir}" || -L "${extensions_dir}" ]] \
    && { [[ ! -d "${extensions_dir}" ]] || [[ -L "${extensions_dir}" ]]; }; then
    warn "OpenClaw extensions root is not a real directory; refusing plugin mutation."
    return 1
  fi

  if [[ -e "${config_path}" || -L "${config_path}" ]]; then
    if [[ ! -f "${config_path}" || -L "${config_path}" \
      || "$(stat -c '%u:%g:%h' -- "${config_path}" 2>/dev/null || true)" != "0:0:1" ]]; then
      warn "OpenClaw config is not a single root-owned regular file; refusing plugin mutation."
      return 1
    fi
    local config_mode=""
    config_mode="$(stat -c '%a' -- "${config_path}" 2>/dev/null || true)"
    if [[ ! "${config_mode}" =~ ^[0-7]{3,4}$ ]] \
      || (( (8#${config_mode}) & 8#022 )); then
      warn "OpenClaw config permissions are unsafe; refusing plugin mutation."
      return 1
    fi
  fi
  if [[ -e "${target_dir}" || -L "${target_dir}" ]] \
    && { [[ ! -d "${target_dir}" ]] || [[ -L "${target_dir}" ]]; }; then
    warn "Existing ask-question plugin path is not a real directory; refusing replacement."
    return 1
  fi

  # Create the shared extensions directory without retightening it if OpenClaw
  # already made it; only our own subtree is forced to 700.
  if ! mkdir -p "${extensions_dir}"; then
    return 1
  fi
  local transaction_dir="${openclaw_state_dir}/.bridgesllm-ask-user-tested-pair-v1"
  if [[ -e "${transaction_dir}" || -L "${transaction_dir}" ]] \
    || ! install -d -m 700 "${transaction_dir}"; then
    return 1
  fi
  local stage_dir="${transaction_dir}/candidate"
  local previous_dir="${transaction_dir}/previous-plugin"
  local previous_config="${transaction_dir}/previous-openclaw.json"
  local inspect_output="${transaction_dir}/inspect.json"
  local rpc_output="${transaction_dir}/rpc.json"
  local target_preexisted=false
  local config_preexisted=false
  local config_registration_attempted=false
  local target_displaced=false
  local plugin_installed=false
  local gateway_was_active=false
  local install_succeeded=false
  local failure_reason=""

  systemctl is-active --quiet openclaw-gateway && gateway_was_active=true
  if [[ -e "${target_dir}" || -L "${target_dir}" ]]; then
    target_preexisted=true
  fi
  if [[ -e "${config_path}" || -L "${config_path}" ]]; then
    config_preexisted=true
  fi

  if ! install -d -m 700 "${stage_dir}"; then
    failure_reason="could not create the staged plugin directory"
  else
    for required_file in index.js package.json openclaw.plugin.json; do
      if ! install -m 600 "${source_dir}/${required_file}" \
          "${stage_dir}/${required_file}"; then
        failure_reason="could not stage ${required_file}"
        break
      fi
    done
    if [[ -z "${failure_reason}" ]]; then
      sync -f "${stage_dir}" 2>/dev/null \
        || failure_reason="could not durably stage the plugin directory"
    fi
  fi
  if [[ -z "${failure_reason}" ]] && $config_preexisted \
    && ! cp -a -- "${config_path}" "${previous_config}"; then
    failure_reason="could not preserve the OpenClaw config"
  fi
  if [[ -z "${failure_reason}" ]] && $config_preexisted \
    && ! sync -f "${previous_config}" 2>/dev/null; then
    failure_reason="could not durably preserve the OpenClaw config"
  fi
  if [[ -z "${failure_reason}" ]]; then
    if ! write_bridgesllm_ask_user_transaction_manifest \
        "${transaction_dir}" \
        "${openclaw_state_dir}" \
        "${target_dir}" \
        "${config_path}" \
        "${target_preexisted}" \
        "${config_preexisted}" \
        "${gateway_was_active}"; then
      failure_reason="could not arm the durable ask-user rollback transaction"
    else
      OPENCLAW_ASK_USER_TRANSACTION_ARMED=true
      OPENCLAW_ASK_USER_TRANSACTION_COMMITTED=false
      OPENCLAW_ASK_USER_TRANSACTION_DIR="${transaction_dir}"
      OPENCLAW_ASK_USER_STATE_DIR="${openclaw_state_dir}"
      OPENCLAW_ASK_USER_GATEWAY_WAS_ACTIVE="${gateway_was_active}"
      OPENCLAW_ASK_USER_BASE_ATTESTED=false
      OPENCLAW_ASK_USER_LIVE_ATTESTED=false
    fi
  fi
  if [[ -z "${failure_reason}" ]] && $target_preexisted; then
    if mv -T -- "${target_dir}" "${previous_dir}"; then
      target_displaced=true
    else
      failure_reason="could not preserve the previous plugin directory"
    fi
  fi
  if [[ -z "${failure_reason}" ]]; then
    if mv -T -- "${stage_dir}" "${target_dir}"; then
      plugin_installed=true
      sync -f "${extensions_dir}" 2>/dev/null \
        || failure_reason="could not durably publish the staged plugin directory"
    else
      failure_reason="could not publish the staged plugin directory"
    fi
  fi
  if [[ -z "${failure_reason}" ]]; then
    config_registration_attempted=true
    if ! python3 "${source_dir}/register.py" >> "${LOG_FILE}" 2>&1; then
      failure_reason="could not register the plugin in OpenClaw config"
    fi
  fi
  if [[ -z "${failure_reason}" ]] \
    && ! verify_bridgesllm_ask_user_plugin_config "${config_path}"; then
    failure_reason="OpenClaw config did not retain the enabled plugin registration"
  fi
  if [[ -z "${failure_reason}" ]] \
    && ! verify_bridgesllm_ask_user_plugin_runtime \
      "${target_dir}" "${inspect_output}"; then
    failure_reason="OpenClaw could not load the plugin or register its ask-user capabilities"
  fi
  if [[ -z "${failure_reason}" ]] && $gateway_was_active; then
    if ! systemctl restart openclaw-gateway >> "${LOG_FILE}" 2>&1; then
      failure_reason="the active OpenClaw gateway could not restart with the plugin"
    elif ! verify_openclaw_gateway_stable \
      "${PIN_OPENCLAW_RUNTIME_VERSION}" 18; then
      failure_reason="the OpenClaw gateway was not stable after plugin activation"
    elif ! verify_bridgesllm_ask_user_gateway_method \
      "${rpc_output}" bootstrap; then
      failure_reason="the running OpenClaw gateway failed ask-user execute and settlement semantics"
    fi
  fi
  [[ -z "${failure_reason}" ]] && install_succeeded=true

  if ! $install_succeeded; then
    local rollback_ok=true
    if $OPENCLAW_ASK_USER_TRANSACTION_ARMED; then
      rollback_bridgesllm_ask_user_transaction || rollback_ok=false
    else
      rm -rf -- "${transaction_dir}" || rollback_ok=false
    fi
    if ! $rollback_ok; then
      warn "Ask-question plugin rollback needs manual recovery from ${transaction_dir}."
    fi
    warn "Ask-question plugin activation failed: ${failure_reason}."
    return 1
  fi

  $gateway_was_active && OPENCLAW_ASK_USER_BASE_ATTESTED=true
  ok "Ask-question answer channel installed and verified; tested-pair rollback remains armed"
}

ensure_openclaw_codex_plugin_compatible() {
  if $SKIP_OPENCLAW || ! command -v openclaw &>/dev/null; then
    return 0
  fi

  if verify_openclaw_codex_plugin_pin "${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}"; then
    ok "OpenClaw Codex plugin ${PIN_OPENCLAW_CODEX_PLUGIN_VERSION} checked (exact pinned npm record)"
    return 0
  fi

  if ! capture_openclaw_codex_plugin_baseline; then
    warn "Could not prove and preserve the existing OpenClaw Codex plugin baseline."
    return 1
  fi
  OPENCLAW_CODEX_PLUGIN_UPDATE_ATTEMPTED=true

  local helper="${PORTAL_DIR}/backend/dist/services/openclawConfigManager.js"
  if [[ -f "${helper}" ]] && command -v node &>/dev/null; then
    info "Repairing stale OpenClaw Codex plugin state..."
    if ! OPENCLAW_ALLOW_ROOT=1 \
      PORTAL_OPENCLAW_CODEX_PLUGIN_VERSION="${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}" \
      NODE_PATH="${PORTAL_DIR}/backend/node_modules" \
      node -e 'const helper = process.argv[1]; const expected = process.argv[2]; const mod = require(helper); const result = mod.repairOpenClawCodexPluginInstallState(expected); console.log(JSON.stringify(result));' \
        "${helper}" "${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}" >> "$LOG_FILE" 2>&1; then
      warn "OpenClaw Codex plugin state repair failed. Continuing with compatibility check."
    else
      ok "OpenClaw Codex plugin state repaired"
    fi
  fi

  info "Installing tested OpenClaw Codex plugin ${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}..."
  if ! OPENCLAW_ALLOW_ROOT=1 openclaw plugins install \
    "@openclaw/codex@${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}" --force --pin >> "$LOG_FILE" 2>&1; then
    warn "OpenClaw Codex plugin install failed; the atomic core/plugin rollback remains armed."
    return 1
  fi
  ok "OpenClaw Codex plugin package installed"

  if ! verify_openclaw_codex_plugin_pin "${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}"; then
    warn "OpenClaw Codex plugin did not produce the exact pinned npm install record and package revision; the atomic rollback remains armed."
    return 1
  fi

  if systemctl is-enabled openclaw-gateway >/dev/null 2>&1; then
    if ! systemctl restart openclaw-gateway >> "$LOG_FILE" 2>&1 \
      || ! verify_openclaw_gateway_stable "${PIN_OPENCLAW_RUNTIME_VERSION}" 18; then
      warn "The gateway did not load the tested Codex plugin cleanly; the atomic core/plugin rollback remains armed."
      return 1
    fi
  fi

  # Keep the rollback armed until the exact core + authenticated gateway RPC +
  # plugin package/install-record pair is verified and committed together.
  ok "OpenClaw Codex plugin ${PIN_OPENCLAW_CODEX_PLUGIN_VERSION} loaded; pair commit pending"
}

apply_openclaw_codex_plugin_pending_input_hotfix() {
  if $SKIP_OPENCLAW || ! command -v openclaw &>/dev/null; then
    return 0
  fi

  local hotfix_script="${PORTAL_DIR}/scripts/patch-openclaw-codex-pending-input-hotfix.sh"
  local target backup
  if [[ ! -f "${hotfix_script}" || -L "${hotfix_script}" ]]; then
    warn "Bundled Codex provider pending-input hotfix is missing or unsafe."
    return 1
  fi
  target="$(resolve_openclaw_codex_plugin_pending_input_hotfix_target || true)"
  if [[ -z "${target}" ]]; then
    warn "Could not resolve exactly one run bundle in the pinned OpenClaw Codex provider."
    return 1
  fi
  backup="${target}.bridgesllm-pending-input-v1.bak"

  # A patcher-owned backup means an earlier process stopped between preserving
  # and committing bytes. Normalize back to the pristine package first; only
  # then capture the package-level rollback baseline used by this transaction.
  if [[ -e "${backup}" || -L "${backup}" ]]; then
    if ! normalize_openclaw_codex_plugin_pending_input_recovery_artifact \
      "${target}" "${hotfix_script}"; then
      warn "Codex provider pending-input recovery artifact is ambiguous or unsafe at ${backup}."
      return 1
    fi
  fi

  if verify_openclaw_codex_plugin_pending_input_hotfix; then
    ok "OpenClaw Codex provider pending-input bridge checked"
    return 0
  fi
  if ! capture_openclaw_codex_plugin_baseline; then
    warn "Could not preserve the Codex provider before pending-input preparation."
    return 1
  fi
  OPENCLAW_CODEX_PLUGIN_UPDATE_ATTEMPTED=true
  chmod 755 "${hotfix_script}" 2>/dev/null || true

  info "Applying Codex provider pending-input hotfix (if needed)..."
  if ! PORTAL_OPENCLAW_PENDING_INPUT_STRICT=1 \
    PORTAL_REQUIRED_OPENCLAW_PACKAGE_NAME='@openclaw/codex' \
    PORTAL_REQUIRED_OPENCLAW_PACKAGE_VERSION="${PIN_OPENCLAW_CODEX_PLUGIN_VERSION}" \
    bash "${hotfix_script}" "$(dirname "${target}")" \
      >> "${LOG_FILE}" 2>&1 \
    || ! openclaw_codex_plugin_pending_input_hotfix_is_applied "${target}"; then
    warn "Codex provider pending-input preparation failed; the package-level rollback remains armed."
    return 1
  fi
  if ! retire_openclaw_codex_plugin_pending_input_backup \
    "${target}" "${hotfix_script}"; then
    warn "Codex provider was patched, but its temporary byte backup could not be retired safely; the package-level rollback remains armed."
    return 1
  fi
  if ! verify_openclaw_codex_plugin_pending_input_hotfix; then
    warn "Codex provider pending-input preparation returned without its exact external-runtime Symbol contract."
    return 1
  fi

  # install_bridgesllm_ask_user_plugin performs the transaction's active-
  # gateway restart after publishing the matching multi-runtime bridge. Until
  # that restart and tested-pair verification succeed, plugin rollback stays
  # armed and restores the exact package tarball captured above.
  ok "OpenClaw Codex provider pending-input bridge prepared; gateway load pending"
}

commit_openclaw_tested_pair() {
  local openclaw_package_dir="" pending_target="" claude_target=""
  local ask_user_transaction="" ask_user_state_root=""
  local ask_user_target="" ask_user_config=""
  local sigint_trap="" sigterm_trap="" sighup_trap=""
  verify_openclaw_tested_pair || return 1
  openclaw_package_dir="$(openclaw_core_package_dir || true)"
  pending_target="${OPENCLAW_PENDING_INPUT_HOTFIX_TARGET:-}"
  claude_target="${OPENCLAW_CLAUDE_ASK_USER_HOTFIX_TARGET:-}"
  if [[ -z "${pending_target}" ]]; then
    pending_target="$(
      resolve_openclaw_pending_input_hotfix_target \
        "${openclaw_package_dir}/dist" || true
    )"
  fi
  if [[ -z "${claude_target}" ]]; then
    claude_target="$(
      resolve_openclaw_claude_ask_user_hotfix_target \
        "${openclaw_package_dir}/dist" || true
    )"
  fi
  [[ -n "${pending_target}" && -n "${claude_target}" ]] || return 1
  openclaw_pending_input_hotfix_is_applied "${pending_target}" || return 1
  openclaw_claude_ask_user_hotfix_is_applied "${claude_target}" || return 1
  $OPENCLAW_ASK_USER_TRANSACTION_ARMED || return 1
  $OPENCLAW_ASK_USER_LIVE_ATTESTED || return 1
  ask_user_transaction="${OPENCLAW_ASK_USER_TRANSACTION_DIR:-}"
  ask_user_state_root="${OPENCLAW_ASK_USER_STATE_DIR:-}"
  ask_user_target="${ask_user_state_root}/extensions/bridgesllm-ask-user"
  ask_user_config="${ask_user_state_root}/openclaw.json"
  [[ -n "${ask_user_transaction}" && -n "${ask_user_state_root}" ]] || return 1

  # One fsynced record is the commit decision for both byte-level mutations.
  # Block termination only across that short decision boundary. Once the
  # record and in-memory flag exist, cleanup can be retried without rolling one
  # half of the tested pair back independently.
  sigint_trap="$(trap -p SIGINT || true)"
  sigterm_trap="$(trap -p TERM || true)"
  sighup_trap="$(trap -p HUP || true)"
  trap '' SIGINT TERM HUP
  if ! write_openclaw_tested_pair_commit_record \
    "${pending_target}" \
    "${claude_target}" \
    "${ask_user_transaction}" \
    "${ask_user_target}" \
    "${ask_user_config}"; then
    [[ -n "${sigint_trap}" ]] && eval "${sigint_trap}" || trap - SIGINT
    [[ -n "${sigterm_trap}" ]] && eval "${sigterm_trap}" || trap - TERM
    [[ -n "${sighup_trap}" ]] && eval "${sighup_trap}" || trap - HUP
    return 1
  fi
  OPENCLAW_UPGRADE_COMMITTED=true
  OPENCLAW_CODEX_PLUGIN_UPDATE_ATTEMPTED=false
  OPENCLAW_ASK_USER_TRANSACTION_COMMITTED=true
  [[ -n "${sigint_trap}" ]] && eval "${sigint_trap}" || trap - SIGINT
  [[ -n "${sigterm_trap}" ]] && eval "${sigterm_trap}" || trap - TERM
  [[ -n "${sighup_trap}" ]] && eval "${sighup_trap}" || trap - HUP

  if ! commit_openclaw_pending_input_hotfix; then
    warn "The tested pair committed, but the native pending-input backup could not be retired; the durable commit record will reconcile it on the next run."
  fi
  if ! commit_openclaw_claude_ask_user_hotfix; then
    warn "The tested pair committed, but the Claude ask-user backup could not be retired; the durable commit record will reconcile it on the next run."
  fi
  if ! commit_bridgesllm_ask_user_transaction; then
    warn "The tested pair committed, but the ask-user plugin/config rollback directory could not be retired; the durable commit record will reconcile it on the next run."
  fi
  OPENCLAW_PENDING_INPUT_HOTFIX_COMMITTED=true
  OPENCLAW_CLAUDE_ASK_USER_HOTFIX_COMMITTED=true
  if ! retire_openclaw_tested_pair_commit_record_if_clean \
    "${pending_target}" \
    "${claude_target}" \
    "${ask_user_transaction}"; then
    warn "The tested pair committed, but its completed decision record could not be retired; backup-generation binding prevents stale replay."
  fi
  return 0
}

configure_openclaw_codex_harness_defaults() {
  if $SKIP_OPENCLAW || ! command -v openclaw &>/dev/null; then
    return 0
  fi

  local oc_config="${HOME}/.openclaw/openclaw.json"
  [[ -f "${oc_config}" ]] || return 0

  if python3 - "$oc_config" >> "$LOG_FILE" 2>&1 <<'PY'
import json
import sys
from pathlib import Path

path = Path(sys.argv[1])
try:
    data = json.loads(path.read_text())
except Exception:
    sys.exit(0)

plugins = data.setdefault("plugins", {})
changed = False
if plugins.get("enabled") is not True:
    plugins["enabled"] = True
    changed = True
entries = plugins.setdefault("entries", {})
codex = entries.setdefault("codex", {})
if codex.get("enabled") is not True:
    codex["enabled"] = True
    changed = True
config = codex.setdefault("config", {})
app_server = config.setdefault("appServer", {})

for key, value in {
    "turnCompletionIdleTimeoutMs": 180000,
    "postToolRawAssistantCompletionIdleTimeoutMs": 180000,
}.items():
    if app_server.get(key) != value:
        app_server[key] = value
        changed = True

if changed:
    path.write_text(json.dumps(data, indent=2) + "\n")
PY
  then
    ok "OpenClaw Codex harness defaults checked"
  else
    warn "Could not update OpenClaw Codex harness defaults"
  fi
}

prepare_openclaw_runtime_for_portal() {
  if $SKIP_OPENCLAW; then
    info "Skipping OpenClaw runtime compatibility checks (--skip-openclaw)"
    return 0
  fi
  if ! prepare_openclaw_upgrade_state; then
    fail "OpenClaw upgrade stopped before the first new gateway restart because legacy state could not be proven safe. No data was deleted and openclaw doctor --fix was not run."
  fi

  if ! verify_openclaw_core_package_pin; then
    fail "OpenClaw core is not the tested ${PIN_OPENCLAW_CORE_PACKAGE_VERSION} package / ${PIN_OPENCLAW_RUNTIME_VERSION} runtime pair. The updater will restore the preserved previous runtime when applicable."
  fi
  # Publish the replacement tool/config under the same durable rollback
  # decision as the core and native bundle patches. Native AskUserQuestion is
  # still available throughout this first boot and live base attestation.
  if ! install_bridgesllm_ask_user_plugin; then
    fail "OpenClaw is healthy, but the Portal ask-question answer channel could not be installed and verified. The previous plugin/config were restored when possible."
  fi
  if ! ensure_openclaw_gateway_boots_cleanly; then
    fail "OpenClaw gateway did not boot cleanly with the replacement ask-user bridge. Check: journalctl -u openclaw-gateway -n 100 --no-pager"
  fi
  if ! ensure_openclaw_gateway_matches_cli; then
    fail "OpenClaw gateway version/RPC readiness could not be verified. The updater will restore the previous OpenClaw runtime when applicable. Check: systemctl status openclaw-gateway"
  fi
  if ! verify_bridgesllm_ask_user_tested_pair /root/.openclaw bootstrap; then
    fail "The replacement ask-user tool or one of its live settlement methods failed base semantic attestation before native Claude question routing could be changed."
  fi
  OPENCLAW_ASK_USER_BASE_ATTESTED=true
  auto_apply_openclaw_compatibility_hotfix
  if ! ensure_openclaw_gateway_boots_cleanly \
    || ! ensure_openclaw_gateway_matches_cli \
    || ! verify_bridgesllm_ask_user_tested_pair; then
    fail "OpenClaw did not retain the complete ask-user bridge after compatibility activation. The tested-pair rollback remains armed."
  fi
  OPENCLAW_ASK_USER_LIVE_ATTESTED=true
  if $OPENCLAW_PACKAGE_UPDATED || [[ -n "${OPENCLAW_UPGRADE_STATE_MANIFEST:-}" ]]; then
    local expected_gateway_version
    expected_gateway_version="$(openclaw_cli_version)"
    $OPENCLAW_PACKAGE_UPDATED && expected_gateway_version="${PIN_OPENCLAW_RUNTIME_VERSION}"
    if ! verify_openclaw_gateway_stable "${expected_gateway_version}" 18; then
      fail "OpenClaw gateway did not remain ready and restart-free through the post-upgrade stability window. The updater will restore the previous runtime."
    fi
  fi
  ensure_openclaw_sandbox_image
  run_openclaw_state_repair_notice
  repair_openclaw_portal_model_config
  bridge_openclaw_codex_cli_auth
  # Runtime attestation below intentionally rejects a disabled or inert Codex
  # provider. Converge the required harness state before inspecting it.
  configure_openclaw_codex_harness_defaults
  if ! ensure_openclaw_codex_plugin_compatible; then
    fail "OpenClaw core is healthy, but the tested Codex plugin ${PIN_OPENCLAW_CODEX_PLUGIN_VERSION} could not be installed and loaded. The previous plugin was restored when possible."
  fi
  if ! apply_openclaw_codex_plugin_pending_input_hotfix; then
    fail "OpenClaw Codex is installed, but its active provider bundle could not be prepared for exact ask-question delivery. The previous plugin was restored when possible."
  fi
  if ! commit_openclaw_tested_pair; then
    fail "OpenClaw compatibility verification did not produce the tested core ${PIN_OPENCLAW_CORE_PACKAGE_VERSION} / Codex plugin ${PIN_OPENCLAW_CODEX_PLUGIN_VERSION} / Portal answer-channel runtime."
  fi
  # Only this boundary, after the required Portal bridge is live, disarms the
  # core/plugin/hotfix rollback paths and retires the owned byte backup.
}

configure_backup_timers() {
  step_header "Configuring backup automation"
  CURRENT_STEP="backup automation"

  $DRY_RUN && { ok "[dry-run] Would configure backup timers"; return; }

  local backup_script="${PORTAL_DIR}/backup-full.sh"
  if [[ ! -f "${backup_script}" ]]; then
    warn "Backup script missing at ${backup_script}; timers not enabled"
    return 0
  fi

  chmod 750 "${backup_script}" 2>/dev/null || true
  local backup_state_dir="${PORTAL_DIR}/backend/.data/backups"
  local backup_config_file="${backup_state_dir}/backup-base-path"
  mkdir -p "${backup_state_dir}"
  # `.data` holds credential-lifecycle state as well as backup state, and
  # `mkdir -p` creates parents under the installer umask. Left at 0755 it fails
  # the credential ledger's own permission contract, which is how provider
  # OAuth setup came to fail on every install. Narrow the parent explicitly.
  chmod 700 "${PORTAL_DIR}/backend/.data"
  chmod 700 "${backup_state_dir}"
  if [[ ! -s "${backup_config_file}" ]]; then
    local configured_backup_base=""
    local portal_database_url=""
    portal_database_url="$(read_env_value "${PORTAL_DIR}/backend/.env.production" DATABASE_URL 2>/dev/null || true)"
    if [[ -n "${portal_database_url}" ]] && command -v node >/dev/null 2>&1 \
      && [[ -d "${PORTAL_DIR}/backend/node_modules/@prisma/client" ]]; then
      configured_backup_base="$(
        cd "${PORTAL_DIR}/backend" && \
        DATABASE_URL="${portal_database_url}" node -e '
          const { prisma } = require("./dist/config/database");
          prisma.systemSetting.findUnique({ where: { key: "system.backupPath" } })
            .then((row) => { if (row?.value) process.stdout.write(row.value); })
            .finally(() => prisma.$disconnect());
        ' 2>/dev/null || true
      )"
    fi
    printf '%s\n' "${configured_backup_base:-/root/backups}" > "${backup_config_file}"
  fi
  chmod 600 "${backup_config_file}"
  BACKUP_CONFIG_FILE="${backup_config_file}" BACKUP_STATE_DIR="${backup_state_dir}" \
    /bin/bash "${backup_script}" --list >> "$LOG_FILE" 2>&1 \
    || fail "Configured backup storage path is invalid or insecure."

  cat > /etc/systemd/system/bridgesllm-backup@.service << BACKUPSERVICE
[Unit]
Description=BridgesLLM Portal %i backup
After=docker.service bridgesllm-product.service
Wants=docker.service

[Service]
Type=oneshot
User=root
Environment=PORTAL_ROOT=${PORTAL_DIR}
Environment=INSTALL_ROOT=${INSTALL_ROOT}
Environment=BACKUP_CONFIG_FILE=${backup_config_file}
Environment=BACKUP_STATE_DIR=${backup_state_dir}
ExecStart=/bin/bash ${backup_script} %i
ExecStopPost=/bin/bash ${backup_script} --recover-quiescence
Nice=10
IOSchedulingClass=best-effort
IOSchedulingPriority=7
UMask=0077
TimeoutStartSec=6h
TimeoutStopSec=10m
StandardOutput=journal
StandardError=journal
BACKUPSERVICE

  cat > /etc/systemd/system/bridgesllm-backup-daily.timer << 'BACKUPDAILY'
[Unit]
Description=Daily BridgesLLM Portal backup

[Timer]
OnCalendar=*-*-* 02:00:00
Persistent=true
Unit=bridgesllm-backup@daily.service

[Install]
WantedBy=timers.target
BACKUPDAILY

  cat > /etc/systemd/system/bridgesllm-backup-comprehensive.timer << 'BACKUPWEEKLY'
[Unit]
Description=Weekly comprehensive BridgesLLM Portal backup

[Timer]
OnCalendar=Sun *-*-* 03:00:00
Persistent=true
Unit=bridgesllm-backup@comprehensive.service

[Install]
WantedBy=timers.target
BACKUPWEEKLY

  cat > /etc/systemd/system/bridgesllm-backup-monthly.timer << 'BACKUPMONTHLY'
[Unit]
Description=Monthly BridgesLLM Portal backup

[Timer]
OnCalendar=*-*-01 04:00:00
Persistent=true
Unit=bridgesllm-backup@monthly.service

[Install]
WantedBy=timers.target
BACKUPMONTHLY

  systemctl daemon-reload
  systemctl enable --now bridgesllm-backup-daily.timer bridgesllm-backup-comprehensive.timer bridgesllm-backup-monthly.timer >> "$LOG_FILE" 2>&1 \
    || fail "Backup timers could not be enabled."

  local cron_tmp
  cron_tmp="$(mktemp)"
  if crontab -l > "${cron_tmp}" 2>/dev/null; then
    if grep -q 'backup-full\.sh' "${cron_tmp}"; then
      grep -v 'backup-full\.sh' "${cron_tmp}" | crontab -
      ok "Removed stale backup cron entries"
    fi
  fi
  rm -f "${cron_tmp}"

  ok "Backup timers configured"
}

ensure_agent_zero_project_model_bridge() {
  local lifecycle="${PORTAL_DIR}/installer/agent-zero-project-model-bridge.sh"
  local lifecycle_command="install"
  [[ -f "$lifecycle" && ! -L "$lifecycle" ]] \
    || fail "Agent Zero Project model bridge lifecycle is missing from the verified release."
  [[ "$(stat -c '%u' "$lifecycle")" == "0" ]] \
    || fail "Agent Zero Project model bridge lifecycle is not root-owned."
  (( (8#$(stat -c '%a' "$lifecycle") & 0022) == 0 )) \
    || fail "Agent Zero Project model bridge lifecycle is writable by an unsafe principal."
  if command -v docker >/dev/null 2>&1 \
    && docker container inspect bridgesllm-agent-zero >/dev/null 2>&1 \
    && [[ "$(docker inspect --format '{{.State.Running}}' bridgesllm-agent-zero 2>/dev/null || true)" == "true" ]]; then
    lifecycle_command="reconcile"
    info "Reconciling Agent Zero Project model bridge with the managed OAuth upstream..."
  else
    info "Installing fail-closed Agent Zero Project model bridge..."
  fi
  bash "$lifecycle" "$lifecycle_command" >> "$LOG_FILE" 2>&1 \
    || fail "Agent Zero Project model bridge could not be installed and verified."
  if [[ "$lifecycle_command" == "reconcile" ]]; then
    ok "Agent Zero Project model bridge is active and upstream-authenticated"
  else
    ok "Agent Zero Project model bridge is active in fail-closed mode (Agent Zero not running)"
  fi
}

start_portal() {
  step_header "Starting portal"
  CURRENT_STEP="startup"

  local env_file="${PORTAL_DIR}/backend/.env.production"
  ensure_project_egress_token_secret "${env_file}"
  ensure_docker_address_pools
  provision_project_runtimes "${env_file}"

  # Start OpenClaw gateway first (portal connects to it)
  if systemctl is-enabled openclaw-gateway &>/dev/null 2>&1; then
    prepare_openclaw_runtime_for_portal
    sleep 3  # Let gateway fully initialize and write its config

    # CRITICAL: Sync the gateway token into .env.production
    # OpenClaw may regenerate its token on first start. Read the ACTUAL token
    # from openclaw.json and ensure .env.production matches.
    local oc_config_path="${HOME}/.openclaw/openclaw.json"
    if [[ -f "${oc_config_path}" ]]; then
      local live_token
      live_token="$(python3 -c "
import json
try:
    d = json.load(open('${oc_config_path}'))
    print(d.get('gateway',{}).get('auth',{}).get('token',''))
except: pass
" 2>/dev/null || true)"
      if [[ -n "${live_token}" ]] && [[ -f "${env_file}" ]]; then
        local env_token
        env_token="$(read_env_value "${env_file}" "OPENCLAW_GATEWAY_TOKEN" || true)"
        if [[ "${live_token}" != "${env_token}" ]]; then
          info "Syncing gateway token (openclaw.json → .env.production)"
          sed -i "s/^OPENCLAW_GATEWAY_TOKEN=.*/OPENCLAW_GATEWAY_TOKEN=${live_token}/" "${env_file}"
        fi
      fi
    fi
  fi

  systemctl start bridgesllm-product
  ensure_agent_zero_project_model_bridge
  if ${RETAINED_RECONNECT_MODE}; then
    # Runtime intent is applied only after signed files, dependencies,
    # configuration, migrations, service units, and Project runtime policy
    # have converged. Starting retained containers from build_portal() was too
    # early: they could race unfinished migrations and stale bridge policy.
    restore_retained_runtime_intent
    # A resumed Agent Zero container changes the bridge from fail-closed to an
    # authenticated upstream. Reconcile once more after applying the intent.
    ensure_agent_zero_project_model_bridge
  fi

  # Auto-approve portal's device pairing with gateway (loopback should auto-approve
  # but some OpenClaw versions require explicit approval for operator-scoped devices)
  if command -v openclaw &>/dev/null; then
    sleep 3  # Wait for portal to attempt first connect
    openclaw devices approve --latest >> "$LOG_FILE" 2>&1 || true
  fi

  if ! verify_portal_service_health "bridgesllm-product" "http://127.0.0.1:4001/health" 60; then
    warn "Portal failed health verification — check: journalctl -u bridgesllm-product -n 50"
  fi
  if ! verify_portal_update_readiness "${VERSION}" "${PORTAL_UPDATE_PROBE_TOKEN}" 900; then
    fail "Portal failed exact-version authenticated readiness verification."
  fi
  if ! verify_app_content_caddy_ready; then
    fail "Isolated app-content TLS host did not become ready. Verify APP_CONTENT_DOMAIN DNS and Caddy ACME logs."
  fi
  if use_tailnet_profile && ! verify_tailnet_tls_ready; then
    fail "The tailnet origin https://${TAILNET_DNS_NAME}/ did not answer over HTTPS, so the installer will not print a credential-bearing setup link. Check 'tailscale serve status' and rerun this installer."
  fi
  if [[ -n "${DOMAIN}" ]] && ! use_local_profile && ! verify_portal_tls_ready; then
    fail "Portal TLS is not ready, so the installer will not print or enable a credential-bearing setup link. Verify DOMAIN DNS and Caddy ACME logs, then rerun the installer with --reinstall."
  fi
  if ! commit_portal_deploy_provenance; then
    fail "Portal is healthy, but verified release provenance could not be committed atomically."
  fi
  ok "Portal release provenance committed"
}

