# Update & Uninstall
# ═══════════════════════════════════════════════════════════════

attest_existing_portal_for_update() {
  local portal_root="${1:-${PORTAL_DIR}}"
  python3 - "${portal_root}" <<'PY2'
import json
import os
import re
import stat
import sys

root = os.path.abspath(sys.argv[1])
if root != os.path.normpath(sys.argv[1]):
    raise SystemExit(1)

def safe_directory(path: str) -> None:
    info = os.lstat(path)
    if (not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode)
            or info.st_uid != 0 or info.st_mode & 0o022):
        raise SystemExit(1)

def safe_file(relative: str, maximum: int) -> str:
    path = os.path.join(root, relative)
    info = os.lstat(path)
    if (not stat.S_ISREG(info.st_mode) or stat.S_ISLNK(info.st_mode)
            or info.st_uid != 0 or info.st_nlink != 1
            or info.st_mode & 0o022 or not 0 < info.st_size <= maximum):
        raise SystemExit(1)
    raw = open(path, "rb").read()
    if b"\x00" in raw:
        raise SystemExit(1)
    return raw.decode("utf-8")

safe_directory(root)
for relative in ("backend", "backend/dist", "frontend", "installer"):
    safe_directory(os.path.join(root, relative))

backend_package = json.loads(safe_file("backend/package.json", 1024 * 1024))
frontend_package = json.loads(safe_file("frontend/package.json", 1024 * 1024))
compiled = safe_file("backend/dist/version.js", 1024 * 1024)
safe_file("backend/dist/server.js", 64 * 1024 * 1024)
installed = safe_file("installer/install.sh", 2 * 1024 * 1024)
safe_file("backend/.env.production", 1024 * 1024)
safe_file("frontend/.env", 1024 * 1024)

compiled_match = re.search(r"PORTAL_VERSION\s*=\s*['\"]([^'\"]+)['\"]", compiled)
installer_match = re.search(r"readonly\s+VERSION\s*=\s*['\"]([^'\"]+)['\"]", installed)
versions = [
    backend_package.get("version"),
    frontend_package.get("version"),
    compiled_match.group(1) if compiled_match else None,
    installer_match.group(1) if installer_match else None,
]
if (not all(isinstance(value, str) for value in versions)
        or len(set(versions)) != 1
        or not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", versions[0])):
    raise SystemExit(1)
print(versions[0])
PY2
}

create_update_backup_dir() {
  local backup_root="${1:-${INSTALL_ROOT}/backups}"
  [[ "${backup_root}" == "${INSTALL_ROOT}/backups" ]] || return 1
  install -d -m 0700 -- "${backup_root}" || return 1
  [[ -d "${backup_root}" && ! -L "${backup_root}" \
    && "$(stat -c '%u:%g:%a' "${backup_root}")" == "0:0:700" ]] || return 1
  local backup_dir
  backup_dir="$(mktemp -d "${backup_root}/update-transaction.XXXXXX")" || return 1
  chmod 0700 "${backup_dir}" || return 1
  printf '%s\n' "${backup_dir}"
}

service_unit_cgroup_is_empty() {
  local service_name="${1:-bridgesllm-product}"
  local control_group="${2:-}"
  local cgroup_root="/sys/fs/cgroup"
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && -n "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT:-}" ]]; then
    cgroup_root="${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT}/sys/fs/cgroup"
  fi
  [[ -n "${control_group}" && "${control_group}" != "/" \
    && "${control_group}" == /* && "${control_group}" != *".."* ]] || return 1
  python3 - "${cgroup_root}" "${control_group}" "${service_name}" <<'PY2'
import os
import pathlib
import re
import sys

root = pathlib.Path(sys.argv[1]).resolve()
control_group = sys.argv[2]
service = sys.argv[3]
if not re.fullmatch(r"/[A-Za-z0-9_.@:/-]+", control_group):
    raise SystemExit(1)
if not control_group.rstrip("/").endswith(f"/{service}.service"):
    raise SystemExit(1)
candidate = (root / control_group.lstrip("/")).resolve()
if candidate != root and root not in candidate.parents:
    raise SystemExit(1)
if not candidate.is_dir():
    raise SystemExit(1)
for procs in candidate.rglob("cgroup.procs"):
    if any(line.strip() for line in procs.read_text(encoding="ascii").splitlines()):
        raise SystemExit(1)
PY2
}

portal_service_port_is_free() {
  local port="${1:-4001}"
  local proc_net_root="/proc/net"
  if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" == "1" \
    && -n "${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT:-}" ]]; then
    proc_net_root="${BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT}/proc/net"
  fi
  [[ "${port}" =~ ^[0-9]+$ && "${port}" -ge 1 && "${port}" -le 65535 ]] || return 1
  python3 - "${port}" "${proc_net_root}" <<'PY2'
import pathlib
import sys

port = int(sys.argv[1])
proc_net = pathlib.Path(sys.argv[2])
needle = f"{port:04X}"
for table in (proc_net / "tcp", proc_net / "tcp6"):
    try:
        rows = table.read_text(encoding="ascii").splitlines()[1:]
    except OSError:
        raise SystemExit(1)
    for row in rows:
        fields = row.split()
        if len(fields) < 4:
            raise SystemExit(1)
        local = fields[1]
        state = fields[3]
        try:
            local_port = local.rsplit(":", 1)[1].upper()
        except IndexError:
            raise SystemExit(1)
        if state == "0A" and local_port == needle:
            raise SystemExit(1)
PY2
}

current_boot_id() {
  local boot_id_path boot_id
  boot_id_path="$(
    update_transaction_state_path /proc/sys/kernel/random/boot_id
  )" || return 1
  boot_id="$(tr -d '[:space:]' < "${boot_id_path}" 2>/dev/null)" \
    || return 1
  [[ "${boot_id}" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$ ]] \
    || return 1
  printf '%s\n' "${boot_id}"
}

process_start_time_of_pid() {
  # Field 22 of /proc/<pid>/stat, parsed after the last ')' so a comm value
  # containing spaces or parentheses can never shift the field index.
  local pid="$1" stat_path stat_line rest start
  [[ "${pid}" =~ ^[1-9][0-9]*$ ]] || return 1
  stat_path="$(update_transaction_state_path "/proc/${pid}/stat")" || return 1
  stat_line="$(cat "${stat_path}" 2>/dev/null)" || return 1
  rest="${stat_line##*)}"
  local -a fields
  read -r -a fields <<<"${rest}"
  start="${fields[19]:-}"
  [[ "${start}" =~ ^[1-9][0-9]*$ ]] || return 1
  printf '%s\n' "${start}"
}

portal_service_is_quiesced() {
  local service_name="${1:-bridgesllm-product}"
  local state load_state active_state sub_state main_pid control_pid control_group
  state="$(systemctl show "${service_name}" \
    -p LoadState -p ActiveState -p SubState -p MainPID -p ControlPID -p ControlGroup 2>/dev/null)" \
    || return 1
  load_state="$(sed -n 's/^LoadState=//p' <<<"${state}")"
  active_state="$(sed -n 's/^ActiveState=//p' <<<"${state}")"
  sub_state="$(sed -n 's/^SubState=//p' <<<"${state}")"
  main_pid="$(sed -n 's/^MainPID=//p' <<<"${state}")"
  control_pid="$(sed -n 's/^ControlPID=//p' <<<"${state}")"
  control_group="$(sed -n 's/^ControlGroup=//p' <<<"${state}")"
  [[ "${load_state}" == "loaded" \
    && "${active_state}" =~ ^(inactive|failed)$ \
    && "${sub_state}" =~ ^(dead|failed)$ \
    && "${main_pid}" == "0" \
    && "${control_pid}" == "0" ]] || return 1
  if [[ -n "${control_group}" ]]; then
    service_unit_cgroup_is_empty "${service_name}" "${control_group}" || return 1
  fi
}

capture_portal_service_baseline() {
  local service_name="${1:-bridgesllm-product}"
  local state load_state active_state main_pid enabled_state
  state="$(systemctl show "${service_name}" -p LoadState -p ActiveState -p MainPID 2>/dev/null)" \
    || return 1
  load_state="$(sed -n 's/^LoadState=//p' <<<"${state}")"
  active_state="$(sed -n 's/^ActiveState=//p' <<<"${state}")"
  main_pid="$(sed -n 's/^MainPID=//p' <<<"${state}")"
  [[ "${load_state}" == "loaded" ]] || return 1
  # Process identity is (boot id, pid, start time): a numeric PID alone is
  # ambiguous across reboots and PID-space reuse, and the replacement proof
  # after cutover/rollback must never be satisfied or defeated by a recycled
  # number.
  UPDATE_TRANSACTION_BASELINE_BOOT_ID="$(current_boot_id)" || return 1
  case "${active_state}" in
    active)
      [[ "${main_pid}" =~ ^[1-9][0-9]*$ ]] || return 1
      UPDATE_TRANSACTION_PORTAL_WAS_ACTIVE=true
      UPDATE_TRANSACTION_BASELINE_PID="${main_pid}"
      UPDATE_TRANSACTION_BASELINE_START_TIME="$(
        process_start_time_of_pid "${main_pid}"
      )" || return 1
      ;;
    inactive|failed)
      [[ "${main_pid}" == "0" ]] || return 1
      UPDATE_TRANSACTION_PORTAL_WAS_ACTIVE=false
      UPDATE_TRANSACTION_BASELINE_PID="0"
      UPDATE_TRANSACTION_BASELINE_START_TIME="0"
      ;;
    *) return 1 ;;
  esac
  enabled_state="$(systemctl is-enabled "${service_name}" 2>/dev/null || true)"
  case "${enabled_state}" in
    enabled) UPDATE_TRANSACTION_PORTAL_WAS_ENABLED=true ;;
    disabled) UPDATE_TRANSACTION_PORTAL_WAS_ENABLED=false ;;
    *) return 1 ;;
  esac
}

quiesce_portal_service() {
  local service_name="${1:-bridgesllm-product}"
  local graceful_timeout="${2:-45}" kill_timeout="${3:-15}" port="${4:-4001}"
  local waited=0 stop_status=0
  [[ "${graceful_timeout}" =~ ^[0-9]+$ && "${kill_timeout}" =~ ^[0-9]+$ \
    && "${port}" =~ ^[0-9]+$ ]] || return 1

  if portal_service_is_quiesced "${service_name}" && portal_service_port_is_free "${port}"; then
    return 0
  fi
  systemctl stop --no-block "${service_name}" >> "${LOG_FILE}" 2>&1 || stop_status=$?
  while (( waited < graceful_timeout )); do
    if portal_service_is_quiesced "${service_name}" && portal_service_port_is_free "${port}"; then
      return 0
    fi
    sleep 1
    waited=$((waited + 1))
  done

  warn "Portal did not quiesce gracefully (systemctl stop exit ${stop_status}); escalating once to SIGKILL."
  systemctl kill --kill-who=all --signal=SIGKILL "${service_name}" >> "${LOG_FILE}" 2>&1 \
    || return 1
  waited=0
  while (( waited < kill_timeout )); do
    if portal_service_is_quiesced "${service_name}" && portal_service_port_is_free "${port}"; then
      return 0
    fi
    sleep 1
    waited=$((waited + 1))
  done
  return 1
}

reload_active_root_user_systemd_manager() {
  local output_path="${1:-${LOG_FILE}}"
  local load_state active_state
  load_state="$(
    systemctl show --property=LoadState --value user@0.service 2>/dev/null
  )" || return 1
  active_state="$(
    systemctl show --property=ActiveState --value user@0.service 2>/dev/null
  )" || return 1
  case "${load_state}:${active_state}" in
    loaded:active)
      [[ -d /run/user/0 && ! -L /run/user/0 \
        && -S /run/user/0/bus && ! -L /run/user/0/bus \
        && -S /run/user/0/systemd/private \
        && ! -L /run/user/0/systemd/private \
        && "$(stat -c '%u:%g' /run/user/0 /run/user/0/bus /run/user/0/systemd/private \
          | sort -u)" == '0:0' ]] \
        || return 1
      (
        export XDG_RUNTIME_DIR=/run/user/0
        export DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/0/bus
        systemctl --user daemon-reload >> "${output_path}" 2>&1
      ) || return 1
      ;;
    loaded:inactive|not-found:inactive)
      ;;
    *)
      return 1
      ;;
  esac
}

install_exact_openclaw_gateway_authorization_fence_dropin() {
  local canonical_dropin_dir="$1"
  local canonical_dropin_path="$2"
  local expected="$3"
  local dropin_dir dropin_path
  dropin_dir="$(
    update_transaction_state_path \
      "${canonical_dropin_dir}"
  )" || return 1
  dropin_path="$(
    update_transaction_state_path \
      "${canonical_dropin_path}"
  )" || return 1
  python3 - "${dropin_dir}" "${dropin_path}" "${expected}" <<'PY2' \
    || return 1
import ctypes
import errno
import os
import stat
import sys
import tempfile

directory, destination, expected_text = sys.argv[1:]
expected = expected_text.encode("utf-8")
if (
    os.geteuid() != 0
    or not os.path.isabs(directory)
    or os.path.normpath(directory) != directory
    or not os.path.isabs(destination)
    or os.path.normpath(destination) != destination
    or os.path.dirname(destination) != directory
    or os.path.basename(destination)
        != "20-bridgesllm-authorization-fence.conf"
):
    raise SystemExit(1)


def attest_directory(path, mode=None):
    details = os.lstat(path)
    if (
        not stat.S_ISDIR(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != 0
        or details.st_gid != 0
        or details.st_mode & 0o022
        or (mode is not None and stat.S_IMODE(details.st_mode) != mode)
    ):
        raise SystemExit(1)


parent = os.path.dirname(directory)
current = os.path.sep
attest_directory(current)
for component in parent.strip(os.path.sep).split(os.path.sep):
    if not component:
        continue
    current = os.path.join(current, component)
    try:
        attest_directory(current)
    except FileNotFoundError:
        current_parent = os.path.dirname(current)
        os.mkdir(current, 0o755)
        os.chown(current, 0, 0)
        os.chmod(current, 0o755)
        current_parent_fd = os.open(
            current_parent,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
        )
        try:
            os.fsync(current_parent_fd)
        finally:
            os.close(current_parent_fd)
        attest_directory(current, 0o755)

try:
    attest_directory(directory, 0o755)
except FileNotFoundError:
    os.mkdir(directory, 0o755)
    os.chown(directory, 0, 0)
    os.chmod(directory, 0o755)
    parent_fd = os.open(
        parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(parent_fd)
    finally:
        os.close(parent_fd)
    attest_directory(directory, 0o755)

directory_fd = os.open(
    directory,
    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
)
destination_name = os.path.basename(destination)


def attest_destination():
    details = os.stat(
        destination_name,
        dir_fd=directory_fd,
        follow_symlinks=False,
    )
    if (
        not stat.S_ISREG(details.st_mode)
        or details.st_uid != 0
        or details.st_gid != 0
        or stat.S_IMODE(details.st_mode) != 0o644
        or details.st_nlink != 1
        or details.st_size != len(expected)
    ):
        raise SystemExit(1)
    descriptor = os.open(
        destination_name,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0),
        dir_fd=directory_fd,
    )
    try:
        opened = os.fstat(descriptor)
        if (
            (opened.st_dev, opened.st_ino, opened.st_mode, opened.st_nlink)
            != (details.st_dev, details.st_ino, details.st_mode, details.st_nlink)
            or opened.st_uid != 0
            or opened.st_gid != 0
            or opened.st_size != len(expected)
        ):
            raise SystemExit(1)
        content = bytearray()
        while len(content) < len(expected) + 1:
            block = os.read(descriptor, len(expected) + 1 - len(content))
            if not block:
                break
            content.extend(block)
        if bytes(content) != expected:
            raise SystemExit(1)
    finally:
        os.close(descriptor)


temporary = ""
try:
    try:
        attest_destination()
    except FileNotFoundError:
        descriptor, temporary = tempfile.mkstemp(
            prefix=".20-bridgesllm-authorization-fence.",
            dir=directory,
        )
        try:
            os.fchown(descriptor, 0, 0)
            os.fchmod(descriptor, 0o644)
            view = memoryview(expected)
            while view:
                written = os.write(descriptor, view)
                view = view[written:]
            os.fsync(descriptor)
        finally:
            os.close(descriptor)

        libc = ctypes.CDLL(None, use_errno=True)
        renameat2 = getattr(libc, "renameat2", None)
        if renameat2 is None:
            raise SystemExit(1)
        renameat2.argtypes = [
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_int,
            ctypes.c_char_p,
            ctypes.c_uint,
        ]
        renameat2.restype = ctypes.c_int
        temporary_name = os.path.basename(temporary)
        result = renameat2(
            directory_fd,
            os.fsencode(temporary_name),
            directory_fd,
            os.fsencode(destination_name),
            1,  # RENAME_NOREPLACE
        )
        if result != 0:
            error = ctypes.get_errno()
            if error != errno.EEXIST:
                raise OSError(error, os.strerror(error))
            attest_destination()
        else:
            temporary = ""
            os.fsync(directory_fd)
        attest_destination()
finally:
    if temporary:
        try:
            os.unlink(temporary)
            os.fsync(directory_fd)
        except FileNotFoundError:
            pass
    os.close(directory_fd)
PY2
}

install_openclaw_gateway_authorization_fence_dropin() {
  local expected_system='[Unit]
ConditionPathExists=!/var/lib/bridgesllm/openclaw-gateway-authorization-fence.v1
[Service]
KillMode=control-group
'
  local expected_root_user='[Unit]
ConditionPathExists=!/var/lib/bridgesllm/openclaw-gateway-authorization-fence.v1
[Service]
KillMode=control-group
ExecCondition=/usr/bin/false
'
  install_exact_openclaw_gateway_authorization_fence_dropin \
    "${OPENCLAW_GATEWAY_AUTHORIZATION_FENCE_DROPIN_DIR}" \
    "${OPENCLAW_GATEWAY_AUTHORIZATION_FENCE_DROPIN}" \
    "${expected_system}" \
    || return 1
  install_exact_openclaw_gateway_authorization_fence_dropin \
    "${OPENCLAW_GATEWAY_ROOT_USER_AUTHORIZATION_FENCE_DROPIN_DIR}" \
    "${OPENCLAW_GATEWAY_ROOT_USER_AUTHORIZATION_FENCE_DROPIN}" \
    "${expected_root_user}" \
    || return 1
  systemctl daemon-reload >> "${LOG_FILE}" 2>&1 || return 1
  reload_active_root_user_systemd_manager || return 1
}

remove_openclaw_gateway_authorization_fence_for_clean_uninstall() {
  local marker_path dropin_dir dropin_path root_user_dropin_dir root_user_dropin_path
  marker_path="$(
    update_transaction_state_path \
      "${OPENCLAW_GATEWAY_AUTHORIZATION_FENCE_MARKER}"
  )" || return 1
  dropin_dir="$(
    update_transaction_state_path \
      "${OPENCLAW_GATEWAY_AUTHORIZATION_FENCE_DROPIN_DIR}"
  )" || return 1
  dropin_path="$(
    update_transaction_state_path \
      "${OPENCLAW_GATEWAY_AUTHORIZATION_FENCE_DROPIN}"
  )" || return 1
  root_user_dropin_dir="$(
    update_transaction_state_path \
      "${OPENCLAW_GATEWAY_ROOT_USER_AUTHORIZATION_FENCE_DROPIN_DIR}"
  )" || return 1
  root_user_dropin_path="$(
    update_transaction_state_path \
      "${OPENCLAW_GATEWAY_ROOT_USER_AUTHORIZATION_FENCE_DROPIN}"
  )" || return 1
  local expected_dropin='[Unit]
ConditionPathExists=!/var/lib/bridgesllm/openclaw-gateway-authorization-fence.v1
[Service]
KillMode=control-group
'
  local expected_root_user_dropin='[Unit]
ConditionPathExists=!/var/lib/bridgesllm/openclaw-gateway-authorization-fence.v1
[Service]
KillMode=control-group
ExecCondition=/usr/bin/false
'
  local expected_marker='{"schema":"bridgesllm.openclaw-gateway-authorization-fence.v1","unit":"openclaw-gateway.service"}
'
  python3 - \
    "${marker_path}" "${dropin_dir}" "${dropin_path}" \
    "${root_user_dropin_dir}" "${root_user_dropin_path}" \
    "${expected_marker}" "${expected_dropin}" \
    "${expected_root_user_dropin}" <<'PY2' \
    || return 1
import os
import stat
import sys

(
    marker,
    dropin_directory,
    dropin,
    root_user_dropin_directory,
    root_user_dropin,
    marker_text,
    dropin_text,
    root_user_dropin_text,
) = sys.argv[1:]
expected_marker = marker_text.encode("utf-8")
expected_dropin = dropin_text.encode("utf-8")
expected_root_user_dropin = root_user_dropin_text.encode("utf-8")
if (
    os.geteuid() != 0
    or not all(os.path.isabs(path) and os.path.normpath(path) == path
               for path in (
                   marker,
                   dropin_directory,
                   dropin,
                   root_user_dropin_directory,
                   root_user_dropin,
               ))
    or os.path.dirname(dropin) != dropin_directory
    or os.path.dirname(root_user_dropin) != root_user_dropin_directory
    or os.path.basename(marker)
        != "openclaw-gateway-authorization-fence.v1"
    or os.path.basename(dropin)
        != "20-bridgesllm-authorization-fence.conf"
    or os.path.basename(root_user_dropin)
        != "20-bridgesllm-authorization-fence.conf"
):
    raise SystemExit(1)


def open_attested_parent(path):
    parent = os.path.dirname(path)
    for candidate in (
        os.path.sep,
        *(os.path.join(
            os.path.sep,
            *parent.strip(os.path.sep).split(os.path.sep)[:index],
        ) for index in range(
            1,
            len(parent.strip(os.path.sep).split(os.path.sep)) + 1,
        )),
    ):
        try:
            details = os.lstat(candidate)
        except FileNotFoundError:
            return None
        if (
            not stat.S_ISDIR(details.st_mode)
            or stat.S_ISLNK(details.st_mode)
            or details.st_uid != 0
            or details.st_gid != 0
            or details.st_mode & 0o022
        ):
            raise SystemExit(1)
    return os.open(
        parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )


def handle_exact(path, expected, required_mode, remove):
    parent_fd = open_attested_parent(path)
    if parent_fd is None:
        return
    name = os.path.basename(path)
    try:
        try:
            details = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return
        if (
            not stat.S_ISREG(details.st_mode)
            or details.st_uid != 0
            or details.st_gid != 0
            or stat.S_IMODE(details.st_mode) != required_mode
            or details.st_nlink != 1
            or details.st_size != len(expected)
        ):
            raise SystemExit(1)
        descriptor = os.open(
            name,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=parent_fd,
        )
        try:
            opened = os.fstat(descriptor)
            if (
                (opened.st_dev, opened.st_ino, opened.st_mode, opened.st_nlink)
                != (details.st_dev, details.st_ino,
                    details.st_mode, details.st_nlink)
                or opened.st_uid != 0
                or opened.st_gid != 0
                or opened.st_size != len(expected)
            ):
                raise SystemExit(1)
            content = bytearray()
            while len(content) < len(expected) + 1:
                block = os.read(descriptor, len(expected) + 1 - len(content))
                if not block:
                    break
                content.extend(block)
            if bytes(content) != expected:
                raise SystemExit(1)
        finally:
            os.close(descriptor)
        if not remove:
            return
        rebound = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            rebound.st_dev,
            rebound.st_ino,
            rebound.st_mode,
            rebound.st_nlink,
        ) != (
            details.st_dev,
            details.st_ino,
            details.st_mode,
            details.st_nlink,
        ):
            raise SystemExit(1)
        os.unlink(name, dir_fd=parent_fd)
        os.fsync(parent_fd)
    finally:
        os.close(parent_fd)


# Prove the complete managed set before deleting any member, then unlink both
# drop-ins first. Until the marker is removed, both managers' currently loaded
# conditions remain start inhibitors even though the file entries are gone.
handle_exact(marker, expected_marker, 0o600, False)
handle_exact(dropin, expected_dropin, 0o644, False)
handle_exact(
    root_user_dropin,
    expected_root_user_dropin,
    0o644,
    False,
)
handle_exact(
    root_user_dropin,
    expected_root_user_dropin,
    0o644,
    True,
)
handle_exact(dropin, expected_dropin, 0o644, True)
handle_exact(marker, expected_marker, 0o600, True)
PY2
  # Clean-slate teardown has already removed INSTALL_ROOT (and its log
  # directory) before terminal authority is released.
  systemctl daemon-reload >/dev/null 2>&1 || return 1
  reload_active_root_user_systemd_manager /dev/null || return 1
}

install_portal_update_boot_fence() {
  local active_journal dropin_dir dropin_path
  active_journal="$(update_transaction_state_path "${UPDATE_ACTIVE_JOURNAL}")" \
    || return 1
  dropin_dir="$(
    update_transaction_state_path "${UPDATE_BOOT_FENCE_DROPIN_DIR}"
  )" || return 1
  dropin_path="$(
    update_transaction_state_path "${UPDATE_BOOT_FENCE_DROPIN}"
  )" || return 1
  local expected="[Unit]
ConditionPathExists=!${active_journal}
"
  python3 - "${dropin_dir}" "${dropin_path}" "${expected}" <<'PY2'
import os
import stat
import sys
import tempfile

directory, destination, expected = sys.argv[1:]
parent = os.path.dirname(directory)
for path in (parent,):
    info = os.lstat(path)
    if (not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode)
            or info.st_uid != 0 or info.st_mode & 0o022):
        raise SystemExit(1)
try:
    info = os.lstat(directory)
except FileNotFoundError:
    os.mkdir(directory, 0o755)
    info = os.lstat(directory)
if (not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0 or info.st_gid != 0 or info.st_mode & 0o022):
    raise SystemExit(1)
os.chmod(directory, 0o755)

try:
    current = os.lstat(destination)
except FileNotFoundError:
    current = None
if current is not None and (not stat.S_ISREG(current.st_mode)
        or stat.S_ISLNK(current.st_mode) or current.st_uid != 0
        or current.st_gid != 0 or current.st_nlink != 1
        or current.st_mode & 0o022 or current.st_size > 4096):
    raise SystemExit(1)
if current is not None:
    with open(destination, "r", encoding="utf-8") as handle:
        if handle.read() == expected:
            raise SystemExit(0)
    raise SystemExit(1)
fd, temporary = tempfile.mkstemp(prefix=".20-update-fence.", dir=directory)
try:
    os.fchmod(fd, 0o644)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(expected)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, destination)
    temporary = ""
    directory_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if temporary:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
PY2
  systemctl daemon-reload >> "${LOG_FILE}" 2>&1 || return 1
  [[ -f "${dropin_path}" && ! -L "${dropin_path}" ]] || return 1
  cmp -s "${dropin_path}" <(printf '%s' "${expected}") || return 1
}

fence_portal_service_boot() {
  install_portal_update_boot_fence
}

restore_portal_service_boot_state() {
  local service_name="${1:-bridgesllm-product}"
  if ${UPDATE_TRANSACTION_PORTAL_WAS_ENABLED:-false}; then
    systemctl enable "${service_name}" >> "${LOG_FILE}" 2>&1 || return 1
    [[ "$(systemctl is-enabled "${service_name}" 2>/dev/null || true)" == "enabled" ]]
  else
    systemctl disable "${service_name}" >> "${LOG_FILE}" 2>&1 || return 1
    [[ "$(systemctl is-enabled "${service_name}" 2>/dev/null || true)" == "disabled" ]]
  fi
}

update_candidate_unit_name() {
  local transaction_id="${1:-${UPDATE_TRANSACTION_ID}}"
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ ]] || return 1
  printf 'bridgesllm-update-candidate-%s\n' "${transaction_id}"
}

start_update_candidate() {
  local transaction_id="${1:-${UPDATE_TRANSACTION_ID}}"
  local candidate_port="${2:-${UPDATE_CANDIDATE_PORT}}"
  local env_file="${PORTAL_DIR}/backend/.env.production"
  local unit_name
  unit_name="$(update_candidate_unit_name "${transaction_id}")" || return 1
  [[ -f "${env_file}" && ! -L "${env_file}" ]] || return 1
  portal_service_port_is_free "${candidate_port}" || return 1

  systemd-run \
    --unit="${unit_name}" \
    --description="BridgesLLM Portal private update candidate ${transaction_id}" \
    --working-directory="${PORTAL_DIR}/backend" \
    --property=Type=exec \
    --property=User=root \
    --property=Group=root \
    --property=Restart=no \
    --property=KillMode=control-group \
    --property=RuntimeMaxSec=1200 \
    --property=TimeoutStopSec=30 \
    --property="EnvironmentFile=${env_file}" \
    /usr/bin/env \
      "HOST=127.0.0.1" \
      "PORT=${candidate_port}" \
      "PORTAL_UPDATE_VALIDATION_MODE=1" \
      /usr/bin/node dist/server.js >> "${LOG_FILE}" 2>&1 || return 1

  UPDATE_TRANSACTION_CANDIDATE_UNIT="${unit_name}"
  local waited=0
  while (( waited < 30 )); do
    systemctl is-active --quiet "${unit_name}" && return 0
    if systemctl is-failed --quiet "${unit_name}"; then
      journalctl -u "${unit_name}" -n 80 --no-pager >> "${LOG_FILE}" 2>&1 || true
      return 1
    fi
    sleep 1
    waited=$((waited + 1))
  done
  return 1
}

portal_runtime_supports_update_validation_contract() {
  local portal_root="${1:-${PORTAL_DIR}}"
  local marker="${portal_root}/installer/update-validation-protocol-v1"
  local server="${portal_root}/backend/dist/server.js"
  python3 - "${portal_root}" "${marker}" "${server}" <<'PY2'
import os
import stat
import sys

root, marker, server = sys.argv[1:]
expected = b"BRIDGESLLM_UPDATE_VALIDATION_CONTRACT_V1\n"
if not os.path.isabs(root) or root != os.path.normpath(root):
    raise SystemExit(1)
for path, maximum in ((marker, 128), (server, 64 * 1024 * 1024)):
    try:
        details = os.lstat(path)
    except OSError:
        # Runtimes built before the validation contract simply do not
        # support it; that is a truthful negative, not a crash.
        raise SystemExit(1)
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != 0
        or details.st_nlink != 1
        or details.st_mode & 0o022
        or not 0 < details.st_size <= maximum
    ):
        raise SystemExit(1)
if open(marker, "rb").read() != expected:
    raise SystemExit(1)
if expected.rstrip() not in open(server, "rb").read():
    raise SystemExit(1)
PY2
}

verify_update_database_schema_exact() {
  # Migration checksums alone do not prove that Prisma-managed constraints,
  # indexes, defaults, foreign keys, or enums still exist. Compare the live
  # database to the signed datamodel with Prisma's read-only diff engine. The
  # database URL travels over stdin into a minimal child environment and is
  # never placed in a process argument.
  local db_url="$1"
  local backend_dir="${2:-${PORTAL_DIR}/backend}"
  local schema="${backend_dir}/prisma/schema.prisma"
  local prisma_cli="${backend_dir}/node_modules/prisma/build/index.js"
  [[ -n "${db_url}" ]] || return 1
  pg_url_component "${db_url}" host >/dev/null \
    && pg_url_component "${db_url}" port >/dev/null \
    && pg_url_component "${db_url}" database >/dev/null \
    && pg_url_component "${db_url}" user >/dev/null \
    || return 1
  python3 - "${backend_dir}" "${schema}" "${prisma_cli}" <<'PY2' \
    >> "${LOG_FILE}" 2>&1 || return 1
import os
import stat
import sys

backend, schema, prisma_cli = sys.argv[1:]
for path, kind, maximum in (
    (backend, "directory", 0),
    (schema, "file", 1024 * 1024),
    (prisma_cli, "file", 16 * 1024 * 1024),
):
    details = os.lstat(path)
    valid_kind = (
        stat.S_ISDIR(details.st_mode)
        if kind == "directory"
        else stat.S_ISREG(details.st_mode) and 0 < details.st_size <= maximum
    )
    if (
        not valid_kind
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_mode & 0o022
    ):
        raise SystemExit(1)
PY2
  local runner_source
  runner_source="$(
    cat <<'PY2'
import os
import subprocess
import sys
import threading

backend, schema, prisma_cli = sys.argv[1:]
secret = os.environ.get("DATABASE_URL", "").encode()
if (
    not secret
    or len(secret) > 128000
    or any(byte < 32 or byte == 127 for byte in secret)
):
    raise SystemExit(1)
command = [
    "/usr/bin/node",
    prisma_cli,
    "migrate",
    "diff",
    "--exit-code",
    "--from-schema-datasource",
    schema,
    "--to-schema-datamodel",
    schema,
]
process = subprocess.Popen(
    command,
    cwd=backend,
    stdin=subprocess.DEVNULL,
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
)
maximum_output = 1024 * 1024
captured = bytearray()
output_overflow = False


def drain_output():
    global output_overflow
    while True:
        chunk = process.stdout.read(65536)
        if not chunk:
            return
        remaining = maximum_output - len(captured)
        if remaining > 0:
            captured.extend(chunk[:remaining])
        if len(chunk) > remaining:
            output_overflow = True


reader = threading.Thread(target=drain_output, daemon=True)
reader.start()
try:
    result = process.wait(timeout=120)
except subprocess.TimeoutExpired:
    print("Prisma schema drift verification timed out", file=sys.stderr)
    raise SystemExit(1)
reader.join(timeout=5)
if reader.is_alive():
    print("Prisma schema drift output did not close", file=sys.stderr)
    raise SystemExit(1)
sanitized = bytes(captured).replace(secret, b"[redacted DATABASE_URL]")
if sanitized:
    sys.stderr.buffer.write(sanitized)
    if not sanitized.endswith(b"\n"):
        sys.stderr.buffer.write(b"\n")
if output_overflow:
    print("Prisma schema drift output exceeded its bound", file=sys.stderr)
    raise SystemExit(1)
if result != 0:
    print(
        f"Prisma schema drift verification failed with exit {result}",
        file=sys.stderr,
    )
    raise SystemExit(1)
PY2
  )" || return 1
  run_attested_database_operation \
    "${db_url}" prisma-schema-diff \
    python3 -c "${runner_source}" "${backend_dir}" "${schema}" "${prisma_cli}" \
    >> "${LOG_FILE}" 2>&1
}

stop_update_candidate() {
  local transaction_id="${1:-${UPDATE_TRANSACTION_ID}}"
  local candidate_port="${2:-${UPDATE_CANDIDATE_PORT}}"
  local unit_name state
  unit_name="$(update_candidate_unit_name "${transaction_id}")" || return 1
  state="$(systemctl show "${unit_name}" -p LoadState --value 2>/dev/null || true)"
  if [[ "${state}" == "loaded" ]]; then
    systemctl stop --no-block "${unit_name}" >> "${LOG_FILE}" 2>&1 || true
    local waited=0
    while (( waited < 30 )); do
      # systemd garbage-collects transient units the moment they stop, so
      # "no longer loaded" is the expected terminal state, not a failure.
      state="$(systemctl show "${unit_name}" -p LoadState --value 2>/dev/null || true)"
      if [[ "${state}" != "loaded" ]] \
        && portal_service_port_is_free "${candidate_port}"; then
        UPDATE_TRANSACTION_CANDIDATE_UNIT=""
        return 0
      fi
      if [[ "${state}" == "loaded" ]] \
        && portal_service_is_quiesced "${unit_name}" \
        && portal_service_port_is_free "${candidate_port}"; then
        systemctl reset-failed "${unit_name}" >> "${LOG_FILE}" 2>&1 || true
        UPDATE_TRANSACTION_CANDIDATE_UNIT=""
        return 0
      fi
      sleep 1
      waited=$((waited + 1))
    done
    state="$(systemctl show "${unit_name}" -p LoadState --value 2>/dev/null || true)"
    if [[ "${state}" == "loaded" ]]; then
      systemctl kill --kill-who=all --signal=SIGKILL "${unit_name}" >> "${LOG_FILE}" 2>&1 \
        || return 1
      sleep 1
      state="$(systemctl show "${unit_name}" -p LoadState --value 2>/dev/null || true)"
      if [[ "${state}" == "loaded" ]]; then
        portal_service_is_quiesced "${unit_name}" || return 1
      fi
    fi
  fi
  portal_service_port_is_free "${candidate_port}" || return 1
  UPDATE_TRANSACTION_CANDIDATE_UNIT=""
}

verify_update_candidate() {
  local transaction_id="${1:-${UPDATE_TRANSACTION_ID}}"
  local expected_version="${2:-${VERSION}}"
  local probe_token="${3:-${PORTAL_UPDATE_PROBE_TOKEN}}"
  local candidate_port="${4:-${UPDATE_CANDIDATE_PORT}}"
  local unit_name db_url
  unit_name="$(update_candidate_unit_name "${transaction_id}")" || return 1
  portal_runtime_supports_update_validation_contract "${PORTAL_DIR}" \
    || return 1
  db_url="$(read_env_value \
    "${PORTAL_DIR}/backend/.env.production" DATABASE_URL)" || return 1
  verify_portal_service_health \
    "${unit_name}" "http://127.0.0.1:${candidate_port}/health" 60 \
    && verify_portal_update_readiness \
      "${expected_version}" "${probe_token}" 900 "${unit_name}" \
      "http://127.0.0.1:${candidate_port}/health/update-ready" candidate \
    && verify_update_database_schema_exact "${db_url}" "${PORTAL_DIR}/backend"
}

verify_canonical_portal_routes_for_transaction() {
  local expected_version="$1"
  use_local_profile && return 0
  if use_tailnet_profile; then
    verify_tailnet_tls_ready
    return
  fi
  [[ -n "${DOMAIN}" ]] || return 1
  verify_portal_tls_ready || return 1
  [[ "${expected_version}" == 3.* ]] || verify_app_content_caddy_ready
}

start_canonical_portal_for_transaction() {
  if ${UPDATE_TRANSACTION_PORTAL_WAS_ACTIVE:-false}; then
    systemctl start bridgesllm-product >> "${LOG_FILE}" 2>&1
  else
    systemctl stop bridgesllm-product >> "${LOG_FILE}" 2>&1 || true
    portal_service_is_quiesced "bridgesllm-product" \
      && portal_service_port_is_free 4001
  fi
}

verify_canonical_portal_for_transaction() {
  local expected_version="$1" probe_token="$2"
  local allow_legacy_validation="${3:-false}"
  if ${UPDATE_TRANSACTION_PORTAL_WAS_ACTIVE:-false}; then
    verify_portal_service_health \
      "bridgesllm-product" "http://127.0.0.1:4001/health" 60 || return 1
    if [[ -n "${probe_token}" ]]; then
      local readiness_mode="canonical"
      if ! portal_runtime_supports_update_validation_contract "${PORTAL_DIR}"; then
        [[ "${allow_legacy_validation}" == "true" \
          && "${expected_version}" == 4.* ]] || return 1
        readiness_mode="legacy-canonical"
      fi
      verify_portal_update_readiness \
        "${expected_version}" "${probe_token}" 900 "bridgesllm-product" \
        "http://127.0.0.1:4001/health/update-ready" "${readiness_mode}" || return 1
    else
      [[ "${expected_version}" == 3.* ]] || return 1
      [[ "$(attest_existing_portal_for_update "${PORTAL_DIR}")" \
        == "${expected_version}" ]] || return 1
    fi
    verify_canonical_portal_routes_for_transaction "${expected_version}" || return 1
    # Replacement identity is (boot id, pid, start time): a recycled PID on
    # the same boot must not defeat the proof, and after a reboot every
    # process is provably new regardless of its number.
    local candidate_pid candidate_start current_boot
    candidate_pid="$(systemctl show bridgesllm-product -p MainPID --value 2>/dev/null || true)"
    [[ "${candidate_pid}" =~ ^[1-9][0-9]*$ ]] || return 1
    candidate_start="$(process_start_time_of_pid "${candidate_pid}")" || return 1
    current_boot="$(current_boot_id)" || return 1
    if [[ "${current_boot}" == "${UPDATE_TRANSACTION_BASELINE_BOOT_ID:-}" ]]; then
      [[ "${candidate_pid}" != "${UPDATE_TRANSACTION_BASELINE_PID:-0}" \
        || "${candidate_start}" != "${UPDATE_TRANSACTION_BASELINE_START_TIME:-0}" ]] \
        || return 1
    fi
  else
    portal_service_is_quiesced "bridgesllm-product" \
      && portal_service_port_is_free 4001
  fi
}

restore_and_verify_canonical_portal_state() {
  local expected_version="$1" probe_token="$2"
  restore_portal_service_boot_state "bridgesllm-product" || return 1
  start_canonical_portal_for_transaction \
    && verify_canonical_portal_for_transaction \
      "${expected_version}" "${probe_token}" true
}

canonical_portal_is_serving_version() {
  # Deliberately narrow: proves only that the canonical service is running and
  # answering as the expected version. Used to decide whether a failed
  # verification may safely tear the Portal back down.
  local expected_version="$1"
  [[ -n "${expected_version}" ]] || return 1
  systemctl is-active --quiet bridgesllm-product || return 1
  [[ "$(curl -sS --max-time 5 -o /dev/null -w '%{http_code}' \
    http://127.0.0.1:4001/health 2>/dev/null || true)" == "200" ]] || return 1
  [[ "$(attest_existing_portal_for_update "${PORTAL_DIR}" 2>/dev/null || true)" \
    == "${expected_version}" ]]
}

update_transaction_helper_path() {
  update_transaction_state_path "${UPDATE_STATE_HELPER}"
}

run_update_transaction_state_helper() {
  local helper test_root=""
  helper="$(update_transaction_helper_path)" || return 1
  [[ -f "${helper}" && ! -L "${helper}" ]] || return 1
  test_root="$(update_transaction_test_root 2>/dev/null || true)"
  if [[ -n "${test_root}" ]]; then
    python3 "${helper}" --test-root "${test_root}" "$@"
  else
    python3 "${helper}" "$@"
  fi
}

install_update_transaction_state_helper() {
  local staged_portal="$1"
  local source="${staged_portal}/installer/update-transaction-state.py"
  local destination state_root caddy_source caddy_destination
  destination="$(update_transaction_helper_path)" || return 1
  state_root="$(dirname "${destination}")"
  python3 - "${source}" "${state_root}" "${destination}" <<'PY2'
import os
import stat
import sys
import tempfile

source, state_root, destination = sys.argv[1:]
expected_uid = os.geteuid()
source_info = os.lstat(source)
if (
    not stat.S_ISREG(source_info.st_mode)
    or stat.S_ISLNK(source_info.st_mode)
    or source_info.st_uid != expected_uid
    or source_info.st_nlink != 1
    or not 1 <= source_info.st_size <= 256 * 1024
):
    raise SystemExit(1)
payload = open(source, "rb").read()
if b"\x00" in payload or not payload.startswith(b"#!/usr/bin/env python3\n"):
    raise SystemExit(1)

parent = os.path.dirname(state_root)
parent_info = os.lstat(parent)
if (
    not stat.S_ISDIR(parent_info.st_mode)
    or stat.S_ISLNK(parent_info.st_mode)
    or parent_info.st_uid != expected_uid
    or parent_info.st_mode & 0o022
):
    raise SystemExit(1)
try:
    os.mkdir(state_root, 0o700)
except FileExistsError:
    pass
state_info = os.lstat(state_root)
if (
    not stat.S_ISDIR(state_info.st_mode)
    or stat.S_ISLNK(state_info.st_mode)
    or state_info.st_uid != expected_uid
    or state_info.st_gid != os.getegid()
    or state_info.st_mode & 0o077
):
    raise SystemExit(1)
os.chmod(state_root, 0o700)

for receipt in ("active-update.json", "cutover-update.json"):
    try:
        os.lstat(os.path.join(state_root, receipt))
    except FileNotFoundError:
        continue
    raise SystemExit(1)

try:
    current = os.lstat(destination)
except FileNotFoundError:
    current = None
if current is not None and (
    not stat.S_ISREG(current.st_mode)
    or stat.S_ISLNK(current.st_mode)
    or current.st_uid != expected_uid
    or current.st_nlink != 1
    or current.st_mode & 0o077
):
    raise SystemExit(1)

descriptor, temporary = tempfile.mkstemp(
    prefix=".update-transaction-state.", dir=state_root
)
try:
    os.fchmod(descriptor, 0o600)
    with os.fdopen(descriptor, "wb") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, destination)
    temporary = ""
    directory_fd = os.open(
        state_root,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if temporary:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
PY2
  python3 "${destination}" --help >/dev/null 2>&1 || return 1
  caddy_source="${staged_portal}/installer/caddy-managed-config.py"
  caddy_destination="$(
    update_transaction_state_path "${UPDATE_CADDY_RECOVERY_HELPER}"
  )" || return 1
  python3 - "${caddy_source}" "${caddy_destination}" <<'PY2'
