read_update_transaction_field() {
  local target="$1" field="$2"
  run_update_transaction_state_helper read \
    --target "${target}" --field "${field}"
}

update_artifact_manifest() {
  local action="$1" artifact_path="$2" manifest_path="$3"
  local allow_absent="${4:-false}"
  [[ "${action}" == "create" || "${action}" == "verify" ]] || return 1
  [[ "${allow_absent}" == "true" || "${allow_absent}" == "false" ]] || return 1
  python3 - "${action}" "${artifact_path}" "${manifest_path}" "${allow_absent}" <<'PY2'
import hashlib
import hmac
import json
import os
import re
import stat
import sys
import tempfile

action, artifact_path, manifest_path, allow_absent_raw = sys.argv[1:]
allow_absent = allow_absent_raw == "true"
expected_uid = os.geteuid()
expected_gid = os.getegid()
max_entries = 350_000
max_bytes = 20 * 1024 * 1024 * 1024
max_manifest = 128 * 1024 * 1024


def fail() -> None:
    raise SystemExit(1)


def validate_text(value: str) -> None:
    if any(ord(char) < 32 or ord(char) == 127 for char in value):
        fail()


def xattr_identity(path: str) -> list[list[str]]:
    values: list[list[str]] = []
    try:
        names = sorted(os.listxattr(path, follow_symlinks=False))
        for name in names:
            validate_text(name)
            value = os.getxattr(path, name, follow_symlinks=False)
            values.append([name, hashlib.sha256(value).hexdigest()])
    except OSError:
        fail()
    return values


def regular_digest(path: str, before: os.stat_result) -> str:
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except OSError:
        fail()
    digest = hashlib.sha256()
    try:
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_dev != before.st_dev
            or opened.st_ino != before.st_ino
            or opened.st_nlink != 1
        ):
            fail()
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
        after = os.fstat(descriptor)
        if (
            after.st_dev != opened.st_dev
            or after.st_ino != opened.st_ino
            or after.st_size != opened.st_size
            or after.st_mtime_ns != opened.st_mtime_ns
            or after.st_ctime_ns != opened.st_ctime_ns
        ):
            fail()
    finally:
        os.close(descriptor)
    return digest.hexdigest()


def entry(path: str, relative: str, root: str) -> tuple[dict[str, object], int]:
    validate_text(relative)
    try:
        details = os.lstat(path)
    except OSError:
        fail()
    if (
        details.st_uid != expected_uid
        or details.st_gid != expected_gid
        or (not stat.S_ISLNK(details.st_mode) and details.st_mode & 0o022)
    ):
        fail()
    common: dict[str, object] = {
        "path": relative,
        "mode": stat.S_IMODE(details.st_mode),
        "uid": details.st_uid,
        "gid": details.st_gid,
        "mtime_ns": details.st_mtime_ns,
        "xattrs": xattr_identity(path),
    }
    if stat.S_ISDIR(details.st_mode):
        common["type"] = "directory"
        common["size"] = 0
        return common, 0
    if stat.S_ISREG(details.st_mode):
        if details.st_nlink != 1:
            fail()
        common["type"] = "file"
        common["size"] = details.st_size
        common["sha256"] = regular_digest(path, details)
        return common, details.st_size
    if stat.S_ISLNK(details.st_mode):
        try:
            target = os.readlink(path)
        except OSError:
            fail()
        validate_text(target)
        if os.path.isabs(target):
            fail()
        resolved = os.path.normpath(os.path.join(os.path.dirname(path), target))
        if os.path.commonpath((root, resolved)) != root:
            fail()
        common["type"] = "symlink"
        common["size"] = len(os.fsencode(target))
        common["target"] = target
        return common, len(os.fsencode(target))
    fail()


def scan() -> dict[str, object]:
    try:
        root_details = os.lstat(artifact_path)
    except FileNotFoundError:
        if not allow_absent:
            fail()
        return {
            "schema": "bridgesllm-update-artifact-v1",
            "state": "absent",
            "entries": [],
            "total_bytes": 0,
        }
    except OSError:
        fail()
    if stat.S_ISLNK(root_details.st_mode):
        fail()
    root = os.path.normpath(os.path.abspath(artifact_path))
    rows: list[dict[str, object]] = []
    total_bytes = 0
    if stat.S_ISDIR(root_details.st_mode):
        root_identity = (root_details.st_dev, root_details.st_ino)
        for current, directories, files in os.walk(root, topdown=True, followlinks=False):
            directories.sort()
            files.sort()
            relative_current = os.path.relpath(current, root)
            row, consumed = entry(current, relative_current, root)
            rows.append(row)
            total_bytes += consumed
            for name in [*directories, *files]:
                path = os.path.join(current, name)
                if os.path.islink(path):
                    relative = os.path.relpath(path, root)
                    row, consumed = entry(path, relative, root)
                    rows.append(row)
                    total_bytes += consumed
            directories[:] = [
                name for name in directories
                if not os.path.islink(os.path.join(current, name))
            ]
            for name in files:
                path = os.path.join(current, name)
                if os.path.islink(path):
                    continue
                relative = os.path.relpath(path, root)
                row, consumed = entry(path, relative, root)
                rows.append(row)
                total_bytes += consumed
            if len(rows) > max_entries or total_bytes > max_bytes:
                fail()
        final_root = os.lstat(root)
        if (final_root.st_dev, final_root.st_ino) != root_identity:
            fail()
    else:
        row, consumed = entry(root, ".", root)
        rows.append(row)
        total_bytes += consumed
    rows.sort(key=lambda item: os.fsencode(str(item["path"])))
    record: dict[str, object] = {
        "schema": "bridgesllm-update-artifact-v1",
        "state": "present",
        "entries": rows,
        "total_bytes": total_bytes,
    }
    return record


def canonical(record: dict[str, object]) -> bytes:
    return (
        json.dumps(record, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
        + "\n"
    ).encode("ascii")


record = scan()
identity = hashlib.sha256(canonical(record)).hexdigest()
record["integrity_sha256"] = identity
payload = canonical(record)
if len(payload) > max_manifest:
    fail()

parent = os.path.dirname(manifest_path)
if action == "create":
    try:
        parent_details = os.lstat(parent)
    except FileNotFoundError:
        os.mkdir(parent, 0o700)
        parent_details = os.lstat(parent)
    if (
        not stat.S_ISDIR(parent_details.st_mode)
        or stat.S_ISLNK(parent_details.st_mode)
        or parent_details.st_uid != expected_uid
        or parent_details.st_gid != expected_gid
        or parent_details.st_mode & 0o077
    ):
        fail()
    descriptor, temporary = tempfile.mkstemp(prefix=".artifact.", dir=parent)
    try:
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, manifest_path)
        temporary = ""
        directory_fd = os.open(
            parent,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
else:
    try:
        details = os.lstat(manifest_path)
    except OSError:
        fail()
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != expected_uid
        or details.st_gid != expected_gid
        or details.st_nlink != 1
        or stat.S_IMODE(details.st_mode) != 0o600
        or not 1 <= details.st_size <= max_manifest
    ):
        fail()
    try:
        stored = open(manifest_path, "rb").read()
    except OSError:
        fail()
    if not hmac.compare_digest(stored, payload):
        fail()
PY2
}

update_transaction_manifest_path() {
  local target="$1" name="$2"
  [[ "${name}" =~ ^[a-z][a-z0-9-]{0,63}$ ]] || return 1
  local transaction_dir
  transaction_dir="$(read_update_transaction_field "${target}" transaction_dir)" \
    || return 1
  printf '%s/manifests/%s.json\n' "${transaction_dir}" "${name}"
}

capture_update_running_app_intent() {
  local db_url="$1"
  local backup_dir transaction_id payload manifest raw connection_url
  backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
  transaction_id="$(
    read_update_transaction_field active transaction_id
  )" || return 1
  payload="${backup_dir}/running-app-intent.json"
  manifest="$(
    update_transaction_manifest_path active running-app-intent
  )" || return 1
  [[ ! -e "${payload}" && ! -L "${payload}" \
    && ! -e "${manifest}" && ! -L "${manifest}" ]] || return 1
  connection_url="$(libpq_database_url "${db_url}")" || return 1
  raw="$(mktemp "${backup_dir}/.running-app-intent.raw.XXXXXX")" \
    || return 1
  chmod 0600 "${raw}" || { rm -f -- "${raw}"; return 1; }
  assert_update_database_topology_unchanged "${db_url}" app-intent-capture \
    || { rm -f -- "${raw}"; return 1; }
  if ! run_with_update_pgpass "${db_url}" \
      psql --dbname="${connection_url}" --no-psqlrc \
        -v ON_ERROR_STOP=1 -qAtc '
SET search_path TO pg_catalog;
SELECT COALESCE(json_agg(json_build_object(
  '\''id'\'', app."id",
  '\''userId'\'', app."userId",
  '\''name'\'', app."name",
  '\''zipPath'\'', app."zipPath",
  '\''isActive'\'', app."isActive",
  '\''deployType'\'', app."deployType",
  '\''port'\'', app."port",
  '\''processStatus'\'', app."processStatus"
) ORDER BY app."id"), '\''[]'\''::json)::text
FROM public."App" AS app
WHERE app."deployType" = '\''fullstack'\''
  AND app."processStatus" IN ('\''running'\'', '\''starting'\'');
' > "${raw}" 2>> "${LOG_FILE}"; then
    rm -f -- "${raw}"
    return 1
  fi
  assert_update_database_topology_unchanged \
    "${db_url}" app-intent-capture-complete \
    || { rm -f -- "${raw}"; return 1; }
  if ! python3 - "${raw}" "${payload}" "${transaction_id}" <<'PY2'
import json
import os
import pathlib
import stat
import sys
import tempfile

source = pathlib.Path(sys.argv[1])
destination = pathlib.Path(sys.argv[2])
transaction_id = sys.argv[3]
try:
    rows = json.loads(source.read_text(encoding="utf-8"))
except (OSError, UnicodeError, json.JSONDecodeError):
    raise SystemExit(1)
if not isinstance(rows, list) or len(rows) > 100_000:
    raise SystemExit(1)
expected_keys = {
    "id", "userId", "name", "zipPath", "isActive", "deployType", "port",
    "processStatus",
}
seen = set()
for row in rows:
    if not isinstance(row, dict) or set(row) != expected_keys:
        raise SystemExit(1)
    if (
        not all(
            isinstance(row[key], str)
            and 0 < len(row[key].encode("utf-8")) <= 4096
            and "\x00" not in row[key]
            for key in ("id", "userId", "name", "zipPath")
        )
        or row["id"] in seen
        or row["deployType"] != "fullstack"
        or row["processStatus"] not in {"running", "starting"}
        or not isinstance(row["isActive"], bool)
        or not isinstance(row["port"], int)
        or isinstance(row["port"], bool)
        or not 1 <= row["port"] <= 65535
        or not os.path.isabs(row["zipPath"])
        or os.path.normpath(row["zipPath"]) != row["zipPath"]
    ):
        raise SystemExit(1)
    seen.add(row["id"])
document = {
    "schema": "bridgesllm-update-running-app-intent-v1",
    "transactionId": transaction_id,
    "apps": rows,
}
encoded = (json.dumps(document, sort_keys=True, separators=(",", ":")) + "\n").encode()
descriptor = os.open(
    destination,
    os.O_WRONLY | os.O_CREAT | os.O_EXCL
    | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    0o600,
)
try:
    os.write(descriptor, encoded)
    os.fchmod(descriptor, 0o600)
    os.fsync(descriptor)
finally:
    os.close(descriptor)
PY2
  then
    rm -f -- "${raw}" "${payload}"
    return 1
  fi
  rm -f -- "${raw}"
  fsync_update_payload "${payload}" || return 1
  update_artifact_manifest create "${payload}" "${manifest}" false \
    && update_artifact_manifest verify "${payload}" "${manifest}" false
}

reconcile_update_running_app_intent() {
  local target="${1:-active}"
  local db_url="$2"
  local backup_dir transaction_id payload manifest sql connection_url
  backup_dir="$(read_update_transaction_field "${target}" backup_dir)" \
    || return 1
  transaction_id="$(
    read_update_transaction_field "${target}" transaction_id
  )" || return 1
  payload="${backup_dir}/running-app-intent.json"
  manifest="$(
    update_transaction_manifest_path "${target}" running-app-intent
  )" || return 1
  update_artifact_manifest verify "${payload}" "${manifest}" false \
    || return 1
  sql="$(mktemp "${backup_dir}/.running-app-intent.sql.XXXXXX")" \
    || return 1
  chmod 0600 "${sql}" || { rm -f -- "${sql}"; return 1; }
  if ! python3 - "${payload}" "${sql}" "${transaction_id}" <<'PY2'
import json
import os
import pathlib
import sys

source = pathlib.Path(sys.argv[1])
destination = pathlib.Path(sys.argv[2])
transaction_id = sys.argv[3]
document = json.loads(source.read_text(encoding="utf-8"))
if (
    not isinstance(document, dict)
    or set(document) != {"schema", "transactionId", "apps"}
    or document.get("schema") != "bridgesllm-update-running-app-intent-v1"
    or document.get("transactionId") != transaction_id
    or not isinstance(document.get("apps"), list)
):
    raise SystemExit(1)
encoded = json.dumps(document, sort_keys=True, separators=(",", ":"))
literal = encoded.replace("'", "''")
statement = f'''BEGIN;
SET LOCAL search_path TO pg_catalog;
DO $bridgesllm_running_app_intent$
DECLARE
  item jsonb;
  current_row record;
  desired_status text;
BEGIN
  FOR item IN
    SELECT value
    FROM jsonb_array_elements('{literal}'::jsonb -> 'apps')
  LOOP
    SELECT app."userId", app."name", app."zipPath", app."isActive",
           app."deployType", app."port", app."processStatus"
      INTO current_row
      FROM public."App" AS app
      WHERE app."id" = item ->> 'id'
      FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'captured running App disappeared during update';
    END IF;
    IF current_row."userId" IS DISTINCT FROM item ->> 'userId'
       OR current_row."name" IS DISTINCT FROM item ->> 'name'
       OR current_row."zipPath" IS DISTINCT FROM item ->> 'zipPath'
       OR current_row."isActive" IS DISTINCT FROM (item ->> 'isActive')::boolean
       OR current_row."deployType" IS DISTINCT FROM item ->> 'deployType'
       OR current_row."port" IS DISTINCT FROM (item ->> 'port')::integer THEN
      RAISE EXCEPTION 'captured running App identity changed during update';
    END IF;
    desired_status := item ->> 'processStatus';
    IF desired_status NOT IN ('running', 'starting') THEN
      RAISE EXCEPTION 'captured running App intent is invalid';
    END IF;
    IF current_row."processStatus" = 'stopped' THEN
      UPDATE public."App"
         SET "processStatus" = desired_status,
             "updatedAt" = CURRENT_TIMESTAMP
       WHERE "id" = item ->> 'id';
    ELSIF current_row."processStatus" NOT IN ('running', 'starting') THEN
      RAISE EXCEPTION 'captured running App entered a non-recoverable state';
    END IF;
  END LOOP;
END
$bridgesllm_running_app_intent$;
COMMIT;
'''
descriptor = os.open(
    destination,
    os.O_WRONLY | os.O_TRUNC | getattr(os, "O_CLOEXEC", 0)
    | getattr(os, "O_NOFOLLOW", 0),
)
try:
    os.write(descriptor, statement.encode("utf-8"))
    os.fchmod(descriptor, 0o600)
    os.fsync(descriptor)
finally:
    os.close(descriptor)
PY2
  then
    rm -f -- "${sql}"
    return 1
  fi
  connection_url="$(libpq_database_url "${db_url}")" \
    || { rm -f -- "${sql}"; return 1; }
  if ! run_attested_database_operation \
      "${db_url}" app-intent-reconcile \
      psql --dbname="${connection_url}" --no-psqlrc \
        -v ON_ERROR_STOP=1 --file="${sql}" \
      >> "${LOG_FILE}" 2>&1; then
    rm -f -- "${sql}"
    return 1
  fi
  rm -f -- "${sql}"
  update_artifact_manifest verify "${payload}" "${manifest}" false
}

snapshot_update_backend_env_alias() {
  local source="$1" snapshot="$2"
  python3 - "${source}" "${snapshot}" <<'PY2'
import base64
import json
import os
import stat
import sys

source, snapshot = sys.argv[1:]
kind_path = os.path.join(snapshot, "backend.env.alias.json")
file_path = os.path.join(snapshot, "backend.env.alias.file")


def xattrs(path: str) -> list[list[str]]:
    return [
        [
            name,
            base64.b64encode(
                os.getxattr(path, name, follow_symlinks=False)
            ).decode("ascii"),
        ]
        for name in sorted(os.listxattr(path, follow_symlinks=False))
    ]


try:
    details = os.lstat(source)
except FileNotFoundError:
    record = {
        "schema": "bridgesllm-backend-env-alias-v1",
        "kind": "absent",
    }
else:
    if stat.S_ISREG(details.st_mode):
        if details.st_nlink != 1:
            raise SystemExit(1)
        source_fd = os.open(
            source,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
        )
        destination_fd = os.open(
            file_path,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
            0o600,
        )
        try:
            opened = os.fstat(source_fd)
            if (
                not stat.S_ISREG(opened.st_mode)
                or opened.st_dev != details.st_dev
                or opened.st_ino != details.st_ino
                or opened.st_nlink != 1
            ):
                raise SystemExit(1)
            os.fchown(destination_fd, os.geteuid(), os.getegid())
            os.fchmod(destination_fd, 0o600)
            while True:
                chunk = os.read(source_fd, 1024 * 1024)
                if not chunk:
                    break
                view = memoryview(chunk)
                while view:
                    consumed = os.write(destination_fd, view)
                    if consumed <= 0:
                        raise OSError("snapshot write made no progress")
                    view = view[consumed:]
            os.fsync(destination_fd)
            after = os.fstat(source_fd)
            if (
                after.st_dev != opened.st_dev
                or after.st_ino != opened.st_ino
                or after.st_size != opened.st_size
                or after.st_mtime_ns != opened.st_mtime_ns
                or after.st_ctime_ns != opened.st_ctime_ns
            ):
                raise SystemExit(1)
        finally:
            os.close(source_fd)
            os.close(destination_fd)
        record = {
            "schema": "bridgesllm-backend-env-alias-v1",
            "kind": "file",
            "mode": stat.S_IMODE(opened.st_mode),
            "uid": opened.st_uid,
            "gid": opened.st_gid,
            "atimeNs": opened.st_atime_ns,
            "mtimeNs": opened.st_mtime_ns,
            "size": opened.st_size,
            "xattrs": xattrs(source),
        }
    elif stat.S_ISLNK(details.st_mode):
        target = os.fsencode(os.readlink(source))
        if len(target) > 4096 or b"\0" in target:
            raise SystemExit(1)
        record = {
            "schema": "bridgesllm-backend-env-alias-v1",
            "kind": "symlink",
            "targetBase64": base64.b64encode(target).decode("ascii"),
            "uid": details.st_uid,
            "gid": details.st_gid,
            "atimeNs": details.st_atime_ns,
            "mtimeNs": details.st_mtime_ns,
            "xattrs": xattrs(source),
        }
    else:
        raise SystemExit(1)

payload = (
    json.dumps(record, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    + "\n"
).encode("ascii")
descriptor = os.open(
    kind_path,
    os.O_WRONLY | os.O_CREAT | os.O_EXCL
    | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    0o600,
)
try:
    os.fchmod(descriptor, 0o600)
    view = memoryview(payload)
    while view:
        consumed = os.write(descriptor, view)
        if consumed <= 0:
            raise OSError("alias snapshot write made no progress")
        view = view[consumed:]
    os.fsync(descriptor)
finally:
    os.close(descriptor)
directory_fd = os.open(
    snapshot,
    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
)
try:
    os.fsync(directory_fd)
finally:
    os.close(directory_fd)
PY2
}

restore_update_backend_env_alias() {
  local snapshot="$1" destination="$2"
  python3 - "${snapshot}" "${destination}" <<'PY2'
import base64
import hashlib
import json
import os
import secrets
import stat
import sys

snapshot, destination = sys.argv[1:]
kind_path = os.path.join(snapshot, "backend.env.alias.json")
file_path = os.path.join(snapshot, "backend.env.alias.file")
try:
    marker = os.lstat(kind_path)
    record = json.loads(open(kind_path, "rb").read())
except (OSError, ValueError):
    raise SystemExit(1)
if (
    not stat.S_ISREG(marker.st_mode)
    or stat.S_ISLNK(marker.st_mode)
    or marker.st_uid != os.geteuid()
    or marker.st_gid != os.getegid()
    or marker.st_nlink != 1
    or stat.S_IMODE(marker.st_mode) != 0o600
    or not isinstance(record, dict)
    or record.get("schema") != "bridgesllm-backend-env-alias-v1"
    or record.get("kind") not in {"absent", "file", "symlink"}
):
    raise SystemExit(1)

parent = os.path.dirname(destination)
parent_details = os.lstat(parent)
if (
    not stat.S_ISDIR(parent_details.st_mode)
    or stat.S_ISLNK(parent_details.st_mode)
    or parent_details.st_uid != os.geteuid()
    or parent_details.st_gid != os.getegid()
    or parent_details.st_mode & 0o022
):
    raise SystemExit(1)


def fsync_destination_parent() -> None:
    descriptor = os.open(
        parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


# The promotion helper can be killed after publishing its private temporary
# symlink but before rename. Recovery owns and removes only that exact bounded
# residue before comparing/restoring the original alias state.
temporary_prefix = f".{os.path.basename(destination)}.update-link."
removed_residue = False
for candidate_name in os.listdir(parent):
    if not candidate_name.startswith(temporary_prefix):
        continue
    candidate = os.path.join(parent, candidate_name)
    candidate_details = os.lstat(candidate)
    if (
        not stat.S_ISLNK(candidate_details.st_mode)
        or candidate_details.st_uid != os.geteuid()
        or candidate_details.st_gid != os.getegid()
        or os.readlink(candidate) != ".env.production"
    ):
        raise SystemExit(1)
    os.unlink(candidate)
    removed_residue = True
if removed_residue:
    fsync_destination_parent()


def xattr_identity(path: str) -> tuple[tuple[bytes, bytes], ...]:
    return tuple(
        (
            os.fsencode(name),
            os.getxattr(path, name, follow_symlinks=False),
        )
        for name in sorted(os.listxattr(path, follow_symlinks=False))
    )


def file_identity(path: str) -> tuple[object, ...]:
    details = os.lstat(path)
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_nlink != 1
    ):
        raise OSError("not an exact regular file")
    digest = hashlib.sha256()
    descriptor = os.open(
        path,
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        opened = os.fstat(descriptor)
        if (
            opened.st_dev != details.st_dev
            or opened.st_ino != details.st_ino
            or opened.st_nlink != 1
        ):
            raise OSError("file changed while opening")
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    finally:
        os.close(descriptor)
    return (
        stat.S_IMODE(details.st_mode),
        details.st_uid,
        details.st_gid,
        details.st_size,
        details.st_mtime_ns,
        digest.digest(),
        xattr_identity(path),
    )


def file_matches_record(path: str) -> bool:
    try:
        expected_xattrs = tuple(
            (
                os.fsencode(name),
                base64.b64decode(value, validate=True),
            )
            for name, value in record["xattrs"]
        )
        expected = (
            int(record["mode"]),
            int(record["uid"]),
            int(record["gid"]),
            int(record["size"]),
            int(record["mtimeNs"]),
            hashlib.sha256(open(file_path, "rb").read()).digest(),
            expected_xattrs,
        )
    except (KeyError, OSError, TypeError, ValueError):
        raise SystemExit(1)
    try:
        return file_identity(path) == expected
    except OSError:
        return False


def original_matches() -> bool:
    kind = record["kind"]
    try:
        current = os.lstat(destination)
    except FileNotFoundError:
        return kind == "absent"
    if kind == "file":
        return file_matches_record(destination)
    if kind == "symlink":
        if not stat.S_ISLNK(current.st_mode):
            return False
        try:
            expected_target = base64.b64decode(
                record["targetBase64"], validate=True
            )
            expected_xattrs = tuple(
                (
                    os.fsencode(name),
                    base64.b64decode(value, validate=True),
                )
                for name, value in record["xattrs"]
            )
        except (KeyError, TypeError, ValueError):
            raise SystemExit(1)
        return (
            os.fsencode(os.readlink(destination)) == expected_target
            and current.st_uid == record.get("uid")
            and current.st_gid == record.get("gid")
            and current.st_mtime_ns == record.get("mtimeNs")
            and xattr_identity(destination) == expected_xattrs
        )
    return False


if original_matches():
    raise SystemExit(0)

try:
    current = os.lstat(destination)
except FileNotFoundError:
    current = None
promoted = (
    current is not None
    and stat.S_ISLNK(current.st_mode)
    and current.st_uid == os.geteuid()
    and current.st_gid == os.getegid()
    and os.fsencode(os.readlink(destination)) == b".env.production"
)
if not promoted:
    raise SystemExit(1)

kind = record["kind"]
temporary = ""
if kind == "absent":
    os.unlink(destination)
elif kind == "file":
    source_details = os.lstat(file_path)
    if (
        not stat.S_ISREG(source_details.st_mode)
        or stat.S_ISLNK(source_details.st_mode)
        or source_details.st_nlink != 1
    ):
        raise SystemExit(1)
    try:
        desired_mode = int(record["mode"])
        desired_uid = int(record["uid"])
        desired_gid = int(record["gid"])
        desired_atime_ns = int(record["atimeNs"])
        desired_mtime_ns = int(record["mtimeNs"])
        desired_size = int(record["size"])
        desired_xattrs = [
            (name, base64.b64decode(value, validate=True))
            for name, value in record["xattrs"]
        ]
    except (KeyError, TypeError, ValueError):
        raise SystemExit(1)
    if (
        not 0 <= desired_mode <= 0o7777
        or desired_uid < 0
        or desired_gid < 0
        or desired_atime_ns < 0
        or desired_mtime_ns < 0
        or desired_size != source_details.st_size
    ):
        raise SystemExit(1)
    for _ in range(16):
        temporary = os.path.join(
            parent, f".update-env-file.{secrets.token_hex(12)}"
        )
        try:
            descriptor = os.open(
                temporary,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0),
                0o600,
            )
            break
        except FileExistsError:
            temporary = ""
    else:
        raise SystemExit(1)
    try:
        os.fchown(descriptor, desired_uid, desired_gid)
        os.fchmod(descriptor, desired_mode)
        with open(file_path, "rb") as source:
            while True:
                chunk = source.read(1024 * 1024)
                if not chunk:
                    break
                view = memoryview(chunk)
                while view:
                    consumed = os.write(descriptor, view)
                    if consumed <= 0:
                        raise OSError("restore write made no progress")
                    view = view[consumed:]
        for name, value in desired_xattrs:
            os.setxattr(
                temporary,
                name,
                value,
                follow_symlinks=False,
            )
        os.utime(
            temporary,
            ns=(desired_atime_ns, desired_mtime_ns),
            follow_symlinks=False,
        )
        os.fsync(descriptor)
        os.close(descriptor)
        descriptor = -1
        os.replace(temporary, destination)
        temporary = ""
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
else:
    try:
        target = base64.b64decode(record["targetBase64"], validate=True)
        expected_xattrs = [
            (name, base64.b64decode(value, validate=True))
            for name, value in record["xattrs"]
        ]
        uid = int(record["uid"])
        gid = int(record["gid"])
        atime_ns = int(record["atimeNs"])
        mtime_ns = int(record["mtimeNs"])
    except (KeyError, TypeError, ValueError):
        raise SystemExit(1)
    if len(target) > 4096 or b"\0" in target:
        raise SystemExit(1)
    for _ in range(16):
        temporary = os.path.join(
            parent, f".update-env-link.{secrets.token_hex(12)}"
        )
        try:
            os.symlink(os.fsdecode(target), temporary)
            break
        except FileExistsError:
            temporary = ""
    else:
        raise SystemExit(1)
    try:
        os.lchown(temporary, uid, gid)
        for name, value in expected_xattrs:
            os.setxattr(temporary, name, value, follow_symlinks=False)
        os.utime(
            temporary,
            ns=(atime_ns, mtime_ns),
            follow_symlinks=False,
        )
        os.replace(temporary, destination)
        temporary = ""
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass

fsync_destination_parent()
if not original_matches():
    raise SystemExit(1)
PY2
}

snapshot_update_runtime_and_environment() {
  local backup_dir runtime_snapshot environment_snapshot
  local runtime_manifest environment_manifest
  backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
  runtime_snapshot="${backup_dir}/portal-runtime"
  environment_snapshot="${backup_dir}/environment"
  runtime_manifest="$(update_transaction_manifest_path active runtime)" || return 1
  environment_manifest="$(update_transaction_manifest_path active environment)" || return 1

  install -d -m 0700 -- "${runtime_snapshot}" "${environment_snapshot}" || return 1
  rsync -aHAX --numeric-ids --delete \
    --exclude='node_modules' \
    --exclude='.git' \
    --exclude='.env' \
    --exclude='.env.production' \
    --exclude='/projects' \
    --exclude='/apps' \
    --exclude='/assets' \
    --exclude='/upload-temp' \
    --exclude='/.data' \
    --exclude='/backend/.data' \
    "${PORTAL_DIR}/" "${runtime_snapshot}/" >> "${LOG_FILE}" 2>&1 || return 1
  # Public 3.26.x tarballs shipped runtime files with group/other-writable
  # modes (0777 vnc_auto.html) and tarball-numeric owners (xfce4-config).
  # The snapshot manifest contract rightly refuses such entries. Normalize
  # ONLY the snapshot copies: the live tree stays untouched until cutover,
  # and a rollback restores exact content with sane root-owned permissions.
  local snapshot_entry
  while IFS= read -r -d '' snapshot_entry; do
    printf 'normalized legacy snapshot permissions: %s\n' "${snapshot_entry}" \
      >> "${LOG_FILE}"
    chown -h root:root -- "${snapshot_entry}" || return 1
    [[ -L "${snapshot_entry}" ]] \
      || chmod g-w,o-w -- "${snapshot_entry}" || return 1
  done < <(
    find "${runtime_snapshot}" \
      \( \( -perm /022 -a ! -type l \) -o ! -user root -o ! -group root \) \
      -print0 2>> "${LOG_FILE}"
  ) || return 1
  cp -a -- "${PORTAL_DIR}/backend/.env.production" \
    "${environment_snapshot}/backend.env.production" || return 1
  cp -a -- "${PORTAL_DIR}/frontend/.env" \
    "${environment_snapshot}/frontend.env" || return 1
  snapshot_update_backend_env_alias \
    "${PORTAL_DIR}/backend/.env" "${environment_snapshot}" || return 1
  sync -f "${backup_dir}" || return 1
  update_artifact_manifest create "${runtime_snapshot}" "${runtime_manifest}" false \
    && update_artifact_manifest verify "${runtime_snapshot}" "${runtime_manifest}" false \
    && update_artifact_manifest create "${environment_snapshot}" "${environment_manifest}" false \
    && update_artifact_manifest verify "${environment_snapshot}" "${environment_manifest}" false
}

