update_regular_files_equal() {
  local first="$1" second="$2"
  python3 - "${first}" "${second}" <<'PY2'
import hashlib
import os
import stat
import sys


def identity(path: str) -> tuple[object, ...]:
    details = os.lstat(path)
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_nlink != 1
    ):
        raise SystemExit(1)
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    xattrs = tuple(
        (name, os.getxattr(path, name, follow_symlinks=False))
        for name in sorted(os.listxattr(path, follow_symlinks=False))
    )
    return (
        stat.S_IMODE(details.st_mode),
        details.st_uid,
        details.st_gid,
        details.st_size,
        details.st_mtime_ns,
        digest.digest(),
        xattrs,
    )


try:
    if identity(sys.argv[1]) != identity(sys.argv[2]):
        raise SystemExit(1)
except OSError:
    raise SystemExit(1)
PY2
}

