    --exclude='/upload-temp' \
    --exclude='/.data' \
    --exclude='/backend/.data' \
    "${snapshot}/" "${PORTAL_DIR}/" 2>> "${LOG_FILE}")" || return 1
  [[ -z "${changes}" ]]
}

atomic_restore_update_file() {
  local source="$1" destination="$2"
  python3 - "${source}" "${destination}" <<'PY2'
import os
import stat
import sys
import tempfile

source, destination = sys.argv[1:]
source_details = os.lstat(source)
if (
    not stat.S_ISREG(source_details.st_mode)
    or stat.S_ISLNK(source_details.st_mode)
    or source_details.st_nlink != 1
):
    raise SystemExit(1)
parent = os.path.dirname(destination)
parent_details = os.lstat(parent)
if not stat.S_ISDIR(parent_details.st_mode) or stat.S_ISLNK(parent_details.st_mode):
    raise SystemExit(1)
try:
    current = os.lstat(destination)
except FileNotFoundError:
    current = None
if current is not None and (
    not stat.S_ISREG(current.st_mode)
    or stat.S_ISLNK(current.st_mode)
    or current.st_nlink != 1
):
    raise SystemExit(1)
payload = open(source, "rb").read()
xattrs = tuple(
    (name, os.getxattr(source, name, follow_symlinks=False))
    for name in sorted(os.listxattr(source, follow_symlinks=False))
)
descriptor, temporary = tempfile.mkstemp(prefix=".update-restore.", dir=parent)
try:
    os.fchown(descriptor, source_details.st_uid, source_details.st_gid)
    os.fchmod(descriptor, stat.S_IMODE(source_details.st_mode))
    with os.fdopen(descriptor, "wb") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    for name, value in xattrs:
        os.setxattr(temporary, name, value, follow_symlinks=False)
    os.utime(
        temporary,
        ns=(source_details.st_atime_ns, source_details.st_mtime_ns),
        follow_symlinks=False,
    )
    os.replace(temporary, destination)
    temporary = ""
    directory_fd = os.open(
        parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if temporary:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
PY2
}

restore_update_environment_snapshot() {
  local backup_dir snapshot updated manifest updated_manifest
  backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
  snapshot="${backup_dir}/environment"
  updated="${backup_dir}/environment.updated"
  manifest="$(update_transaction_manifest_path active environment)" || return 1
  updated_manifest="$(
    update_transaction_manifest_path active environment-updated
  )" || return 1
  update_artifact_manifest verify "${snapshot}" "${manifest}" false || return 1
  update_artifact_manifest verify "${updated}" "${updated_manifest}" false || return 1
  # Environment promotion replaces the backend and frontend files separately,
  # so SIGKILL between them leaves a legitimate mixed state. Converge each
  # file independently: already-original is done, exactly-updated rolls back,
  # anything else is foreign content and fails closed.
  local relative current
  for relative in backend.env.production frontend.env; do
    case "${relative}" in
      backend.env.production) current="${PORTAL_DIR}/backend/.env.production" ;;
      frontend.env) current="${PORTAL_DIR}/frontend/.env" ;;
    esac
    if update_regular_files_equal "${snapshot}/${relative}" "${current}"; then
      continue
    fi
    update_regular_files_equal "${updated}/${relative}" "${current}" || return 1
    atomic_restore_update_file "${snapshot}/${relative}" "${current}" || return 1
  done
  restore_update_backend_env_alias \
    "${snapshot}" "${PORTAL_DIR}/backend/.env" || return 1
  sync -f "${PORTAL_DIR}/backend" || return 1
  sync -f "${PORTAL_DIR}/frontend" || return 1
  update_regular_files_equal \
    "${snapshot}/backend.env.production" "${PORTAL_DIR}/backend/.env.production" \
    && update_regular_files_equal \
      "${snapshot}/frontend.env" "${PORTAL_DIR}/frontend/.env" \
    && restore_update_backend_env_alias \
      "${snapshot}" "${PORTAL_DIR}/backend/.env"
}

restore_update_dependencies_snapshot() {
  local backup_dir snapshot manifest preexisted
  backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
  snapshot="${backup_dir}/backend-node-modules"
  manifest="$(update_transaction_manifest_path active dependencies)" || return 1
  preexisted="$(read_update_transaction_field active node_modules_preexisted)" || return 1
  update_artifact_manifest verify "${snapshot}" "${manifest}" true || return 1
  if [[ -e "${PORTAL_DIR}/backend/node_modules" \
    || -L "${PORTAL_DIR}/backend/node_modules" ]]; then
    [[ -d "${PORTAL_DIR}/backend/node_modules" \
      && ! -L "${PORTAL_DIR}/backend/node_modules" ]] || return 1
    rm -rf -- "${PORTAL_DIR}/backend/node_modules"
  fi
  if [[ "${preexisted}" == "true" ]]; then
    install -d -m 0700 -- "${PORTAL_DIR}/backend/node_modules" || return 1
    rsync -aHAX --numeric-ids --delete \
      "${snapshot}/" "${PORTAL_DIR}/backend/node_modules/" \
      >> "${LOG_FILE}" 2>&1 || return 1
    sync -f "${PORTAL_DIR}/backend/node_modules" || return 1
    update_artifact_manifest verify \
      "${PORTAL_DIR}/backend/node_modules" "${manifest}" false
  else
    update_artifact_manifest verify \
      "${PORTAL_DIR}/backend/node_modules" "${manifest}" true
  fi
}

restore_update_caddy_snapshot() {
  local backup_dir snapshot expected_current manifest required helper
  backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
  snapshot="${backup_dir}/Caddyfile"
  expected_current="${backup_dir}/Caddyfile.updated"
  manifest="$(update_transaction_manifest_path active caddy)" || return 1
  required="$(read_update_transaction_field active caddy_snapshot_required)" || return 1
  update_artifact_manifest verify "${snapshot}" "${manifest}" true || return 1
  [[ "${required}" == "true" ]] || return 0
  if [[ ! -e "${expected_current}" && ! -L "${expected_current}" ]]; then
    # The managed helper durably writes the exact would-be installed snapshot
    # before replacing Caddy. If it does not exist, replacement could not have
    # begun; accept only an exact match to the original snapshot.
    update_artifact_manifest verify /etc/caddy/Caddyfile "${manifest}" false
    return
  fi
  [[ -f "${expected_current}" && ! -L "${expected_current}" ]] || return 1
  helper="$(update_transaction_state_path "${UPDATE_CADDY_RECOVERY_HELPER}")" \
    || return 1
  [[ -f "${helper}" && ! -L "${helper}" ]] || return 1
  python3 "${helper}" restore \
    --caddy-path /etc/caddy/Caddyfile \
    --snapshot-path "${snapshot}" \
    --expected-current-path "${expected_current}" \
    >> "${LOG_FILE}" 2>&1 || return 1
  update_artifact_manifest verify /etc/caddy/Caddyfile "${manifest}" false
}

restore_update_provenance_snapshot() {
  local backup_dir manifest existed
  backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
  manifest="$(update_transaction_manifest_path active provenance)" || return 1
  existed="$(read_update_transaction_field active deploy_stamp_preexisted)" || return 1
  update_artifact_manifest verify \
    "${backup_dir}/last-portal-deploy.previous" "${manifest}" true || return 1
  UPDATE_RECOVERY_DEPLOY_STAMP_CAPTURED=true
  UPDATE_RECOVERY_DEPLOY_STAMP_EXISTED="${existed}"
  UPDATE_RECOVERY_DEPLOY_STAMP_BACKUP="${backup_dir}/last-portal-deploy.previous"
  restore_portal_deploy_stamp_after_failed_update || return 1
  update_artifact_manifest verify "${PORTAL_DEPLOY_STAMP}" "${manifest}" true
}

prepare_updated_environment_candidate() {
  local backup_dir source candidate manifest env_file stage_dir transaction_id
  local portal_app_sources_root
  backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
  stage_dir="$(read_update_transaction_field active stage_dir)" || return 1
  transaction_id="$(read_update_transaction_field active transaction_id)" \
    || return 1
  source="${backup_dir}/environment"
  candidate="${backup_dir}/environment.updated"
  manifest="$(update_transaction_manifest_path active environment-updated)" \
    || return 1
  [[ -d "${source}" && ! -L "${source}" ]] || return 1
  rm -rf -- "${candidate}"
  install -d -m 0700 -- "${candidate}" || return 1
  rsync -aHAX --numeric-ids --delete "${source}/" "${candidate}/" \
    >> "${LOG_FILE}" 2>&1 || return 1
  env_file="${candidate}/backend.env.production"
  [[ -f "${env_file}" && ! -L "${env_file}" ]] || return 1

  # A transient validation process receives this flag through systemd only.
  # Persisting it would turn the canonical Portal into a health-only server.
  remove_env_assignment_atomic "${env_file}" "PORTAL_UPDATE_VALIDATION_MODE" \
    || return 1
  sed -i 's|^\(MAIL_DOMAIN=[^[:space:]]*\)DOMAIN=.*|\1|' "${env_file}" \
    || return 1
  grep -q '^HOST=' "${env_file}" \
    && sed -i 's|^HOST=.*|HOST=127.0.0.1|' "${env_file}" \
    || printf '\nHOST=127.0.0.1\n' >> "${env_file}"
  grep -q '^INSTALL_ROOT=' "${env_file}" \
    || printf 'INSTALL_ROOT=%s\n' "${INSTALL_ROOT}" >> "${env_file}"
  grep -q '^APPS_ROOT=' "${env_file}" \
    || printf 'APPS_ROOT=%s/apps\n' "${INSTALL_ROOT}" >> "${env_file}"
  grep -q '^UPLOAD_DIR=' "${env_file}" \
    || printf 'UPLOAD_DIR=%s/uploads\n' "${INSTALL_ROOT}" >> "${env_file}"
  grep -q '^INSTALL_PROFILE=' "${env_file}" \
    || printf 'INSTALL_PROFILE=%s\n' "${INSTALL_PROFILE}" >> "${env_file}"
  grep -q '^PORTAL_URL=' "${env_file}" \
    || printf 'PORTAL_URL=%s\n' "$(portal_primary_origin)" >> "${env_file}"
  portal_app_sources_root="$(
    select_portal_app_sources_root \
      "${env_file}" "${UPDATE_TRANSACTION_PREVIOUS_VERSION}"
  )" || return 1
  ensure_portal_app_sources_root "${portal_app_sources_root}" || return 1
  set_env_value_atomic \
    "${env_file}" "PORTAL_APPS_ROOT" "${portal_app_sources_root}" \
    || return 1
  set_env_value_atomic \
    "${env_file}" "PORTAL_APP_ZIPS_ROOT" \
    "${PORTAL_DIR}/upload-temp/app-zips" || return 1

  set_env_value_atomic "${env_file}" "APP_CONTENT_DOMAIN" "${APP_CONTENT_DOMAIN}" \
    || return 1
  set_env_value_atomic "${env_file}" "APP_CONTENT_ORIGIN" "${APP_CONTENT_ORIGIN}" \
    || return 1
  set_env_value_atomic "${env_file}" "APP_CONTENT_DNS_MODE" "${APP_CONTENT_DNS_MODE}" \
    || return 1
  if [[ -n "${TELEMETRY_INSTALL_ID}" ]]; then
    set_env_value_atomic "${env_file}" "TELEMETRY_INSTALL_ID" "${TELEMETRY_INSTALL_ID}" \
      || return 1
  fi
  if [[ -n "${DOMAIN}" ]]; then
    set_env_value_atomic "${env_file}" "DOMAIN" "${DOMAIN}" || return 1
  fi
  grep -q '^JWT_REFRESH_SECRET=' "${env_file}" \
    || printf 'JWT_REFRESH_SECRET=%s\n' "$(rand_hex 32)" >> "${env_file}"
  set_env_value_atomic \
    "${env_file}" "PORTAL_UPDATE_PROBE_TOKEN" "${PORTAL_UPDATE_PROBE_TOKEN}" \
    || return 1
  local project_egress_secret=""
  project_egress_secret="$(
    read_env_value "${env_file}" "PROJECT_EGRESS_TOKEN_SECRET" || true
  )"
  if [[ -z "${project_egress_secret}" ]]; then
    project_egress_secret="$(rand_hex 32)"
  fi
  valid_project_egress_token_secret "${project_egress_secret}" || return 1
  set_env_value_atomic \
    "${env_file}" "PROJECT_EGRESS_TOKEN_SECRET" "${project_egress_secret}" \
    || return 1
  apply_prepared_update_project_runtime_environment \
    "${env_file}" "${stage_dir}" "${transaction_id}" || return 1
  chmod --reference="${source}/backend.env.production" "${env_file}" || return 1
  chown --reference="${source}/backend.env.production" "${env_file}" || return 1
  sync -f "${candidate}" || return 1
  update_artifact_manifest create "${candidate}" "${manifest}" false \
    && update_artifact_manifest verify "${candidate}" "${manifest}" false
}

atomic_install_update_symlink() {
  local target="$1" destination="$2"
  python3 - "${target}" "${destination}" <<'PY2'
import os
import secrets
import stat
import sys

target, destination = sys.argv[1:]
if (
    not target
    or os.path.isabs(target)
    or "/" in target
    or "\0" in target
    or not os.path.isabs(destination)
    or os.path.normpath(destination) != destination
    or destination == os.path.sep
):
    raise SystemExit(1)
parent = os.path.dirname(destination)
name = os.path.basename(destination)
parent_details = os.lstat(parent)
if (
    not stat.S_ISDIR(parent_details.st_mode)
    or stat.S_ISLNK(parent_details.st_mode)
    or parent_details.st_uid != os.geteuid()
    or parent_details.st_gid != os.getegid()
    or parent_details.st_mode & 0o022
):
    raise SystemExit(1)
try:
    current = os.lstat(destination)
except FileNotFoundError:
    current = None
if current is not None and not (
    stat.S_ISREG(current.st_mode) or stat.S_ISLNK(current.st_mode)
):
    raise SystemExit(1)


def fsync_parent():
    descriptor = os.open(
        parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


prefix = f".{name}.update-link."
# A prior hard kill before rename can leave only this bounded temporary
# symlink. The global installer operation lock excludes a concurrent owner.
for candidate_name in os.listdir(parent):
    if not candidate_name.startswith(prefix):
        continue
    candidate = os.path.join(parent, candidate_name)
    details = os.lstat(candidate)
    if (
        not stat.S_ISLNK(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_gid != os.getegid()
        or os.readlink(candidate) != target
    ):
        raise SystemExit(1)
    os.unlink(candidate)
    fsync_parent()

temporary = os.path.join(
    parent, f"{prefix}{os.getpid()}.{secrets.token_hex(8)}"
)
source_only = (
    os.environ.get("BRIDGESLLM_INSTALLER_SOURCE_ONLY") == "1"
    and bool(os.environ.get("BRIDGESLLM_UPDATE_TRANSACTION_TEST_ROOT"))
)
crash_at = (
    os.environ.get("BRIDGESLLM_UPDATE_TRANSACTION_TEST_ENV_LINK_CRASH_AT", "")
    if source_only
    else ""
)
if crash_at not in {"", "before-replace", "after-replace"}:
    raise SystemExit(1)
try:
    os.symlink(target, temporary)
    created = os.lstat(temporary)
    if (
        not stat.S_ISLNK(created.st_mode)
        or created.st_uid != os.geteuid()
        or created.st_gid != os.getegid()
        or os.readlink(temporary) != target
    ):
        raise SystemExit(1)
    fsync_parent()
    if crash_at == "before-replace":
        os._exit(95)
    os.replace(temporary, destination)
    temporary = ""
    installed = os.lstat(destination)
    if (
        not stat.S_ISLNK(installed.st_mode)
        or installed.st_uid != os.geteuid()
        or installed.st_gid != os.getegid()
        or os.readlink(destination) != target
    ):
        raise SystemExit(1)
    if crash_at == "after-replace":
        os._exit(96)
    fsync_parent()
finally:
    if temporary:
        try:
            os.unlink(temporary)
            fsync_parent()
        except FileNotFoundError:
            pass
PY2
}

install_updated_environment_candidate() {
  local backup_dir candidate manifest
  backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
  candidate="${backup_dir}/environment.updated"
  manifest="$(update_transaction_manifest_path active environment-updated)" \
    || return 1
  update_artifact_manifest verify "${candidate}" "${manifest}" false || return 1
  atomic_restore_update_file \
    "${candidate}/backend.env.production" \
    "${PORTAL_DIR}/backend/.env.production" || return 1
  atomic_restore_update_file \
    "${candidate}/frontend.env" \
    "${PORTAL_DIR}/frontend/.env" || return 1
  atomic_install_update_symlink \
    .env.production "${PORTAL_DIR}/backend/.env" || return 1
  local validation_assignment_status=0
  env_file_has_assignment \
    "${PORTAL_DIR}/backend/.env.production" \
    "PORTAL_UPDATE_VALIDATION_MODE" || validation_assignment_status=$?
  [[ "${validation_assignment_status}" -eq 1 ]] || return 1
  update_regular_files_equal \
    "${candidate}/backend.env.production" \
    "${PORTAL_DIR}/backend/.env.production" \
    && update_regular_files_equal \
      "${candidate}/frontend.env" "${PORTAL_DIR}/frontend/.env"
}

overlay_verified_update_runtime() {
  local staged_portal="$1" changes
  [[ -f "${staged_portal}/frontend/dist/index.html" \
    && -f "${staged_portal}/backend/dist/server.js" \
    && -f "${staged_portal}/backend/dist/services/projectEgressPolicy.js" \
    && -f "${staged_portal}/backend/dist/services/projectEgressProxy.js" ]] \
    || return 1
  rsync -aHAX --numeric-ids --delete \
    --exclude='node_modules' \
    --exclude='.git' \
    --exclude='.env' \
    --exclude='.env.production' \
    --exclude='/projects' \
    --exclude='/apps' \
    --exclude='/assets' \
    --exclude='/upload-temp' \
    --exclude='/.data' \
    --exclude='/backend/.data' \
    "${staged_portal}/" "${PORTAL_DIR}/" >> "${LOG_FILE}" 2>&1 || return 1
  sync -f "${PORTAL_DIR}" || return 1
  changes="$(rsync -aHAXnc --numeric-ids --delete --itemize-changes \
    --exclude='node_modules' \
    --exclude='.git' \
    --exclude='.env' \
    --exclude='.env.production' \
    --exclude='/projects' \
    --exclude='/apps' \
    --exclude='/assets' \
    --exclude='/upload-temp' \
    --exclude='/.data' \
    --exclude='/backend/.data' \
    "${staged_portal}/" "${PORTAL_DIR}/" 2>> "${LOG_FILE}")" || return 1
  [[ -z "${changes}" ]]
}

install_prepared_update_dependencies() {
  local staged_portal="$1"
  local source="${staged_portal}/backend/node_modules"
  [[ -d "${source}" && ! -L "${source}" ]] || return 1
  if [[ -e "${PORTAL_DIR}/backend/node_modules" \
    || -L "${PORTAL_DIR}/backend/node_modules" ]]; then
    [[ -d "${PORTAL_DIR}/backend/node_modules" \
      && ! -L "${PORTAL_DIR}/backend/node_modules" ]] || return 1
    rm -rf -- "${PORTAL_DIR}/backend/node_modules"
  fi
  install -d -m 0700 -- "${PORTAL_DIR}/backend/node_modules" || return 1
  rsync -aHAX --numeric-ids --delete \
    "${source}/" "${PORTAL_DIR}/backend/node_modules/" \
    >> "${LOG_FILE}" 2>&1 || return 1
  sync -f "${PORTAL_DIR}/backend/node_modules" || return 1
  (
    cd "${PORTAL_DIR}/backend"
    node -e "for (const name of ['@prisma/client','@prisma/adapter-pg','pg','bcrypt','sharp','node-pty']) require(name)"
  ) >> "${LOG_FILE}" 2>&1 || return 1
  verify_prisma_client_runtime \
    "${PORTAL_DIR}/backend" installed-prisma-check \
    >> "${LOG_FILE}" 2>&1
}

prepare_update_transaction_layout() {
  local transaction_id="$1" stage_dir="$2"
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ ]] || return 1
  local state_root transaction_root backup_root expected_stage_root
  state_root="$(update_transaction_state_path "${UPDATE_STATE_ROOT}")" || return 1
  transaction_root="${state_root}/transactions"
  backup_root="$(update_transaction_state_path "${UPDATE_BACKUP_ROOT}")" || return 1
  expected_stage_root="$(update_transaction_state_path "${UPDATE_STAGE_ROOT}")" \
    || return 1
  python3 - "${transaction_id}" "${state_root}" "${transaction_root}" \
    "${backup_root}" "${expected_stage_root}" "${stage_dir}" <<'PY2'
import os
import stat
import sys

transaction_id, state_root, transaction_root, backup_root, stage_root, stage_dir = sys.argv[1:]
expected_uid = os.geteuid()
expected_gid = os.getegid()
expected = (
    os.path.join(transaction_root, transaction_id),
    os.path.join(backup_root, f"update-{transaction_id}"),
    os.path.join(stage_root, f"update-{transaction_id}"),
)
if stage_dir != expected[2]:
    raise SystemExit(1)


def secure_directory(path: str, *, mode=None) -> None:
    details = os.lstat(path)
    if (
        not stat.S_ISDIR(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != expected_uid
        or details.st_gid != expected_gid
        or details.st_mode & 0o077
    ):
        raise SystemExit(1)
    if mode is not None and stat.S_IMODE(details.st_mode) != mode:
        raise SystemExit(1)


for root in (state_root, stage_root):
    secure_directory(root, mode=0o700)

for root in (transaction_root, backup_root):
    parent = os.path.dirname(root)
    try:
        parent_details = os.lstat(parent)
    except FileNotFoundError:
        grandparent = os.path.dirname(parent)
        grandparent_details = os.lstat(grandparent)
        if (
            not stat.S_ISDIR(grandparent_details.st_mode)
            or stat.S_ISLNK(grandparent_details.st_mode)
            or grandparent_details.st_uid != expected_uid
            or grandparent_details.st_mode & 0o022
        ):
            raise SystemExit(1)
        os.mkdir(parent, 0o700)
        parent_details = os.lstat(parent)
    if (
        not stat.S_ISDIR(parent_details.st_mode)
        or stat.S_ISLNK(parent_details.st_mode)
        or parent_details.st_uid != expected_uid
        or parent_details.st_mode & 0o022
    ):
        raise SystemExit(1)
    try:
        os.mkdir(root, 0o700)
    except FileExistsError:
        pass
    os.chmod(root, 0o700)
    secure_directory(root, mode=0o700)

for leaf in expected[:2]:
    try:
        os.mkdir(leaf, 0o700)
    except FileExistsError:
        raise SystemExit(1)
    secure_directory(leaf, mode=0o700)
secure_directory(expected[2], mode=0o700)

for directory in (*expected, transaction_root, backup_root, stage_root, state_root):
    descriptor = os.open(
        directory,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
PY2
}

prepare_update_transaction() {
  local previous_version="$1" staged_portal="$2"
  local transaction_id="${3:-${UPDATE_TRANSACTION_ID}}"
  local -a database_topology_pin=()
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ ]] || return 1
  mapfile -t database_topology_pin < <(
    read_update_disk_reserve_database_topology "${transaction_id}"
  ) || return 1
  [[ "${#database_topology_pin[@]}" -eq 3 ]] || return 1
  install_update_transaction_state_helper "${staged_portal}" || return 1
  prepare_update_transaction_layout \
    "${transaction_id}" "$(dirname "${staged_portal}")" || return 1

  local node_modules_preexisted=false deploy_stamp_preexisted=false
  local caddy_snapshot_required=false repair_reinstall=false
  local openclaw_package_preexisted=false openclaw_package_version=""
  local openclaw_runtime_version="" openclaw_state_preexisted=false
  local openclaw_gateway_was_active=false openclaw_gateway_was_enabled=false
  local openclaw_codex_plugin_preexisted=false openclaw_codex_plugin_version=""

  [[ -d "${PORTAL_DIR}/backend/node_modules" \
    && ! -L "${PORTAL_DIR}/backend/node_modules" ]] \
    && node_modules_preexisted=true
  [[ -f "${PORTAL_DEPLOY_STAMP}" && ! -L "${PORTAL_DEPLOY_STAMP}" ]] \
    && deploy_stamp_preexisted=true
  if ! use_local_profile && ! use_tailnet_profile; then
    caddy_snapshot_required=true
  fi
  ${REPAIR_REINSTALL:-false} && repair_reinstall=true
  if command -v openclaw >/dev/null 2>&1; then
    openclaw_package_preexisted=true
    openclaw_package_version="$(openclaw_core_package_version || true)"
    openclaw_runtime_version="$(openclaw_cli_version || true)"
    [[ -n "${openclaw_package_version}" && -n "${openclaw_runtime_version}" ]] \
      || return 1
    local plugin_details=""
    if plugin_details="$(openclaw_codex_plugin_details 2>/dev/null)"; then
      openclaw_codex_plugin_preexisted=true
      openclaw_codex_plugin_version="$(head -1 <<<"${plugin_details}")"
      [[ -n "${openclaw_codex_plugin_version}" ]] || return 1
    else
      local plugin_status=$?
      [[ "${plugin_status}" -eq 2 ]] || return 1
    fi
  fi
  openclaw_installation_state_present "${HOME}/.openclaw" \
    && openclaw_state_preexisted=true
  systemctl is-active --quiet openclaw-gateway && openclaw_gateway_was_active=true
  systemctl is-enabled openclaw-gateway >/dev/null 2>&1 \
    && openclaw_gateway_was_enabled=true

  local -a command=(
    create
    --transaction-id "${transaction_id}"
    --previous-version "${previous_version}"
    --target-version "${VERSION}"
    --release-artifact-sha256 "${VERIFIED_RELEASE_ARTIFACT_SHA256}"
    --release-manifest-sha256 "${VERIFIED_RELEASE_MANIFEST_SHA256}"
    --database-system-identifier "${database_topology_pin[0]}"
    --database-topology-sha256 "${database_topology_pin[1]}"
    --previous-main-pid "${UPDATE_TRANSACTION_BASELINE_PID}"
    --baseline-boot-id "${UPDATE_TRANSACTION_BASELINE_BOOT_ID}"
    --previous-main-start-time "${UPDATE_TRANSACTION_BASELINE_START_TIME}"
    --portal-was-active "${UPDATE_TRANSACTION_PORTAL_WAS_ACTIVE}"
    --portal-was-enabled "${UPDATE_TRANSACTION_PORTAL_WAS_ENABLED}"
    --deploy-stamp-preexisted "${deploy_stamp_preexisted}"
    --caddy-snapshot-required "${caddy_snapshot_required}"
    --node-modules-preexisted "${node_modules_preexisted}"
    --repair-reinstall "${repair_reinstall}"
    --openclaw-package-preexisted "${openclaw_package_preexisted}"
    --openclaw-state-preexisted "${openclaw_state_preexisted}"
    --openclaw-gateway-was-active "${openclaw_gateway_was_active}"
    --openclaw-gateway-was-enabled "${openclaw_gateway_was_enabled}"
    --openclaw-codex-plugin-preexisted "${openclaw_codex_plugin_preexisted}"
  )
  [[ -z "${openclaw_package_version}" ]] \
    || command+=(--openclaw-package-version "${openclaw_package_version}")
  [[ -z "${openclaw_runtime_version}" ]] \
    || command+=(--openclaw-runtime-version "${openclaw_runtime_version}")
  [[ -z "${openclaw_codex_plugin_version}" ]] \
    || command+=(--openclaw-codex-plugin-version "${openclaw_codex_plugin_version}")
  # Install both permanent ConditionPathExists boundaries while no receipt
  # exists. The OpenClaw fence marker is managed only by the Portal's
  # authorization-transition coordinator; update/repair must never clear it.
  install_openclaw_gateway_authorization_fence_dropin || return 1
  # Publishing the active update receipt then becomes the Portal boot-fence
  # decision.
  install_portal_update_boot_fence || return 1
  run_update_transaction_state_helper "${command[@]}" >/dev/null || return 1
  # From receipt publication onward, every failure path must use the durable
  # recovery engine and must preserve the stage/backup directories it names.
  UPDATE_RECOVERY_ARMED=true

  UPDATE_TRANSACTION_ID="${transaction_id}"
  UPDATE_TRANSACTION_GENERATION="$(
    read_update_transaction_field active generation
  )" || return 1
  UPDATE_RECOVERY_BACKUP_DIR="$(
    read_update_transaction_field active backup_dir
  )" || return 1
  UPDATE_RELEASE_STAGE_DIR="$(
    read_update_transaction_field active stage_dir
  )" || return 1
  UPDATE_TRANSACTION_PREVIOUS_VERSION="${previous_version}"
  UPDATE_TRANSACTION_TARGET_VERSION="${VERSION}"
}

dashboard_update_progress_for_transaction_phase() {
  local phase="$1"
  case "${phase}" in
    boot_blocked)
      dashboard_update_progress running 42 portal-transaction \
        "Opening protected update transaction" \
        "Step 7 of 13 · Portal boot is fenced before any live runtime mutation."
      ;;
    portal_quiesced)
      dashboard_update_progress running 46 portal-quiesced \
        "Portal stopped safely" \
        "Step 7 of 13 · The existing Portal is quiesced and the rollback boundary is active."
      ;;
    runtime_snapshot_complete)
      dashboard_update_progress running 50 rollback-snapshots \
        "Taking recovery snapshots" \
        "Step 8 of 13 · Runtime and environment recovery copies are sealed."
      ;;
    database_snapshot_complete)
      dashboard_update_progress running 52 rollback-snapshots \
        "Taking recovery snapshots" \
        "Step 8 of 13 · The database recovery snapshot is verified."
      ;;
    node_modules_moved)
      dashboard_update_progress running 55 rollback-snapshots \
        "Recovery snapshots complete" \
        "Step 8 of 13 · Runtime, database, routing, and dependency recovery points are sealed."
      ;;
    runtime_overlaid)
      dashboard_update_progress running 62 runtime-install \
        "Installing signed Portal runtime" \
        "Step 9 of 13 · Signed runtime files were promoted; environment and database work follows."
      ;;
    dependencies_updated)
      dashboard_update_progress running 66 runtime-install \
        "Installing signed Portal runtime" \
        "Step 9 of 13 · Preverified backend dependencies were promoted."
      ;;
    database_migrated)
      dashboard_update_progress running 70 database-migration \
        "Portal runtime and database installed" \
        "Step 9 of 13 · Database migrations completed inside the rollback transaction."
      ;;
    candidate_started)
      dashboard_update_progress running 76 candidate-verification \
        "Starting private candidate" \
        "Step 10 of 13 · The signed Portal is running on a private validation port."
      ;;
    candidate_verified)
      dashboard_update_progress running 82 candidate-verification \
        "Private candidate verified" \
        "Step 10 of 13 · Exact version, schema, and mutation-free readiness checks passed."
      ;;
    provenance_committed)
      dashboard_update_progress running 86 cutover-preparation \
        "Preparing verified cutover" \
        "Step 11 of 13 · Signed release provenance is committed."
      ;;
    canonical_started)
      dashboard_update_progress running 91 portal-restarting \
        "Updated Portal is restarting" \
        "Step 12 of 13 · Reconnecting automatically while the canonical service starts."
      ;;
    canonical_verified)
      dashboard_update_progress running 93 portal-restarting \
        "Updated Portal verified" \
        "Step 12 of 13 · The canonical service passed exact-version and readiness checks."
      ;;
    boot_state_restored)
      dashboard_update_progress running 94 portal-restarting \
        "Restoring Portal service state" \
        "Step 12 of 13 · The prior enablement policy is restored before commit."
      ;;
    committed)
      DASHBOARD_UPDATE_PORTAL_COMMITTED=true
      dashboard_update_progress running 95 portal-committed \
        "Updated Portal is online" \
        "Step 12 of 13 · The signed Portal is durably committed; transaction cleanup and host integration remain."
      ;;
    recovery_pending|recovery_quiesce_pending)
      dashboard_update_progress recovering \
        "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
        "Preparing automatic recovery" \
        "The updater is preserving the recovery boundary and stopping partial runtime state."
      ;;
    recovery_quiesced)
      dashboard_update_progress recovering \
        "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
        "Portal stopped for recovery" \
        "The previous runtime, database, routing, and dependencies can now be restored safely."
      ;;
    recovery_database_restored)
      dashboard_update_progress recovering \
        "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
        "Database recovery verified" \
        "The pre-update database snapshot has been restored and attested."
      ;;
    recovery_runtime_restored)
      dashboard_update_progress recovering \
        "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
        "Previous Portal files restored" \
        "The pre-update runtime and environment are back in place."
      ;;
    recovery_dependencies_restored)
      dashboard_update_progress recovering \
        "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
        "Previous dependencies restored" \
        "The exact pre-update backend dependencies are back in place."
      ;;
    recovery_service_restored|recovery_verify_pending)
      dashboard_update_progress recovering \
        "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" recovery \
        "Verifying restored Portal" \
        "The previous Portal is restarting for exact-version and health verification."
      ;;
    recovered)
      dashboard_update_progress rolled_back \
        "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" rolled-back \
        "Previous Portal restored" \
        "The previous Portal was restored, restarted, and verified after the update stopped."
      ;;
  esac
}

advance_update_transaction_phase() {
  local target="$1" expected_phase="$2" next_phase="$3"
  local generation transaction_id
  transaction_id="$(read_update_transaction_field "${target}" transaction_id)" \
    || return 1
  generation="$(read_update_transaction_field "${target}" generation)" \
    || return 1
  run_update_transaction_state_helper update \
    --target "${target}" \
    --transaction-id "${transaction_id}" \
    --expected-generation "${generation}" \
    --expected-phase "${expected_phase}" \
    --phase "${next_phase}" >/dev/null || return 1
  UPDATE_TRANSACTION_ID="${transaction_id}"
  UPDATE_TRANSACTION_GENERATION="$((generation + 1))"
  dashboard_update_progress_for_transaction_phase "${next_phase}"
}

cutover_update_transaction() {
  local expected_phase="${1:-cutover_pending}"
  local generation transaction_id
  transaction_id="$(read_update_transaction_field active transaction_id)" || return 1
  generation="$(read_update_transaction_field active generation)" || return 1
  run_update_transaction_state_helper cutover \
    --transaction-id "${transaction_id}" \
    --expected-generation "${generation}" \
    --expected-phase "${expected_phase}" >/dev/null || return 1
  UPDATE_TRANSACTION_ID="${transaction_id}"
  UPDATE_TRANSACTION_GENERATION="${generation}"
}

finish_update_transaction() {
  local target="$1" terminal_phase="$2"
  local generation transaction_id
  transaction_id="$(read_update_transaction_field "${target}" transaction_id)" \
    || return 1
  generation="$(read_update_transaction_field "${target}" generation)" || return 1
  run_update_transaction_state_helper remove \
    --target "${target}" \
    --transaction-id "${transaction_id}" \
    --expected-generation "${generation}" \
    --expected-phase "${terminal_phase}" >/dev/null || return 1
  UPDATE_RECOVERY_ARMED=false
  UPDATE_TRANSACTION_ID=""
  UPDATE_TRANSACTION_GENERATION=""
  UPDATE_TRANSACTION_PREVIOUS_VERSION=""
  UPDATE_TRANSACTION_TARGET_VERSION=""
}

arm_update_transaction_traps() {
  trap 'handle_update_transaction_err $?' ERR
  trap 'handle_sigint' SIGINT
  trap 'handle_sigterm' TERM
  trap 'handle_sighup' HUP
}

update_forward_phase_rank() {
  case "$1" in
    prepared) echo 0 ;;
    boot_block_pending) echo 1 ;;
    boot_blocked) echo 2 ;;
    portal_quiesce_pending) echo 3 ;;
    portal_quiesced) echo 4 ;;
    runtime_snapshot_pending) echo 5 ;;
    runtime_snapshot_complete) echo 6 ;;
    database_snapshot_pending) echo 7 ;;
    database_snapshot_complete) echo 8 ;;
    caddy_snapshot_pending) echo 9 ;;
    caddy_snapshot_complete) echo 10 ;;
    openclaw_snapshot_pending) echo 11 ;;
    openclaw_snapshot_complete) echo 12 ;;
    node_modules_move_pending) echo 13 ;;
    node_modules_moved) echo 14 ;;
    runtime_overlay_pending) echo 15 ;;
    runtime_overlaid) echo 16 ;;
    environment_update_pending) echo 17 ;;
    environment_updated) echo 18 ;;
    caddy_update_pending) echo 19 ;;
    caddy_updated) echo 20 ;;
    dependencies_update_pending) echo 21 ;;
    dependencies_updated) echo 22 ;;
    database_migration_pending) echo 23 ;;
    database_migrated) echo 24 ;;
    openclaw_update_pending) echo 25 ;;
    openclaw_updated) echo 26 ;;
    candidate_start_pending) echo 27 ;;
    candidate_started) echo 28 ;;
    candidate_verification_pending) echo 29 ;;
    candidate_verified) echo 30 ;;
    provenance_commit_pending) echo 31 ;;
    provenance_committed) echo 32 ;;
    cutover_pending) echo 33 ;;
    canonical_start_pending) echo 34 ;;
    canonical_started) echo 35 ;;
    canonical_verification_pending) echo 36 ;;
    canonical_verified) echo 37 ;;
    boot_state_restore_pending) echo 38 ;;
    boot_state_restored) echo 39 ;;
    committed) echo 40 ;;
    *) return 1 ;;
  esac
}

update_recovery_reached_phase() {
  local threshold="$1" recovery_from from_rank threshold_rank
  recovery_from="$(read_update_transaction_field active recovery_from_phase)" \
    || return 1
  [[ -n "${recovery_from}" ]] || return 1
  from_rank="$(update_forward_phase_rank "${recovery_from}")" || return 1
  threshold_rank="$(update_forward_phase_rank "${threshold}")" || return 1
  (( from_rank >= threshold_rank ))
}

current_update_receipt_target() {
  local active_journal cutover_journal target=""
  active_journal="$(update_transaction_state_path "${UPDATE_ACTIVE_JOURNAL}")" \
    || return 1
  cutover_journal="$(update_transaction_state_path "${UPDATE_CUTOVER_JOURNAL}")" \
    || return 1
  if [[ -e "${active_journal}" || -L "${active_journal}" ]]; then
    [[ ! -e "${cutover_journal}" && ! -L "${cutover_journal}" ]] || return 1
    target=active
  elif [[ -e "${cutover_journal}" || -L "${cutover_journal}" ]]; then
    target=cutover
  else
    return 1
  fi
  # `read` validates the entire receipt schema, metadata, generation, bounded
  # paths, artifact identities, and phase contract before returning any field.
  read_update_transaction_field "${target}" transaction_id >/dev/null \
    || return 1
  printf '%s\n' "${target}"
}

load_update_origin_from_environment() {
  local env_file="$1"
  local profile origin domain tailnet_name app_domain app_origin app_mode
  [[ -f "${env_file}" && ! -L "${env_file}" ]] || return 1
  profile="$(read_env_value "${env_file}" "INSTALL_PROFILE" || true)"
  origin="$(read_env_value "${env_file}" "ORIGIN_MODE" || true)"
  domain="$(read_env_value "${env_file}" "DOMAIN" || true)"
  tailnet_name="$(read_env_value "${env_file}" "TAILNET_DNS_NAME" || true)"
  app_domain="$(read_env_value "${env_file}" "APP_CONTENT_DOMAIN" || true)"
  app_origin="$(read_env_value "${env_file}" "APP_CONTENT_ORIGIN" || true)"
  app_mode="$(read_env_value "${env_file}" "APP_CONTENT_DNS_MODE" || true)"

  case "${profile}" in
    ""|server) profile="server" ;;
    local) ;;
    *) return 1 ;;
  esac
  case "${origin}" in
    "") ;;
    tailnet) ;;
    *) return 1 ;;
  esac
  [[ ! ( "${profile}" == "local" && "${origin}" == "tailnet" ) ]] || return 1

  if [[ "${profile}" == "local" || "${origin}" == "tailnet" ]]; then
    [[ -z "${domain}" ]] || return 1
  else
    domain="$(
      python3 - "${domain}" <<'PY2'
import re
import sys

value = sys.argv[1].strip().lower().rstrip(".")
labels = value.split(".")
valid = (
    1 <= len(value) <= 253
    and len(labels) >= 2
    and all(
        1 <= len(label) <= 63
        and re.fullmatch(r"[a-z0-9](?:[a-z0-9-]*[a-z0-9])?", label)
        for label in labels
    )
)
if not valid:
    raise SystemExit(1)
print(value)
PY2
    )" || return 1
  fi

  if [[ "${origin}" == "tailnet" ]]; then
    tailnet_name="$(
      python3 - "${tailnet_name}" <<'PY2'
import re
import sys

value = sys.argv[1].strip().lower().rstrip(".")
labels = value.split(".")
if (
    not value.endswith(".ts.net")
    or len(value) > 253
    or not all(
        1 <= len(label) <= 63
        and re.fullmatch(r"[a-z0-9](?:[a-z0-9-]*[a-z0-9])?", label)
        for label in labels
    )
):
    raise SystemExit(1)
print(value)
PY2
    )" || return 1
  else
    tailnet_name=""
  fi

  if [[ "${profile}" == "server" && -z "${origin}" ]]; then
    if [[ -z "${app_domain}" ]]; then
      app_domain="$(app_content_domain_from_origin "${app_origin}" || true)"
    fi
    if [[ -n "${app_domain}" ]]; then
      app_domain="$(
        python3 - "${app_domain}" <<'PY2'
import re
import sys

value = sys.argv[1].strip().lower().rstrip(".")
labels = value.split(".")
if (
    len(value) > 253
    or len(labels) < 2
    or not all(
        1 <= len(label) <= 63
        and re.fullmatch(r"[a-z0-9](?:[a-z0-9-]*[a-z0-9])?", label)
        for label in labels
    )
):
    raise SystemExit(1)
print(value)
PY2
      )" || return 1
    fi
    case "${app_mode}" in
      ""|custom|sslip) ;;
      *) return 1 ;;
    esac
  else
    app_domain=""
  fi

  INSTALL_PROFILE="${profile}"
  ORIGIN_MODE="${origin}"
  DOMAIN="${domain}"
  TAILNET_DNS_NAME="${tailnet_name}"
  APP_CONTENT_DOMAIN="${app_domain}"
  APP_CONTENT_DNS_MODE="${app_mode}"
}

load_update_transaction_context() {
  local target="$1"
  UPDATE_TRANSACTION_ID="$(
    read_update_transaction_field "${target}" transaction_id
  )" || return 1
  UPDATE_TRANSACTION_GENERATION="$(
    read_update_transaction_field "${target}" generation
  )" || return 1
  UPDATE_TRANSACTION_PREVIOUS_VERSION="$(
    read_update_transaction_field "${target}" previous_version
  )" || return 1
  UPDATE_TRANSACTION_TARGET_VERSION="$(
    read_update_transaction_field "${target}" target_version
  )" || return 1
  UPDATE_TRANSACTION_BASELINE_PID="$(
    read_update_transaction_field "${target}" previous_main_pid
  )" || return 1
  UPDATE_TRANSACTION_BASELINE_BOOT_ID="$(
    read_update_transaction_field "${target}" baseline_boot_id
  )" || return 1
  UPDATE_TRANSACTION_BASELINE_START_TIME="$(
    read_update_transaction_field "${target}" previous_main_start_time
  )" || return 1
  UPDATE_TRANSACTION_PORTAL_WAS_ACTIVE="$(
    read_update_transaction_field "${target}" portal_was_active
  )" || return 1
  UPDATE_TRANSACTION_PORTAL_WAS_ENABLED="$(
    read_update_transaction_field "${target}" portal_was_enabled
  )" || return 1
  UPDATE_RECOVERY_BACKUP_DIR="$(
    read_update_transaction_field "${target}" backup_dir
  )" || return 1
  UPDATE_RELEASE_STAGE_DIR="$(
    read_update_transaction_field "${target}" stage_dir
  )" || return 1
  [[ "${UPDATE_TRANSACTION_ID}" =~ ^[a-f0-9]{32}$ \
    && "${UPDATE_TRANSACTION_GENERATION}" =~ ^[1-9][0-9]*$ \
    && "${UPDATE_TRANSACTION_PREVIOUS_VERSION}" =~ ^[0-9]+\.[0-9]+\.[0-9]+ \
    && "${UPDATE_TRANSACTION_TARGET_VERSION}" =~ ^[0-9]+\.[0-9]+\.[0-9]+ \
    && "${UPDATE_TRANSACTION_BASELINE_PID}" =~ ^[0-9]+$ \
    && "${UPDATE_TRANSACTION_PORTAL_WAS_ACTIVE}" =~ ^(true|false)$ \
    && "${UPDATE_TRANSACTION_PORTAL_WAS_ENABLED}" =~ ^(true|false)$ ]] || return 1
  UPDATE_RECOVERY_ARMED=true
}

reopen_cutover_update_transaction() {
  local phase generation transaction_id
  transaction_id="$(read_update_transaction_field cutover transaction_id)" \
    || return 1
  generation="$(read_update_transaction_field cutover generation)" || return 1
  phase="$(read_update_transaction_field cutover phase)" || return 1
  run_update_transaction_state_helper reopen \
    --transaction-id "${transaction_id}" \
    --expected-generation "${generation}" \
    --expected-phase "${phase}" >/dev/null || return 1
  UPDATE_TRANSACTION_ID="${transaction_id}"
  UPDATE_TRANSACTION_GENERATION="$((generation + 1))"
}

remove_update_transaction_artifacts() {
  local mode="$1" transaction_id="$2" backup_dir="$3" stage_dir="$4" transaction_dir="$5"
  local test_root=""
  test_root="$(update_transaction_test_root 2>/dev/null || true)"
  python3 - "${mode}" "${transaction_id}" "${backup_dir}" "${stage_dir}" \
    "${transaction_dir}" "${test_root}" <<'PY2'
import os
import shutil
import stat
import sys

mode, transaction_id, backup_dir, stage_dir, transaction_dir, test_root = sys.argv[1:]
prefix = test_root if test_root else os.path.sep
expected = (
    os.path.join(prefix, "opt/bridgesllm/backups/update-transactions", f"update-{transaction_id}"),
    os.path.join(prefix, "opt/bridgesllm/update-staging", f"update-{transaction_id}"),
    os.path.join(prefix, "var/lib/bridgesllm-installer/transactions", transaction_id),
)
provided = (backup_dir, stage_dir, transaction_dir)
if provided != expected:
    raise SystemExit(1)
# The secret-bearing payload (backup snapshots, staged release) must be
# removable while the terminal receipt still exists, so a crash mid-cleanup
# always leaves an authoritative receipt pointing at idempotent work. The
# journal directory holds only manifests and helpers and is removed last.
if mode == "payload":
    selected = provided[:2]
elif mode == "journal":
    selected = provided[2:]
else:
    raise SystemExit(1)
expected_uid = os.geteuid()
for path in selected:
    try:
        details = os.lstat(path)
    except FileNotFoundError:
        continue
    if (
        not stat.S_ISDIR(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != expected_uid
        or details.st_mode & 0o077
    ):
        raise SystemExit(1)
for path in selected:
    try:
        shutil.rmtree(path)
    except FileNotFoundError:
        pass
    parent = os.path.dirname(path)
    descriptor = os.open(
        parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)
PY2
}

complete_update_transaction() {
  local target="$1" terminal_phase="$2"
  local transaction_id backup_dir stage_dir transaction_dir cleanup_policy
  transaction_id="$(read_update_transaction_field "${target}" transaction_id)" \
    || return 1
  backup_dir="$(read_update_transaction_field "${target}" backup_dir)" || return 1
  stage_dir="$(read_update_transaction_field "${target}" stage_dir)" || return 1
  transaction_dir="$(read_update_transaction_field "${target}" transaction_dir)" \
    || return 1
  # Once canonical verification reaches a terminal receipt, the preallocated
  # emergency blocks are no longer needed. Release them while the receipt
  # still exists so a crash leaves an idempotent, authoritative cleanup path.
  # A crash after payload removal but before receipt removal intentionally
  # leaves no staged runtime-policy evidence. Dual payload absence is itself
  # the durable replay boundary: the removal below can run only after runtime
  # tags were cleaned successfully. Do not require Docker again on that exact
  # terminal replay; the authoritative receipt and journal still remain.
  if [[ -e "${backup_dir}" || -L "${backup_dir}" \
    || -e "${stage_dir}" || -L "${stage_dir}" ]]; then
    cleanup_policy="$(
      update_project_runtime_cleanup_policy_for_target "${target}" \
        2>/dev/null || true
    )"
    cleanup_prepared_update_project_runtime_tags \
      "${transaction_id}" "${cleanup_policy}" || return 1
  fi
  release_update_disk_reserves || return 1
  # Order is load-bearing: secret-bearing payload first (receipt retains
  # recovery authority over a crash here), then the receipt, then the
  # secret-free journal directory.
  remove_update_transaction_artifacts payload \
    "${transaction_id}" "${backup_dir}" "${stage_dir}" "${transaction_dir}" \
    || return 1
  finish_update_transaction "${target}" "${terminal_phase}" || return 1
  remove_update_transaction_artifacts journal \
    "${transaction_id}" "${backup_dir}" "${stage_dir}" "${transaction_dir}" \
    || return 1
  if [[ "${terminal_phase}" == "recovered" ]]; then
    dashboard_update_progress rolled_back \
      "${DASHBOARD_UPDATE_PROGRESS_PERCENT}" rolled-back \
      "Previous Portal restored" \
      "The previous Portal was restored, restarted, and verified after the update stopped."
  elif [[ "${terminal_phase}" == "committed" ]]; then
    DASHBOARD_UPDATE_PORTAL_COMMITTED=true
    dashboard_update_progress running 95 portal-committed \
      "Updated Portal is online" \
      "Step 12 of 13 · The signed Portal is committed; final host integration is still running."
  fi
}

complete_committed_update_transaction() {
  # `committed` is the first phase from which rollback to the prior Portal is
  # impossible. Promote the already pinned immutable IDs now, never while an
  # old environment might still be restored. Replays are idempotent because
  # the same receipt and image IDs remain authoritative until cleanup finishes.
  promote_prepared_update_project_runtime_images cutover \
    && complete_update_transaction cutover committed
}

refence_cutover_recovery() {
  reopen_cutover_update_transaction || return 1
  install_portal_update_boot_fence || return 1
  quiesce_portal_service "bridgesllm-product" 20 10 4001
}

finish_forward_cutover_transaction() {
  load_update_transaction_context cutover || return 1
  load_update_origin_from_environment \
    "${PORTAL_DIR}/backend/.env.production" || return 1
  local phase probe_token validation_assignment_status
  while true; do
    phase="$(read_update_transaction_field cutover phase)" || return 1
    case "${phase}" in
      cutover_pending)
        stop_update_candidate "${UPDATE_TRANSACTION_ID}" "${UPDATE_CANDIDATE_PORT}" \
          || { refence_cutover_recovery || true; return 1; }
        advance_update_transaction_phase \
          cutover cutover_pending canonical_start_pending || return 1
        ;;
      canonical_start_pending)
        if ! start_canonical_portal_for_transaction; then
          refence_cutover_recovery || true
          return 1
        fi
        advance_update_transaction_phase \
          cutover canonical_start_pending canonical_started || return 1
        ;;
      canonical_started)
        advance_update_transaction_phase \
          cutover canonical_started canonical_verification_pending || return 1
        ;;
      canonical_verification_pending)
        probe_token="$(read_env_value \
          "${PORTAL_DIR}/backend/.env.production" \
          "PORTAL_UPDATE_PROBE_TOKEN" || true)"
        validation_assignment_status=0
        env_file_has_assignment \
          "${PORTAL_DIR}/backend/.env.production" \
          "PORTAL_UPDATE_VALIDATION_MODE" \
          || validation_assignment_status=$?
        if [[ -z "${probe_token}" ]] \
          || [[ "${validation_assignment_status}" -ne 1 ]] \
          || ! verify_canonical_portal_for_transaction \
            "${UPDATE_TRANSACTION_TARGET_VERSION}" "${probe_token}"; then
          refence_cutover_recovery || true
          return 1
        fi
        advance_update_transaction_phase \
          cutover canonical_verification_pending canonical_verified || return 1
        ;;
      canonical_verified)
        advance_update_transaction_phase \
          cutover canonical_verified boot_state_restore_pending || return 1
        ;;
      boot_state_restore_pending)
        if ! restore_portal_service_boot_state "bridgesllm-product"; then
          refence_cutover_recovery || true
          return 1
        fi
        advance_update_transaction_phase \
          cutover boot_state_restore_pending boot_state_restored || return 1
        ;;
      boot_state_restored)
        advance_update_transaction_phase \
          cutover boot_state_restored committed || return 1
        ;;
      committed)
        complete_committed_update_transaction
        return
        ;;
      *)
        return 1
        ;;
    esac
  done
}

recover_active_update_transaction() {
  load_update_transaction_context active || return 1
  local phase recovery_from probe_token db_url backup_dir manifest contract_variant
  while true; do
    phase="$(read_update_transaction_field active phase 2>/dev/null || true)"
    if [[ -z "${phase}" ]]; then
      # Recovery cutover phases deliberately move the receipt out of the boot
      # fence. Continue from that exact cutover receipt.
      phase="$(read_update_transaction_field cutover phase)" || return 1
      case "${phase}" in
        recovery_cutover_pending|recovery_service_restore_pending|recovery_service_restored|recovery_verify_pending|recovered)
          ;;
        *) return 1 ;;
      esac
    fi
    case "${phase}" in
      recovery_pending)
        advance_update_transaction_phase \
          active recovery_pending recovery_quiesce_pending || return 1
        ;;
      recovery_quiesce_pending)
        stop_update_candidate "${UPDATE_TRANSACTION_ID}" "${UPDATE_CANDIDATE_PORT}" \
          || return 1
        quiesce_portal_service "bridgesllm-product" 45 15 4001 || return 1
        advance_update_transaction_phase \
          active recovery_quiesce_pending recovery_quiesced || return 1
        ;;
      recovery_quiesced)
        if update_recovery_reached_phase portal_quiesce_pending; then
          local app_intent_env="${PORTAL_DIR}/backend/.env.production"
          if update_recovery_reached_phase runtime_snapshot_complete; then
            backup_dir="$(read_update_transaction_field active backup_dir)" \
              || return 1
            app_intent_env="${backup_dir}/environment/backend.env.production"
          fi
          db_url="$(read_env_value \
            "${app_intent_env}" DATABASE_URL || true)"
          [[ -n "${db_url}" ]] || return 1
          reconcile_update_running_app_intent active "${db_url}" || return 1
        fi
        advance_update_transaction_phase \
          active recovery_quiesced recovery_openclaw_restore_pending || return 1
        ;;
      recovery_openclaw_restore_pending)
        # Global OpenClaw/tool convergence is intentionally post-commit. These
        # journal phases are a proven no-op kept for schema compatibility.
        advance_update_transaction_phase \
          active recovery_openclaw_restore_pending recovery_openclaw_restored \
          || return 1
        ;;
      recovery_openclaw_restored)
        advance_update_transaction_phase \
          active recovery_openclaw_restored recovery_database_restore_pending \
          || return 1
        ;;
      recovery_database_restore_pending)
        if update_recovery_reached_phase database_migration_pending; then
          backup_dir="$(read_update_transaction_field active backup_dir)" || return 1
          manifest="$(update_transaction_manifest_path active database)" || return 1
          update_artifact_manifest verify \
            "${backup_dir}/database-before-update.dump" "${manifest}" false \
            || return 1
          contract_variant="$(
            read_update_database_contract_snapshot active "${backup_dir}"
          )" || return 1
          db_url="$(read_env_value \
            "${backup_dir}/environment/backend.env.production" \
            "DATABASE_URL" || true)"
          [[ -n "${db_url}" ]] || return 1
          UPDATE_RECOVERY_DATABASE_URL="${db_url}"
          UPDATE_RECOVERY_DATABASE_DUMP="${backup_dir}/database-before-update.dump"
          UPDATE_RECOVERY_DATABASE_CONTRACT_VARIANT="${contract_variant}"
          restore_database_after_failed_update || return 1
        fi
        advance_update_transaction_phase \
          active recovery_database_restore_pending recovery_database_restored \
          || return 1
        ;;
      recovery_database_restored)
        advance_update_transaction_phase \
          active recovery_database_restored recovery_caddy_restore_pending \
          || return 1
        ;;
      recovery_caddy_restore_pending)
        if update_recovery_reached_phase caddy_update_pending; then
          restore_update_caddy_snapshot || return 1
        fi
        advance_update_transaction_phase \
          active recovery_caddy_restore_pending recovery_caddy_restored \
          || return 1
        ;;
      recovery_caddy_restored)
        advance_update_transaction_phase \
          active recovery_caddy_restored recovery_environment_restore_pending \
          || return 1
        ;;
      recovery_environment_restore_pending)
        if update_recovery_reached_phase environment_update_pending; then
          restore_update_environment_snapshot || return 1
        fi
        advance_update_transaction_phase \
          active recovery_environment_restore_pending recovery_environment_restored \
          || return 1
        ;;
      recovery_environment_restored)
        load_update_origin_from_environment \
          "${PORTAL_DIR}/backend/.env.production" || return 1
        advance_update_transaction_phase \
          active recovery_environment_restored recovery_runtime_restore_pending \
          || return 1
        ;;
      recovery_runtime_restore_pending)
        if update_recovery_reached_phase runtime_overlay_pending; then
          restore_update_runtime_snapshot || return 1
        fi
        advance_update_transaction_phase \
          active recovery_runtime_restore_pending recovery_runtime_restored \
          || return 1
        ;;
      recovery_runtime_restored)
        advance_update_transaction_phase \
          active recovery_runtime_restored recovery_dependencies_restore_pending \
          || return 1
        ;;
      recovery_dependencies_restore_pending)
        if update_recovery_reached_phase dependencies_update_pending; then
          restore_update_dependencies_snapshot || return 1
        fi
        advance_update_transaction_phase \
          active recovery_dependencies_restore_pending recovery_dependencies_restored \
          || return 1
        ;;
      recovery_dependencies_restored)
        advance_update_transaction_phase \
          active recovery_dependencies_restored recovery_provenance_restore_pending \
          || return 1
        ;;
      recovery_provenance_restore_pending)
        if update_recovery_reached_phase provenance_commit_pending; then
          restore_update_provenance_snapshot || return 1
        fi
        load_update_origin_from_environment \
          "${PORTAL_DIR}/backend/.env.production" || return 1
        probe_token="$(read_env_value \
          "${PORTAL_DIR}/backend/.env.production" \
          "PORTAL_UPDATE_PROBE_TOKEN" || true)"
        if portal_runtime_supports_update_validation_contract "${PORTAL_DIR}"; then
          [[ -n "${probe_token}" ]] || return 1
          start_update_candidate \
            "${UPDATE_TRANSACTION_ID}" "${UPDATE_CANDIDATE_PORT}" || return 1
          verify_portal_update_readiness \
            "${UPDATE_TRANSACTION_PREVIOUS_VERSION}" "${probe_token}" 900 \
            "$(update_candidate_unit_name "${UPDATE_TRANSACTION_ID}")" \
            "http://127.0.0.1:${UPDATE_CANDIDATE_PORT}/health/update-ready" candidate \
            || return 1
          stop_update_candidate \
            "${UPDATE_TRANSACTION_ID}" "${UPDATE_CANDIDATE_PORT}" || return 1
        else
          # Public 3.x and the immediately preceding 4.0 runtime predate the
          # immutable validation-protocol marker. Never boot those runtimes as
          # a second private Portal: attest the restored bytes now, then start
          # the canonical service exactly once below. A token-bearing legacy
          # 4.x endpoint is verified in explicit legacy-canonical mode, where
          # the updateValidation fields must be absent rather than false.
          [[ "${UPDATE_TRANSACTION_PREVIOUS_VERSION}" == 3.* \
            || "${UPDATE_TRANSACTION_PREVIOUS_VERSION}" == 4.* ]] || return 1
          [[ "$(attest_existing_portal_for_update "${PORTAL_DIR}")" \
            == "${UPDATE_TRANSACTION_PREVIOUS_VERSION}" ]] || return 1
        fi
        advance_update_transaction_phase \
          active recovery_provenance_restore_pending recovery_provenance_restored \
          || return 1
        ;;
      recovery_provenance_restored)
        advance_update_transaction_phase \
          active recovery_provenance_restored recovery_cutover_pending || return 1
        ;;
      recovery_cutover_pending|recovery_service_restore_pending|recovery_service_restored|recovery_verify_pending)
        local target
        load_update_origin_from_environment \
          "${PORTAL_DIR}/backend/.env.production" || return 1
        target="$(current_update_receipt_target)" || return 1
        if [[ "${target}" == "active" ]]; then
          cutover_update_transaction "${phase}" || return 1
          continue
        fi
        case "${phase}" in
          recovery_cutover_pending)
            advance_update_transaction_phase \
              cutover recovery_cutover_pending recovery_service_restore_pending \
              || return 1
            ;;
          recovery_service_restore_pending)
            probe_token="$(read_env_value \
              "${PORTAL_DIR}/backend/.env.production" \
              "PORTAL_UPDATE_PROBE_TOKEN" || true)"
            if ! restore_and_verify_canonical_portal_state \
                "${UPDATE_TRANSACTION_PREVIOUS_VERSION}" "${probe_token}"; then
              # The rollback target may already be restored and serving.
              # Re-fencing then stops a healthy Portal and leaves the machine
              # with no Portal at all, which is strictly worse than an
              # unfinished journal entry. Only fence when nothing is serving.
              if canonical_portal_is_serving_version \
                  "${UPDATE_TRANSACTION_PREVIOUS_VERSION}"; then
                warn "Rollback verification did not fully pass, but Portal ${UPDATE_TRANSACTION_PREVIOUS_VERSION} is running and healthy. Leaving it in service; the recovery journal and rollback artifacts were preserved."
                return 1
              fi
              refence_cutover_recovery || true
              return 1
            fi
            advance_update_transaction_phase \
              cutover recovery_service_restore_pending recovery_service_restored \
              || return 1
            ;;
          recovery_service_restored)
            advance_update_transaction_phase \
              cutover recovery_service_restored recovery_verify_pending || return 1
            ;;
          recovery_verify_pending)
            probe_token="$(read_env_value \
              "${PORTAL_DIR}/backend/.env.production" \
              "PORTAL_UPDATE_PROBE_TOKEN" || true)"
            if ! verify_canonical_portal_for_transaction \
                "${UPDATE_TRANSACTION_PREVIOUS_VERSION}" "${probe_token}" true; then
              refence_cutover_recovery || true
              return 1
            fi
            advance_update_transaction_phase \
              cutover recovery_verify_pending recovered || return 1
            ;;
        esac
        ;;
      recovered)
        complete_update_transaction cutover recovered
        return
        ;;
      *)
        return 1
        ;;
    esac
  done
}

update_recovery_phase_rank() {
  case "$1" in
    recovery_pending) echo 0 ;;
    recovery_quiesce_pending) echo 1 ;;
    recovery_quiesced) echo 2 ;;
    recovery_openclaw_restore_pending) echo 3 ;;
    recovery_openclaw_restored) echo 4 ;;
    recovery_database_restore_pending) echo 5 ;;
    recovery_database_restored) echo 6 ;;
    recovery_caddy_restore_pending) echo 7 ;;
    recovery_caddy_restored) echo 8 ;;
    recovery_environment_restore_pending) echo 9 ;;
    recovery_environment_restored) echo 10 ;;
    recovery_runtime_restore_pending) echo 11 ;;
    recovery_runtime_restored) echo 12 ;;
    recovery_dependencies_restore_pending) echo 13 ;;
    recovery_dependencies_restored) echo 14 ;;
    recovery_provenance_restore_pending) echo 15 ;;
    recovery_provenance_restored) echo 16 ;;
    recovery_cutover_pending) echo 17 ;;
    recovery_service_restore_pending) echo 18 ;;
    recovery_service_restored) echo 19 ;;
    recovery_verify_pending) echo 20 ;;
    recovered) echo 21 ;;
    *) return 1 ;;
  esac
}

assert_update_recovery_preconditions_before_emergency_release() {
  # This function is deliberately read-only. It proves every feasible
  # authority, path, artifact, and PostgreSQL prerequisite before the final
  # reserve is consumed. Any failure leaves every emergency inode allocated
  # for an administrator to correct the non-space problem and retry.
  local target="$1" phase="$2" actual_target transaction_id
  local receipt_system_identifier receipt_topology_digest
  local backup_dir stage_dir transaction_dir state_root backup_root stage_root
  local test_root="" recovery_from="${phase}" from_rank recovery_rank=-1
  local env_file db_url contract_variant manifest
  local -a pinned=()
  [[ "${target}" =~ ^(active|cutover)$ && -n "${phase}" ]] || return 1
  actual_target="$(current_update_receipt_target)" || return 1
  [[ "${actual_target}" == "${target}" ]] || return 1
  load_update_transaction_context "${target}" || return 1
  transaction_id="${UPDATE_TRANSACTION_ID}"
  receipt_system_identifier="$(
    read_update_transaction_field "${target}" database_system_identifier
  )" || return 1
  receipt_topology_digest="$(
    read_update_transaction_field "${target}" database_topology_sha256
  )" || return 1
  mapfile -t pinned < <(
    read_update_disk_reserve_database_topology "${transaction_id}"
  ) || return 1
  [[ "${#pinned[@]}" -eq 3 \
    && "${pinned[0]}" == "${receipt_system_identifier}" \
    && "${pinned[1]}" == "${receipt_topology_digest}" ]] || return 1

  backup_dir="$(read_update_transaction_field "${target}" backup_dir)" \
    || return 1
  stage_dir="$(read_update_transaction_field "${target}" stage_dir)" \
    || return 1
  transaction_dir="$(
    read_update_transaction_field "${target}" transaction_dir
  )" || return 1
  state_root="$(update_transaction_state_path "${UPDATE_STATE_ROOT}")" \
    || return 1
  backup_root="$(update_transaction_state_path "${UPDATE_BACKUP_ROOT}")" \
    || return 1
  stage_root="$(update_transaction_state_path "${UPDATE_STAGE_ROOT}")" \
    || return 1
  test_root="$(update_transaction_test_root 2>/dev/null || true)"
  python3 - "${transaction_id}" "${backup_dir}" "${stage_dir}" \
    "${transaction_dir}" "${state_root}" "${backup_root}" "${stage_root}" \
    "${test_root}" <<'PY2' || return 1
import os
import stat
import sys

(
    transaction_id,
    backup_dir,
    stage_dir,
    transaction_dir,
    state_root,
    backup_root,
    stage_root,
    test_root,
) = sys.argv[1:]
expected = (
    os.path.join(backup_root, f"update-{transaction_id}"),
    os.path.join(stage_root, f"update-{transaction_id}"),
    os.path.join(state_root, "transactions", transaction_id),
)
if (backup_dir, stage_dir, transaction_dir) != expected:
    raise SystemExit(1)
if test_root:
    root = os.path.realpath(test_root)
    if any(
        os.path.commonpath((root, os.path.realpath(path))) != root
        for path in (*expected, state_root, backup_root, stage_root)
    ):
        raise SystemExit(1)
stage_payload = expected[1]
for path in (*expected, state_root, backup_root, stage_root):
    try:
        details = os.lstat(path)
    except FileNotFoundError:
        # The state helper's terminal cleanup removes secret-bearing payload
        # directories while the receipt still exists, so an absent stage
        # payload is a legitimate post-cleanup state. Every other directory
        # in this layout must exist; a present stage must still pass the
        # full secure-directory contract below.
        if path == stage_payload:
            continue
        raise SystemExit(1)
    if (
        not stat.S_ISDIR(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != os.geteuid()
        or details.st_gid != os.getegid()
        or details.st_mode & 0o077
    ):
        raise SystemExit(1)
PY2

  if [[ "${phase}" == recovery_* && "${phase}" != "recovered" ]]; then
    recovery_from="$(
      read_update_transaction_field "${target}" recovery_from_phase
    )" || return 1
    recovery_rank="$(update_recovery_phase_rank "${phase}")" || return 1
  fi
  from_rank="$(update_forward_phase_rank "${recovery_from}")" || return 1

  if (( from_rank >= $(update_forward_phase_rank portal_quiesce_pending) )); then
    manifest="$(
      update_transaction_manifest_path "${target}" running-app-intent
    )" || return 1
    update_artifact_manifest verify \
      "${backup_dir}/running-app-intent.json" "${manifest}" false \
      || return 1
  fi

  # Runtime/environment snapshots exist before any mutable Portal layer. Use
  # the original protected environment as database authority whenever it has
  # been captured; before that point the canonical environment is unchanged.
  env_file="${PORTAL_DIR}/backend/.env.production"
  if (( from_rank >= $(update_forward_phase_rank runtime_snapshot_complete) )); then
    manifest="$(update_transaction_manifest_path "${target}" environment)" \
      || return 1
    update_artifact_manifest verify \
      "${backup_dir}/environment" "${manifest}" false || return 1
    env_file="${backup_dir}/environment/backend.env.production"
  fi
  assert_env_file_no_duplicate_keys "${env_file}" || return 1
  load_update_origin_from_environment "${env_file}" || return 1
  db_url="$(read_env_value "${env_file}" "DATABASE_URL" || true)"
  [[ -n "${db_url}" ]] || return 1
  assert_update_database_topology_unchanged \
    "${db_url}" recovery-emergency-release || return 1

  if (( from_rank >= $(update_forward_phase_rank database_migration_pending) \
    && (recovery_rank < 0 \
      || recovery_rank <= $(update_recovery_phase_rank recovery_database_restore_pending)) )); then
    manifest="$(update_transaction_manifest_path "${target}" database)" \
      || return 1
    update_artifact_manifest verify \
      "${backup_dir}/database-before-update.dump" "${manifest}" false \
      || return 1
    contract_variant="$(
      read_update_database_contract_snapshot "${target}" "${backup_dir}"
    )" || return 1
    [[ "${contract_variant}" =~ ^(owner-null|pg-database-owner-default)$ ]] \
      || return 1
  fi
  if (( from_rank >= $(update_forward_phase_rank caddy_update_pending) \
    && (recovery_rank < 0 \
      || recovery_rank <= $(update_recovery_phase_rank recovery_caddy_restore_pending)) )); then
    manifest="$(update_transaction_manifest_path "${target}" caddy)" \
      || return 1
    update_artifact_manifest verify \
      "${backup_dir}/Caddyfile" "${manifest}" true || return 1
  fi
  if (( from_rank >= $(update_forward_phase_rank environment_update_pending) \
    && (recovery_rank < 0 \
      || recovery_rank <= $(update_recovery_phase_rank recovery_environment_restore_pending)) )); then
    manifest="$(update_transaction_manifest_path "${target}" environment-updated)" \
      || return 1
    update_artifact_manifest verify \
      "${backup_dir}/environment.updated" "${manifest}" false || return 1
  fi
  if (( from_rank >= $(update_forward_phase_rank runtime_overlay_pending) \
    && (recovery_rank < 0 \
      || recovery_rank <= $(update_recovery_phase_rank recovery_runtime_restore_pending)) )); then
    manifest="$(update_transaction_manifest_path "${target}" runtime)" \
      || return 1
    update_artifact_manifest verify \
      "${backup_dir}/portal-runtime" "${manifest}" false || return 1
  fi
  if (( from_rank >= $(update_forward_phase_rank dependencies_update_pending) \
    && (recovery_rank < 0 \
      || recovery_rank <= $(update_recovery_phase_rank recovery_dependencies_restore_pending)) )); then
    manifest="$(update_transaction_manifest_path "${target}" dependencies)" \
      || return 1
    update_artifact_manifest verify \
      "${backup_dir}/backend-node-modules" "${manifest}" true || return 1
  fi
  if (( from_rank >= $(update_forward_phase_rank provenance_commit_pending) \
    && (recovery_rank < 0 \
      || recovery_rank <= $(update_recovery_phase_rank recovery_provenance_restore_pending)) )); then
    manifest="$(update_transaction_manifest_path "${target}" provenance)" \
      || return 1
    update_artifact_manifest verify \
      "${backup_dir}/last-portal-deploy.previous" "${manifest}" true \
      || return 1
  fi
}

recover_pending_update_transaction() {
  ${UPDATE_RECOVERY_IN_PROGRESS:-false} && return 1
  UPDATE_RECOVERY_IN_PROGRESS=true
  trap - ERR
  trap '' SIGINT TERM HUP
  set +e

  local target phase result=1
  target="$(current_update_receipt_target 2>/dev/null || true)"
  [[ "${target}" =~ ^(active|cutover)$ ]] || return 1
  phase="$(read_update_transaction_field "${target}" phase 2>/dev/null || true)"
  # A transaction created by an older installer can resume through this newer
  # recovery engine. Install and attest the static OpenClaw start inhibitor
  # before any rollback or forward-cutover path can boot Portal 4.0 code.
  install_openclaw_gateway_authorization_fence_dropin || return 1
  case "${phase}" in
    committed|recovered)
      # Terminal cleanup owns the full reserve release and can resume a
      # partially journaled cleanup after SIGKILL.
      ;;
    *)
      prepare_update_disk_reserves_for_recovery || return 1
      ;;
  esac
  # Forward cutover needs no rollback space and must not burn the emergency
  # tier merely to start or verify a service. Every path that is entering or
  # resuming rollback first proves all read-only preconditions, then consumes
  # an explicitly escalated tier immediately before its first durable write.
  case "${target}:${phase}" in
    cutover:cutover_pending|cutover:canonical_start_pending|\
    cutover:canonical_started|cutover:canonical_verification_pending|\
    cutover:canonical_verified|cutover:boot_state_restore_pending|\
    cutover:boot_state_restored|cutover:committed|cutover:recovered)
      ;;
    *)
      assert_update_recovery_preconditions_before_emergency_release \
        "${target}" "${phase}" || return 1
      consume_update_emergency_disk_reserves_for_recovery || return 1
      ;;
  esac
  if [[ "${target}" == "cutover" ]]; then
    phase="$(read_update_transaction_field cutover phase 2>/dev/null || true)"
    case "${phase}" in
      committed)
        complete_committed_update_transaction
        result=$?
        ;;
      cutover_pending|canonical_start_pending|canonical_started|canonical_verification_pending|canonical_verified|boot_state_restore_pending|boot_state_restored)
        finish_forward_cutover_transaction
        result=$?
        ;;
      recovery_cutover_pending|recovery_service_restore_pending|recovery_service_restored|recovery_verify_pending)
        if reopen_cutover_update_transaction \
          && install_portal_update_boot_fence \
          && quiesce_portal_service "bridgesllm-product" 45 15 4001; then
          recover_active_update_transaction
          result=$?
        fi
        ;;
      recovered)
        complete_update_transaction cutover recovered
        result=$?
        ;;
    esac
  elif [[ "${target}" == "active" ]]; then
    phase="$(read_update_transaction_field active phase 2>/dev/null || true)"
    if [[ "${phase}" == recovery_* ]]; then
      install_portal_update_boot_fence \
        && recover_active_update_transaction
      result=$?
    elif [[ -n "${phase}" && "${phase}" != "committed" ]]; then
      if advance_update_transaction_phase \
          active "${phase}" recovery_pending \
        && install_portal_update_boot_fence; then
        recover_active_update_transaction
        result=$?
      fi
    fi
  fi

  if [[ "${result}" -eq 0 ]]; then
    set -e
    UPDATE_RECOVERY_IN_PROGRESS=false
    trap 'handle_err $LINENO' ERR
    trap handle_sigint SIGINT
    trap handle_sigterm TERM
    trap handle_sighup HUP
  else
    # A failed recovery is terminal for this process: keep every trap
    # disabled and the in-progress latch set so no second attempt and no
    # secondary failure handler can run. The journal deliberately retains
    # the last pending phase for the next installer invocation to resume.
    trap '' ERR SIGINT TERM HUP
  fi
  return "${result}"
}

do_update() {
  banner
  echo ""
  if $REPAIR_REINSTALL; then
    echo -e "  ${BOLD}${WHITE}Repairing BridgesLLM Portal installation${NC}"
  else
    echo -e "  ${BOLD}${WHITE}Updating BridgesLLM Portal${NC}"
  fi
  echo ""
  CURRENT_STEP="update"

  dashboard_update_progress running 10 host-safety \
    "Checking host safety" \
    "Step 2 of 13 · Inspecting scheduled Docker cleanup without changing unrelated host jobs."
  converge_unsafe_docker_prune_automation \
    || fail "Unsafe scheduled Docker cleanup remains active. Review the guard details above, disable the unknown job or repair the legacy-file drift, and retry."

  local previous_portal_version=""
  previous_portal_version="$(attest_existing_portal_for_update "${PORTAL_DIR}")" \
    || fail "The existing Portal runtime or configuration is incomplete, linked, writable by another account, or version-inconsistent. Repair it explicitly before updating."

  node_version_meets_minimum \
    || fail "The running Portal uses a Node.js release outside ${OPENCLAW_NODE_ENGINE_RANGE}. Update the shared Node runtime first (Node 22 must be >=22.22.3 and <23), then retry. The updater refused before its boot fence and will not replace Node without a rollback boundary. See docs/PORTAL_NODE_RUNTIME_REMEDIATION.md."

  dashboard_update_progress running 16 portal-preflight \
    "Validating current Portal and recovery prerequisites" \
    "Step 3 of 13 · The installed runtime and shared Node.js boundary are attested."

  load_existing_telemetry_install_id
  ensure_telemetry_install_id

  local env_file="${PORTAL_DIR}/backend/.env.production"
  # Environment authority must be unambiguous before anything reads it: a key
  # assigned twice makes installer reads and systemd's effective (last-wins)
  # value diverge, splitting database/origin/probe authority mid-transaction.
  assert_env_file_no_duplicate_keys "${env_file}" \
    || fail "The existing backend environment file is missing, linked, or assigns a variable more than once; the installer and systemd would disagree about the effective configuration. Repair ${env_file} before updating."
  assert_env_file_no_duplicate_keys "${PORTAL_DIR}/frontend/.env" \
    || fail "The existing frontend environment file is missing, linked, or assigns a variable more than once. Repair ${PORTAL_DIR}/frontend/.env before updating."
  assert_prisma_runtime_environment_safe "${env_file}" \
    || fail "The existing backend or installer process environment overrides the attested database runtime. Remove Prisma engine switches, node-postgres PG* fallbacks, NODE_PG_FORCE_NATIVE, and NODE_TLS_REJECT_UNAUTHORIZED before updating."
  local validation_assignment_status=0
  env_file_has_assignment "${env_file}" "PORTAL_UPDATE_VALIDATION_MODE" \
    || validation_assignment_status=$?
  if [[ "${validation_assignment_status}" -ne 1 ]]; then
    fail "PORTAL_UPDATE_VALIDATION_MODE is a transient updater flag and must never be stored in .env.production. Remove that line before retrying."
  fi

  # Read the exact existing database identity. A missing or malformed value
  # must never drift into the installer's local default.
  local existing_db_url=""
  existing_db_url="$(read_env_value "${env_file}" "DATABASE_URL" || true)"
  local db_component
  for db_component in host port database user password; do
    pg_url_component "${existing_db_url}" "${db_component}" >/dev/null \
      || fail "The existing DATABASE_URL is missing or malformed; refusing to touch any database."
  done
  pg_url_uses_public_schema "${existing_db_url}" \
    || fail "The existing DATABASE_URL selects a non-public or ambiguous Prisma schema. Portal rollback is defined only for the public schema; remove the schema option or set schema=public before updating."
  pg_url_uses_supported_prisma_adapter_options "${existing_db_url}" \
    || fail "The existing DATABASE_URL has an ambiguous or unsupported database-driver option. Remote databases must set sslmode=disable, require, verify-ca, or verify-full. An absolute sslrootcert is required for verify-ca/verify-full; sslcert/client identities/keys, sslaccept, and channel_binding are not supported. Only lowercase application_name, fallback_application_name, options, client_encoding, replication, and documented Prisma pool controls may be supplied; literal plus signs must be percent-encoded. Custom connect_timeout and pool_timeout values must match. Repair the URL before updating."
  PORTAL_UPDATE_PROBE_TOKEN="$(
    read_env_value "${env_file}" "PORTAL_UPDATE_PROBE_TOKEN" || true
  )"
  if [[ -z "${PORTAL_UPDATE_PROBE_TOKEN}" \
    && "${previous_portal_version}" != 3.* ]]; then
    fail "This Portal 4.x installation is missing its authenticated update probe token. Repair the environment before updating."
  fi
  [[ -n "${PORTAL_UPDATE_PROBE_TOKEN}" ]] \
    || PORTAL_UPDATE_PROBE_TOKEN="$(rand_hex 32)"
  DB_PASSWORD="$(pg_url_component "${existing_db_url}" password)" \
    || fail "The existing database password could not be parsed safely."
  # Use one identity for the pre-staging reserves, stage tree, and durable
  # receipt. Publishing it before admission lets reserve files be named and
  # recovered deterministically even if the installer is SIGKILLed while the
  # signed candidate is still being staged.
  UPDATE_TRANSACTION_ID="$(openssl rand -hex 16)"
  [[ "${UPDATE_TRANSACTION_ID}" =~ ^[a-f0-9]{32}$ ]] \
    || fail "Could not create a bounded update transaction identifier."
  attest_update_database_ownership "${existing_db_url}" admission \
    || fail "The existing database does not follow the exact installer ownership contract (public must be the only user schema; every dumpable public-schema object and ACL must have Portal-owned/default state). Rollback could not restore it exactly, so the update refuses to start. Details: ${LOG_FILE}."
  local disk_admission_status=0
  assert_update_transaction_disk_admission "${PORTAL_DIR}" "${existing_db_url}" \
    || disk_admission_status=$?
  if [[ "${disk_admission_status}" -eq 2 ]]; then
    fail "This host does not have enough free disk for staging, rollback snapshots, the installer journal, and recovery reserve. Free space and retry. Measured shortfall: $(update_disk_admission_last_detail). Details: ${LOG_FILE}."
  elif [[ "${disk_admission_status}" -ne 0 ]]; then
    fail "The update refused to start because this host could not be admitted for a safe, rollback-capable upgrade. This is not a disk-space shortfall. Reason: $(update_disk_admission_last_detail). Details: ${LOG_FILE}."
  fi
  ensure_media_toolchain \
    || fail "Animated GIF uploads require ffmpeg and ffprobe, but the updater could not repair the FFmpeg package while the existing Portal was still online. Check ${LOG_FILE}, repair apt, and retry."

  dashboard_update_progress running 22 capacity-preflight \
    "Checking database, disk, and recovery capacity" \
    "Step 4 of 13 · Database ownership, disk reserves, and required host tools passed admission."

  local existing_install_profile
  existing_install_profile="$(read_env_value "${env_file}" "INSTALL_PROFILE" || true)"
  [[ -n "${existing_install_profile}" ]] && INSTALL_PROFILE="${existing_install_profile}"
  if [[ -z "${ORIGIN_MODE}" ]]; then
    ORIGIN_MODE="$(read_env_value "${env_file}" "ORIGIN_MODE" || true)"
  fi
  if use_tailnet_profile && [[ -z "${TAILNET_DNS_NAME}" ]]; then
    TAILNET_DNS_NAME="$(read_env_value "${env_file}" "TAILNET_DNS_NAME" || true)"
    local live_tailnet_name
    live_tailnet_name="$(tailnet_dns_name_from_status)"
    [[ -n "${live_tailnet_name}" ]] && TAILNET_DNS_NAME="${live_tailnet_name}"
  fi
  [[ -n "${DOMAIN}" ]] || DOMAIN="$(read_env_value "${env_file}" "DOMAIN" || true)"
  if [[ -z "${APP_CONTENT_DOMAIN}" ]]; then
    APP_CONTENT_DOMAIN="$(read_env_value "${env_file}" "APP_CONTENT_DOMAIN" || true)"
    APP_CONTENT_DNS_MODE="$(read_env_value "${env_file}" "APP_CONTENT_DNS_MODE" || true)"
    if [[ -z "${APP_CONTENT_DOMAIN}" ]]; then
      local existing_app_content_origin
      existing_app_content_origin="$(read_env_value "${env_file}" "APP_CONTENT_ORIGIN" || true)"
      APP_CONTENT_DOMAIN="$(app_content_domain_from_origin "${existing_app_content_origin}" || true)"
    fi
  fi

  # Stage and prepare the candidate while the old Portal remains online.
  dashboard_update_progress running 24 signed-release \
    "Downloading and verifying signed release" \
    "Step 5 of 13 · Fetching the versioned manifest, signature, and Portal artifact."
  UPDATE_RELEASE_STAGE_DIR="$(
    new_release_stage_dir "${UPDATE_TRANSACTION_ID}"
  )" || fail "Could not create the private update staging directory."
  if ! stage_verified_release "${UPDATE_RELEASE_STAGE_DIR}"; then
    cleanup_release_stage_dir "${UPDATE_RELEASE_STAGE_DIR}" || true
    UPDATE_RELEASE_STAGE_DIR=""
    fail "Update release signature, version, digest, or archive validation failed before downtime."
  fi
  dashboard_update_progress running 30 signed-release \
    "Signed release verified" \
    "Step 5 of 13 · Manifest signature, release version, digest, and archive boundaries passed."
  local staged_update_dir="${UPDATE_RELEASE_STAGE_DIR}/portal"
  # Public 3.26.x installs never shipped build-essential; candidate native
  # module verification needs it. Install while the old Portal is still up.
  ensure_build_tools
  prepare_staged_backend_runtime_dependencies "${staged_update_dir}" \
    || fail "Candidate runtime dependencies could not be prepared and verified before downtime."
  prepare_update_project_runtimes \
    "${staged_update_dir}" "${env_file}" "${UPDATE_TRANSACTION_ID}"
  if [[ "${previous_portal_version}" != 3.* ]]; then
    local continuity_repair_plan="${UPDATE_RELEASE_STAGE_DIR}/portal-continuity-repair-plan.json"
    run_staged_portal_rebootability_preflight \
      "${staged_update_dir}" "${env_file}" "${continuity_repair_plan}" \
      || fail "The signed candidate could not classify persisted App/Project continuity safely. No database mutation, transaction, or downtime was started; repair the reported ambiguity and retry. Details: ${LOG_FILE}."
    run_staged_portal_continuity_repair \
      "${staged_update_dir}" "${env_file}" "${continuity_repair_plan}" \
      || fail "The signed candidate could not apply its exact serializable App continuity repair while the existing Portal was online. No update transaction or downtime was started; the repair refused a race or ambiguous row. Details: ${LOG_FILE}."
    run_staged_portal_rebootability_preflight \
      "${staged_update_dir}" "${env_file}" \
      || fail "The signed candidate could not reattest a clean, rebootable App/Project state after continuity repair. The existing Portal remains online and no update transaction or downtime was started. Details: ${LOG_FILE}."
  else
    info "Legacy 3.x source detected; the 4.x App identity preflight will run after continuity enrollment."
  fi
  disk_admission_status=0
  assert_update_transaction_disk_admission \
    "${PORTAL_DIR}" "${existing_db_url}" "${staged_update_dir}" \
    || disk_admission_status=$?
  if [[ "${disk_admission_status}" -eq 2 ]]; then
    fail "The fully staged candidate and additive Project runtime images do not leave enough disk for runtime promotion, rollback snapshots, the installer journal, and recovery. No receipt or downtime was started; free space and retry. Measured shortfall: $(update_disk_admission_last_detail). Details: ${LOG_FILE}."
  elif [[ "${disk_admission_status}" -ne 0 ]]; then
    fail "The staged candidate could not be admitted for promotion, and not because of free disk. No receipt or downtime was started. Reason: $(update_disk_admission_last_detail). Details: ${LOG_FILE}."
  fi

  dashboard_update_progress running 38 runtime-preparation \
    "Preparing dependencies and project runtimes" \
    "Step 6 of 13 · Backend dependencies and additive runtime images are staged and verified."

  recover_domain_from_caddyfile
  local existing_public_ip detected_public_ip
  existing_public_ip="$(read_env_value "${env_file}" "PUBLIC_IP" || true)"
  detected_public_ip="$(curl -4 -fsSL --max-time 8 https://api.ipify.org 2>/dev/null || true)"
  PUBLIC_IP="${detected_public_ip:-${existing_public_ip}}"
  if [[ "${APP_CONTENT_DNS_MODE}" == "sslip" ]]; then
    APP_CONTENT_DOMAIN=""
  fi
  configure_app_content_identity

  capture_portal_service_baseline "bridgesllm-product" \
    || fail "Portal service state is masked, static, unknown, or internally inconsistent; refusing an update without an exact restore policy."
  prepare_update_transaction \
    "${previous_portal_version}" "${staged_update_dir}" "${UPDATE_TRANSACTION_ID}" \
    || fail "The durable update transaction could not be created safely."
  dashboard_update_progress running 40 portal-transaction \
    "Opening protected update transaction" \
    "Step 7 of 13 · A durable rollback journal now protects the live cutover."
  arm_update_transaction_traps

  advance_update_transaction_phase active prepared boot_block_pending \
    || fail "Could not record the boot-fence write-ahead phase."
  fence_portal_service_boot \
    || fail "The Portal boot fence could not be installed and verified."
  advance_update_transaction_phase active boot_block_pending boot_blocked \
    || fail "Could not commit the boot-fence phase."

  capture_update_running_app_intent "${existing_db_url}" \
    || fail "The exact running full-stack App intent could not be sealed before Portal shutdown."
  advance_update_transaction_phase \
    active boot_blocked portal_quiesce_pending \
    || fail "Could not record the Portal quiescence write-ahead phase."
  quiesce_portal_service "bridgesllm-product" 45 15 4001 \
    || fail "Portal could not be proven stopped; no runtime or database mutation was attempted."
  reconcile_update_running_app_intent active "${existing_db_url}" \
    || fail "Running full-stack App intent changed incompatibly during Portal shutdown; the update was rolled back."
  advance_update_transaction_phase \
    active portal_quiesce_pending portal_quiesced \
    || fail "Could not commit the Portal quiescence phase."
  reattest_quiesced_update_project_egress_generation \
    "${UPDATE_RELEASE_STAGE_DIR}" "${UPDATE_TRANSACTION_ID}" \
    || fail "Managed Project egress resources changed after candidate preparation. The update was rolled back before runtime or database mutation; retry after Project activity is quiet."

  advance_update_transaction_phase \
    active portal_quiesced runtime_snapshot_pending \
    || fail "Could not record the runtime snapshot phase."
  snapshot_update_runtime_and_environment \
    || fail "The exact runtime and environment rollback snapshots could not be created."
  snapshot_update_provenance \
    || fail "The deploy-provenance rollback snapshot could not be created."
  advance_update_transaction_phase \
    active runtime_snapshot_pending runtime_snapshot_complete \
    || fail "Could not commit the runtime snapshot phase."

  advance_update_transaction_phase \
    active runtime_snapshot_complete database_snapshot_pending \
    || fail "Could not record the database snapshot phase."
  snapshot_update_database "${existing_db_url}" \
    || fail "The PostgreSQL rollback snapshot could not be created and verified."
  advance_update_transaction_phase \
    active database_snapshot_pending database_snapshot_complete \
    || fail "Could not commit the database snapshot phase."

  advance_update_transaction_phase \
    active database_snapshot_complete caddy_snapshot_pending \
    || fail "Could not record the routing snapshot phase."
  snapshot_update_caddy \
    || fail "The exact Caddy rollback snapshot could not be created."
  advance_update_transaction_phase \
    active caddy_snapshot_pending caddy_snapshot_complete \
    || fail "Could not commit the routing snapshot phase."

  advance_update_transaction_phase \
    active caddy_snapshot_complete openclaw_snapshot_pending \
    || fail "Could not record the ancillary-state snapshot phase."
  # Global OpenClaw and host-tool convergence is post-commit. These phases are
  # a proven no-op because a Portal snapshot cannot restore global packages.
  advance_update_transaction_phase \
    active openclaw_snapshot_pending openclaw_snapshot_complete \
    || fail "Could not commit the ancillary-state snapshot phase."

  advance_update_transaction_phase \
    active openclaw_snapshot_complete node_modules_move_pending \
    || fail "Could not record the dependency snapshot phase."
  snapshot_update_dependencies \
    || fail "The exact backend dependency rollback snapshot could not be created."
  advance_update_transaction_phase \
    active node_modules_move_pending node_modules_moved \
    || fail "Could not commit the dependency snapshot phase."

  prepare_updated_environment_candidate \
    || fail "The updated environment candidate could not be prepared without mutating the live installation."
  seal_update_project_runtime_promotion_manifest active \
    || fail "Prepared Project runtime identities could not be sealed in the non-secret transaction journal."

  advance_update_transaction_phase \
    active node_modules_moved runtime_overlay_pending \
    || fail "Could not record the runtime overlay write-ahead phase."
  overlay_verified_update_runtime "${staged_update_dir}" \
    || fail "The signed Portal runtime could not be overlaid exactly."
  advance_update_transaction_phase \
    active runtime_overlay_pending runtime_overlaid \
    || fail "Could not commit the runtime overlay phase."

  advance_update_transaction_phase \
    active runtime_overlaid environment_update_pending \
    || fail "Could not record the environment update write-ahead phase."
  install_updated_environment_candidate \
    || fail "The verified environment candidate could not be installed atomically."
  advance_update_transaction_phase \
    active environment_update_pending environment_updated \
    || fail "Could not commit the environment update phase."

  advance_update_transaction_phase \
    active environment_updated caddy_update_pending \
    || fail "Could not record the routing update write-ahead phase."
  if ! use_local_profile && ! use_tailnet_profile; then
    write_caddy_config \
      || fail "The managed Caddy transaction failed; unrelated sites were preserved."
  fi
  advance_update_transaction_phase \
    active caddy_update_pending caddy_updated \
    || fail "Could not commit the routing update phase."

  advance_update_transaction_phase \
    active caddy_updated dependencies_update_pending \
    || fail "Could not record the dependency replacement write-ahead phase."
  install_prepared_update_dependencies "${staged_update_dir}" \
    || fail "The preverified backend dependencies could not be promoted."
  advance_update_transaction_phase \
    active dependencies_update_pending dependencies_updated \
    || fail "Could not commit the dependency replacement phase."

  advance_update_transaction_phase \
    active dependencies_updated database_migration_pending \
    || fail "Could not record the database migration write-ahead phase."
  run_migrations_safe "${existing_db_url}"
  advance_update_transaction_phase \
    active database_migration_pending database_migrated \
    || fail "Could not commit the database migration phase."

  advance_update_transaction_phase \
    active database_migrated openclaw_update_pending \
    || fail "Could not record the post-Portal dependency phase."
  advance_update_transaction_phase \
    active openclaw_update_pending openclaw_updated \
    || fail "Could not commit the post-Portal dependency phase."

  assert_prepared_update_project_runtime_images_available active \
    || fail "Prepared Project runtime images disappeared before candidate validation."
  advance_update_transaction_phase \
    active openclaw_updated candidate_start_pending \
    || fail "Could not record the private candidate start phase."
  start_update_candidate "${UPDATE_TRANSACTION_ID}" "${UPDATE_CANDIDATE_PORT}" \
    || fail "The signed Portal candidate could not start in its private validation unit."
  advance_update_transaction_phase \
    active candidate_start_pending candidate_started \
    || fail "Could not commit the private candidate start phase."

  advance_update_transaction_phase \
    active candidate_started candidate_verification_pending \
    || fail "Could not record the private candidate verification phase."
  verify_update_candidate \
    "${UPDATE_TRANSACTION_ID}" "${VERSION}" \
    "${PORTAL_UPDATE_PROBE_TOKEN}" "${UPDATE_CANDIDATE_PORT}" \
    || fail "The private candidate failed exact version, schema, or mutation-free readiness verification."
  advance_update_transaction_phase \
    active candidate_verification_pending candidate_verified \
    || fail "Could not commit the private candidate verification phase."

  advance_update_transaction_phase \
    active candidate_verified provenance_commit_pending \
    || fail "Could not record the deploy-provenance write-ahead phase."
  commit_portal_deploy_provenance \
    || fail "Verified candidate provenance could not be committed atomically."
  advance_update_transaction_phase \
    active provenance_commit_pending provenance_committed \
    || fail "Could not commit the deploy-provenance phase."
  advance_update_transaction_phase \
    active provenance_committed cutover_pending \
    || fail "Could not record the canonical cutover decision."

  dashboard_update_progress running 88 portal-cutover \
    "Switching to the verified Portal" \
    "Step 11 of 13 · The private candidate passed; publishing the durable cutover decision now."

  # The receipt move is the durable commit decision. Before it, recovery rolls
  # back. After it, recovery finishes the already verified forward cutover.
  cutover_update_transaction cutover_pending \
    || fail "The atomic Portal cutover decision could not be published."
  finish_forward_cutover_transaction \
    || fail "Canonical Portal cutover did not complete; recovery was re-fenced."

  UPDATE_RELEASE_STAGE_DIR=""
  trap 'handle_err $LINENO' ERR
  trap handle_sigint SIGINT
  trap handle_sigterm TERM
  trap handle_sighup HUP

  # Host-wide tools and optional runtimes stay outside the Portal transaction.
  # The new Portal is already loaded, schema-ready, and provenance-attested.
  DASHBOARD_UPDATE_PORTAL_COMMITTED=true
  dashboard_update_progress running 97 postflight \
    "Completing host services and cleanup" \
    "Step 13 of 13 · Portal is online while host integration and optional runtimes converge."
  update_dependencies
  telemetry_event "deps_updated"
  info "Checking Remote Desktop..."
  setup_remote_desktop
  configure_backup_timers
  ensure_project_egress_token_secret "${env_file}"
  ensure_docker_address_pools
  provision_project_runtimes "${env_file}"
  ensure_agent_zero_project_model_bridge
  if systemctl is-enabled openclaw-gateway &>/dev/null 2>&1; then
    prepare_openclaw_runtime_for_portal
  fi
  if command -v openclaw &>/dev/null; then
    openclaw devices approve --latest >> "$LOG_FILE" 2>&1 || true
  fi

  # This proof belongs after every post-commit host mutation. The outer
  # systemd finalizer accepts the 99% checkpoint as its success prerequisite,
  # so do not publish that checkpoint from a generic, spoofable health body.
  # Reuse the authenticated update-ready contract, systemd activity/PID proof,
  # exact version, schema, and canonical-route checks that guarded cutover.
  verify_canonical_portal_for_transaction \
    "${VERSION}" "${PORTAL_UPDATE_PROBE_TOKEN}" \
    || fail "Final authenticated Portal readiness verification failed after host integration."

  dashboard_update_progress running 99 postflight \
    "Finalizing update receipt" \
    "Step 13 of 13 · Host integration and authenticated exact-version health verification passed."

  echo ""
  echo -e "  ${GREEN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
  echo -e "  ${GREEN}${BOLD}  Update complete!${NC}"
  telemetry_event "update_complete"
  echo -e "  ${GREEN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
  echo ""
}

write_retained_install_receipt() {
  local portal_dir="${1:-${PORTAL_DIR}}"
  local marker_path="${2:-${RETAINED_INSTALL_MARKER}}"
  local manifest_path="${3:-${RETAINED_INSTALL_MANIFEST}}"
  local env_file="${portal_dir}/backend/.env.production"
  [[ -f "${env_file}" && ! -L "${env_file}" ]] || return 1
  assert_env_file_no_duplicate_keys "${env_file}" || return 1
  python3 - "${portal_dir}" "${marker_path}" "${manifest_path}" "${VERSION}" <<'PY'
import datetime
import hashlib
import json
import os
import pathlib
import stat
import sys
import tempfile

portal_raw, marker_raw, manifest_raw, version = sys.argv[1:]
portal = pathlib.Path(portal_raw)
marker = pathlib.Path(marker_raw)
manifest = pathlib.Path(manifest_raw)

def bounded_absolute(path: pathlib.Path) -> pathlib.Path:
    value = str(path)
    if not value.startswith("/") or os.path.normpath(value) != value or value == "/":
        raise ValueError("retained path is not a bounded canonical absolute path")
    return path

for item in (portal, marker, manifest):
    bounded_absolute(item)
if marker.parent != manifest.parent or portal.parent != marker.parent:
    raise ValueError("retained receipt paths do not share the installation boundary")

current = pathlib.Path("/")
for component in portal.parts[1:]:
    current /= component
    info = os.lstat(current)
    if (not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode)
            or info.st_uid != 0 or info.st_mode & 0o022):
        raise ValueError("retained Portal path crosses an unsafe ownership boundary")
if os.path.realpath(portal) != str(portal):
    raise ValueError("retained Portal path does not resolve to itself")

allowed_roots = {
    ".data",
    "apps",
    "assets",
    "backend",
    "frontend",
    "projects",
    "upload-temp",
}
allowed_backend = {".data", ".env", ".env.production"}
allowed_frontend = {".env"}
entries = []

def digest_file(path: pathlib.Path, initial: os.stat_result) -> str:
    digest = hashlib.sha256()
    with path.open("rb", buffering=0) as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    final = os.lstat(path)
    identity = (
        initial.st_dev, initial.st_ino, initial.st_mode, initial.st_uid,
        initial.st_gid, initial.st_size, initial.st_mtime_ns,
    )
    if identity != (
        final.st_dev, final.st_ino, final.st_mode, final.st_uid,
        final.st_gid, final.st_size, final.st_mtime_ns,
    ):
        raise ValueError("retained file changed while it was inventoried")
    return digest.hexdigest()

for child in sorted(portal.iterdir(), key=lambda item: item.name):
    if child.name not in allowed_roots:
        raise ValueError(f"unexpected retained top-level entry: {child.name}")
for directory, dirnames, filenames in os.walk(portal, topdown=True, followlinks=False):
    base = pathlib.Path(directory)
    relative_base = base.relative_to(portal)
    if relative_base == pathlib.Path("."):
        dirnames[:] = sorted(name for name in dirnames if name in allowed_roots)
    elif relative_base == pathlib.Path("backend"):
        unexpected = set(dirnames) | set(filenames)
        unexpected -= allowed_backend
        if unexpected:
            raise ValueError("unexpected retained backend payload")
    elif relative_base == pathlib.Path("frontend"):
        unexpected = set(dirnames) | set(filenames)
        unexpected -= allowed_frontend
        if unexpected:
            raise ValueError("unexpected retained frontend payload")
    dirnames.sort()
    filenames.sort()
    for name in [*dirnames, *filenames]:
        path = base / name
        relative = path.relative_to(portal).as_posix()
        info = os.lstat(path)
        common = {
            "path": relative,
            "mode": stat.S_IMODE(info.st_mode),
            "uid": info.st_uid,
            "gid": info.st_gid,
        }
        if stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode):
            entries.append({**common, "type": "directory"})
        elif stat.S_ISREG(info.st_mode) and not stat.S_ISLNK(info.st_mode):
            if info.st_nlink != 1:
                raise ValueError("retained file has multiple hard links")
            entries.append({
                **common,
                "type": "file",
                "size": info.st_size,
                "sha256": digest_file(path, info),
            })
        elif stat.S_ISLNK(info.st_mode):
            target = os.readlink(path)
            resolved = os.path.realpath(path)
            if (relative != "backend/.env" or target != ".env.production"
                    or resolved != str(portal / "backend" / ".env.production")):
                raise ValueError("retained tree contains an unsafe symbolic link")
            entries.append({**common, "type": "symlink", "target": target})
            if name in dirnames:
                dirnames.remove(name)
        else:
            raise ValueError("retained tree contains a special inode")

env = portal / "backend" / ".env.production"
env_info = os.lstat(env)
if (not stat.S_ISREG(env_info.st_mode) or stat.S_ISLNK(env_info.st_mode)
        or env_info.st_uid != 0 or env_info.st_nlink != 1
        or env_info.st_mode & 0o022 or env_info.st_size <= 0
        or env_info.st_size > 1024 * 1024):
    raise ValueError("retained environment is unsafe")
env_sha256 = digest_file(env, env_info)
document = {
    "schema": "bridgesllm.retained-install-tree.v1",
    "portalRoot": str(portal),
    "entries": sorted(entries, key=lambda entry: entry["path"]),
}
encoded = (json.dumps(document, indent=2, sort_keys=True) + "\n").encode()

def publish(path: pathlib.Path, payload: bytes) -> None:
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    parent_info = os.lstat(path.parent)
    if (not stat.S_ISDIR(parent_info.st_mode) or stat.S_ISLNK(parent_info.st_mode)
            or parent_info.st_uid != 0 or parent_info.st_mode & 0o022):
        raise ValueError("retained receipt parent is unsafe")
    fd, temporary = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    try:
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        temporary = ""
        os.chmod(path, 0o600)
        parent_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(parent_fd)
        finally:
            os.close(parent_fd)
    finally:
        if temporary:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass

publish(manifest, encoded)
manifest_sha256 = hashlib.sha256(encoded).hexdigest()
marker_document = {
    "schema": "bridgesllm.retained-install.v1",
    "installerVersion": version,
    "createdAt": datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    "installRoot": str(marker.parent),
    "portalRoot": str(portal),
    "manifestPath": str(manifest),
    "manifestSha256": manifest_sha256,
    "environmentSha256": env_sha256,
}
publish(marker, (json.dumps(marker_document, indent=2, sort_keys=True) + "\n").encode())
PY
}

verify_retained_install_receipt() {
  local portal_dir="${1:-${PORTAL_DIR}}"
  local marker_path="${2:-${RETAINED_INSTALL_MARKER}}"
  local manifest_path="${3:-${RETAINED_INSTALL_MANIFEST}}"
  local allow_runtime_overlay="${4:-false}"
  [[ "${allow_runtime_overlay}" == "true" || "${allow_runtime_overlay}" == "false" ]] \
    || return 1
  [[ -f "${marker_path}" && ! -L "${marker_path}" \
    && -f "${manifest_path}" && ! -L "${manifest_path}" ]] || return 1
  [[ "$(stat -c '%u:%g:%a' "${marker_path}" 2>/dev/null)" == '0:0:600' \
    && "$(stat -c '%u:%g:%a' "${manifest_path}" 2>/dev/null)" == '0:0:600' ]] \
    || return 1
  python3 - "${portal_dir}" "${marker_path}" "${manifest_path}" "${allow_runtime_overlay}" <<'PY'
import hashlib
import json
import os
import pathlib
import stat
import sys

portal = pathlib.Path(sys.argv[1])
marker_path = pathlib.Path(sys.argv[2])
manifest_path = pathlib.Path(sys.argv[3])
allow_runtime_overlay = sys.argv[4] == "true"
try:
    marker_raw = marker_path.read_bytes()
    manifest_raw = manifest_path.read_bytes()
    marker = json.loads(marker_raw)
    manifest = json.loads(manifest_raw)
except (OSError, ValueError, json.JSONDecodeError):
    raise SystemExit(1)
if (
    marker.get("schema") != "bridgesllm.retained-install.v1"
    or marker.get("installRoot") != str(portal.parent)
    or marker.get("portalRoot") != str(portal)
    or marker.get("manifestPath") != str(manifest_path)
    or marker.get("manifestSha256") != hashlib.sha256(manifest_raw).hexdigest()
    or manifest.get("schema") != "bridgesllm.retained-install-tree.v1"
    or manifest.get("portalRoot") != str(portal)
    or not isinstance(manifest.get("entries"), list)
):
    raise SystemExit(1)

expected = manifest["entries"]
if len(expected) > 2_000_000:
    raise SystemExit(1)
observed = []
def retained_path(relative: str) -> bool:
    parts = pathlib.PurePosixPath(relative).parts
    if not parts:
        return False
    if parts[0] in {".data", "apps", "assets", "projects", "upload-temp"}:
        return True
    if parts[0] == "backend":
        return len(parts) == 1 or (len(parts) >= 2 and parts[1] in {".data", ".env", ".env.production"})
    if parts[0] == "frontend":
        return len(parts) == 1 or (len(parts) == 2 and parts[1] == ".env")
    return False

for directory, dirnames, filenames in os.walk(portal, topdown=True, followlinks=False):
    base = pathlib.Path(directory)
    dirnames.sort()
    filenames.sort()
    for name in [*dirnames, *filenames]:
        path = base / name
        relative = path.relative_to(portal).as_posix()
        if allow_runtime_overlay and not retained_path(relative):
            continue
        info = os.lstat(path)
        common = {
            "path": relative,
            "mode": stat.S_IMODE(info.st_mode),
            "uid": info.st_uid,
            "gid": info.st_gid,
        }
        if stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode):
            observed.append({**common, "type": "directory"})
        elif stat.S_ISREG(info.st_mode) and not stat.S_ISLNK(info.st_mode):
            if info.st_nlink != 1:
                raise SystemExit(1)
            digest = hashlib.sha256()
            with path.open("rb", buffering=0) as handle:
                while True:
                    chunk = handle.read(1024 * 1024)
                    if not chunk:
                        break
                    digest.update(chunk)
            final = os.lstat(path)
            if (
                info.st_dev, info.st_ino, info.st_mode, info.st_uid,
                info.st_gid, info.st_size, info.st_mtime_ns,
            ) != (
                final.st_dev, final.st_ino, final.st_mode, final.st_uid,
                final.st_gid, final.st_size, final.st_mtime_ns,
            ):
                raise SystemExit(1)
            observed.append({
                **common,
                "type": "file",
                "size": info.st_size,
                "sha256": digest.hexdigest(),
            })
        elif stat.S_ISLNK(info.st_mode):
            observed.append({**common, "type": "symlink", "target": os.readlink(path)})
            if name in dirnames:
                dirnames.remove(name)
        else:
            raise SystemExit(1)
if sorted(observed, key=lambda entry: entry["path"]) != expected:
    raise SystemExit(1)
env = portal / "backend" / ".env.production"
try:
    env_digest = hashlib.sha256(env.read_bytes()).hexdigest()
except OSError:
    raise SystemExit(1)
if env_digest != marker.get("environmentSha256"):
    raise SystemExit(1)
PY
}

detect_retained_install_reconnect() {
  if [[ ! -e "${RETAINED_INSTALL_MARKER}" && ! -L "${RETAINED_INSTALL_MARKER}" \
    && ! -e "${RETAINED_INSTALL_MANIFEST}" && ! -L "${RETAINED_INSTALL_MANIFEST}" ]]; then
    return 0
  fi
  verify_retained_install_receipt \
    || fail "A retained Portal tree exists, but its root-only reconnect receipt or exact tree manifest no longer matches. Refusing to overlay it."
  RETAINED_RECONNECT_MODE=true
  FORCE_FRESH=true
  info "Verified the exact retained Portal data tree; reconnecting it to the signed runtime."
}

clear_retained_install_receipt() {
  local allow_runtime_overlay="${1:-false}"
  verify_retained_install_receipt \
    "${PORTAL_DIR}" "${RETAINED_INSTALL_MARKER}" "${RETAINED_INSTALL_MANIFEST}" \
    "${allow_runtime_overlay}" || return 1
  rm -f -- "${RETAINED_INSTALL_MARKER}" "${RETAINED_INSTALL_MANIFEST}" || return 1
  [[ ! -e "${RETAINED_INSTALL_MARKER}" && ! -L "${RETAINED_INSTALL_MARKER}" \
    && ! -e "${RETAINED_INSTALL_MANIFEST}" && ! -L "${RETAINED_INSTALL_MANIFEST}" ]]
}

assert_fresh_install_target_available() {
  local portal_dir="${1:-${PORTAL_DIR}}"
  local retained_reconnect="${2:-${RETAINED_RECONNECT_MODE}}"

  if [[ ! -e "${portal_dir}" && ! -L "${portal_dir}" ]]; then
    return 0
  fi

  # detect_retained_install_reconnect() is the only production path that sets
  # this flag, and it does so only after verifying the root-only receipt and
  # exact retained-tree manifest. That attested tree is the expected input to
  # build_portal(); rejecting it here would make Keep Data uninstall permanent.
  if [[ "${retained_reconnect}" == "true" ]]; then
    return 0
  fi

  fail "A partial or unattested Portal path already exists at ${portal_dir}. Refusing to treat it as a fresh host; recover or remove that exact installation deliberately."
}

remove_portal_runtime_preserving_data() {
  local portal_dir="${1:-${PORTAL_DIR}}"
  local expected_portal_dir="${2:-${PORTAL_DIR}}"
  local portal_attestation=""
  portal_attestation="$(python3 - "${portal_dir}" "${expected_portal_dir}" <<'PY'
import os
import stat
import sys

path, expected = sys.argv[1:]
for value in (path, expected):
    if not os.path.isabs(value) or value != os.path.normpath(value) or value == os.path.sep:
        raise SystemExit("Portal runtime path must be a bounded canonical absolute path")
if path != expected:
    raise SystemExit("Portal runtime path does not match the fixed installation boundary")

current = os.path.sep
parts = path.strip(os.path.sep).split(os.path.sep)
for index, component in enumerate(parts):
    current = os.path.join(current, component)
    if not os.path.lexists(current):
        print("absent")
        raise SystemExit(0)
    info = os.lstat(current)
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode) or info.st_uid != 0:
        raise SystemExit("Portal runtime path crosses an unsafe ownership boundary")
    if info.st_mode & 0o022:
        if index == len(parts) - 1 or not info.st_mode & stat.S_ISVTX:
            raise SystemExit("Portal runtime path crosses a writable ownership boundary")

if os.path.realpath(path) != path:
    raise SystemExit("Portal runtime path does not resolve to its fixed boundary")
info = os.lstat(path)
print(f"{info.st_dev}:{info.st_ino}")
PY
)" || return 1
  [[ "${portal_attestation}" != "absent" ]] || return 0

  # Pin the attested directory while preparing rsync and prove the shell did
  # not reopen a different inode. Root-owned non-writable parents prevent an
  # unprivileged rename after this check.
  local portal_fd actual_portal_attestation
  exec {portal_fd}< "${portal_dir}" || return 1
  actual_portal_attestation="$(stat -Lc '%d:%i' "/proc/$$/fd/${portal_fd}" 2>/dev/null)" \
    || { exec {portal_fd}<&-; return 1; }
  [[ "${actual_portal_attestation}" == "${portal_attestation}" ]] \
    || { exec {portal_fd}<&-; return 1; }

  # Empty-source rsync deletes only runtime payload. These exclusions are the
  # same persistent boundaries used by update/reinstall, plus the retained
  # environment needed to reconnect a custom database on the next install.
  local empty_source
  empty_source="$(mktemp -d)"
  mkdir -p "${empty_source}/backend" "${empty_source}/frontend"
  if ! rsync -a --delete \
      --exclude='/projects' \
      --exclude='/apps' \
      --exclude='/assets' \
      --exclude='/upload-temp' \
      --exclude='/.data' \
      --exclude='/backend/.data' \
      --exclude='/backend/.env.production' \
      --exclude='/backend/.env' \
      --exclude='/frontend/.env' \
      "${empty_source}/" "${portal_dir}/"; then
    rm -rf -- "${empty_source}"
    exec {portal_fd}<&-
    return 1
  fi
  rmdir -- "${empty_source}/backend" "${empty_source}/frontend" "${empty_source}" \
    || { exec {portal_fd}<&-; return 1; }
  exec {portal_fd}<&-
}

remove_portal_backup_automation() {
  # Backup automation is Portal runtime, not user data. Leaving these units
  # enabled after either uninstall mode creates dangling timers whose ExecStart
  # points into the removed Portal tree. Stop known instances before removing
  # the exact installer-owned unit files; retained archives and backup settings
  # are deliberately untouched and will be reused on a later install.
  local timer_units=(
    bridgesllm-backup-daily.timer
    bridgesllm-backup-comprehensive.timer
    bridgesllm-backup-monthly.timer
  )
  local service_units=(
    bridgesllm-backup@daily.service
    bridgesllm-backup@comprehensive.service
    bridgesllm-backup@monthly.service
  )

  systemctl disable --now "${timer_units[@]}" >/dev/null 2>&1 || true
  systemctl stop "${service_units[@]}" >/dev/null 2>&1 || true

  # A failed stop cannot be treated as cosmetic before Clean slate removes the
  # database and filesystem. Read back every known unit and refuse to continue
  # while a timer or backup process is active, activating, or deactivating.
  local unit active_state
  for unit in "${timer_units[@]}" "${service_units[@]}"; do
    active_state="$(systemctl show --property=ActiveState --value "${unit}" 2>/dev/null)" \
      || fail "Portal backup unit ${unit} state could not be verified; uninstall was aborted before data removal."
    case "${active_state}" in
      inactive|failed) ;;
      *) fail "Portal backup unit ${unit} did not stop cleanly; uninstall was aborted before data removal." ;;
    esac
  done

  rm -f -- \
    /etc/systemd/system/bridgesllm-backup@.service \
    /etc/systemd/system/bridgesllm-backup-daily.timer \
    /etc/systemd/system/bridgesllm-backup-comprehensive.timer \
    /etc/systemd/system/bridgesllm-backup-monthly.timer \
    /etc/systemd/system/timers.target.wants/bridgesllm-backup-daily.timer \
    /etc/systemd/system/timers.target.wants/bridgesllm-backup-comprehensive.timer \
    /etc/systemd/system/timers.target.wants/bridgesllm-backup-monthly.timer
  systemctl daemon-reload >/dev/null 2>&1 \
    || fail "Systemd could not forget removed Portal backup automation; uninstall was aborted."
  systemctl reset-failed "${service_units[@]}" >/dev/null 2>&1 || true
}

portal_remote_desktop_account_matches_contract() {
  local rd_user="bridgesrd"
  local rd_home="/home/bridgesrd"
  local rd_marker="${rd_home}/.bridgesllm-portal-managed"
  local passwd_entry=""
  passwd_entry="$(getent passwd "${rd_user}" 2>/dev/null || true)"
  [[ -n "${passwd_entry}" ]] || return 1

  local account_name _password account_uid account_gid _gecos account_home account_shell
  IFS=: read -r account_name _password account_uid account_gid _gecos account_home account_shell <<< "${passwd_entry}"
  [[ "${account_name}" == "${rd_user}" \
    && "${account_uid}" =~ ^[0-9]+$ \
    && "${account_gid}" =~ ^[0-9]+$ \
    && ${account_uid} -lt 1000 \
    && "${account_home}" == "${rd_home}" \
    && "${account_shell}" == "/bin/bash" \
    && -d "${rd_home}" \
    && ! -L "${rd_home}" ]] || return 1
  [[ "$(stat -c '%u:%g' "${rd_home}" 2>/dev/null || true)" == "${account_uid}:${account_gid}" ]] \
    || return 1

  if [[ -f "${rd_marker}" && ! -L "${rd_marker}" \
    && "$(stat -c '%u:%g:%a' "${rd_marker}" 2>/dev/null || true)" == '0:0:600' \
    && "$(cat -- "${rd_marker}" 2>/dev/null || true)" == 'managed-by=bridgesllm-portal-remote-desktop-v1' ]]; then
    return 0
  fi

  # Releases predating the ownership marker are still safely attributable when
  # both exact Portal-authored units remain. Refuse account deletion on partial,
  # linked, or administrator-shaped state.
  local vnc_unit="/etc/systemd/system/bridges-rd-xtigervnc.service"
  local websockify_unit="/etc/systemd/system/bridges-rd-websockify.service"
  [[ -f "${vnc_unit}" && ! -L "${vnc_unit}" \
    && -f "${websockify_unit}" && ! -L "${websockify_unit}" ]] || return 1
  grep -Fx 'Description=Bridges Remote Desktop Xtigervnc :1' "${vnc_unit}" >/dev/null 2>&1 \
    && grep -Fx 'ExecStart=/usr/local/bin/bridges-rd-xtigervnc-start.sh' "${vnc_unit}" >/dev/null 2>&1 \
    && grep -Fx 'Description=Bridges Remote Desktop noVNC Websockify' "${websockify_unit}" >/dev/null 2>&1 \
    && grep -Fx 'User=bridgesrd' "${websockify_unit}" >/dev/null 2>&1
}

remove_portal_remote_desktop_launcher_lock() {
  local lock_path="${1:-/var/lib/bridgesllm/remote-desktop-ai-launchers.lock}"
  local lock_fd lock_fd_identity lock_path_identity
  if [[ ! -e "${lock_path}" && ! -L "${lock_path}" ]]; then
    return 0
  fi
  [[ -f "${lock_path}" && ! -L "${lock_path}" ]] \
    || fail "Managed AI launcher lifecycle lock is linked or non-regular; Remote Desktop uninstall was aborted."
  [[ "$(stat -c '%u:%g:%a' "${lock_path}")" == '0:0:600' ]] \
    || fail "Managed AI launcher lifecycle lock is not root-owned mode 0600; Remote Desktop uninstall was aborted."
  exec {lock_fd}<>"${lock_path}" \
    || fail "Managed AI launcher lifecycle lock could not be opened safely; Remote Desktop uninstall was aborted."
  flock -x "${lock_fd}" \
    || fail "Managed AI launcher lifecycle lock could not be acquired; Remote Desktop uninstall was aborted."
  [[ -f "${lock_path}" && ! -L "${lock_path}"
    && "$(stat -c '%u:%g:%a' "${lock_path}")" == '0:0:600' ]] \
    || fail "Managed AI launcher lifecycle lock changed while uninstall waited for it."
  lock_fd_identity="$(stat -Lc '%d:%i' "/proc/$$/fd/${lock_fd}")"
  lock_path_identity="$(stat -Lc '%d:%i' "${lock_path}")"
  [[ "${lock_fd_identity}" == "${lock_path_identity}" ]] \
    || fail "Managed AI launcher lifecycle lock identity changed while uninstall waited for it."
  rm -f -- "${lock_path}"
  [[ ! -e "${lock_path}" && ! -L "${lock_path}" ]] \
    || fail "Managed AI launcher lifecycle lock survived Remote Desktop uninstall."
  exec {lock_fd}>&-
}

remove_portal_remote_desktop_open_handoffs() {
  local production_root='/var/lib/bridgesllm/remote-desktop-open'
  local handoff_root group_entry group_name group_password desktop_gid group_members
  handoff_root="$(update_transaction_state_path "${production_root}")" \
    || fail "Remote Desktop file handoff path could not be bounded safely; uninstall was aborted."
  if [[ ! -e "${handoff_root}" && ! -L "${handoff_root}" ]]; then
    return 0
  fi

  group_entry="$(getent group bridgesrd 2>/dev/null)" \
    || fail "Remote Desktop group identity could not be resolved while file handoffs remain; uninstall was aborted."
  [[ -n "${group_entry}" && "${group_entry}" != *$'\n'* ]] \
    || fail "Remote Desktop group identity is ambiguous while file handoffs remain; uninstall was aborted."
  IFS=: read -r group_name group_password desktop_gid group_members <<< "${group_entry}"
  [[ "${group_name}" == 'bridgesrd' && "${desktop_gid}" =~ ^[1-9][0-9]*$ ]] \
    || fail "Remote Desktop group identity is invalid while file handoffs remain; uninstall was aborted."

  python3 - "${handoff_root}" "${desktop_gid}" <<'PY' \
    || fail "Remote Desktop file handoffs failed exact lifecycle attestation; uninstall was aborted without deleting an unvalidated target."
import os
import re
import stat
import sys

root_path, desktop_gid_text = sys.argv[1:]
desktop_gid = int(desktop_gid_text)
request_pattern = re.compile(r"[a-f0-9]{32}\Z")
directory_flags = (
    os.O_RDONLY
    | getattr(os, "O_DIRECTORY", 0)
    | getattr(os, "O_CLOEXEC", 0)
    | getattr(os, "O_NOFOLLOW", 0)
)
file_flags = (
    os.O_RDONLY
    | getattr(os, "O_CLOEXEC", 0)
    | getattr(os, "O_NOFOLLOW", 0)
)

if (
    os.geteuid() != 0
    or desktop_gid <= 0
    or not os.path.isabs(root_path)
    or os.path.normpath(root_path) != root_path
    or os.path.basename(root_path) != "remote-desktop-open"
):
    raise SystemExit(1)


def inode_identity(details):
    return (
        details.st_dev,
        details.st_ino,
        details.st_mode,
        details.st_nlink,
        details.st_uid,
        details.st_gid,
    )


def stable_directory_identity(details):
    return (
        details.st_dev,
        details.st_ino,
        stat.S_IFMT(details.st_mode),
        stat.S_IMODE(details.st_mode),
        details.st_uid,
        details.st_gid,
    )


def mount_id(descriptor):
    with open(
        f"/proc/self/fdinfo/{descriptor}",
        "r",
        encoding="ascii",
        errors="strict",
    ) as handle:
        for line in handle:
            if line.startswith("mnt_id:\t"):
                value = line.split("\t", 1)[1].strip()
                if value.isdigit():
                    return int(value)
    raise SystemExit(1)


def stat_entry(name, directory_fd):
    return os.stat(name, dir_fd=directory_fd, follow_symlinks=False)


def assert_directory(details, uid, gid, mode, device):
    if (
        not stat.S_ISDIR(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != uid
        or details.st_gid != gid
        or stat.S_IMODE(details.st_mode) != mode
        or details.st_dev != device
    ):
        raise SystemExit(1)


def assert_file(details, gids, mode, device):
    if (
        not stat.S_ISREG(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != 0
        or details.st_gid not in gids
        or stat.S_IMODE(details.st_mode) != mode
        or details.st_nlink != 1
        or details.st_dev != device
    ):
        raise SystemExit(1)


# Every ancestor is root-owned and non-writable before the final parent is
# pinned. That makes the descriptor-relative identity proofs below stable
# against unprivileged rename/rebind attempts.
parent_path = os.path.dirname(root_path)
current = os.path.sep
for component in parent_path.strip(os.path.sep).split(os.path.sep):
    if not component:
        continue
    current = os.path.join(current, component)
    details = os.lstat(current)
    if (
        not stat.S_ISDIR(details.st_mode)
        or stat.S_ISLNK(details.st_mode)
        or details.st_uid != 0
        or details.st_mode & 0o022
    ):
        raise SystemExit(1)

parent_fd = os.open(parent_path, directory_flags)
root_fd = -1
directory_records = []
try:
    root_name = os.path.basename(root_path)
    try:
        root_entry = stat_entry(root_name, parent_fd)
    except FileNotFoundError:
        raise SystemExit(0)
    root_fd = os.open(root_name, directory_flags, dir_fd=parent_fd)
    root_opened = os.fstat(root_fd)
    if inode_identity(root_opened) != inode_identity(root_entry):
        raise SystemExit(1)
    assert_directory(root_opened, 0, desktop_gid, 0o710, root_opened.st_dev)
    root_device = root_opened.st_dev
    if root_device != os.fstat(parent_fd).st_dev or mount_id(root_fd) != mount_id(parent_fd):
        raise SystemExit(1)

    request_names = sorted(os.listdir(root_fd))
    if len(request_names) > 32 or any(not request_pattern.fullmatch(name) for name in request_names):
        raise SystemExit(1)

    # Pin and prove the complete tree before deleting any member. A malformed
    # sibling therefore cannot turn a partial cleanup into guessed ownership.
    for request_name in request_names:
        request_entry = stat_entry(request_name, root_fd)
        request_fd = os.open(request_name, directory_flags, dir_fd=root_fd)
        request_opened = os.fstat(request_fd)
        try:
            if inode_identity(request_opened) != inode_identity(request_entry):
                raise SystemExit(1)
            assert_directory(request_opened, 0, desktop_gid, 0o750, root_device)
            if mount_id(request_fd) != mount_id(root_fd):
                raise SystemExit(1)

            file_names = sorted(os.listdir(request_fd))
            if len(file_names) > 2:
                raise SystemExit(1)
            snapshot_names = [name for name in file_names if name != ".reservation"]
            if len(snapshot_names) > 1:
                raise SystemExit(1)

            file_records = []
            reservation_bytes = None
            snapshot_details = None
            for file_name in file_names:
                is_reservation = file_name == ".reservation"
                expected_gids = (
                    {0}
                    if is_reservation
                    else ({0, desktop_gid} if ".reservation" in file_names else {desktop_gid})
                )
                expected_mode = 0o400 if file_name == ".reservation" else 0o440
                file_entry = stat_entry(file_name, request_fd)
                file_fd = os.open(file_name, file_flags, dir_fd=request_fd)
                file_opened = os.fstat(file_fd)
                try:
                    if inode_identity(file_opened) != inode_identity(file_entry):
                        raise SystemExit(1)
                    assert_file(file_opened, expected_gids, expected_mode, root_device)
                    if mount_id(file_fd) != mount_id(root_fd):
                        raise SystemExit(1)
                    if is_reservation:
                        payload = os.read(file_fd, 16)
                        if os.read(file_fd, 1):
                            raise SystemExit(1)
                        try:
                            reservation_text = payload.decode("ascii")
                        except UnicodeDecodeError:
                            raise SystemExit(1)
                        if not re.fullmatch(r"0|[1-9][0-9]*", reservation_text):
                            raise SystemExit(1)
                        reservation_bytes = int(reservation_text)
                        if reservation_bytes > 256 * 1024 * 1024:
                            raise SystemExit(1)
                    else:
                        snapshot_details = file_opened
                        if snapshot_details.st_size > 256 * 1024 * 1024:
                            raise SystemExit(1)
                    file_records.append((file_name, file_fd, inode_identity(file_opened)))
                    file_fd = -1
                finally:
                    if file_fd >= 0:
                        os.close(file_fd)
            if snapshot_details is not None and reservation_bytes is not None:
                if (
                    snapshot_details.st_gid == 0
                    and snapshot_details.st_size > reservation_bytes
                ) or (
                    snapshot_details.st_gid == desktop_gid
                    and snapshot_details.st_size != reservation_bytes
                ):
                    raise SystemExit(1)
            directory_records.append((
                request_name,
                request_fd,
                stable_directory_identity(request_opened),
                file_records,
            ))
            request_fd = -1
        finally:
            if request_fd >= 0:
                os.close(request_fd)

    # Revalidate the full pinned tree once more before the first unlink. The
    # per-entry check immediately before each mutation then catches a late
    # replacement without ever following it.
    if inode_identity(stat_entry(root_name, parent_fd)) != inode_identity(root_opened):
        raise SystemExit(1)
    for request_name, request_fd, request_identity, file_records in directory_records:
        if stable_directory_identity(stat_entry(request_name, root_fd)) != request_identity:
            raise SystemExit(1)
        if stable_directory_identity(os.fstat(request_fd)) != request_identity:
            raise SystemExit(1)
        for file_name, file_fd, file_identity in file_records:
            if inode_identity(stat_entry(file_name, request_fd)) != file_identity:
                raise SystemExit(1)
            if inode_identity(os.fstat(file_fd)) != file_identity:
                raise SystemExit(1)

    for request_name, request_fd, request_identity, file_records in directory_records:
        for file_name, file_fd, file_identity in file_records:
            if (
                inode_identity(stat_entry(file_name, request_fd)) != file_identity
                or inode_identity(os.fstat(file_fd)) != file_identity
            ):
                raise SystemExit(1)
            os.unlink(file_name, dir_fd=request_fd)
            if os.fstat(file_fd).st_nlink != 0:
                raise SystemExit(1)
            os.close(file_fd)
        os.fsync(request_fd)
        if os.listdir(request_fd):
            raise SystemExit(1)
        if (
            stable_directory_identity(stat_entry(request_name, root_fd))
            != request_identity
            or stable_directory_identity(os.fstat(request_fd))
            != request_identity
        ):
            raise SystemExit(1)
        os.rmdir(request_name, dir_fd=root_fd)
        os.close(request_fd)

    os.fsync(root_fd)
    if os.listdir(root_fd):
        raise SystemExit(1)
    if (
        stable_directory_identity(stat_entry(root_name, parent_fd))
        != stable_directory_identity(root_opened)
        or stable_directory_identity(os.fstat(root_fd))
        != stable_directory_identity(root_opened)
    ):
        raise SystemExit(1)
    os.rmdir(root_name, dir_fd=parent_fd)
    os.fsync(parent_fd)
    try:
        stat_entry(root_name, parent_fd)
    except FileNotFoundError:
        pass
    else:
        raise SystemExit(1)
finally:
    for _request_name, request_fd, _request_identity, file_records in directory_records:
        for _file_name, file_fd, _file_identity in file_records:
            try:
                os.close(file_fd)
            except OSError:
                pass
        try:
            os.close(request_fd)
        except OSError:
            pass
    if root_fd >= 0:
        os.close(root_fd)
    os.close(parent_fd)
PY
}

portal_remote_desktop_watchdog_runtime_absent() {
  [[ ! -e /run/bridges-rd && ! -L /run/bridges-rd ]]
}

remove_portal_remote_desktop_runtime() {
  local data_choice="${1:-1}"
  [[ "${data_choice}" == "1" || "${data_choice}" == "2" ]] \
    || fail "Invalid Remote Desktop uninstall data choice; expected 1 or 2."

  local rd_user="bridgesrd"
  local rd_account_is_managed=false
  # Account ownership governs the process boundary in both uninstall modes.
  # Keep Data preserves the profile, but detached XFCE/browser processes owned
  # by an attested Portal account must not outlive the removed services. A
  # foreign or drifted bridgesrd identity remains completely untouched.
  if portal_remote_desktop_account_matches_contract; then
    rd_account_is_managed=true
  fi

  # Stop the out-of-process watchdog first so it cannot race teardown by
  # restarting a Remote Desktop unit while uninstall is removing its files.
  local rd_health_units=(
    bridges-rd-healthcheck.timer
    bridges-rd-healthcheck.service
  )
  systemctl disable --now bridges-rd-healthcheck.timer >/dev/null 2>&1 || true
  systemctl stop "${rd_health_units[@]}" >/dev/null 2>&1 || true
  systemctl kill --kill-who=all bridges-rd-healthcheck.service >/dev/null 2>&1 || true

  local rd_unit rd_unit_state rd_unit_load_state
  for rd_unit in "${rd_health_units[@]}"; do
    rd_unit_load_state="$(systemctl show --property=LoadState --value "${rd_unit}" 2>/dev/null)" \
      || fail "Remote Desktop watchdog unit ${rd_unit} load state could not be verified; uninstall was aborted before files or accounts were removed."
    rd_unit_state="$(systemctl show --property=ActiveState --value "${rd_unit}" 2>/dev/null)" \
      || fail "Remote Desktop watchdog unit ${rd_unit} active state could not be verified; uninstall was aborted before files or accounts were removed."
    case "${rd_unit_state}" in
      inactive|failed) ;;
      *) fail "Remote Desktop watchdog unit ${rd_unit} is still ${rd_unit_state:-unknown} (${rd_unit_load_state:-unknown}); uninstall was aborted before files or accounts were removed." ;;
    esac
  done

  local rd_units=(
    bridges-rd-xtigervnc.service
    bridges-rd-websockify.service
    bridges-rd-vnc.service
  )
  systemctl disable --now "${rd_units[@]}" >/dev/null 2>&1 || true
  systemctl stop "${rd_units[@]}" >/dev/null 2>&1 || true
  systemctl kill --kill-who=all "${rd_units[@]}" >/dev/null 2>&1 || true
  for rd_unit in "${rd_units[@]}"; do
    rd_unit_load_state="$(systemctl show --property=LoadState --value "${rd_unit}" 2>/dev/null)" \
      || fail "Remote Desktop unit ${rd_unit} load state could not be verified; uninstall was aborted before files or accounts were removed."
    rd_unit_state="$(systemctl show --property=ActiveState --value "${rd_unit}" 2>/dev/null)" \
      || fail "Remote Desktop unit ${rd_unit} active state could not be verified; uninstall was aborted before files or accounts were removed."
    case "${rd_unit_state}" in
      inactive|failed) ;;
      *) fail "Remote Desktop unit ${rd_unit} is still ${rd_unit_state:-unknown} (${rd_unit_load_state:-unknown}); uninstall was aborted before files or accounts were removed." ;;
    esac
  done

  if pgrep -f '/usr/local/bin/bridges-rd-healthcheck\.sh|/usr/local/bin/bridges-rd-xtigervnc-start\.sh|/usr/local/bin/bridges-rd-session-guard\.sh|/usr/bin/Xtigervnc[[:space:]]+:1([[:space:]]|$)|/usr/bin/websockify([[:space:]].*)?127\.0\.0\.1:6080([[:space:]]|$)' >/dev/null 2>&1; then
    fail "Remote Desktop host processes are still running; uninstall was aborted before files or accounts were removed."
  fi

  # A uid-wide kill crosses the service boundary and is safe only after the
  # account itself passed the Portal ownership contract. Exact managed service
  # processes were already stopped and attested above. Preserve every process
  # and home file belonging to an unattested/foreign bridgesrd account.
  if [[ "${rd_account_is_managed}" == "true" ]] && id "${rd_user}" >/dev/null 2>&1; then
    local rd_process_status=0
    if pkill -TERM -u "${rd_user}" >/dev/null 2>&1; then
      :
    else
      rd_process_status=$?
      [[ ${rd_process_status} -eq 1 ]] \
        || fail "Remote Desktop user processes could not be signaled safely; uninstall was aborted before files or accounts were removed."
    fi
    local wait_attempt rd_processes_remain=false
    for wait_attempt in 1 2 3 4 5; do
      if pgrep -u "${rd_user}" >/dev/null 2>&1; then
        rd_processes_remain=true
      else
        rd_process_status=$?
        [[ ${rd_process_status} -eq 1 ]] \
          || fail "Remote Desktop user process state could not be verified; uninstall was aborted before files or accounts were removed."
        rd_processes_remain=false
        break
      fi
      sleep 0.2
    done
    if [[ "${rd_processes_remain}" == "true" ]]; then
      if pkill -KILL -u "${rd_user}" >/dev/null 2>&1; then
        :
      else
        rd_process_status=$?
        [[ ${rd_process_status} -eq 1 ]] \
          || fail "Remote Desktop user processes could not be force-stopped safely; uninstall was aborted before files or accounts were removed."
      fi
    fi
    if pgrep -u "${rd_user}" >/dev/null 2>&1; then
      fail "Remote Desktop user processes are still running; uninstall was aborted before files or accounts were removed."
    else
      rd_process_status=$?
      [[ ${rd_process_status} -eq 1 ]] \
        || fail "Remote Desktop user process convergence could not be verified; uninstall was aborted before files or accounts were removed."
    fi
  fi

  # Portal was fenced and stopped before this lifecycle phase. The exact RD
  # units and, for an attested account, every bridgesrd process are now also
  # proven stopped, so no product writer can race removal of ephemeral file
  # handoffs. Both uninstall modes remove these runtime-only snapshots.
  remove_portal_remote_desktop_open_handoffs

  local ai_provider_launcher='/usr/local/bin/bridges-rd-ai-launchers.sh'
  if [[ "${rd_account_is_managed}" == "true" ]]; then
    if [[ -f "${ai_provider_launcher}" && ! -L "${ai_provider_launcher}" ]]; then
      local ai_remove_args=(remove)
      [[ "${data_choice}" == '2' ]] && ai_remove_args+=(--purge-profiles)
      "${ai_provider_launcher}" "${ai_remove_args[@]}" >/dev/null \
        || fail "Managed AI provider Remote Desktop launchers could not be removed safely."
    fi
    remove_portal_remote_desktop_launcher_lock
  fi

  rm -f -- \
    /etc/systemd/system/bridges-rd-healthcheck.service \
    /etc/systemd/system/bridges-rd-healthcheck.timer \
    /etc/systemd/system/bridges-rd-xtigervnc.service \
    /etc/systemd/system/bridges-rd-websockify.service \
    /etc/systemd/system/bridges-rd-vnc.service \
    /etc/systemd/system/timers.target.wants/bridges-rd-healthcheck.timer \
    /etc/systemd/system/multi-user.target.wants/bridges-rd-xtigervnc.service \
    /etc/systemd/system/multi-user.target.wants/bridges-rd-websockify.service \
    /etc/systemd/system/multi-user.target.wants/bridges-rd-vnc.service \
    /usr/local/bin/bridges-rd-web-open.sh \
    /usr/local/bin/bridges-rd-shared-chrome.sh \
    /usr/local/bin/bridges-rd-openclaw-ui.sh \
    /usr/local/bin/bridges-rd-ai-launchers.sh \
    /usr/local/bin/bridges-rd-websockify-launcher.sh \
    /usr/local/bin/bridges-rd-healthcheck.sh \
    /usr/local/bin/bridges-rd-xtigervnc-start.sh \
    /usr/local/bin/bridges-rd-session-guard.sh \
    /usr/local/bin/bridges-rd-window-fit.sh \
    /usr/local/share/pixmaps/bridges-shared-browser.svg \
    /usr/local/share/pixmaps/bridges-openclaw-ui.svg
  if [[ "${data_choice}" == "2" && "${rd_account_is_managed}" == "true" ]]; then
    rm -f -- \
      "/home/${rd_user}/Desktop/Shared Chrome.desktop" \
      "/home/${rd_user}/Desktop/OpenClaw Web UI.desktop" \
      "/home/${rd_user}/.bridges-rd-env" \
      "/home/${rd_user}/.Xauthority"
  fi
  rm -rf -- /tmp/bridges-rd-runtime /run/bridges-rd
  rm -f -- /run/lock/bridges-rd-healthcheck.lock
  portal_remote_desktop_watchdog_runtime_absent \
    || fail "Remote Desktop watchdog runtime state could not be removed safely."
  systemctl daemon-reload >/dev/null 2>&1 \
    || fail "Systemd could not forget removed Remote Desktop units; uninstall was aborted."
  for rd_unit in "${rd_health_units[@]}"; do
    rd_unit_load_state="$(systemctl show --property=LoadState --value "${rd_unit}" 2>/dev/null)" \
      || fail "Removed Remote Desktop watchdog unit ${rd_unit} could not be re-inspected."
    [[ "${rd_unit_load_state}" == "not-found" ]] \
      || fail "Remote Desktop watchdog unit ${rd_unit} still has load state ${rd_unit_load_state:-unknown} after removal."
  done
  systemctl reset-failed "${rd_health_units[@]}" "${rd_units[@]}" >/dev/null 2>&1 || true
  systemctl unmask \
    tigervncserver@:1.service tigervncserver@1.service \
    vncserver@:1.service vncserver@1.service >/dev/null 2>&1 || true

  if [[ "${data_choice}" == "2" ]]; then
    if [[ "${rd_account_is_managed}" == "true" ]]; then
      rm -rf -- /var/log/bridges-rd
      userdel --remove "${rd_user}" >/dev/null 2>&1 \
        || fail "Portal-owned Remote Desktop account could not be removed safely."
      if getent group "${rd_user}" >/dev/null 2>&1; then
        groupdel "${rd_user}" >/dev/null 2>&1 || true
      fi
      ok "Portal-owned Remote Desktop account and profile removed"
    elif id "${rd_user}" >/dev/null 2>&1; then
      warn "The bridgesrd account did not match Portal ownership safeguards; its home was preserved."
    fi
  fi
}

assert_no_managed_project_runtime_residuals() {
  local query kind selector residuals name
  local queries=(
    'container|com.bridgesllm.project-egress.runtime-fingerprint'
    'container|com.bridgesllm.project-egress.policy'
    'container|com.bridgesllm.project-workload.policy'
    'container|com.bridgesllm.ollama-project.policy'
    'container|com.bridgesllm.project-runtime=true'
    'container|com.bridgesllm.project-git=true'
    'container|io.bridgesllm.managed=agent-zero-project'
    'volume|io.bridgesllm.managed=agent-zero-project'
    'network|io.bridgesllm.managed=agent-zero-project'
    'network|com.bridgesllm.project-egress.policy'
  )
  for query in "${queries[@]}"; do
    IFS='|' read -r kind selector <<<"${query}"
    case "${kind}" in
      container)
        residuals="$(docker container ls --all --quiet --filter "label=${selector}" 2>/dev/null)" \
          || fail "Docker project-container state could not be authoritatively inspected."
        ;;
      volume)
        residuals="$(docker volume ls --quiet --filter "label=${selector}" 2>/dev/null)" \
          || fail "Docker project-volume state could not be authoritatively inspected."
        ;;
      network)
        residuals="$(docker network ls --quiet --filter "label=${selector}" 2>/dev/null)" \
          || fail "Docker project-network state could not be authoritatively inspected."
        ;;
      *) fail "Internal project-runtime residual query was invalid." ;;
    esac
    [[ -z "${residuals//[[:space:]]/}" ]] \
      || fail "Managed project resources remain but their cleanup helper is unavailable; clean-slate uninstall was aborted."
  done

  # Labels are ownership evidence, but cannot be the only discovery key: a
  # crashed or partially migrated runtime can retain an exact reserved Portal
  # name after its labels or database identity disappear. Enumerate every
  # Docker namespace read-only and fail closed on only the exact deterministic
  # product shapes. The signed preflight performs attested cleanup on the first
  # run; a helperless repeat never guesses that a name-shaped resource is safe
  # to delete.
  residuals="$(docker container ls --all --format '{{.Names}}' 2>/dev/null)" \
    || fail "Docker container names could not be authoritatively inspected for project residue."
  while IFS= read -r name; do
    [[ -z "${name}" ]] && continue
    if [[ "${name}" =~ ^p4e-proxy-[a-f0-9]{20}$ \
      || "${name}" =~ ^p4ol-[a-f0-9]{24}$ \
      || "${name}" =~ ^p4cx-[a-f0-9]{24}$ \
      || "${name}" =~ ^p4cc-[a-f0-9]{24}$ \
      || "${name}" =~ ^p4ag-[a-f0-9]{24}$ \
      || "${name}" =~ ^p4oc-[a-f0-9]{16}-[a-z0-9._-]{1,32}-[a-f0-9]{8}$ \
      || "${name}" =~ ^bridgesllm-a0p-[a-f0-9]{24}$ \
      || "${name}" =~ ^bridgesllm-project-(app|job|git)-[a-f0-9]{20}$ ]]; then
      fail "Reserved Portal project container residue remains but its cleanup helper is unavailable."
    fi
  done <<<"${residuals}"

  residuals="$(docker network ls --format '{{.Name}}' 2>/dev/null)" \
    || fail "Docker network names could not be authoritatively inspected for project residue."
  while IFS= read -r name; do
    [[ -z "${name}" ]] && continue
    if [[ "${name}" =~ ^p4e-(in|out)-[a-f0-9]{20}$ ]]; then
      fail "Reserved Portal project network residue remains but its cleanup helper is unavailable."
    fi
  done <<<"${residuals}"

  residuals="$(docker volume ls --format '{{.Name}}' 2>/dev/null)" \
    || fail "Docker volume names could not be authoritatively inspected for project residue."
  while IFS= read -r name; do
    [[ -z "${name}" ]] && continue
    if [[ "${name}" =~ ^bridgesllm-a0p-[a-f0-9]{24}-usr$ ]]; then
      fail "Reserved Portal project volume residue remains but its cleanup helper is unavailable."
    fi
  done <<<"${residuals}"

  # A repeat Clean slate can continue without the deleted helper only after a
  # global host-firewall scan proves that neither exact Portal signatures nor
  # ambiguous Portal-shaped chains remain. The first run removes these through
  # the signed TypeScript preflight; this is deliberately verification-only.
  local firewall_tool firewall_rules
  for firewall_tool in iptables ip6tables; do
    command -v "${firewall_tool}" >/dev/null 2>&1 \
      || fail "${firewall_tool} is unavailable; project firewall cleanup could not be verified."
    firewall_rules="$(${firewall_tool} -w -S 2>/dev/null)" \
      || fail "${firewall_tool} project firewall state could not be authoritatively inspected."
    if grep -E -- '(^-N (P4E-|A0P-)[A-Za-z0-9_.:-]+$)|( --comment "?(p4e-v1|a0p-v3):[a-f0-9]{64}:[a-f0-9]{64}"?( |$))|( -[jg] (P4E-|A0P-)[A-Za-z0-9_.:-]+( |$))' \
        <<<"${firewall_rules}" >/dev/null; then
      fail "Managed or ambiguous project firewall residue remains; clean-slate uninstall was aborted."
    fi
  done
}

quiesce_managed_project_runtime_containers() {
  command -v docker >/dev/null 2>&1 || fail "Docker is unavailable; retained Project runtimes could not be stopped safely."
  python3 - <<'PY'
import json
import re
import subprocess

DOCKER = "/usr/bin/docker"
selectors = {
    "com.bridgesllm.project-egress.policy": {"portal-project-egress-v1"},
    "com.bridgesllm.project-workload.policy": {"portal-project-workload-v1"},
    "com.bridgesllm.ollama-project.policy": {"portal-ollama-project-sandbox-v1"},
    "com.bridgesllm.project-runtime": {"true"},
    "com.bridgesllm.project-git": {"true"},
    "io.bridgesllm.managed": {"agent-zero-project"},
}

def run(args, *, allow=(0,)):
    result = subprocess.run(
        [DOCKER, *args],
        check=False,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=60,
        env={"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"},
    )
    if result.returncode not in allow:
        raise RuntimeError("Docker command failed")
    return result.stdout

identifiers = [line.strip() for line in run(
    ["container", "ls", "--all", "--no-trunc", "--format", "{{.ID}}"],
).splitlines() if line.strip()]
managed = []
for identifier in identifiers:
    if not re.fullmatch(r"[a-f0-9]{64}", identifier):
        raise RuntimeError("Docker returned an invalid container identity")
    raw = run(["container", "inspect", identifier])
    payload = json.loads(raw)
    if not isinstance(payload, list) or len(payload) != 1 or not isinstance(payload[0], dict):
        raise RuntimeError("Docker inspection was ambiguous")
    container = payload[0]
    labels = ((container.get("Config") or {}).get("Labels") or {})
    if not isinstance(labels, dict):
        raise RuntimeError("Docker labels were invalid")
    claims = [(key, labels.get(key)) for key in selectors if key in labels]
    runtime_fingerprint = labels.get("com.bridgesllm.project-egress.runtime-fingerprint")
    if runtime_fingerprint is not None and (
        not isinstance(runtime_fingerprint, str)
        or not re.fullmatch(r"[a-f0-9]{64}", runtime_fingerprint)
    ):
        raise RuntimeError("Project runtime fingerprint is invalid")
    if not claims and runtime_fingerprint is None:
        continue
    if claims and not any(value in selectors[key] for key, value in claims):
        raise RuntimeError("Portal-shaped Project labels contradict the managed runtime contract")
    # Every recognized ownership label present must carry its exact product
    # value. This prevents a foreign/drifted container from being stopped just
    # because it copied one reserved key.
    if any(value not in selectors[key] for key, value in claims):
        raise RuntimeError("Project runtime ownership labels are inconsistent")
    name = str(container.get("Name") or "").lstrip("/")
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", name):
        raise RuntimeError("Managed Project container name is invalid")
    managed.append((identifier, name, bool((container.get("State") or {}).get("Running"))))

for identifier, _name, running in managed:
    if running:
        run(["container", "stop", "--time", "30", identifier])
for identifier, _name, _running in managed:
    raw = run(["container", "inspect", identifier])
    payload = json.loads(raw)
    if bool(((payload[0].get("State") or {}).get("Running"))):
        raise RuntimeError("Managed Project container did not remain stopped")
print(f"Stopped {sum(1 for _identifier, _name, running in managed if running)} managed Project container(s); retained data and identities were preserved.")
PY
}

quiesce_project_runtimes_preserving_data() {
  info "Stopping managed Project runtimes while retaining sources, sessions, and identities..."
  quiesce_managed_project_runtime_containers \
    || fail "Managed Project runtimes could not be stopped without crossing their exact ownership boundary."
  local agent_zero_helper="${PORTAL_DIR}/installer/agent-zero-runtime.sh"
  if [[ -f "${agent_zero_helper}" && ! -L "${agent_zero_helper}" ]]; then
    bash "${agent_zero_helper}" quiesce \
      || fail "Managed Agent Zero could not be stopped while preserving its data."
  elif [[ -e "${agent_zero_helper}" || -L "${agent_zero_helper}" ]]; then
    fail "Agent Zero lifecycle helper is unsafe; retained-data uninstall was aborted."
  fi
}

# Keep Data stops managed runtimes for a safe teardown; the pre-quiesce
# running set is the user's runtime-running intent and must survive to the
# reconnect. First writer wins: a resumed phase re-run observes containers the
# earlier attempt already stopped and must not overwrite the original record.
record_retained_runtime_intent() {
  local intent_file="${PORTAL_DIR}/backend/.data/retained-runtime-intent.json"
  local agent_zero_running="false"
  local agent_zero_helper="${PORTAL_DIR}/installer/agent-zero-runtime.sh"
  if [[ -f "${agent_zero_helper}" && ! -L "${agent_zero_helper}" ]]; then
    agent_zero_running="$(bash "${agent_zero_helper}" runtime-active)" \
      || fail "Agent Zero running state could not be recorded before quiescence."
    [[ "${agent_zero_running}" == "true" || "${agent_zero_running}" == "false" ]] \
      || fail "Agent Zero running state was unreadable before quiescence."
  fi
  python3 - "${intent_file}" "${agent_zero_running}" <<'PY' \
    || fail "The retained runtime-running intent could not be recorded before quiescence."
import datetime
import json
import os
import re
import stat
import subprocess
import sys

target, agent_zero_running = sys.argv[1:]
if os.geteuid() != 0 or agent_zero_running not in {"true", "false"}:
    raise SystemExit(1)
try:
    existing = os.lstat(target)
except FileNotFoundError:
    existing = None
if existing is not None:
    if (not stat.S_ISREG(existing.st_mode) or stat.S_ISLNK(existing.st_mode)
            or existing.st_uid != 0 or existing.st_mode & 0o022):
        raise SystemExit("retained runtime intent already exists but is unsafe")
    raise SystemExit(0)
directory = os.path.dirname(target)
os.makedirs(directory, mode=0o700, exist_ok=True)
info = os.lstat(directory)
if (not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0 or info.st_mode & 0o022):
    raise SystemExit("retained runtime intent directory is unsafe")

DOCKER = "/usr/bin/docker"
selectors = {
    "com.bridgesllm.project-egress.policy": {"portal-project-egress-v1"},
    "com.bridgesllm.project-workload.policy": {"portal-project-workload-v1"},
    "com.bridgesllm.ollama-project.policy": {"portal-ollama-project-sandbox-v1"},
    "com.bridgesllm.project-runtime": {"true"},
    "com.bridgesllm.project-git": {"true"},
    "io.bridgesllm.managed": {"agent-zero-project"},
}

def run(arguments):
    result = subprocess.run(
        [DOCKER, *arguments], check=False, text=True,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60,
        env={"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"},
    )
    if result.returncode != 0:
        raise RuntimeError("Docker command failed")
    return result.stdout

running = []
if os.path.exists(DOCKER):
    for identifier in run(["container", "ls", "--no-trunc", "--format", "{{.ID}}"]).splitlines():
        identifier = identifier.strip()
        if not identifier:
            continue
        if not re.fullmatch(r"[a-f0-9]{64}", identifier):
            raise RuntimeError("Docker returned an invalid container identity")
        payload = json.loads(run(["container", "inspect", identifier]))
        if not isinstance(payload, list) or len(payload) != 1:
            raise RuntimeError("Docker inspection was ambiguous")
        container = payload[0]
        labels = ((container.get("Config") or {}).get("Labels") or {})
        claims = [(key, labels.get(key)) for key in selectors if key in labels]
        runtime_fingerprint = labels.get("com.bridgesllm.project-egress.runtime-fingerprint")
        if runtime_fingerprint is not None and (
            not isinstance(runtime_fingerprint, str)
            or not re.fullmatch(r"[a-f0-9]{64}", runtime_fingerprint)
        ):
            raise RuntimeError("Project runtime fingerprint is invalid")
        if not claims and runtime_fingerprint is None:
            continue
        if any(value not in selectors[key] for key, value in claims):
            raise RuntimeError("Project runtime labels contradict the managed contract")
        if bool((container.get("State") or {}).get("Running")):
            running.append(identifier)

document = {
    "schema": "bridgesllm.retained-runtime-intent.v1",
    "recordedAt": datetime.datetime.now(datetime.timezone.utc)
        .replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    "projectContainers": sorted(running),
    "agentZeroRunning": agent_zero_running == "true",
}
descriptor = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
    json.dump(document, handle, indent=2, sort_keys=True)
    handle.write("\n")
    handle.flush()
    os.fsync(handle.fileno())
directory_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
try:
    os.fsync(directory_fd)
finally:
    os.close(directory_fd)
PY
}

# Retire the reconnect intent as a durable directory-entry update. The file
# contains no reusable credential, but resurrecting it after a crash could
# restart an old runtime set during a later repair.
durably_remove_retained_runtime_intent() {
  local intent_file="${PORTAL_DIR}/backend/.data/retained-runtime-intent.json"
  python3 - "${intent_file}" "${PORTAL_DIR}/backend/.data" <<'PY'
import os
import stat
import sys

path, expected_parent = sys.argv[1:]
if (
    not os.path.isabs(path)
    or os.path.normpath(path) != path
    or os.path.dirname(path) != expected_parent
    or os.path.basename(path) != "retained-runtime-intent.json"
):
    raise SystemExit(1)
parent = os.lstat(expected_parent)
if (
    not stat.S_ISDIR(parent.st_mode)
    or stat.S_ISLNK(parent.st_mode)
    or parent.st_uid != 0
    or parent.st_gid != 0
    or parent.st_mode & 0o022
):
    raise SystemExit(1)
try:
    os.unlink(path)
except FileNotFoundError:
    pass
directory_fd = os.open(expected_parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
try:
    os.fsync(directory_fd)
finally:
    os.close(directory_fd)
PY
}

# Reconnect restores the recorded intent explicitly but never fails the
# install over it: a runtime that disappeared or whose ownership labels
# drifted is reported and skipped, and the Portal's own boot attestation
# remains the authority over what may keep running afterwards.
restore_retained_runtime_intent() {
  local intent_file="${PORTAL_DIR}/backend/.data/retained-runtime-intent.json"
  [[ -e "${intent_file}" || -L "${intent_file}" ]] || return 0
  if [[ ! -f "${intent_file}" || -L "${intent_file}" ]]; then
    warn "Retained runtime-running intent is not a regular file; no runtime was started from it."
    durably_remove_retained_runtime_intent \
      || warn "The rejected retained runtime intent could not be removed durably."
    return 0
  fi
  local summary
  if ! summary="$(python3 - "${intent_file}" <<'PY'
import json
import os
import re
import stat
import subprocess
import sys

path = sys.argv[1]
info = os.lstat(path)
if (not stat.S_ISREG(info.st_mode) or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0 or info.st_mode & 0o022
        or info.st_size <= 0 or info.st_size > 65536):
    raise SystemExit("retained runtime intent is unsafe")
document = json.load(open(path, "r", encoding="utf-8"))
containers = document.get("projectContainers")
agent_zero = document.get("agentZeroRunning")
if (document.get("schema") != "bridgesllm.retained-runtime-intent.v1"
        or not isinstance(containers, list) or len(containers) > 256
        or not all(isinstance(item, str) and re.fullmatch(r"[a-f0-9]{64}", item)
                   for item in containers)
        or len(set(containers)) != len(containers)
        or not isinstance(agent_zero, bool)):
    raise SystemExit("retained runtime intent is invalid")

DOCKER = "/usr/bin/docker"
selectors = {
    "com.bridgesllm.project-egress.policy": {"portal-project-egress-v1"},
    "com.bridgesllm.project-workload.policy": {"portal-project-workload-v1"},
    "com.bridgesllm.ollama-project.policy": {"portal-ollama-project-sandbox-v1"},
    "com.bridgesllm.project-runtime": {"true"},
    "com.bridgesllm.project-git": {"true"},
    "io.bridgesllm.managed": {"agent-zero-project"},
}

def run(arguments, tolerate=False):
    result = subprocess.run(
        [DOCKER, *arguments], check=False, text=True,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60,
        env={"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"},
    )
    if result.returncode != 0 and not tolerate:
        raise RuntimeError("Docker command failed")
    return result.returncode, result.stdout

started = already = missing = drifted = failed = 0
if containers and not os.path.exists(DOCKER):
    missing = len(containers)
    containers = []
for identifier in containers:
    status, raw = run(["container", "inspect", identifier], tolerate=True)
    if status != 0:
        missing += 1
        continue
    payload = json.loads(raw)
    if not isinstance(payload, list) or len(payload) != 1:
        drifted += 1
        continue
    container = payload[0]
    labels = ((container.get("Config") or {}).get("Labels") or {})
    claims = [(key, labels.get(key)) for key in selectors if key in labels]
    runtime_fingerprint = labels.get("com.bridgesllm.project-egress.runtime-fingerprint")
    if runtime_fingerprint is not None and (
        not isinstance(runtime_fingerprint, str)
        or not re.fullmatch(r"[a-f0-9]{64}", runtime_fingerprint)
    ):
        drifted += 1
        continue
    if (
        (not claims and runtime_fingerprint is None)
        or any(value not in selectors[key] for key, value in claims)
    ):
        drifted += 1
        continue
    if bool((container.get("State") or {}).get("Running")):
        already += 1
        continue
    status, _raw = run(["container", "start", identifier], tolerate=True)
    if status == 0:
        started += 1
    else:
        failed += 1
print(
    f"started={started} already={already} missing={missing} "
    f"drifted={drifted} failed={failed} agentZero={'true' if agent_zero else 'false'}"
)
PY
)"; then
    warn "Retained runtime-running intent could not be applied; no runtime was started from it."
    durably_remove_retained_runtime_intent \
      || warn "The rejected retained runtime intent could not be removed durably."
    return 0
  fi
  info "Retained runtime intent: ${summary%% agentZero=*}"
  if [[ "${summary}" != *"missing=0"* || "${summary}" != *"drifted=0"* || "${summary}" != *"failed=0"* ]]; then
    warn "Some previously running Project runtimes were not restored (${summary%% agentZero=*}); they will be rebuilt on demand."
  fi
  if [[ "${summary}" == *"agentZero=true"* ]]; then
    local agent_zero_helper="${PORTAL_DIR}/installer/agent-zero-runtime.sh"
    if [[ -f "${agent_zero_helper}" && ! -L "${agent_zero_helper}" ]]; then
      bash "${agent_zero_helper}" resume \
        || warn "The managed Agent Zero runtime did not resume; it can be reconciled from Settings."
    else
      warn "Agent Zero was running before uninstall but its lifecycle helper is unavailable; it was not restarted."
    fi
  fi
  durably_remove_retained_runtime_intent \
    || warn "The applied retained runtime intent could not be retired durably; it will be rechecked on the next repair."
}

run_project_runtime_clean_slate_preflight() {
  local portal_dir="${1:-${PORTAL_DIR}}"
  local preflight="${portal_dir}/backend/dist/cli/projectRuntimeUninstallPreflight.js"
  local env_file="${portal_dir}/backend/.env.production"
  if [[ -L "${preflight}" || ( -e "${preflight}" && ! -f "${preflight}" ) \
    || -L "${env_file}" || ( -e "${env_file}" && ! -f "${env_file}" ) ]]; then
    fail "Project-runtime cleanup helper or environment is unsafe; clean-slate uninstall was aborted."
  fi
  if [[ ! -f "${preflight}" || ! -f "${env_file}" ]]; then
    handle_helperless_clean_slate_residue project
    return 0
  fi

  info "Removing managed project runtimes and provider resources..."
  /usr/bin/timeout --foreground --kill-after=15s 1800s \
    /usr/bin/node "${preflight}" \
      --env-file "${env_file}" \
      --max-runtime-seconds 1740 \
    || fail "Managed project resources could not be removed safely; clean-slate uninstall was aborted."
}

remove_managed_agent_zero_for_clean_uninstall() {
  local portal_dir="${1:-${PORTAL_DIR}}"
  local helper="${portal_dir}/installer/agent-zero-runtime.sh"
  if [[ -L "${helper}" || ( -e "${helper}" && ! -f "${helper}" ) ]]; then
    fail "Agent Zero cleanup helper is unsafe; clean-slate uninstall was aborted."
  fi
  if [[ ! -f "${helper}" ]]; then
    handle_helperless_clean_slate_residue agent-zero
    return 0
  fi

  info "Removing managed Agent Zero runtime..."
  bash "${helper}" uninstall \
    || fail "Managed Agent Zero runtime could not be removed safely; clean-slate uninstall was aborted."
}

assert_no_managed_agent_zero_runtime_residuals() {
  local names name volumes path
  names="$(docker container ls --all --format '{{.Names}}' 2>/dev/null)" \
    || fail "Docker container state could not be authoritatively inspected for Agent Zero residue."
  while IFS= read -r name; do
    [[ -z "${name}" ]] && continue
    if [[ "${name}" == 'bridgesllm-agent-zero' \
      || "${name}" == 'bridgesllm-agent-zero-rollback' \
      || "${name}" =~ ^bridgesllm-agent-zero-pre-rollback-[0-9]{8}T[0-9]{6}Z$ ]]; then
      fail "Managed Agent Zero container residue remains but its cleanup helper is unavailable."
    fi
  done <<<"${names}"
  volumes="$(docker volume ls --format '{{.Name}}' 2>/dev/null)" \
    || fail "Docker volume state could not be authoritatively inspected for Agent Zero residue."
  grep -Fx 'bridgesllm-agent-zero-usr' <<<"${volumes}" >/dev/null \
    && fail "Managed Agent Zero volume residue remains but its cleanup helper is unavailable."
  for path in \
    /etc/bridgesllm/agent-zero.env \
    /var/lib/bridgesllm/agent-zero-runtime \
    /var/backups/bridgesllm/agent-zero; do
    [[ ! -e "${path}" && ! -L "${path}" ]] \
      || fail "Managed Agent Zero filesystem residue remains but its cleanup helper is unavailable."
  done
}

assert_no_agent_zero_project_bridge_residuals() {
  local bridge_service='bridgesllm-agent-zero-project-model-bridge.service'
  local load_state active_state process_status path
  load_state="$(systemctl show --property=LoadState --value "${bridge_service}" 2>/dev/null)" \
    || fail "Agent Zero Project model bridge load state could not be verified."
  active_state="$(systemctl show --property=ActiveState --value "${bridge_service}" 2>/dev/null)" \
    || fail "Agent Zero Project model bridge active state could not be verified."
  [[ "${load_state}" == 'not-found' && ( "${active_state}" == 'inactive' || "${active_state}" == 'failed' ) ]] \
    || fail "Agent Zero Project model bridge residue remains but its lifecycle helper is unavailable."
  for path in \
    /etc/systemd/system/bridgesllm-agent-zero-project-model-bridge.service \
    /etc/bridgesllm/agent-zero-project-model-bridge.env \
    /var/lib/bridgesllm/agent-zero-project-model-bridge; do
    [[ ! -e "${path}" && ! -L "${path}" ]] \
      || fail "Agent Zero Project model bridge filesystem residue remains but its lifecycle helper is unavailable."
  done
  id -u bridgesllm-a0-bridge >/dev/null 2>&1 \
    && fail "Agent Zero Project model bridge account residue remains but its lifecycle helper is unavailable."
  getent group bridgesllm-a0-bridge >/dev/null 2>&1 \
    && fail "Agent Zero Project model bridge group residue remains but its lifecycle helper is unavailable."
  if pgrep -f -- '/opt/bridgesllm/portal/backend/dist/agents/providers/agentZero/AgentZeroProjectModelBridge\.js([[:space:]]|$)' >/dev/null 2>&1; then
    fail "Agent Zero Project model bridge process residue remains but its lifecycle helper is unavailable."
  else
    process_status=$?
    [[ ${process_status} -eq 1 ]] \
      || fail "Agent Zero Project model bridge process state could not be verified."
  fi
}

# Detect or remove leftover managed runtime residue on the helperless repeat
# clean-slate path. Every deletion is scoped to the exact deterministic product
# shapes the fail-closed asserts recognize; nothing else on the host is
# touched. "report" is read-only and prints `present=<bool> bytes=<estimate>`
# followed by one human line per finding. "wipe" saves a full iptables and
# ip6tables backup before deleting anything, then removes only the matched
# resources; the caller must re-run the fail-closed asserts as the
# authoritative absence proof.
managed_runtime_residue_tool() {
  local mode="$1"
  local scope="${2:-all}"
  local backup_dir="${3:-}"
  local plan_path="${4:-}"
  local expected_plan_digest="${5:-}"
  python3 - "${mode}" "${scope}" "${backup_dir}" \
    "${plan_path}" "${expected_plan_digest}" <<'PY'
import datetime
import hashlib
import json
import os
import re
import shlex
import shutil
import stat
import subprocess
import sys
import tempfile

mode, scope, backup_dir, plan_path, expected_plan_digest = sys.argv[1:]
if (
    mode not in {"report", "seal-plan", "quiesce", "wipe", "prove-absent"}
    or scope not in {"all", "project", "agent-zero"}
):
    raise SystemExit("invalid managed-residue tool invocation")
if os.geteuid() != 0:
    raise SystemExit("the managed-residue tool requires root")

TEST_ROOT = os.environ.get("BRIDGESLLM_RESIDUE_TEST_ROOT", "")
if TEST_ROOT:
    if (
        not re.fullmatch(r"/tmp/bridgesllm-residue-fixture-[A-Za-z0-9._-]+",
                         TEST_ROOT)
        or os.path.normpath(TEST_ROOT) != TEST_ROOT
        or os.path.realpath(TEST_ROOT) != TEST_ROOT
    ):
        raise SystemExit("the managed-residue fixture root is unsafe")
    test_info = os.lstat(TEST_ROOT)
    if (
        not stat.S_ISDIR(test_info.st_mode)
        or stat.S_ISLNK(test_info.st_mode)
        or test_info.st_uid != 0
        or test_info.st_gid != 0
        or stat.S_IMODE(test_info.st_mode) != 0o700
    ):
        raise SystemExit("the managed-residue fixture root is unsafe")


def mapped_path(path):
    if not TEST_ROOT:
        return path
    if not path.startswith("/"):
        raise SystemExit("fixture mapping requires an absolute path")
    result = os.path.normpath(TEST_ROOT + path)
    if result != TEST_ROOT and not result.startswith(TEST_ROOT + os.sep):
        raise SystemExit("fixture path escaped its root")
    return result


TRUSTED_BINARY_NAMES = {
    "docker",
    "du",
    "iptables",
    "ip6tables",
    "iptables-save",
    "ip6tables-save",
}
TRUSTED_PRODUCTION_BINARY_DIRS = (
    "/usr/local/sbin",
    "/usr/local/bin",
    "/usr/sbin",
    "/usr/bin",
)


class BinaryAttestationError(RuntimeError):
    pass


def path_is_within(path, root):
    try:
        return os.path.commonpath((path, root)) == root
    except ValueError:
        return False


def attest_directory(path):
    info = os.lstat(path)
    if (
        not stat.S_ISDIR(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or info.st_mode & 0o022
    ):
        raise BinaryAttestationError("binary path crosses an unsafe directory")


def resolve_attested_binary(path, anchor):
    requested = os.path.normpath(path)
    if (
        not os.path.isabs(requested)
        or not path_is_within(requested, anchor)
    ):
        raise BinaryAttestationError("binary path escaped its trust anchor")
    attest_directory(anchor)
    seen = set()
    for _ in range(40):
        if requested in seen:
            raise BinaryAttestationError("binary path contains a symlink cycle")
        seen.add(requested)
        relative = os.path.relpath(requested, anchor)
        parts = [] if relative == "." else relative.split(os.sep)
        current = anchor
        redirected = None
        for index, component in enumerate(parts):
            current = os.path.join(current, component)
            info = os.lstat(current)
            if stat.S_ISLNK(info.st_mode):
                if info.st_uid != 0 or info.st_gid != 0:
                    raise BinaryAttestationError(
                        "binary path contains an unowned symlink")
                target = os.readlink(current)
                target_path = (
                    target
                    if os.path.isabs(target)
                    else os.path.join(os.path.dirname(current), target)
                )
                suffix = parts[index + 1:]
                redirected = os.path.normpath(
                    os.path.join(target_path, *suffix))
                if not path_is_within(redirected, anchor):
                    raise BinaryAttestationError(
                        "binary symlink escaped its trust anchor")
                break
            if index < len(parts) - 1:
                attest_directory(current)
                continue
            if (
                not stat.S_ISREG(info.st_mode)
                or info.st_uid != 0
                or info.st_gid != 0
                or info.st_mode & 0o022
                or not info.st_mode & 0o111
            ):
                raise BinaryAttestationError(
                    "binary target failed its ownership contract")
            return current
        if redirected is None:
            raise BinaryAttestationError("binary path did not resolve to a file")
        requested = redirected
    raise BinaryAttestationError("binary path exceeded the symlink safety limit")


def attest_trusted_binary(candidate):
    if (
        not isinstance(candidate, str)
        or not os.path.isabs(candidate)
        or os.path.normpath(candidate) != candidate
        or os.path.basename(candidate) not in TRUSTED_BINARY_NAMES
    ):
        raise BinaryAttestationError("binary frontend is outside the allowlist")
    if TEST_ROOT:
        binary_dir = os.path.join(TEST_ROOT, "bin")
        if os.path.dirname(candidate) != binary_dir:
            raise BinaryAttestationError(
                "fixture binary frontend escaped its sealed directory")
        resolved = resolve_attested_binary(candidate, TEST_ROOT)
        if not path_is_within(resolved, binary_dir):
            raise BinaryAttestationError(
                "fixture binary target escaped its sealed directory")
        return resolved
    if os.path.dirname(candidate) not in TRUSTED_PRODUCTION_BINARY_DIRS:
        raise BinaryAttestationError(
            "binary frontend escaped the production allowlist")
    resolved = resolve_attested_binary(candidate, "/")
    if not resolved.startswith(("/usr/local/", "/usr/")):
        raise BinaryAttestationError(
            "binary target escaped the immutable system tree")
    return resolved


def trusted_binary(name):
    if name not in TRUSTED_BINARY_NAMES:
        return None
    directories = (
        (os.path.join(TEST_ROOT, "bin"),)
        if TEST_ROOT
        else TRUSTED_PRODUCTION_BINARY_DIRS
    )
    for directory in directories:
        candidate = os.path.join(directory, name)
        try:
            attest_trusted_binary(candidate)
        except (BinaryAttestationError, FileNotFoundError, OSError):
            continue
        # Keep the sealed frontend path: multicall tools such as
        # xtables-nft-multi select iptables/ip6tables behavior from argv[0].
        return candidate
    return None


DOCKER = trusted_binary("docker")
if DOCKER is None:
    raise SystemExit("docker is unavailable; managed residue could not be inspected")

MAX_COMMAND_BYTES = 16 * 1024 * 1024
MAX_RESOURCES = 4096
SAFE_ENV = {
    "PATH": (
        os.path.join(TEST_ROOT, "bin") + ":/usr/bin:/bin"
        if TEST_ROOT
        else "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
    ),
    "LANG": "C.UTF-8",
    "LC_ALL": "C.UTF-8",
}
if TEST_ROOT:
    SAFE_ENV["BRIDGESLLM_RESIDUE_TEST_ROOT"] = TEST_ROOT


def run_result(args, tolerate_failure=False):
    try:
        resolved = attest_trusted_binary(args[0])
        flags = os.O_RDONLY | os.O_CLOEXEC
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(resolved, flags)
        try:
            opened = os.fstat(descriptor)
            current = os.stat(resolved, follow_symlinks=False)
            if (
                not stat.S_ISREG(opened.st_mode)
                or opened.st_uid != 0
                or opened.st_gid != 0
                or opened.st_mode & 0o022
                or not opened.st_mode & 0o111
                or (opened.st_dev, opened.st_ino)
                    != (current.st_dev, current.st_ino)
            ):
                raise BinaryAttestationError(
                    "binary changed before its pinned execution")
            result = subprocess.run(
                args,
                executable=f"/proc/self/fd/{descriptor}",
                pass_fds=(descriptor,),
                capture_output=True,
                text=True,
                timeout=90,
                env=SAFE_ENV,
            )
        finally:
            os.close(descriptor)
    except (
        BinaryAttestationError,
        FileNotFoundError,
        OSError,
        subprocess.TimeoutExpired,
    ):
        raise SystemExit(
            f"{os.path.basename(args[0])} failed its pinned binary "
            f"attestation while handling managed {scope} residue")
    if len(result.stdout.encode("utf-8", "replace")) > MAX_COMMAND_BYTES:
        raise SystemExit("command output exceeded the managed-residue safety limit")
    if result.returncode != 0 and not tolerate_failure:
        raise SystemExit(
            f"{os.path.basename(args[0])} failed with exit code "
            f"{result.returncode} while handling managed {scope} residue")
    return result


def run(args, tolerate_failure=False):
    return run_result(args, tolerate_failure=tolerate_failure).stdout


PROJECT_CONTAINER_RES = [
    re.compile(r"^p4e-proxy-[a-f0-9]{20}$"),
    re.compile(r"^p4ol-[a-f0-9]{24}$"),
    re.compile(r"^p4cx-[a-f0-9]{24}$"),
    re.compile(r"^p4cc-[a-f0-9]{24}$"),
    re.compile(r"^p4ag-[a-f0-9]{24}$"),
    re.compile(r"^p4oc-[a-f0-9]{16}-[a-z0-9._-]{1,32}-[a-f0-9]{8}$"),
    re.compile(r"^bridgesllm-a0p-[a-f0-9]{24}$"),
    re.compile(r"^bridgesllm-project-(app|job|git)-[a-f0-9]{20}$"),
]
PROJECT_CONTAINER_LABELS = [
    "com.bridgesllm.project-egress.runtime-fingerprint",
    "com.bridgesllm.project-egress.policy=portal-project-egress-v1",
    "com.bridgesllm.project-workload.policy=portal-project-workload-v1",
    "com.bridgesllm.ollama-project.policy=portal-ollama-project-sandbox-v1",
    "com.bridgesllm.project-runtime=true",
    "com.bridgesllm.project-git=true",
    "io.bridgesllm.managed=agent-zero-project",
]
PROJECT_CONTAINER_LABEL_RULES = {
    "com.bridgesllm.project-egress.runtime-fingerprint":
        lambda value: bool(re.fullmatch(r"[a-f0-9]{64}", value)),
    "com.bridgesllm.project-egress.policy":
        lambda value: value == "portal-project-egress-v1",
    "com.bridgesllm.project-workload.policy":
        lambda value: value == "portal-project-workload-v1",
    "com.bridgesllm.ollama-project.policy":
        lambda value: value == "portal-ollama-project-sandbox-v1",
    "com.bridgesllm.project-runtime": lambda value: value == "true",
    "com.bridgesllm.project-git": lambda value: value == "true",
    "io.bridgesllm.managed": lambda value: value == "agent-zero-project",
}
PROJECT_NETWORK_RE = re.compile(r"^p4e-(in|out)-[a-f0-9]{20}$")
PROJECT_NETWORK_LABELS = [
    "io.bridgesllm.managed=agent-zero-project",
    "com.bridgesllm.project-egress.policy=portal-project-egress-v1",
]
PROJECT_NETWORK_LABEL_RULES = {
    "io.bridgesllm.managed": lambda value: value == "agent-zero-project",
    "com.bridgesllm.project-egress.policy":
        lambda value: value == "portal-project-egress-v1",
}
PROJECT_VOLUME_RE = re.compile(r"^bridgesllm-a0p-[a-f0-9]{24}-usr$")
PROJECT_VOLUME_LABELS = ["io.bridgesllm.managed=agent-zero-project"]
PROJECT_VOLUME_LABEL_RULES = {
    "io.bridgesllm.managed": lambda value: value == "agent-zero-project",
}
AGENT_ZERO_CONTAINER_RES = [
    re.compile(r"^bridgesllm-agent-zero$"),
    re.compile(r"^bridgesllm-agent-zero-rollback$"),
    re.compile(r"^bridgesllm-agent-zero-pre-rollback-[0-9]{8}T[0-9]{6}Z$"),
]
AGENT_ZERO_VOLUME = "bridgesllm-agent-zero-usr"
AGENT_ZERO_IMAGES = {
    "agent0ai/agent-zero@sha256:9b48534c1279fb831513b8c970e2d9004e7a2a6708a4d53a91a76d24a4f9f7eb",
    "agent0ai/agent-zero@sha256:da107b689828124369d83f017b9664493c0699c60e57809fbd32f647078de49c",
}
AGENT_ZERO_PATHS = [
    mapped_path("/etc/bridgesllm/agent-zero.env"),
    mapped_path("/var/lib/bridgesllm/agent-zero-runtime"),
    mapped_path("/var/backups/bridgesllm/agent-zero"),
]
MANAGED_CHAIN_RE = re.compile(r"^(P4E-|A0P-)[A-Za-z0-9_.:-]+$")
MANAGED_COMMENT_RE = re.compile(r"^(p4e-v1|a0p-v3):[a-f0-9]{64}:[a-f0-9]{64}$")
P4E_PROJECT_CHAIN_RE = re.compile(r"^P4E-[A-F0-9]{23}$")
A0P_PROJECT_CHAIN_RE = re.compile(r"^A0P-[A-F0-9]{24}$")
P4E_MASTER_CHAIN = "P4E-MASTER-V1"
P4E_HOST_CHAIN = "P4E-HOST-V1"

want_project = scope in {"all", "project"}
want_agent_zero = scope in {"all", "agent-zero"}


def docker_names(kind):
    args = [DOCKER, kind, "ls", "--format",
            "{{.Names}}" if kind == "container" else "{{.Name}}"]
    if kind == "container":
        args.insert(3, "--all")
    names = {line.strip() for line in run(args).splitlines() if line.strip()}
    if len(names) > MAX_RESOURCES:
        raise SystemExit("Docker name inventory exceeded the safety limit")
    return names


def docker_identities(kind):
    args = [DOCKER, kind, "ls"]
    if kind == "container":
        args.extend(["--all", "--no-trunc", "--format", "{{.ID}}"])
    elif kind == "network":
        args.extend(["--no-trunc", "--format", "{{.ID}}"])
    else:
        args.extend(["--format", "{{.Name}}"])
    values = [line.strip() for line in run(args).splitlines() if line.strip()]
    if (
        len(values) > MAX_RESOURCES
        or len(values) != len(set(values))
        or (
            kind in {"container", "network"}
            and not all(re.fullmatch(r"[a-f0-9]{64}", value)
                        for value in values)
        )
        or (
            kind == "volume"
            and not all(re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", value)
                for value in values)
        )
    ):
        raise SystemExit("Docker identity inventory was invalid")
    return set(values)


def docker_label_ids(kind, label):
    args = [DOCKER, kind, "ls", "--quiet", "--filter", f"label={label}"]
    if kind == "container":
        args.insert(3, "--all")
        args.insert(4, "--no-trunc")
    elif kind == "network":
        args.insert(3, "--no-trunc")
    identities = {line.strip() for line in run(args).splitlines() if line.strip()}
    if len(identities) > MAX_RESOURCES:
        raise SystemExit("Docker label inventory exceeded the safety limit")
    return identities


def normalized_labels(value):
    if value is None:
        return {}
    if not isinstance(value, dict):
        raise SystemExit("Docker returned invalid resource labels")
    if not all(isinstance(key, str) and isinstance(item, str)
               for key, item in value.items()):
        raise SystemExit("Docker returned invalid resource labels")
    return dict(value)


def inspect_resource(kind, reference, tolerate_missing=False, include_size=False):
    args = [DOCKER, kind, "inspect"]
    if kind == "container" and include_size:
        args.append("--size")
    args.append(reference)
    result = run_result(args, tolerate_failure=tolerate_missing)
    if result.returncode != 0:
        return None
    try:
        payload = json.loads(result.stdout)
    except json.JSONDecodeError:
        raise SystemExit("Docker inspection returned invalid JSON")
    if not isinstance(payload, list) or len(payload) != 1 or not isinstance(payload[0], dict):
        raise SystemExit("Docker inspection was ambiguous")
    item = payload[0]
    if kind == "container":
        identity = item.get("Id")
        name = str(item.get("Name") or "").lstrip("/")
        labels = normalized_labels((item.get("Config") or {}).get("Labels"))
        mounts = item.get("Mounts")
        if (
            not isinstance(mounts, list)
            or not all(isinstance(mount, dict) for mount in mounts)
        ):
            raise SystemExit("Docker returned invalid container mounts")
        mounts = sorted(
            mounts,
            key=lambda mount: json.dumps(
                mount, sort_keys=True, separators=(",", ":")
            ),
        )
        stable = {
            "id": identity,
            "name": name,
            "config": item.get("Config"),
            "hostConfig": item.get("HostConfig"),
            # Docker does not guarantee inspect ordering for this set.
            "mounts": mounts,
        }
        size = item.get("SizeRw")
        running = bool((item.get("State") or {}).get("Running"))
        restart_policy = str(
            (((item.get("HostConfig") or {}).get("RestartPolicy") or {}).get("Name"))
            or "no"
        )
    elif kind == "network":
        identity = item.get("Id")
        name = item.get("Name")
        labels = normalized_labels(item.get("Labels"))
        stable = {
            key: item.get(key)
            for key in (
                "Id", "Name", "Driver", "Scope", "Internal", "Attachable",
                "Ingress", "IPAM", "Options", "Labels",
            )
        }
        size = None
        running = False
        restart_policy = "no"
    else:
        identity = item.get("Name")
        name = identity
        labels = normalized_labels(item.get("Labels"))
        stable = {
            key: item.get(key)
            for key in (
                "Name", "Driver", "Scope", "Mountpoint", "Labels", "Options",
                "CreatedAt",
            )
        }
        size = None
        running = False
        restart_policy = "no"
    if not isinstance(name, str) or not re.fullmatch(
            r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", name):
        raise SystemExit("Docker returned an invalid resource name")
    if kind != "volume" and (
            not isinstance(identity, str)
            or not re.fullmatch(r"[a-f0-9]{64}", identity)):
        raise SystemExit("Docker returned an invalid immutable resource identity")
    canonical = json.dumps(stable, sort_keys=True, separators=(",", ":"))
    return {
        "kind": kind,
        "identity": identity,
        "name": name,
        "labels": labels,
        "stable": stable,
        "attestation": hashlib.sha256(canonical.encode("utf-8")).hexdigest(),
        "size": size,
        "mountpoint": item.get("Mountpoint") if kind == "volume" else None,
        "running": running,
        "restartPolicy": restart_policy,
    }


def valid_label_claim(labels, rules):
    claims = [(key, validator) for key, validator in rules.items() if key in labels]
    return bool(claims) and all(validator(labels[key]) for key, validator in claims)


def contradictory_managed_labels(kind, labels):
    rules = {
        "container": PROJECT_CONTAINER_LABEL_RULES,
        "network": PROJECT_NETWORK_LABEL_RULES,
        "volume": PROJECT_VOLUME_LABEL_RULES,
    }[kind]
    return any(
        key in labels and not validator(labels[key])
        for key, validator in rules.items()
    )


def exact_managed_name(kind, name):
    if kind == "container":
        return (
            want_project
            and any(pattern.fullmatch(name) for pattern in PROJECT_CONTAINER_RES)
        ) or (
            want_agent_zero
            and any(pattern.fullmatch(name) for pattern in AGENT_ZERO_CONTAINER_RES)
        )
    if kind == "network":
        return want_project and bool(PROJECT_NETWORK_RE.fullmatch(name))
    return (
        want_project and bool(PROJECT_VOLUME_RE.fullmatch(name))
    ) or (
        want_agent_zero and name == AGENT_ZERO_VOLUME
    )


def exact_managed_labels(kind, labels):
    if not want_project:
        return False
    rules = {
        "container": PROJECT_CONTAINER_LABEL_RULES,
        "network": PROJECT_NETWORK_LABEL_RULES,
        "volume": PROJECT_VOLUME_LABEL_RULES,
    }[kind]
    return valid_label_claim(labels, rules)


def agent_zero_container_contract(record):
    if not any(
        pattern.fullmatch(record["name"])
        for pattern in AGENT_ZERO_CONTAINER_RES
    ):
        return True
    stable = record["stable"]
    config = stable.get("config") or {}
    host = stable.get("hostConfig") or {}
    mounts = stable.get("mounts") or []
    labels = normalized_labels(config.get("Labels"))
    pre_rollback = bool(re.fullmatch(
        r"bridgesllm-agent-zero-pre-rollback-[0-9]{8}T[0-9]{6}Z",
        record["name"],
    ))
    managed_label = labels.get("io.bridgesllm.agent-zero.managed")
    if (
        config.get("Image") not in AGENT_ZERO_IMAGES
        or labels.get("io.bridgesllm.agent-zero.version") != "2.5"
        or managed_label not in {None, "true"}
        or ((host.get("RestartPolicy") or {}).get("Name")) != "unless-stopped"
        or len(host.get("PortBindings") or {}) != 1
        or (host.get("PortBindings") or {}).get("80/tcp")
            != [{"HostIp": "127.0.0.1", "HostPort": "50001"}]
        or len(mounts) != 2
        or (pre_rollback and record["running"])
    ):
        return False
    data_mounts = [
        mount for mount in mounts
        if isinstance(mount, dict) and mount.get("Destination") == "/a0/usr"
    ]
    auth_mounts = [
        mount for mount in mounts
        if isinstance(mount, dict) and mount.get("Destination") == "/a0/.env"
    ]
    if len(data_mounts) != 1 or len(auth_mounts) != 1:
        return False
    data_mount = data_mounts[0]
    auth_mount = auth_mounts[0]
    return (
        data_mount.get("Type") == "volume"
        and data_mount.get("RW") is True
        and (
            pre_rollback
            and bool(re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}",
                str(data_mount.get("Name") or ""),
            ))
            or data_mount.get("Name") == AGENT_ZERO_VOLUME
        )
        and auth_mount.get("Type") == "bind"
        and auth_mount.get("Source")
            == mapped_path("/etc/bridgesllm/agent-zero.env")
        and auth_mount.get("RW") is False
    )


def agent_zero_volume_contract(record):
    if record["name"] != AGENT_ZERO_VOLUME:
        return True
    stable = record["stable"]
    labels = normalized_labels(stable.get("Labels"))
    root = run([DOCKER, "info", "--format", "{{.DockerRootDir}}"]).strip()
    expected_mountpoint = os.path.join(
        root.rstrip("/"), "volumes", AGENT_ZERO_VOLUME, "_data")
    try:
        mount_info = os.lstat(expected_mountpoint)
    except FileNotFoundError:
        return False
    if (
        not os.path.isabs(root)
        or stable.get("Driver") != "local"
        or stable.get("Scope") != "local"
        or labels not in ({}, {"io.bridgesllm.agent-zero.managed": "true"})
        or stable.get("Mountpoint") != expected_mountpoint
        or not os.path.isdir(expected_mountpoint)
        or os.path.islink(expected_mountpoint)
        or os.path.realpath(expected_mountpoint) != expected_mountpoint
        or mount_info.st_uid != 0
        or mount_info.st_gid != 0
    ):
        return False
    references = run([
        DOCKER, "container", "ls", "--all", "--no-trunc",
        "--filter", f"volume={AGENT_ZERO_VOLUME}",
        "--format", "{{.ID}}",
    ]).splitlines()
    selected_ids = {
        item["identity"]
        for item in container_records
        if any(
            pattern.fullmatch(item["name"])
            for pattern in AGENT_ZERO_CONTAINER_RES
        )
    }
    return all(
        re.fullmatch(r"[a-f0-9]{64}", reference.strip())
        and reference.strip() in selected_ids
        for reference in references
        if reference.strip()
    )


def canonical_records(kind, references):
    records = {}
    for reference in sorted(references):
        record = inspect_resource(
            kind, reference, include_size=kind == "container")
        if record is None:
            raise SystemExit("Docker residue disappeared during its initial attestation")
        if contradictory_managed_labels(kind, record["labels"]):
            raise SystemExit(
                f"Docker {kind} carries a contradictory Portal ownership label")
        if not (
            exact_managed_name(kind, record["name"])
            or exact_managed_labels(kind, record["labels"])
        ):
            raise SystemExit(
                f"Docker {kind} has a contradictory or incomplete Portal ownership contract")
        if kind == "container" and not agent_zero_container_contract(record):
            raise SystemExit(
                "Agent Zero container residue failed its exact managed contract")
        if kind == "volume" and not agent_zero_volume_contract(record):
            raise SystemExit(
                "Agent Zero volume residue failed its exact managed contract")
        existing = records.get(record["identity"])
        if existing is not None and existing["attestation"] != record["attestation"]:
            raise SystemExit(
                "Docker returned contradictory duplicate "
                f"{kind} identity for {record['name']}"
            )
        records[record["identity"]] = record
    return [records[identity] for identity in sorted(records)]


container_refs, network_refs, volume_refs = set(), set(), set()
container_names = docker_names("container")
network_names = docker_names("network")
volume_names = docker_names("volume")

if want_project:
    container_refs |= {name for name in container_names
                       if any(pattern.fullmatch(name) for pattern in PROJECT_CONTAINER_RES)}
    network_refs |= {name for name in network_names if PROJECT_NETWORK_RE.fullmatch(name)}
    volume_refs |= {name for name in volume_names if PROJECT_VOLUME_RE.fullmatch(name)}
    for label in PROJECT_CONTAINER_LABELS:
        container_refs |= docker_label_ids("container", label)
    for label in PROJECT_NETWORK_LABELS:
        network_refs |= docker_label_ids("network", label)
    for label in PROJECT_VOLUME_LABELS:
        volume_refs |= docker_label_ids("volume", label)
if want_agent_zero:
    container_refs |= {name for name in container_names
                       if any(pattern.fullmatch(name) for pattern in AGENT_ZERO_CONTAINER_RES)}
    volume_refs |= {name for name in volume_names if name == AGENT_ZERO_VOLUME}

container_records = canonical_records("container", container_refs)
network_records = canonical_records("network", network_refs)
volume_records = canonical_records("volume", volume_refs)


def decode_mount_path(value):
    return (
        value.replace("\\040", " ")
        .replace("\\011", "\t")
        .replace("\\012", "\n")
        .replace("\\134", "\\")
    )


def current_mountpoints():
    mountinfo_path = mapped_path("/proc/self/mountinfo")
    try:
        with open(mountinfo_path, "r", encoding="utf-8") as handle:
            return {
                mapped_path(decode_mount_path(columns[4]))
                if TEST_ROOT else decode_mount_path(columns[4])
                for line in handle
                if len((columns := line.split())) >= 5
            }
    except OSError:
        raise SystemExit("mount topology could not be inspected")


def descriptor_mount_id(descriptor):
    try:
        with open(
            f"/proc/self/fdinfo/{descriptor}",
            "r",
            encoding="utf-8",
        ) as handle:
            matches = [
                line.split(":", 1)[1].strip()
                for line in handle
                if line.startswith("mnt_id:")
            ]
    except OSError:
        raise SystemExit("open descriptor mount identity could not be read")
    if (
        len(matches) != 1
        or not re.fullmatch(r"[0-9]+", matches[0])
        or int(matches[0]) <= 0
    ):
        raise SystemExit("open descriptor mount identity was invalid")
    return int(matches[0])


def path_record(path):
    if path not in AGENT_ZERO_PATHS or not os.path.isabs(path):
        raise SystemExit("managed residue path escaped its exact ownership boundary")
    if not os.path.lexists(path):
        return None
    current = TEST_ROOT if TEST_ROOT else "/"
    relative = os.path.relpath(path, current)
    if relative == ".." or relative.startswith(".." + os.sep):
        raise SystemExit("managed residue path escaped its fixture root")
    for component in relative.split(os.sep)[:-1]:
        current = os.path.join(current, component)
        info = os.lstat(current)
        if (
            not stat.S_ISDIR(info.st_mode)
            or stat.S_ISLNK(info.st_mode)
            or info.st_uid != 0
            or info.st_gid != 0
            or info.st_mode & 0o022
        ):
            raise SystemExit("managed residue path crosses an unsafe ancestor")
    parent = os.path.dirname(path)
    parent_info = os.lstat(parent)
    try:
        info = os.lstat(path)
    except FileNotFoundError:
        return None
    if (
        stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or os.path.realpath(path) != path
    ):
        raise SystemExit("managed residue path is unsafe")
    expected_type = "file" if path.endswith(".env") else "directory"
    for mountpoint in current_mountpoints():
        if mountpoint == path or mountpoint.startswith(path + os.sep):
            raise SystemExit("managed Agent Zero residue contains a mount boundary")
    if expected_type == "file":
        if (
            not stat.S_ISREG(info.st_mode)
            or stat.S_IMODE(info.st_mode) != 0o600
            or info.st_nlink != 1
        ):
            raise SystemExit("managed Agent Zero environment residue is unsafe")
    else:
        if not stat.S_ISDIR(info.st_mode) or stat.S_IMODE(info.st_mode) != 0o700:
            raise SystemExit("managed Agent Zero directory residue is unsafe")
        for entry in os.scandir(path):
            entry_info = entry.stat(follow_symlinks=False)
            if (
                stat.S_ISLNK(entry_info.st_mode)
                or entry_info.st_uid != 0
                or entry_info.st_gid != 0
            ):
                raise SystemExit(
                    "managed Agent Zero residue has an unsafe top-level entry")
    return {
        "path": path,
        "device": info.st_dev,
        "inode": info.st_ino,
        "mode": info.st_mode,
        "uid": info.st_uid,
        "gid": info.st_gid,
        "type": expected_type,
        "parentDevice": parent_info.st_dev,
        "parentInode": parent_info.st_ino,
        "parentMode": parent_info.st_mode,
    }


path_records = []
if want_agent_zero:
    for candidate in AGENT_ZERO_PATHS:
        record = path_record(candidate)
        if record is not None:
            path_records.append(record)
paths = [record["path"] for record in path_records]


def shaped_path_quarantines():
    discovered = set()
    for path in AGENT_ZERO_PATHS:
        parent = os.path.dirname(path)
        try:
            info = os.lstat(parent)
        except FileNotFoundError:
            continue
        if (
            not stat.S_ISDIR(info.st_mode)
            or stat.S_ISLNK(info.st_mode)
            or info.st_uid != 0
            or info.st_gid != 0
            or info.st_mode & 0o022
        ):
            raise SystemExit(
                "managed residue quarantine parent is unsafe")
        prefix = f".{os.path.basename(path)}.bridgesllm-wipe-"
        for name in os.listdir(parent):
            if name.startswith(prefix):
                discovered.add(os.path.join(parent, name))
    return discovered


quarantine_candidates = (
    shaped_path_quarantines() if want_agent_zero else set())
if (
    quarantine_candidates
    and mode in {"report", "seal-plan", "quiesce"}
):
    raise SystemExit(
        "an unexpected managed-residue quarantine requires recovery")


def normalize_firewall_line(value):
    normalized = value.strip()
    normalized = re.sub(r'--comment "([^"]*)"', r"--comment \1", normalized)
    normalized = re.sub(
        r" -j REJECT --reject-with (?:icmp6?-port-unreachable|icmp-port-unreachable)$",
        " -j REJECT",
        normalized,
    )
    return normalized


def managed_firewall_comment(line):
    matches = re.findall(r"(?:^| )--comment ([^ ]+)(?= |$)", line)
    return matches[0] if len(matches) == 1 else None


def comment_matches_chain(comment, chain):
    p4e = re.fullmatch(r"p4e-v1:[a-f0-9]{64}:([a-f0-9]{64})", comment)
    if p4e and P4E_PROJECT_CHAIN_RE.fullmatch(chain):
        return chain == f"P4E-{p4e.group(1)[:23].upper()}"
    a0p = re.fullmatch(r"a0p-v3:[a-f0-9]{64}:([a-f0-9]{64})", comment)
    return bool(
        a0p
        and A0P_PROJECT_CHAIN_RE.fullmatch(chain)
        and chain == f"A0P-{a0p.group(1)[:24].upper()}"
    )


def reference_lines(lines, chain):
    target = re.compile(rf" (?:-j|-g) {re.escape(chain)}(?: |$)")
    return [
        line for line in lines
        if not line.startswith(f"-A {chain} ") and target.search(line)
    ]


def valid_p4e_chain_rules(lines, chain, comment):
    escaped_chain = re.escape(chain)
    escaped_comment = re.escape(comment)
    cidr = r"[0-9A-Fa-f:.]+/[0-9]{1,3}"
    deny = re.compile(
        rf"^-A {escaped_chain} -d {cidr} -m comment --comment "
        rf"{escaped_comment} -j REJECT$")
    ipv4_return = re.compile(
        rf"^-A {escaped_chain} -p tcp -m multiport --dports 80,443 "
        rf"-m comment --comment {escaped_comment} -j RETURN$")
    ipv6_return = re.compile(
        rf"^-A {escaped_chain} -d 2000::/3 -p tcp -m multiport "
        rf"--dports 80,443 -m comment --comment {escaped_comment} -j RETURN$")
    final_reject = re.compile(
        rf"^-A {escaped_chain} -m comment --comment "
        rf"{escaped_comment} -j REJECT$")
    allowed = (deny, ipv4_return, ipv6_return, final_reject)
    return (
        len(lines) >= 2
        and all(any(pattern.fullmatch(line) for pattern in allowed) for line in lines)
        and sum(
            bool(ipv4_return.fullmatch(line) or ipv6_return.fullmatch(line))
            for line in lines
        ) == 1
        and bool(final_reject.fullmatch(lines[-1]))
    )


def valid_a0p_chain_rules(lines, chain, comment):
    escaped_chain = re.escape(chain)
    escaped_comment = re.escape(comment)
    established = re.compile(
        rf"^-A {escaped_chain} -m conntrack --ctstate RELATED,ESTABLISHED "
        rf"-m comment --comment {escaped_comment} -j ACCEPT$")
    destination = re.compile(
        rf"^-A {escaped_chain} -d [0-9.]+/32 -p tcp -m tcp "
        rf"--dport [0-9]{{1,5}} -m comment --comment "
        rf"{escaped_comment} -j ACCEPT$")
    reject = re.compile(
        rf"^-A {escaped_chain} -m comment --comment "
        rf"{escaped_comment} -j REJECT$")
    return (
        len(lines) == 4
        and bool(established.fullmatch(lines[0]))
        and bool(destination.fullmatch(lines[1]))
        and bool(destination.fullmatch(lines[2]))
        and bool(reject.fullmatch(lines[3]))
    )


def parse_managed_firewall(tool, binary, payload):
    lines = [
        normalize_firewall_line(line)
        for line in payload.splitlines()
        if line.strip()
    ]
    if len(lines) > MAX_RESOURCES:
        raise SystemExit(f"{tool} firewall inventory exceeded the safety limit")
    declarations = {
        match.group(1)
        for line in lines
        if (match := re.fullmatch(r"-N ([A-Za-z0-9_.:-]+)", line))
    }
    broad = {name for name in declarations if MANAGED_CHAIN_RE.fullmatch(name)}
    project_chains = sorted(
        name for name in broad
        if P4E_PROJECT_CHAIN_RE.fullmatch(name)
        or A0P_PROJECT_CHAIN_RE.fullmatch(name)
    )
    shared_chains = {
        name for name in (P4E_MASTER_CHAIN, P4E_HOST_CHAIN)
        if name in declarations
    }
    if broad != set(project_chains) | shared_chains:
        raise SystemExit(f"{tool} contains an ambiguous Portal-shaped chain")
    consumed = set()
    for chain in project_chains:
        local_rules = [line for line in lines if line.startswith(f"-A {chain} ")]
        comments = {
            comment for line in local_rules
            if (comment := managed_firewall_comment(line))
        }
        if len(comments) != 1:
            raise SystemExit(f"{tool} contains an ambiguous Portal chain")
        comment = next(iter(comments))
        if (
            not all(managed_firewall_comment(line) == comment for line in local_rules)
            or not comment_matches_chain(comment, chain)
            or (
                chain.startswith("P4E-")
                and not valid_p4e_chain_rules(local_rules, chain, comment)
            )
            or (
                chain.startswith("A0P-")
                and not valid_a0p_chain_rules(local_rules, chain, comment)
            )
        ):
            raise SystemExit(f"{tool} contains an ambiguous Portal chain")
        parents = reference_lines(lines, chain)
        escaped_chain = re.escape(chain)
        escaped_comment = re.escape(comment)
        cidr = r"[0-9A-Fa-f:.]+/[0-9]{1,3}"
        if chain.startswith("P4E-"):
            parent_pattern = re.compile(
                rf"^-A {P4E_MASTER_CHAIN} -s {cidr} -m comment --comment "
                rf"{escaped_comment} -j {escaped_chain}$")
        else:
            parent_pattern = re.compile(
                rf"^-A (?:INPUT|DOCKER-USER) -s {cidr} -m comment --comment "
                rf"{escaped_comment} -j {escaped_chain}$")
        if not all(parent_pattern.fullmatch(line) for line in parents):
            raise SystemExit(f"{tool} contains an ambiguous Portal chain reference")
        consumed.update(local_rules)
        consumed.update(parents)
        consumed.add(f"-N {chain}")

    host_rules = [
        line for line in lines if line.startswith(f"-A {P4E_HOST_CHAIN} ")
    ]
    # Match what the Portal actually writes into the host chain. Every managed
    # subnet gets a conntrack RELATED,ESTABLISHED ACCEPT followed by a REJECT
    # (see projectEgressPlane.ts), `iptables -S` quotes comments, and REJECT
    # carries a --reject-with suffix. The previous pattern accepted none of
    # those, so any box that had ever run a Project with egress control failed
    # this check and could not be uninstalled at all.
    #
    # Still fail-closed: ACCEPT is only recognised together with the conntrack
    # match, so a bare permissive ACCEPT in this chain remains ambiguous.
    host_comment = r"\"?p4e-v1:[a-f0-9]{64}:[a-f0-9]{64}\"?"
    host_cidr = r"[0-9A-Fa-f:.]+/[0-9]{1,3}"
    host_established_pattern = re.compile(
        rf"^-A {P4E_HOST_CHAIN} -s {host_cidr} "
        rf"-m conntrack --ctstate RELATED,ESTABLISHED "
        rf"-m comment --comment {host_comment} -j ACCEPT$")
    host_reject_pattern = re.compile(
        rf"^-A {P4E_HOST_CHAIN} -s {host_cidr} "
        rf"-m comment --comment {host_comment} "
        rf"-j REJECT(?: --reject-with [a-z0-9-]+)?$")
    if not all(
        host_established_pattern.fullmatch(line)
        or host_reject_pattern.fullmatch(line)
        for line in host_rules
    ):
        raise SystemExit(f"{tool} contains ambiguous Portal host rules")
    consumed.update(host_rules)

    master_rules = [
        line for line in lines if line.startswith(f"-A {P4E_MASTER_CHAIN} ")
    ]
    recognized_master = {
        line for chain in project_chains if chain.startswith("P4E-")
        for line in reference_lines(lines, chain)
    }
    if any(line not in recognized_master for line in master_rules):
        raise SystemExit(f"{tool} contains ambiguous Portal master rules")

    master_parents = reference_lines(lines, P4E_MASTER_CHAIN)
    host_parents = reference_lines(lines, P4E_HOST_CHAIN)
    if (
        any(line != f"-A DOCKER-USER -j {P4E_MASTER_CHAIN}"
            for line in master_parents)
        or any(line != f"-A INPUT -j {P4E_HOST_CHAIN}" for line in host_parents)
        or (
            P4E_MASTER_CHAIN not in declarations
            and (master_rules or master_parents)
        )
        or (
            P4E_HOST_CHAIN not in declarations
            and (host_rules or host_parents)
        )
    ):
        raise SystemExit(f"{tool} contains ambiguous Portal shared-chain rules")
    consumed.update(master_parents)
    consumed.update(host_parents)
    for chain in shared_chains:
        consumed.add(f"-N {chain}")

    for line in lines:
        shaped = (
            bool(re.match(r"^-N (?:P4E-|A0P-)", line))
            or bool(re.search(r" --comment (?:p4e-v1|a0p-v3):", line))
            or bool(re.search(r" (?:-j|-g) (?:P4E-|A0P-)", line))
        )
        if shaped and line not in consumed:
            raise SystemExit(f"{tool} contains unrecognized Portal-shaped rules")

    managed_chains = sorted(set(project_chains) | shared_chains)
    references = []
    for chain in managed_chains:
        for line in reference_lines(lines, chain):
            parent = line.split()[1]
            if parent not in managed_chains:
                tokens = shlex.split(line)
                references.append((parent, tokens[2:], line))
    return {
        "binary": binary,
        "chains": managed_chains,
        "references": references,
        "snapshot": "\n".join(lines),
    }


firewall = {}
if want_project:
    for tool in ("iptables", "ip6tables"):
        binary = trusted_binary(tool)
        if binary is None:
            raise SystemExit(f"{tool} is unavailable; firewall residue could not be inspected")
        payload = run([binary, "-w", "-S"])
        if mode in {"report", "seal-plan", "prove-absent"}:
            state = parse_managed_firewall(tool, binary, payload)
            firewall[tool] = state
        else:
            firewall[tool] = {
                "binary": binary,
                "currentSnapshot": "\n".join(
                    normalize_firewall_line(line)
                    for line in payload.splitlines()
                    if line.strip()
                ),
            }


def remove_first_line(lines, target):
    updated = list(lines)
    try:
        updated.remove(target)
    except ValueError:
        raise SystemExit("managed firewall plan could not be constructed")
    return updated


def firewall_mutation_plan(state):
    lines = state["snapshot"].splitlines() if state["snapshot"] else []
    initial = "\n".join(lines)
    mutations = []
    for parent, spec, line in state["references"]:
        lines = remove_first_line(lines, line)
        mutations.append({
            "args": ["-D", parent, *spec],
            "after": "\n".join(lines),
        })
    for chain in state["chains"]:
        local_rules = [
            line for line in lines if line.startswith(f"-A {chain} ")
        ]
        for line in local_rules:
            tokens = shlex.split(line)
            if len(tokens) < 3 or tokens[:2] != ["-A", chain]:
                raise SystemExit(
                    "managed firewall rule could not be sealed exactly")
            lines = remove_first_line(lines, line)
            mutations.append({
                "args": ["-D", chain, *tokens[2:]],
                "after": "\n".join(lines),
            })
    for chain in state["chains"]:
        lines = remove_first_line(lines, f"-N {chain}")
        mutations.append({
            "args": ["-X", chain],
            "after": "\n".join(lines),
        })
    return {
        "initial": initial,
        "mutations": mutations,
        "final": "\n".join(lines),
    }


def record_scopes(record):
    scopes = []
    if record["kind"] == "container":
        if (
            any(pattern.fullmatch(record["name"]) for pattern in PROJECT_CONTAINER_RES)
            or valid_label_claim(
                record["labels"], PROJECT_CONTAINER_LABEL_RULES)
        ):
            scopes.append("project")
        if any(
            pattern.fullmatch(record["name"])
            for pattern in AGENT_ZERO_CONTAINER_RES
        ):
            scopes.append("agent-zero")
    elif record["kind"] == "network":
        if (
            PROJECT_NETWORK_RE.fullmatch(record["name"])
            or valid_label_claim(record["labels"], PROJECT_NETWORK_LABEL_RULES)
        ):
            scopes.append("project")
    else:
        if (
            PROJECT_VOLUME_RE.fullmatch(record["name"])
            or valid_label_claim(record["labels"], PROJECT_VOLUME_LABEL_RULES)
        ):
            scopes.append("project")
        if record["name"] == AGENT_ZERO_VOLUME:
            scopes.append("agent-zero")
    if not scopes:
        raise SystemExit("managed Docker residue had no exact lifecycle scope")
    return sorted(set(scopes))


def create_plan_document():
    docker_plan = {}
    for kind, records in (
        ("container", container_records),
        ("network", network_records),
        ("volume", volume_records),
    ):
        docker_plan[kind] = [
            {
                "identity": record["identity"],
                "name": record["name"],
                "attestation": record["attestation"],
                "scopes": record_scopes(record),
            }
            for record in records
        ]
    firewall_plan = {
        tool: firewall_mutation_plan(state)
        for tool, state in sorted(firewall.items())
    }
    return {
        "schema": "bridgesllm.uninstall-residue-plan.v1",
        "docker": docker_plan,
        "paths": path_records,
        "firewall": firewall_plan,
    }


def canonical_plan(document):
    return json.dumps(document, sort_keys=True, separators=(",", ":"))


def plan_digest(document):
    return hashlib.sha256(canonical_plan(document).encode("utf-8")).hexdigest()


plan_document = create_plan_document() if mode in {"report", "seal-plan"} else None
current_plan_digest = plan_digest(plan_document) if plan_document is not None else ""

present = bool(
    container_records
    or network_records
    or volume_records
    or paths
    or any(
        state.get("chains") or state.get("references")
        for state in firewall.values()
    )
)


def size_of_path(path):
    du = trusted_binary("du")
    if du is None:
        return None
    result = run_result([du, "-sb", "--", path], tolerate_failure=True)
    try:
        return int(result.stdout.split()[0]) if result.returncode == 0 else None
    except (ValueError, IndexError):
        return None


if mode == "report":
    estimated = 0
    size_complete = True
    for record in container_records:
        try:
            estimated += max(int(record["size"]), 0)
        except (TypeError, ValueError):
            size_complete = False
    for record in volume_records:
        mountpoint = record["mountpoint"]
        if mountpoint and os.path.isdir(mountpoint):
            measured = size_of_path(mountpoint)
            if measured is None:
                size_complete = False
            else:
                estimated += measured
        else:
            size_complete = False
    for path in paths:
        measured = size_of_path(path)
        if measured is None:
            size_complete = False
        else:
            estimated += measured
    print(
        f"present={'true' if present else 'false'} "
        f"planDigest={current_plan_digest} "
        f"sizeComplete={'true' if size_complete else 'false'} bytes={estimated}")
    for record in container_records:
        print(f"Docker container: {record['name']}")
    for record in network_records:
        print(f"Docker network: {record['name']}")
    for record in volume_records:
        print(f"Docker volume: {record['name']}")
    for path in paths:
        print(f"File tree: {path}")
    for tool, state in sorted(firewall.items()):
        if state["chains"] or state["references"]:
            print(f"Firewall ({tool}): {len(state['chains'])} Portal chain(s), "
                  f"{len(state['references'])} referencing rule(s)")
    raise SystemExit(0)

if mode == "seal-plan":
    plan_root = mapped_path(
        "/var/lib/bridgesllm-installer/uninstall/transactions")
    if (
        not re.fullmatch(r"[a-f0-9]{64}", expected_plan_digest)
        or expected_plan_digest != current_plan_digest
        or not os.path.isabs(plan_path)
        or os.path.normpath(plan_path) != plan_path
        or os.path.basename(plan_path) != "residue-plan.json"
        or not re.fullmatch(
            re.escape(plan_root)
            + r"/[a-f0-9]{32}/residue-plan\.json",
            plan_path)
    ):
        raise SystemExit(
            "managed residue changed after confirmation; restart uninstall to review it")
    parent = os.path.dirname(plan_path)
    parent_info = os.lstat(parent)
    if (
        not stat.S_ISDIR(parent_info.st_mode)
        or stat.S_ISLNK(parent_info.st_mode)
        or parent_info.st_uid != 0
        or parent_info.st_gid != 0
        or stat.S_IMODE(parent_info.st_mode) != 0o700
        or os.path.realpath(parent) != parent
    ):
        raise SystemExit("the uninstall residue-plan directory is unsafe")
    envelope = {
        "schema": "bridgesllm.sealed-uninstall-residue-plan.v1",
        "planDigest": current_plan_digest,
        "plan": plan_document,
    }
    payload = json.dumps(envelope, indent=2, sort_keys=True) + "\n"
    descriptor = os.open(
        plan_path,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    parent_fd = os.open(
        parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(parent_fd)
    finally:
        os.close(parent_fd)
    raise SystemExit(0)

if not present and mode not in {"quiesce", "wipe", "prove-absent"}:
    raise SystemExit(0)


def load_sealed_plan():
    plan_root = mapped_path(
        "/var/lib/bridgesllm-installer/uninstall/transactions")
    if (
        not os.path.isabs(plan_path)
        or os.path.normpath(plan_path) != plan_path
        or os.path.basename(plan_path) != "residue-plan.json"
        or not re.fullmatch(
            re.escape(plan_root)
            + r"/[a-f0-9]{32}/residue-plan\.json",
            plan_path)
    ):
        raise SystemExit("the uninstall residue plan escaped its transaction boundary")
    info = os.lstat(plan_path)
    if (
        not stat.S_ISREG(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or info.st_nlink != 1
        or stat.S_IMODE(info.st_mode) != 0o600
        or info.st_size <= 0
        or info.st_size > 8 * 1024 * 1024
    ):
        raise SystemExit("the uninstall residue plan is unsafe")
    with open(plan_path, "r", encoding="utf-8") as handle:
        envelope = json.load(handle)
    if (
        not isinstance(envelope, dict)
        or set(envelope) != {"schema", "planDigest", "plan"}
        or envelope.get("schema")
            != "bridgesllm.sealed-uninstall-residue-plan.v1"
        or not re.fullmatch(r"[a-f0-9]{64}", str(envelope.get("planDigest", "")))
        or not isinstance(envelope.get("plan"), dict)
        or plan_digest(envelope["plan"]) != envelope["planDigest"]
    ):
        raise SystemExit("the uninstall residue plan failed integrity validation")
    document = envelope["plan"]
    if (
        document.get("schema") != "bridgesllm.uninstall-residue-plan.v1"
        or set(document) != {"schema", "docker", "paths", "firewall"}
        or set(document.get("docker", {}))
            != {"container", "network", "volume"}
        or not isinstance(document.get("paths"), list)
        or not isinstance(document.get("firewall"), dict)
    ):
        raise SystemExit("the uninstall residue plan has an invalid schema")
    return document


sealed_plan = load_sealed_plan()
global_identities_by_kind = {
    kind: docker_identities(kind)
    for kind in ("container", "network", "volume")
}
planned_by_kind = {}
for kind in ("container", "network", "volume"):
    planned = sealed_plan["docker"].get(kind)
    if not isinstance(planned, list) or len(planned) > MAX_RESOURCES:
        raise SystemExit("the uninstall residue plan exceeds its Docker limit")
    selected = {}
    for record in planned:
        if (
            not isinstance(record, dict)
            or set(record) != {
                "identity", "name", "attestation", "scopes",
            }
            or not isinstance(record.get("scopes"), list)
            or not record["scopes"]
            or any(item not in {"project", "agent-zero"}
                   for item in record["scopes"])
            or record["scopes"] != sorted(set(record["scopes"]))
            or not re.fullmatch(r"[a-f0-9]{64}",
                                str(record.get("attestation", "")))
            or not isinstance(record.get("name"), str)
            or not re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}",
                record["name"],
            )
        ):
            raise SystemExit("the uninstall residue plan has an invalid Docker record")
        key = record.get("identity")
        if (
            (
                kind in {"container", "network"}
                and not isinstance(key, str)
            )
            or (
                kind in {"container", "network"}
                and not re.fullmatch(r"[a-f0-9]{64}", key)
            )
            or (
                kind == "volume"
                and key != record["name"]
            )
        ):
            raise SystemExit(
                "the uninstall residue plan has an invalid Docker identity")
        if scope == "all" or scope in record["scopes"]:
            if key in selected:
                raise SystemExit(
                    "the uninstall residue plan has duplicate Docker identities")
            selected[key] = record
    planned_by_kind[kind] = selected

for kind, current_records in (
    ("container", container_records),
    ("network", network_records),
    ("volume", volume_records),
):
    present = {}
    listed_identities = global_identities_by_kind[kind]
    for identity, planned in planned_by_kind[kind].items():
        inspected = inspect_resource(
            kind,
            identity,
            tolerate_missing=True,
            include_size=kind == "container",
        )
        if mode == "prove-absent":
            if identity in listed_identities or inspected is not None:
                raise SystemExit(
                    f"a user-confirmed Docker {kind} still exists at "
                    "terminal cleanup")
            continue
        if inspected is None:
            if identity in listed_identities:
                raise SystemExit(
                    f"a listed user-confirmed Docker {kind} could not be "
                    "re-inspected by its full identity")
            if mode == "quiesce":
                raise SystemExit(
                    f"a user-confirmed Docker {kind} disappeared before "
                    "Safe cleanup")
            # A wipe can resume after an earlier invocation durably removed
            # an object but crashed before advancing the uninstall phase.
            continue
        if (
            identity not in listed_identities
            or inspected["identity"] != identity
            or inspected["name"] != planned["name"]
            or inspected["attestation"] != planned["attestation"]
        ):
            raise SystemExit(
                f"a user-confirmed Docker {kind} changed identity, name, "
                "labels, or topology after confirmation")
        present[identity] = planned
    current = {record["identity"]: record for record in current_records}
    if (
        len(current) != len(current_records)
        or set(current) != set(present)
    ):
        raise SystemExit(
            "the current and user-confirmed managed Docker inventories differ")
    for identity, record in current.items():
        planned = present[identity]
        if (
            record["name"] != planned["name"]
            or record["attestation"] != planned["attestation"]
        ):
            raise SystemExit(
                "managed Docker residue changed after the user's confirmation")

transaction_directory = os.path.dirname(plan_path)
transaction_id = os.path.basename(transaction_directory)
sealed_plan_digest = plan_digest(sealed_plan)
receipt_directory = os.path.join(
    transaction_directory, "residue-path-deletions")


def integer_field(record, name, *, positive=False):
    value = record.get(name)
    return (
        isinstance(value, int)
        and not isinstance(value, bool)
        and (value > 0 if positive else value >= 0)
    )


all_planned_paths = {}
for record in sealed_plan["paths"]:
    if (
        not isinstance(record, dict)
        or set(record) != {
            "path", "device", "inode", "mode", "uid", "gid", "type",
            "parentDevice", "parentInode", "parentMode",
        }
        or record.get("path") not in AGENT_ZERO_PATHS
        or record.get("type") not in {"file", "directory"}
        or not all(integer_field(record, name, positive=name.endswith("Inode")
                                 or name == "inode")
                   for name in (
                       "device", "inode", "mode", "uid", "gid",
                       "parentDevice", "parentInode", "parentMode",
                   ))
        or record["uid"] != 0
        or record["gid"] != 0
        or (
            record["type"] == "file"
            and (
                not stat.S_ISREG(record["mode"])
                or stat.S_IMODE(record["mode"]) != 0o600
            )
        )
        or (
            record["type"] == "directory"
            and (
                not stat.S_ISDIR(record["mode"])
                or stat.S_IMODE(record["mode"]) != 0o700
            )
        )
        or not stat.S_ISDIR(record["parentMode"])
        or record["parentMode"] & 0o022
    ):
        raise SystemExit(
            "the uninstall residue plan has an invalid filesystem record")
    if record["path"] in all_planned_paths:
        raise SystemExit(
            "the uninstall residue plan has duplicate filesystem paths")
    all_planned_paths[record["path"]] = record

planned_paths = all_planned_paths if want_agent_zero else {}
current_paths = {record["path"]: record for record in path_records}
if (
    len(current_paths) != len(path_records)
    or any(path not in planned_paths for path in current_paths)
):
    raise SystemExit(
        "the current and user-confirmed managed filesystem inventories differ")


def record_digest(record):
    return hashlib.sha256(
        canonical_plan(record).encode("utf-8")
    ).hexdigest()


def quarantine_path(record):
    path = record["path"]
    name = (
        f".{os.path.basename(path)}.bridgesllm-wipe-"
        f"{transaction_id}-{record_digest(record)[:32]}"
    )
    return os.path.join(os.path.dirname(path), name)


def receipt_paths(record):
    name = hashlib.sha256(
        record["path"].encode("utf-8")
    ).hexdigest() + ".json"
    path = os.path.join(receipt_directory, name)
    return path, os.path.join(receipt_directory, f".{name}.tmp")


def safe_receipt_file(path, *, allow_empty=False):
    try:
        info = os.lstat(path)
    except FileNotFoundError:
        return False
    return (
        stat.S_ISREG(info.st_mode)
        and not stat.S_ISLNK(info.st_mode)
        and info.st_uid == 0
        and info.st_gid == 0
        and info.st_nlink == 1
        and stat.S_IMODE(info.st_mode) == 0o600
        and (allow_empty or info.st_size > 0)
        and info.st_size <= 65536
    )


def expected_receipt(record):
    return {
        "schema": "bridgesllm.uninstall-path-deletion.v1",
        "transactionId": transaction_id,
        "planDigest": sealed_plan_digest,
        "path": record["path"],
        "quarantine": quarantine_path(record),
        "recordDigest": record_digest(record),
    }


def receipt_state(record):
    receipt, temporary = receipt_paths(record)
    temporary_exists = os.path.lexists(temporary)
    if temporary_exists and not safe_receipt_file(
            temporary, allow_empty=True):
        raise SystemExit("the path-deletion receipt temporary is unsafe")
    if not os.path.lexists(receipt):
        return False, temporary_exists
    if not safe_receipt_file(receipt):
        raise SystemExit("the path-deletion receipt is unsafe")
    try:
        with open(receipt, "r", encoding="utf-8") as handle:
            document = json.load(handle)
    except (OSError, ValueError):
        raise SystemExit("the path-deletion receipt is invalid")
    if document != expected_receipt(record):
        raise SystemExit(
            "the path-deletion receipt does not match the sealed record")
    return True, temporary_exists


def assert_parent_identity(record):
    parent = os.path.dirname(record["path"])
    info = os.lstat(parent)
    if (
        not stat.S_ISDIR(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or info.st_mode & 0o022
        or os.path.realpath(parent) != parent
        or info.st_dev != record["parentDevice"]
        or info.st_ino != record["parentInode"]
        or info.st_mode != record["parentMode"]
    ):
        raise SystemExit(
            "managed residue parent changed after the user's confirmation")


def opened_parent(record):
    parent = os.path.dirname(record["path"])
    flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor = os.open(parent, flags)
    opened = os.fstat(descriptor)
    current = os.lstat(parent)
    if (
        opened.st_dev != record["parentDevice"]
        or opened.st_ino != record["parentInode"]
        or opened.st_mode != record["parentMode"]
        or opened.st_uid != 0
        or opened.st_gid != 0
        or (opened.st_dev, opened.st_ino, opened.st_mode)
            != (current.st_dev, current.st_ino, current.st_mode)
    ):
        os.close(descriptor)
        raise SystemExit(
            "managed residue parent raced its sealed identity")
    return descriptor


def durably_confirm_path_absence(record, quarantine):
    parent_fd = opened_parent(record)
    try:
        # A prior invocation can die after unlink/rmdir and before its parent
        # fsync.  Seeing the names absent is not yet a crash-durable deletion
        # proof: flush that exact sealed parent, then re-check both entries
        # through the bound descriptor before allowing a receipt to adopt the
        # already-missing state.
        os.fsync(parent_fd)
        for candidate in (record["path"], quarantine):
            try:
                os.stat(
                    os.path.basename(candidate),
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                continue
            raise SystemExit(
                "managed filesystem residue reappeared while sealing absence")
        if TEST_ROOT:
            trace = os.path.join(
                TEST_ROOT, "state", "managed-path-parent-fsync.log")
            with open(trace, "a", encoding="utf-8") as handle:
                handle.write(record["path"] + "\n")
    finally:
        os.close(parent_fd)


def assert_quarantine_identity(record, quarantine):
    info = os.lstat(quarantine)
    if (
        stat.S_ISLNK(info.st_mode)
        or info.st_dev != record["device"]
        or info.st_ino != record["inode"]
        or info.st_mode != record["mode"]
        or info.st_uid != record["uid"]
        or info.st_gid != record["gid"]
        or (
            record["type"] == "file"
            and not stat.S_ISREG(info.st_mode)
        )
        or (
            record["type"] == "directory"
            and not stat.S_ISDIR(info.st_mode)
        )
    ):
        raise SystemExit(
            "managed residue quarantine does not match its sealed inode")
    for mountpoint in current_mountpoints():
        if (
            mountpoint == quarantine
            or mountpoint.startswith(quarantine + os.sep)
        ):
            raise SystemExit(
                "managed residue quarantine contains a mount boundary")


def validate_receipt_directory():
    if not os.path.lexists(receipt_directory):
        return False
    info = os.lstat(receipt_directory)
    if (
        not stat.S_ISDIR(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or stat.S_IMODE(info.st_mode) != 0o700
        or os.path.realpath(receipt_directory) != receipt_directory
    ):
        raise SystemExit("the path-deletion receipt directory is unsafe")
    allowed = set()
    for record in planned_paths.values():
        allowed.update(receipt_paths(record))
    for name in os.listdir(receipt_directory):
        candidate = os.path.join(receipt_directory, name)
        if candidate not in allowed:
            raise SystemExit(
                "the path-deletion receipt directory contains an unknown entry")
    return True


receipt_directory_exists = validate_receipt_directory()
planned_path_states = {}
expected_quarantines = {
    quarantine_path(record)
    for record in planned_paths.values()
}
if quarantine_candidates - expected_quarantines:
    raise SystemExit("an unexpected managed-residue quarantine exists")
for path, record in planned_paths.items():
    assert_parent_identity(record)
    quarantine = quarantine_path(record)
    prefix = f".{os.path.basename(path)}.bridgesllm-wipe-"
    for name in os.listdir(os.path.dirname(path)):
        candidate = os.path.join(os.path.dirname(path), name)
        if name.startswith(prefix) and candidate != quarantine:
            raise SystemExit(
                "an unexpected managed-residue quarantine exists")
    original_exists = os.path.lexists(path)
    quarantine_exists = os.path.lexists(quarantine)
    if original_exists and quarantine_exists:
        raise SystemExit(
            "managed residue exists at both original and quarantine paths")
    has_receipt, has_temporary = (
        receipt_state(record)
        if receipt_directory_exists
        else (False, False)
    )
    if mode == "quiesce":
        if (
            not original_exists
            or quarantine_exists
            or has_receipt
            or has_temporary
            or current_paths.get(path) != record
        ):
            raise SystemExit(
                "managed filesystem residue changed before Safe cleanup")
        planned_path_states[path] = {
            "record": record,
            "quarantine": quarantine,
            "state": "original",
        }
        continue
    if mode == "prove-absent":
        # A receipt proves *this* step deleted the path. It is not the only
        # honest route to absence: the residue plan is sealed before the
        # ordinary uninstall steps run, and those steps legitimately remove
        # some of the same paths (the Agent Zero runtime, its env file, and
        # its backups). Demanding a receipt for a path an attested earlier
        # step already removed made Complete wipe unable to converge in the
        # normal case, leaving a boot fence and a half-uninstalled host.
        #
        # Absence with no quarantine and no temporary is still absence: a
        # partially-moved deletion would have left one of those behind, and
        # both are still refused below.
        if (
            original_exists
            or quarantine_exists
            or has_temporary
        ):
            raise SystemExit(
                "sealed managed filesystem residue is not durably absent")
        durably_confirm_path_absence(record, quarantine)
        planned_path_states[path] = {
            "record": record,
            "quarantine": quarantine,
            "state": "deleted",
        }
        continue
    if original_exists:
        if (
            quarantine_exists
            or has_receipt
            or has_temporary
            or current_paths.get(path) != record
        ):
            raise SystemExit(
                "managed filesystem residue changed before Complete wipe")
        state = "original"
    elif quarantine_exists:
        assert_quarantine_identity(record, quarantine)
        state = "quarantine"
    elif not has_temporary:
        # Either this step already deleted it (receipt present), or an earlier
        # attested uninstall step did. Both end at the same verified absence;
        # only an interrupted move leaves a quarantine or temporary, and those
        # are handled above and below.
        durably_confirm_path_absence(record, quarantine)
        state = "deleted"
    else:
        raise SystemExit(
            "sealed managed filesystem residue disappeared while a deletion "
            "temporary was still present")
    planned_path_states[path] = {
        "record": record,
        "quarantine": quarantine,
        "state": state,
    }

if mode == "prove-absent":
    for tool, state in firewall.items():
        if state["chains"] or state["references"]:
            raise SystemExit(
                f"user-confirmed managed {tool} residue remains at terminal cleanup")
    print("The sealed managed-residue inventory is absent.")
    raise SystemExit(0)

firewall_positions = {}
if want_project:
    for tool in ("iptables", "ip6tables"):
        planned = sealed_plan["firewall"].get(tool)
        current = firewall.get(tool, {}).get("currentSnapshot")
        if (
            not isinstance(planned, dict)
            or set(planned) != {"initial", "mutations", "final"}
            or not isinstance(planned.get("initial"), str)
            or not isinstance(planned.get("mutations"), list)
            or not isinstance(planned.get("final"), str)
            or current is None
        ):
            raise SystemExit("the uninstall residue plan has invalid firewall state")
        states = [planned["initial"]]
        for mutation in planned["mutations"]:
            if (
                not isinstance(mutation, dict)
                or set(mutation) != {"args", "after"}
                or not isinstance(mutation.get("args"), list)
                or not all(isinstance(item, str) for item in mutation["args"])
                or not isinstance(mutation.get("after"), str)
            ):
                raise SystemExit("the uninstall residue plan has an invalid firewall mutation")
            states.append(mutation["after"])
        matches = [index for index, state in enumerate(states) if state == current]
        if len(matches) != 1:
            raise SystemExit(
                "firewall state changed outside the user-confirmed cleanup plan")
        firewall_positions[tool] = matches[0]

if mode == "quiesce":
    stopped = 0
    for record in container_records:
        current = inspect_resource("container", record["identity"], tolerate_missing=True)
        if current is None or current["attestation"] != record["attestation"]:
            raise SystemExit(
                "a managed container changed before Safe cleanup could stop it")
        if current["running"]:
            run([DOCKER, "container", "stop", "--time", "30", record["identity"]])
            stopped += 1
        verified = inspect_resource("container", record["identity"])
        if (
            verified is None
            or verified["attestation"] != record["attestation"]
            or verified["running"]
        ):
            raise SystemExit(
                "a managed container did not remain stopped for Safe cleanup")
    print(
        f"Stopped {stopped} managed leftover container(s); "
        "Docker objects and host firewall rules were retained.")
    raise SystemExit(0)

if not backup_dir or not os.path.isabs(backup_dir) or os.path.normpath(backup_dir) != backup_dir:
    raise SystemExit("a firewall backup directory is required before any wipe")
BACKUP_BASE = mapped_path("/var/backups/bridgesllm")
backup_name = os.path.basename(backup_dir)
backup_match = re.fullmatch(r"firewall-wipe-([a-f0-9]{32})", backup_name)
if os.path.dirname(backup_dir) != BACKUP_BASE or backup_match is None:
    raise SystemExit("the firewall backup directory is outside its transaction boundary")
transaction_id = backup_match.group(1)
if os.path.basename(os.path.dirname(plan_path)) != transaction_id:
    raise SystemExit("the firewall backup does not match the consent transaction")


def fsync_dir(path):
    descriptor = os.open(
        path,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def safe_root_directory(path, exact_mode=None):
    try:
        info = os.lstat(path)
    except FileNotFoundError:
        return False
    return (
        stat.S_ISDIR(info.st_mode)
        and not stat.S_ISLNK(info.st_mode)
        and info.st_uid == 0
        and info.st_gid == 0
        and not info.st_mode & 0o022
        and (exact_mode is None or stat.S_IMODE(info.st_mode) == exact_mode)
        and os.path.realpath(path) == path
    )


def safe_backup_file(path):
    try:
        info = os.lstat(path)
    except FileNotFoundError:
        return False
    return (
        stat.S_ISREG(info.st_mode)
        and not stat.S_ISLNK(info.st_mode)
        and info.st_uid == 0
        and info.st_gid == 0
        and info.st_nlink == 1
        and stat.S_IMODE(info.st_mode) == 0o600
    )


def write_exclusive(path, payload):
    descriptor = os.open(
        path,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())


def digest(payload):
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def validate_sealed_backup():
    manifest_path = os.path.join(backup_dir, "manifest.json")
    if not safe_backup_file(manifest_path):
        return False
    try:
        with open(manifest_path, "r", encoding="utf-8") as handle:
            manifest = json.load(handle)
    except (OSError, ValueError):
        raise SystemExit("the existing firewall backup manifest is invalid")
    if (
        set(manifest) != {"schema", "transactionId", "createdAt", "snapshots"}
        or manifest.get("schema") != "bridgesllm.firewall-wipe-backup.v1"
        or manifest.get("transactionId") != transaction_id
        or not isinstance(manifest.get("createdAt"), str)
        or set(manifest.get("snapshots", {})) != {"iptables", "ip6tables"}
    ):
        raise SystemExit("the existing firewall backup manifest is invalid")
    for tool in ("iptables", "ip6tables"):
        record = manifest["snapshots"].get(tool)
        rules_path = os.path.join(backup_dir, f"{tool}.rules")
        if (
            not isinstance(record, dict)
            or set(record) != {"bytes", "sha256"}
            or not isinstance(record.get("bytes"), int)
            or record["bytes"] < 0
            or not isinstance(record.get("sha256"), str)
            or not re.fullmatch(r"[a-f0-9]{64}", record["sha256"])
            or not safe_backup_file(rules_path)
        ):
            raise SystemExit("the existing firewall backup is incomplete or unsafe")
        with open(rules_path, "r", encoding="utf-8") as handle:
            payload = handle.read(MAX_COMMAND_BYTES + 1)
        if (
            len(payload.encode("utf-8")) != record["bytes"]
            or digest(payload) != record["sha256"]
        ):
            raise SystemExit("the existing firewall backup does not match its manifest")
    return True


for parent in (mapped_path("/var"), mapped_path("/var/backups")):
    if not safe_root_directory(parent):
        raise SystemExit("the firewall backup parent is unsafe")
if not os.path.lexists(BACKUP_BASE):
    os.mkdir(BACKUP_BASE, 0o700)
    fsync_dir(mapped_path("/var/backups"))
if not safe_root_directory(BACKUP_BASE):
    raise SystemExit("the firewall backup root is unsafe")
try:
    os.mkdir(backup_dir, 0o700)
    fsync_dir(BACKUP_BASE)
except FileExistsError:
    pass
if not safe_root_directory(backup_dir, 0o700):
    raise SystemExit("the firewall backup directory is unsafe")

if not validate_sealed_backup():
    # A missing manifest is an interrupted pre-delete seal. This version never
    # mutates Docker, files, or firewall state until the manifest is durable,
    # so only exact root-owned partial files may be refreshed here.
    allowed_partial = {"iptables.rules", "ip6tables.rules", "manifest.json"}
    for name in os.listdir(backup_dir):
        path = os.path.join(backup_dir, name)
        if name not in allowed_partial or not safe_backup_file(path):
            raise SystemExit("the incomplete firewall backup contains an unsafe entry")
        os.unlink(path)
    fsync_dir(backup_dir)
    snapshots = {}
    for tool in ("iptables", "ip6tables"):
        saver = trusted_binary(f"{tool}-save")
        if saver is None:
            raise SystemExit(
                f"{tool}-save is unavailable; refusing to touch the firewall without a backup")
        snapshot = run([saver])
        write_exclusive(os.path.join(backup_dir, f"{tool}.rules"), snapshot)
        snapshots[tool] = {
            "bytes": len(snapshot.encode("utf-8")),
            "sha256": digest(snapshot),
        }
    manifest = {
        "schema": "bridgesllm.firewall-wipe-backup.v1",
        "transactionId": transaction_id,
        "createdAt": datetime.datetime.now(datetime.timezone.utc)
            .replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "snapshots": snapshots,
    }
    write_exclusive(
        os.path.join(backup_dir, "manifest.json"),
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
    )
    fsync_dir(backup_dir)
    if not validate_sealed_backup():
        raise SystemExit("the firewall backup could not be durably sealed")


def fixture_path_crash(point):
    if not TEST_ROOT:
        return
    control = os.path.join(
        TEST_ROOT, "state", "managed-path-crash-point")
    try:
        with open(control, "r", encoding="utf-8") as handle:
            requested = handle.read(128).strip()
    except FileNotFoundError:
        return
    if requested != point:
        return
    os.unlink(control)
    raise SystemExit(f"fixture crash after managed path {point}")


def ensure_receipt_directory():
    info = os.lstat(transaction_directory)
    if (
        not stat.S_ISDIR(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or stat.S_IMODE(info.st_mode) != 0o700
        or os.path.realpath(transaction_directory) != transaction_directory
    ):
        raise SystemExit(
            "the uninstall transaction directory is unsafe for deletion receipts")
    if not os.path.lexists(receipt_directory):
        os.mkdir(receipt_directory, 0o700)
        fsync_dir(transaction_directory)
    if not validate_receipt_directory():
        raise SystemExit("the path-deletion receipt directory could not be sealed")


def write_path_receipt(record):
    receipt, temporary = receipt_paths(record)
    has_receipt, has_temporary = receipt_state(record)
    if has_receipt:
        if has_temporary:
            os.unlink(temporary)
            fsync_dir(receipt_directory)
        return
    if has_temporary:
        os.unlink(temporary)
        fsync_dir(receipt_directory)
    payload = json.dumps(
        expected_receipt(record), indent=2, sort_keys=True) + "\n"
    descriptor = os.open(
        temporary,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL
        | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            descriptor = -1
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    if os.path.lexists(receipt):
        raise SystemExit("the path-deletion receipt raced its atomic publish")
    os.replace(temporary, receipt)
    fsync_dir(receipt_directory)
    has_receipt, has_temporary = receipt_state(record)
    if not has_receipt or has_temporary:
        raise SystemExit("the path-deletion receipt was not committed durably")


def assert_opened_inode(descriptor, record):
    opened = os.fstat(descriptor)
    if (
        opened.st_dev != record["device"]
        or opened.st_ino != record["inode"]
        or opened.st_mode != record["mode"]
        or opened.st_uid != record["uid"]
        or opened.st_gid != record["gid"]
    ):
        raise SystemExit(
            "managed residue inode changed before quarantine")


def prepare_path_quarantine(state):
    record = state["record"]
    original = record["path"]
    quarantine = state["quarantine"]
    if state["state"] == "deleted":
        return
    parent_fd = opened_parent(record)
    try:
        original_name = os.path.basename(original)
        quarantine_name = os.path.basename(quarantine)
        if state["state"] == "original":
            flags = (
                os.O_RDONLY
                | getattr(os, "O_NONBLOCK", 0)
                | getattr(os, "O_NOFOLLOW", 0)
            )
            if record["type"] == "directory":
                flags |= getattr(os, "O_DIRECTORY", 0)
            inode_fd = os.open(
                original_name, flags, dir_fd=parent_fd)
            try:
                assert_opened_inode(inode_fd, record)
                try:
                    os.stat(
                        quarantine_name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    pass
                else:
                    raise SystemExit(
                        "managed residue quarantine appeared before rename")
                os.rename(
                    original_name,
                    quarantine_name,
                    src_dir_fd=parent_fd,
                    dst_dir_fd=parent_fd,
                )
                moved = os.stat(
                    quarantine_name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                if (
                    moved.st_dev != record["device"]
                    or moved.st_ino != record["inode"]
                    or moved.st_mode != record["mode"]
                ):
                    raise SystemExit(
                        "managed residue quarantine changed during rename")
                try:
                    os.stat(
                        original_name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    pass
                else:
                    raise SystemExit(
                        "managed residue original survived quarantine rename")
                os.fsync(parent_fd)
            finally:
                os.close(inode_fd)
            state["state"] = "quarantine"
            fixture_path_crash("quarantine")
        else:
            assert_quarantine_identity(record, quarantine)
    finally:
        os.close(parent_fd)
    write_path_receipt(record)
    fixture_path_crash("receipt")


if planned_paths:
    ensure_receipt_directory()
    for path in sorted(planned_path_states):
        prepare_path_quarantine(planned_path_states[path])


def current_firewall_snapshot(binary):
    return "\n".join(
        normalize_firewall_line(line)
        for line in run([binary, "-w", "-S"]).splitlines()
        if line.strip()
    )


def validate_firewall_mutation_args(args):
    if not args or args[0] not in {"-D", "-X"}:
        return False
    if args[0] == "-X":
        return len(args) == 2 and bool(
            P4E_PROJECT_CHAIN_RE.fullmatch(args[1])
            or A0P_PROJECT_CHAIN_RE.fullmatch(args[1])
            or args[1] in {P4E_MASTER_CHAIN, P4E_HOST_CHAIN}
        )
    if len(args) < 4 or not re.fullmatch(
            r"[A-Za-z0-9_.:-]+", args[1]):
        return False
    targets = [
        args[index + 1]
        for index, token in enumerate(args[:-1])
        if token in {"-j", "-g"}
    ]
    managed_parent = bool(
        P4E_PROJECT_CHAIN_RE.fullmatch(args[1])
        or A0P_PROJECT_CHAIN_RE.fullmatch(args[1])
        or args[1] in {P4E_MASTER_CHAIN, P4E_HOST_CHAIN}
    )
    managed_target = len(targets) == 1 and bool(
        P4E_PROJECT_CHAIN_RE.fullmatch(targets[0])
        or A0P_PROJECT_CHAIN_RE.fullmatch(targets[0])
        or targets[0] in {P4E_MASTER_CHAIN, P4E_HOST_CHAIN}
    )
    return len(targets) == 1 and (managed_parent or managed_target)


if want_project:
    for tool in ("iptables", "ip6tables"):
        state = firewall[tool]
        planned = sealed_plan["firewall"][tool]
        position = firewall_positions[tool]
        expected = (
            planned["initial"] if position == 0
            else planned["mutations"][position - 1]["after"]
        )
        for mutation in planned["mutations"][position:]:
            args = mutation["args"]
            after = mutation["after"]
            if not validate_firewall_mutation_args(args):
                raise SystemExit(
                    "the sealed firewall cleanup plan contains an unsafe command")
            if current_firewall_snapshot(state["binary"]) != expected:
                raise SystemExit(
                    "firewall state raced the scoped cleanup operation")
            run([state["binary"], "-w", *args])
            if current_firewall_snapshot(state["binary"]) != after:
                raise SystemExit(
                    "firewall state did not match the sealed cleanup result")
            expected = after
        final = parse_managed_firewall(
            tool, state["binary"],
            run([state["binary"], "-w", "-S"]),
        )
        if final["chains"] or final["references"]:
            raise SystemExit("Portal firewall residue remained after the sealed wipe")
        removed_count = len(planned["mutations"])
        if removed_count:
            print(
                f"Applied {removed_count} sealed {tool} cleanup operation(s); "
                "the original full firewall backup was preserved.")


for kind, records in (
    ("container", container_records),
    ("network", network_records),
    ("volume", volume_records),
):
    for record in records:
        current = inspect_resource(kind, record["identity"], tolerate_missing=True)
        if current is None or current["attestation"] != record["attestation"]:
            raise SystemExit(f"Docker {kind} changed immediately before deletion")
        if kind == "container":
            run([DOCKER, "container", "rm", "--force", record["identity"]])
        elif kind == "network":
            run([DOCKER, "network", "rm", record["identity"]])
        else:
            run([DOCKER, "volume", "rm", record["identity"]])
        remaining_identities = docker_identities(kind)
        if record["identity"] in remaining_identities:
            raise SystemExit(f"Docker {kind} remained after its sealed deletion")
        if inspect_resource(
            kind, record["identity"], tolerate_missing=True
        ) is not None:
            raise SystemExit(
                f"Docker {kind} remained inspectable after its sealed deletion")
        print(f"Removed Docker {kind} {record['name']}")


def secure_remove_quarantine(state):
    record = state["record"]
    path = state["quarantine"]
    has_receipt, has_temporary = receipt_state(record)
    if not has_receipt or has_temporary:
        raise SystemExit(
            "managed residue quarantine lacks its durable deletion receipt")
    if os.path.lexists(record["path"]):
        raise SystemExit(
            "managed residue original reappeared before quarantine deletion")
    assert_quarantine_identity(record, path)
    parent_fd = opened_parent(record)
    quarantine_name = os.path.basename(path)
    flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    root_fd = os.open(quarantine_name, flags, dir_fd=parent_fd)
    try:
        root_info = os.fstat(root_fd)
        root_mount_id = descriptor_mount_id(root_fd)
        if (
            root_info.st_dev != record["device"]
            or root_info.st_ino != record["inode"]
            or root_info.st_mode != record["mode"]
            or root_mount_id != descriptor_mount_id(parent_fd)
        ):
            raise SystemExit(
                "managed Agent Zero directory changed mount or inode "
                "identity immediately before deletion")

        def remove_contents(
            parent_fd, parent_path, root_device, root_mount_id
        ):
            if descriptor_mount_id(parent_fd) != root_mount_id:
                raise SystemExit(
                    "managed Agent Zero residue crossed a mount identity")
            for entry in list(os.scandir(parent_fd)):
                child_path = os.path.join(parent_path, entry.name)
                before = os.stat(
                    entry.name, dir_fd=parent_fd, follow_symlinks=False)
                if stat.S_ISDIR(before.st_mode):
                    if (
                        before.st_dev != root_device
                        or any(
                            mountpoint == child_path
                            or mountpoint.startswith(child_path + os.sep)
                            for mountpoint in current_mountpoints()
                        )
                    ):
                        raise SystemExit(
                            "managed Agent Zero residue gained a mount boundary")
                    child_fd = os.open(
                        entry.name, flags, dir_fd=parent_fd)
                    try:
                        opened = os.fstat(child_fd)
                        if (
                            (opened.st_dev, opened.st_ino) != (
                                before.st_dev, before.st_ino
                            )
                            or descriptor_mount_id(child_fd)
                                != root_mount_id
                        ):
                            raise SystemExit(
                                "managed residue directory raced or crossed "
                                "a mount during deletion")
                        remove_contents(
                            child_fd,
                            child_path,
                            root_device,
                            root_mount_id,
                        )
                    finally:
                        os.close(child_fd)
                    after = os.stat(
                        entry.name, dir_fd=parent_fd, follow_symlinks=False)
                    if (after.st_dev, after.st_ino) != (
                        before.st_dev, before.st_ino
                    ):
                        raise SystemExit(
                            "managed residue directory raced deletion")
                    os.rmdir(entry.name, dir_fd=parent_fd)
                    fixture_path_crash("mid-delete")
                else:
                    after = os.stat(
                        entry.name, dir_fd=parent_fd, follow_symlinks=False)
                    if (after.st_dev, after.st_ino, after.st_mode) != (
                        before.st_dev, before.st_ino, before.st_mode
                    ):
                        raise SystemExit("managed residue entry raced deletion")
                    os.unlink(entry.name, dir_fd=parent_fd)
                    fixture_path_crash("mid-delete")

        remove_contents(
            root_fd, path, root_info.st_dev, root_mount_id)
        rebound = os.stat(
            quarantine_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            rebound.st_dev != record["device"]
            or rebound.st_ino != record["inode"]
            or rebound.st_mode != record["mode"]
        ):
            raise SystemExit(
                "managed residue quarantine changed during deletion")
        os.rmdir(quarantine_name, dir_fd=parent_fd)
        fixture_path_crash("directory-root-unlink")
        os.fsync(parent_fd)
    finally:
        os.close(root_fd)
        os.close(parent_fd)


def secure_remove_quarantined_file(state):
    record = state["record"]
    quarantine = state["quarantine"]
    has_receipt, has_temporary = receipt_state(record)
    if not has_receipt or has_temporary:
        raise SystemExit(
            "managed residue quarantine lacks its durable deletion receipt")
    if os.path.lexists(record["path"]):
        raise SystemExit(
            "managed residue original reappeared before quarantine deletion")
    assert_quarantine_identity(record, quarantine)
    parent_fd = opened_parent(record)
    try:
        name = os.path.basename(quarantine)
        before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            before.st_dev != record["device"]
            or before.st_ino != record["inode"]
            or before.st_mode != record["mode"]
            or before.st_nlink != 1
        ):
            raise SystemExit(
                "managed residue file changed before quarantine deletion")
        os.unlink(name, dir_fd=parent_fd)
        fixture_path_crash("file-root-unlink")
        os.fsync(parent_fd)
        fixture_path_crash("mid-delete")
    finally:
        os.close(parent_fd)


for path in sorted(planned_path_states):
    state = planned_path_states[path]
    if state["state"] == "deleted":
        continue
    if state["state"] != "quarantine":
        raise SystemExit(
            "managed filesystem residue was not quarantined before deletion")
    if state["record"]["type"] == "directory":
        secure_remove_quarantine(state)
    else:
        secure_remove_quarantined_file(state)
    if (
        os.path.lexists(state["record"]["path"])
        or os.path.lexists(state["quarantine"])
    ):
        raise SystemExit(
            "managed filesystem residue remained after quarantine deletion")
    state["state"] = "deleted"
    print(f"Removed {state['record']['path']}")
PY
}

resolve_uninstall_residue_policy() {
  local policy
  policy="$(read_uninstall_transaction_field residuePolicy 2>/dev/null || true)"
  case "${policy}" in
    wipe) printf 'wipe' ;;
    *) printf 'safe' ;;
  esac
}

# Resolve leftover managed runtime residue on the helperless repeat clean-slate
# path according to the policy the user confirmed: "safe" finishes the
# uninstall and leaves the residue untouched (the host firewall is never
# edited), "wipe" removes exactly the recognized product shapes after a full
# firewall backup and then re-proves absence through the fail-closed asserts.
handle_helperless_clean_slate_residue() {
  local scope="$1"
  local report first_line policy transaction_id transaction_dir plan_path backup_dir
  policy="$(resolve_uninstall_residue_policy)"
  transaction_id="$(read_uninstall_transaction_field transactionId)" \
    || fail "The uninstall transaction id could not be read before residue handling."
  transaction_dir="$(read_uninstall_transaction_field transactionDir)" \
    || fail "The uninstall transaction directory could not be read before residue handling."
  plan_path="$(read_uninstall_transaction_field residuePlan)" \
    || fail "The uninstall residue plan could not be read."
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ \
    && "${transaction_dir}" == "${UNINSTALL_TRANSACTIONS_ROOT}/${transaction_id}" \
    && "${plan_path}" == "${transaction_dir}/residue-plan.json" ]] \
    || fail "The uninstall residue plan escaped its exact transaction boundary."
  if [[ "${policy}" == "wipe" ]]; then
    backup_dir="/var/backups/bridgesllm/firewall-wipe-${transaction_id}"
    info "Complete wipe: removing leftover managed runtime residue (firewall backup: ${backup_dir})..."
    managed_runtime_residue_tool wipe "${scope}" "${backup_dir}" "${plan_path}" \
      || fail "Leftover managed runtime residue could not be removed completely; clean-slate uninstall was aborted. The firewall backup (if written) is at ${backup_dir}."
    case "${scope}" in
      project) assert_no_managed_project_runtime_residuals ;;
      agent-zero) assert_no_managed_agent_zero_runtime_residuals ;;
      all)
        assert_no_managed_project_runtime_residuals
        assert_no_managed_agent_zero_runtime_residuals
        ;;
    esac
    if [[ -d "${backup_dir}" && ! -L "${backup_dir}" ]]; then
      UNINSTALL_RESIDUE_WIPE_BACKUP_DIR="${backup_dir}"
      ok "Leftover managed runtime residue removed; firewall backup kept at ${backup_dir}"
    else
      info "Managed runtime residue was already absent; no firewall backup was needed."
    fi
    # Absence is confirmed at each recorded location, not proven host-wide. Say
    # so plainly rather than let "Complete wipe" imply more than it verifies.
    info "Complete wipe confirms each managed path is gone from the location it was recorded at."
    info "A managed path copied or moved elsewhere before this uninstall is not tracked, and that copy remains. Review this host directly if it held sensitive data."
  else
    report="$(managed_runtime_residue_tool report "${scope}")" \
      || fail "Managed runtime residue could not be authoritatively inspected; clean-slate uninstall was aborted."
    first_line="$(head -n 1 <<<"${report}")"
    if [[ "${first_line}" == present=false* ]]; then
      info "Managed runtime residue is already absent; the cleanup helper is no longer required."
      return 0
    fi
    [[ "${first_line}" == present=true* ]] \
      || fail "Managed runtime residue inspection returned an unreadable result; clean-slate uninstall was aborted."
    managed_runtime_residue_tool quiesce "${scope}" "" "${plan_path}" \
      || fail "Safe cleanup could not stop and verify every confirmed managed container; clean-slate uninstall was aborted before deleting data."
    warn "Safe cleanup: leftover managed runtime residue stays on this server (chosen at confirmation):"
    tail -n +2 <<<"${report}" | sed 's/^/      /'
    warn "Re-run the installer with --uninstall and choose Complete wipe to remove it later."
  fi
}

attest_clean_slate_tree() {
  local path="$1"
  local expected_path="$2"
  local contract="${3:-generic}"
  local related_root="${4:-}"
  local mountinfo_file="${5:-/proc/self/mountinfo}"
  python3 - "${path}" "${expected_path}" "${contract}" "${related_root}" "${mountinfo_file}" <<'PY'
import os
import re
import stat
import sys

path, expected, contract, related, mountinfo_path = sys.argv[1:]
for value in (path, expected):
    if not os.path.isabs(value) or value != os.path.normpath(value) or value == os.path.sep:
        raise SystemExit("Clean-slate path must be a bounded canonical absolute path")
if path != expected:
    raise SystemExit("Clean-slate path does not match its exact ownership boundary")

current = os.path.sep
parts = path.strip(os.path.sep).split(os.path.sep)
for index, component in enumerate(parts):
    current = os.path.join(current, component)
    if not os.path.lexists(current):
        print("absent")
        raise SystemExit(0)
    info = os.lstat(current)
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode) or info.st_uid != 0:
        raise SystemExit("Clean-slate path crosses an unsafe ownership boundary")
    if info.st_mode & 0o022:
        if index == len(parts) - 1 or not info.st_mode & stat.S_ISVTX:
            raise SystemExit("Clean-slate path crosses a writable ownership boundary")
if os.path.realpath(path) != path:
    raise SystemExit("Clean-slate path does not resolve to its exact boundary")

def decode_mount(value: str) -> str:
    return (value.replace("\\040", " ").replace("\\011", "\t")
                 .replace("\\012", "\n").replace("\\134", "\\"))

try:
    with open(mountinfo_path, "r", encoding="utf-8") as handle:
        mountpoints = [decode_mount(line.split()[4]) for line in handle if len(line.split()) >= 5]
except OSError as error:
    raise SystemExit(f"Mount topology could not be inspected: {error}")
for mountpoint in mountpoints:
    if mountpoint == path or mountpoint.startswith(path + os.sep):
        raise SystemExit("Clean-slate path contains a mount or bind-mount boundary")

def owned_dir(candidate: str) -> bool:
    try:
        info = os.lstat(candidate)
    except FileNotFoundError:
        return False
    return stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode) and info.st_uid == 0 and not info.st_mode & 0o022

def owned_file(candidate: str) -> bool:
    try:
        info = os.lstat(candidate)
    except FileNotFoundError:
        return False
    return stat.S_ISREG(info.st_mode) and not stat.S_ISLNK(info.st_mode) and info.st_uid == 0 and info.st_nlink == 1 and not info.st_mode & 0o022

def safe_owned_root(candidate: str) -> bool:
    if not candidate or not os.path.isabs(candidate) or candidate != os.path.normpath(candidate):
        return False
    current = os.path.sep
    components = candidate.strip(os.path.sep).split(os.path.sep)
    for index, component in enumerate(components):
        current = os.path.join(current, component)
        try:
            info = os.lstat(current)
        except FileNotFoundError:
            return False
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode) or info.st_uid != 0:
            return False
        if info.st_mode & 0o022 and (index == len(components) - 1 or not info.st_mode & stat.S_ISVTX):
            return False
    return os.path.realpath(candidate) == candidate

if contract == "portal":
    # A legacy Portal root is attributed by owned, Portal-specific directory
    # markers. `projects` is the usual one, but a legacy tree that never had a
    # Project created still contains the other Portal-owned roots. Requiring
    # `projects` unconditionally made clean-slate uninstall abort outright on
    # such a tree -- and it aborted *after* the database had already been
    # dropped, leaving the host neither working nor uninstalled.
    #
    # Accept either marker set. Both are equally Portal-specific, so this does
    # not widen attribution to a foreign /portal: an unrelated directory of
    # that name still has none of these owned subdirectories and is still
    # refused.
    # A legacy Portal root is attributed by owned, Portal-specific markers.
    # Two distinct shapes exist in the wild and BOTH must be accepted:
    #
    #  - a runtime tree, identified by owned `.data` or by signed
    #    backend/frontend package identities; and
    #  - a data-only tree left by older installs, which has none of those but
    #    does have Portal's own data roots (app-zips, apps, project-zips).
    #
    # Requiring the runtime markers unconditionally made clean-slate uninstall
    # abort on the data-only shape -- the common case on an upgraded host --
    # exactly as requiring `projects` did. Either shape is sufficient identity;
    # a foreign directory called /portal has neither and is still refused.
    portal_data_markers = [
        name for name in ("projects", "app-zips", "project-zips", "apps")
        if owned_dir(os.path.join(path, name))
    ]
    attributed_by_data = (
        "projects" in portal_data_markers or len(portal_data_markers) >= 2
    )

    attributed_by_runtime = owned_dir(os.path.join(path, ".data"))
    if not attributed_by_runtime:
        backend_package = os.path.join(path, "backend", "package.json")
        frontend_package = os.path.join(path, "frontend", "package.json")
        if owned_file(backend_package) and owned_file(frontend_package):
            import json
            try:
                with open(backend_package, "r", encoding="utf-8") as handle:
                    backend = json.load(handle)
                with open(frontend_package, "r", encoding="utf-8") as handle:
                    frontend = json.load(handle)
            except (OSError, ValueError):
                raise SystemExit("Legacy Portal package identity markers are unreadable")
            if (backend.get("name") != "bridgesllm-backend"
                    or frontend.get("name") != "bridgesllm-frontend"):
                raise SystemExit("Legacy Portal package identity markers do not match")
            attributed_by_runtime = True

    if not attributed_by_data and not attributed_by_runtime:
        raise SystemExit("Legacy Portal root lacks any owned Portal identity marker")
elif contract == "apps":
    if not safe_owned_root(related) or not owned_dir(os.path.join(related, "projects")):
        raise SystemExit("Legacy app root cannot be tied to an owned Portal projects root")
    uuid_prefix = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}-")
    for name in os.listdir(path):
        candidate = os.path.join(path, name)
        if not uuid_prefix.match(name) or not owned_dir(candidate):
            raise SystemExit("Legacy app root contains an unattributable entry")
        owner_id = name[:36]
        if not owned_dir(os.path.join(related, "projects", owner_id)):
            raise SystemExit("Legacy app entry has no matching owned Portal project identity")
elif contract == "portal-files":
    modern_marker = os.path.join(related, "portal", "installer", "install.sh") if related else ""
    legacy_projects = os.path.join(related, "projects") if related else ""
    legacy_state = os.path.join(related, ".data") if related else ""
    if not safe_owned_root(related) or not ((modern_marker and owned_file(modern_marker))
            or (legacy_projects and owned_dir(legacy_projects) and owned_dir(legacy_state))):
        raise SystemExit("Portal file root cannot be tied to an owned Portal installation")
elif contract == "stalwart-legacy-store":
    marker = os.path.join(path, "data", "IDENTITY")
    if not owned_file(marker):
        raise SystemExit("Legacy Stalwart store lacks its owned identity marker")
    with open(marker, "r", encoding="ascii") as handle:
        identity = handle.read(128).strip()
    if not re.fullmatch(r"[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}", identity):
        raise SystemExit("Legacy Stalwart identity marker is malformed")
elif contract == "stalwart-legacy-mail":
    marker = os.path.join(path, "etc", "config.toml")
    if not owned_file(marker):
        raise SystemExit("Legacy Stalwart mail root lacks its owned config marker")
    with open(marker, "r", encoding="utf-8") as handle:
        first_line = handle.readline().rstrip("\r\n")
    if first_line not in {"# Stalwart Mail Server - BridgesLLM", "# Stalwart Mail Server — BridgesLLM Portal"}:
        raise SystemExit("Legacy Stalwart config marker is not Portal-authored")
elif contract == "install-root":
    marker = os.path.join(path, "portal", "installer", "install.sh")
    if not owned_file(marker):
        raise SystemExit("Install root lacks the Portal installer ownership marker")
elif contract != "generic":
    raise SystemExit("Unknown clean-slate ownership contract")

info = os.lstat(path)
print(f"{info.st_dev}:{info.st_ino}")
PY
}

remove_attested_clean_slate_tree() {
  local path="$1"
  local expected_path="$2"
  local contract="${3:-generic}"
  local related_root="${4:-}"
  local mountinfo_file="${5:-/proc/self/mountinfo}"
  local attestation
  attestation="$(attest_clean_slate_tree "${path}" "${expected_path}" "${contract}" "${related_root}" "${mountinfo_file}")" \
    || return 1
  [[ "${attestation}" != "absent" ]] || return 0
  rm -rf --one-file-system -- "${path}" || return 1
  [[ ! -e "${path}" && ! -L "${path}" ]]
}

# Prove every legacy tree can be attributed BEFORE anything is destroyed.
#
# Clean-slate uninstall is a phase machine whose destructive steps (Agent Zero,
# Stalwart, the Portal database and role) all run before legacy attribution.
# When attribution failed, the database was already gone and the host was left
# neither working nor uninstalled -- and re-running could not finish, because
# the same gate failed again with nothing left to roll back to.
#
# This runs the identical attestations read-only, up front, so an
# unattributable tree fails while the system is still intact and the operator
# still has a working Portal.
assert_clean_slate_legacy_attribution() {
  local legacy_portal_root="${1:-/portal}"
  local legacy_apps_root="${2:-/var/www/bridgesllm-apps}"
  local portal_files_root="${3:-/var/portal-files}"
  local related_install_root="${4:-${INSTALL_ROOT}}"

  if [[ -e "${legacy_apps_root}" || -L "${legacy_apps_root}" ]]; then
    attest_clean_slate_tree \
      "${legacy_apps_root}" "${legacy_apps_root}" apps "${legacy_portal_root}" >/dev/null \
      || fail "Legacy hosted-app data cannot be attributed. Nothing was removed. Resolve this before uninstalling."
  fi
  if [[ -e "${portal_files_root}" || -L "${portal_files_root}" ]]; then
    if ! attest_clean_slate_tree \
        "${portal_files_root}" "${portal_files_root}" portal-files "${related_install_root}" >/dev/null 2>&1 \
      && ! attest_clean_slate_tree \
        "${portal_files_root}" "${portal_files_root}" portal-files "${legacy_portal_root}" >/dev/null 2>&1; then
      fail "Portal upload data at ${portal_files_root} cannot be attributed to this Portal, so nothing was removed. Inspect that path and move or delete it if it is not Portal data."
    fi
  fi
  if [[ -e "${legacy_portal_root}" || -L "${legacy_portal_root}" ]]; then
    attest_clean_slate_tree \
      "${legacy_portal_root}" "${legacy_portal_root}" portal "${related_install_root}" >/dev/null \
      || fail "Legacy Portal data at ${legacy_portal_root} cannot be attributed to this Portal, so nothing was removed. Inspect that path: if it is not Portal data, move or delete it and retry; a stray ${legacy_portal_root} can be created by running Portal tooling without PORTAL_DATA_ROOT set."
  fi
  return 0
}

remove_legacy_portal_data_for_clean_uninstall() {
  local legacy_portal_root="${1:-/portal}"
  local legacy_apps_root="${2:-/var/www/bridgesllm-apps}"
  local portal_files_root="${3:-/var/portal-files}"
  local expected_legacy_portal_root="${4:-/portal}"
  local expected_legacy_apps_root="${5:-/var/www/bridgesllm-apps}"
  local expected_portal_files_root="${6:-/var/portal-files}"
  local related_install_root="${7:-${INSTALL_ROOT}}"

  # App ownership is tied to user/project identities in the legacy Portal
  # root, so it must be checked and removed before that root disappears.
  if [[ -e "${legacy_apps_root}" || -L "${legacy_apps_root}" ]]; then
    remove_attested_clean_slate_tree \
      "${legacy_apps_root}" "${expected_legacy_apps_root}" apps "${legacy_portal_root}" \
      || fail "Legacy hosted-app data could not be attributed and removed safely; clean-slate uninstall was aborted."
  fi
  if [[ -e "${portal_files_root}" || -L "${portal_files_root}" ]]; then
    if remove_attested_clean_slate_tree \
        "${portal_files_root}" "${expected_portal_files_root}" portal-files "${related_install_root}" 2>/dev/null; then
      :
    elif remove_attested_clean_slate_tree \
        "${portal_files_root}" "${expected_portal_files_root}" portal-files "${legacy_portal_root}"; then
      :
    else
      fail "Portal upload data could not be attributed and removed safely; clean-slate uninstall was aborted."
    fi
  fi
  if [[ -e "${legacy_portal_root}" || -L "${legacy_portal_root}" ]]; then
    remove_attested_clean_slate_tree \
      "${legacy_portal_root}" "${expected_legacy_portal_root}" portal \
      || fail "Legacy Portal data could not be attributed and removed safely; clean-slate uninstall was aborted."
  fi
}

remove_install_root_for_clean_uninstall() {
  local install_root="${1:-${INSTALL_ROOT}}"
  local expected_install_root="${2:-${INSTALL_ROOT}}"
  if [[ ! -f "${install_root}/portal/installer/install.sh" \
    && ( -e "${install_root}/.retained-install-v1.json" \
      || -L "${install_root}/.retained-install-v1.json" ) ]]; then
    verify_retained_install_receipt \
      "${install_root}/portal" \
      "${install_root}/.retained-install-v1.json" \
      "${install_root}/.retained-install-tree-v1.json" \
      || fail "The retained install receipt no longer matches its exact Portal tree; clean-slate removal was paused."
    remove_attested_clean_slate_tree \
      "${install_root}" "${expected_install_root}" generic \
      || fail "The retained Portal install root could not be removed safely."
    return 0
  fi
  remove_attested_clean_slate_tree "${install_root}" "${expected_install_root}" install-root \
    || fail "Portal install root could not be attributed and removed safely; clean-slate uninstall was aborted."
}

attest_stalwart_compose_tree() {
  local stalwart_dir="$1"
  local expected_stalwart_dir="$2"
  local tree_attestation
  tree_attestation="$(attest_clean_slate_tree "${stalwart_dir}" "${expected_stalwart_dir}" generic)" \
    || return 1
  [[ "${tree_attestation}" != "absent" ]] || return 1
  python3 - "${stalwart_dir}" <<'PY'
import os
import stat
import sys

root = sys.argv[1]
compose = os.path.join(root, "docker-compose.yml")
expected = """version: '3.8'
services:
  stalwart:
    image: stalwartlabs/stalwart:v0.15.5
    container_name: stalwart-mail
    restart: unless-stopped
    ports:
      - "25:25"
      - "587:587"
      - "993:993"
      - "127.0.0.1:8580:8080"
    volumes:
      - ./data:/opt/stalwart
"""
info = os.lstat(compose)
if not stat.S_ISREG(info.st_mode) or stat.S_ISLNK(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1 or info.st_mode & 0o022 or info.st_size > 4096:
    raise SystemExit("Managed Stalwart compose file is unsafe")
with open(compose, "r", encoding="utf-8") as handle:
    if handle.read(4097) != expected:
        raise SystemExit("Managed Stalwart compose content has drifted")
marker = os.path.join(root, "data", "etc", "config.toml")
marker_info = os.lstat(marker)
if not stat.S_ISREG(marker_info.st_mode) or stat.S_ISLNK(marker_info.st_mode) or marker_info.st_uid != 0 or marker_info.st_nlink != 1 or marker_info.st_mode & 0o022:
    raise SystemExit("Managed Stalwart data marker is unsafe")
with open(marker, "r", encoding="utf-8") as handle:
    if handle.readline().rstrip("\r\n") != "# Stalwart Mail Server — BridgesLLM Portal":
        raise SystemExit("Managed Stalwart data marker is not Portal-authored")
PY
}

attest_stalwart_container_contract() {
  local inspect_json="$1"
  local mode="$2"
  local expected_source="$3"
  printf '%s' "${inspect_json}" | python3 /dev/fd/3 "${mode}" "${expected_source}" 3<<'PY'
import json
import os
import sys

mode, expected_source = sys.argv[1:]
try:
    payload = json.load(sys.stdin)
except (ValueError, TypeError):
    raise SystemExit("Stalwart container inspection was not valid JSON")
if isinstance(payload, list):
    if len(payload) != 1:
        raise SystemExit("Stalwart inspection returned an ambiguous container set")
    payload = payload[0]
if not isinstance(payload, dict) or payload.get("Name") != "/stalwart-mail":
    raise SystemExit("Stalwart container identity does not match")
config = payload.get("Config") or {}
host = payload.get("HostConfig") or {}
expected_image = "stalwartlabs/stalwart:v0.15.5" if mode == "modern" else "stalwartlabs/stalwart:latest"
if config.get("Image") != expected_image or host.get("Privileged") is not False:
    raise SystemExit("Stalwart image or privilege contract does not match")
restart = host.get("RestartPolicy") or {}
if restart.get("Name") != "unless-stopped" or restart.get("MaximumRetryCount") not in (0, None):
    raise SystemExit("Stalwart restart contract does not match")
expected_ports = {
    "25/tcp": [{"HostIp": "", "HostPort": "25"}],
    "587/tcp": [{"HostIp": "", "HostPort": "587"}],
    "993/tcp": [{"HostIp": "", "HostPort": "993"}],
    "8080/tcp": [{"HostIp": "127.0.0.1", "HostPort": "8580"}],
}
if host.get("PortBindings") != expected_ports:
    raise SystemExit("Stalwart port contract does not match")
mounts = payload.get("Mounts") or []
if len(mounts) != 1:
    raise SystemExit("Stalwart mount contract is ambiguous")
mount = mounts[0]
if (mount.get("Type") != "bind" or os.path.normpath(mount.get("Source", "")) != expected_source
        or mount.get("Destination") != "/opt/stalwart" or mount.get("RW") is not True):
    raise SystemExit("Stalwart data mount contract does not match")
state = payload.get("State") or {}
print("running" if state.get("Running") is True else "stopped")
PY
}

stop_managed_stalwart_for_clean_uninstall() {
  local stalwart_dir="${1:-${INSTALL_ROOT}/stalwart}"
  local expected_stalwart_dir="${2:-${INSTALL_ROOT}/stalwart}"
  local legacy_store="${3:-/var/stalwart}"
  local legacy_mail="${4:-/var/stalwart-mail}"
  local expected_legacy_store="${5:-/var/stalwart}"
  local expected_legacy_mail="${6:-/var/stalwart-mail}"
  local stalwart_container_names=""
  stalwart_container_names="$(docker container ls --all --format '{{.Names}}' 2>/dev/null)" \
    || fail "Docker state could not be inspected before clean-slate uninstall."
  local mode="legacy"
  local expected_source="${expected_legacy_store}"
  if [[ -e "${stalwart_dir}" || -L "${stalwart_dir}" ]]; then
    attest_stalwart_compose_tree "${stalwart_dir}" "${expected_stalwart_dir}" \
      || fail "Managed Stalwart compose/data ownership could not be attested; clean-slate uninstall was aborted."
    mode="modern"
    expected_source="${expected_stalwart_dir}/data"
  fi

  if grep -Fx 'stalwart-mail' <<< "${stalwart_container_names}" >/dev/null; then
    if [[ "${mode}" == "legacy" ]]; then
      [[ "$(attest_clean_slate_tree "${legacy_store}" "${expected_legacy_store}" stalwart-legacy-store)" != "absent" ]] \
        || fail "Legacy Stalwart store ownership could not be attested; clean-slate uninstall was aborted."
      [[ "$(attest_clean_slate_tree "${legacy_mail}" "${expected_legacy_mail}" stalwart-legacy-mail)" != "absent" ]] \
        || fail "Legacy Stalwart mail ownership could not be attested; clean-slate uninstall was aborted."
    fi
    local inspect_json container_state
    inspect_json="$(docker container inspect stalwart-mail 2>/dev/null)" \
      || fail "The stalwart-mail container could not be inspected; clean-slate uninstall was aborted."
    container_state="$(attest_stalwart_container_contract "${inspect_json}" "${mode}" "${expected_source}")" \
      || fail "The stalwart-mail container does not match the Portal ownership contract; clean-slate uninstall was aborted."
    info "Stopping mail server..."
    if [[ "${container_state}" == "running" ]]; then
      docker container stop --time 30 stalwart-mail >/dev/null 2>&1 \
        || fail "Managed Stalwart mail could not be stopped; clean-slate uninstall was aborted."
    fi
    docker container rm stalwart-mail >/dev/null 2>&1 \
      || fail "Managed Stalwart mail container could not be removed; clean-slate uninstall was aborted."
  fi

  stalwart_container_names="$(docker container ls --all --format '{{.Names}}' 2>/dev/null)" \
    || fail "Docker state could not be re-inspected after Stalwart cleanup."
  grep -Fx 'stalwart-mail' <<< "${stalwart_container_names}" >/dev/null \
    && fail "The managed stalwart-mail container still exists; clean-slate uninstall was aborted."

  # These are the two supported legacy stores. They are removed only after the
  # exact legacy container is absent and each root independently proves Portal
  # ownership. Modern installs keep their data under INSTALL_ROOT.
  if [[ -e "${legacy_store}" || -L "${legacy_store}" ]]; then
    remove_attested_clean_slate_tree "${legacy_store}" "${expected_legacy_store}" stalwart-legacy-store \
      || fail "Legacy Stalwart store could not be removed safely; clean-slate uninstall was aborted."
  fi
  if [[ -e "${legacy_mail}" || -L "${legacy_mail}" ]]; then
    remove_attested_clean_slate_tree "${legacy_mail}" "${expected_legacy_mail}" stalwart-legacy-mail \
      || fail "Legacy Stalwart mail root could not be removed safely; clean-slate uninstall was aborted."
  fi
}

is_installer_default_database_url() {
  local database_url="${1:-}"
  [[ -n "${database_url}" ]] || return 1

  # Parse through the same credential-safe helper used by migrations and
  # backups. Percent-encoding and non-identity libpq options are valid, but an
  # alternate scheme, endpoint, account, database, missing password, fragment,
  # or query-string identity override is not the installer-owned fallback.
  [[ "$(pg_url_component "${database_url}" host 2>/dev/null)" == '127.0.0.1' \
    && "$(pg_url_component "${database_url}" port 2>/dev/null)" == '5432' \
    && "$(pg_url_component "${database_url}" database 2>/dev/null)" == 'bridgesllm_portal' \
    && "$(pg_url_component "${database_url}" user 2>/dev/null)" == 'blp' ]] \
    || return 1
  pg_url_component "${database_url}" password >/dev/null 2>&1 || return 1

  printf '%s' "${database_url}" | python3 /dev/fd/3 3<<'PY2'
import sys
from urllib.parse import urlsplit

raw = sys.stdin.read()
try:
    parsed = urlsplit(raw)
except ValueError:
    raise SystemExit(1)
raise SystemExit(0 if parsed.scheme == "postgresql" else 1)
PY2
}

default_portal_database_catalog_is_exclusive() {
  # The URL proves only the configured endpoint/name. It does not prove that a
  # pre-existing role/database was created for this Portal. Require the target
  # database to be owned by blp and reject every blp-owned database or shared
  # dependency outside that target before issuing any terminating or DROP SQL.
  local owner_match other_database_count external_dependency_count
  owner_match="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --tuples-only --no-align \
    --command="SELECT 1 FROM pg_database d JOIN pg_roles r ON r.oid = d.datdba WHERE d.datname = 'bridgesllm_portal' AND r.rolname = 'blp';")" \
    || return 1
  [[ "${owner_match//[[:space:]]/}" == '1' ]] || return 1

  other_database_count="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --tuples-only --no-align \
    --command="SELECT count(*) FROM pg_database d JOIN pg_roles r ON r.oid = d.datdba WHERE r.rolname = 'blp' AND d.datname <> 'bridgesllm_portal';")" \
    || return 1
  [[ "${other_database_count//[[:space:]]/}" == '0' ]] || return 1

  external_dependency_count="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --tuples-only --no-align \
    --command="WITH target AS (SELECT oid FROM pg_database WHERE datname = 'bridgesllm_portal'), portal_role AS (SELECT oid FROM pg_roles WHERE rolname = 'blp') SELECT count(*) FROM pg_shdepend dep CROSS JOIN target CROSS JOIN portal_role WHERE dep.refclassid = 'pg_authid'::regclass AND dep.refobjid = portal_role.oid AND NOT (dep.dbid = target.oid OR (dep.dbid = 0 AND dep.classid = 'pg_database'::regclass AND dep.objid = target.oid));")" \
    || return 1
  [[ "${external_dependency_count//[[:space:]]/}" == '0' ]]
}

remove_default_portal_database_for_clean_uninstall() {
  info "Removing default local Portal database..."
  sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --command="SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = 'bridgesllm_portal' AND pid <> pg_backend_pid();" >/dev/null \
    || fail "Default local Portal database connections could not be stopped; clean-slate uninstall was aborted."
  sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --command='DROP DATABASE IF EXISTS bridgesllm_portal;' >/dev/null \
    || fail "Default local Portal database could not be removed; clean-slate uninstall was aborted."

  local remaining_role_dependencies=""
  remaining_role_dependencies="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --tuples-only --no-align \
    --command="SELECT count(*) FROM pg_shdepend dep JOIN pg_roles r ON dep.refclassid = 'pg_authid'::regclass AND dep.refobjid = r.oid WHERE r.rolname = 'blp';")" \
    || fail "Default local Portal role dependencies could not be re-inspected after database removal."
  [[ "${remaining_role_dependencies//[[:space:]]/}" == '0' ]] \
    || fail "The blp role gained or retained external dependencies; role removal was aborted."
  sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --command='DROP ROLE IF EXISTS blp;' >/dev/null \
    || fail "Default local Portal database role could not be removed; clean-slate uninstall was aborted."

  local database_present=""
  database_present="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --tuples-only --no-align \
    --command="SELECT 1 FROM pg_database WHERE datname = 'bridgesllm_portal';")" \
    || fail "Default local Portal database removal could not be verified."
  [[ -z "${database_present//[[:space:]]/}" ]] \
    || fail "Default local Portal database still exists; clean-slate uninstall was aborted."

  local role_present=""
  role_present="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --tuples-only --no-align \
    --command="SELECT 1 FROM pg_roles WHERE rolname = 'blp';")" \
    || fail "Default local Portal database role removal could not be verified."
  [[ -z "${role_present//[[:space:]]/}" ]] \
    || fail "Default local Portal database role still exists; clean-slate uninstall was aborted."
  ok "Default local Portal database and role removed"
}

remove_configured_default_database_for_clean_uninstall() {
  local configured_url="${1:-}"
  if ! is_installer_default_database_url "${configured_url}"; then
    warn "The configured database is missing, unreadable, or not the exact installer-owned local default; local PostgreSQL databases and roles were preserved."
    return 0
  fi

  command -v psql >/dev/null 2>&1 \
    || fail "The exact installer-owned database is configured, but PostgreSQL tools are unavailable; clean-slate uninstall was paused before forgetting its credentials."
  local database_present role_present
  database_present="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --tuples-only --no-align \
    --command="SELECT count(*) FROM pg_database WHERE datname = 'bridgesllm_portal';")" \
    || fail "The configured local Portal database could not be inspected; clean-slate uninstall was paused."
  role_present="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
    --tuples-only --no-align \
    --command="SELECT count(*) FROM pg_roles WHERE rolname = 'blp';")" \
    || fail "The configured local Portal role could not be inspected; clean-slate uninstall was paused."
  database_present="${database_present//[[:space:]]/}"
  role_present="${role_present//[[:space:]]/}"
  [[ "${database_present}" == "0" || "${database_present}" == "1" ]] \
    || fail "The local Portal database catalog returned an invalid identity count."
  [[ "${role_present}" == "0" || "${role_present}" == "1" ]] \
    || fail "The local Portal role catalog returned an invalid identity count."

  if [[ "${database_present}" == "0" && "${role_present}" == "0" ]]; then
    ok "Default local Portal database and role are already absent"
    return 0
  fi
  if [[ "${database_present}" == "1" && "${role_present}" == "1" ]]; then
    default_portal_database_catalog_is_exclusive \
      || fail "The local blp role/database is externally owned, shared, or ambiguous; clean-slate uninstall was paused before deleting it."
    remove_default_portal_database_for_clean_uninstall
    return 0
  fi
  if [[ "${database_present}" == "0" && "${role_present}" == "1" ]]; then
    local remaining_role_dependencies
    remaining_role_dependencies="$(sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
      --tuples-only --no-align \
      --command="SELECT count(*) FROM pg_shdepend dep JOIN pg_roles r ON dep.refclassid = 'pg_authid'::regclass AND dep.refobjid = r.oid WHERE r.rolname = 'blp';")" \
      || fail "The partially removed Portal role could not be re-inspected."
    [[ "${remaining_role_dependencies//[[:space:]]/}" == "0" ]] \
      || fail "The partially removed blp role has external dependencies; clean-slate uninstall was paused."
    sudo -u postgres psql --no-psqlrc --dbname=postgres --set=ON_ERROR_STOP=1 \
      --command='DROP ROLE IF EXISTS blp;' >/dev/null \
      || fail "The partially removed Portal role could not be removed."
    ok "Partially removed default local Portal database state converged"
    return 0
  fi
  fail "The default Portal database exists without its expected owner role; clean-slate uninstall was paused rather than guessing ownership."
}

prepare_uninstall_transaction() {
  local mode="$1"
  local env_file="${2:-${PORTAL_DIR}/backend/.env.production}"
  local residue_policy="${3:-safe}"
  [[ "${mode}" == "keep" || "${mode}" == "clean" ]] || return 1
  [[ "${residue_policy}" == "safe" || "${residue_policy}" == "wipe" ]] || return 1
  local transaction_id transaction_dir env_snapshot="" residue_plan=""
  transaction_id="$(openssl rand -hex 16)" || return 1
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ ]] || return 1
  transaction_dir="${UNINSTALL_TRANSACTIONS_ROOT}/${transaction_id}"
  [[ ! -e "${UNINSTALL_ACTIVE_JOURNAL}" && ! -L "${UNINSTALL_ACTIVE_JOURNAL}" ]] \
    || return 1
  # The shared journal root is named explicitly. `install -d` applies -m only
  # to the last component it creates, so letting it appear implicitly as a
  # parent leaves it 0755 -- which later fails the update admission contract
  # and makes every future update on this host refuse to start.
  install -d -m 700 -o root -g root \
    "${UPDATE_STATE_ROOT}" \
    "${UNINSTALL_STATE_ROOT}" "${UNINSTALL_TRANSACTIONS_ROOT}" "${transaction_dir}" \
    || return 1
  if [[ -e "${env_file}" || -L "${env_file}" ]]; then
    [[ -f "${env_file}" && ! -L "${env_file}" ]] || return 1
    assert_env_file_no_duplicate_keys "${env_file}" || return 1
    env_snapshot="${transaction_dir}/portal.env"
    install -m 600 -o root -g root -- "${env_file}" "${env_snapshot}" || return 1
    cmp -s -- "${env_file}" "${env_snapshot}" || return 1
  fi
  if [[ "${mode}" == "clean" ]]; then
    [[ "${UNINSTALL_RESIDUE_PLAN_DIGEST}" =~ ^[a-f0-9]{64}$ ]] || return 1
    residue_plan="${transaction_dir}/residue-plan.json"
    if ! managed_runtime_residue_tool seal-plan all "" \
      "${residue_plan}" "${UNINSTALL_RESIDUE_PLAN_DIGEST}"; then
      rm -rf --one-file-system -- "${transaction_dir}" >/dev/null 2>&1 || true
      fsync_uninstall_directory "${UNINSTALL_TRANSACTIONS_ROOT}" >/dev/null 2>&1 || true
      return 1
    fi
  fi
  python3 - "${UNINSTALL_ACTIVE_JOURNAL}" "${transaction_id}" "${mode}" \
    "${transaction_dir}" "${env_snapshot}" "${VERSION}" "${residue_policy}" \
    "${residue_plan}" "${UNINSTALL_RESIDUE_PLAN_DIGEST}" <<'PY'
import datetime
import json
import os
import re
import stat
import sys
import tempfile

(
    target, transaction_id, mode, transaction_dir, env_snapshot, version,
    residue_policy, residue_plan, residue_plan_digest,
) = sys.argv[1:]
if residue_policy not in {"safe", "wipe"}:
    raise SystemExit(1)
if os.geteuid() != 0:
    raise SystemExit(1)
if not all(os.path.isabs(value) and os.path.normpath(value) == value
           for value in (target, transaction_dir)):
    raise SystemExit(1)
if env_snapshot and (not os.path.isabs(env_snapshot) or os.path.normpath(env_snapshot) != env_snapshot):
    raise SystemExit(1)
if mode == "clean":
    if (
        residue_plan != os.path.join(transaction_dir, "residue-plan.json")
        or not re.fullmatch(r"[a-f0-9]{64}", residue_plan_digest)
    ):
        raise SystemExit(1)
elif residue_plan or residue_plan_digest:
    raise SystemExit(1)
document = {
    "schema": "bridgesllm.uninstall-transaction.v1",
    "transactionId": transaction_id,
    "mode": mode,
    "phase": "prepared",
    "residuePolicy": residue_policy,
    "residuePlan": residue_plan or None,
    "residuePlanDigest": residue_plan_digest or None,
    "transactionDir": transaction_dir,
    "environmentSnapshot": env_snapshot or None,
    "installerVersion": version,
    "startedAt": datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    "terminalDirectoryDeletionIntent": None,
}
directory = os.path.dirname(target)
info = os.lstat(directory)
if (not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0 or info.st_mode & 0o022):
    raise SystemExit(1)
fd, temporary = tempfile.mkstemp(prefix=".active-uninstall.", dir=directory)
try:
    os.fchmod(fd, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        json.dump(document, handle, indent=2, sort_keys=True)
        handle.write("\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, target)
    temporary = ""
    os.chmod(target, 0o600)
    directory_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if temporary:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
PY
  UNINSTALL_TRANSACTION_ID="${transaction_id}"
}

read_uninstall_transaction_field() {
  local field="$1"
  [[ "${field}" =~ ^[A-Za-z][A-Za-z0-9]*$ ]] || return 1
  python3 - "${UNINSTALL_ACTIVE_JOURNAL}" "${field}" <<'PY'
import json
import os
import re
import stat
import sys

path, field = sys.argv[1:]
info = os.lstat(path)
if (not stat.S_ISREG(info.st_mode) or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0 or info.st_gid != 0 or info.st_nlink != 1
        or info.st_mode & 0o022 or info.st_size <= 0 or info.st_size > 65536):
    raise SystemExit(1)
with open(path, "r", encoding="utf-8") as handle:
    document = json.load(handle)
expected_keys = {
    "schema",
    "transactionId",
    "mode",
    "phase",
    "residuePolicy",
    "residuePlan",
    "residuePlanDigest",
    "transactionDir",
    "environmentSnapshot",
    "installerVersion",
    "startedAt",
    "terminalDirectoryDeletionIntent",
}
if (
    not isinstance(document, dict)
    or set(document) != expected_keys
    or document.get("schema") != "bridgesllm.uninstall-transaction.v1"
    or not re.fullmatch(r"[a-f0-9]{32}", str(document.get("transactionId", "")))
    or document.get("mode") not in {"keep", "clean"}
    or document.get("residuePolicy") not in {"safe", "wipe"}
    or not isinstance(document.get("phase"), str)
    or not re.fullmatch(r"[a-z][a-z0-9_]{0,63}", document["phase"])
    or not isinstance(document.get("installerVersion"), str)
    or not document["installerVersion"]
    or not isinstance(document.get("startedAt"), str)
    or not document["startedAt"]
):
    raise SystemExit(1)
transaction_id = document["transactionId"]
transaction_root = os.path.join(os.path.dirname(path), "transactions")
transaction_dir = document.get("transactionDir")
if (
    not isinstance(transaction_dir, str)
    or transaction_dir
        != os.path.join(transaction_root, transaction_id)
    or os.path.normpath(transaction_dir) != transaction_dir
):
    raise SystemExit(1)
environment_snapshot = document.get("environmentSnapshot")
if environment_snapshot not in {
    None, os.path.join(transaction_dir, "portal.env")
}:
    raise SystemExit(1)
expected_plan = os.path.join(
    transaction_dir, "residue-plan.json")
if document.get("mode") == "clean":
    if (
        document.get("residuePlan") != expected_plan
        or not re.fullmatch(
            r"[a-f0-9]{64}", str(document.get("residuePlanDigest", "")))
    ):
        raise SystemExit(1)
elif (
    document.get("residuePlan") is not None
    or document.get("residuePlanDigest") is not None
):
    raise SystemExit(1)
intent = document.get("terminalDirectoryDeletionIntent")
if intent is not None:
    expected_intent_keys = {
        "schema",
        "transactionId",
        "path",
        "device",
        "inode",
        "mode",
        "uid",
        "gid",
        "residuePlanDigest",
    }
    expected_intent_digest = (
        document["residuePlanDigest"]
        if document["mode"] == "clean"
        and document["residuePolicy"] == "wipe"
        else None
    )
    if (
        document["phase"] != "terminal"
        or not isinstance(intent, dict)
        or set(intent) != expected_intent_keys
        or intent.get("schema")
            != "bridgesllm.uninstall-terminal-directory-deletion-intent.v1"
        or intent.get("transactionId") != transaction_id
        or intent.get("path") != transaction_dir
        or not all(
            isinstance(intent.get(name), int)
            and not isinstance(intent.get(name), bool)
            for name in ("device", "inode", "mode", "uid", "gid")
        )
        or intent["device"] < 0
        or intent["inode"] <= 0
        or not stat.S_ISDIR(intent["mode"])
        or stat.S_IMODE(intent["mode"]) != 0o700
        or intent["uid"] != 0
        or intent["gid"] != 0
        or intent.get("residuePlanDigest") != expected_intent_digest
    ):
        raise SystemExit(1)
if field not in document:
    raise SystemExit(1)
value = document.get(field)
if value is None:
    print("")
elif isinstance(value, (str, int, bool)):
    print(str(value).lower() if isinstance(value, bool) else value)
else:
    raise SystemExit(1)
PY
}

advance_uninstall_transaction_phase() {
  local expected="$1"
  local next="$2"
  [[ "${expected}" =~ ^[a-z][a-z0-9_]{0,63}$ \
    && "${next}" =~ ^[a-z][a-z0-9_]{0,63}$ ]] || return 1
  python3 - "${UNINSTALL_ACTIVE_JOURNAL}" "${expected}" "${next}" <<'PY'
import json
import os
import re
import stat
import sys
import tempfile

path, expected, next_phase = sys.argv[1:]
info = os.lstat(path)
if (not stat.S_ISREG(info.st_mode) or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0 or info.st_gid != 0 or info.st_nlink != 1
        or info.st_mode & 0o022 or info.st_size <= 0 or info.st_size > 65536):
    raise SystemExit(1)
with open(path, "r", encoding="utf-8") as handle:
    document = json.load(handle)
expected_keys = {
    "schema",
    "transactionId",
    "mode",
    "phase",
    "residuePolicy",
    "residuePlan",
    "residuePlanDigest",
    "transactionDir",
    "environmentSnapshot",
    "installerVersion",
    "startedAt",
    "terminalDirectoryDeletionIntent",
}
transaction_id = document.get("transactionId")
transaction_root = os.path.join(os.path.dirname(path), "transactions")
transaction_dir = document.get("transactionDir")
expected_plan = (
    os.path.join(transaction_dir, "residue-plan.json")
    if isinstance(transaction_dir, str)
    else ""
)
if (
    not isinstance(document, dict)
    or set(document) != expected_keys
    or document.get("schema") != "bridgesllm.uninstall-transaction.v1"
    or not isinstance(transaction_id, str)
    or not re.fullmatch(r"[a-f0-9]{32}", transaction_id)
    or transaction_dir != os.path.join(transaction_root, transaction_id)
    or os.path.normpath(transaction_dir) != transaction_dir
    or document.get("mode") not in {"keep", "clean"}
    or document.get("residuePolicy") not in {"safe", "wipe"}
    or document.get("phase") != expected
    or not isinstance(document.get("installerVersion"), str)
    or not document["installerVersion"]
    or not isinstance(document.get("startedAt"), str)
    or not document["startedAt"]
    or document.get("environmentSnapshot") not in {
        None, os.path.join(transaction_dir, "portal.env")
    }
    or document.get("terminalDirectoryDeletionIntent") is not None
):
    raise SystemExit(1)
if document["mode"] == "clean":
    if (
        document.get("residuePlan") != expected_plan
        or not re.fullmatch(
            r"[a-f0-9]{64}", str(document.get("residuePlanDigest", "")))
    ):
        raise SystemExit(1)
elif (
    document.get("residuePlan") is not None
    or document.get("residuePlanDigest") is not None
):
    raise SystemExit(1)
document["phase"] = next_phase
directory = os.path.dirname(path)
fd, temporary = tempfile.mkstemp(prefix=".active-uninstall.", dir=directory)
try:
    os.fchmod(fd, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        json.dump(document, handle, indent=2, sort_keys=True)
        handle.write("\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, path)
    temporary = ""
    directory_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if temporary:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
PY
}

install_portal_uninstall_boot_fence() {
  local expected="[Unit]
ConditionPathExists=!${UNINSTALL_ACTIVE_JOURNAL}
"
  install -d -m 755 -o root -g root "${UPDATE_BOOT_FENCE_DROPIN_DIR}" || return 1
  python3 - "${UNINSTALL_BOOT_FENCE_DROPIN}" "${expected}" <<'PY'
import os
import stat
import sys
import tempfile

target, expected = sys.argv[1:]
directory = os.path.dirname(target)
info = os.lstat(directory)
if (not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0 or info.st_gid != 0 or info.st_mode & 0o022):
    raise SystemExit(1)
try:
    current = os.lstat(target)
except FileNotFoundError:
    current = None
if current is not None:
    if (not stat.S_ISREG(current.st_mode) or stat.S_ISLNK(current.st_mode)
            or current.st_uid != 0 or current.st_gid != 0 or current.st_nlink != 1
            or current.st_mode & 0o022 or current.st_size > 4096):
        raise SystemExit(1)
    with open(target, "r", encoding="utf-8") as handle:
        if handle.read() == expected:
            raise SystemExit(0)
    raise SystemExit(1)
fd, temporary = tempfile.mkstemp(prefix=".30-uninstall-fence.", dir=directory)
try:
    os.fchmod(fd, 0o644)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(expected)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, target)
    temporary = ""
finally:
    if temporary:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
PY
  systemctl daemon-reload >/dev/null 2>&1 || return 1
}

remove_exact_portal_tailnet_serve_mapping() {
  local env_file="${1:-}"
  [[ -n "${env_file}" && -f "${env_file}" && ! -L "${env_file}" ]] || return 0
  assert_env_file_no_duplicate_keys "${env_file}" || return 1
  local origin_mode tailnet_name
  origin_mode="$(read_env_value "${env_file}" ORIGIN_MODE 2>/dev/null || true)"
  [[ "${origin_mode}" == "tailnet" ]] || return 0
  tailnet_name="$(read_env_value "${env_file}" TAILNET_DNS_NAME 2>/dev/null || true)"
  [[ "${tailnet_name}" =~ ^[A-Za-z0-9.-]{1,253}$ ]] || return 1
  command -v tailscale >/dev/null 2>&1 || return 1
  local before_file after_file target_port=""
  before_file="$(mktemp /tmp/bridgesllm-tailnet-serve-before.XXXXXX)"
  after_file="$(mktemp /tmp/bridgesllm-tailnet-serve-after.XXXXXX)"
  chmod 600 "${before_file}" "${after_file}"
  if ! tailscale serve status --json > "${before_file}" 2>/dev/null; then
    rm -f -- "${before_file}" "${after_file}"
    return 1
  fi
  target_port="$(python3 - "${before_file}" "${tailnet_name}" <<'PY'
import json
import re
import sys

with open(sys.argv[1], "r", encoding="utf-8") as handle:
    document = json.load(handle)
expected_name = sys.argv[2].rstrip(".").lower()
matches = []
for endpoint, value in (document.get("Web") or {}).items():
    if not isinstance(endpoint, str) or not isinstance(value, dict):
        continue
    host, separator, port = endpoint.rpartition(":")
    if not separator or host.rstrip(".").lower() != expected_name or not port.isdigit():
        continue
    handlers = value.get("Handlers")
    if not isinstance(handlers, dict) or set(handlers) != {"/"}:
        continue
    handler = handlers.get("/")
    proxy = handler.get("Proxy") if isinstance(handler, dict) else None
    if proxy in {"http://127.0.0.1:4001", "http://localhost:4001"}:
        tcp = (document.get("TCP") or {}).get(port)
        if tcp != {"HTTPS": True}:
            raise SystemExit(2)
        matches.append(port)
if len(matches) > 1:
    raise SystemExit(2)
if matches:
    print(matches[0])
PY
)" || { rm -f -- "${before_file}" "${after_file}"; return 1; }
  if [[ -z "${target_port}" ]]; then
    rm -f -- "${before_file}" "${after_file}"
    return 0
  fi
  [[ "${target_port}" =~ ^[0-9]{1,5}$ \
    && "${target_port}" -ge 1 && "${target_port}" -le 65535 ]] \
    || { rm -f -- "${before_file}" "${after_file}"; return 1; }
  tailscale serve --https="${target_port}" off >/dev/null 2>&1 \
    || { rm -f -- "${before_file}" "${after_file}"; return 1; }
  tailscale serve status --json > "${after_file}" 2>/dev/null \
    || { rm -f -- "${before_file}" "${after_file}"; return 1; }
  python3 - "${before_file}" "${after_file}" "${tailnet_name}" "${target_port}" <<'PY'
import copy
import json
import sys

before_path, after_path, tailnet_name, port = sys.argv[1:]
with open(before_path, "r", encoding="utf-8") as handle:
    before = json.load(handle)
with open(after_path, "r", encoding="utf-8") as handle:
    after = json.load(handle)
expected = copy.deepcopy(before)
endpoint = f"{tailnet_name.rstrip('.')}:{port}"
web = expected.get("Web")
tcp = expected.get("TCP")
if not isinstance(web, dict) or not isinstance(tcp, dict):
    raise SystemExit(1)
removed = False
for key in list(web):
    if key.rstrip(".").lower() == endpoint.lower():
        del web[key]
        removed = True
if port in tcp:
    del tcp[port]
    removed = True
if not removed:
    raise SystemExit(1)
if web == {}:
    expected.pop("Web", None)
if tcp == {}:
    expected.pop("TCP", None)
if after != expected:
    raise SystemExit(1)
PY
  local status=$?
  rm -f -- "${before_file}" "${after_file}"
  return "${status}"
}

remove_portal_service_unit_for_uninstall() {
  systemctl disable bridgesllm-product >/dev/null 2>&1 || true
  rm -f -- \
    /etc/systemd/system/bridgesllm-product.service \
    /etc/systemd/system/multi-user.target.wants/bridgesllm-product.service
  systemctl daemon-reload >/dev/null 2>&1 || return 1
  local active_state
  active_state="$(systemctl show --property=ActiveState --value bridgesllm-product 2>/dev/null)" \
    || return 1
  [[ "${active_state}" == "inactive" || "${active_state}" == "failed" ]]
}

# Persist a deletion before the uninstall journal advances past it. These
# helpers are deliberately narrower than rm: only the transaction directory
# or one exact root-owned regular file may be retired, and the containing
# directory is fsynced after the directory entry changes.
fsync_uninstall_directory() {
  local directory="$1"
  python3 - "${directory}" <<'PY'
import os
import stat
import sys

path = sys.argv[1]
info = os.lstat(path)
if (
    not os.path.isabs(path)
    or os.path.normpath(path) != path
    or not stat.S_ISDIR(info.st_mode)
    or stat.S_ISLNK(info.st_mode)
    or info.st_uid != 0
    or info.st_gid != 0
    or info.st_mode & 0o022
):
    raise SystemExit(1)
descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
try:
    os.fsync(descriptor)
finally:
    os.close(descriptor)
PY
}

seal_terminal_uninstall_directory_deletion_intent() {
  local journal_path="$1"
  local transaction_dir="$2"
  python3 - "${journal_path}" "${transaction_dir}" <<'PY'
import json
import os
import re
import stat
import sys
import tempfile

journal_path, transaction_dir = sys.argv[1:]
expected_keys = {
    "schema",
    "transactionId",
    "mode",
    "phase",
    "residuePolicy",
    "residuePlan",
    "residuePlanDigest",
    "transactionDir",
    "environmentSnapshot",
    "installerVersion",
    "startedAt",
    "terminalDirectoryDeletionIntent",
}
expected_intent_keys = {
    "schema",
    "transactionId",
    "path",
    "device",
    "inode",
    "mode",
    "uid",
    "gid",
    "residuePlanDigest",
}


def read_pinned_journal(path):
    before = os.lstat(path)
    if (
        not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or before.st_uid != 0
        or before.st_gid != 0
        or before.st_nlink != 1
        or stat.S_IMODE(before.st_mode) != 0o600
        or not 0 < before.st_size <= 65536
    ):
        raise SystemExit("the terminal uninstall journal is unsafe")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(path, flags)
    try:
        opened = os.fstat(descriptor)
        current = os.lstat(path)
        identity = (
            before.st_dev,
            before.st_ino,
            before.st_mode,
            before.st_uid,
            before.st_gid,
            before.st_nlink,
        )
        if (
            (
                opened.st_dev,
                opened.st_ino,
                opened.st_mode,
                opened.st_uid,
                opened.st_gid,
                opened.st_nlink,
            ) != identity
            or (
                current.st_dev,
                current.st_ino,
                current.st_mode,
                current.st_uid,
                current.st_gid,
                current.st_nlink,
            ) != identity
        ):
            raise SystemExit(
                "the terminal uninstall journal raced its sealed identity")
        with os.fdopen(
            os.dup(descriptor), "r", encoding="utf-8"
        ) as handle:
            return json.load(handle)
    finally:
        os.close(descriptor)


def validate_document(document):
    if (
        not isinstance(document, dict)
        or set(document) != expected_keys
        or document.get("schema")
            != "bridgesllm.uninstall-transaction.v1"
        or not isinstance(document.get("transactionId"), str)
        or not re.fullmatch(
            r"[a-f0-9]{32}", document["transactionId"])
        or document.get("mode") not in {"keep", "clean"}
        or document.get("phase") != "terminal"
        or document.get("residuePolicy") not in {"safe", "wipe"}
        or not isinstance(document.get("installerVersion"), str)
        or not document["installerVersion"]
        or not isinstance(document.get("startedAt"), str)
        or not document["startedAt"]
    ):
        raise SystemExit(
            "the terminal uninstall journal schema is invalid")
    transaction_id = document["transactionId"]
    transaction_root = os.path.join(
        os.path.dirname(journal_path), "transactions")
    expected_transaction_dir = os.path.join(
        transaction_root, transaction_id)
    if (
        transaction_dir != expected_transaction_dir
        or document.get("transactionDir") != expected_transaction_dir
        or os.path.normpath(transaction_dir) != transaction_dir
        or document.get("environmentSnapshot") not in {
            None, os.path.join(transaction_dir, "portal.env")
        }
    ):
        raise SystemExit(
            "the terminal uninstall journal path is invalid")
    expected_plan = os.path.join(
        transaction_dir, "residue-plan.json")
    if document["mode"] == "clean":
        if (
            document.get("residuePlan") != expected_plan
            or not re.fullmatch(
                r"[a-f0-9]{64}",
                str(document.get("residuePlanDigest", "")),
            )
        ):
            raise SystemExit(
                "the terminal uninstall journal plan is invalid")
    elif (
        document.get("residuePlan") is not None
        or document.get("residuePlanDigest") is not None
    ):
        raise SystemExit(
            "the terminal uninstall journal plan is invalid")
    expected_digest = (
        document["residuePlanDigest"]
        if document["mode"] == "clean"
        and document["residuePolicy"] == "wipe"
        else None
    )
    intent = document.get("terminalDirectoryDeletionIntent")
    if intent is not None and (
        not isinstance(intent, dict)
        or set(intent) != expected_intent_keys
        or intent.get("schema")
            != "bridgesllm.uninstall-terminal-directory-deletion-intent.v1"
        or intent.get("transactionId") != transaction_id
        or intent.get("path") != transaction_dir
        or not all(
            isinstance(intent.get(name), int)
            and not isinstance(intent.get(name), bool)
            for name in ("device", "inode", "mode", "uid", "gid")
        )
        or intent["device"] < 0
        or intent["inode"] <= 0
        or not stat.S_ISDIR(intent["mode"])
        or stat.S_IMODE(intent["mode"]) != 0o700
        or intent["uid"] != 0
        or intent["gid"] != 0
        or intent.get("residuePlanDigest") != expected_digest
    ):
        raise SystemExit(
            "the terminal uninstall deletion intent is invalid")
    return transaction_id, expected_digest, intent


if (
    not os.path.isabs(journal_path)
    or os.path.normpath(journal_path) != journal_path
):
    raise SystemExit("the terminal uninstall journal is unsafe")
document = read_pinned_journal(journal_path)
transaction_id, expected_digest, intent = validate_document(document)

parent = os.path.dirname(transaction_dir)
parent_info = os.lstat(parent)
if (
    not stat.S_ISDIR(parent_info.st_mode)
    or stat.S_ISLNK(parent_info.st_mode)
    or parent_info.st_uid != 0
    or parent_info.st_gid != 0
    or parent_info.st_mode & 0o022
    or os.path.realpath(parent) != parent
):
    raise SystemExit(
        "the terminal uninstall transaction parent is unsafe")
parent_flags = (
    os.O_RDONLY
    | getattr(os, "O_DIRECTORY", 0)
    | getattr(os, "O_NOFOLLOW", 0)
)
parent_fd = os.open(parent, parent_flags)
try:
    opened_parent = os.fstat(parent_fd)
    current_parent = os.lstat(parent)
    sealed_parent = (
        parent_info.st_dev,
        parent_info.st_ino,
        parent_info.st_mode,
        parent_info.st_uid,
        parent_info.st_gid,
    )
    if (
        (
            opened_parent.st_dev,
            opened_parent.st_ino,
            opened_parent.st_mode,
            opened_parent.st_uid,
            opened_parent.st_gid,
        ) != sealed_parent
        or (
            current_parent.st_dev,
            current_parent.st_ino,
            current_parent.st_mode,
            current_parent.st_uid,
            current_parent.st_gid,
        ) != sealed_parent
    ):
        raise SystemExit(
            "the terminal uninstall transaction parent raced sealing")
    name = os.path.basename(transaction_dir)
    try:
        before = os.stat(
            name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        if intent is None:
            raise SystemExit(
                "the uninstall transaction disappeared before deletion "
                "intent was sealed")
        raise SystemExit(0)
    if (
        not stat.S_ISDIR(before.st_mode)
        or stat.S_ISLNK(before.st_mode)
        or before.st_uid != 0
        or before.st_gid != 0
        or stat.S_IMODE(before.st_mode) != 0o700
        or before.st_dev != opened_parent.st_dev
    ):
        raise SystemExit(
            "the terminal uninstall transaction directory is unsafe")
    target_fd = os.open(name, parent_flags, dir_fd=parent_fd)
    try:
        opened = os.fstat(target_fd)
        current = os.stat(
            name, dir_fd=parent_fd, follow_symlinks=False)
        identity = (
            before.st_dev,
            before.st_ino,
            before.st_mode,
            before.st_uid,
            before.st_gid,
        )
        if (
            (
                opened.st_dev,
                opened.st_ino,
                opened.st_mode,
                opened.st_uid,
                opened.st_gid,
            ) != identity
            or (
                current.st_dev,
                current.st_ino,
                current.st_mode,
                current.st_uid,
                current.st_gid,
            ) != identity
        ):
            raise SystemExit(
                "the terminal uninstall transaction directory raced sealing")
        expected_intent = {
            "schema":
                "bridgesllm.uninstall-terminal-directory-deletion-intent.v1",
            "transactionId": transaction_id,
            "path": transaction_dir,
            "device": before.st_dev,
            "inode": before.st_ino,
            "mode": before.st_mode,
            "uid": before.st_uid,
            "gid": before.st_gid,
            "residuePlanDigest": expected_digest,
        }
        if intent is not None:
            if intent != expected_intent:
                raise SystemExit(
                    "the terminal uninstall transaction no longer matches "
                    "its deletion intent")
            raise SystemExit(0)
        rebound = os.stat(
            name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            rebound.st_dev,
            rebound.st_ino,
            rebound.st_mode,
            rebound.st_uid,
            rebound.st_gid,
        ) != identity:
            raise SystemExit(
                "the terminal uninstall transaction raced intent publication")
    finally:
        os.close(target_fd)
finally:
    os.close(parent_fd)

document["terminalDirectoryDeletionIntent"] = expected_intent
validate_document(document)
journal_parent = os.path.dirname(journal_path)
journal_parent_info = os.lstat(journal_parent)
if (
    not stat.S_ISDIR(journal_parent_info.st_mode)
    or stat.S_ISLNK(journal_parent_info.st_mode)
    or journal_parent_info.st_uid != 0
    or journal_parent_info.st_gid != 0
    or journal_parent_info.st_mode & 0o022
):
    raise SystemExit("the terminal uninstall journal parent is unsafe")
descriptor, temporary = tempfile.mkstemp(
    prefix=".active-uninstall-terminal-intent.",
    dir=journal_parent,
)
try:
    os.fchmod(descriptor, 0o600)
    with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        descriptor = -1
        json.dump(document, handle, indent=2, sort_keys=True)
        handle.write("\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, journal_path)
    temporary = ""
    directory_fd = os.open(
        journal_parent,
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)
finally:
    if descriptor >= 0:
        os.close(descriptor)
    if temporary:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass

sealed_document = read_pinned_journal(journal_path)
_transaction_id, _digest, sealed_intent = validate_document(
    sealed_document)
if sealed_intent != expected_intent:
    raise SystemExit(
        "the terminal uninstall deletion intent was not committed")
PY
}

durably_remove_uninstall_transaction_directory() {
  local transaction_dir="$1"
  local transactions_root="$2"
  local journal_path="$3"
  local self_mountinfo="${4:-/proc/self/mountinfo}"
  local pid1_mountinfo="${5:-/proc/1/mountinfo}"
  local fixture_crash_control="${6:-}"
  local fixture_trace="${7:-}"
  python3 - \
    "${transaction_dir}" "${transactions_root}" "${journal_path}" \
    "${self_mountinfo}" "${pid1_mountinfo}" \
    "${fixture_crash_control}" "${fixture_trace}" <<'PY'
import json
import os
import re
import stat
import sys

(
    target, expected_parent, journal_path, self_mountinfo, pid1_mountinfo,
    fixture_crash_control, fixture_trace,
) = sys.argv[1:]

if (
    not os.path.isabs(target)
    or os.path.normpath(target) != target
    or not os.path.isabs(expected_parent)
    or os.path.normpath(expected_parent) != expected_parent
    or os.path.dirname(target) != expected_parent
    or not re.fullmatch(r"[a-f0-9]{32}", os.path.basename(target))
):
    raise SystemExit("the uninstall transaction path is invalid")

expected_journal_keys = {
    "schema",
    "transactionId",
    "mode",
    "phase",
    "residuePolicy",
    "residuePlan",
    "residuePlanDigest",
    "transactionDir",
    "environmentSnapshot",
    "installerVersion",
    "startedAt",
    "terminalDirectoryDeletionIntent",
}
expected_intent_keys = {
    "schema",
    "transactionId",
    "path",
    "device",
    "inode",
    "mode",
    "uid",
    "gid",
    "residuePlanDigest",
}
if (
    not os.path.isabs(journal_path)
    or os.path.normpath(journal_path) != journal_path
    or expected_parent
        != os.path.join(os.path.dirname(journal_path), "transactions")
):
    raise SystemExit(
        "the terminal uninstall deletion-intent journal is unsafe")
journal_info = os.lstat(journal_path)
if (
    not stat.S_ISREG(journal_info.st_mode)
    or stat.S_ISLNK(journal_info.st_mode)
    or journal_info.st_uid != 0
    or journal_info.st_gid != 0
    or journal_info.st_nlink != 1
    or stat.S_IMODE(journal_info.st_mode) != 0o600
    or journal_info.st_size <= 0
    or journal_info.st_size > 65536
):
    raise SystemExit(
        "the terminal uninstall deletion-intent journal is unsafe")
journal_flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
if hasattr(os, "O_NOFOLLOW"):
    journal_flags |= os.O_NOFOLLOW
journal_fd = os.open(journal_path, journal_flags)
try:
    journal_opened = os.fstat(journal_fd)
    journal_current = os.lstat(journal_path)
    journal_identity = (
        journal_info.st_dev,
        journal_info.st_ino,
        journal_info.st_mode,
        journal_info.st_uid,
        journal_info.st_gid,
        journal_info.st_nlink,
    )
    if (
        (
            journal_opened.st_dev,
            journal_opened.st_ino,
            journal_opened.st_mode,
            journal_opened.st_uid,
            journal_opened.st_gid,
            journal_opened.st_nlink,
        ) != journal_identity
        or (
            journal_current.st_dev,
            journal_current.st_ino,
            journal_current.st_mode,
            journal_current.st_uid,
            journal_current.st_gid,
            journal_current.st_nlink,
        ) != journal_identity
    ):
        raise SystemExit(
            "the terminal uninstall deletion-intent journal raced")
    with os.fdopen(
        os.dup(journal_fd), "r", encoding="utf-8"
    ) as handle:
        journal = json.load(handle)
finally:
    os.close(journal_fd)
transaction_id = os.path.basename(target)
if (
    not isinstance(journal, dict)
    or set(journal) != expected_journal_keys
    or journal.get("schema") != "bridgesllm.uninstall-transaction.v1"
    or journal.get("transactionId") != transaction_id
    or journal.get("transactionDir") != target
    or journal.get("mode") not in {"keep", "clean"}
    or journal.get("phase") != "terminal"
    or journal.get("residuePolicy") not in {"safe", "wipe"}
    or not isinstance(journal.get("installerVersion"), str)
    or not journal["installerVersion"]
    or not isinstance(journal.get("startedAt"), str)
    or not journal["startedAt"]
    or journal.get("environmentSnapshot") not in {
        None, os.path.join(target, "portal.env")
    }
):
    raise SystemExit(
        "the terminal uninstall deletion-intent journal is invalid")
if journal["mode"] == "clean":
    if (
        journal.get("residuePlan")
            != os.path.join(target, "residue-plan.json")
        or not re.fullmatch(
            r"[a-f0-9]{64}",
            str(journal.get("residuePlanDigest", "")),
        )
    ):
        raise SystemExit(
            "the terminal uninstall deletion-intent plan is invalid")
elif (
    journal.get("residuePlan") is not None
    or journal.get("residuePlanDigest") is not None
):
    raise SystemExit(
        "the terminal uninstall deletion-intent plan is invalid")
expected_intent_digest = (
    journal["residuePlanDigest"]
    if journal["mode"] == "clean"
    and journal["residuePolicy"] == "wipe"
    else None
)
intent = journal.get("terminalDirectoryDeletionIntent")
if (
    not isinstance(intent, dict)
    or set(intent) != expected_intent_keys
    or intent.get("schema")
        != "bridgesllm.uninstall-terminal-directory-deletion-intent.v1"
    or intent.get("transactionId") != transaction_id
    or intent.get("path") != target
    or not all(
        isinstance(intent.get(name), int)
        and not isinstance(intent.get(name), bool)
        for name in ("device", "inode", "mode", "uid", "gid")
    )
    or intent["device"] < 0
    or intent["inode"] <= 0
    or not stat.S_ISDIR(intent["mode"])
    or stat.S_IMODE(intent["mode"]) != 0o700
    or intent["uid"] != 0
    or intent["gid"] != 0
    or intent.get("residuePlanDigest") != expected_intent_digest
):
    raise SystemExit(
        "the terminal uninstall directory deletion intent is invalid")
intent_identity = (
    intent["device"],
    intent["inode"],
    intent["mode"],
    intent["uid"],
    intent["gid"],
)

fixture_root = os.environ.get("BRIDGESLLM_RESIDUE_TEST_ROOT", "")
if fixture_crash_control or fixture_trace:
    if (
        not fixture_root
        or not re.fullmatch(
            r"/tmp/bridgesllm-residue-fixture-[A-Za-z0-9._-]+",
            fixture_root,
        )
        or os.path.realpath(fixture_root) != fixture_root
        or not target.startswith(fixture_root + os.sep)
        or fixture_crash_control
            != os.path.join(
                fixture_root, "state", "terminal-delete-crash-point")
        or fixture_trace
            != os.path.join(
                fixture_root, "state", "terminal-delete-fsync.log")
    ):
        raise SystemExit("the uninstall transaction fixture controls are unsafe")


def decode_mount_path(value):
    escapes = {
        "040": " ",
        "011": "\t",
        "012": "\n",
        "134": "\\",
    }
    return re.sub(
        r"\\(040|011|012|134)",
        lambda match: escapes[match.group(1)],
        value,
    )


def relevant_mounts(path):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            payload = handle.read(16 * 1024 * 1024 + 1)
    except OSError:
        raise SystemExit("uninstall transaction mount topology is unreadable")
    if len(payload.encode("utf-8", "replace")) > 16 * 1024 * 1024:
        raise SystemExit("uninstall transaction mount topology is oversized")
    result = set()
    for line in payload.splitlines():
        columns = line.split()
        if len(columns) < 10 or "-" not in columns[6:]:
            raise SystemExit("uninstall transaction mount topology is invalid")
        mountpoint = decode_mount_path(columns[4])
        if not os.path.isabs(mountpoint):
            raise SystemExit("uninstall transaction mount topology is invalid")
        if mountpoint == target or mountpoint.startswith(target + os.sep):
            result.add(mountpoint)
    return result


def assert_mount_boundary_empty():
    self_mounts = relevant_mounts(self_mountinfo)
    pid1_mounts = relevant_mounts(pid1_mountinfo)
    if self_mounts != pid1_mounts:
        raise SystemExit(
            "PID 1 and installer mount topology disagree below "
            "the uninstall transaction")
    if self_mounts:
        raise SystemExit(
            "the uninstall transaction contains a mount boundary")


def descriptor_mount_id(descriptor):
    try:
        with open(
            f"/proc/self/fdinfo/{descriptor}",
            "r",
            encoding="utf-8",
        ) as handle:
            matches = [
                line.split(":", 1)[1].strip()
                for line in handle
                if line.startswith("mnt_id:")
            ]
    except OSError:
        raise SystemExit(
            "the uninstall transaction descriptor mount identity "
            "could not be read")
    if (
        len(matches) != 1
        or not re.fullmatch(r"[0-9]+", matches[0])
        or int(matches[0]) <= 0
    ):
        raise SystemExit(
            "the uninstall transaction descriptor mount identity is invalid")
    return int(matches[0])


parent_before = os.lstat(expected_parent)
if (
    not stat.S_ISDIR(parent_before.st_mode)
    or stat.S_ISLNK(parent_before.st_mode)
    or parent_before.st_uid != 0
    or parent_before.st_gid != 0
    or parent_before.st_mode & 0o022
    or os.path.realpath(expected_parent) != expected_parent
):
    raise SystemExit("the uninstall transaction parent is unsafe")
parent_flags = (
    os.O_RDONLY
    | getattr(os, "O_DIRECTORY", 0)
    | getattr(os, "O_NOFOLLOW", 0)
)
parent_fd = os.open(expected_parent, parent_flags)
try:
    parent_opened = os.fstat(parent_fd)
    parent_current = os.lstat(expected_parent)
    sealed_parent = (
        parent_before.st_dev,
        parent_before.st_ino,
        parent_before.st_mode,
        parent_before.st_uid,
        parent_before.st_gid,
    )
    if (
        (
            parent_opened.st_dev,
            parent_opened.st_ino,
            parent_opened.st_mode,
            parent_opened.st_uid,
            parent_opened.st_gid,
        ) != sealed_parent
        or (
            parent_current.st_dev,
            parent_current.st_ino,
            parent_current.st_mode,
            parent_current.st_uid,
            parent_current.st_gid,
        ) != sealed_parent
    ):
        raise SystemExit(
            "the uninstall transaction parent raced its sealed identity")
    root_mount_id = descriptor_mount_id(parent_fd)

    assert_mount_boundary_empty()
    name = os.path.basename(target)
    try:
        before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        before = None

    if before is not None:
        if (
            not stat.S_ISDIR(before.st_mode)
            or stat.S_ISLNK(before.st_mode)
            or before.st_uid != 0
            or before.st_gid != 0
            or stat.S_IMODE(before.st_mode) != 0o700
            or before.st_dev != parent_opened.st_dev
            or (
                before.st_dev,
                before.st_ino,
                before.st_mode,
                before.st_uid,
                before.st_gid,
            ) != intent_identity
        ):
            raise SystemExit(
                "the uninstall transaction directory does not match "
                "its sealed deletion intent")
        target_fd = os.open(name, parent_flags, dir_fd=parent_fd)
        try:
            opened = os.fstat(target_fd)
            current = os.stat(
                name, dir_fd=parent_fd, follow_symlinks=False)
            sealed_target = (
                before.st_dev,
                before.st_ino,
                before.st_mode,
                before.st_uid,
                before.st_gid,
            )
            if (
                (
                    opened.st_dev,
                    opened.st_ino,
                    opened.st_mode,
                    opened.st_uid,
                    opened.st_gid,
                ) != sealed_target
                or (
                    current.st_dev,
                    current.st_ino,
                    current.st_mode,
                    current.st_uid,
                    current.st_gid,
                ) != sealed_target
                or descriptor_mount_id(target_fd) != root_mount_id
            ):
                raise SystemExit(
                    "the uninstall transaction directory raced its "
                    "sealed identity or crossed a mount")
            assert_mount_boundary_empty()

            def remove_contents(
                directory_fd,
                directory_path,
                root_device,
                root_mount_id,
            ):
                if descriptor_mount_id(directory_fd) != root_mount_id:
                    raise SystemExit(
                        "the uninstall transaction crossed a directory "
                        "mount identity")
                assert_mount_boundary_empty()
                for entry in list(os.scandir(directory_fd)):
                    child_path = os.path.join(directory_path, entry.name)
                    child = os.stat(
                        entry.name,
                        dir_fd=directory_fd,
                        follow_symlinks=False,
                    )
                    if stat.S_ISDIR(child.st_mode):
                        if (
                            child.st_dev != root_device
                            or child.st_uid != 0
                            or child.st_gid != 0
                            or child.st_mode & 0o022
                        ):
                            raise SystemExit(
                                "the uninstall transaction crossed an "
                                "unsafe directory boundary")
                        child_fd = os.open(
                            entry.name, parent_flags, dir_fd=directory_fd)
                        try:
                            child_opened = os.fstat(child_fd)
                            if (
                                child_opened.st_dev,
                                child_opened.st_ino,
                                child_opened.st_mode,
                                child_opened.st_uid,
                                child_opened.st_gid,
                            ) != (
                                child.st_dev,
                                child.st_ino,
                                child.st_mode,
                                child.st_uid,
                                child.st_gid,
                            ) or descriptor_mount_id(
                                child_fd
                            ) != root_mount_id:
                                raise SystemExit(
                                    "the uninstall transaction directory "
                                    "raced deletion or crossed a mount")
                            remove_contents(
                                child_fd,
                                child_path,
                                root_device,
                                root_mount_id,
                            )
                            os.fsync(child_fd)
                        finally:
                            os.close(child_fd)
                        rebound = os.stat(
                            entry.name,
                            dir_fd=directory_fd,
                            follow_symlinks=False,
                        )
                        if (
                            rebound.st_dev,
                            rebound.st_ino,
                            rebound.st_mode,
                        ) != (
                            child.st_dev,
                            child.st_ino,
                            child.st_mode,
                        ):
                            raise SystemExit(
                                "the uninstall transaction directory "
                                "raced deletion")
                        assert_mount_boundary_empty()
                        if descriptor_mount_id(
                            directory_fd
                        ) != root_mount_id:
                            raise SystemExit(
                                "the uninstall transaction parent crossed "
                                "a mount before directory removal")
                        os.rmdir(entry.name, dir_fd=directory_fd)
                        continue
                    if (
                        not stat.S_ISREG(child.st_mode)
                        or child.st_dev != root_device
                        or child.st_uid != 0
                        or child.st_gid != 0
                        or child.st_nlink != 1
                        or child.st_mode & 0o022
                    ):
                        raise SystemExit(
                            "the uninstall transaction contains an "
                            "unsafe non-directory entry")
                    rebound = os.stat(
                        entry.name,
                        dir_fd=directory_fd,
                        follow_symlinks=False,
                    )
                    if (
                        rebound.st_dev,
                        rebound.st_ino,
                        rebound.st_mode,
                        rebound.st_nlink,
                    ) != (
                        child.st_dev,
                        child.st_ino,
                        child.st_mode,
                        child.st_nlink,
                    ):
                        raise SystemExit(
                            "the uninstall transaction file raced deletion")
                    assert_mount_boundary_empty()
                    if descriptor_mount_id(
                        directory_fd
                    ) != root_mount_id:
                        raise SystemExit(
                            "the uninstall transaction parent crossed "
                            "a mount before file removal")
                    os.unlink(entry.name, dir_fd=directory_fd)

            remove_contents(
                target_fd,
                target,
                opened.st_dev,
                root_mount_id,
            )
            os.fsync(target_fd)
            rebound = os.stat(
                name, dir_fd=parent_fd, follow_symlinks=False)
            if (
                rebound.st_dev,
                rebound.st_ino,
                rebound.st_mode,
            ) != (
                before.st_dev,
                before.st_ino,
                before.st_mode,
            ):
                raise SystemExit(
                    "the uninstall transaction root raced deletion")
            os.rmdir(name, dir_fd=parent_fd)
        finally:
            os.close(target_fd)

        if fixture_crash_control:
            try:
                with open(
                    fixture_crash_control, "r", encoding="utf-8"
                ) as handle:
                    crash_point = handle.read(128).strip()
            except FileNotFoundError:
                crash_point = ""
            if crash_point == "after-rmdir-before-parent-fsync":
                os.unlink(fixture_crash_control)
                raise SystemExit(
                    "fixture crash after transaction rmdir")

    # This fsync is intentionally unconditional.  A resumed invocation that
    # observes the target already absent may be closing the kill window after
    # a prior rmdir but before that prior invocation's parent fsync.
    os.fsync(parent_fd)
    try:
        os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        pass
    else:
        raise SystemExit(
            "the uninstall transaction directory survived durable removal")
    if fixture_trace:
        with open(fixture_trace, "a", encoding="utf-8") as handle:
            handle.write("parent-fsync-after-absence\n")
finally:
    os.close(parent_fd)
PY
}

durably_unlink_uninstall_file() {
  local path="$1"
  local expected_parent="$2"
  python3 - "${path}" "${expected_parent}" <<'PY'
import os
import stat
import sys

path, expected_parent = sys.argv[1:]
if (
    not os.path.isabs(path)
    or os.path.normpath(path) != path
    or os.path.dirname(path) != expected_parent
):
    raise SystemExit(1)
parent = os.lstat(expected_parent)
if (
    not stat.S_ISDIR(parent.st_mode)
    or stat.S_ISLNK(parent.st_mode)
    or parent.st_uid != 0
    or parent.st_gid != 0
    or parent.st_mode & 0o022
):
    raise SystemExit(1)
try:
    info = os.lstat(path)
except FileNotFoundError:
    info = None
if info is not None:
    if (
        not stat.S_ISREG(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or info.st_uid != 0
        or info.st_gid != 0
        or info.st_nlink != 1
        or info.st_mode & 0o022
    ):
        raise SystemExit(1)
    os.unlink(path)
descriptor = os.open(expected_parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
try:
    os.fsync(descriptor)
finally:
    os.close(descriptor)
PY
}

# Terminal cleanup must stay re-runnable: a crash between the terminal phase
# advance and these removals leaves the journal on disk, and a surviving
# journal keeps the boot fence blocking every future Portal start and refuses
# any new uninstall transaction. The transaction directory (which holds the
# environment snapshot) may already be gone on a re-run only when the journal
# first sealed its exact deletion intent; the journal is removed last as the
# commit point so recovery can always finish the rest.
cleanup_terminal_uninstall_transaction() {
  local transaction_dir transaction_id mode residue_policy residue_plan
  transaction_dir="$(read_uninstall_transaction_field transactionDir)" || return 1
  transaction_id="$(read_uninstall_transaction_field transactionId)" || return 1
  mode="$(read_uninstall_transaction_field mode)" || return 1
  residue_policy="$(read_uninstall_transaction_field residuePolicy)" || return 1
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ \
    && "${transaction_dir}" == "${UNINSTALL_TRANSACTIONS_ROOT}/${transaction_id}" ]] \
    || return 1
  if [[ "${mode}" == "clean" && "${residue_policy}" == "wipe" ]]; then
    # This is the final commit guard, after every phase reports success and
    # before the consent plan or journal can disappear. While the transaction
    # directory exists, prove every sealed full Docker identity absent too;
    # after that directory is durably removed, container/network identities
    # cannot be recreated and exact volume names remain covered by the global
    # name proof. Any resurrected filesystem path or Portal firewall rule also
    # keeps recovery active.
    if [[ -e "${transaction_dir}" || -L "${transaction_dir}" ]]; then
      residue_plan="$(read_uninstall_transaction_field residuePlan)" || return 1
      [[ "${residue_plan}" == "${transaction_dir}/residue-plan.json" ]] \
        || return 1
      managed_runtime_residue_tool \
        prove-absent all "" "${residue_plan}" >/dev/null \
        || return 1
    fi
    assert_no_managed_project_runtime_residuals || return 1
    assert_no_managed_agent_zero_runtime_residuals || return 1
  fi
  if [[ "${mode}" == "clean" ]]; then
    # Clean slate has already retired the Portal runtime, authorization
    # database, and managed provider resources. Remove only the exact
    # installer/backend-owned OpenClaw fence pair. Keep Data deliberately
    # preserves both so an unresolved transition cannot be reopened by
    # uninstalling the Portal runtime around it.
    remove_openclaw_gateway_authorization_fence_for_clean_uninstall \
      || return 1
  fi
  # Claim the exact root-owned transaction inode in the active journal only
  # after every applicable sealed/global absence proof succeeds.  A resumed
  # cleanup may accept lexical directory absence only when this durable intent
  # already exists; otherwise an out-of-band pre-cleanup rename would erase
  # the full-identity consent plan and bypass prove-absent.
  seal_terminal_uninstall_directory_deletion_intent \
    "${UNINSTALL_ACTIVE_JOURNAL}" "${transaction_dir}" \
    || return 1
  durably_remove_uninstall_transaction_directory \
    "${transaction_dir}" "${UNINSTALL_TRANSACTIONS_ROOT}" \
    "${UNINSTALL_ACTIVE_JOURNAL}" \
    || return 1
  durably_unlink_uninstall_file \
    "${UNINSTALL_BOOT_FENCE_DROPIN}" "${UPDATE_BOOT_FENCE_DROPIN_DIR}" \
    || return 1
  systemctl daemon-reload >/dev/null 2>&1 || return 1
  # The journal is the final commit point. If any earlier cleanup or
  # daemon-reload fails, it remains and the next installer run resumes the
  # exact terminal phase instead of marooning a loaded boot fence.
  durably_unlink_uninstall_file \
    "${UNINSTALL_ACTIVE_JOURNAL}" "${UNINSTALL_STATE_ROOT}" \
    || return 1
  [[ ! -e "${UNINSTALL_ACTIVE_JOURNAL}" && ! -L "${UNINSTALL_ACTIVE_JOURNAL}" ]]
}

complete_uninstall_transaction() {
  advance_uninstall_transaction_phase terminal_pending terminal || return 1
  cleanup_terminal_uninstall_transaction
}

resume_active_uninstall_transaction() {
  [[ -f "${UNINSTALL_ACTIVE_JOURNAL}" && ! -L "${UNINSTALL_ACTIVE_JOURNAL}" ]] \
    || return 1
  local mode phase env_snapshot transaction_id
  mode="$(read_uninstall_transaction_field mode)" || return 1
  env_snapshot="$(read_uninstall_transaction_field environmentSnapshot)" || return 1
  transaction_id="$(read_uninstall_transaction_field transactionId)" || return 1
  [[ "${mode}" == "keep" || "${mode}" == "clean" ]] || return 1
  [[ "${transaction_id}" =~ ^[a-f0-9]{32}$ ]] || return 1
  phase="$(read_uninstall_transaction_field phase)" || return 1
  if [[ "${phase}" == "terminal" ]]; then
    # The prior run crashed after its terminal advance; the transaction
    # directory and its environment snapshot may already be gone, so finish
    # the terminal cleanup without revalidating them.
    cleanup_terminal_uninstall_transaction
    return
  fi
  if [[ -n "${env_snapshot}" ]]; then
    [[ "${env_snapshot}" == "${UNINSTALL_TRANSACTIONS_ROOT}/${transaction_id}/portal.env" \
      && -f "${env_snapshot}" && ! -L "${env_snapshot}" \
      && "$(stat -c '%u:%g:%a' "${env_snapshot}")" == '0:0:600' ]] || return 1
    assert_env_file_no_duplicate_keys "${env_snapshot}" || return 1
  fi

  while :; do
    phase="$(read_uninstall_transaction_field phase)" || return 1
    case "${phase}" in
      prepared)
        install_portal_uninstall_boot_fence || return 1
        advance_uninstall_transaction_phase prepared boot_fenced || return 1
        ;;
      boot_fenced)
        stop_portal_service_for_uninstall
        advance_uninstall_transaction_phase boot_fenced portal_quiesced || return 1
        ;;
      portal_quiesced)
        remove_portal_remote_desktop_runtime "$([[ "${mode}" == "clean" ]] && printf 2 || printf 1)"
        advance_uninstall_transaction_phase portal_quiesced remote_desktop_removed || return 1
        ;;
      remote_desktop_removed)
        remove_portal_backup_automation
        advance_uninstall_transaction_phase remote_desktop_removed backup_automation_removed || return 1
        ;;
      backup_automation_removed)
        if [[ "${mode}" == "clean" ]]; then
          run_project_runtime_clean_slate_preflight
        else
          record_retained_runtime_intent
          quiesce_project_runtimes_preserving_data
        fi
        advance_uninstall_transaction_phase backup_automation_removed project_runtimes_removed || return 1
        ;;
      project_runtimes_removed)
        local bridge_helper="${PORTAL_DIR}/installer/agent-zero-project-model-bridge.sh"
        if [[ -f "${bridge_helper}" && ! -L "${bridge_helper}" ]]; then
          local bridge_command='uninstall'
          [[ "${mode}" == "clean" ]] && bridge_command='uninstall-clean-slate'
          bash "${bridge_helper}" "${bridge_command}" \
            || fail "Agent Zero Project model bridge could not revoke its upstream token safely."
        elif [[ -e "${bridge_helper}" || -L "${bridge_helper}" ]]; then
          fail "Agent Zero Project model bridge lifecycle helper is linked or non-regular; uninstall was aborted."
        else
          assert_no_agent_zero_project_bridge_residuals
        fi
        advance_uninstall_transaction_phase project_runtimes_removed agent_zero_bridge_removed || return 1
        ;;
      agent_zero_bridge_removed)
        remove_exact_portal_tailnet_serve_mapping "${env_snapshot}" \
          || fail "The Portal's exact Tailscale Serve mapping could not be removed without changing unrelated tailnet routes."
        advance_uninstall_transaction_phase agent_zero_bridge_removed tailnet_mapping_removed || return 1
        ;;
      tailnet_mapping_removed)
        remove_portal_service_unit_for_uninstall \
          || fail "The Portal service unit could not be removed and re-inspected safely."
        advance_uninstall_transaction_phase tailnet_mapping_removed portal_service_removed || return 1
        ;;
      portal_service_removed)
        if [[ "${mode}" == "clean" ]]; then
          remove_managed_agent_zero_for_clean_uninstall
          advance_uninstall_transaction_phase portal_service_removed agent_zero_removed || return 1
        else
          remove_portal_runtime_preserving_data "${PORTAL_DIR}" \
            || fail "Could not remove the Portal runtime without risking retained data."
          advance_uninstall_transaction_phase portal_service_removed runtime_removed || return 1
        fi
        ;;
      runtime_removed)
        [[ "${mode}" == "keep" ]] || return 1
        write_retained_install_receipt \
          || fail "The retained Portal tree could not be sealed with an exact root-only reconnect receipt."
        advance_uninstall_transaction_phase runtime_removed retained_receipt_written || return 1
        ;;
      retained_receipt_written)
        [[ "${mode}" == "keep" ]] || return 1
        advance_uninstall_transaction_phase retained_receipt_written terminal_pending || return 1
        ;;
      agent_zero_removed)
        [[ "${mode}" == "clean" ]] || return 1
        stop_managed_stalwart_for_clean_uninstall "${INSTALL_ROOT}/stalwart"
        advance_uninstall_transaction_phase agent_zero_removed stalwart_removed || return 1
        ;;
      stalwart_removed)
        [[ "${mode}" == "clean" ]] || return 1
        local configured_url=""
        if [[ -n "${env_snapshot}" ]]; then
          configured_url="$(read_env_value "${env_snapshot}" DATABASE_URL 2>/dev/null || true)"
        fi
        remove_configured_default_database_for_clean_uninstall "${configured_url}"
        advance_uninstall_transaction_phase stalwart_removed database_removed || return 1
        ;;
      database_removed)
        [[ "${mode}" == "clean" ]] || return 1
        remove_legacy_portal_data_for_clean_uninstall
        advance_uninstall_transaction_phase database_removed legacy_data_removed || return 1
        ;;
      legacy_data_removed)
        [[ "${mode}" == "clean" ]] || return 1
        remove_install_root_for_clean_uninstall
        advance_uninstall_transaction_phase legacy_data_removed install_root_removed || return 1
        ;;
      install_root_removed)
        [[ "${mode}" == "clean" ]] || return 1
        advance_uninstall_transaction_phase install_root_removed terminal_pending || return 1
        ;;
      terminal_pending)
        complete_uninstall_transaction || return 1
        return 0
        ;;
      terminal)
        cleanup_terminal_uninstall_transaction || return 1
        return 0
        ;;
      *)
        return 1
        ;;
    esac
  done
}

recover_pending_uninstall_transaction() {
  [[ -e "${UNINSTALL_ACTIVE_JOURNAL}" || -L "${UNINSTALL_ACTIVE_JOURNAL}" ]] \
    || return 0
  [[ -f "${UNINSTALL_ACTIVE_JOURNAL}" && ! -L "${UNINSTALL_ACTIVE_JOURNAL}" ]] \
    || return 1
  warn "An interrupted Portal uninstall exists; resuming its exact previously confirmed data policy."
  resume_active_uninstall_transaction || return 1
  UNINSTALL_RECOVERED_THIS_RUN=true
  ok "Interrupted Portal uninstall converged"
}

stop_portal_service_for_uninstall() {
  # Stop errors are not authoritative: a service that was already stopped can
  # legitimately make the stop command fail. The readback is authoritative,
  # and any query failure is unsafe because the API could still recreate
  # Remote Desktop or backup state while uninstall removes it.
  systemctl stop bridgesllm-product >/dev/null 2>&1 || true
  local load_state active_state
  load_state="$(systemctl show --property=LoadState --value bridgesllm-product 2>/dev/null)" \
    || fail "Portal service load state could not be verified; uninstall was aborted before data removal."
  active_state="$(systemctl show --property=ActiveState --value bridgesllm-product 2>/dev/null)" \
    || fail "Portal service active state could not be verified; uninstall was aborted before data removal."
  [[ -n "${load_state}" && -n "${active_state}" ]] \
    || fail "Portal service returned an incomplete state; uninstall was aborted before data removal."
  case "${active_state}" in
    inactive|failed) ;;
    *) fail "Portal service is still ${active_state}; uninstall was aborted before data removal." ;;
  esac
}

do_uninstall() {
  banner
  echo ""
  echo -e "  ${BOLD}${RED}Uninstalling BridgesLLM Portal${NC}"
  echo ""

  warn "This will remove:"
  echo "    ${BULLET} Portal at ${PORTAL_DIR}"
  echo "    ${BULLET} Portal and Remote Desktop services and launchers"
  echo "    ${BULLET} Local Portal data only if you explicitly choose Clean slate"
  echo ""

  # The database may be remote/custom and therefore absent from the local
  # PostgreSQL catalog. Always offer preservation; do not infer that no data
  # exists merely because the default local database is not present.
  local configured_database_url=""
  configured_database_url="$(read_env_value "${PORTAL_DIR}/backend/.env.production" DATABASE_URL 2>/dev/null || true)"

  echo -e "  ${CYAN}Choose whether Portal-owned data should remain on this server.${NC}"
  echo ""
  echo -e "    1) ${BOLD}Keep my data${NC} — Preserve the configured database, projects, apps,"
  echo -e "       uploads, mail, Portal state, backups, OpenClaw state, and Remote Desktop profile"
  echo -e "       ${DIM}(Reinstall later using the same owner credentials.)${NC}"
  echo -e ""
  echo -e "    2) ${BOLD}Clean slate${NC} — Remove the local Portal installation, default database,"
  echo -e "       and Portal-owned Remote Desktop account/profile"
  echo -e "       ${DIM}(Backup archives inside ${INSTALL_ROOT} and managed Agent Zero recovery snapshots${NC}"
  echo -e "       ${DIM} under /var/backups/bridgesllm/agent-zero are removed. Other external archives remain and may${NC}"
  echo -e "       ${DIM} contain Portal, OpenClaw, mail, project, credential, and uploaded-file data.)${NC}"
  echo -e "       ${DIM}(Irreversible. A separately hosted/custom database is not dropped.)${NC}"
  echo ""
  read -rp "  Choose [1/2] (default: 1): " data_choice
  data_choice="${data_choice:-1}"
  [[ "${data_choice}" == "1" || "${data_choice}" == "2" ]] \
    || fail "Invalid uninstall data choice; expected 1 or 2."

  # Leftover residue from an earlier partial cleanup is only decidable by the
  # user: the signed helper is gone, so either the leftovers stay (safe) or
  # the installer edits the host firewall (wipe). Ask with the findings and an
  # honest size estimate in front of them, before the final confirmation.
  local residue_policy="safe"
  if [[ "${data_choice}" == "2" ]]; then
    local residue_helper="${PORTAL_DIR}/backend/dist/cli/projectRuntimeUninstallPreflight.js"
    local residue_report="" residue_first=""
    residue_report="$(managed_runtime_residue_tool report all)" \
      || fail "Managed runtime residue could not be authoritatively inventoried before confirmation."
    residue_first="$(head -n 1 <<<"${residue_report}")"
    [[ "${residue_first}" =~ planDigest=([a-f0-9]{64}) ]] \
      || fail "Managed runtime residue inventory did not include a valid consent digest."
    UNINSTALL_RESIDUE_PLAN_DIGEST="${BASH_REMATCH[1]}"
    if [[ ( ! -f "${residue_helper}" || -L "${residue_helper}" ) \
      && "${residue_first}" == present=true* ]]; then
      local residue_bytes residue_mb
      residue_bytes="${residue_first##*bytes=}"
      [[ "${residue_bytes}" =~ ^[0-9]+$ ]] || residue_bytes=0
      residue_mb=$(( (residue_bytes + 1048575) / 1048576 ))
      echo ""
      warn "Leftovers from an earlier partial cleanup were found (their cleanup helper is gone):"
      tail -n +2 <<<"${residue_report}" | sed 's/^/      /'
      echo ""
      echo -e "  ${CYAN}Choose how to handle these leftovers.${NC}"
      echo ""
      echo "    1) ${BOLD}Safe cleanup${NC} — Stop leftover managed containers, then finish"
      echo "       uninstalling while leaving their Docker objects and firewall entries in place"
      echo "       ${DIM}(~${residue_mb} MB stays on disk. The firewall entries use no disk space —${NC}"
      echo "       ${DIM} they may still affect matching traffic. The host firewall is never edited.)${NC}"
      echo ""
      echo "    2) ${BOLD}Complete wipe${NC} — Also delete the leftover Docker resources and the"
      echo "       Portal-created firewall entries"
      echo "       ${DIM}(A full firewall backup is saved first, but editing the host firewall${NC}"
      echo "       ${DIM} carries a small risk of breaking this server's networking.)${NC}"
      echo "       ${DIM}(Removal is confirmed at each recorded location. Anything copied or${NC}"
      echo "       ${DIM} moved elsewhere beforehand is not tracked and will remain.)${NC}"
      echo ""
      if [[ -n "${RESIDUE_POLICY}" ]]; then
        residue_policy="${RESIDUE_POLICY}"
        info "Using --residue-policy ${residue_policy} for these leftovers."
      else
        local residue_choice
        read -rp "  Choose [1/2] (default: 1): " residue_choice
        residue_choice="${residue_choice:-1}"
        [[ "${residue_choice}" == "1" || "${residue_choice}" == "2" ]] \
          || fail "Invalid leftover-cleanup choice; expected 1 or 2."
        [[ "${residue_choice}" == "2" ]] && residue_policy="wipe"
      fi
    elif [[ -n "${RESIDUE_POLICY}" ]]; then
      residue_policy="${RESIDUE_POLICY}"
    fi
  fi

  echo ""
  read -rp "  Type 'yes' to confirm uninstall: " yn
  [[ "$yn" == "yes" ]] || { echo "  Cancelled."; exit 0; }

  local uninstall_mode="keep"
  [[ "${data_choice}" == "2" ]] && uninstall_mode="clean"

  # Clean slate destroys the database and runtimes before it reaches legacy
  # attribution. Prove attribution first, while the system is still intact.
  if [[ "${uninstall_mode}" == "clean" ]]; then
    assert_clean_slate_legacy_attribution
  fi

  prepare_uninstall_transaction \
    "${uninstall_mode}" "${PORTAL_DIR}/backend/.env.production" "${residue_policy}" \
    || fail "The durable uninstall transaction could not be created before teardown."
  resume_active_uninstall_transaction \
    || fail "The uninstall transaction did not converge. Its root-only journal and boot fence were preserved for the next installer run."

  if [[ "${data_choice}" == "2" ]]; then
    ok "BridgesLLM Portal and local Portal data removed"
  else
    ok "BridgesLLM Portal runtime removed; retained data was left in place"
  fi

  echo ""
  if [[ "${data_choice:-1}" == "1" ]]; then
    echo -e "  ${GREEN}Your data has been preserved.${NC}"
    echo -e "  ${DIM}Reinstall to reconnect the retained database and files.${NC}"
    echo -e "  ${DIM}Your existing owner password remains unchanged.${NC}"
    echo -e "  ${DIM}Stalwart mail and OpenClaw were not stopped or modified.${NC}"
    [[ -n "${configured_database_url}" ]] \
      && echo -e "  ${DIM}The retained DATABASE_URL will be reused exactly.${NC}"
  else
    echo -e "  ${DIM}Not removed (clean up manually if needed):${NC}"
    echo "    ${BULLET} Caddy (/etc/caddy/Caddyfile)"
    echo "    ${BULLET} Node.js, Docker, ClamAV, Ollama, OpenClaw"
    echo "    ${BULLET} Backup archives stored outside ${INSTALL_ROOT}"
    echo "    ${BULLET} Tailscale, including this machine's tailnet membership"
    echo ""
    # Tailscale surviving while the Portal's record of the pairing does not is
    # the confusing part: the tailnet still looks healthy, so a working Remote
    # GPU appears to have broken for no reason. Say it plainly.
    echo -e "  ${DIM}Removed with the database (re-add after reinstalling):${NC}"
    echo "    ${BULLET} Remote GPU / tailnet peer configuration held by Portal"
    echo "    ${BULLET} Connected provider accounts and per-project settings"
    echo -e "  ${DIM}Tailscale itself stays installed and joined, so the peer remains${NC}"
    echo -e "  ${DIM}reachable — only Portal's side of the pairing is gone.${NC}"
    if [[ -n "${UNINSTALL_RESIDUE_WIPE_BACKUP_DIR}" ]]; then
      echo ""
      echo -e "  ${DIM}A firewall backup from the Complete wipe was kept at:${NC}"
      echo "    ${BULLET} ${UNINSTALL_RESIDUE_WIPE_BACKUP_DIR}"
      echo -e "  ${DIM}(Restore with iptables-restore / ip6tables-restore if networking misbehaves.)${NC}"
    fi
  fi
  echo ""
}

# ═══════════════════════════════════════════════════════════════
# Main
# ═══════════════════════════════════════════════════════════════

print_dry_run_plan() {
  local existing_install=false action="install"
  if [[ -f "${PORTAL_DIR}/backend/package.json" \
    && -f "${PORTAL_DIR}/backend/.env.production" ]]; then
    existing_install=true
  fi

  if $UNINSTALL_MODE; then
    action="uninstall"
  elif $UPDATE_MODE; then
    action="update"
  elif $FORCE_FRESH && $existing_install; then
    action="reinstall"
  elif $existing_install; then
    action="update"
  fi

  banner
  echo ""
  echo -e "  ${BOLD}${WHITE}Dry-run plan${NC}"
  echo -e "  ${GREEN}No changes will be made.${NC}"
  echo -e "  ${DIM}This command performs no filesystem writes, lock creation, downloads,${NC}"
  echo -e "  ${DIM}telemetry, package work, service changes, firewall changes, Tailscale${NC}"
  echo -e "  ${DIM}changes, database work, or interactive confirmation prompts.${NC}"
  echo ""
  print_kv "Action" "${action}"
  print_kv "Portal path" "${PORTAL_DIR}"
  print_kv "Existing install" "${existing_install}"
  if use_tailnet_profile; then
    print_kv "Origin" "experimental private Tailscale (${TS_HOSTNAME})"
  elif use_local_profile; then
    print_kv "Origin" "experimental local/loopback"
  elif [[ -n "${DOMAIN}" ]]; then
    print_kv "Origin" "public HTTPS (${DOMAIN})"
  else
    print_kv "Origin" "loopback until browser setup"
  fi
  echo ""

  case "${action}" in
    uninstall)
      echo "  A real run would:"
      echo "    ${BULLET} Ask whether to keep Portal data or remove the local clean slate"
      echo "    ${BULLET} On a clean slate with helperless leftovers, ask for Safe cleanup or Complete wipe"
      echo "    ${BULLET} Require an exact uninstall confirmation"
      echo "    ${BULLET} Stop Portal, then remove its service, Remote Desktop, and backup automation"
      echo "    ${BULLET} Preserve or remove only the data selected at confirmation time"
      ;;
    update)
      echo "  A real run would:"
      echo "    ${BULLET} Stage and cryptographically verify the signed ${VERSION} release"
      echo "    ${BULLET} Stop Portal and capture runtime, database, dependency, config, and provenance recovery state"
      echo "    ${BULLET} Replace the runtime, migrate the database, and converge managed services"
      echo "    ${BULLET} Verify readiness before committing release provenance; recover on failure"
      if $MAINTAIN_TOOLS; then
        echo "    ${BULLET} Explicitly maintain optional AI tools"
      fi
      ;;
    reinstall)
      echo "  A real run would repair the existing Portal through the protected update transaction:"
      echo "    ${BULLET} Preserve its database, secrets, origin identities, projects, apps, uploads, and runtime data"
      echo "    ${BULLET} Quiesce Portal, snapshot every rollback layer, then reinstall the signed runtime"
      echo "    ${BULLET} Run migrations and converge managed services with durable interruption recovery"
      echo "    ${BULLET} Verify the new process and exact version before committing"
      ;;
    install)
      echo "  A real run would:"
      echo "    ${BULLET} Validate host resources, OS support, and required port boundaries"
      if use_tailnet_profile; then
        echo "    ${BULLET} Install/connect Tailscale and configure private HTTPS Serve"
      fi
      echo "    ${BULLET} Install pinned host tools and provision the Portal database"
      echo "    ${BULLET} Verify and install the signed Portal release"
      echo "    ${BULLET} Configure managed services, backups, and Remote Desktop"
      echo "    ${BULLET} Start Portal and verify readiness before reporting completion"
      ;;
  esac
  echo ""
  echo -e "  ${DIM}Dry-run is intentionally read-only; it does not prove network or dependency readiness.${NC}"
  echo ""
}

main() {
  parse_args "$@"
  if ${REPAIR_PROJECT_RUNTIME_IMAGE}; then
    [[ "${EUID:-$(id -u)}" -eq 0 ]] \
      || fail "Must run Project runtime image repair as root."
    acquire_project_runtime_image_repair_lock
    repair_project_runtime_image
    exit 0
  fi
  detect_runtime_profile
  detect_retained_install_reconnect
  load_existing_origin_for_forced_reinstall
  validate_selected_origin

  # A dry-run is a zero-side-effect planning command. Keep it above the root
  # check and operation lock: even creating the lock inode would violate the
  # advertised contract, and routing into update/uninstall would be dangerous.
  if $DRY_RUN; then
    print_dry_run_plan
    exit 0
  fi

  [[ "${EUID:-$(id -u)}" -eq 0 ]] || fail "Must run as root. Use: sudo bash ${SCRIPT_NAME}"
  acquire_portal_operation_lock
  if ${UNINSTALL_RECOVERED_THIS_RUN}; then
    info "The interrupted uninstall is complete. Run the installer again only if you now want to install Portal."
    exit 0
  fi

  # Uninstall mode
  if $UNINSTALL_MODE; then
    do_uninstall
    exit 0
  fi

  # Update mode
  if $UPDATE_MODE; then
    mkdir -p "$LOG_DIR"
    touch "$LOG_FILE"
    chmod 600 "$LOG_FILE"
    do_update
    exit 0
  fi

  # A forced reinstall over an attested installation is a repair operation,
  # not a fresh install. It must use the same quiesce/snapshot/rollback path as
  # an update so a live old process can never race file or schema replacement.
  if $FORCE_FRESH \
     && [[ -f "${PORTAL_DIR}/backend/package.json" ]] \
     && [[ -f "${PORTAL_DIR}/backend/.env.production" ]]; then
    mkdir -p "$LOG_DIR"
    touch "$LOG_FILE"
    chmod 600 "$LOG_FILE"
    REPAIR_REINSTALL=true
    UPDATE_MODE=true
    do_update
    exit 0
  fi

  # Auto-detect an existing installation and update it instead of reinstalling.
  # The advertised one-liner (curl ... | sudo bash) carries no --update flag, so
  # a re-run on an existing box would otherwise take the fresh-install path —
  # which rsyncs the live dir onto itself (RELEASE_FALLBACK_DIR == PORTAL_DIR),
  # silently no-ops the deploy, and still reports "Installation complete!". It
  # would also rewrite a working HTTPS Caddyfile to HTTP-only when DOMAIN is
  # blank in .env.production. Routing to do_update fixes both. --reinstall uses
  # that same protected transaction with repair semantics.
  if ! $FORCE_FRESH \
     && [[ -f "${PORTAL_DIR}/backend/package.json" ]] \
     && [[ -f "${PORTAL_DIR}/backend/.env.production" ]]; then
    mkdir -p "$LOG_DIR"
    touch "$LOG_FILE"
    chmod 600 "$LOG_FILE"
    info "Existing installation detected at ${PORTAL_DIR} — updating instead of reinstalling."
    info "(Use --reinstall to force a fresh install.)"
    UPDATE_MODE=true
    do_update
    exit 0
  fi

  assert_fresh_install_target_available

  # Fresh install
  mkdir -p "$LOG_DIR"
  touch "$LOG_FILE"
  chmod 600 "$LOG_FILE"

  INSTALL_START_TIME=$(date +%s)

  banner

  preflight
  converge_unsafe_docker_prune_automation \
    || fail "Unsafe scheduled Docker cleanup remains active. Review the guard details above, disable the unknown job or repair the legacy-file drift, and retry."
  ensure_telemetry_install_id
  telemetry_event "install_start"
  if use_tailnet_profile; then
    setup_tailnet_origin
  fi
  install_system_packages
  install_ai_tools
  setup_database
  build_portal
  install_native_provider_tools
  configure_services
  configure_backup_timers
  setup_remote_desktop
  start_portal
  print_success
}

if [[ "${BRIDGESLLM_INSTALLER_SOURCE_ONLY:-0}" != "1" ]]; then
  main "$@"
fi
